/// Synthetic trust_ir variable namespace emitted by trust-cg-lower for fixed scalar
/// alloca debug locals. The low bits are the LIR/MachIR stack slot index.
const ALLOCA_DEBUG_PROVENANCE_VAR_TAG: u32 = 0x8000_0000;
/// Synthetic trust_ir variable namespace emitted by trust-cg-lower for source-spanned
/// scalar constant values. The low bits are the stable trust_ir instruction ordinal.
const CONST_VALUE_DEBUG_PROVENANCE_VAR_TAG: u32 = 0x4000_0000;
/// Synthetic trust_ir variable namespace emitted by trust-cg-lower for source-spanned
/// scalar value results. The low bits are the stable trust_ir instruction ordinal.
const VALUE_DEBUG_PROVENANCE_VAR_TAG: u32 = 0x2000_0000;
const DEBUG_PROVENANCE_VAR_INDEX_MASK: u32 = 0x1fff_ffff;

// ---------------------------------------------------------------------------
// Pipeline errors
