/// Errors during compilation.
#[derive(Debug, Error)]
pub enum PipelineError {
    #[error("instruction selection failed: {0}")]
    ISel(String),
    #[error("register allocation failed: {0}")]
    RegAlloc(String),
    #[error("optimization invariant violation in `{function}`: {detail}")]
    OptimizationInvariantViolation { function: String, detail: String },
    #[error("encoding failed: {0}")]
    Encoding(String),
    #[error("unsupported opcode during encoding: {0:?}")]
    UnsupportedOpcode(IrOpcode),
    #[error("branch relaxation failed: {0}")]
    Relaxation(#[from] crate::relax::RelaxError),
    #[error("invalid operand in regalloc adapter: {0}")]
    InvalidOperand(String),
    #[error("AArch64 formal argument copy hazard: {0}")]
    Aarch64FormalArgCopyHazard(String),
    #[error("AArch64 call-argument repair failed closed: {0}")]
    Aarch64CallArgRepair(String),
    #[error("malformed AArch64 machine function `{function}`: {detail}")]
    MalformedAarch64Function { function: String, detail: String },
    #[error(
        "AArch64 object field `{field}` for function `{function}` cannot represent byte count {value} (maximum {max})"
    )]
    Aarch64ObjectFieldTooLarge {
        function: String,
        field: &'static str,
        value: u128,
        max: u128,
    },
    #[error("debug provenance validation failed: {0}")]
    DebugProvenance(String),
    #[error("guard kernel gate fail-closed re-check rejected: {0}")]
    GuardKernelRecheckRejected(String),
    #[error("target object emission unsupported for {target} {format}: {reason}")]
    TargetObjectUnsupported {
        target: String,
        format: String,
        reason: String,
    },
    #[error(
        "exception-handling sidecar unsupported at code-only API `{api}` for `{function}`: {reason}"
    )]
    EhSidecarUnsupported {
        function: String,
        api: &'static str,
        reason: String,
    },
    #[error("object relocation inventory for `{object}` is incomplete: {reason}")]
    ObjectRelocationInventoryIncomplete { object: String, reason: String },
    #[error("dispatch verification failed ({violations} violations): {summary}")]
    DispatchVerificationFailed {
        violations: usize,
        summary: String,
        report: VerificationReport,
    },
    #[error("CoreML MIL emission failed: {0}")]
    CoreMLEmit(#[from] CoreMLEmitError),
    #[error("Metal kernel emission failed: {0}")]
    MetalEmit(#[from] crate::metal_emitter::MetalEmitError),
    #[error("Mach-O fixup resolution failed: {0}")]
    Fixup(#[from] crate::macho::FixupError),
    #[error("Mach-O relocation emission failed: {0}")]
    MachORelocation(#[from] crate::macho::MachORelocationError),
    #[error("Mach-O object serialization failed: {0}")]
    MachOWrite(#[from] crate::macho::MachOWriteError),
    #[error("compact-unwind emission failed: {0}")]
    CompactUnwind(#[from] crate::unwind::CompactUnwindError),
    /// [`DispatchVerifyMode::Sampled`] selected this function but the crate
    /// was built without the `verify` feature, so no verifier is linked.
    /// Sampled verification is an explicit opt-in; skipping it silently would
    /// be fail-open, so the compile is rejected instead.
    #[error(
        "sampled verification selected `{function}` but trust-cg-codegen was built without the `verify` feature"
    )]
    SampledVerifyUnavailable { function: String },
    #[cfg(feature = "verify")]
    #[error(
        "function verification failed: {failures} failures, {coverage:.1}% coverage ({function})"
    )]
    VerificationFailed {
        function: String,
        failures: usize,
        coverage: f64,
        report: trust_cg_verify::FunctionVerificationReport,
    },
    /// The fsym trust-ir preflight reported a deref-coverage gap (a dereference
    /// obligation dropped without a verdict — the #49 fail-open class). The CLI
    /// path already fails closed on `report.has_coverage_error()`; this variant
    /// surfaces the same gap at the in-pipeline preflight so a coverage gap
    /// FAILS the compile rather than only sitting in the advisory report.
    #[cfg(feature = "verify")]
    #[error("fsym deref-coverage gap: {0}")]
    FsymCoverageGap(String),
}

/// Keep public `Result`-returning compile APIs total across fail-closed
/// optimizer assertions.  The optimizer's direct pass API intentionally keeps
/// assertions as hard X5 teeth for pass-level tests; at the pipeline boundary
/// an unwinding assertion is converted into a typed rejection so malformed or
/// newly exposed CFG shapes cannot crash a compiler service.
fn catch_optimization_invariant<T>(
    function: String,
    run: impl FnOnce() -> T,
) -> Result<T, PipelineError> {
    std::panic::catch_unwind(std::panic::AssertUnwindSafe(run)).map_err(|payload| {
        let detail = if let Some(message) = payload.downcast_ref::<&'static str>() {
            (*message).to_owned()
        } else if let Some(message) = payload.downcast_ref::<String>() {
            message.clone()
        } else {
            "non-string optimizer panic payload".to_owned()
        };
        PipelineError::OptimizationInvariantViolation { function, detail }
    })
}

fn aarch64_object_field_too_large(
    function: &str,
    field: &'static str,
    value: u128,
    max: u128,
) -> PipelineError {
    PipelineError::Aarch64ObjectFieldTooLarge {
        function: function.to_owned(),
        field,
        value,
        max,
    }
}

fn checked_aarch64_object_u32(
    function: &str,
    field: &'static str,
    value: usize,
) -> Result<u32, PipelineError> {
    let value = value as u128;
    u32::try_from(value)
        .map_err(|_| aarch64_object_field_too_large(function, field, value, u128::from(u32::MAX)))
}

fn checked_aarch64_object_u64(
    function: &str,
    field: &'static str,
    value: usize,
) -> Result<u64, PipelineError> {
    let value = value as u128;
    u64::try_from(value)
        .map_err(|_| aarch64_object_field_too_large(function, field, value, u128::from(u64::MAX)))
}

fn checked_aarch64_fixup_offset(
    function: &str,
    base: u64,
    local: u32,
) -> Result<u32, PipelineError> {
    let value = u128::from(base) + u128::from(local);
    u32::try_from(value).map_err(|_| {
        aarch64_object_field_too_large(
            function,
            "combined text fixup offset",
            value,
            u128::from(u32::MAX),
        )
    })
}

fn checked_aarch64_macho_relocation_offset(
    function: &str,
    field: &'static str,
    value: u32,
) -> Result<u32, PipelineError> {
    if value <= i32::MAX as u32 {
        Ok(value)
    } else {
        Err(aarch64_object_field_too_large(
            function,
            field,
            u128::from(value),
            i32::MAX as u128,
        ))
    }
}

fn checked_aarch64_capacity(
    function: &str,
    field: &'static str,
    count: usize,
    stride: usize,
) -> Result<usize, PipelineError> {
    count.checked_mul(stride).ok_or_else(|| {
        aarch64_object_field_too_large(
            function,
            field,
            (count as u128) * (stride as u128),
            usize::MAX as u128,
        )
    })
}

fn checked_aarch64_size_sum(
    function: &str,
    field: &'static str,
    left: usize,
    right: usize,
) -> Result<usize, PipelineError> {
    left.checked_add(right).ok_or_else(|| {
        aarch64_object_field_too_large(
            function,
            field,
            (left as u128) + (right as u128),
            usize::MAX as u128,
        )
    })
}

fn extend_aarch64_object_code(
    combined: &mut Vec<u8>,
    function: &str,
    code: &[u8],
) -> Result<(), PipelineError> {
    let expected_len = checked_aarch64_size_sum(
        function,
        "combined code byte length",
        combined.len(),
        code.len(),
    )?;
    combined.try_reserve(code.len()).map_err(|error| {
        PipelineError::Encoding(format!(
            "AArch64 combined code allocation for `{function}` failed: {error}"
        ))
    })?;
    combined.extend_from_slice(code);
    debug_assert_eq!(combined.len(), expected_len);
    Ok(())
}

/// The architectural AArch64 NOP word, used as inter-function padding.
const AARCH64_NOP_WORD: [u8; 4] = 0xD503_201Fu32.to_le_bytes();

/// Pad the combined `__text` stream so the NEXT function starts on the
/// alignment its emission requested ([`MachFunction::text_align_log2`],
/// raised above the 4-byte default only by the loop-head alignment pass —
/// see [`crate::loop_align`]). Padding bytes are architectural NOP words:
/// they sit between functions (every function ends in a hard terminator, so
/// no PC ever reaches them) and belong to no function's unwind span.
///
/// Fails closed if the stream is not word-aligned (every AArch64 function is
/// a whole number of 4-byte words; anything else means an emitter bug that
/// MUST not be papered over with byte padding).
fn pad_aarch64_text_for_function_alignment(
    combined: &mut Vec<u8>,
    function: &str,
    text_align_log2: u8,
) -> Result<(), PipelineError> {
    // Default 4-byte alignment holds by construction (whole words only).
    if text_align_log2 <= 2 {
        return Ok(());
    }
    if !combined.len().is_multiple_of(4) {
        return Err(PipelineError::Encoding(format!(
            "combined AArch64 text length {} is not word-aligned before placing `{function}` \
             (fail-closed: padding must never mask a partial-word emission)",
            combined.len()
        )));
    }
    let align: usize = 1usize << u32::from(text_align_log2);
    let pad = (align - (combined.len() % align)) % align;
    let expected_len =
        checked_aarch64_size_sum(function, "combined code byte length", combined.len(), pad)?;
    for _ in 0..(pad / 4) {
        combined.extend_from_slice(&AARCH64_NOP_WORD);
    }
    debug_assert_eq!(combined.len(), expected_len);
    debug_assert_eq!(combined.len() % align, 0);
    Ok(())
}

/// The `__text` section alignment (log2) a module must carry so every
/// function-relative alignment request in `functions` is absolute after
/// linking: the maximum requested alignment, floored at the AArch64
/// instruction default (2).
fn aarch64_module_text_align_log2(functions: &[IrMachFunction]) -> u8 {
    functions
        .iter()
        .map(|func| func.text_align_log2)
        .max()
        .unwrap_or(2)
        .max(2)
}

/// ELF `sh_addralign` in BYTES for a `.text` section carrying code whose
/// strongest function-relative alignment request is `text_align_log2`:
/// the machine's baseline alignment raised to that request.
fn elf_text_align_bytes(machine: crate::elf::ElfMachine, text_align_log2: u8) -> u64 {
    let baseline: u64 = match machine {
        crate::elf::ElfMachine::AArch64 => 4,
        crate::elf::ElfMachine::X86_64 => 16,
        crate::elf::ElfMachine::Riscv64 => 4,
    };
    baseline.max(1u64 << u32::from(text_align_log2.min(63)))
}

