/// A single proof fact cited by a proof-optimization certificate.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ProofOptimizationConsumedFactCitation {
    pub name: String,
    pub payload: Option<String>,
}

/// Stable, serializable citation for a proof-optimization certificate emitted
/// by `trust-cg-opt`.
///
/// The underlying `OptCertificate` stays in `trust-cg-opt`; codegen/release/replay
/// artifacts carry this compact form so downstream tooling can cite the
/// certificate identity and its proof/validation hashes without depending on
/// pass-internal data structures.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ProofOptimizationCertificateCitation {
    pub function_name: String,
    pub certificate_id: String,
    pub proof_hash: String,
    pub validation_hash: String,
    pub source_region_hash: String,
    pub target_region_hash: String,
    pub transform_name: String,
    pub transform_version: u32,
    pub admission: String,
    pub kind: String,
    pub status: String,
    pub rejection_code: Option<String>,
    pub rejection_fact: Option<String>,
    pub rejection_detail: Option<String>,
    pub consumed_facts: Vec<ProofOptimizationConsumedFactCitation>,
}

impl ProofOptimizationCertificateCitation {
    fn from_opt_certificate(
        function_name: &str,
        certificate: &trust_cg_opt::proof_opts::OptCertificate,
    ) -> Self {
        let consumed_facts = certificate
            .consumed_facts
            .iter()
            .copied()
            .map(|fact| ProofOptimizationConsumedFactCitation {
                name: fact.stable_name().to_owned(),
                payload: fact.payload(),
            })
            .collect();
        let rejection = certificate.rejection.as_ref();

        Self {
            function_name: function_name.to_owned(),
            certificate_id: format_u128_identity(certificate.certificate_id),
            proof_hash: format_u128_identity(certificate.proof_hash),
            validation_hash: format_u128_identity(certificate.validation_hash),
            source_region_hash: format_u128_identity(certificate.source_region_hash),
            target_region_hash: format_u128_identity(certificate.target_region_hash),
            transform_name: certificate.transform.name.clone(),
            transform_version: certificate.transform.version,
            admission: certificate.route.admission.clone(),
            kind: format!("{:?}", certificate.kind),
            status: if rejection.is_some() {
                "rejected".to_owned()
            } else {
                "applied".to_owned()
            },
            rejection_code: rejection.map(|rejection| rejection.code.as_str().to_owned()),
            rejection_fact: rejection.map(|rejection| rejection.fact.clone()),
            rejection_detail: rejection.map(|rejection| rejection.detail.clone()),
            consumed_facts,
        }
    }

    pub fn to_json_value(&self) -> serde_json::Value {
        let consumed_facts = self
            .consumed_facts
            .iter()
            .map(|fact| {
                let mut object = serde_json::Map::with_capacity(2);
                object.insert(
                    "name".to_owned(),
                    serde_json::Value::String(fact.name.clone()),
                );
                object.insert(
                    "payload".to_owned(),
                    fact.payload
                        .as_ref()
                        .map_or(serde_json::Value::Null, |payload| {
                            serde_json::Value::String(payload.clone())
                        }),
                );
                serde_json::Value::Object(object)
            })
            .collect();

        let mut object = serde_json::Map::with_capacity(15);
        object.insert(
            "function_name".to_owned(),
            serde_json::Value::String(self.function_name.clone()),
        );
        object.insert(
            "certificate_id".to_owned(),
            serde_json::Value::String(self.certificate_id.clone()),
        );
        object.insert(
            "proof_hash".to_owned(),
            serde_json::Value::String(self.proof_hash.clone()),
        );
        object.insert(
            "validation_hash".to_owned(),
            serde_json::Value::String(self.validation_hash.clone()),
        );
        object.insert(
            "source_region_hash".to_owned(),
            serde_json::Value::String(self.source_region_hash.clone()),
        );
        object.insert(
            "target_region_hash".to_owned(),
            serde_json::Value::String(self.target_region_hash.clone()),
        );
        object.insert(
            "transform_name".to_owned(),
            serde_json::Value::String(self.transform_name.clone()),
        );
        object.insert(
            "transform_version".to_owned(),
            serde_json::Value::Number(serde_json::Number::from(u64::from(self.transform_version))),
        );
        object.insert(
            "admission".to_owned(),
            serde_json::Value::String(self.admission.clone()),
        );
        object.insert(
            "kind".to_owned(),
            serde_json::Value::String(self.kind.clone()),
        );
        object.insert(
            "status".to_owned(),
            serde_json::Value::String(self.status.clone()),
        );
        object.insert(
            "rejection_code".to_owned(),
            self.rejection_code
                .as_ref()
                .map_or(serde_json::Value::Null, |code| {
                    serde_json::Value::String(code.clone())
                }),
        );
        object.insert(
            "rejection_fact".to_owned(),
            self.rejection_fact
                .as_ref()
                .map_or(serde_json::Value::Null, |fact| {
                    serde_json::Value::String(fact.clone())
                }),
        );
        object.insert(
            "rejection_detail".to_owned(),
            self.rejection_detail
                .as_ref()
                .map_or(serde_json::Value::Null, |detail| {
                    serde_json::Value::String(detail.clone())
                }),
        );
        object.insert(
            "consumed_facts".to_owned(),
            serde_json::Value::Array(consumed_facts),
        );
        serde_json::Value::Object(object)
    }
}

fn format_u128_identity(value: u128) -> String {
    format!("{value:032x}")
}

fn proof_optimization_certificate_citations(
    function_name: &str,
    certificates: &[trust_cg_opt::proof_opts::OptCertificate],
) -> Vec<ProofOptimizationCertificateCitation> {
    certificates
        .iter()
        .map(|certificate| {
            ProofOptimizationCertificateCitation::from_opt_certificate(function_name, certificate)
        })
        .collect()
}

#[cfg(feature = "verify")]
fn fsym_trust_ir_summary_from_report(
    module_name: &str,
    function_name: &str,
    report: trust_cg_verify::fsym_trust_ir::FsymTrustIrReport,
) -> FsymTrustIrPipelineSummary {
    let diagnostics: Vec<FsymTrustIrPipelineDiagnostic> = report
        .diagnostics
        .iter()
        .filter(|diagnostic| diagnostic.function == function_name)
        .map(|diagnostic| FsymTrustIrPipelineDiagnostic {
            kind: format!("{:?}", diagnostic.kind),
            block: diagnostic.block,
            inst_index: diagnostic.inst_index,
            span: diagnostic.span.map(|span| FsymTrustIrPipelineSourceSpan {
                file: span.file,
                line: span.line,
                col: span.col,
            }),
            message: diagnostic.message.clone(),
            warning: diagnostic.render(
                trust_cg_verify::fsym_trust_ir::FsymTrustIrSeverity::Warning,
                None,
            ),
        })
        .collect();

    let unknown_obligations: Vec<FsymTrustIrPipelineUnknown> = report
        .unknown_obligations
        .iter()
        .filter(|unknown| unknown.function == function_name)
        .map(|unknown| FsymTrustIrPipelineUnknown {
            kind: format!("{:?}", unknown.kind),
            label: unknown.label.clone(),
            block: unknown.block,
            inst_index: unknown.inst_index,
            reason: unknown.reason.clone(),
            warning: unknown.render(None),
        })
        .collect();

    let skipped = report
        .skipped_functions
        .iter()
        .find(|skip| skip.function == function_name)
        .map(|skip| FsymTrustIrPipelineSkip {
            reason: format!("{:?}", skip.reason),
            detail: skip.detail.clone(),
        });

    let scanned = report
        .scanned_function_names
        .iter()
        .any(|name| name == function_name);
    let warning_count =
        diagnostics.len() + unknown_obligations.len() + usize::from(skipped.is_some());

    // Carry deref-coverage gaps for this function so the preflight can fail
    // closed on them (the #49 dropped-obligation class), matching the CLI gate.
    let coverage_errors: Vec<String> = report
        .coverage_errors
        .iter()
        .filter(|err| err.function == function_name)
        .map(|err| err.render(None))
        .collect();

    FsymTrustIrPipelineSummary {
        module_name: module_name.to_owned(),
        function_name: function_name.to_owned(),
        scanned,
        diagnostic_count: diagnostics.len(),
        warning_count,
        unknown_obligation_count: unknown_obligations.len(),
        skipped,
        diagnostics,
        unknown_obligations,
        coverage_error_count: coverage_errors.len(),
        coverage_errors,
    }
}

#[cfg(feature = "verify")]
fn fsym_single_function_module(
    module: &trust_ir::Module,
    trust_ir_func: &trust_ir::Function,
) -> trust_ir::Module {
    let mut module = module.clone();
    module.functions = vec![trust_ir_func.clone()];
    module
}

fn provenance_from_isel_trust_ir_origins(
    isel_func: &trust_cg_lower::isel::ISelFunction,
) -> Option<trust_cg_ir::ProvenanceMap> {
    let mut provenance = trust_cg_ir::ProvenanceMap::new();
    let mut recorded = false;
    let pass = trust_cg_ir::PassId::new("codegen-trust_ir-provenance");
    let mut ir_inst_idx = 0_u32;

    for block_ref in &isel_func.block_order {
        let Some(block) = isel_func.blocks.get(block_ref) else {
            continue;
        };
        for inst_idx in 0..block.insts.len() {
            if let Some(origin) = block.trust_ir_origins.get(inst_idx).copied().flatten() {
                provenance.record_lowering(origin, &[InstId(ir_inst_idx)], pass.clone());
                recorded = true;
            }
            ir_inst_idx = ir_inst_idx.saturating_add(1);
        }
    }

    recorded.then_some(provenance)
}

fn trust_ir_source_locs_from_input(
    input: &trust_cg_lower::Function,
) -> BTreeMap<trust_cg_ir::TrustIrInstId, trust_cg_ir::SourceLoc> {
    let mut source_locs = BTreeMap::new();

    for block_ref in input.layout_order() {
        let Some(block) = input.blocks.get(&block_ref) else {
            continue;
        };
        let trust_ir_origins = input.trust_ir_origins.get(&block_ref);
        for inst_idx in 0..block.instructions.len() {
            let Some(origin) = trust_ir_origins
                .and_then(|origins| origins.get(inst_idx))
                .copied()
                .flatten()
            else {
                continue;
            };
            let Some(loc) = block.source_locs.get(inst_idx).copied().flatten() else {
                continue;
            };
            source_locs.entry(origin).or_insert(loc);
        }
    }

    source_locs
}

fn source_line_entries_from_inst_source_locs(
    ir_func: &IrMachFunction,
) -> Vec<crate::dwarf_info::SourceLineEntry> {
    let mut line_entries = Vec::new();
    let mut inst_offset: u64 = 0;
    for block_id in &ir_func.block_order {
        let block = &ir_func.blocks[block_id.0 as usize];
        for &inst_id in &block.insts {
            let inst = &ir_func.insts[inst_id.0 as usize];
            if let Some(loc) = &inst.source_loc {
                line_entries.push(crate::dwarf_info::SourceLineEntry {
                    address: inst_offset,
                    line: loc.line,
                    column: loc.col as u16,
                    is_stmt: true,
                });
            }
            inst_offset += 4; // AArch64: each instruction is 4 bytes.
        }
    }
    line_entries
}

fn source_line_entries_from_provenance(
    provenance: &trust_cg_ir::ProvenanceMap,
    trust_ir_source_locs: &BTreeMap<trust_cg_ir::TrustIrInstId, trust_cg_ir::SourceLoc>,
) -> Vec<crate::dwarf_info::SourceLineEntry> {
    provenance
        .source_offsets()
        .filter_map(|(offset, trust_ir_ids)| {
            trust_ir_ids.iter().find_map(|trust_ir_id| {
                trust_ir_source_locs.get(trust_ir_id).map(|loc| {
                    crate::dwarf_info::SourceLineEntry {
                        address: offset as u64,
                        line: loc.line,
                        column: loc.col as u16,
                        is_stmt: true,
                    }
                })
            })
        })
        .collect()
}

fn mark_consecutive_line_statements(
    mut line_entries: Vec<crate::dwarf_info::SourceLineEntry>,
) -> Vec<crate::dwarf_info::SourceLineEntry> {
    let mut previous_line = None;
    for entry in &mut line_entries {
        let is_new_line = previous_line != Some(entry.line);
        entry.is_stmt = is_new_line;
        previous_line = Some(entry.line);
    }
    line_entries
}

fn build_source_line_entries(
    ir_func: &IrMachFunction,
    debug_provenance: Option<(
        &trust_cg_ir::ProvenanceMap,
        &BTreeMap<trust_cg_ir::TrustIrInstId, trust_cg_ir::SourceLoc>,
    )>,
) -> Vec<crate::dwarf_info::SourceLineEntry> {
    if let Some((provenance, trust_ir_source_locs)) = debug_provenance {
        let line_entries = source_line_entries_from_provenance(provenance, trust_ir_source_locs);
        if !line_entries.is_empty() {
            return mark_consecutive_line_statements(line_entries);
        }
    }

    mark_consecutive_line_statements(source_line_entries_from_inst_source_locs(ir_func))
}

#[cfg(feature = "verify")]
pub use trust_cg_verify::CegisPassStats;

#[cfg(not(feature = "verify"))]
#[derive(Debug, Clone, Default)]
pub struct CegisPassStats {
    pub functions_seen: u64,
    pub cache_hits: u64,
    pub cache_misses: u64,
    pub cache_puts: u64,
    pub candidates: u64,
    pub verified: u64,
    pub rejected: u64,
    pub budget_exhausted: u64,
    pub solver_calls: u64,
}

// ---------------------------------------------------------------------------
// Input format detection and module loading
// ---------------------------------------------------------------------------

/// Magic bytes for the binary trust_ir bitcode (.tmbc) format.
pub const TMBC_MAGIC: &[u8; 4] = b"tMBC";

/// Current version of the .tmbc wire format.
pub const TMBC_VERSION: u32 = 1;

/// Detected input format for trust_ir module files.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum InputFormat {
    /// JSON wire format (.json).
    Json,
    /// Binary trust_ir bitcode (.tmbc).
    Tmbc,
    /// Human-readable text format (.trust_ir), produced by
    /// `trust_ir::Module`'s `Display` impl and parsed by `trust_ir::parser`.
    TrustIr,
}

/// Format selection mode, used when the caller wants either explicit
/// choice or the legacy auto-detect behaviour.
///
/// `Tmbc`, `Json`, and `Text` force the corresponding parser and ignore
/// both the file extension and any magic-byte mismatch until decode.
/// `Auto` restores the pre-#414 behaviour: prefer `.tmbc`/`.json`/`.trust_ir`
/// by extension, then sniff magic bytes, finally fall back to JSON.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum FormatMode {
    /// Force binary trust_ir bitcode (.tmbc).
    Tmbc,
    /// Force JSON wire format.
    Json,
    /// Force human-readable `.trust_ir` text format (#413).
    ///
    /// The text format is produced by `trust_ir::Module`'s `Display` impl
    /// and parsed by `trust_ir::parser::parse_module`. The parser is
    /// gated behind the upstream `parser` feature, which Trust Codegen now
    /// enables in `[workspace.dependencies]`.
    Text,
    /// Auto-detect by extension and magic bytes (legacy behaviour).
    Auto,
}

/// Detect the input format of a trust_ir module file (legacy auto-detect).
///
/// Checks file extension first (`.tmbc`, `.trust_ir`, or `.json`). For
/// unknown extensions, reads the first 4 bytes and checks for the
/// tMBC magic header; otherwise, sniffs for the text-format header
/// `; TrustIr text format` (produced by `trust_ir::Module`'s `Display` impl).
///
/// Prefer `load_module_as` for new code: per the trust_ir transport
/// architecture (designs/2026-04-16-trust_ir-transport-architecture.md,
/// Layer 4), binary `.tmbc` is the intended default and JSON input is
/// a debug-only opt-in.
pub fn detect_input_format(path: &std::path::Path) -> InputFormat {
    match path.extension().and_then(|ext| ext.to_str()) {
        Some("tmbc") => return InputFormat::Tmbc,
        Some("json") => return InputFormat::Json,
        Some("trust_ir") => return InputFormat::TrustIr,
        _ => {}
    }

    // Fall back to magic-byte detection. trust_ir text-format modules start
    // with the exact comment `; trust_ir text format v1` (see
    // `trust_ir::display`). We treat any leading `;` trust_ir header or
    // `module ` prefix as a text-format hint, then fall back to JSON.
    //
    // The sniff buffer MUST be at least as long as the longest needle: the
    // `; trust_ir text format` header is 22 bytes (it was only 18 bytes under
    // the legacy `; tmir text format` name, so the old 20-byte buffer silently
    // stopped matching after the tmir -> trust_ir rename — a 20-byte slice can
    // never `starts_with` a 22-byte needle). We also use a short-read-tolerant
    // fill loop instead of `read_exact` so that short-but-valid text modules
    // (e.g. `module "x"`) are sniffed rather than misclassified as JSON on EOF.
    let mut magic = [0u8; 32];
    let mut filled = 0usize;
    if let Ok(mut file) = std::fs::File::open(path) {
        use std::io::Read;
        while filled < magic.len() {
            match file.read(&mut magic[filled..]) {
                Ok(0) => break,
                Ok(n) => filled += n,
                Err(ref err) if err.kind() == std::io::ErrorKind::Interrupted => continue,
                Err(_) => break,
            }
        }
    }
    let magic = &magic[..filled];
    if magic.starts_with(b"tMBC") {
        return InputFormat::Tmbc;
    }
    if is_trust_ir_text_header(magic) || magic.starts_with(b"module ") {
        return InputFormat::TrustIr;
    }
    InputFormat::Json
}

/// True if `prefix` begins with a trust_ir text-format header comment.
///
/// Accepts both the snake_case `; trust_ir text format` spelling (used by the
/// `.trust_ir` extension, the `--emit-trust_ir` flag, and vendored conformance
/// fixtures) and the CamelCase `; TrustIr text format` spelling emitted by the
/// upstream `trust_ir::Module` `Display` impl, so the loader recognises files
/// produced by any toolchain version regardless of header styling drift.
fn is_trust_ir_text_header(prefix: &[u8]) -> bool {
    prefix.starts_with(b"; trust_ir text format") || prefix.starts_with(b"; TrustIr text format")
}

/// Load a trust_ir module from a file using the legacy auto-detect path.
///
/// Kept for in-tree callers that still want the old behaviour. The CLI
/// now uses [`load_module_as`] and defaults to binary `.tmbc`.
pub fn load_module(path: &std::path::Path) -> Result<trust_ir::Module, PipelineError> {
    load_module_as(path, FormatMode::Auto)
}

/// Load a trust_ir module from a file with an explicit format selection.
///
/// - `FormatMode::Tmbc`: parse the file as binary trust_ir bitcode. If the
///   magic bytes do not match, return a clear `PipelineError::ISel`
///   error that names the `--format=json` CLI escape hatch.
/// - `FormatMode::Json`: parse the file as a JSON-serialised
///   `trust_ir::Module`, regardless of extension.
/// - `FormatMode::Text`: parse the file as a human-readable `.trust_ir`
///   text module via `trust_ir::parser::parse_module` (#413).
/// - `FormatMode::Auto`: preserve the pre-#414 auto-detect behaviour
///   (extension + magic-byte sniffing, JSON fallback; now also
///   recognises `.trust_ir`).
pub fn load_module_as(
    path: &std::path::Path,
    mode: FormatMode,
) -> Result<trust_ir::Module, PipelineError> {
    match mode {
        FormatMode::Tmbc => {
            let bytes =
                crate::resource_limits::read_file_bounded(path).map_err(PipelineError::ISel)?;
            if !bytes.starts_with(TMBC_MAGIC) {
                return Err(PipelineError::ISel(format!(
                    "'{}' does not start with the tMBC magic header; the CLI now defaults to \
                     binary trust_ir bitcode input. Pass `--format=json` if this file is a trust_ir \
                     JSON wire-format module, or regenerate it as `.tmbc`.",
                    path.display()
                )));
            }
            decode_tmbc(&bytes)
        }
        FormatMode::Json => {
            let json =
                crate::resource_limits::read_utf8_bounded(path).map_err(PipelineError::ISel)?;
            serde_json::from_str(&json)
                .map_err(|err: serde_json::Error| PipelineError::ISel(format!("JSON error: {err}")))
        }
        FormatMode::Text => {
            let text =
                crate::resource_limits::read_utf8_bounded(path).map_err(PipelineError::ISel)?;
            parse_trust_ir_text(&text)
        }
        FormatMode::Auto => match detect_input_format(path) {
            InputFormat::Json => {
                let json =
                    crate::resource_limits::read_utf8_bounded(path).map_err(PipelineError::ISel)?;
                serde_json::from_str(&json).map_err(|err: serde_json::Error| {
                    PipelineError::ISel(format!("JSON error: {err}"))
                })
            }
            InputFormat::Tmbc => {
                let bytes =
                    crate::resource_limits::read_file_bounded(path).map_err(PipelineError::ISel)?;
                decode_tmbc(&bytes)
            }
            InputFormat::TrustIr => {
                let text =
                    crate::resource_limits::read_utf8_bounded(path).map_err(PipelineError::ISel)?;
                parse_trust_ir_text(&text)
            }
        },
    }
}

/// Load a trust_ir module from in-memory bytes, auto-detecting the format.
///
/// Bytes starting with `tMBC` magic are decoded as binary bitcode. UTF-8
/// text that begins with `; TrustIr text format` or `module ` is parsed
/// as `.trust_ir` text (#413). Otherwise the bytes are interpreted as a
/// UTF-8 JSON string.
pub fn load_module_from_bytes(bytes: &[u8]) -> Result<trust_ir::Module, PipelineError> {
    if bytes.starts_with(TMBC_MAGIC) {
        return decode_tmbc(bytes);
    }
    let text = std::str::from_utf8(bytes).map_err(|err| PipelineError::ISel(err.to_string()))?;
    let trimmed = text.trim_start();
    if is_trust_ir_text_header(trimmed.as_bytes()) || trimmed.starts_with("module ") {
        return parse_trust_ir_text(text);
    }
    serde_json::from_str(text)
        .map_err(|err: serde_json::Error| PipelineError::ISel(format!("JSON error: {err}")))
}

/// Parse a `.trust_ir` human-readable text-format module via
/// `trust_ir::parser::parse_module` (#413).
///
/// Requires the `parser` feature on the upstream `trust_ir` crate, which
/// Trust Codegen's `[workspace.dependencies]` now enables.
pub fn parse_trust_ir_text(text: &str) -> Result<trust_ir::Module, PipelineError> {
    trust_ir::parser::parse_module(text)
        .map_err(|err| PipelineError::ISel(format!(".trust_ir parse error: {err}")))
}

/// Render a `trust_ir::Module` to `.trust_ir` human-readable text via its
/// `Display` impl (always on in upstream; see `trust_ir::display`).
///
/// The returned string round-trips through `trust_ir::parser::parse_module`.
pub fn encode_trust_ir_text(module: &trust_ir::Module) -> String {
    format!("{}", module)
}

/// Serialize a `trust_ir::Module` as `.trust_ir` text and write it to disk (#413).
pub fn save_module_to_trust_ir_text(
    module: &trust_ir::Module,
    path: &std::path::Path,
) -> Result<(), PipelineError> {
    let text = encode_trust_ir_text(module);
    std::fs::write(path, text).map_err(|e| {
        PipelineError::ISel(format!(
            "failed to write .trust_ir text file {}: {e}",
            path.display()
        ))
    })
}

// ---------------------------------------------------------------------------
// Binary trust_ir bitcode (.tmbc) codec
// ---------------------------------------------------------------------------

/// Decode a binary trust_ir bitcode (.tmbc) buffer into a `trust_ir::Module`.
///
/// Format: `tMBC` magic (4 bytes) + version u32-LE (4 bytes) + `trust_ir::binary`
/// payload (itself prefixed with `TRUST_IR` magic + u32-LE version; see
/// `trust_ir::binary::deserialize_module`).
///
/// The outer `tMBC` envelope is Trust Codegen's transport-layer header (see
/// `designs/2026-04-16-trust_ir-transport-architecture.md`, Layer 2). The inner
/// payload is produced by the upstream `trust_ir/binary` feature — a compact,
/// zero-extra-dependency encoding with its own `TRUST_IR` magic and version.
pub fn decode_tmbc(bytes: &[u8]) -> Result<trust_ir::Module, PipelineError> {
    if bytes.len() < 8 {
        return Err(PipelineError::ISel(format!(
            "invalid tMBC data: expected at least 8 bytes, got {}",
            bytes.len()
        )));
    }

    if &bytes[..4] != TMBC_MAGIC {
        return Err(PipelineError::ISel(format!(
            "invalid tMBC magic: expected {:?}, got {:?}",
            TMBC_MAGIC,
            &bytes[..4]
        )));
    }

    let version = u32::from_le_bytes([bytes[4], bytes[5], bytes[6], bytes[7]]);
    if version != TMBC_VERSION {
        return Err(PipelineError::ISel(format!(
            "unsupported tMBC version: {version}"
        )));
    }

    trust_ir::binary::deserialize_module(&bytes[8..])
        .map_err(|e| PipelineError::ISel(format!("failed to deserialize tMBC payload: {e}")))
}

/// Encode a `trust_ir::Module` into binary trust_ir bitcode (.tmbc) format.
///
/// Format: `tMBC` magic (4 bytes) + version u32-LE (4 bytes) + `trust_ir::binary`
/// payload. The inner payload is produced by `trust_ir::binary::serialize_module`,
/// which carries its own `TRUST_IR` magic + u32-LE version header. See
/// `designs/2026-04-16-trust_ir-transport-architecture.md`, Layer 2.
pub fn encode_tmbc(module: &trust_ir::Module) -> Result<Vec<u8>, PipelineError> {
    let payload = trust_ir::binary::serialize_module(module);

    let mut buf = Vec::with_capacity(8 + payload.len());
    buf.extend_from_slice(TMBC_MAGIC);
    buf.extend_from_slice(&TMBC_VERSION.to_le_bytes());
    buf.extend_from_slice(&payload);
    Ok(buf)
}

/// Serialize a `trust_ir::Module` and write it to a `.tmbc` file on disk.
pub fn save_module_to_tmbc(
    module: &trust_ir::Module,
    path: &std::path::Path,
) -> Result<(), PipelineError> {
    let buf = encode_tmbc(module)?;
    std::fs::write(path, buf).map_err(|e| {
        PipelineError::ISel(format!("failed to write tMBC file {}: {e}", path.display()))
    })
}

// ---------------------------------------------------------------------------
// CompilationUnit — holds all state across compilation phases
// ---------------------------------------------------------------------------

/// Holds the state of a single function being compiled through the pipeline.
pub struct CompilationUnit {
    /// The function name.
    pub name: String,
    /// The IR-level function (shared model used by opt and frame lowering).
    pub ir_func: IrMachFunction,
    /// Encoded machine code bytes (populated after encoding phase).
    pub code: Vec<u8>,
    /// Pipeline configuration.
    pub config: PipelineConfig,
}

impl CompilationUnit {
    /// Create a new compilation unit from an IR function.
    pub fn new(ir_func: IrMachFunction, config: PipelineConfig) -> Self {
        let name = ir_func.name.clone();
        Self {
            name,
            ir_func,
            code: Vec::new(),
            config,
        }
    }
}

// ---------------------------------------------------------------------------
// Adapter: trust_cg_lower::isel::ISelFunction -> trust_cg_ir::MachFunction
// ---------------------------------------------------------------------------

// NOTE: `map_isel_opcode()` has been ELIMINATED as of issue #73.
//
// The ISel now uses `trust_cg_ir::AArch64Opcode` directly (re-exported via
// `trust_cg_lower::isel::AArch64Opcode`). There is no longer a separate ISel
// opcode enum, so no mapping is needed. The `isel_to_ir` adapter below
// uses `isel_inst.opcode` directly as an `IrOpcode`.

/// Convert ISel's `ISelFunction` to the canonical `trust_cg_ir::MachFunction`.
///
/// Delegates to `ISelFunction::to_ir_func()` which owns the conversion logic
/// (issue #73 consolidation). This thin wrapper is preserved for backward
/// compatibility — new code should call `isel_func.to_ir_func()` directly.
pub fn isel_to_ir(
    isel_func: &trust_cg_lower::isel::ISelFunction,
    _param_types: &[trust_cg_ir::function::Type],
    _return_types: &[trust_cg_ir::function::Type],
) -> IrMachFunction {
    // The ISelFunction::to_ir_func() method derives the IR signature from
    // the ISel's own signature using From<Signature>. The param_types and
    // return_types arguments are now unused — they were only needed when
    // the conversion was done externally.
    isel_func.to_ir_func()
}

// ---------------------------------------------------------------------------
// Adapter: trust_cg_ir::MachFunction -> trust_cg_regalloc::RegAllocFunction
// ---------------------------------------------------------------------------

/// Convert the canonical `trust_cg_ir::MachFunction` to `RegAllocFunction` format.
///
/// The `RegAllocFunction` separates defs from uses for liveness analysis.
/// We use a simple heuristic: first operand is def, rest are uses
/// (for most instructions). Special cases: branches and calls have no defs.
///
/// Uses `From`/`TryFrom` impls from `trust_cg_regalloc::machine_types` for
/// individual block and operand conversions (issue #73 consolidation).
pub fn ir_to_regalloc(
    ir_func: &IrMachFunction,
) -> Result<trust_cg_regalloc::RegAllocFunction, PipelineError> {
    use trust_cg_regalloc::machine_types as ra;

    let mut ra_func = ra::RegAllocFunction {
        name: ir_func.name.clone(),
        insts: Vec::new(),
        blocks: Vec::new(),
        block_order: ir_func.block_order.clone(),
        entry_block: ir_func.entry,
        next_vreg: ir_func.next_vreg,
        next_stack_slot: ir_func.stack_slots.len() as u32,
        stack_slots: BTreeMap::new(),
    };

    // Convert stack slots using From impl (issue #73).
    for (i, slot) in ir_func.stack_slots.iter().enumerate() {
        ra_func.stack_slots.insert(
            trust_cg_ir::types::StackSlotId(i as u32),
            ra::RegAllocStackSlot::from(slot),
        );
    }

    // Convert instructions.
    // InstFlags are unified (issue #73) — same type in trust_cg_ir and trust_cg_regalloc,
    // so flags pass through directly without conversion.
    for ir_inst in &ir_func.insts {
        let (defs, uses, tied_operands) = classify_def_use(ir_inst)?;
        let mut implicit_defs: Vec<PReg> = ir_inst.implicit_defs.to_vec();
        let implicit_uses: Vec<PReg> = ir_inst.implicit_uses.to_vec();

        if is_aarch64_call_boundary(ir_inst) {
            add_aarch64_call_clobbers(&mut implicit_defs);
        }

        ra_func.insts.push(ra::RegAllocInst {
            opcode: ir_inst.opcode as u16,
            defs,
            uses,
            implicit_defs,
            implicit_uses,
            tied_operands,
            flags: ir_inst.flags,
        });
    }

    // Convert blocks using From impl (issue #73).
    for ir_block in &ir_func.blocks {
        ra_func.blocks.push(ra::RegAllocBlock::from(ir_block));
    }

    Ok(ra_func)
}

pub(crate) fn derive_ir_cfg_edges_from_branch_operands(
    ir_func: &IrMachFunction,
) -> Vec<(BlockId, BlockId)> {
    let mut edges = Vec::new();
    for (layout_idx, &block_id) in ir_func.block_order.iter().enumerate() {
        let Some(block) = ir_func.blocks.get(block_id.0 as usize) else {
            continue;
        };
        // Trailing `AlignNop` padding (loop-head alignment inserts it AFTER a
        // block's terminator when the next block is an aligned loop header) is
        // not control flow: skip it when locating the terminator, or a block
        // ending in `B`/`Ret` + padding would spuriously derive a fallthrough
        // edge into the very loop header the padding aligns.
        let last_real_inst = block.insts.iter().rev().find_map(|inst_id| {
            ir_func
                .insts
                .get(inst_id.0 as usize)
                .filter(|inst| !inst.is_pseudo() && inst.opcode != IrOpcode::AlignNop)
        });

        for &inst_id in &block.insts {
            let Some(inst) = ir_func.insts.get(inst_id.0 as usize) else {
                continue;
            };
            // Jump-table dispatch successors: a dense switch reaches its case and
            // default blocks only through the data-driven indirect `Br`, recorded
            // on `ir_func.jump_tables[idx].targets` (referenced by an
            // `Adr ..., JumpTableIndex(idx)` operand) rather than as explicit
            // `Block` operands. Seed those edges so the CFG round-trip keeps the
            // targets reachable and laid out (defect #5).
            for operand in &inst.operands {
                if let Some(jt_idx) = operand.as_jump_table_index()
                    && let Some(jt) = ir_func.jump_tables.get(jt_idx as usize)
                {
                    for &target in &jt.targets {
                        edges.push((block_id, target));
                    }
                }
            }
            if !inst.is_branch() && !inst.is_terminator() {
                continue;
            }
            for operand in &inst.operands {
                if let IrOperand::Block(target) = operand {
                    edges.push((block_id, *target));
                }
            }
        }

        // The encoder lays blocks out contiguously. Any block without a hard
        // non-fallthrough terminator therefore reaches the next layout block,
        // including the final post-layout form where a redundant `B next` was
        // deliberately elided.
        let hard_terminator = last_real_inst.is_some_and(|inst| {
            inst.is_unconditional_branch()
                || inst.is_return()
                // BRK is not globally flagged as a terminator because exact
                // guard expansions use an intra-block `B.cond; BRK; continue`
                // shape. It is nevertheless non-fallthrough when it is the
                // block's last real instruction.
                || matches!(inst.opcode, IrOpcode::Brk)
                || (inst.is_terminator() && !inst.is_conditional_branch())
        });
        if !hard_terminator && let Some(&fallthrough) = ir_func.block_order.get(layout_idx + 1) {
            edges.push((block_id, fallthrough));
        }
    }

    // The unwinder transfers control from each protected call site to its
    // landing pad without an encoded branch operand.  These edges are still
    // semantic CFG authority for liveness and must match the successors that
    // Invoke lowering records.
    for call_site in &ir_func.eh_metadata.call_sites {
        if let Some(landing_pad) = call_site.landing_pad_block {
            edges.push((call_site.call_block, landing_pad));
        }
    }

    edges
}

/// Reconstruct inter-block CFG edges after branch resolution. AArch64 branch
/// displacements are measured in fixed-width instruction units from the branch
/// itself, so every resolved local target can be mapped back to a laid-out
/// block start exactly. The only permitted non-block targets are the validated
/// `conditional +2; BRK` guard expansions, whose skip stays within the current
/// block and therefore does not create an inter-block liveness edge.
fn derive_ir_cfg_edges_from_resolved_stream(
    ir_func: &IrMachFunction,
) -> Result<Vec<(BlockId, BlockId)>, String> {
    let mut edges = derive_ir_cfg_edges_from_branch_operands(ir_func);
    let mut block_starts: BTreeMap<i64, Vec<BlockId>> = BTreeMap::new();
    let mut real_insts: BTreeMap<i64, (BlockId, InstId)> = BTreeMap::new();
    let mut inst_offsets: HashMap<InstId, (BlockId, i64)> = HashMap::new();
    let mut offset = 0i64;

    for &block_id in &ir_func.block_order {
        block_starts.entry(offset).or_default().push(block_id);
        for &inst_id in &ir_func.block(block_id).insts {
            let inst = ir_func.inst(inst_id);
            if inst.is_pseudo() {
                continue;
            }
            real_insts.insert(offset, (block_id, inst_id));
            inst_offsets.insert(inst_id, (block_id, offset));
            offset += 1;
        }
    }

    for &block_id in &ir_func.block_order {
        for &inst_id in &ir_func.block(block_id).insts {
            let inst = ir_func.inst(inst_id);
            let displacement = match inst.opcode {
                IrOpcode::B | IrOpcode::TailCall => {
                    inst.operands.first().and_then(IrOperand::as_imm)
                }
                IrOpcode::BCond | IrOpcode::Bcc | IrOpcode::Cbz | IrOpcode::Cbnz => {
                    inst.operands.get(1).and_then(IrOperand::as_imm)
                }
                IrOpcode::Tbz | IrOpcode::Tbnz => inst.operands.get(2).and_then(IrOperand::as_imm),
                _ => None,
            };
            let Some(displacement) = displacement else {
                continue;
            };
            let Some(&(source_block, inst_offset)) = inst_offsets.get(&inst_id) else {
                continue;
            };
            let target_offset = inst_offset + displacement;

            if let Some(targets) = block_starts.get(&target_offset) {
                // Empty blocks may share a byte offset. Enter the first one in
                // layout order; its fallthrough chain conservatively reaches
                // the remaining co-located blocks.
                if let Some(&target) = targets.first() {
                    edges.push((source_block, target));
                }
                continue;
            }

            let is_conditional = matches!(
                inst.opcode,
                IrOpcode::BCond
                    | IrOpcode::Bcc
                    | IrOpcode::Cbz
                    | IrOpcode::Cbnz
                    | IrOpcode::Tbz
                    | IrOpcode::Tbnz
            );
            let is_guard_skip = is_conditional
                && displacement == 2
                && real_insts
                    .get(&(inst_offset + 1))
                    .is_some_and(|&(trap_block, trap_id)| {
                        trap_block == source_block && ir_func.inst(trap_id).opcode == IrOpcode::Brk
                    });
            if is_guard_skip
                && (real_insts
                    .get(&target_offset)
                    .is_some_and(|&(target_block, _)| target_block == source_block)
                    || target_offset == offset)
            {
                continue;
            }

            if let Some(&(target_block, _)) = real_insts.get(&target_offset) {
                return Err(format!(
                    "resolved branch instruction {:?} in {:?} targets the middle of {:?}",
                    inst_id, source_block, target_block
                ));
            }
            if inst.opcode == IrOpcode::TailCall {
                // A resolved direct tail call may target another function and
                // has no successor within this MachFunction.
                continue;
            }
            return Err(format!(
                "resolved branch instruction {:?} in {:?} targets instruction offset {} outside the laid-out function",
                inst_id, source_block, target_offset
            ));
        }
    }

    Ok(edges)
}

pub(crate) fn install_ir_cfg_edges(ir_func: &mut IrMachFunction, edges: Vec<(BlockId, BlockId)>) {
    for block in &mut ir_func.blocks {
        block.preds.clear();
        block.succs.clear();
    }

    for (from, to) in edges {
        let from_idx = from.0 as usize;
        let to_idx = to.0 as usize;
        if from_idx >= ir_func.blocks.len() || to_idx >= ir_func.blocks.len() {
            continue;
        }
        if !ir_func.blocks[from_idx].succs.contains(&to) {
            ir_func.blocks[from_idx].succs.push(to);
        }
        if !ir_func.blocks[to_idx].preds.contains(&from) {
            ir_func.blocks[to_idx].preds.push(from);
        }
    }
}

fn reconstruct_aarch64_resolved_cfg(ir_func: &IrMachFunction) -> Result<IrMachFunction, String> {
    let mut reconstructed = ir_func.clone();
    let edges = derive_ir_cfg_edges_from_resolved_stream(&reconstructed)?;
    install_ir_cfg_edges(&mut reconstructed, edges);
    Ok(reconstructed)
}

fn rebuild_ir_cfg_edges_from_branch_operands(ir_func: &mut IrMachFunction) {
    let edges = derive_ir_cfg_edges_from_branch_operands(ir_func);
    install_ir_cfg_edges(ir_func, edges);
}

fn add_aarch64_call_clobbers(implicit_defs: &mut Vec<PReg>) {
    let mut clobbers: Vec<PReg> = trust_cg_regalloc::aarch64_caller_saved_regs()
        .into_iter()
        .collect();
    clobbers.sort_by_key(|preg| preg.encoding());

    for preg in clobbers {
        if !implicit_defs.contains(&preg) {
            implicit_defs.push(preg);
        }
    }
}

/// Structural AArch64 call boundary. Do not trust mutable `InstFlags` for
/// allocation or argument authority: opcode identity survives every MachIR
/// adapter, and `TailCall` is the only branch form that consumes call args.
fn is_aarch64_call_boundary(inst: &IrMachInst) -> bool {
    matches!(
        inst.opcode,
        IrOpcode::Bl | IrOpcode::BL | IrOpcode::Blr | IrOpcode::BLR | IrOpcode::TailCall
    )
}

/// Classify operands into defs and uses for regalloc.
///
/// Convention:
/// - For most ALU instructions: operand[0] is def, rest are uses
/// - For stores: all operands are uses (no register def)
/// - For branches/calls/returns: all operands are uses
/// - For loads: operand[0] is def, rest are uses
///
/// Uses `TryFrom<&MachOperand>` for `RegAllocOperand` (issue #73) for the
/// individual operand conversions. The TryFrom impl rejects IR-only variants
/// (FrameIndex, MemOp, Special) that must be lowered before register
/// allocation.
fn classify_def_use(
    inst: &IrMachInst,
) -> Result<
    (
        Vec<trust_cg_regalloc::RegAllocOperand>,
        Vec<trust_cg_regalloc::RegAllocOperand>,
        Vec<(u32, u32)>,
    ),
    PipelineError,
> {
    use trust_cg_regalloc::machine_types::RegAllocOperand as RaOp;

    let convert_op = |op: &IrOperand| -> Result<RaOp, PipelineError> {
        RaOp::try_from(op).map_err(|e| PipelineError::InvalidOperand(e.message))
    };

    let (def_positions, use_positions) = classify_operand_positions(inst);
    let defs: Vec<_> = def_positions
        .iter()
        .map(|&pos| convert_op(&inst.operands[pos]))
        .collect::<Result<_, _>>()?;
    let uses: Vec<_> = use_positions
        .iter()
        .map(|&pos| convert_op(&inst.operands[pos]))
        .collect::<Result<_, _>>()?;

    let mut tied_operands = Vec::new();
    for (def_idx, &def_pos) in def_positions.iter().enumerate() {
        if let Some(use_idx) = use_positions.iter().position(|&p| p == def_pos) {
            tied_operands.push((def_idx as u32, use_idx as u32));
        }
    }

    Ok((defs, uses, tied_operands))
}

// NOTE: `convert_ir_flags_to_regalloc()` has been ELIMINATED as of issue #73.
//
// InstFlags are now unified: trust_cg_regalloc re-exports trust_cg_ir::InstFlags
// directly. The bit-for-bit flag conversion function is no longer needed —
// flags pass through directly in ir_to_regalloc().

// ---------------------------------------------------------------------------
// Apply register allocation results back to IR
// ---------------------------------------------------------------------------

fn project_allocated_preg(preg: PReg, class: RegClass) -> Option<PReg> {
    match class {
        RegClass::Gpr64 => match preg_class(preg) {
            RegClass::Gpr64 => Some(preg),
            RegClass::Gpr32 | RegClass::System => gpr32_to_gpr64(preg),
            _ => None,
        },
        RegClass::Gpr32 | RegClass::System => match preg_class(preg) {
            RegClass::Gpr32 | RegClass::System => Some(preg),
            RegClass::Gpr64 => gpr64_to_gpr32(preg),
            _ => None,
        },
        _ if preg_class(preg) == class => Some(preg),
        _ => None,
    }
}

fn allocated_preg_for_vreg(vreg: VReg, allocation: &BTreeMap<VReg, PReg>) -> Option<PReg> {
    allocation
        .get(&vreg)
        .and_then(|&preg| project_allocated_preg(preg, vreg.class))
}

/// Rewrite all VReg operands in the IR function with their allocated PRegs.
pub fn apply_regalloc(ir_func: &mut IrMachFunction, allocation: &BTreeMap<VReg, PReg>) {
    for inst in &mut ir_func.insts {
        for operand in &mut inst.operands {
            if let IrOperand::VReg(vreg) = operand
                && let Some(preg) = allocated_preg_for_vreg(*vreg, allocation)
            {
                *operand = IrOperand::PReg(preg);
            }
            // If not found in allocation, the vreg was spilled.
            // Spill code insertion should have already handled this.
        }
    }
}

fn apply_regalloc_to_regalloc(
    ra_func: &mut trust_cg_regalloc::RegAllocFunction,
    allocation: &BTreeMap<VReg, PReg>,
) {
    fn rewrite_operand(
        operand: &mut trust_cg_regalloc::machine_types::RegAllocOperand,
        allocation: &BTreeMap<VReg, PReg>,
    ) {
        if let trust_cg_regalloc::machine_types::RegAllocOperand::VReg(vreg) = operand
            && let Some(preg) = allocated_preg_for_vreg(*vreg, allocation)
        {
            *operand = trust_cg_regalloc::machine_types::RegAllocOperand::PReg(preg);
        }
    }

    for inst in &mut ra_func.insts {
        for operand in &mut inst.defs {
            rewrite_operand(operand, allocation);
        }
        for operand in &mut inst.uses {
            rewrite_operand(operand, allocation);
        }
    }
}

fn spill_slot_shape(class: RegClass) -> (u32, u32) {
    match class {
        RegClass::Gpr32 | RegClass::Fpr32 | RegClass::System => (4, 4),
        RegClass::Gpr64 | RegClass::Fpr64 => (8, 8),
        RegClass::Fpr128 => (16, 16),
        RegClass::Fpr16 => (2, 2),
        RegClass::Fpr8 => (1, 1),
    }
}

fn ensure_spill_stack_slots(ir_func: &mut IrMachFunction, spills: &[trust_cg_regalloc::SpillInfo]) {
    let Some(max_slot) = spills.iter().map(|spill| spill.slot.0 as usize).max() else {
        return;
    };

    while ir_func.stack_slots.len() <= max_slot {
        ir_func.stack_slots.push(IrStackSlot::new(8, 8));
    }

    for spill in spills {
        let slot_idx = spill.slot.0 as usize;
        assert!(
            !ir_func.stack_slots[slot_idx].is_runtime_sized(),
            "regalloc spill slot {} must not alias a runtime-sized stack slot",
            slot_idx
        );
        let (size, align) = spill_slot_shape(spill.vreg.class);
        ir_func.stack_slots[slot_idx] = IrStackSlot::new(size, align);
    }
}

fn rebuild_stack_slots_from_regalloc(
    ir_func: &mut IrMachFunction,
    ra_func: &trust_cg_regalloc::RegAllocFunction,
) {
    let Some(max_slot) = ra_func.stack_slots.keys().map(|slot| slot.0 as usize).max() else {
        return;
    };

    while ir_func.stack_slots.len() <= max_slot {
        ir_func.stack_slots.push(IrStackSlot::new(8, 8));
    }

    for (slot_id, ra_slot) in &ra_func.stack_slots {
        let slot = match ra_slot.allocation {
            StackSlotAllocationKind::Fixed => IrStackSlot::new(ra_slot.size, ra_slot.align),
            StackSlotAllocationKind::RuntimeSized { size_source } if ra_slot.size > 0 => {
                IrStackSlot::new_dynamic_with_unit(size_source, ra_slot.size, ra_slot.align)
            }
            StackSlotAllocationKind::RuntimeSized { size_source } => {
                IrStackSlot::new_dynamic(size_source, ra_slot.align)
            }
        };
        ir_func.stack_slots[slot_id.0 as usize] = slot;
    }
}

fn scratch_pool_for_class(class: RegClass) -> Result<[PReg; 2], PipelineError> {
    match class {
        RegClass::Gpr64 => Ok([X16, X17]),
        RegClass::Gpr32 | RegClass::System => Ok([W16, W17]),
        RegClass::Fpr128 => Ok([V16, V17]),
        RegClass::Fpr64 => Ok([D16, D17]),
        RegClass::Fpr32 => Ok([S16, S17]),
        RegClass::Fpr16 => Ok([H16, H17]),
        other => Err(PipelineError::RegAlloc(format!(
            "AArch64 spill materialization does not yet support scratch class {other:?}"
        ))),
    }
}

fn operand_physical_regs(inst: &IrMachInst) -> Vec<PReg> {
    inst.operands
        .iter()
        .filter_map(|operand| match operand {
            IrOperand::PReg(reg) => Some(*reg),
            IrOperand::MemOp { base, .. } => Some(*base),
            _ => None,
        })
        .collect()
}

fn preg_overlaps_any(reg: PReg, regs: &[PReg]) -> bool {
    regs.iter().any(|&other| regs_overlap(reg, other))
}

fn available_scratch_for_class(
    class: RegClass,
    reserved: &[PReg],
    used: &[PReg],
) -> Result<Option<PReg>, PipelineError> {
    let pool = scratch_pool_for_class(class)?;
    Ok(pool.into_iter().find(|&scratch| {
        !preg_overlaps_any(scratch, reserved) && !preg_overlaps_any(scratch, used)
    }))
}

fn scratch_slot_index(preg: PReg) -> Option<usize> {
    match preg {
        p if p == X16 || p == W16 || p == V16 || p == D16 || p == S16 || p == H16 => Some(0),
        p if p == X17 || p == W17 || p == V17 || p == D17 || p == S17 || p == H17 => Some(1),
        _ => None,
    }
}

fn pair_value_stride(class: RegClass) -> Option<i64> {
    match class {
        RegClass::Gpr64 | RegClass::Fpr64 => Some(8),
        RegClass::Gpr32 | RegClass::System | RegClass::Fpr32 => Some(4),
        RegClass::Fpr128 => Some(16),
        _ => None,
    }
}

fn pair_value_scratch(class: RegClass, base_scratch: PReg) -> Result<PReg, PipelineError> {
    let pool = scratch_pool_for_class(class)?;
    pool.into_iter()
        .find(|scratch| !regs_overlap(*scratch, base_scratch))
        .ok_or_else(|| {
            PipelineError::RegAlloc(format!(
                "AArch64 spill materialization cannot find non-overlapping {class:?} pair scratch for base {base_scratch:?}"
            ))
        })
}

fn classify_operand_positions(inst: &IrMachInst) -> (Vec<usize>, Vec<usize>) {
    if opcode_has_lse_atomic_operand_roles(inst.opcode)
        || opcode_has_explicit_writeback_operand_roles(inst.opcode)
    {
        return (
            aarch64_def_operand_positions(inst.opcode, inst.operands.len()),
            aarch64_use_operand_positions(inst.opcode, inst.operands.len()),
        );
    }

    if opcode_uses_all_operands_for_regalloc(inst.opcode, inst.flags) || inst.operands.is_empty() {
        (Vec::new(), (0..inst.operands.len()).collect())
    } else {
        (
            aarch64_def_operand_positions(inst.opcode, inst.operands.len()),
            aarch64_use_operand_positions(inst.opcode, inst.operands.len()),
        )
    }
}

fn opcode_has_lse_atomic_operand_roles(opcode: IrOpcode) -> bool {
    is_lse_rmw(opcode) || is_lse_cas(opcode)
}

fn opcode_has_explicit_writeback_operand_roles(opcode: IrOpcode) -> bool {
    matches!(
        opcode,
        IrOpcode::NeonLd1Post
            | IrOpcode::NeonLdpQPost
            | IrOpcode::NeonSt1Post
            | IrOpcode::NeonStpQPost
            | IrOpcode::LdrPreIndex
            | IrOpcode::StrPreIndex
            | IrOpcode::LdrPostIndex
            | IrOpcode::StrPostIndex
            | IrOpcode::LdpPostIndex
            | IrOpcode::StpPreIndex
    )
}

fn opcode_uses_all_operands_for_regalloc(
    opcode: IrOpcode,
    flags: trust_cg_ir::inst::InstFlags,
) -> bool {
    if opcode_has_lse_atomic_operand_roles(opcode)
        || opcode_has_explicit_writeback_operand_roles(opcode)
    {
        return false;
    }

    let is_store = flags.contains(trust_cg_ir::inst::InstFlags::WRITES_MEMORY);
    let is_branch = flags.contains(trust_cg_ir::inst::InstFlags::IS_BRANCH);
    let is_return = flags.contains(trust_cg_ir::inst::InstFlags::IS_RETURN);
    let is_call = flags.contains(trust_cg_ir::inst::InstFlags::IS_CALL);
    let is_cmp = matches!(opcode, IrOpcode::CmpRR | IrOpcode::CmpRI | IrOpcode::Fcmp);

    is_store || is_branch || is_return || is_call || is_cmp
}

fn make_spill_load(
    scratch: PReg,
    slot: StackSlotId,
    source_loc: Option<trust_cg_ir::inst::SourceLoc>,
) -> IrMachInst {
    let mut load = IrMachInst::new(
        IrOpcode::LdrRI,
        vec![IrOperand::PReg(scratch), IrOperand::StackSlot(slot)],
    );
    load.source_loc = source_loc;
    load
}

fn make_spill_store(
    scratch: PReg,
    slot: StackSlotId,
    source_loc: Option<trust_cg_ir::inst::SourceLoc>,
) -> IrMachInst {
    let mut store = IrMachInst::new(
        IrOpcode::StrRI,
        vec![IrOperand::PReg(scratch), IrOperand::StackSlot(slot)],
    );
    store.source_loc = source_loc;
    store
}

fn register_offset_index_scratch(index_class: RegClass) -> Result<(PReg, PReg), PipelineError> {
    match index_class {
        RegClass::Gpr64 => Ok((X17, X17)),
        RegClass::Gpr32 | RegClass::System => Ok((W17, X17)),
        other => Err(PipelineError::RegAlloc(format!(
            "AArch64 spill materialization does not yet support register-offset index class {other:?}"
        ))),
    }
}

/// log2 of the memory access size for a register-offset load/store whose
/// transfer register (operand 0) has class `access_class`. This is the shift
/// amount the hardware applies when the register-offset S (scale-present) bit
/// is set, and it must equal what the non-spill `LdrRO`/`StrRO` encoder derives
/// from the same operand-0 class (`sf_from_operand` / `fp_size_from_inst` in
/// aarch64/encode.rs): 8-byte access -> 3, 4-byte -> 2, 16-byte -> 4, 2-byte
/// -> 1. Returns `None` (caller fails closed) for classes with no scaled
/// register-offset encoding.
fn register_offset_scale_log2(access_class: RegClass) -> Option<u32> {
    match access_class {
        // 8-byte accesses (encoder size = Double).
        RegClass::Gpr64 | RegClass::Fpr64 | RegClass::System => Some(3),
        // 4-byte accesses (encoder size = Word).
        RegClass::Gpr32 | RegClass::Fpr32 => Some(2),
        // 16-byte / 2-byte FP accesses.
        RegClass::Fpr128 => Some(4),
        RegClass::Fpr16 => Some(1),
        // Fpr8 has no register-offset encoding path here; fail closed.
        RegClass::Fpr8 => None,
    }
}

fn spilled_vreg_at(
    inst: &IrMachInst,
    pos: usize,
    spill_slots: &HashMap<VReg, StackSlotId>,
) -> Option<(VReg, StackSlotId)> {
    let Some(IrOperand::VReg(vreg)) = inst.operands.get(pos) else {
        return None;
    };
    spill_slot_for_vreg(*vreg, spill_slots).map(|slot| (*vreg, slot))
}

fn materialize_spilled_register_offset_mem(
    ir_func: &mut IrMachFunction,
    inst_id: InstId,
    inst_snapshot: &IrMachInst,
    use_spill_slots: &HashMap<VReg, StackSlotId>,
    def_spill_slots: &HashMap<VReg, StackSlotId>,
    new_block_insts: &mut Vec<InstId>,
    debug_info: &mut SpillMaterializationDebugInfo,
) -> Result<bool, PipelineError> {
    let is_store = inst_snapshot.opcode == IrOpcode::StrRO;
    // Loads include the narrow register-offset siblings (LDRB/LDRH) the
    // ext_addr fold emits. Their access WIDTH is fixed by the opcode (1/2
    // bytes), NOT the transfer class — so both the scale derivation and the
    // decomposed RI opcode below are opcode-driven for the narrow forms.
    let is_load = matches!(
        inst_snapshot.opcode,
        IrOpcode::LdrRO | IrOpcode::LdrbRO | IrOpcode::LdrhRO
    );
    if !is_store && !is_load {
        return Ok(false);
    }

    if inst_snapshot.operands.len() < 3 {
        return Ok(false);
    }

    let Some((base_vreg, base_slot)) = spilled_vreg_at(inst_snapshot, 1, use_spill_slots) else {
        return Ok(false);
    };
    let Some((index_vreg, index_slot)) = spilled_vreg_at(inst_snapshot, 2, use_spill_slots) else {
        return Ok(false);
    };

    let transfer_pos = 0;
    let transfer_spill_slots = if is_store {
        use_spill_slots
    } else {
        def_spill_slots
    };
    let Some((transfer_vreg, transfer_slot)) =
        spilled_vreg_at(inst_snapshot, transfer_pos, transfer_spill_slots)
    else {
        return Ok(false);
    };

    if base_vreg.class != RegClass::Gpr64 {
        return Err(PipelineError::RegAlloc(format!(
            "AArch64 spill materialization for {:?} requires spilled base operand to be Gpr64, got {:?}",
            inst_snapshot.opcode, base_vreg.class
        )));
    }

    // Decode the register-offset addressing mode from operand[3]. Contract
    // (mirrors the LdrRO/StrRO encoder in aarch64/encode.rs and the ext_addr
    // emitter in trust-cg-opt): operand[3] is a packed immediate
    // `(option << 1) | S`, where `option` selects how the index register is
    // extended before being added to the base
    //   UXTW = 0b010, LSL/UXTX = 0b011, SXTW = 0b110, SXTX = 0b111
    // and `S` (scale-present) means the extended index is shifted left by
    // log2(access_size) — the access size being the width of the transfer
    // register (operand 0). An absent operand[3] is the default LSL/UXTX with
    // S=0 (i.e. `addr = base + index`).
    let (ro_option, ro_shifted) = match inst_snapshot.operands.get(3) {
        None => (0b011u32, false),
        Some(IrOperand::Imm(packed)) => {
            let packed = *packed as u32;
            ((packed >> 1) & 0b111, (packed & 1) != 0)
        }
        Some(other) => {
            return Err(PipelineError::RegAlloc(format!(
                "AArch64 spill materialization for {:?} expected a packed Imm addressing operand at [3], got {other:?}",
                inst_snapshot.opcode
            )));
        }
    };

    // Fail closed on any option we do not implement with full confidence.
    // These four are the only encodings the register-offset lowering produces.
    if !matches!(ro_option, 0b010 | 0b011 | 0b110 | 0b111) {
        return Err(PipelineError::RegAlloc(format!(
            "AArch64 spill materialization for {:?} does not support register-offset extend option 0b{ro_option:03b}",
            inst_snapshot.opcode
        )));
    }

    // The scale amount is log2(access_size). For the narrow forms the access
    // size is fixed by the opcode (LDRB=1 -> 0, LDRH=2 -> 1); for the full-width
    // forms it is derived from the transfer register class exactly as the
    // encoder derives the size field. This MUST match the encoder / ext_addr
    // emitter, otherwise the reconstructed effective address would diverge.
    let ro_scale: u32 = if ro_shifted {
        let log2 = match inst_snapshot.opcode {
            IrOpcode::LdrbRO => Some(0),
            IrOpcode::LdrhRO => Some(1),
            _ => register_offset_scale_log2(transfer_vreg.class),
        };
        log2.ok_or_else(|| {
            PipelineError::RegAlloc(format!(
                "AArch64 spill materialization for {:?} cannot derive a register-offset scale for transfer class {:?}",
                inst_snapshot.opcode, transfer_vreg.class
            ))
        })?
    } else {
        0
    };

    let source_loc = inst_snapshot.source_loc;
    let base_scratch = X16;
    let (index_load_scratch, index_addr_scratch) = register_offset_index_scratch(index_vreg.class)?;

    let load_base_id = ir_func.push_inst(make_spill_load(base_scratch, base_slot, source_loc));
    new_block_insts.push(load_base_id);

    let load_index_id =
        ir_func.push_inst(make_spill_load(index_load_scratch, index_slot, source_loc));
    new_block_insts.push(load_index_id);

    // Apply the index extend, then the scale, in the index scratch register so
    // the effective address computed below (base + index_addr_scratch) matches
    // the non-spill register-offset semantics exactly:
    //   addr = base + (extend(index) << scale)
    // The extend/shift operate on `index_addr_scratch` (the 64-bit X view of
    // the scratch the index was loaded into), so this is correct whether the
    // index arrived as a 32-bit (W17) or 64-bit (X17) load.
    match ro_option {
        // UXTW: zero-extend the low 32 bits of the index into 64 bits.
        0b010 => {
            let mut ext = IrMachInst::new(
                IrOpcode::Uxtw,
                vec![
                    IrOperand::PReg(index_addr_scratch),
                    IrOperand::PReg(index_addr_scratch),
                ],
            );
            ext.source_loc = source_loc;
            let ext_id = ir_func.push_inst(ext);
            new_block_insts.push(ext_id);
        }
        // SXTW: sign-extend the low 32 bits of the index into 64 bits.
        0b110 => {
            let mut ext = IrMachInst::new(
                IrOpcode::Sxtw,
                vec![
                    IrOperand::PReg(index_addr_scratch),
                    IrOperand::PReg(index_addr_scratch),
                ],
            );
            ext.source_loc = source_loc;
            let ext_id = ir_func.push_inst(ext);
            new_block_insts.push(ext_id);
        }
        // LSL/UXTX (0b011) and SXTX (0b111): the full 64-bit index is used
        // directly; the extend is the identity on a 64-bit value.
        _ => {}
    }

    if ro_scale > 0 {
        let mut shift = IrMachInst::new(
            IrOpcode::LslRI,
            vec![
                IrOperand::PReg(index_addr_scratch),
                IrOperand::PReg(index_addr_scratch),
                IrOperand::Imm(ro_scale as i64),
            ],
        );
        shift.source_loc = source_loc;
        let shift_id = ir_func.push_inst(shift);
        new_block_insts.push(shift_id);
    }

    if is_store {
        let addr_scratch = X17;
        let add_addr_id = ir_func.push_inst(IrMachInst::new(
            IrOpcode::AddRR,
            vec![
                IrOperand::PReg(addr_scratch),
                IrOperand::PReg(base_scratch),
                IrOperand::PReg(index_addr_scratch),
            ],
        ));
        new_block_insts.push(add_addr_id);

        let value_scratch = scratch_pool_for_class(transfer_vreg.class)?[0];
        let load_value_id =
            ir_func.push_inst(make_spill_load(value_scratch, transfer_slot, source_loc));
        new_block_insts.push(load_value_id);

        let inst = &mut ir_func.insts[inst_id.0 as usize];
        inst.opcode = IrOpcode::StrRI;
        inst.flags = IrOpcode::StrRI.default_flags();
        inst.operands = vec![
            IrOperand::PReg(value_scratch),
            IrOperand::PReg(addr_scratch),
            IrOperand::Imm(0),
        ];
    } else {
        let addr_scratch = X16;
        let add_addr_id = ir_func.push_inst(IrMachInst::new(
            IrOpcode::AddRR,
            vec![
                IrOperand::PReg(addr_scratch),
                IrOperand::PReg(base_scratch),
                IrOperand::PReg(index_addr_scratch),
            ],
        ));
        new_block_insts.push(add_addr_id);

        let dst_scratch = scratch_pool_for_class(transfer_vreg.class)?[1];
        // Preserve the ACCESS WIDTH when decomposing to the immediate-offset
        // form: a narrow register-offset load must become the matching narrow
        // immediate load (LDRB/LDRH), never the full-width LDR — otherwise it
        // would read 4 bytes instead of 1/2.
        let ri_opcode = match inst_snapshot.opcode {
            IrOpcode::LdrbRO => IrOpcode::LdrbRI,
            IrOpcode::LdrhRO => IrOpcode::LdrhRI,
            _ => IrOpcode::LdrRI,
        };
        let inst = &mut ir_func.insts[inst_id.0 as usize];
        inst.opcode = ri_opcode;
        inst.flags = ri_opcode.default_flags();
        inst.operands = vec![
            IrOperand::PReg(dst_scratch),
            IrOperand::PReg(addr_scratch),
            IrOperand::Imm(0),
        ];

        let store_dst_id =
            ir_func.push_inst(make_spill_store(dst_scratch, transfer_slot, source_loc));
        new_block_insts.push(inst_id);
        new_block_insts.push(store_dst_id);
        debug_info.record_store(transfer_vreg, transfer_slot, store_dst_id);
        return Ok(true);
    }

    new_block_insts.push(inst_id);
    Ok(true)
}

fn materialize_spilled_store_pair(
    ir_func: &mut IrMachFunction,
    inst_snapshot: &IrMachInst,
    use_spill_slots: &HashMap<VReg, StackSlotId>,
    new_block_insts: &mut Vec<InstId>,
) -> Result<bool, PipelineError> {
    if inst_snapshot.opcode != IrOpcode::StpRI || inst_snapshot.operands.len() < 4 {
        return Ok(false);
    }

    let Some((value0_vreg, value0_slot)) = spilled_vreg_at(inst_snapshot, 0, use_spill_slots)
    else {
        return Ok(false);
    };
    let Some((value1_vreg, value1_slot)) = spilled_vreg_at(inst_snapshot, 1, use_spill_slots)
    else {
        return Ok(false);
    };
    let Some((base_vreg, base_slot)) = spilled_vreg_at(inst_snapshot, 2, use_spill_slots) else {
        return Ok(false);
    };

    if value0_vreg == value1_vreg || value0_vreg == base_vreg || value1_vreg == base_vreg {
        return Ok(false);
    }

    if value0_vreg.class != value1_vreg.class {
        return Err(PipelineError::RegAlloc(format!(
            "AArch64 spill materialization for StpRI requires matching spilled value classes, got {:?} and {:?}",
            value0_vreg.class, value1_vreg.class
        )));
    }
    if base_vreg.class != RegClass::Gpr64 {
        return Err(PipelineError::RegAlloc(format!(
            "AArch64 spill materialization for StpRI requires a spilled Gpr64 base, got {:?}",
            base_vreg.class
        )));
    }
    let value_stride = pair_value_stride(value0_vreg.class).ok_or_else(|| {
        PipelineError::RegAlloc(format!(
            "AArch64 spill materialization for StpRI does not support spilled value class {:?}",
            value0_vreg.class
        ))
    })?;
    let base_scratch = X17;
    let value_scratch = pair_value_scratch(value0_vreg.class, base_scratch)?;

    let offset = match inst_snapshot.operands[3] {
        IrOperand::Imm(offset) => offset,
        ref operand => {
            return Err(PipelineError::RegAlloc(format!(
                "AArch64 spill materialization for StpRI expected immediate pair offset, got {operand:?}"
            )));
        }
    };

    let source_loc = inst_snapshot.source_loc;
    let load_base_id = ir_func.push_inst(make_spill_load(base_scratch, base_slot, source_loc));
    new_block_insts.push(load_base_id);

    if offset != 0 {
        let (opcode, magnitude) = if offset > 0 {
            (IrOpcode::AddRI, offset)
        } else {
            (IrOpcode::SubRI, -offset)
        };
        let adjust_id = push_inst_with_source(
            ir_func,
            opcode,
            vec![
                IrOperand::PReg(base_scratch),
                IrOperand::PReg(base_scratch),
                IrOperand::Imm(magnitude),
            ],
            source_loc,
        );
        new_block_insts.push(adjust_id);
    }

    let load_value0_id = ir_func.push_inst(make_spill_load(value_scratch, value0_slot, source_loc));
    new_block_insts.push(load_value0_id);
    let store_value0_id = push_inst_with_source(
        ir_func,
        IrOpcode::StrRI,
        vec![
            IrOperand::PReg(value_scratch),
            IrOperand::PReg(base_scratch),
            IrOperand::Imm(0),
        ],
        source_loc,
    );
    new_block_insts.push(store_value0_id);

    let load_value1_id = ir_func.push_inst(make_spill_load(value_scratch, value1_slot, source_loc));
    new_block_insts.push(load_value1_id);
    let store_value1_id = push_inst_with_source(
        ir_func,
        IrOpcode::StrRI,
        vec![
            IrOperand::PReg(value_scratch),
            IrOperand::PReg(base_scratch),
            IrOperand::Imm(value_stride),
        ],
        source_loc,
    );
    new_block_insts.push(store_value1_id);

    Ok(true)
}

fn materialize_spilled_load_pair(
    ir_func: &mut IrMachFunction,
    inst_snapshot: &IrMachInst,
    use_spill_slots: &HashMap<VReg, StackSlotId>,
    def_spill_slots: &HashMap<VReg, StackSlotId>,
    new_block_insts: &mut Vec<InstId>,
    debug_info: &mut SpillMaterializationDebugInfo,
) -> Result<bool, PipelineError> {
    if inst_snapshot.opcode != IrOpcode::LdpRI || inst_snapshot.operands.len() < 4 {
        return Ok(false);
    }

    let Some((dst0_vreg, dst0_slot)) = spilled_vreg_at(inst_snapshot, 0, def_spill_slots) else {
        return Ok(false);
    };
    let Some((dst1_vreg, dst1_slot)) = spilled_vreg_at(inst_snapshot, 1, def_spill_slots) else {
        return Ok(false);
    };

    if dst0_vreg == dst1_vreg {
        return Err(PipelineError::RegAlloc(format!(
            "AArch64 spill materialization for LdpRI requires distinct spilled defs in {:?}",
            inst_snapshot
        )));
    }
    if dst0_vreg.class != dst1_vreg.class {
        return Err(PipelineError::RegAlloc(format!(
            "AArch64 spill materialization for LdpRI requires matching spilled def classes, got {:?} and {:?}",
            dst0_vreg.class, dst1_vreg.class
        )));
    }
    let value_stride = pair_value_stride(dst0_vreg.class).ok_or_else(|| {
        PipelineError::RegAlloc(format!(
            "AArch64 spill materialization for LdpRI does not support spilled def class {:?}",
            dst0_vreg.class
        ))
    })?;
    let offset = match inst_snapshot.operands[3] {
        IrOperand::Imm(offset) => offset,
        ref operand => {
            return Err(PipelineError::RegAlloc(format!(
                "AArch64 spill materialization for LdpRI expected immediate pair offset, got {operand:?}"
            )));
        }
    };

    // PHYSICAL-BASE PAIR (pr28982b loop-carried-pointer miscompile). When the
    // pair BASE is an allocated (non-spilled) register it stays live and needs
    // no reload, yet BOTH paired destinations are spilled. The generic multi-def
    // materialization path keeps both loaded values SIMULTANEOUSLY in the two
    // scratch registers (X16 AND X17) across their two spill stores; the
    // frame-index eliminator then materializes each far spill-slot address in
    // the OTHER scratch, overwriting the still-live second value. (In pr28982b
    // the odd loop-carried pointers result7,9,..,19 were stored as a stack
    // address instead of `input+k`, so every `*ptr` load read 0.) Split the
    // LdpRI into two INDEPENDENT single-value load + spill-store sequences that
    // hold each value in scratch slot 0 only, leaving scratch slot 1 FREE for
    // the eliminator's large-offset address materialization — so no live value
    // is ever clobbered.
    if let IrOperand::PReg(base_preg) = inst_snapshot.operands[2] {
        if preg_class(base_preg) != RegClass::Gpr64 {
            return Ok(false);
        }
        let value_scratch = scratch_pool_for_class(dst0_vreg.class)?[0];
        // The paired-def clobber only arises when the VALUE scratch registers
        // alias the GPR address scratch (X16/X17) that the frame-index
        // eliminator borrows to materialize a far spill-slot offset — i.e. the
        // GPR classes (value scratch X16/W16 & X17/W17). FP pairs load into
        // V/D/S/H 16/17, which never alias the GPR address scratch, so their
        // generic single-`ldp` materialization is already sound (and one fewer
        // instruction); leave it on the generic path untouched.
        if !regs_overlap(value_scratch, X16) && !regs_overlap(value_scratch, X17) {
            return Ok(false);
        }
        if regs_overlap(base_preg, value_scratch) {
            return Err(PipelineError::RegAlloc(format!(
                "AArch64 spill materialization for LdpRI: physical base {base_preg:?} aliases value scratch {value_scratch:?} in {inst_snapshot:?}"
            )));
        }
        let source_loc = inst_snapshot.source_loc;
        for (element_off, dst_vreg, dst_slot) in [
            (offset, dst0_vreg, dst0_slot),
            (offset + value_stride, dst1_vreg, dst1_slot),
        ] {
            // Load this element into the value scratch. A directly-encodable
            // element offset needs one LDR [base, #off]; otherwise compute
            // base+off into the scratch first (|off| is bounded by the pair's
            // imm7 reach plus one stride, so it always fits an ADD/SUB #imm12).
            if (-256..=4095).contains(&element_off) {
                let load_id = push_inst_with_source(
                    ir_func,
                    IrOpcode::LdrRI,
                    vec![
                        IrOperand::PReg(value_scratch),
                        IrOperand::PReg(base_preg),
                        IrOperand::Imm(element_off),
                    ],
                    source_loc,
                );
                new_block_insts.push(load_id);
            } else {
                let (opcode, magnitude) = if element_off >= 0 {
                    (IrOpcode::AddRI, element_off)
                } else {
                    (IrOpcode::SubRI, -element_off)
                };
                let addr_id = push_inst_with_source(
                    ir_func,
                    opcode,
                    vec![
                        IrOperand::PReg(value_scratch),
                        IrOperand::PReg(base_preg),
                        IrOperand::Imm(magnitude),
                    ],
                    source_loc,
                );
                new_block_insts.push(addr_id);
                let load_id = push_inst_with_source(
                    ir_func,
                    IrOpcode::LdrRI,
                    vec![
                        IrOperand::PReg(value_scratch),
                        IrOperand::PReg(value_scratch),
                        IrOperand::Imm(0),
                    ],
                    source_loc,
                );
                new_block_insts.push(load_id);
            }
            let store_id = ir_func.push_inst(make_spill_store(value_scratch, dst_slot, source_loc));
            new_block_insts.push(store_id);
            debug_info.record_store(dst_vreg, dst_slot, store_id);
        }
        return Ok(true);
    }

    // SPILLED-BASE PAIR: the base is itself spilled. Reload it around each
    // element so the store's far-offset address materialization (which clobbers
    // the base scratch) never loses a value.
    let Some((base_vreg, base_slot)) = spilled_vreg_at(inst_snapshot, 2, use_spill_slots) else {
        return Ok(false);
    };
    if dst0_vreg == base_vreg || dst1_vreg == base_vreg {
        return Err(PipelineError::RegAlloc(format!(
            "AArch64 spill materialization for LdpRI requires distinct spilled defs/base in {:?}",
            inst_snapshot
        )));
    }
    if base_vreg.class != RegClass::Gpr64 {
        return Err(PipelineError::RegAlloc(format!(
            "AArch64 spill materialization for LdpRI requires a spilled Gpr64 base, got {:?}",
            base_vreg.class
        )));
    }
    let base_scratch = X16;
    let dst_scratch = pair_value_scratch(dst0_vreg.class, base_scratch)?;

    let source_loc = inst_snapshot.source_loc;
    let load_base_id = ir_func.push_inst(make_spill_load(base_scratch, base_slot, source_loc));
    new_block_insts.push(load_base_id);

    if offset != 0 {
        let (opcode, magnitude) = if offset > 0 {
            (IrOpcode::AddRI, offset)
        } else {
            (IrOpcode::SubRI, -offset)
        };
        let adjust_id = push_inst_with_source(
            ir_func,
            opcode,
            vec![
                IrOperand::PReg(base_scratch),
                IrOperand::PReg(base_scratch),
                IrOperand::Imm(magnitude),
            ],
            source_loc,
        );
        new_block_insts.push(adjust_id);
    }

    let load_dst0_id = push_inst_with_source(
        ir_func,
        IrOpcode::LdrRI,
        vec![
            IrOperand::PReg(dst_scratch),
            IrOperand::PReg(base_scratch),
            IrOperand::Imm(0),
        ],
        source_loc,
    );
    new_block_insts.push(load_dst0_id);
    let store_dst0_id = ir_func.push_inst(make_spill_store(dst_scratch, dst0_slot, source_loc));
    new_block_insts.push(store_dst0_id);
    debug_info.record_store(dst0_vreg, dst0_slot, store_dst0_id);

    let reload_base_id = ir_func.push_inst(make_spill_load(base_scratch, base_slot, source_loc));
    new_block_insts.push(reload_base_id);
    if offset != 0 {
        let (opcode, magnitude) = if offset > 0 {
            (IrOpcode::AddRI, offset)
        } else {
            (IrOpcode::SubRI, -offset)
        };
        let readjust_id = push_inst_with_source(
            ir_func,
            opcode,
            vec![
                IrOperand::PReg(base_scratch),
                IrOperand::PReg(base_scratch),
                IrOperand::Imm(magnitude),
            ],
            source_loc,
        );
        new_block_insts.push(readjust_id);
    }

    let load_dst1_id = push_inst_with_source(
        ir_func,
        IrOpcode::LdrRI,
        vec![
            IrOperand::PReg(dst_scratch),
            IrOperand::PReg(base_scratch),
            IrOperand::Imm(value_stride),
        ],
        source_loc,
    );
    new_block_insts.push(load_dst1_id);
    let store_dst1_id = ir_func.push_inst(make_spill_store(dst_scratch, dst1_slot, source_loc));
    new_block_insts.push(store_dst1_id);
    debug_info.record_store(dst1_vreg, dst1_slot, store_dst1_id);

    Ok(true)
}

fn push_inst_with_source(
    ir_func: &mut IrMachFunction,
    opcode: IrOpcode,
    operands: Vec<IrOperand>,
    source_loc: Option<trust_cg_ir::inst::SourceLoc>,
) -> InstId {
    let mut inst = IrMachInst::new(opcode, operands);
    inst.source_loc = source_loc;
    ir_func.push_inst(inst)
}

fn project_scratch_for_result_width(
    scratch: PReg,
    result_class: RegClass,
) -> Result<PReg, PipelineError> {
    project_allocated_preg(scratch, result_class).ok_or_else(|| {
        PipelineError::RegAlloc(format!(
            "AArch64 spill materialization cannot project scratch {scratch:?} to {result_class:?}"
        ))
    })
}

fn materialize_spilled_multiply_accumulate(
    ir_func: &mut IrMachFunction,
    inst_id: InstId,
    inst_snapshot: &IrMachInst,
    use_spill_slots: &HashMap<VReg, StackSlotId>,
    def_spill_slots: &HashMap<VReg, StackSlotId>,
    new_block_insts: &mut Vec<InstId>,
    debug_info: &mut SpillMaterializationDebugInfo,
) -> Result<bool, PipelineError> {
    let combine_opcode = match inst_snapshot.opcode {
        IrOpcode::Madd => IrOpcode::AddRR,
        IrOpcode::Msub => IrOpcode::SubRR,
        _ => return Ok(false),
    };

    if inst_snapshot.operands.len() < 4 {
        return Ok(false);
    }

    let Some((lhs_vreg, lhs_slot)) = spilled_vreg_at(inst_snapshot, 1, use_spill_slots) else {
        return Ok(false);
    };
    let Some((rhs_vreg, rhs_slot)) = spilled_vreg_at(inst_snapshot, 2, use_spill_slots) else {
        return Ok(false);
    };
    let Some((acc_vreg, acc_slot)) = spilled_vreg_at(inst_snapshot, 3, use_spill_slots) else {
        return Ok(false);
    };

    let mut dst_spill = None;
    let (dst, result_class) = match inst_snapshot.operands[0] {
        IrOperand::PReg(preg) => (preg, preg_class(preg)),
        IrOperand::VReg(vreg) => {
            let Some(slot) = spill_slot_for_vreg(vreg, def_spill_slots) else {
                return Ok(false);
            };
            dst_spill = Some((vreg, slot));
            let [dst_scratch, _] = scratch_pool_for_class(vreg.class)?;
            (dst_scratch, vreg.class)
        }
        ref operand => {
            return Err(PipelineError::RegAlloc(format!(
                "AArch64 spill materialization for {:?} expected register destination, got {:?}",
                inst_snapshot.opcode, operand
            )));
        }
    };

    if !matches!(result_class, RegClass::Gpr32 | RegClass::Gpr64) {
        return Err(PipelineError::RegAlloc(format!(
            "AArch64 spill materialization for {:?} requires GPR32/GPR64 result, got {:?}",
            inst_snapshot.opcode, result_class
        )));
    }

    let lhs_load_scratch = scratch_pool_for_class(lhs_vreg.class)?[0];
    let rhs_load_scratch = scratch_pool_for_class(rhs_vreg.class)?[1];
    let acc_load_scratch = scratch_pool_for_class(acc_vreg.class)?
        .into_iter()
        .rev()
        .find(|&scratch| {
            project_scratch_for_result_width(scratch, result_class)
                .is_ok_and(|projected| !regs_overlap(projected, dst))
        })
        .ok_or_else(|| {
            PipelineError::RegAlloc(format!(
                "AArch64 spill materialization for {:?} cannot find accumulator scratch avoiding destination {:?}",
                inst_snapshot.opcode, dst
            ))
        })?;
    let lhs_mul_scratch = project_scratch_for_result_width(lhs_load_scratch, result_class)?;
    let rhs_mul_scratch = project_scratch_for_result_width(rhs_load_scratch, result_class)?;
    let acc_combine_scratch = project_scratch_for_result_width(acc_load_scratch, result_class)?;

    let source_loc = inst_snapshot.source_loc;
    let load_lhs_id = ir_func.push_inst(make_spill_load(lhs_load_scratch, lhs_slot, source_loc));
    new_block_insts.push(load_lhs_id);

    let load_rhs_id = ir_func.push_inst(make_spill_load(rhs_load_scratch, rhs_slot, source_loc));
    new_block_insts.push(load_rhs_id);

    {
        let inst = &mut ir_func.insts[inst_id.0 as usize];
        inst.opcode = IrOpcode::MulRR;
        inst.flags = IrOpcode::MulRR.default_flags();
        inst.operands = vec![
            IrOperand::PReg(dst),
            IrOperand::PReg(lhs_mul_scratch),
            IrOperand::PReg(rhs_mul_scratch),
        ];
    }
    new_block_insts.push(inst_id);

    let load_acc_id = ir_func.push_inst(make_spill_load(acc_load_scratch, acc_slot, source_loc));
    new_block_insts.push(load_acc_id);

    let combine_operands = if combine_opcode == IrOpcode::AddRR {
        vec![
            IrOperand::PReg(dst),
            IrOperand::PReg(dst),
            IrOperand::PReg(acc_combine_scratch),
        ]
    } else {
        vec![
            IrOperand::PReg(dst),
            IrOperand::PReg(acc_combine_scratch),
            IrOperand::PReg(dst),
        ]
    };
    let combine_id = push_inst_with_source(ir_func, combine_opcode, combine_operands, source_loc);
    new_block_insts.push(combine_id);

    if let Some((vreg, slot)) = dst_spill {
        let store_id = ir_func.push_inst(make_spill_store(dst, slot, source_loc));
        new_block_insts.push(store_id);
        debug_info.record_store(vreg, slot, store_id);
    }

    Ok(true)
}

/// Materialize a scalar fused multiply-add (`FmaddRR`, `Fd = Fa + Fn*Fm`) whose
/// THREE source operands are all spilled to distinct slots.
///
/// The generic spill path draws reload scratch from the 2-register pool
/// (`D16`/`D17` and their width aliases, see [`scratch_pool_for_class`]). Three
/// DISTINCT spilled sources need three registers live simultaneously, and a
/// single-rounding FMADD cannot be split into `FMUL`+`FADD` without changing the
/// result (double rounding — a bit-level miscompile). So the generic path runs
/// out of scratch and fails. This handler recovers the third register from the
/// FMADD DESTINATION.
///
/// SOUNDNESS — the dest-reuse argument:
///   * `FmaddRR` writes `Rd` as a PURE def: it reads only `Rn`/`Rm`/`Ra` (the
///     addend is the separate operand `Ra`, NOT the prior `Rd`). It is
///     deliberately absent from `has_tied_def_use` — unlike the accumulating
///     `NeonFmla`/`NeonFmls`. So loading a source into `Rd` before the FMADD
///     destroys nothing the instruction still needs.
///   * The scratch registers `D16`/`D17` (and their `V`/`S`/`H` aliases) are
///     RESERVED — never present in `aarch64_allocatable_regs()`. Hence the
///     allocated destination preg can never BE a scratch register: the three
///     targets {scratch_n, scratch_m, dst} are pairwise distinct, so the three
///     reloads cannot clobber one another regardless of order. (A defensive
///     guard below fails closed should that reservation invariant ever change.)
///   * Engages ONLY when all three sources are spilled AND are three DISTINCT
///     vregs. That means every source operand is being reloaded — there is no
///     non-spilled source register that `dst` could alias and corrupt, so the
///     classic dest-reuse precondition ("dst read by no surviving source") holds
///     vacuously. With <=2 distinct spilled sources the generic 2-scratch path
///     already succeeds, so we defer to keep byte-identical output.
///
/// The rewrite (Fpr64 shown; class-general):
/// ```text
///   ldr   D16, [slot(Rn)]
///   ldr   D17, [slot(Rm)]
///   ldr   Rd,  [slot(Ra)]        ; Rd's old value is dead (pure def)
///   fmadd Rd,  D16, D17, Rd      ; Rd = Rd(Ra) + D16(Rn)*D17(Rm)
/// ```
///
/// A spilled-VReg destination (no physical home to borrow) is left to the
/// generic path, which fail-closes with the documented "ran out of scratch"
/// error: three distinct spilled sources plus a spilled def genuinely exceed the
/// scratch budget for a fused, un-splittable op.
fn materialize_spilled_fused_multiply_add(
    ir_func: &mut IrMachFunction,
    inst_id: InstId,
    inst_snapshot: &IrMachInst,
    use_spill_slots: &HashMap<VReg, StackSlotId>,
    new_block_insts: &mut Vec<InstId>,
) -> Result<bool, PipelineError> {
    if inst_snapshot.opcode != IrOpcode::FmaddRR {
        return Ok(false);
    }
    if inst_snapshot.operands.len() != 4 {
        return Ok(false);
    }

    // Destination must be a physical register we can borrow as the third
    // reload target. A spilled-VReg destination has no physical home to reuse.
    let IrOperand::PReg(dst) = inst_snapshot.operands[0] else {
        return Ok(false);
    };

    // All three sources (Rn, Rm, Ra at operand positions 1, 2, 3) must be
    // spilled — otherwise the generic 2-scratch path already suffices.
    let Some((n_vreg, n_slot)) = spilled_vreg_at(inst_snapshot, 1, use_spill_slots) else {
        return Ok(false);
    };
    let Some((m_vreg, m_slot)) = spilled_vreg_at(inst_snapshot, 2, use_spill_slots) else {
        return Ok(false);
    };
    let Some((a_vreg, a_slot)) = spilled_vreg_at(inst_snapshot, 3, use_spill_slots) else {
        return Ok(false);
    };

    // Engage ONLY when the pool is genuinely insufficient: three DISTINCT
    // spilled source vregs. A repeated vreg reuses one scratch (the generic
    // path's `assigned` map), leaving <=2 distinct sources it can satisfy — so
    // defer to it and stay byte-identical.
    if n_vreg == m_vreg || n_vreg == a_vreg || m_vreg == a_vreg {
        return Ok(false);
    }

    // FMADD operands share one FP width; the destination shares it too. Fail
    // closed on any class mismatch rather than emit a mixed-width reload.
    let class = n_vreg.class;
    if m_vreg.class != class || a_vreg.class != class {
        return Err(PipelineError::RegAlloc(format!(
            "AArch64 spill materialization for FmaddRR requires matching source classes, got {:?}/{:?}/{:?}",
            n_vreg.class, m_vreg.class, a_vreg.class
        )));
    }
    if preg_class(dst) != class {
        return Err(PipelineError::RegAlloc(format!(
            "AArch64 spill materialization for FmaddRR requires destination class {:?} to match source class {:?}",
            preg_class(dst),
            class
        )));
    }

    let [scratch_n, scratch_m] = scratch_pool_for_class(class)?;

    // Defensive soundness guard: the destination MUST NOT alias either scratch
    // register. This holds by construction (the scratch aliases are reserved out
    // of `aarch64_allocatable_regs()`), but assert it so a future change to the
    // reserved set fails closed instead of silently clobbering a reload.
    if regs_overlap(dst, scratch_n) || regs_overlap(dst, scratch_m) {
        return Err(PipelineError::RegAlloc(format!(
            "AArch64 spill materialization for FmaddRR: destination {dst:?} aliases a reserved scratch register ({scratch_n:?}/{scratch_m:?})"
        )));
    }

    let source_loc = inst_snapshot.source_loc;

    // Reload the two multiplicands into the scratch pool and the addend into the
    // (pure-def, now-dead) destination register. The three targets are pairwise
    // distinct, so load order is immaterial for correctness.
    let load_n = ir_func.push_inst(make_spill_load(scratch_n, n_slot, source_loc));
    new_block_insts.push(load_n);
    let load_m = ir_func.push_inst(make_spill_load(scratch_m, m_slot, source_loc));
    new_block_insts.push(load_m);
    let load_a = ir_func.push_inst(make_spill_load(dst, a_slot, source_loc));
    new_block_insts.push(load_a);

    {
        let inst = &mut ir_func.insts[inst_id.0 as usize];
        inst.operands = vec![
            IrOperand::PReg(dst),
            IrOperand::PReg(scratch_n),
            IrOperand::PReg(scratch_m),
            IrOperand::PReg(dst),
        ];
    }
    new_block_insts.push(inst_id);

    Ok(true)
}

#[cfg(test)]
fn materialize_spilled_operands(
    ir_func: &mut IrMachFunction,
    spills: &[trust_cg_regalloc::SpillInfo],
) -> Result<(), PipelineError> {
    let spill_slots: HashMap<VReg, StackSlotId> = spills
        .iter()
        .map(|spill| (spill.vreg, spill.slot))
        .collect();
    if spill_slots.is_empty() {
        return Ok(());
    }

    let mut sites: HashMap<InstId, SpillMaterializationSite> = HashMap::new();
    for block in &ir_func.blocks {
        for &inst_id in &block.insts {
            let inst = ir_func.inst(inst_id);
            let (def_positions, use_positions) = classify_operand_positions(inst);

            for &pos in &use_positions {
                let Some((vreg, slot)) = spilled_vreg_at(inst, pos, &spill_slots) else {
                    continue;
                };
                sites.entry(inst_id).or_default().uses.insert(vreg, slot);
            }

            for &pos in &def_positions {
                let Some((vreg, slot)) = spilled_vreg_at(inst, pos, &spill_slots) else {
                    continue;
                };
                sites.entry(inst_id).or_default().defs.insert(vreg, slot);
            }
        }
    }

    materialize_spilled_operands_at_sites(ir_func, &sites).map(|_| ())
}

/// True when a spilled-copy materialization site is a provable IDENTITY slot
/// round-trip that can be elided entirely (load + copy + store all dropped).
///
/// The shape: `Copy dst_vreg <- src_vreg` where BOTH operands are spilled and
/// the site binds the use and the def to the SAME stack slot `S` (the
/// coalesced-phi-web self-copy — commonly `dst_vreg == src_vreg`). The generic
/// materialization path would emit
///
/// ```text
///     ldr <scratch>, [S]     ; reload src
///     mov <scratch'>, <scratch>   ; the copy (often scratch' == scratch => nop)
///     str <scratch'>, [S]    ; spill dst
/// ```
///
/// SOUNDNESS (why eliding the whole site preserves semantics):
///  * The allocator's spill contract — validated on the regalloc-form function
///    (incl. the slot-initialization dominance gate) — guarantees `mem[S]`
///    holds `value(src_vreg)` at this program point: that is precisely the
///    contract the use-reload this site would otherwise emit relies on.
///  * The instruction's entire effect is `dst_vreg := src_vreg`, and dst's
///    spill contract is discharged by storing `value(dst_vreg)` to the SAME
///    slot `S`. Since `mem[S] == value(src_vreg) == value(dst_vreg)` already,
///    the store writes back exactly the bytes the load read: memory is
///    unchanged byte-for-byte (the class-equality check pins load width ==
///    store width, so this holds even under spill-slot reuse).
///  * The scratch registers the triple would have used are conjured by this
///    materialization per site and are never live outside it by construction,
///    so no program-visible register changes either.
///
/// FAIL-CLOSED: any deviation from the exact shape (extra site entries, class
/// mismatch, non-VReg operands, unexpected roles) falls through to the generic
/// materialization path unchanged. Kill switch: `TCG_SPILL_IDENT_OFF=1`
/// restores the byte-identical old behavior.
fn identity_spilled_copy_slot(
    inst: &IrMachInst,
    site: &SpillMaterializationSite,
) -> Option<StackSlotId> {
    if inst.opcode != IrOpcode::Copy || inst.operands.len() != 2 {
        return None;
    }
    let (IrOperand::VReg(dst), IrOperand::VReg(src)) = (&inst.operands[0], &inst.operands[1])
    else {
        return None;
    };
    // Same register class => same spill access width (identity is byte-exact).
    if dst.class != src.class {
        return None;
    }
    // Roles must be exactly [Def, Use] (defensive: this is Copy's contract).
    let (def_positions, use_positions) = classify_operand_positions(inst);
    if def_positions != [0] || use_positions != [1] {
        return None;
    }
    // The site must bind exactly this use and this def, to the same slot.
    if site.uses.len() != 1 || site.defs.len() != 1 {
        return None;
    }
    let use_slot = site.uses.get(src)?;
    let def_slot = site.defs.get(dst)?;
    (use_slot == def_slot).then_some(*use_slot)
}

fn spill_ident_elide_disabled() -> bool {
    std::env::var_os("TCG_SPILL_IDENT_OFF").is_some()
}

fn spill_peep_stats_enabled() -> bool {
    std::env::var_os("TCG_SPILL_PEEP_STATS").is_some()
}

fn materialize_spilled_operands_at_sites(
    ir_func: &mut IrMachFunction,
    sites: &HashMap<InstId, SpillMaterializationSite>,
) -> Result<SpillMaterializationDebugInfo, PipelineError> {
    let mut debug_info = SpillMaterializationDebugInfo::default();
    if sites.is_empty() {
        return Ok(debug_info);
    }

    let ident_elide_enabled = !spill_ident_elide_disabled();
    let mut ident_elided = 0u32;
    let num_blocks = ir_func.blocks.len();
    for block_idx in 0..num_blocks {
        let block_insts = std::mem::take(&mut ir_func.blocks[block_idx].insts);
        let mut new_block_insts = Vec::with_capacity(block_insts.len());

        for inst_id in block_insts {
            let Some(site) = sites.get(&inst_id) else {
                new_block_insts.push(inst_id);
                continue;
            };
            if site.is_empty() {
                new_block_insts.push(inst_id);
                continue;
            }

            let inst_snapshot = ir_func.insts[inst_id.0 as usize].clone();
            if spill_materialization_trace_enabled(&ir_func.name) {
                eprintln!(
                    "[trust_cg][spill-materialize] func={} block=bb{} inst=inst{} opcode={:?} operands={:?} uses={:?} defs={:?}",
                    ir_func.name,
                    block_idx,
                    inst_id.0,
                    inst_snapshot.opcode,
                    inst_snapshot.operands,
                    site.uses,
                    site.defs,
                );
            }
            // IDENTITY-SLOT-COPY ELISION: a spilled phi self-copy whose use and
            // def share one slot is a dead `ldr [S]; mov; str [S]` round-trip —
            // drop the whole site (see `identity_spilled_copy_slot` for the
            // soundness argument). Checked before every materialization helper
            // so no load/store for the site is ever created.
            if ident_elide_enabled && identity_spilled_copy_slot(&inst_snapshot, site).is_some() {
                let inst = &mut ir_func.insts[inst_id.0 as usize];
                inst.opcode = IrOpcode::Nop;
                inst.operands.clear();
                // Pseudo Nop: every encoder walk skips it (0 bytes emitted).
                inst.flags = trust_cg_ir::inst::InstFlags::IS_PSEUDO;
                new_block_insts.push(inst_id);
                ident_elided += 1;
                continue;
            }

            if materialize_spilled_store_pair(
                ir_func,
                &inst_snapshot,
                &site.uses,
                &mut new_block_insts,
            )? {
                continue;
            }
            if materialize_spilled_load_pair(
                ir_func,
                &inst_snapshot,
                &site.uses,
                &site.defs,
                &mut new_block_insts,
                &mut debug_info,
            )? {
                continue;
            }
            if materialize_spilled_register_offset_mem(
                ir_func,
                inst_id,
                &inst_snapshot,
                &site.uses,
                &site.defs,
                &mut new_block_insts,
                &mut debug_info,
            )? {
                continue;
            }
            if materialize_spilled_multiply_accumulate(
                ir_func,
                inst_id,
                &inst_snapshot,
                &site.uses,
                &site.defs,
                &mut new_block_insts,
                &mut debug_info,
            )? {
                continue;
            }
            if materialize_spilled_fused_multiply_add(
                ir_func,
                inst_id,
                &inst_snapshot,
                &site.uses,
                &mut new_block_insts,
            )? {
                continue;
            }

            let (def_positions, use_positions) = classify_operand_positions(&inst_snapshot);
            let mut use_bindings: Vec<(usize, VReg, PReg, StackSlotId)> = Vec::new();
            let mut def_bindings: Vec<(usize, VReg, PReg, StackSlotId)> = Vec::new();
            let mut use_loads: Vec<(PReg, StackSlotId)> = Vec::new();

            let mut assigned: HashMap<VReg, PReg> = HashMap::new();
            let reserved_scratch_regs = operand_physical_regs(&inst_snapshot);
            let mut used_scratch_regs = Vec::new();

            for &pos in &use_positions {
                let IrOperand::VReg(vreg) = inst_snapshot.operands[pos] else {
                    continue;
                };
                let Some(slot) = spill_slot_for_vreg(vreg, &site.uses) else {
                    continue;
                };

                let scratch = if let Some(&preg) = assigned.get(&vreg) {
                    preg
                } else {
                    let Some(preg) = available_scratch_for_class(
                        vreg.class,
                        &reserved_scratch_regs,
                        &used_scratch_regs,
                    )?
                    else {
                        return Err(PipelineError::RegAlloc(format!(
                            "AArch64 spill materialization ran out of scratch registers in {:?}",
                            inst_snapshot
                        )));
                    };
                    assigned.insert(vreg, preg);
                    used_scratch_regs.push(preg);
                    use_loads.push((preg, slot));
                    preg
                };
                use_bindings.push((pos, vreg, scratch, slot));
            }

            let spilled_defs: Vec<_> = def_positions
                .iter()
                .filter_map(|&pos| {
                    let IrOperand::VReg(vreg) = inst_snapshot.operands[pos] else {
                        return None;
                    };
                    let slot = spill_slot_for_vreg(vreg, &site.defs)?;
                    Some((pos, vreg, slot))
                })
                .collect();
            let spilled_def_count = spilled_defs.len();

            for (pos, vreg, slot) in spilled_defs {
                let scratch = if let Some(&preg) = assigned.get(&vreg) {
                    preg
                } else if let Some(preg) = available_scratch_for_class(
                    vreg.class,
                    &reserved_scratch_regs,
                    &used_scratch_regs,
                )? {
                    assigned.insert(vreg, preg);
                    used_scratch_regs.push(preg);
                    preg
                } else if spilled_def_count == 1 {
                    let first_use = use_bindings.first().ok_or_else(|| {
                        PipelineError::RegAlloc(format!(
                            "missing spill scratch for def-only spill in {:?}",
                            inst_snapshot
                        ))
                    })?;
                    let slot_idx = scratch_slot_index(first_use.2).ok_or_else(|| {
                        PipelineError::RegAlloc(format!(
                            "unknown spill scratch register {:?} in {:?}",
                            first_use.2, inst_snapshot
                        ))
                    })?;
                    scratch_pool_for_class(vreg.class)?[slot_idx]
                } else {
                    return Err(PipelineError::RegAlloc(format!(
                        "AArch64 spill materialization ran out of scratch registers for multiple defs in {:?}",
                        inst_snapshot
                    )));
                };
                def_bindings.push((pos, vreg, scratch, slot));
            }

            if use_bindings.is_empty() && def_bindings.is_empty() {
                new_block_insts.push(inst_id);
                continue;
            }

            for (scratch, slot) in &use_loads {
                let load_id =
                    ir_func.push_inst(make_spill_load(*scratch, *slot, inst_snapshot.source_loc));
                new_block_insts.push(load_id);
            }

            {
                let inst = &mut ir_func.insts[inst_id.0 as usize];
                for (pos, _, scratch, _) in &use_bindings {
                    inst.operands[*pos] = IrOperand::PReg(*scratch);
                }
                for (pos, _, scratch, _) in &def_bindings {
                    inst.operands[*pos] = IrOperand::PReg(*scratch);
                }
            }
            new_block_insts.push(inst_id);

            for (_, vreg, scratch, slot) in def_bindings {
                let store_id =
                    ir_func.push_inst(make_spill_store(scratch, slot, inst_snapshot.source_loc));
                new_block_insts.push(store_id);
                debug_info.record_store(vreg, slot, store_id);
            }
        }

        ir_func.blocks[block_idx].insts = new_block_insts;
    }

    if ident_elided > 0 && spill_peep_stats_enabled() {
        eprintln!(
            "[trust-cg-spill-peep] func={} ident_slot_copies_elided={}",
            ir_func.name, ident_elided
        );
    }

    Ok(debug_info)
}

/// Post-materialization redundant spill-slot reload elision (CSE over the CFG).
///
/// `materialize_spilled_operands_at_sites` conjures one reload per use SITE, so
/// several consecutive uses of one spilled value in a block re-load the same
/// untouched slot into the same scratch register (huffbench decode pays three
/// `ldr x16, [S]` in a row), and a spill store followed by a reload of the same
/// slot re-loads the value that is still sitting in the store's data register.
/// This pass deletes a reload `LdrRI r, [S]` when `r` PROVABLY still holds
/// `mem[S]`:
///
///  * a tracked fact `(S -> r)` is established by a previous spill reload
///    `LdrRI r, [S]` (post-state: `r == mem[S]`) or spill store `StrRI r, [S]`
///    (post-state: `mem[S] == r`), and
///  * no instruction between redefines `r` (explicit def positions per the
///    operand-role table, with sub-register overlap via `regs_overlap`), and
///  * no instruction between can write `mem[S]`, and
///  * the walk never crosses a call, return, indirect/trap terminator or any
///    instruction it cannot positively classify (facts are dropped there).
///
/// CROSS-BLOCK (the huffbench encode/decode residual). The tracker is a forward
/// MUST-dataflow over the post-RA CFG: `IN[B] = meet(OUT[P] for P in preds(B))`
/// with `meet` = keep only `(S -> r)` pairs on which every predecessor agrees
/// EXACTLY, `IN[entry] = {}`, and `OUT[B] = walk(B, IN[B])`. Optimistic
/// initialization (`OUT[B] = TOP`, the meet identity) is what lets a fact
/// generated in a loop header survive the body's back edge — huffbench's decode
/// insertion-sort reloads its spilled counter twice per outer iteration, once in
/// the header and once in the latch, with the inner loop in between (3 far-offset
/// instructions per reload). A single-predecessor rule cannot see that; the
/// fixpoint can. Soundness of the meet: a fact means "register `r` holds
/// `mem[S]` here", which is path-insensitive, so it may be assumed at a join
/// only if it holds on EVERY incoming edge — exactly what the intersection
/// computes. Any predecessor set that cannot be derived exactly makes the whole
/// function fall back to the block-local walk (see `cross_block_spill_facts`).
///
/// Facts flow along an edge only if the predecessor's terminator is a plain
/// direct local branch (`B`/`B.cond`/`CBZ`/`CBNZ`/`TBZ`/`TBNZ` with `Block`
/// operands and no register def); calls, returns, tail calls (`B <symbol>`),
/// indirect `Br` and every `Trap*` guard pseudo (which expand post-RA into
/// `MOVZ X16, #imm; CMP` — an IP-scratch clobber) drop them.
///
/// WHY USER STORES CANNOT WRITE A TRACKED SLOT (the alias proof): a slot is
/// tracked only if (a) it is a regalloc-created spill slot (`effective_spills`,
/// minted by `alloc_stack_slot` after all program-visible slots) AND (b) a
/// whole-function pre-scan shows EVERY reference to it is the exact 2-operand
/// spill access shape `LdrRI/StrRI [PReg, StackSlot]`. (b) proves the slot's
/// address is never materialized into any register (no address-of, no base+
/// offset form, no pair form), so no program pointer can name it; a
/// well-defined program's stores therefore cannot touch it (reaching it would
/// require out-of-bounds arithmetic from another object — UB, the standard
/// spill-slot no-alias assumption every production compiler makes).
///
/// SCRATCH-LIVENESS (the pr28982b X17-clobber class): deleting a reload
/// extends the scratch's live range backward to the PREVIOUS access of the
/// slot. The extension region is exactly the instructions between the two
/// accesses, and the tracker CLEARS all facts at every instruction that frame
/// lowering could expand with an IP-scratch borrow:
///
///  * any StackSlot-bearing instruction outside the tracked spill shapes,
///  * every spill STORE (its far-offset form borrows the other IP register for
///    the address), and
///  * every spill LOAD whose data register is not a GPR — an FPR reload cannot
///    host its own address arithmetic, so `frame.rs` borrows X16/X17 for it.
///
/// Therefore no instruction inside an extension region ever grows a scratch
/// borrow, and `frame.rs`'s own fail-closed IP-scratch liveness guard remains
/// the backstop for anything unforeseen (a wrong extension is a NAMED compile
/// error there, never a silent miscompile). That backstop is only a backstop if
/// it sees the same live ranges this pass creates, so `frame.rs` computes
/// X16/X17 liveness over the WHOLE function (`ip_scratch_block_live_out`); it
/// used to seed live-out-of-block = false on the "IP scratch never crosses a
/// block boundary" invariant, which cross-block elision retires.
///
/// Anything not positively classified clears all facts (fail-closed default).
///
/// THE CROSS-BLOCK SOLVE IS OPT-IN (`TCG_SPILL_RELOAD_CSE_XBLOCK=1`), because
/// it is a MEASURED WASH and shipping a wash into the default pipeline is
/// churn. Interleaved trimmed-median + min, best-of-15, vs clang 21 -O3:
///
/// | program           | block-local   | + cross-block | elides |
/// |-------------------|---------------|---------------|--------|
/// | huffbench         | 1.1713/1.1745 | 1.1724/1.1723 |  5->6  |
/// | McGill/exptree*   | 1.5322/1.5294 | 1.5265/1.5138 |  2->9  |
/// | Linpack/linpack-pc| 1.1436/1.1543 | 1.1403/1.1509 |  9->13 |
/// | Misc/ReedSolomon  | 1.1578/1.1594 | 1.1639/1.1663 |  4->8  |
///
/// (*exptree on an amplified input — its default input runs 4 ms, where the
/// spawn floor manufactured a fake -11%.) The ReedSolomon loss is NOT the
/// transform: with `TCG_NO_LOOP_HEAD_ALIGN=1` it inverts to 1.1585 -> 1.1549,
/// so removing four instructions moved a loop head across an alignment
/// boundary. It fires on 10 of the 65 importable SingleSource programs.
///
/// The block-local pass stays default-ON and is byte-identical with the
/// extension off (verified across all 65). Kill switch for the whole pass:
/// `TCG_SPILL_RELOAD_CSE_OFF=1`; bisect key `spill_reload_cse`
/// (TRUST_CG_DISABLE_PASSES).
fn elide_redundant_spill_slot_reloads(
    ir_func: &mut IrMachFunction,
    regalloc_spill_slots: &BTreeSet<StackSlotId>,
) -> u32 {
    elide_redundant_spill_slot_reloads_scoped(
        ir_func,
        regalloc_spill_slots,
        std::env::var_os("TCG_SPILL_RELOAD_CSE_XBLOCK").is_some(),
    )
}

/// [`elide_redundant_spill_slot_reloads`] with the cross-block solve chosen
/// explicitly instead of read from the environment (the tests drive both modes
/// without touching process-global state).
fn elide_redundant_spill_slot_reloads_scoped(
    ir_func: &mut IrMachFunction,
    regalloc_spill_slots: &BTreeSet<StackSlotId>,
    cross_block: bool,
) -> u32 {
    use trust_cg_ir::inst::InstFlags;

    if regalloc_spill_slots.is_empty() || std::env::var_os("TCG_SPILL_RELOAD_CSE_OFF").is_some() {
        return 0;
    }

    // PRE-SCAN (address-escape proof): keep only slots whose EVERY reference
    // in the function is the exact 2-operand spill load/store shape.
    let mut trackable: BTreeSet<StackSlotId> = regalloc_spill_slots.clone();
    for block in &ir_func.blocks {
        for &inst_id in &block.insts {
            let inst = &ir_func.insts[inst_id.0 as usize];
            if spill_access_shape(inst).is_some() {
                continue;
            }
            for op in &inst.operands {
                if let IrOperand::StackSlot(slot) = op {
                    trackable.remove(slot);
                }
            }
        }
    }
    if trackable.is_empty() {
        return 0;
    }

    // Cross-block MUST-dataflow entry facts (empty for every block when the
    // extension is off or the CFG cannot be derived exactly).
    let entry_facts = cross_block
        .then(|| cross_block_spill_facts(ir_func, &trackable))
        .flatten();

    let mut removed = 0u32;
    for block_idx in 0..ir_func.blocks.len() {
        let empty = SpillFacts::new();
        let facts_in = entry_facts
            .as_ref()
            .and_then(|f| f.get(block_idx))
            .unwrap_or(&empty);
        let (_, redundant) = walk_block_spill_facts(ir_func, block_idx, facts_in, &trackable);
        if redundant.is_empty() {
            continue;
        }
        for &pos in &redundant {
            // `reg` still holds `mem[slot]` — the reload is a no-op. Nop the
            // body so any stale InstId reference stays harmless, then drop it
            // from the block.
            let inst_id = ir_func.blocks[block_idx].insts[pos];
            let inst = &mut ir_func.insts[inst_id.0 as usize];
            inst.opcode = IrOpcode::Nop;
            inst.operands.clear();
            inst.flags = InstFlags::IS_PSEUDO;
            removed += 1;
        }
        let drop: BTreeSet<usize> = redundant.into_iter().collect();
        let mut pos = 0usize;
        ir_func.blocks[block_idx].insts.retain(|_| {
            let keep = !drop.contains(&pos);
            pos += 1;
            keep
        });
    }

    if removed > 0 && spill_peep_stats_enabled() {
        eprintln!(
            "[trust-cg-spill-peep] func={} redundant_slot_reloads_elided={}",
            ir_func.name, removed
        );
    }

    removed
}

/// "Register `r` currently holds the bytes of spill slot `S`", for every slot
/// whose value is provably resident. At most one entry per REGISTER as well as
/// per slot: establishing a fact first drops every overlapping-register fact.
type SpillFacts = BTreeMap<StackSlotId, PReg>;

/// The exact spill access shapes emitted by `make_spill_load` /
/// `make_spill_store`: `(is_load, data_reg, slot)`.
fn spill_access_shape(inst: &IrMachInst) -> Option<(bool, PReg, StackSlotId)> {
    let is_load = match inst.opcode {
        IrOpcode::LdrRI => true,
        IrOpcode::StrRI => false,
        _ => return None,
    };
    match inst.operands.as_slice() {
        [IrOperand::PReg(reg), IrOperand::StackSlot(slot)] => Some((is_load, *reg, *slot)),
        _ => None,
    }
}

/// NZCV-only side effects: safe to walk across (no GPR/FPR def, no memory).
fn spill_facts_compare_only(opcode: IrOpcode) -> bool {
    matches!(
        opcode,
        IrOpcode::CmpRR
            | IrOpcode::CmpRI
            | IrOpcode::CMPWrr
            | IrOpcode::CMPXrr
            | IrOpcode::CMPWri
            | IrOpcode::CMPXri
            | IrOpcode::Tst
            | IrOpcode::Fcmp
    )
}

/// Plain (non-volatile, non-writeback) user stores: write through program
/// pointers, which the address-escape pre-scan proves cannot name a tracked
/// slot; they define no register (their operands are all uses).
fn spill_facts_plain_user_store(opcode: IrOpcode) -> bool {
    matches!(
        opcode,
        IrOpcode::StrRI | IrOpcode::StrbRI | IrOpcode::StrhRI | IrOpcode::StrRO
    )
}

/// True iff `inst` is a plain DIRECT LOCAL branch across which slot->register
/// facts survive into the successor block: it transfers control inside this
/// function through `Block` operands, defines no register, touches no memory
/// and carries nothing frame-flavored.
///
/// Deliberately NOT fact-preserving (each drops every fact):
///  * `Bl`/`Blr`/`Ret` — calls clobber the caller-saved set, returns end the
///    live range;
///  * a tail-call `B <symbol>` — leaves the function (`Symbol`, not `Block`);
///  * indirect `Br` — its successor set lives in a jump table, and a computed
///    goto has none at all;
///  * every `Trap*` guard pseudo — `expand_trap_bounds_check_exact` rewrites
///    those post-RA into `MOVZ X16, #imm (+MOVK); CMP` and the overflow carrier
///    borrows X16 the same way, so walking one would silently step over an
///    IP-scratch clobber.
fn spill_facts_local_branch(inst: &IrMachInst) -> bool {
    use trust_cg_ir::inst::InstFlags;
    if !matches!(
        inst.opcode,
        IrOpcode::B
            | IrOpcode::BCond
            | IrOpcode::Bcc
            | IrOpcode::Cbz
            | IrOpcode::Cbnz
            | IrOpcode::Tbz
            | IrOpcode::Tbnz
    ) || inst.flags.contains(InstFlags::IS_CALL)
    {
        return false;
    }
    let mut has_block_target = false;
    for op in &inst.operands {
        match op {
            IrOperand::Block(_) => has_block_target = true,
            IrOperand::PReg(_) | IrOperand::Imm(_) | IrOperand::Special(_) => {}
            // Symbol (tail call), StackSlot/FrameIndex/MemOp (frame-flavored,
            // legalizable with a scratch borrow), VReg, anything else: no.
            _ => return false,
        }
    }
    // Nothing in this family writes a register; assert it rather than assume it
    // (a def would end a tracked register's live range mid-edge).
    let (def_positions, _) = classify_operand_positions(inst);
    has_block_target
        && def_positions.is_empty()
        && !inst.flags.contains(InstFlags::WRITES_MEMORY)
        && inst.implicit_defs.is_empty()
}

/// Walk one block's instruction stream from `facts_in`, returning the facts
/// that hold at the block's exit and the POSITIONS (indices into the block's
/// instruction list) of reloads that are provably redundant.
///
/// This is the single transfer function: the dataflow fixpoint and the final
/// rewrite both call it, so what the fixpoint proves is exactly what the
/// rewrite deletes. Deleting a redundant reload leaves the fact set unchanged
/// (the register already held the slot's bytes), so the returned exit facts are
/// valid both before and after the rewrite. Monotone in `facts_in` — every rule
/// either clears unconditionally, drops facts by register overlap, or inserts a
/// fixed pair — which is what makes the optimistic fixpoint terminate.
fn walk_block_spill_facts(
    ir_func: &IrMachFunction,
    block_idx: usize,
    facts_in: &SpillFacts,
    trackable: &BTreeSet<StackSlotId>,
) -> (SpillFacts, Vec<usize>) {
    use trust_cg_ir::inst::InstFlags;

    let mut track = facts_in.clone();
    let mut redundant: Vec<usize> = Vec::new();
    let Some(block) = ir_func.blocks.get(block_idx) else {
        return (SpillFacts::new(), redundant);
    };

    for (pos, &inst_id) in block.insts.iter().enumerate() {
        let Some(inst) = ir_func.insts.get(inst_id.0 as usize) else {
            track.clear();
            continue;
        };

        if let Some((is_load, reg, slot)) = spill_access_shape(inst) {
            if !trackable.contains(&slot) {
                // Frame access to an unproven slot: address provenance and
                // far-offset scratch borrows unknown — full barrier.
                track.clear();
                continue;
            }
            if is_load {
                if track.get(&slot) == Some(&reg) {
                    // `reg` still holds `mem[slot]`: the reload is a no-op.
                    redundant.push(pos);
                    continue;
                }
                if !matches!(preg_class(reg), RegClass::Gpr32 | RegClass::Gpr64) {
                    // An FPR reload cannot host its own address arithmetic, so
                    // the far-offset form borrows X16/X17 — the same clobber a
                    // spill STORE pays. Drop everything, then record the fact.
                    track.clear();
                } else {
                    // A GPR reload's far-offset form materializes the address
                    // in the destination register itself (`load_dest_gpr`), so
                    // only that register's facts die.
                    track.retain(|_, held| !regs_overlap(*held, reg));
                }
                track.insert(slot, reg);
            } else {
                // Spill STORE: its far-offset lowering borrows the other IP
                // scratch for the address, so every other fact's register may
                // be clobbered at frame lowering — drop them all. The store's
                // own data register is read, never borrowed, so
                // `mem[slot] == reg` holds afterwards.
                track.clear();
                track.insert(slot, reg);
            }
            continue;
        }

        // Pseudo/alignment nops: no machine effect.
        if matches!(inst.opcode, IrOpcode::Nop | IrOpcode::AlignNop) {
            continue;
        }

        let flags = inst.flags;
        if flags.contains(InstFlags::IS_CALL)
            || flags.contains(InstFlags::IS_BRANCH)
            || flags.contains(InstFlags::IS_RETURN)
            || flags.contains(InstFlags::IS_TERMINATOR)
        {
            // A plain direct local branch transfers control without touching a
            // register or memory, so facts survive it (and, when the successor
            // has no other predecessor reaching it with different facts, the
            // edge itself). Everything else in the family fails closed.
            if !spill_facts_local_branch(inst) {
                track.clear();
            }
            continue;
        }

        // Operand sanity: only plain register/immediate/special/symbol
        // operands may pass. Anything frame-flavored (StackSlot in a
        // non-spill shape, FrameIndex, MemOp) can be expanded by frame
        // lowering with an IP-scratch borrow; unresolved VRegs and other
        // exotic operands mean this walk does not understand the
        // instruction — fail closed.
        let operands_understood = inst.operands.iter().all(|op| {
            matches!(
                op,
                IrOperand::PReg(_)
                    | IrOperand::Imm(_)
                    | IrOperand::FImm(_)
                    | IrOperand::Special(_)
                    | IrOperand::Symbol(_)
            )
        });
        if !operands_understood {
            track.clear();
            continue;
        }

        // Side-effecting / memory-writing instructions: only the compare
        // family (NZCV-only) and plain user stores (cannot write a tracked
        // slot, define nothing) may pass; everything else fails closed.
        if (flags.contains(InstFlags::WRITES_MEMORY) || flags.contains(InstFlags::HAS_SIDE_EFFECTS))
            && !spill_facts_compare_only(inst.opcode)
            && !spill_facts_plain_user_store(inst.opcode)
        {
            track.clear();
            continue;
        }

        // Ordinary computational instruction (or an allowed store/compare):
        // drop facts whose register overlaps any explicit def.
        let (def_positions, _) = classify_operand_positions(inst);
        for &pos in &def_positions {
            if let Some(IrOperand::PReg(def_reg)) = inst.operands.get(pos) {
                track.retain(|_, held| !regs_overlap(*held, *def_reg));
            }
        }
        for def_reg in inst.implicit_defs.iter() {
            track.retain(|_, held| !regs_overlap(*held, *def_reg));
        }
    }

    (track, redundant)
}

/// Solve the cross-block MUST-dataflow and return each block's entry facts, or
/// `None` when the extension is off or the function's control flow cannot be
/// pinned down exactly (every caller then falls back to per-block empty entry
/// facts, i.e. the block-local pass).
///
/// `IN[entry] = {}`; `IN[B] = meet over preds` (an entry survives only if EVERY
/// predecessor's exit map carries the same slot -> register pair); `OUT[B] =
/// walk(B, IN[B])`. `OUT` starts at TOP (the meet identity, `None` below) so a
/// fact generated in a loop header and preserved around the back edge is
/// discovered — the pessimistic `{}` start can never introduce a loop-carried
/// fact, which is exactly the huffbench decode shape. TOP is only ever an
/// identity in the meet: a block whose predecessors are all still TOP is left
/// unevaluated, and at the fixpoint every entry-reachable block is concrete
/// (the entry is concrete and concreteness propagates along every edge).
///
/// FAIL-CLOSED CONDITIONS (whole function falls back to block-local):
///  * the caller did not ask for it (the solve is opt-in behind
///    `TCG_SPILL_RELOAD_CSE_XBLOCK=1` — see the measurement table on
///    `elide_redundant_spill_slot_reloads`);
///  * an indirect `Br` whose successors are not fully described by a jump table
///    in the same block (a computed goto's edges are underivable);
///  * a `Block` operand on a non-branch instruction (an address-of-block whose
///    edge the CFG derivation does not model);
///  * the iteration does not reach a fixpoint inside its budget.
fn cross_block_spill_facts(
    ir_func: &IrMachFunction,
    trackable: &BTreeSet<StackSlotId>,
) -> Option<Vec<SpillFacts>> {
    let n_blocks = ir_func.blocks.len();
    if n_blocks < 2 {
        return None;
    }

    // Underivable-edge guards. Both are whole-function: one unmodelled edge
    // anywhere could let a fact reach a block it does not hold in.
    for block in &ir_func.blocks {
        let insts = || {
            block
                .insts
                .iter()
                .map(|id| ir_func.insts.get(id.0 as usize))
        };
        if insts().any(|inst| inst.is_none()) {
            return None;
        }
        let jump_table_in_block = insts().flatten().any(|inst| {
            inst.operands
                .iter()
                .any(|op| op.as_jump_table_index().is_some())
        });
        for inst in insts().flatten() {
            if inst.opcode == IrOpcode::Br && !jump_table_in_block {
                return None;
            }
            let has_block_operand = inst
                .operands
                .iter()
                .any(|op| matches!(op, IrOperand::Block(_)));
            if has_block_operand && !inst.is_branch() && !inst.is_terminator() {
                return None;
            }
        }
    }

    // Predecessors from the canonical post-RA CFG authority (branch operands,
    // jump-table targets, EH landing pads and layout fallthrough), plus a
    // supplementary scan of blocks that are NOT in `block_order` so a branch
    // living in an unlaid-out block still counts as a predecessor.
    let mut preds: Vec<BTreeSet<usize>> = vec![BTreeSet::new(); n_blocks];
    for (from, to) in derive_ir_cfg_edges_from_branch_operands(ir_func) {
        let (from, to) = (from.0 as usize, to.0 as usize);
        if from >= n_blocks || to >= n_blocks {
            return None;
        }
        preds[to].insert(from);
    }
    let laid_out: BTreeSet<usize> = ir_func
        .block_order
        .iter()
        .map(|b| b.0 as usize)
        .collect::<BTreeSet<_>>();
    for (idx, block) in ir_func.blocks.iter().enumerate() {
        if laid_out.contains(&idx) {
            continue;
        }
        for &inst_id in &block.insts {
            let inst = ir_func.insts.get(inst_id.0 as usize)?;
            for op in &inst.operands {
                if let IrOperand::Block(target) = op {
                    let target = target.0 as usize;
                    if target >= n_blocks {
                        return None;
                    }
                    preds[target].insert(idx);
                }
            }
        }
    }

    let entry = ir_func.entry.0 as usize;
    if entry >= n_blocks {
        return None;
    }

    // Visit order: `block_order` first (a near-topological sweep, so most
    // functions converge in one pass), then any block missing from it.
    let mut order: Vec<usize> = Vec::with_capacity(n_blocks);
    let mut seen = vec![false; n_blocks];
    for &block_id in &ir_func.block_order {
        let idx = block_id.0 as usize;
        if idx < n_blocks && !seen[idx] {
            seen[idx] = true;
            order.push(idx);
        }
    }
    for (idx, visited) in seen.iter().enumerate() {
        if !visited {
            order.push(idx);
        }
    }

    // `None` = TOP (not yet evaluated / meet identity).
    let mut ins: Vec<Option<SpillFacts>> = vec![None; n_blocks];
    let mut outs: Vec<Option<SpillFacts>> = vec![None; n_blocks];

    // The lattice is finite and every sweep is monotonically decreasing, so a
    // fixpoint always exists; sweeping in near-topological order reaches it in
    // about (loop depth + 2) passes. The budget caps the compile-time cost and
    // fails the whole function closed if anything ever needs more.
    const SWEEP_BUDGET: usize = 32;
    let mut converged = false;
    for _ in 0..SWEEP_BUDGET {
        let mut changed = false;
        for &idx in &order {
            let new_in: Option<SpillFacts> = if idx == entry || preds[idx].is_empty() {
                // Entry, and any block whose predecessors are not derivable
                // (unreachable): nothing may be assumed.
                Some(SpillFacts::new())
            } else {
                let mut acc: Option<SpillFacts> = None;
                for &p in &preds[idx] {
                    let Some(pred_out) = outs[p].as_ref() else {
                        continue; // TOP: the meet identity.
                    };
                    acc = Some(match acc {
                        None => pred_out.clone(),
                        Some(cur) => cur
                            .into_iter()
                            .filter(|(slot, reg)| pred_out.get(slot) == Some(reg))
                            .collect(),
                    });
                }
                acc
            };
            if new_in != ins[idx] {
                ins[idx] = new_in;
                changed = true;
            }
            if let Some(facts_in) = ins[idx].as_ref() {
                let (exit, _) = walk_block_spill_facts(ir_func, idx, facts_in, trackable);
                if outs[idx].as_ref() != Some(&exit) {
                    outs[idx] = Some(exit);
                    changed = true;
                }
            }
        }
        if !changed {
            converged = true;
            break;
        }
    }
    if !converged {
        return None;
    }

    Some(
        ins.into_iter()
            .map(|f| f.unwrap_or_default())
            .collect::<Vec<_>>(),
    )
}

/// A pure-integer-immediate materialization recovered as a rematerialization
/// template for a spilled loop-invariant constant: `<op> <dst>, <imm...>` with
/// NO register inputs. Cloned at each spill reload site with `dst` set to the
/// reload's already-assigned scratch register, so a constant the allocator had
/// to spill is recomputed per use instead of reloaded from the frame.
#[derive(Debug, Clone)]
struct RematConstTemplate {
    /// The defining move opcode (`Movz`/`Movn`/`MovI`).
    opcode: IrOpcode,
    /// The defining instruction's operands EXCLUDING the destination register —
    /// verified by the classifier to be all integer immediates. Prepended with
    /// the reload's scratch `PReg` to rebuild the full instruction.
    imm_operands: Vec<IrOperand>,
}

/// Identify spilled vregs whose unique defining instruction is a **Free**
/// rematerialization candidate — a single pure-integer-immediate move with no
/// register inputs — and return a map from each such vreg's spill SLOT to its
/// rematerialization template.
///
/// This is the sound counterpart of the allocator-side `apply_rematerialization`
/// (see the note on `ra_config.enable_remat`): it runs in the pipeline where the
/// reload's scratch register is knowable, so the recomputed value can be placed
/// in a real physical register instead of leaking an unallocated vreg.
///
/// SCOPE — Free (pure integer immediate) only:
///   * `Movz` / `Movn` / `MovI` — the measured spilled-loop-constant win
///     (Bubblesort / fannkuch LCG constants reloaded every iteration).
///   * EXCLUDES `Movz`+`Movk` chains: a chain defines its vreg twice, so the
///     "exactly one non-reload def" test rejects it (cloning one half of a
///     multi-instruction constant would be a miscompile).
///   * EXCLUDES `Adrp` / address materialization: those carry a `Symbol`
///     operand, which the all-immediate-operands test rejects. A lone `adrp` is
///     only half of a PC-relative address, and re-sinking a hoisted address
///     into a loop would undo LICM — the exact case the allocator-side
///     deeper-loop guard protects. Restricting to pure immediates makes that
///     guard unnecessary here (there is no hoisted address to un-hoist, and
///     replacing an existing per-iteration reload with a per-iteration
///     recompute is never worse).
///   * EXCLUDES `Cheap` (one register input): proving the input register's
///     physical assignment is live and unchanged at every reload site is a
///     dataflow claim we do not make.
///   * EXCLUDES slots shared by more than one spilled vreg (spill-slot reuse):
///     rewriting every reload of such a slot into one vreg's constant would
///     corrupt the other vreg's reloads.
fn find_free_remat_spilled_constants(
    ir_func: &IrMachFunction,
    spills: &[trust_cg_regalloc::SpillInfo],
) -> HashMap<StackSlotId, RematConstTemplate> {
    let mut result = HashMap::new();
    if spills.is_empty() {
        return result;
    }

    // Slot -> the distinct spilled vregs assigned to it. A slot used by more
    // than one vreg (spill-slot reuse) is disqualified below.
    let mut slot_vregs: HashMap<StackSlotId, BTreeSet<VReg>> = HashMap::new();
    for spill in spills {
        slot_vregs.entry(spill.slot).or_default().insert(spill.vreg);
    }
    let spilled: HashMap<VReg, StackSlotId> = spills.iter().map(|s| (s.vreg, s.slot)).collect();

    // Count non-reload definitions of each spilled vreg and remember the def.
    // Only instructions reachable through a block are considered; a spilled
    // constant's real definition always is.
    let mut def_count: HashMap<VReg, u32> = HashMap::new();
    let mut def_inst: HashMap<VReg, InstId> = HashMap::new();
    for &block_id in &ir_func.block_order {
        let Some(block) = ir_func.blocks.get(block_id.0 as usize) else {
            continue;
        };
        for &inst_id in &block.insts {
            let Some(inst) = ir_func.insts.get(inst_id.0 as usize) else {
                continue;
            };
            let (def_positions, _) = classify_operand_positions(inst);
            for &pos in &def_positions {
                if let Some(IrOperand::VReg(v)) = inst.operands.get(pos)
                    && spilled.contains_key(v)
                {
                    *def_count.entry(*v).or_insert(0) += 1;
                    def_inst.insert(*v, inst_id);
                }
            }
        }
    }

    for (&vreg, &slot) in &spilled {
        // Slot must belong to exactly this one spilled vreg (no reuse sharing).
        if slot_vregs.get(&slot).map(|s| s.len()).unwrap_or(0) != 1 {
            continue;
        }
        // Exactly one definition of the vreg in the function.
        if def_count.get(&vreg).copied().unwrap_or(0) != 1 {
            continue;
        }
        let Some(&def_id) = def_inst.get(&vreg) else {
            continue;
        };
        let Some(inst) = ir_func.insts.get(def_id.0 as usize) else {
            continue;
        };
        // Free integer-immediate materialization only (single instruction).
        if !matches!(
            inst.opcode,
            IrOpcode::Movz | IrOpcode::Movn | IrOpcode::MovI
        ) {
            continue;
        }
        let (def_positions, use_positions) = classify_operand_positions(inst);
        // Exactly one def operand, and it is this vreg.
        if def_positions.len() != 1 {
            continue;
        }
        if inst
            .operands
            .get(def_positions[0])
            .and_then(|o| o.as_vreg())
            != Some(vreg)
        {
            continue;
        }
        // Every non-def operand must be a pure integer immediate: no register
        // input, no `Symbol`/adrp, no memory, no stack slot.
        let all_imm = use_positions
            .iter()
            .all(|&p| matches!(inst.operands.get(p), Some(IrOperand::Imm(_))));
        if !all_imm {
            continue;
        }
        // Build the template operands = everything except the destination,
        // preserving order. Defensive re-check that they are all immediates.
        let imm_operands: Vec<IrOperand> = inst
            .operands
            .iter()
            .enumerate()
            .filter(|(i, _)| *i != def_positions[0])
            .map(|(_, o)| o.clone())
            .collect();
        if imm_operands.is_empty() || !imm_operands.iter().all(|o| matches!(o, IrOperand::Imm(_))) {
            continue;
        }
        result.insert(
            slot,
            RematConstTemplate {
                opcode: inst.opcode,
                imm_operands,
            },
        );
    }
    result
}

/// Replace each spill RELOAD (`LdrRI <scratch>, [<slot>]`) of a Free-constant
/// spill slot with a rematerialization of that constant into the SAME scratch
/// register. The reload's scratch is already assigned by
/// [`materialize_spilled_operands_at_sites`], so the recomputed value lands in
/// exactly the register the consumer expects — this is the physical-register
/// step the allocator-side remat could not perform (it ran before scratch
/// assignment, leaving an unresolved vreg the encoder rejects).
///
/// Keyed by SLOT, so it fires uniformly for reloads emitted by ANY
/// materialization path (the general path, the multiply-accumulate helper,
/// etc.). Every slot in `remat` is a dedicated spill slot for a single Free
/// constant (`find_free_remat_spilled_constants` disqualifies shared slots), so
/// its ONLY `LdrRI` reads are reloads of that constant — rewriting them is
/// value-preserving. The one-time spill STORE to the slot is left in place (a
/// non-loop dead store); the per-iteration reload is what this removes.
///
/// Returns the number of reloads rematerialized.
fn remat_free_spilled_constant_reloads(
    ir_func: &mut IrMachFunction,
    remat: &HashMap<StackSlotId, RematConstTemplate>,
) -> u32 {
    if remat.is_empty() {
        return 0;
    }
    let mut count = 0u32;
    for inst in &mut ir_func.insts {
        if inst.opcode != IrOpcode::LdrRI || inst.operands.len() != 2 {
            continue;
        }
        let IrOperand::PReg(scratch) = inst.operands[0] else {
            continue;
        };
        let IrOperand::StackSlot(slot) = inst.operands[1] else {
            continue;
        };
        let Some(template) = remat.get(&slot) else {
            continue;
        };
        let source_loc = inst.source_loc;
        let mut operands = Vec::with_capacity(1 + template.imm_operands.len());
        operands.push(IrOperand::PReg(scratch));
        operands.extend(template.imm_operands.iter().cloned());
        let mut new_inst = IrMachInst::new(template.opcode, operands);
        new_inst.source_loc = source_loc;
        *inst = new_inst;
        count += 1;
    }
    count
}

fn spill_materialization_trace_enabled(function_name: &str) -> bool {
    match std::env::var("TRUST_CG_TRACE_SPILL_MATERIALIZATION") {
        Ok(filter) => filter == "1" || filter == "all" || function_name.contains(&filter),
        Err(_) => false,
    }
}

fn add_missing_spill_materialization_sites(
    ir_func: &IrMachFunction,
    sites: &mut HashMap<InstId, SpillMaterializationSite>,
    spills: &[trust_cg_regalloc::SpillInfo],
) {
    let spill_slots: HashMap<VReg, StackSlotId> = spills
        .iter()
        .map(|spill| (spill.vreg, spill.slot))
        .collect();
    if spill_slots.is_empty() {
        return;
    }

    for &block_id in &ir_func.block_order {
        let block = ir_func.block(block_id);
        for &inst_id in &block.insts {
            let inst = ir_func.inst(inst_id);
            let (def_positions, use_positions) = classify_operand_positions(inst);

            for &pos in &use_positions {
                let Some((vreg, slot)) = spilled_vreg_at(inst, pos, &spill_slots) else {
                    continue;
                };
                sites.entry(inst_id).or_default().uses.insert(vreg, slot);
            }

            for &pos in &def_positions {
                let Some((vreg, slot)) = spilled_vreg_at(inst, pos, &spill_slots) else {
                    continue;
                };
                sites.entry(inst_id).or_default().defs.insert(vreg, slot);
            }
        }
    }
}

fn spill_slot_for_vreg(
    vreg: VReg,
    spill_slots: &HashMap<VReg, StackSlotId>,
) -> Option<StackSlotId> {
    spill_slots.get(&vreg).copied()
}

fn is_regalloc_spill_pseudo(opcode: u16) -> bool {
    opcode == trust_cg_regalloc::spill::PSEUDO_SPILL_LOAD
        || opcode == trust_cg_regalloc::spill::PSEUDO_SPILL_STORE
}

fn is_regalloc_inserted_pseudo(opcode: u16) -> bool {
    is_regalloc_spill_pseudo(opcode)
        || opcode == trust_cg_regalloc::phi_elim::PSEUDO_COPY
        || opcode == trust_cg_regalloc::phi_elim::PSEUDO_JUMP
        || opcode == 0xFFFF
}

#[derive(Debug, Default)]
struct SpillMaterializationSite {
    uses: HashMap<VReg, StackSlotId>,
    defs: HashMap<VReg, StackSlotId>,
}

impl SpillMaterializationSite {
    fn is_empty(&self) -> bool {
        self.uses.is_empty() && self.defs.is_empty()
    }

    fn merge(&mut self, other: SpillMaterializationSite) {
        self.uses.extend(other.uses);
        self.defs.extend(other.defs);
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct SpillMaterializedStore {
    vreg: VReg,
    slot: StackSlotId,
    inst: InstId,
}

#[derive(Debug, Clone, Default)]
struct SpillMaterializationDebugInfo {
    stores: Vec<SpillMaterializedStore>,
}

impl SpillMaterializationDebugInfo {
    fn record_store(&mut self, vreg: VReg, slot: StackSlotId, inst: InstId) {
        self.stores
            .push(SpillMaterializedStore { vreg, slot, inst });
    }
}

fn regalloc_spill_pseudo_key(
    inst: &trust_cg_regalloc::machine_types::RegAllocInst,
) -> Option<(VReg, StackSlotId)> {
    use trust_cg_regalloc::machine_types::RegAllocOperand as RaOperand;

    let slot = inst.uses.iter().find_map(|operand| match operand {
        RaOperand::StackSlot(slot) => Some(*slot),
        _ => None,
    })?;

    if inst.opcode == trust_cg_regalloc::spill::PSEUDO_SPILL_LOAD {
        let vreg = inst.defs.iter().find_map(|operand| operand.as_vreg())?;
        return Some((vreg, slot));
    }

    if inst.opcode == trust_cg_regalloc::spill::PSEUDO_SPILL_STORE {
        let vreg = inst.uses.iter().find_map(|operand| operand.as_vreg())?;
        return Some((vreg, slot));
    }

    None
}

fn retained_spill_materialization_sites(
    ra_func: &trust_cg_regalloc::RegAllocFunction,
    spills: &[trust_cg_regalloc::SpillInfo],
) -> HashMap<usize, SpillMaterializationSite> {
    let valid_spills: BTreeSet<(VReg, StackSlotId)> = spills
        .iter()
        .map(|spill| (spill.vreg, spill.slot))
        .collect();
    if valid_spills.is_empty() {
        return HashMap::new();
    }

    let mut sites = HashMap::new();
    for block in &ra_func.blocks {
        let mut pending_loads = Vec::new();
        let mut last_materialized_inst = None;

        for inst_id in &block.insts {
            let Some(inst) = ra_func.insts.get(inst_id.0 as usize) else {
                continue;
            };

            if let Some((vreg, slot)) = regalloc_spill_pseudo_key(inst) {
                if !valid_spills.contains(&(vreg, slot)) {
                    continue;
                }

                if inst.opcode == trust_cg_regalloc::spill::PSEUDO_SPILL_LOAD {
                    pending_loads.push((vreg, slot));
                } else if let Some(target) = last_materialized_inst {
                    let site: &mut SpillMaterializationSite = sites.entry(target).or_default();
                    site.defs.insert(vreg, slot);
                }
                continue;
            }

            if !pending_loads.is_empty() {
                let site: &mut SpillMaterializationSite =
                    sites.entry(inst_id.0 as usize).or_default();
                for (vreg, slot) in pending_loads.drain(..) {
                    site.uses.insert(vreg, slot);
                }
            }
            last_materialized_inst = Some(inst_id.0 as usize);
        }
    }

    sites
}

fn remap_spill_materialization_sites(
    sites: HashMap<usize, SpillMaterializationSite>,
    inst_map: &[Option<InstId>],
) -> HashMap<InstId, SpillMaterializationSite> {
    let mut remapped = HashMap::new();
    for (old_inst_idx, site) in sites {
        let Some(Some(new_inst_id)) = inst_map.get(old_inst_idx) else {
            continue;
        };
        remapped
            .entry(*new_inst_id)
            .or_insert_with(SpillMaterializationSite::default)
            .merge(site);
    }
    remapped
}

fn effective_spills_from_materialization_sites(
    sites: &HashMap<InstId, SpillMaterializationSite>,
    spills: &[trust_cg_regalloc::SpillInfo],
) -> Vec<trust_cg_regalloc::SpillInfo> {
    let retained: BTreeSet<(VReg, StackSlotId)> = sites
        .values()
        .flat_map(|site| site.uses.iter().chain(site.defs.iter()))
        .map(|(vreg, slot)| (*vreg, *slot))
        .collect();

    if retained.is_empty() {
        return Vec::new();
    }

    let mut emitted = BTreeSet::new();
    spills
        .iter()
        .filter_map(|spill| {
            let key = (spill.vreg, spill.slot);
            if retained.contains(&key) && emitted.insert(key) {
                Some(spill.clone())
            } else {
                None
            }
        })
        .collect()
}

fn leak_pregs(pregs: &[PReg]) -> &'static [PReg] {
    if pregs.is_empty() {
        &[]
    } else {
        Box::leak(pregs.to_vec().into_boxed_slice())
    }
}

fn regalloc_operand_to_ir(
    operand: &trust_cg_regalloc::machine_types::RegAllocOperand,
) -> IrOperand {
    use trust_cg_regalloc::machine_types::RegAllocOperand as RaOperand;

    match operand {
        RaOperand::VReg(vreg) => IrOperand::VReg(*vreg),
        RaOperand::PReg(preg) => IrOperand::PReg(*preg),
        RaOperand::Imm(imm) => IrOperand::Imm(*imm),
        RaOperand::FImm(imm) => IrOperand::FImm(*imm),
        RaOperand::Block(block) => IrOperand::Block(*block),
        RaOperand::StackSlot(slot) => IrOperand::StackSlot(*slot),
    }
}

fn regalloc_opcode_to_ir(opcode: u16) -> Result<IrOpcode, PipelineError> {
    if opcode == trust_cg_regalloc::spill::PSEUDO_SPILL_LOAD {
        return Ok(IrOpcode::LdrRI);
    }
    if opcode == trust_cg_regalloc::spill::PSEUDO_SPILL_STORE {
        return Ok(IrOpcode::StrRI);
    }
    if opcode == IrOpcode::Copy as u16 {
        return Ok(IrOpcode::Copy);
    }
    if opcode == trust_cg_regalloc::phi_elim::PSEUDO_COPY {
        return Ok(IrOpcode::Copy);
    }
    if opcode == trust_cg_regalloc::phi_elim::PSEUDO_JUMP {
        return Ok(IrOpcode::B);
    }
    if opcode == 0xFFFF {
        return Ok(IrOpcode::Nop);
    }

    // The valid AArch64 opcode discriminant space is dense and 0-based; the
    // current maximum is the last variant in the enum. The u16 round-trip
    // (`ir_to_regalloc`'s `opcode as u16` -> this transmute) happens entirely
    // within one process, so both sides always agree on the discriminants.
    // KEEP THIS AT THE ENUM'S LAST VARIANT: a newly appended opcode above this
    // bound fails closed here for EVERY function containing it (the
    // LdrGottprel/TLSIE lesson — caught by `e2e_aarch64_elf_tlsie`, which
    // drives the full prepare_function path).
    const MAX_AARCH64_OPCODE: u16 = IrOpcode::VolatileStrhRI as u16;
    if opcode > MAX_AARCH64_OPCODE {
        return Err(PipelineError::InvalidOperand(format!(
            "unknown regalloc opcode 0x{opcode:04x}"
        )));
    }

    // SAFETY: AArch64Opcode has a dense 0-based discriminant space up to
    // MAX_AARCH64_OPCODE, checked above. The enum has more than 256 fieldless
    // variants, so its tag (and this transmute's source) is u16; the compiler
    // rejects this line (E0512) if the enum ever shrinks back below 257
    // variants — change the source type back to u8 in that case.
    Ok(unsafe { std::mem::transmute::<u16, IrOpcode>(opcode) })
}

fn regalloc_explicit_operand_count(
    opcode: IrOpcode,
    def_count: usize,
    use_count: usize,
) -> Result<usize, PipelineError> {
    let max_operand_count = def_count.checked_add(use_count).ok_or_else(|| {
        PipelineError::InvalidOperand(format!(
            "{opcode:?} regalloc rebuild operand count overflow for {def_count} defs and {use_count} uses"
        ))
    })?;

    let mut matches = (0..=max_operand_count).filter(|&operand_count| {
        let roles = aarch64_operand_roles(opcode, operand_count);
        let role_def_count = roles
            .iter()
            .filter(|&&role| matches!(role, OperandRole::Def | OperandRole::DefUse))
            .count();
        let role_use_count = roles
            .iter()
            .filter(|&&role| matches!(role, OperandRole::Use | OperandRole::DefUse))
            .count();
        role_def_count == def_count && role_use_count == use_count
    });

    let Some(operand_count) = matches.next() else {
        return Err(PipelineError::InvalidOperand(format!(
            "{opcode:?} regalloc rebuild could not infer operand count from {def_count} defs and {use_count} uses"
        )));
    };

    if matches.next().is_some() {
        return Err(PipelineError::InvalidOperand(format!(
            "{opcode:?} regalloc rebuild inferred ambiguous operand count from {def_count} defs and {use_count} uses"
        )));
    }

    Ok(operand_count)
}

fn rebuild_operands_from_regalloc(
    opcode: IrOpcode,
    defs: &[trust_cg_regalloc::machine_types::RegAllocOperand],
    uses: &[trust_cg_regalloc::machine_types::RegAllocOperand],
) -> Result<Vec<IrOperand>, PipelineError> {
    let operand_count = regalloc_explicit_operand_count(opcode, defs.len(), uses.len())?;
    let roles = aarch64_operand_roles(opcode, operand_count);
    let mut def_iter = defs.iter();
    let mut use_iter = uses.iter();
    let mut operands = Vec::with_capacity(operand_count);

    for (idx, role) in roles.into_iter().enumerate() {
        match role {
            OperandRole::Def => {
                let operand = def_iter.next().ok_or_else(|| {
                    PipelineError::InvalidOperand(format!(
                        "{opcode:?} regalloc rebuild missing def for operand {idx}"
                    ))
                })?;
                operands.push(regalloc_operand_to_ir(operand));
            }
            OperandRole::Use => {
                let operand = use_iter.next().ok_or_else(|| {
                    PipelineError::InvalidOperand(format!(
                        "{opcode:?} regalloc rebuild missing use for operand {idx}"
                    ))
                })?;
                operands.push(regalloc_operand_to_ir(operand));
            }
            OperandRole::DefUse => {
                let def_operand = def_iter.next().ok_or_else(|| {
                    PipelineError::InvalidOperand(format!(
                        "{opcode:?} regalloc rebuild missing tied def for operand {idx}"
                    ))
                })?;
                let _use_operand = use_iter.next().ok_or_else(|| {
                    PipelineError::InvalidOperand(format!(
                        "{opcode:?} regalloc rebuild missing tied use for operand {idx}"
                    ))
                })?;
                operands.push(regalloc_operand_to_ir(def_operand));
            }
        }
    }

    if def_iter.next().is_some() || use_iter.next().is_some() {
        return Err(PipelineError::InvalidOperand(format!(
            "{opcode:?} regalloc rebuild left extra explicit operands from {} defs and {} uses",
            defs.len(),
            uses.len()
        )));
    }

    Ok(operands)
}

/// Regalloc sees these operands as `Imm(0)` placeholders; codegen still needs
/// the original relocation/frame metadata after the regalloc-side rebuild.
fn is_regalloc_opaque_operand(operand: &IrOperand) -> bool {
    matches!(
        operand,
        IrOperand::Symbol(_) | IrOperand::JumpTableIndex(_) | IrOperand::IncomingArg(_)
    )
}

fn regalloc_rebuilt_operand_matches_original(rebuilt: &IrOperand, original: &IrOperand) -> bool {
    if is_regalloc_opaque_operand(original) {
        return matches!(rebuilt, IrOperand::Imm(0));
    }

    match (rebuilt, original) {
        (IrOperand::VReg(rebuilt), IrOperand::VReg(original)) => rebuilt == original,
        (IrOperand::PReg(rebuilt), IrOperand::PReg(original)) => rebuilt == original,
        (IrOperand::PReg(preg), IrOperand::VReg(vreg))
        | (IrOperand::VReg(vreg), IrOperand::PReg(preg)) => {
            project_allocated_preg(*preg, vreg.class).is_some()
        }
        _ => rebuilt == original,
    }
}

fn regalloc_rebuilt_operands_match_original(operands: &[IrOperand], original: &IrMachInst) -> bool {
    operands.len() == original.operands.len()
        && operands
            .iter()
            .zip(&original.operands)
            .all(|(rebuilt, original)| regalloc_rebuilt_operand_matches_original(rebuilt, original))
}

/// LOOSE per-operand provenance match: like the strict rule, but a rebuilt VReg
/// may carry a DIFFERENT id than the original VReg as long as the register
/// class agrees. Live-range splitting renames a def/use to a fresh split-child
/// vreg (`split_interval` -> `alloc_vreg`), so a spilled split child reaches the
/// rebuild with an id the original stream never contained; identity then rests
/// on the non-register operands (stack slots, immediates, opaque placeholders),
/// which regalloc never rewrites. Physical registers stay EXACT — pregs are
/// pinned constraints, never renamed.
fn regalloc_rebuilt_operand_matches_original_loose(
    rebuilt: &IrOperand,
    original: &IrOperand,
) -> bool {
    if is_regalloc_opaque_operand(original) {
        return matches!(rebuilt, IrOperand::Imm(0));
    }

    match (rebuilt, original) {
        (IrOperand::VReg(rebuilt), IrOperand::VReg(original)) => rebuilt.class == original.class,
        (IrOperand::PReg(rebuilt), IrOperand::PReg(original)) => rebuilt == original,
        (IrOperand::PReg(preg), IrOperand::VReg(vreg))
        | (IrOperand::VReg(vreg), IrOperand::PReg(preg)) => {
            project_allocated_preg(*preg, vreg.class).is_some()
        }
        _ => rebuilt == original,
    }
}

fn regalloc_rebuilt_operands_match_original_loose(
    operands: &[IrOperand],
    original: &IrMachInst,
) -> bool {
    operands.len() == original.operands.len()
        && operands
            .iter()
            .zip(&original.operands)
            .all(|(rebuilt, original)| {
                regalloc_rebuilt_operand_matches_original_loose(rebuilt, original)
            })
}

fn match_regalloc_original_candidate<'a>(
    original_insts: &'a [IrMachInst],
    original_idx: usize,
    opcode: IrOpcode,
    operands: &[IrOperand],
) -> Result<(Option<&'a IrMachInst>, usize), PipelineError> {
    let mut matched = None;
    let mut matched_idx = original_idx;
    let mut matched_opaque = false;
    let mut saw_skipped_opaque = false;

    for (idx, candidate) in original_insts.iter().enumerate().skip(original_idx) {
        if candidate.opcode != opcode {
            continue;
        }

        let candidate_opaque = has_regalloc_opaque_operand(candidate);
        if regalloc_rebuilt_operands_match_original(operands, candidate) {
            if matched.is_some() {
                if matched_opaque || candidate_opaque {
                    return Err(PipelineError::InvalidOperand(format!(
                        "{opcode:?} regalloc rebuild found ambiguous opaque operand provenance"
                    )));
                }
                continue;
            }
            matched = Some(candidate);
            matched_idx = idx;
            matched_opaque = candidate_opaque;
        } else {
            saw_skipped_opaque |= candidate_opaque;
        }
    }

    if matched.is_none() && saw_skipped_opaque {
        // Strict matching found nothing, and an opaque candidate is still in
        // range, so declining to match could restore the wrong (or no)
        // relocation. Retry with the LOOSE rule: live-range splitting renames
        // vregs to fresh split-child ids (e.g. a spilled split child of an
        // `AddPCRel dst, sp, slot` frame-address def), which the strict
        // VReg-id-equality rule can never re-associate. The loose rule keys
        // identity on the non-register operands instead — accepted ONLY when
        // exactly one candidate matches, so an ambiguous provenance (two
        // opaque candidates of the same shape) still fails closed.
        let mut loose_matched = None;
        let mut loose_idx = original_idx;
        let mut loose_ambiguous = false;
        for (idx, candidate) in original_insts.iter().enumerate().skip(original_idx) {
            if candidate.opcode != opcode {
                continue;
            }
            if regalloc_rebuilt_operands_match_original_loose(operands, candidate) {
                if loose_matched.is_some() {
                    loose_ambiguous = true;
                    break;
                }
                loose_matched = Some(candidate);
                loose_idx = idx;
            }
        }
        if let Some(candidate) = loose_matched
            && !loose_ambiguous
        {
            return Ok((Some(candidate), loose_idx + 1));
        }
        // No (unambiguous) loose match either. That is only a problem when the
        // rebuilt instruction could actually be missing an opaque operand: the
        // regalloc blinding replaces Symbol/JumpTableIndex/IncomingArg with an
        // `Imm(0)` placeholder, so a rebuilt instruction with NO `Imm(0)`
        // operand provably needs no restoration — failing to find its original
        // costs only optional metadata (proof/source_loc), never a relocation.
        // Rematerialization reaches exactly this case: a remat CLONE of a
        // frame-address def (`AddPCRel dst, sp, slot`) appears late in the
        // stream after the cursor has consumed its original, while unrelated
        // Symbol-form candidates of the same opcode sit ahead of the cursor
        // (`saw_skipped_opaque`). The clone carries its full operands, so it is
        // safe to rebuild without provenance. Anything still holding an
        // `Imm(0)` placeholder stays fail-closed.
        if !rebuilt_may_need_opaque_provenance(operands) {
            return Ok((None, original_idx));
        }
        return Err(PipelineError::InvalidOperand(format!(
            "{opcode:?} regalloc rebuild could not match opaque operand provenance"
        )));
    }

    Ok((matched, matched.map_or(original_idx, |_| matched_idx + 1)))
}

/// True when a rebuilt instruction could be carrying a regalloc-blinded opaque
/// operand: the blinding writes `Imm(0)` placeholders (see
/// [`restore_regalloc_opaque_operands`]), so an instruction without any
/// `Imm(0)` operand cannot need opaque-provenance restoration. (A genuine zero
/// immediate also answers true — conservative: such instructions keep the
/// fail-closed provenance requirement.)
fn rebuilt_may_need_opaque_provenance(operands: &[IrOperand]) -> bool {
    operands
        .iter()
        .any(|operand| matches!(operand, IrOperand::Imm(0)))
}

fn indexed_regalloc_original_candidate<'a>(
    original_insts: &'a [IrMachInst],
    ra_inst_idx: usize,
    opcode: IrOpcode,
    operands: &[IrOperand],
) -> Result<Option<&'a IrMachInst>, PipelineError> {
    let Some(candidate) = original_insts.get(ra_inst_idx) else {
        return Ok(None);
    };

    if candidate.opcode != opcode {
        if has_regalloc_opaque_operand(candidate) && rebuilt_may_need_opaque_provenance(operands) {
            return Err(PipelineError::InvalidOperand(format!(
                "{opcode:?} regalloc rebuild changed opcode for indexed opaque operand provenance"
            )));
        }
        return Ok(None);
    }

    if regalloc_rebuilt_operands_match_original(operands, candidate) {
        return Ok(Some(candidate));
    }

    if has_regalloc_opaque_operand(candidate) && rebuilt_may_need_opaque_provenance(operands) {
        // Strict matching failed on an index-aligned opaque candidate. Arena
        // slots are index-stable across regalloc (the adapter converts the IR
        // insts 1:1 in order, spill/reload code is `func.insts.push`ed at the
        // arena END, and post-RA deletions tombstone to the 0xFFFF NOP rather
        // than compacting), so the candidate at this index IS this instruction
        // — the only ways its registers differ are the preg assignment
        // (already accepted by the strict rule) and a live-range SPLIT rename
        // to a fresh split-child vreg id (`split_interval` -> `alloc_vreg` ->
        // in-place `rewrite_vreg_operands`), which the strict VReg-id-equality
        // rule can never re-associate. Accept the candidate under the LOOSE
        // rule — register classes must agree and every non-register operand
        // must be identical — exactly the documented loose rule the SCAN
        // matcher already applies (and stronger here: the index pins the
        // candidate set to ONE, so there is no ambiguity to guard). Without
        // this, an -O2 register-pressure split of e.g. an `Adrp dst,
        // Symbol(..)` def fails the whole compile ("could not match indexed
        // opaque operand provenance" — the get_backtrace_style unwind-lane
        // fallback class). Anything that fails even the loose rule (an operand
        // COUNT or non-register operand change) still fails closed.
        if regalloc_rebuilt_operands_match_original_loose(operands, candidate) {
            return Ok(Some(candidate));
        }
        return Err(PipelineError::InvalidOperand(format!(
            "{opcode:?} regalloc rebuild could not match indexed opaque operand provenance \
             (rebuilt {operands:?} vs original {:?})",
            candidate.operands
        )));
    }

    Ok(None)
}

fn restore_regalloc_opaque_operands(operands: &mut [IrOperand], original: &IrMachInst) {
    for (idx, operand) in operands.iter_mut().enumerate() {
        if !matches!(operand, IrOperand::Imm(0)) {
            continue;
        }

        if let Some(
            original_operand @ (IrOperand::Symbol(_)
            | IrOperand::JumpTableIndex(_)
            | IrOperand::IncomingArg(_)),
        ) = original.operands.get(idx)
        {
            *operand = original_operand.clone();
        }
    }
}

fn has_regalloc_opaque_operand(inst: &IrMachInst) -> bool {
    inst.operands.iter().any(is_regalloc_opaque_operand)
}

#[cfg(test)]
fn rebuild_ir_from_regalloc(
    ir_func: &mut IrMachFunction,
    ra_func: &trust_cg_regalloc::RegAllocFunction,
) -> Result<(), PipelineError> {
    rebuild_ir_from_regalloc_with_map(ir_func, ra_func).map(|_| ())
}

fn rebuild_ir_from_regalloc_with_map(
    ir_func: &mut IrMachFunction,
    ra_func: &trust_cg_regalloc::RegAllocFunction,
) -> Result<Vec<Option<InstId>>, PipelineError> {
    let original_insts = ir_func.insts.clone();
    let mut rebuilt_insts = Vec::with_capacity(ra_func.insts.len());
    let mut inst_map: Vec<Option<InstId>> = Vec::with_capacity(ra_func.insts.len());
    let mut original_idx = 0usize;

    for (ra_inst_idx, ra_inst) in ra_func.insts.iter().enumerate() {
        if is_regalloc_spill_pseudo(ra_inst.opcode) {
            inst_map.push(None);
            continue;
        }

        let opcode = regalloc_opcode_to_ir(ra_inst.opcode)?;
        let mut operands = if ra_inst.opcode == 0xFFFF {
            Vec::new()
        } else if opcode_uses_all_operands_for_regalloc(opcode, ra_inst.flags) {
            ra_inst
                .defs
                .iter()
                .chain(ra_inst.uses.iter())
                .map(regalloc_operand_to_ir)
                .collect()
        } else {
            rebuild_operands_from_regalloc(opcode, &ra_inst.defs, &ra_inst.uses)?
        };
        let original = if is_regalloc_inserted_pseudo(ra_inst.opcode) {
            None
        } else {
            let indexed = indexed_regalloc_original_candidate(
                &original_insts,
                ra_inst_idx,
                opcode,
                &operands,
            )?;
            if let Some(original) = indexed {
                original_idx = original_idx.max(ra_inst_idx + 1);
                Some(original)
            } else {
                let (matched, next_original_idx) = match_regalloc_original_candidate(
                    &original_insts,
                    original_idx,
                    opcode,
                    &operands,
                )?;
                original_idx = next_original_idx;
                matched
            }
        };
        if let Some(original) = original
            && original.opcode == opcode
        {
            restore_regalloc_opaque_operands(&mut operands, original);
        }
        let mut inst = IrMachInst::with_flags(opcode, operands, ra_inst.flags);
        inst.implicit_defs = leak_pregs(&ra_inst.implicit_defs);
        inst.implicit_uses = leak_pregs(&ra_inst.implicit_uses);
        if let Some(original) = original {
            inst.proof = original.proof;
            inst.source_loc = original.source_loc;
        }
        inst_map.push(Some(InstId(rebuilt_insts.len() as u32)));
        rebuilt_insts.push(inst);
    }

    ir_func.insts = rebuilt_insts;
    let mut rebuilt_blocks = Vec::with_capacity(ra_func.blocks.len());
    for block in &ra_func.blocks {
        let mut insts = Vec::with_capacity(block.insts.len());
        for old_id in &block.insts {
            let mapped = inst_map.get(old_id.0 as usize).ok_or_else(|| {
                PipelineError::InvalidOperand(format!(
                    "regalloc block references unknown instruction {}",
                    old_id.0
                ))
            })?;
            if let Some(new_id) = mapped {
                insts.push(*new_id);
            }
        }
        rebuilt_blocks.push(trust_cg_ir::function::MachBlock {
            insts,
            preds: block.preds.clone(),
            succs: block.succs.clone(),
            loop_depth: block.loop_depth,
        });
    }
    ir_func.blocks = rebuilt_blocks;
    ir_func.block_order = ra_func.block_order.clone();
    ir_func.entry = ra_func.entry_block;
    ir_func.next_vreg = ra_func.next_vreg;
    rebuild_stack_slots_from_regalloc(ir_func, ra_func);

    // NOTE (defect #5, fixed): dense switches that lower to a JumpTable used to
    // fail to encode at O2/O3 with "jump table target block has no byte offset",
    // because the jump-table case blocks are reachable only through the
    // data-driven indirect branch and the CFG round-trips
    // (`rebuild_ir_cfg_edges_from_branch_operands` here, and
    // `cfg_simplify::rebuild_cfg_edges` in the opt pipeline) rebuilt succ/pred
    // edges from explicit `Block` operands only, dropping the targets and then
    // pruning them from `block_order`. Both round-trips now seed the jump-table
    // successor edges from `jump_tables[idx].targets` (referenced by an
    // `Adr ..., JumpTableIndex(idx)` operand) before block order / reachability
    // is recomputed, so the targets stay in `block_order` at their natural
    // layout position. This also fixes the O0 liveness of values live across a
    // back-edge through a jump-table block (defect #6), since liveness propagates
    // through `succs`.

    Ok(inst_map)
}

fn ensure_no_unresolved_vregs(ir_func: &IrMachFunction, phase: &str) -> Result<(), PipelineError> {
    let mut unresolved = Vec::new();

    // Encoding walks the laid-out block stream, not every arena slot or block
    // shell. After CFG cleanup and regalloc-side rebuilding, unreachable
    // blocks can remain in the block arena but be absent from `block_order`;
    // those are not encoded and should not block codegen.
    for &block_id in &ir_func.block_order {
        let block = ir_func.block(block_id);
        for &inst_id in &block.insts {
            let inst = ir_func.inst(inst_id);
            for (operand_idx, operand) in inst.operands.iter().enumerate() {
                if let IrOperand::VReg(vreg) = operand {
                    unresolved.push((inst_id, operand_idx, inst.opcode, *vreg));
                }
            }
        }
    }

    if unresolved.is_empty() {
        return Ok(());
    }

    let preview = unresolved
        .iter()
        .take(8)
        .map(|(inst_id, operand_idx, opcode, vreg)| {
            format!(
                "inst {} {opcode:?} operand {operand_idx} -> {vreg:?}",
                inst_id.0
            )
        })
        .collect::<Vec<_>>()
        .join(", ");
    let suffix = if unresolved.len() > 8 {
        format!("; {} more", unresolved.len() - 8)
    } else {
        String::new()
    };

    Err(PipelineError::RegAlloc(format!(
        "unresolved virtual register(s) after {phase}: {preview}{suffix}"
    )))
}

// ---------------------------------------------------------------------------
// Proof annotation propagation
// ---------------------------------------------------------------------------

/// Convert an adapter-layer [`Proof`](trust_cg_lower::Proof) to the IR-layer
/// [`ProofAnnotation`](trust_cg_ir::ProofAnnotation).
///
/// Some proof variants carry extra metadata that is not represented in the
/// simpler IR annotation enum. Only proof kinds with an exact machine carrier
/// are converted here.
fn proof_to_annotation(proof: &trust_cg_lower::Proof) -> Option<trust_cg_ir::ProofAnnotation> {
    match proof {
        trust_cg_lower::Proof::NoOverflow { signed: true } => {
            Some(trust_cg_ir::ProofAnnotation::NoSignedOverflow)
        }
        trust_cg_lower::Proof::NoOverflow { signed: false } => {
            Some(trust_cg_ir::ProofAnnotation::NoUnsignedOverflow)
        }
        // Synthetic carrier-only seed: maps to the SAME overflow annotation as a genuine on-op
        // `NoOverflow`, so the carrier binder (`apply_guard_proof_annotations`) can stamp the
        // `TrapOverflowExact` carrier. Its distinguishing behaviour (exclusion from the general
        // value-proof loop, closing the over-elimination leak) is enforced in `select_proof_annotation`
        // at the Proof level, BEFORE this conversion — see that function.
        trust_cg_lower::Proof::CarrierNoOverflow { signed: true } => {
            Some(trust_cg_ir::ProofAnnotation::NoSignedOverflow)
        }
        trust_cg_lower::Proof::CarrierNoOverflow { signed: false } => {
            Some(trust_cg_ir::ProofAnnotation::NoUnsignedOverflow)
        }
        trust_cg_lower::Proof::ExactInBounds { .. } => Some(trust_cg_ir::ProofAnnotation::InBounds),
        trust_cg_lower::Proof::InBounds { .. } => None,
        trust_cg_lower::Proof::NotNull { .. } => Some(trust_cg_ir::ProofAnnotation::NotNull),
        trust_cg_lower::Proof::ValidBorrow { .. } => {
            Some(trust_cg_ir::ProofAnnotation::ValidBorrow)
        }
        trust_cg_lower::Proof::NonZeroDivisor { .. } => {
            Some(trust_cg_ir::ProofAnnotation::NonZeroDivisor)
        }
        trust_cg_lower::Proof::ValidShift { .. } => Some(trust_cg_ir::ProofAnnotation::ValidShift),
        trust_cg_lower::Proof::Pure => Some(trust_cg_ir::ProofAnnotation::Pure),
        trust_cg_lower::Proof::Associative => Some(trust_cg_ir::ProofAnnotation::Associative),
        trust_cg_lower::Proof::Commutative => Some(trust_cg_ir::ProofAnnotation::Commutative),
        trust_cg_lower::Proof::Idempotent => Some(trust_cg_ir::ProofAnnotation::Idempotent),
        // InRange has no direct annotation counterpart — the range info
        // cannot be expressed in the single-variant ProofAnnotation. We
        // skip it here; range-based opts use the full ProofContext.
        trust_cg_lower::Proof::InRange { .. } => None,
        // A declared refinement is a fact about a VALUE, not a producer safety claim about an
        // instruction, and it is deliberately NOT representable as a `ProofAnnotation`: stamping
        // one would let a type-level fact masquerade as an eliminable proof label on whatever
        // instruction happened to define the value. Its only consumer is the lattice, which
        // re-decides it against the exact guard it might discharge — see
        // `install_lattice_guard_authority`.
        trust_cg_lower::Proof::Refinement { .. } => None,
    }
}

fn proof_annotation_priority(annotation: trust_cg_ir::ProofAnnotation, opcode: IrOpcode) -> u8 {
    use trust_cg_ir::ProofAnnotation as Proof;

    match annotation {
        Proof::NoOverflow | Proof::NoSignedOverflow | Proof::NoUnsignedOverflow => match opcode {
            IrOpcode::AddsRR | IrOpcode::AddsRI | IrOpcode::SubsRR | IrOpcode::SubsRI => 100,
            _ => 80,
        },
        Proof::InBounds => match opcode {
            IrOpcode::TrapBoundsCheckExact => 100,
            _ => 80,
        },
        Proof::NonZeroDivisor => match opcode {
            // Self-contained carrier (production) ranks highest; legacy CmpRI pair retained.
            IrOpcode::TrapDivZeroIfZero => 100,
            IrOpcode::CmpRI => 90,
            _ => 80,
        },
        Proof::ValidShift => match opcode {
            // Self-contained carrier (production) ranks highest; legacy CmpRI/bare-trap retained.
            IrOpcode::TrapShiftRangeIfOOB => 100,
            IrOpcode::CmpRI | IrOpcode::TrapShiftRange => 90,
            _ => 80,
        },
        Proof::NotNull => match opcode {
            IrOpcode::TrapNullIfZero => 100,
            _ => 80,
        },
        Proof::ValidBorrow | Proof::Pure | Proof::PositiveRefCount => 70,
        Proof::Associative | Proof::Commutative | Proof::Idempotent => 10,
    }
}

fn requires_guard_binding(annotation: trust_cg_ir::ProofAnnotation) -> bool {
    matches!(
        annotation,
        trust_cg_ir::ProofAnnotation::InBounds
            | trust_cg_ir::ProofAnnotation::NotNull
            | trust_cg_ir::ProofAnnotation::NonZeroDivisor
            | trust_cg_ir::ProofAnnotation::ValidShift
    )
}

/// True for the overflow proof annotations the self-contained `TrapOverflowExact` carrier consumes.
///
/// Unlike [`requires_guard_binding`], these are NOT excluded from the general value-proof loop
/// (`select_proof_annotation`): the legacy entangled overflow path still annotates the flag-setting
/// ADDS/SUBS via that loop, EXACTLY as before. They are bound to the DECOUPLED carrier IN ADDITION,
/// by [`apply_guard_proof_annotations`], so adding the carrier never regresses the legacy path. The
/// two are not mutually exclusive: a decoupled carrier function has no ADDS for the general loop to
/// match, and the legacy ADDS function has no `TrapOverflowExact` for the guard binder to match.
fn binds_to_overflow_carrier(annotation: trust_cg_ir::ProofAnnotation) -> bool {
    matches!(
        annotation,
        trust_cg_ir::ProofAnnotation::NoSignedOverflow
            | trust_cg_ir::ProofAnnotation::NoUnsignedOverflow
    )
}

/// True for the SYNTHETIC carrier-only overflow seed (`Proof::CarrierNoOverflow`).
///
/// This is the leak-closing discriminator. The genuine on-op [`trust_cg_lower::Proof::NoOverflow`]
/// (keyed to an arithmetic op's OWN result) is NOT carrier-only and stays eligible for the general
/// value-proof loop, preserving legacy ADDS/SUBS→ADD/SUB overflow elimination. The synthetic seed
/// (keyed to a carrier's OPERAND vregs by `translate_overflow`) IS carrier-only and is excluded from
/// the general loop, so it can never be stamped onto an operand's defining instruction and authorize
/// deleting an unrelated operation's overflow check. The two produce the SAME `ProofAnnotation`, so
/// they cannot be distinguished post-conversion — the filter MUST operate at the `Proof` level here.
fn is_carrier_only_proof(proof: &trust_cg_lower::Proof) -> bool {
    matches!(proof, trust_cg_lower::Proof::CarrierNoOverflow { .. })
}

fn select_proof_annotation(
    proofs: &[trust_cg_lower::Proof],
    opcode: IrOpcode,
) -> Option<trust_cg_ir::ProofAnnotation> {
    proofs
        .iter()
        // Carrier-only seeds are consumed exclusively by the operand-sensitive carrier binder
        // (`apply_guard_proof_annotations`); they MUST NOT reach a value's defining instruction here.
        .filter(|proof| !is_carrier_only_proof(proof))
        .filter_map(proof_to_annotation)
        .filter(|annotation| !requires_guard_binding(*annotation))
        .max_by_key(|annotation| proof_annotation_priority(*annotation, opcode))
}

fn value_map_vreg(
    value: &trust_cg_lower::instructions::Value,
    value_map: &std::collections::HashMap<
        trust_cg_lower::instructions::Value,
        trust_cg_lower::isel::ISelOperand,
    >,
) -> Option<VReg> {
    match value_map.get(value) {
        Some(trust_cg_lower::isel::ISelOperand::VReg(vreg)) => Some(*vreg),
        _ => None,
    }
}

fn operand_vreg(inst: &IrMachInst, idx: usize) -> Option<VReg> {
    match inst.operands.get(idx) {
        Some(IrOperand::VReg(vreg)) => Some(*vreg),
        _ => None,
    }
}

fn operand_imm(inst: &IrMachInst, idx: usize) -> Option<i64> {
    match inst.operands.get(idx) {
        Some(IrOperand::Imm(imm)) => Some(*imm),
        _ => None,
    }
}

fn next_opcode(
    ir_func: &IrMachFunction,
    block_insts: &[trust_cg_ir::types::InstId],
    pos: usize,
) -> Option<IrOpcode> {
    block_insts
        .get(pos + 1)
        .map(|next_id| ir_func.inst(*next_id).opcode)
}

fn bcond_has_condition(inst: &IrMachInst, condition: trust_cg_ir::CondCode) -> bool {
    inst.opcode == IrOpcode::BCond
        && matches!(
            inst.operands.first(),
            Some(IrOperand::Imm(cond)) if *cond == i64::from(condition.encoding())
        )
}

fn next_is_bcond_with_condition(
    ir_func: &IrMachFunction,
    block_insts: &[trust_cg_ir::types::InstId],
    pos: usize,
    condition: trust_cg_ir::CondCode,
) -> bool {
    block_insts
        .get(pos + 1)
        .is_some_and(|next_id| bcond_has_condition(ir_func.inst(*next_id), condition))
}

fn proof_matches_guard_shape(
    ir_func: &IrMachFunction,
    block_insts: &[trust_cg_ir::types::InstId],
    pos: usize,
    vreg: VReg,
    proof: &trust_cg_lower::Proof,
    value_map: &std::collections::HashMap<
        trust_cg_lower::instructions::Value,
        trust_cg_lower::isel::ISelOperand,
    >,
) -> Option<trust_cg_ir::ProofAnnotation> {
    let inst = ir_func.inst(block_insts[pos]);
    match proof {
        trust_cg_lower::Proof::ExactInBounds { base, index, bound } => {
            let base_vreg = value_map_vreg(base, value_map)?;
            let index_vreg = value_map_vreg(index, value_map)?;
            if inst.opcode == IrOpcode::TrapBoundsCheckExact
                && operand_vreg(inst, 0) == Some(base_vreg)
                && operand_vreg(inst, 1) == Some(index_vreg)
                && operand_imm(inst, 2) == Some(*bound as i64)
            {
                Some(trust_cg_ir::ProofAnnotation::InBounds)
            } else {
                None
            }
        }
        trust_cg_lower::Proof::InBounds { .. } => None,
        trust_cg_lower::Proof::NotNull { .. } => match inst.opcode {
            IrOpcode::TrapNullIfZero if operand_vreg(inst, 0) == Some(vreg) => {
                Some(trust_cg_ir::ProofAnnotation::NotNull)
            }
            _ => None,
        },
        trust_cg_lower::Proof::NoOverflow { signed } => {
            // Production carrier: self-contained `TrapOverflowExact lhs, rhs, Imm(op_tag)`. The proof
            // binds only when (a) the carrier references the proven vreg as lhs OR rhs, AND (b) the
            // carrier's op-tag SIGNEDNESS matches the proof's `signed` flag. This signedness check is
            // soundness-critical: a signed-overflow proof must NEVER annotate an unsigned-overflow
            // carrier (and vice versa), since their overflow conditions differ. The legacy entangled
            // ADDS/SUBS path is NOT matched here — it flows through the unchanged value-proof
            // propagation onto the flag-setting ADDS/SUBS, exactly as before.
            if inst.opcode != IrOpcode::TrapOverflowExact {
                return None;
            }
            if operand_vreg(inst, 0) != Some(vreg) && operand_vreg(inst, 1) != Some(vreg) {
                return None;
            }
            let tag = operand_imm(inst, 2)?;
            let (op, _width) = trust_cg_ir::unpack_overflow_tag(tag)?;
            let op_is_signed = matches!(
                op,
                trust_cg_ir::OverflowOp::SignedAdd
                    | trust_cg_ir::OverflowOp::SignedSub
                    | trust_cg_ir::OverflowOp::SignedMul
            );
            if op_is_signed != *signed {
                return None;
            }
            Some(if *signed {
                trust_cg_ir::ProofAnnotation::NoSignedOverflow
            } else {
                trust_cg_ir::ProofAnnotation::NoUnsignedOverflow
            })
        }
        trust_cg_lower::Proof::CarrierNoOverflow { signed } => {
            // Synthetic carrier-only seed from the `Inst::Overflow` auto-rewrite. Binds EXACTLY like
            // the genuine `NoOverflow` arm above — operand-sensitive, signedness-checked — but is
            // sourced ONLY by `translate_overflow` seeding the carrier's operand vregs, and (unlike
            // `NoOverflow`) is excluded from the general value-proof loop by `select_proof_annotation`
            // so it can never leak onto an operand's defining ADDS/SUBS. The signedness check is
            // soundness-critical: a signed seed must NEVER annotate an unsigned carrier or vice versa.
            if inst.opcode != IrOpcode::TrapOverflowExact {
                return None;
            }
            if operand_vreg(inst, 0) != Some(vreg) && operand_vreg(inst, 1) != Some(vreg) {
                return None;
            }
            let tag = operand_imm(inst, 2)?;
            let (op, _width) = trust_cg_ir::unpack_overflow_tag(tag)?;
            let op_is_signed = matches!(
                op,
                trust_cg_ir::OverflowOp::SignedAdd
                    | trust_cg_ir::OverflowOp::SignedSub
                    | trust_cg_ir::OverflowOp::SignedMul
            );
            if op_is_signed != *signed {
                return None;
            }
            Some(if *signed {
                trust_cg_ir::ProofAnnotation::NoSignedOverflow
            } else {
                trust_cg_ir::ProofAnnotation::NoUnsignedOverflow
            })
        }
        trust_cg_lower::Proof::NonZeroDivisor { .. } => match inst.opcode {
            // Production carrier: self-contained `TrapDivZeroIfZero divisor` (the DivZero mirror of
            // the NotNull `TrapNullIfZero ptr` arm above). The proven-nonzero divisor IS the carrier's
            // operand 0, so the binding is operand-sensitive — never inferred from nearby shape.
            IrOpcode::TrapDivZeroIfZero if operand_vreg(inst, 0) == Some(vreg) => {
                Some(trust_cg_ir::ProofAnnotation::NonZeroDivisor)
            }
            // Legacy CmpRI+TrapDivZero pair (no longer emitted by the production ISel; retained).
            IrOpcode::CmpRI
                if operand_vreg(inst, 0) == Some(vreg)
                    && operand_imm(inst, 1) == Some(0)
                    && next_opcode(ir_func, block_insts, pos) == Some(IrOpcode::TrapDivZero) =>
            {
                Some(trust_cg_ir::ProofAnnotation::NonZeroDivisor)
            }
            _ => None,
        },
        trust_cg_lower::Proof::ValidShift { bitwidth, .. } => {
            let bitwidth = i64::from(*bitwidth);
            match inst.opcode {
                // Production carrier: self-contained `TrapShiftRangeIfOOB amount, Imm(bitwidth)` (the
                // ShiftRange mirror of the InBounds `TrapBoundsCheckExact` arm). The proven-in-range
                // amount IS operand 0 and the width IS operand 1 — operand-sensitive, never inferred.
                IrOpcode::TrapShiftRangeIfOOB
                    if operand_vreg(inst, 0) == Some(vreg)
                        && operand_imm(inst, 1) == Some(bitwidth) =>
                {
                    Some(trust_cg_ir::ProofAnnotation::ValidShift)
                }
                // Legacy CmpRI + (TrapShiftRange | B.HS) pair (no longer emitted; retained).
                IrOpcode::CmpRI
                    if operand_vreg(inst, 0) == Some(vreg)
                        && operand_imm(inst, 1) == Some(bitwidth)
                        && (next_opcode(ir_func, block_insts, pos)
                            == Some(IrOpcode::TrapShiftRange)
                            || next_is_bcond_with_condition(
                                ir_func,
                                block_insts,
                                pos,
                                trust_cg_ir::CondCode::HS,
                            )) =>
                {
                    Some(trust_cg_ir::ProofAnnotation::ValidShift)
                }
                _ => None,
            }
        }
        _ => None,
    }
}

fn apply_guard_proof_annotations(
    ir_func: &mut IrMachFunction,
    proof_ctx: &trust_cg_lower::ProofContext,
    value_map: &std::collections::HashMap<
        trust_cg_lower::instructions::Value,
        trust_cg_lower::isel::ISelOperand,
    >,
) {
    let mut bindings = Vec::new();
    for (value, proofs) in &proof_ctx.value_proofs {
        let Some(vreg) = value_map_vreg(value, value_map) else {
            continue;
        };
        for proof in proofs {
            // Guard-bound safety facts (bounds/null/div/shift) AND the overflow carrier proofs both
            // bind to operand-sensitive carriers here. A genuine on-op `NoOverflow` remains ALSO
            // eligible for the general value-proof loop (the legacy ADDS/SUBS path stays intact); the
            // SYNTHETIC `CarrierNoOverflow` seed is consumed ONLY here (it is excluded from the general
            // loop by `select_proof_annotation`), which is what closes the over-elimination leak.
            // Both map to `NoSignedOverflow`/`NoUnsignedOverflow`, so `binds_to_overflow_carrier`
            // admits each into the carrier binder.
            if proof_to_annotation(proof)
                .is_some_and(|a| requires_guard_binding(a) || binds_to_overflow_carrier(a))
            {
                bindings.push((value.0, vreg, proof.clone()));
            }
        }
    }
    bindings.sort_by_key(|(value, vreg, proof)| {
        let annotation_rank = match proof_to_annotation(proof) {
            Some(trust_cg_ir::ProofAnnotation::InBounds) => 0,
            Some(trust_cg_ir::ProofAnnotation::NotNull) => 1,
            Some(trust_cg_ir::ProofAnnotation::NonZeroDivisor) => 2,
            Some(trust_cg_ir::ProofAnnotation::ValidShift) => 3,
            _ => 4,
        };
        (*value, vreg.id, annotation_rank)
    });

    let block_insts: Vec<Vec<_>> = ir_func
        .blocks
        .iter()
        .map(|block| block.insts.clone())
        .collect();
    let mut annotations = Vec::new();
    for (_, vreg, proof) in bindings {
        for insts in &block_insts {
            for pos in 0..insts.len() {
                if let Some(annotation) =
                    proof_matches_guard_shape(ir_func, insts, pos, vreg, &proof, value_map)
                {
                    annotations.push((insts[pos], annotation));
                }
            }
        }
    }

    annotations.sort_by_key(|(inst_id, annotation)| {
        let annotation_rank = match annotation {
            trust_cg_ir::ProofAnnotation::InBounds => 0,
            trust_cg_ir::ProofAnnotation::NotNull => 1,
            trust_cg_ir::ProofAnnotation::NonZeroDivisor => 2,
            trust_cg_ir::ProofAnnotation::ValidShift => 3,
            _ => 4,
        };
        (inst_id.0, annotation_rank)
    });
    annotations.dedup();

    for (inst_id, annotation) in annotations {
        let inst = ir_func.inst_mut(inst_id);
        if inst.proof.is_none() {
            inst.proof = Some(annotation);
        }
    }
}

/// Whether the fail-closed guard policy is enforced.
///
/// This is deliberately unconditional.  `TRUST_CG_GUARD_KERNEL_GATE` used to select between the
/// kernel and a weaker label-only path; either spelling could therefore become a policy bypass.  The
/// production optimizer now always installs an empty-authority kernel gate until exact validator
/// replay is wired, so every carrier is kept and expanded to a runtime check.
pub(crate) fn guard_kernel_gate_enabled() -> bool {
    true
}

/// Build the production AArch64 guard gate.
///
/// Producer-owned status, lineage, `ProofRef` labels and synthesized ids remain report metadata:
/// they contribute NOTHING here, exactly as before. The one thing that does contribute is a
/// [`trust_cg_lower::lattice_guard::LatticeBoundsCapability`] — a decidable, obligation-bound,
/// replayable authorization minted by trust-ir's own solver-free `implies`. See
/// [`install_lattice_guard_authority`].
///
/// Returning `Some` is load-bearing: `None` would select the legacy label-only optimizer.
fn build_guard_kernel_gate(
    ir_func: &mut IrMachFunction,
    isel_func: &trust_cg_lower::isel::ISelFunction,
    proof_ctx: Option<&trust_cg_lower::ProofContext>,
    _trust_ir_module: Option<&trust_ir::Module>,
) -> Option<(
    trust_cg_ir::DischargedEvidenceTable,
    std::collections::HashMap<InstId, (u128, Option<u128>)>,
)> {
    // Start from the fail-closed production position: empty evidence AND empty bindings, so even a
    // forged matching pair cannot reach `decide`.
    let mut evidence = trust_cg_lower::guard_evidence::production_guard_replay_evidence();
    let mut obligations: std::collections::HashMap<InstId, (u128, Option<u128>)> =
        std::collections::HashMap::new();

    if let Some(ctx) = proof_ctx {
        install_lattice_guard_authority(ir_func, isel_func, ctx, &mut evidence, &mut obligations);
    }

    Some((evidence, obligations))
}

/// **The payoff, wired.** Turn every replayed lattice capability into kernel evidence bound to the
/// exact carrier it was certified for.
///
/// Four independent conditions must ALL hold before a single carrier is bound. Any one failing
/// leaves the carrier untouched, so it expands to a runtime bounds check exactly as today:
///
/// 1. **Authority.** `lattice_guard_replay_authority_available()` — the `lattice-guard-elision`
///    Cargo feature. A default build returns here having done nothing at all.
/// 2. **Replay.** Every capability is re-decided from scratch against the module's interned
///    predicate/universe tables, and both of its ids re-derived. A capability that does not
///    reproduce is discarded (and does not disable the others — it simply is not authority).
/// 3. **Carrier binding.** The ISel recorded `fingerprint -> obligation id` in
///    `guard_obligations`, keyed by the operand fingerprint the kernel itself computes. We
///    re-derive that fingerprint from the LIVE MachInst and look it up; a carrier whose operands
///    do not fingerprint to a lattice obligation is not bound.
/// 4. **Kernel + re-check.** Binding only fills the receipt slot. `trust_cg_ir::decide` still has
///    to authorize, and the independent operand re-check still has to re-justify, or the compile
///    fails closed.
///
/// The `ProofAnnotation::InBounds` stamp is applied to EXACTLY the carriers bound in (3) — never
/// broadcast — because the proof-consuming pass dispatches on it. Stamping is therefore not an
/// authority grant: an annotated carrier with no kernel-authorized obligation is still kept.
fn install_lattice_guard_authority(
    ir_func: &mut IrMachFunction,
    isel_func: &trust_cg_lower::isel::ISelFunction,
    proof_ctx: &trust_cg_lower::ProofContext,
    evidence: &mut trust_cg_ir::DischargedEvidenceTable,
    obligations: &mut std::collections::HashMap<InstId, (u128, Option<u128>)>,
) {
    use trust_cg_ir::GuardTarget;
    use trust_cg_lower::lattice_guard;

    // (1) Authority.
    if !lattice_guard::lattice_guard_replay_authority_available() {
        return;
    }
    if proof_ctx.lattice_bounds_capabilities.is_empty() || isel_func.guard_obligations.is_empty() {
        return;
    }

    // (2) Replay every capability against the module's own tables, then index by obligation id.
    let env = &proof_ctx.refinement_env;
    let mut replayed: std::collections::HashMap<u64, u128> = std::collections::HashMap::new();
    for capability in &proof_ctx.lattice_bounds_capabilities {
        if capability.replay(env) {
            replayed.insert(capability.obligation_id(), capability.lineage_digest());
        }
    }
    if replayed.is_empty() {
        return;
    }

    // (3) Bind carriers whose re-derived operand fingerprint names a replayed lattice obligation.
    let target = trust_cg_ir::AArch64GuardTarget;
    let mut bound: Vec<InstId> = Vec::new();
    for idx in 0..ir_func.insts.len() {
        let inst_id = InstId(idx as u32);
        let Some(kind) = target.classify_carrier(ir_func.inst(inst_id)) else {
            continue;
        };
        // Only the bounds-guard family is lattice-certifiable today; every other guard kind stays
        // exactly as fail-closed as it was.
        if kind != trust_cg_ir::GuardKind::BoundsCheck {
            continue;
        }
        let identity = target.operand_identity(ir_func.inst(inst_id));
        let fingerprint = trust_cg_ir::fingerprint_for_kind(kind, &identity.operands);
        let Some(&obligation_id) = isel_func.guard_obligations.get(&fingerprint) else {
            continue;
        };
        // Defence in depth: only ids minted by the lattice, and only ones that replayed.
        if !lattice_guard::is_lattice_obligation_id(obligation_id) {
            continue;
        }
        let Some(&lineage) = replayed.get(&obligation_id) else {
            continue;
        };
        evidence.insert(
            u128::from(obligation_id),
            trust_cg_ir::DischargeStatus::Certified,
            Some(lineage),
        );
        obligations.insert(inst_id, (u128::from(obligation_id), Some(lineage)));
        bound.push(inst_id);
    }

    // Stamp the annotation on exactly the bound carriers so the proof pass reaches them.
    for inst_id in bound {
        let inst = ir_func.inst_mut(inst_id);
        if inst.proof.is_none() {
            inst.proof = Some(trust_cg_ir::ProofAnnotation::InBounds);
        }
    }
}

/// Propagate proof annotations from the adapter's [`ProofContext`](trust_cg_lower::ProofContext)
/// onto machine instructions in the IR function.
///
/// Uses the ISel value map to resolve LIR Values to VRegs, then builds a
/// reverse map (VReg ID -> InstId) to locate the defining instruction for
/// each value and annotate it with the appropriate [`ProofAnnotation`].
///
/// Function-level proofs (Pure, Associative, etc.) are stored on the
/// [`MachFunction::function_proofs`] field.
fn apply_proof_annotations(
    ir_func: &mut IrMachFunction,
    proof_ctx: &trust_cg_lower::ProofContext,
    value_map: &std::collections::HashMap<
        trust_cg_lower::instructions::Value,
        trust_cg_lower::isel::ISelOperand,
    >,
) {
    // Build reverse map: VReg -> unique defining InstId. Use the shared
    // def/use classifier so first-operand uses such as CMP/STR/branches are
    // never mistaken for definitions. If a VReg has multiple defs, mark it
    // ambiguous and skip proof binding rather than guessing.
    let vreg_to_inst = vreg_defining_insts(ir_func);

    // The production caller invokes this helper only after acquiring exact replay authority.  Unit
    // tests call it directly to exercise the structural binding model.
    apply_guard_proof_annotations(ir_func, proof_ctx, value_map);

    // Propagate remaining per-value proofs onto defining instructions.
    for (value, proofs) in &proof_ctx.value_proofs {
        if let Some(vreg) = value_map_vreg(value, value_map)
            && let Some(Some(inst_id)) = vreg_to_inst.get(&vreg).copied()
        {
            let opcode = ir_func.inst(inst_id).opcode;
            if let Some(annotation) = select_proof_annotation(proofs, opcode) {
                let inst = ir_func.inst_mut(inst_id);
                // Only set if no annotation is already present (ISel may
                // have set one, and we do not want to overwrite).
                if inst.proof.is_none() {
                    inst.proof = Some(annotation);
                }
            }
        }
    }

    // Propagate function-level proofs onto MachFunction metadata.
    for proof in proof_ctx.function_proofs() {
        if let Some(annotation) = proof_to_annotation(proof) {
            ir_func.function_proofs.push(annotation);
        }
    }

    // Thread `noalias` pointer-parameter attributes onto the MachFunction so the
    // `neon-map` store vectorizer can prove store/load non-aliasing. The ISel
    // binds formal parameter `i` to `Value(i)`; resolve each noalias param index
    // through the value map to its machine vreg. Under-resolution is safe (the
    // pass BAILS); only proven-noalias params ever reach this list.
    for &param_index in &proof_ctx.noalias_param_indices {
        let value = trust_cg_lower::instructions::Value(param_index as u32);
        if let Some(vreg) = value_map_vreg(&value, value_map)
            && !ir_func.noalias_params.contains(&vreg.id)
        {
            ir_func.noalias_params.push(vreg.id);
        }
    }
}

fn vreg_defining_insts(
    ir_func: &IrMachFunction,
) -> std::collections::HashMap<VReg, Option<InstId>> {
    let mut vreg_to_inst: std::collections::HashMap<VReg, Option<InstId>> =
        std::collections::HashMap::new();
    for (idx, inst) in ir_func.insts.iter().enumerate() {
        let (def_positions, _) = classify_operand_positions(inst);
        for pos in def_positions {
            if let Some(IrOperand::VReg(vreg)) = inst.operands.get(pos) {
                vreg_to_inst
                    .entry(*vreg)
                    .and_modify(|slot| *slot = None)
                    .or_insert(Some(InstId(idx as u32)));
            }
        }
    }
    vreg_to_inst
}

fn proof_optimization_metadata_from_context(
    ir_func: &IrMachFunction,
    proof_ctx: &trust_cg_lower::ProofContext,
    value_map: &std::collections::HashMap<
        trust_cg_lower::instructions::Value,
        trust_cg_lower::isel::ISelOperand,
    >,
) -> trust_cg_opt::proof_opts::ProofOptimizationMetadata {
    let mut metadata = trust_cg_opt::proof_opts::ProofOptimizationMetadata::new();
    for (inst_id, facts) in
        proof_optimization_facts_by_inst_from_context(ir_func, proof_ctx, value_map)
    {
        metadata.set_inst_proof_facts(inst_id, facts);
    }

    metadata
}

fn proof_optimization_metadata_from_isel_facts(
    isel_func: &trust_cg_lower::isel::ISelFunction,
) -> trust_cg_opt::proof_opts::ProofOptimizationMetadata {
    let mut metadata = trust_cg_opt::proof_opts::ProofOptimizationMetadata::new();
    let mut next_inst_id = 0_u32;

    for block_ref in &isel_func.block_order {
        let Some(block) = isel_func.blocks.get(block_ref) else {
            continue;
        };
        for idx in 0..block.insts.len() {
            if let Some(facts) = block.proof_facts.get(idx)
                && !facts.is_empty()
            {
                metadata.set_inst_proof_facts(InstId(next_inst_id), facts.clone());
            }
            next_inst_id += 1;
        }
    }

    metadata
}

fn merge_proof_optimization_metadata(
    base: &mut trust_cg_opt::proof_opts::ProofOptimizationMetadata,
    extra: trust_cg_opt::proof_opts::ProofOptimizationMetadata,
) {
    for (inst_id, facts) in extra.proof_facts() {
        let mut merged = base.inst_proof_facts(*inst_id).to_vec();
        for fact in facts {
            if !merged.contains(fact) {
                merged.push(*fact);
            }
        }
        base.set_inst_proof_facts(*inst_id, merged);
    }
}

fn proof_optimization_facts_by_inst_from_context(
    ir_func: &IrMachFunction,
    proof_ctx: &trust_cg_lower::ProofContext,
    value_map: &std::collections::HashMap<
        trust_cg_lower::instructions::Value,
        trust_cg_lower::isel::ISelOperand,
    >,
) -> BTreeMap<InstId, Vec<trust_cg_ir::ProofFact>> {
    let vreg_to_inst = vreg_defining_insts(ir_func);
    let mut facts_by_inst: BTreeMap<InstId, Vec<trust_cg_ir::ProofFact>> = BTreeMap::new();
    let mut sorted_facts_by_inst: BTreeMap<InstId, Vec<trust_cg_ir::ProofFact>> = BTreeMap::new();
    let function_vectorization_facts: Vec<_> = proof_ctx
        .function_facts()
        .iter()
        .copied()
        .map(trust_cg_ir::ProofFact::from)
        .filter(is_vectorization_function_proof_fact)
        .collect();
    if !function_vectorization_facts.is_empty() {
        for idx in 0..ir_func.insts.len() {
            facts_by_inst
                .entry(InstId(idx as u32))
                .or_default()
                .extend(function_vectorization_facts.iter().copied());
        }
    }

    for (value, facts) in &proof_ctx.value_facts {
        let Some(vreg) = value_map_vreg(value, value_map) else {
            continue;
        };
        let ir_facts: Vec<trust_cg_ir::ProofFact> = facts
            .iter()
            .copied()
            .map(trust_cg_ir::ProofFact::from)
            .collect();
        if ir_facts.is_empty() {
            continue;
        }
        let aligned_facts: Vec<trust_cg_ir::ProofFact> = ir_facts
            .iter()
            .copied()
            .filter(|fact| matches!(fact, trust_cg_ir::ProofFact::Aligned(_)))
            .collect();
        let vectorization_facts: Vec<trust_cg_ir::ProofFact> = ir_facts
            .iter()
            .copied()
            .filter(is_vectorization_operand_proof_fact)
            .collect();

        let mut inst_ids = BTreeSet::new();
        if let Some(Some(inst_id)) = vreg_to_inst.get(&vreg).copied() {
            inst_ids.insert(inst_id);
        }

        for (idx, inst) in ir_func.insts.iter().enumerate() {
            let inst_id = InstId(idx as u32);
            if inst.proof.is_none() {
                if inst.operands.iter().any(
                    |operand| matches!(operand, IrOperand::VReg(operand_vreg) if *operand_vreg == vreg),
                ) && !vectorization_facts.is_empty()
                {
                    facts_by_inst
                        .entry(inst_id)
                        .or_default()
                        .extend(vectorization_facts.iter().copied());
                }
                let memory_aligned_facts = aligned_pair_memory_facts_for_base(
                    ir_func,
                    &vreg_to_inst,
                    inst,
                    vreg,
                    &aligned_facts,
                );
                if !memory_aligned_facts.is_empty() {
                    facts_by_inst
                        .entry(inst_id)
                        .or_default()
                        .extend(memory_aligned_facts);
                }
                continue;
            }
            if inst.operands.iter().any(
                |operand| matches!(operand, IrOperand::VReg(operand_vreg) if *operand_vreg == vreg),
            ) {
                inst_ids.insert(inst_id);
            }
            let memory_aligned_facts = aligned_pair_memory_facts_for_base(
                ir_func,
                &vreg_to_inst,
                inst,
                vreg,
                &aligned_facts,
            );
            if !memory_aligned_facts.is_empty() {
                facts_by_inst
                    .entry(inst_id)
                    .or_default()
                    .extend(memory_aligned_facts);
            }
        }

        for inst_id in inst_ids {
            facts_by_inst
                .entry(inst_id)
                .or_default()
                .extend(ir_facts.iter().copied());
        }
    }

    for (inst_id, mut facts) in facts_by_inst {
        facts.sort_by_key(|fact| {
            (
                fact.stable_name(),
                match fact {
                    trust_cg_ir::ProofFact::Aligned(bytes) => Some(*bytes),
                    trust_cg_ir::ProofFact::BoundedLoop(bound) => Some(*bound),
                    _ => None,
                },
                match fact {
                    trust_cg_ir::ProofFact::DivergenceClass(divergence) => Some(match divergence {
                        trust_cg_ir::ProofDivergence::Uniform => 0_u8,
                        trust_cg_ir::ProofDivergence::Low => 1,
                        trust_cg_ir::ProofDivergence::High => 2,
                    }),
                    _ => None,
                },
            )
        });
        facts.dedup();
        sorted_facts_by_inst.insert(inst_id, facts);
    }

    sorted_facts_by_inst
}

fn is_vectorization_function_proof_fact(fact: &trust_cg_ir::ProofFact) -> bool {
    matches!(
        fact,
        trust_cg_ir::ProofFact::BoundedLoop(_)
            | trust_cg_ir::ProofFact::Monotonic
            | trust_cg_ir::ProofFact::ParallelMap
    )
}

fn is_vectorization_operand_proof_fact(fact: &trust_cg_ir::ProofFact) -> bool {
    matches!(
        fact,
        trust_cg_ir::ProofFact::InBounds
            | trust_cg_ir::ProofFact::NoAlias
            | trust_cg_ir::ProofFact::BoundedLoop(_)
            | trust_cg_ir::ProofFact::Monotonic
            | trust_cg_ir::ProofFact::ParallelMap
    )
}

fn aligned_pair_memory_facts_for_base(
    ir_func: &IrMachFunction,
    vreg_to_inst: &std::collections::HashMap<VReg, Option<InstId>>,
    inst: &IrMachInst,
    vreg: VReg,
    aligned_facts: &[trust_cg_ir::ProofFact],
) -> Vec<trust_cg_ir::ProofFact> {
    let Some((base, offset)) = aligned_pair_scalar_base_vreg_and_offset(inst) else {
        return Vec::new();
    };
    let total_offset = if base == vreg {
        offset
    } else {
        let Some((add_base, add_offset)) =
            unique_gpr64_offset_base_and_offset(ir_func, vreg_to_inst, base)
        else {
            return Vec::new();
        };
        if add_base != vreg {
            return Vec::new();
        }
        let Some(total_offset) = add_offset.checked_add(offset) else {
            return Vec::new();
        };
        total_offset
    };

    aligned_facts
        .iter()
        .filter_map(|fact| match fact {
            trust_cg_ir::ProofFact::Aligned(bytes) if *bytes > 0 => {
                let derived = if total_offset == 0 {
                    *bytes
                } else {
                    gcd_u64(*bytes, total_offset.unsigned_abs())
                };
                (derived >= 16).then_some(trust_cg_ir::ProofFact::Aligned(derived))
            }
            _ => None,
        })
        .collect()
}

fn unique_gpr64_offset_base_and_offset(
    ir_func: &IrMachFunction,
    vreg_to_inst: &std::collections::HashMap<VReg, Option<InstId>>,
    temp: VReg,
) -> Option<(VReg, i64)> {
    unique_gpr64_addri_base_and_offset(ir_func, vreg_to_inst, temp)
        .or_else(|| unique_gpr64_madd_const_offset_base_and_offset(ir_func, vreg_to_inst, temp))
}

fn gcd_u64(mut lhs: u64, mut rhs: u64) -> u64 {
    while rhs != 0 {
        let next = lhs % rhs;
        lhs = rhs;
        rhs = next;
    }
    lhs
}

fn aligned_pair_scalar_base_vreg_and_offset(inst: &IrMachInst) -> Option<(VReg, i64)> {
    if !matches!(inst.opcode, IrOpcode::LdrRI | IrOpcode::StrRI) {
        return None;
    }
    let offset = match inst.operands.get(2) {
        Some(IrOperand::Imm(offset)) => *offset,
        None => 0,
        _ => return None,
    };
    match inst.operands.get(1) {
        Some(IrOperand::VReg(vreg)) if vreg.class == RegClass::Gpr64 => Some((*vreg, offset)),
        _ => None,
    }
}

fn unique_gpr64_addri_base_and_offset(
    ir_func: &IrMachFunction,
    vreg_to_inst: &std::collections::HashMap<VReg, Option<InstId>>,
    temp: VReg,
) -> Option<(VReg, i64)> {
    if temp.class != RegClass::Gpr64 {
        return None;
    }
    let Some(Some(def_id)) = vreg_to_inst.get(&temp).copied() else {
        return None;
    };
    let add = ir_func.insts.get(def_id.0 as usize)?;
    if add.opcode != IrOpcode::AddRI {
        return None;
    }

    match (
        add.operands.first(),
        add.operands.get(1),
        add.operands.get(2),
    ) {
        (Some(IrOperand::VReg(dst)), Some(IrOperand::VReg(base)), Some(IrOperand::Imm(offset)))
            if *dst == temp && dst.class == RegClass::Gpr64 && base.class == RegClass::Gpr64 =>
        {
            Some((*base, *offset))
        }
        _ => None,
    }
}

fn unique_gpr64_madd_const_offset_base_and_offset(
    ir_func: &IrMachFunction,
    vreg_to_inst: &std::collections::HashMap<VReg, Option<InstId>>,
    temp: VReg,
) -> Option<(VReg, i64)> {
    if temp.class != RegClass::Gpr64 {
        return None;
    }
    let Some(Some(def_id)) = vreg_to_inst.get(&temp).copied() else {
        return None;
    };
    let madd = ir_func.insts.get(def_id.0 as usize)?;
    if madd.opcode != IrOpcode::Madd {
        return None;
    }

    let (
        Some(IrOperand::VReg(dst)),
        Some(IrOperand::VReg(lhs)),
        Some(IrOperand::VReg(rhs)),
        Some(IrOperand::VReg(base)),
    ) = (
        madd.operands.first(),
        madd.operands.get(1),
        madd.operands.get(2),
        madd.operands.get(3),
    )
    else {
        return None;
    };
    if *dst != temp
        || dst.class != RegClass::Gpr64
        || lhs.class != RegClass::Gpr64
        || rhs.class != RegClass::Gpr64
        || base.class != RegClass::Gpr64
    {
        return None;
    }

    let lhs = unique_gpr64_movz_imm(ir_func, vreg_to_inst, *lhs)?;
    let rhs = unique_gpr64_movz_imm(ir_func, vreg_to_inst, *rhs)?;
    let offset = lhs.checked_mul(rhs)?;
    Some((*base, offset))
}

fn unique_gpr64_movz_imm(
    ir_func: &IrMachFunction,
    vreg_to_inst: &std::collections::HashMap<VReg, Option<InstId>>,
    temp: VReg,
) -> Option<i64> {
    if temp.class != RegClass::Gpr64 {
        return None;
    }
    let Some(Some(def_id)) = vreg_to_inst.get(&temp).copied() else {
        return None;
    };
    let movz = ir_func.insts.get(def_id.0 as usize)?;
    if movz.opcode != IrOpcode::Movz {
        return None;
    }

    let (dst, imm) = match movz.operands.as_slice() {
        [IrOperand::VReg(dst), IrOperand::Imm(imm)] => Some((dst, imm)),
        [IrOperand::VReg(dst), IrOperand::Imm(imm), IrOperand::Imm(0)] => Some((dst, imm)),
        _ => None,
    }?;
    (*dst == temp && dst.class == RegClass::Gpr64 && (0..=0xffff).contains(imm)).then_some(*imm)
}

// ---------------------------------------------------------------------------
// Copy lowering: pseudo Copy -> real MOVWrr/MOVXrr / FmovFprFpr
// ---------------------------------------------------------------------------

/// Lower all pseudo `Copy` instructions to real move instructions.
///
/// After register allocation, the allocator inserts `Copy` pseudo-instructions
/// to move data between physical registers. These must be lowered to real
/// instructions before encoding, since the encoder skips pseudo-instructions.
///
/// **GPR copies** become `MOVWrr`/`MOVXrr`
/// (encoded as `ORR Wd, WZR, Wm` / `ORR Xd, XZR, Xm`).
/// **FPR copies** (scalar H/S/D *and* 128-bit Q/V) become `NeonOrrV dst, src,
/// src` (encoded as `ORR Vd.16B, Vn.16B, Vn.16B`, the architectural
/// `MOV Vd.16B, Vn.16B` full-width vector-copy alias).
///
/// Lowering scalar FP copies as the `.16B` ORR alias (rather than the FP-pipe
/// `FMOV Dd, Dn`) is a deliberate performance choice: on Apple M-series the
/// full-width ORR vector-move alias is rename-eliminated (zero latency), while
/// scalar `FMOV` occupies the FP pipe (~2 cycles) and chains regalloc phi-cycle
/// copies into loop-carried critical paths — the form clang emits for exactly
/// this reason. Scalar copies pass a trailing `Imm(1)` arrangement selector so
/// the encoder derives `Q=1` (`.16B`); without it the scalar dest class would
/// imply the `.8B` form, which is NOT move-eliminated. `Fpr128` copies keep the
/// 3-operand form (their dest class already implies `Q=1`).
///
/// `ORR Vd.16B, Vn.16B, Vn.16B` copies all 128 bits, so the source's
/// architecturally-undefined upper 64 bits are written into the dest's upper 64.
/// This is sound because only the low `<=64` bits are defined for the
/// `Fpr16/Fpr32/Fpr64` classes (every D-register vector — `<8 x i8>`,
/// `<4 x i16>`, `<2 x i32>` — lives in the low 64 bits) and nothing in the
/// backend reads a scalar FPR's upper 64 bits: a 128-bit read requires an
/// `Fpr128` vreg, which the allocator only satisfies from a full-width def. It
/// is also bit-preserving, so signalling-NaN payloads survive a copy chain.
///
/// Using the wrong move type is a correctness bug: `ORR Xd, XZR, Xm` operates
/// on GPR registers only and does NOT touch the FP register file.
///
/// Copies where source == destination are eliminated entirely (converted to Nop).
///
/// Fail-closed: a copy whose destination class has no encodable move form
/// (Fpr8, System) is a hard compile error. Leaving it as a pseudo would make
/// the encoder silently SKIP it (pseudos are not encoded) and converting it
/// blindly to a GPR `MovR` was exactly the FP loop-carried P0 miscompile.
pub fn lower_copies(ir_func: &mut IrMachFunction) -> Result<(), PipelineError> {
    let use_counts = reachable_vreg_use_counts(ir_func);

    for idx in 0..ir_func.insts.len() {
        if ir_func.insts[idx].opcode == IrOpcode::Copy && ir_func.insts[idx].operands.len() >= 2 {
            if let IrOperand::VReg(dst) = ir_func.insts[idx].operands[0] {
                if use_counts.get(&dst).copied().unwrap_or(0) == 0 {
                    let inst = &mut ir_func.insts[idx];
                    inst.opcode = IrOpcode::Nop;
                }
                // A live unresolved-VReg destination is caught right after
                // this pass by `ensure_no_unresolved_vregs` (fail-closed).
                continue;
            }

            let inst = &mut ir_func.insts[idx];
            #[cfg(debug_assertions)]
            if std::env::var("TRUST_CG_DEBUG_REGALLOC").is_ok()
                && !matches!(
                    (&inst.operands[0], &inst.operands[1]),
                    (IrOperand::PReg(_), IrOperand::PReg(_))
                )
            {
                eprintln!(
                    "  lower_copies saw non-preg copy operands: {:?}",
                    inst.operands
                );
            }

            // Copy operands: [dst, src]
            // Check if src == dst (redundant copy).
            let is_redundant = match (&inst.operands[0], &inst.operands[1]) {
                (IrOperand::PReg(a), IrOperand::PReg(b)) => a == b,
                _ => false,
            };
            if is_redundant {
                inst.opcode = IrOpcode::Nop;
                // Nop is still pseudo, flags stay IS_PSEUDO — that's correct.
            } else {
                inst.opcode = match &inst.operands[0] {
                    IrOperand::PReg(preg) => match preg_class(*preg) {
                        RegClass::Gpr32 => IrOpcode::MOVWrr,
                        RegClass::Gpr64 => IrOpcode::MOVXrr,
                        // Scalar FPR (H/S/D) and 128-bit (Q/V) copies both lower
                        // to the rename-eliminated `ORR Vd.16B, Vn.16B, Vn.16B`
                        // vector-move alias (`MOV Vd.16B, Vn.16B`), which Apple
                        // M-series executes at zero latency (a register rename),
                        // unlike the FP-pipe `FMOV Dd, Dn`. ORR needs the source
                        // operand twice. Scalar copies force the full-width `.16B`
                        // arrangement (Q=1) via a trailing `Imm(1)` selector —
                        // the `.8B` (Q=0) form the dest class would otherwise imply
                        // is NOT move-eliminated on M-series. Copying the source's
                        // (architecturally undefined) upper 64 bits into the dest
                        // is sound because only the low `<=64` bits are defined for
                        // the `Fpr16/Fpr32/Fpr64` classes and nothing in the backend
                        // reads a scalar FPR's upper 64 bits (a 128-bit read needs
                        // an `Fpr128` vreg, which carries a full-width def). It is
                        // also bit-preserving, so signalling-NaN payloads survive a
                        // copy chain unchanged. `Fpr128` already implies Q=1 from
                        // its dest class, so it keeps the 3-operand form.
                        class @ (RegClass::Fpr16
                        | RegClass::Fpr32
                        | RegClass::Fpr64
                        | RegClass::Fpr128) => {
                            let src = inst.operands[1].clone();
                            inst.operands.truncate(2);
                            inst.operands.push(src);
                            if class != RegClass::Fpr128 {
                                // Force `.16B` (Q=1); `neon_q_bit` reads this
                                // trailing Imm as the arrangement selector.
                                inst.operands.push(IrOperand::Imm(1));
                            }
                            IrOpcode::NeonOrrV
                        }
                        class @ (RegClass::Fpr8 | RegClass::System) => {
                            return Err(PipelineError::Encoding(format!(
                                "cannot lower Copy to {class:?} destination {preg:?} in `{}`: \
                                 no encodable register-move form (fail-closed)",
                                ir_func.name
                            )));
                        }
                    },
                    // Special GPR aliases: XZR/WZR discard destinations.
                    IrOperand::Special(
                        trust_cg_ir::regs::SpecialReg::XZR | trust_cg_ir::regs::SpecialReg::WZR,
                    ) => IrOpcode::MovR,
                    other => {
                        return Err(PipelineError::Encoding(format!(
                            "cannot lower Copy with non-register destination {other:?} in `{}` \
                             (fail-closed)",
                            ir_func.name
                        )));
                    }
                };
                // Clear the IS_PSEUDO flag so the encoder processes this as a
                // real instruction.
                inst.flags.remove(trust_cg_ir::inst::InstFlags::IS_PSEUDO);
            }
        }
    }

    Ok(())
}

/// Eliminate the redundant second copy of an adjacent two-copy round-trip
/// `Copy b <- a; Copy a <- b`.
///
/// After `Copy b <- a`, register `b` holds the value of `a`, so the immediately
/// following `Copy a <- b` is `a <- a` — a provable no-op. A genuine register
/// *swap* requires a scratch register (three copies: `t<-a; a<-b; b<-t`), so an
/// adjacent two-copy `b<-a; a<-b` is ALWAYS a redundant round-trip and removing
/// the second copy never changes program meaning.
///
/// Runs immediately before [`fixup_aarch64_call_arg_source_clobbers`], which
/// treats a call's argument-register setup as a *parallel* move. The register
/// allocator can emit such a round-trip when relocating a call result out of and
/// back into an argument register; read as a parallel swap, the fixup would
/// preserve a stale value and clobber a live argument. Dropping the redundant
/// copy first keeps the setup a faithful sequential assignment.
fn eliminate_redundant_copy_roundtrips(ir_func: &mut IrMachFunction) {
    let block_order = ir_func.block_order.clone();
    for block_id in block_order {
        let insts = ir_func.block(block_id).insts.clone();
        for window in insts.windows(2) {
            let (id0, id1) = (window[0], window[1]);
            let pair = {
                let first = ir_func.inst(id0);
                let second = ir_func.inst(id1);
                if first.opcode == IrOpcode::Copy && second.opcode == IrOpcode::Copy {
                    match (
                        first.operands.first(),
                        first.operands.get(1),
                        second.operands.first(),
                        second.operands.get(1),
                    ) {
                        (
                            Some(IrOperand::PReg(fd)),
                            Some(IrOperand::PReg(fs)),
                            Some(IrOperand::PReg(sd)),
                            Some(IrOperand::PReg(ss)),
                        ) => Some((*fd, *fs, *sd, *ss)),
                        _ => None,
                    }
                } else {
                    None
                }
            };
            // first: fd <- fs ; second: sd <- ss. Round-trip iff second is the
            // inverse of first (sd == fs, ss == fd) and it is not a self-copy.
            if let Some((fd, fs, sd, ss)) = pair
                && sd == fs
                && ss == fd
                && fd != fs
            {
                let second = ir_func.inst_mut(id1);
                second.opcode = IrOpcode::Nop;
                // If the second copy carries call-setup semantic provenance, the
                // sequential round-trip proof establishes that its destination
                // already contains the required value. Preserve that fact as
                // an exact identity marker; leaving the stale pre-elimination
                // source operand would make the final provenance malformed.
                if second.flags.is_call_arg_setup() {
                    second.operands[1] = IrOperand::PReg(sd);
                }
            }
        }
    }
}

// ---------------------------------------------------------------------------
// AArch64 call argument setup repair
// ---------------------------------------------------------------------------

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Aarch64CallArgSetupKind {
    Copy,
    Uxtw,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct Aarch64CallArgSetup {
    inst_id: InstId,
    src: PReg,
    dst: PReg,
    kind: Aarch64CallArgSetupKind,
}

/// Make physical-register argument setup behave like a parallel move.
///
/// After register allocation, a call sequence can contain physical copies into
/// ABI argument registers immediately before a `BL`/`BLR`. Those copies are a
/// logical parallel assignment: all sources must be read before any destination
/// clobbers another source. A sequential lowering such as `X0 <- X1; X1 <- X0`
/// corrupts the second argument unless the original `X0` is preserved first.
///
/// This pass runs before pseudo `Copy` lowering. It keeps already-safe call
/// sequences unchanged and only inserts scratch preserves for sources that
/// would otherwise be overwritten by an earlier argument-register setup.
fn fixup_aarch64_call_arg_source_clobbers(
    ir_func: &mut IrMachFunction,
) -> Result<(), PipelineError> {
    // Plan and apply on a clone so any late planning failure leaves the caller's
    // function byte-for-byte unchanged. In particular, no rewritten setup may
    // point at a scratch save that was never inserted.
    let mut repaired = ir_func.clone();
    fixup_aarch64_call_arg_source_clobbers_in_place(&mut repaired)?;
    *ir_func = repaired;
    Ok(())
}

fn fixup_aarch64_call_arg_source_clobbers_in_place(
    ir_func: &mut IrMachFunction,
) -> Result<(), PipelineError> {
    let block_order = ir_func.block_order.clone();
    #[cfg(debug_assertions)]
    let debug = std::env::var("TRUST_CG_DEBUG_REGALLOC").is_ok();

    for block_id in block_order {
        let insts = ir_func.block(block_id).insts.clone();
        let mut insertions: Vec<(usize, Vec<InstId>)> = Vec::new();

        for (call_pos, &call_id) in insts.iter().enumerate() {
            let call_implicit_uses = {
                let call_inst = ir_func.inst(call_id);
                if !is_aarch64_call_boundary(call_inst) || call_inst.implicit_uses.is_empty() {
                    continue;
                }
                call_inst.implicit_uses.to_vec()
            };
            // One namespace for every exact parallel-move source cycle at this
            // call, so two preserved sources never reuse a scratch.
            let mut allocated_scratch = Vec::new();

            let setup_region = aarch64_call_arg_setups_in_current_region(
                ir_func,
                &insts,
                call_pos,
                &call_implicit_uses,
            )?;
            if let Some(group_start) = setup_region.first().map(|(pos, _)| *pos) {
                // Marked setups need not remain contiguous: spill
                // materialization may insert sequential reloads between them.
                // The semantic setup flag, not adjacency, determines membership
                // in this logical parallel assignment.
                let setups: Vec<Aarch64CallArgSetup> =
                    setup_region.into_iter().map(|(_, setup)| setup).collect();
                let setups = prune_redundant_aarch64_identity_arg_setups(setups);

                #[cfg(debug_assertions)]
                if debug {
                    eprintln!(
                        "  aarch64_call_arg_fixup block={:?} call={:?} implicit_uses={:?} setups={:?}",
                        block_id, call_id, call_implicit_uses, setups
                    );
                }

                let preserve_sources = aarch64_call_arg_sources_requiring_preserve(&setups);
                if !preserve_sources.is_empty() {
                    let protected = aarch64_call_arg_protected_regs(
                        ir_func,
                        ir_func.inst(call_id),
                        &insts[group_start..call_pos],
                    );
                    let mut preserves = Vec::new();

                    for source in preserve_sources {
                        let scratch = choose_aarch64_call_arg_scratch(
                            source,
                            &protected,
                            &allocated_scratch,
                        )
                        .ok_or_else(|| {
                            PipelineError::Aarch64CallArgRepair(format!(
                                "function `{}` block {:?} call {:?}: no {:?} scratch register can preserve parallel-move source {:?}",
                                ir_func.name,
                                block_id,
                                call_id,
                                preg_class(source),
                                source
                            ))
                        })?;
                        allocated_scratch.push(scratch);
                        preserves.push((source, scratch));
                    }

                    #[cfg(debug_assertions)]
                    if debug {
                        eprintln!(
                            "  aarch64_call_arg_fixup preserves for call {:?}: {:?}",
                            call_id, preserves
                        );
                    }

                    if !preserves.is_empty() {
                        let preserve_insts: Vec<_> = preserves
                            .iter()
                            .map(|&(source, scratch)| {
                                ir_func.push_inst(IrMachInst::new(
                                    IrOpcode::Copy,
                                    vec![IrOperand::PReg(scratch), IrOperand::PReg(source)],
                                ))
                            })
                            .collect();

                        for setup in setups {
                            if let Some((_, scratch)) =
                                preserves.iter().find(|&&(source, _)| source == setup.src)
                            {
                                rewrite_aarch64_call_arg_setup_source(
                                    ir_func.inst_mut(setup.inst_id),
                                    setup.kind,
                                    *scratch,
                                );
                            }
                        }

                        insertions.push((group_start, preserve_insts));
                    }
                }
            }

            // A non-setup definition of an ABI argument register can either be a
            // transient borrow or the actual value consumed by the call. The
            // liveness-gated repair rescues the safe cases (a live value across a
            // transient clobber -> preserve/restore) and leaves the establishing
            // cases alone (a dead incoming value the clobber legitimately supplies
            // -> no restore). Cases it cannot clear insert nothing, so a guessed
            // older value is never restored over a possibly real call argument;
            // the final `verify_aarch64_final_call_argument_sequence` gate below
            // still fails closed on any residual unresolved hazard.
            let dest_preserves =
                aarch64_call_arg_dest_preserves(ir_func, &insts, call_pos, &call_implicit_uses)?;
            let implicit_preserves = aarch64_call_arg_implicit_preserves(
                ir_func,
                &insts,
                call_pos,
                &call_implicit_uses,
                block_id == ir_func.entry,
            )?;
            for preserve in dest_preserves.into_iter().chain(implicit_preserves) {
                let preserve_inst = ir_func.push_inst(IrMachInst::new(
                    IrOpcode::Copy,
                    vec![
                        IrOperand::PReg(preserve.scratch),
                        IrOperand::PReg(preserve.arg_reg),
                    ],
                ));
                let restore_inst = ir_func.push_inst(IrMachInst::new(
                    IrOpcode::Copy,
                    vec![
                        IrOperand::PReg(preserve.arg_reg),
                        IrOperand::PReg(preserve.scratch),
                    ],
                ));
                insertions.push((preserve.insert_after_pos + 1, vec![preserve_inst]));
                insertions.push((call_pos, vec![restore_inst]));
            }
        }

        if insertions.is_empty() {
            continue;
        }

        let block = ir_func.block_mut(block_id);
        insertions.sort_by_key(|(insert_pos, _)| *insert_pos);
        for (insert_pos, inserted_insts) in insertions.into_iter().rev() {
            block.insts.splice(insert_pos..insert_pos, inserted_insts);
        }
    }

    Ok(())
}

/// Drop an identity setup whose destination was already established earlier
/// in the same contiguous argument group.
///
/// Post-RA coalescing deliberately retains a final `xN <- xN` as provenance
/// for the single-setup case. In a group such as `x1 <- x19; x0 <- x21;
/// x1 <- x1`, however, the identity reads the value just written by the first
/// setup; treating its source as the *pre-group* x1 value makes the
/// parallel-move repair preserve and restore stale data over the real x1
/// argument.
fn prune_redundant_aarch64_identity_arg_setups(
    setups: Vec<Aarch64CallArgSetup>,
) -> Vec<Aarch64CallArgSetup> {
    setups
        .iter()
        .enumerate()
        .filter_map(|(idx, setup)| {
            let redundant_identity = setup.dst == setup.src
                && setups[..idx]
                    .iter()
                    .any(|earlier| regs_overlap(earlier.dst, setup.dst));
            (!redundant_identity).then_some(*setup)
        })
        .collect()
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct Aarch64CallArgDestPreserve {
    insert_after_pos: usize,
    arg_reg: PReg,
    scratch: PReg,
}

// Repair (not fail-closed): rescue a live argument-register value that a
// transient in-region clobber destroys, gated by liveness so a clobber that
// legitimately establishes the argument is left ALONE. This is the
// scalar-temp / num_objs / entry-alloca-addr defect family: where the parallel
// session's audit chose to fail closed on the ambiguous physical stream, the
// liveness gates below prove which of those streams are actually safe (the
// wp5/wp6/wp7 whole-program shapes) and either skip (dead incoming value) or
// preserve/restore (live value across a transient clobber). Cases NOT cleared
// by a gate still fall through: `dest_preserves`/`implicit_preserves` never
// insert a guessed restore, and the setup-parallel-move fail-closed paths and
// the final `verify_aarch64_final_call_argument_sequence` gate remain intact.
fn aarch64_call_arg_dest_preserves(
    ir_func: &IrMachFunction,
    insts: &[InstId],
    call_pos: usize,
    call_implicit_uses: &[PReg],
) -> Result<Vec<Aarch64CallArgDestPreserve>, PipelineError> {
    let setups =
        aarch64_call_arg_setups_in_current_region(ir_func, insts, call_pos, call_implicit_uses)?;
    let mut preserves = Vec::new();
    let mut allocated_scratch = Vec::new();

    for (setup_pos, setup) in setups.iter().copied() {
        let setup_is_overwritten_by_later_setup = setups.iter().any(|(other_pos, other_setup)| {
            *other_pos > setup_pos && regs_overlap(other_setup.dst, setup.dst)
        });
        if setup_is_overwritten_by_later_setup {
            continue;
        }

        let later_clobbers_arg = insts[setup_pos + 1..call_pos].iter().any(|&inst_id| {
            aarch64_inst_def_pregs(ir_func.inst(inst_id))
                .into_iter()
                .any(|defined| regs_overlap(defined, setup.dst))
        });
        if !later_clobbers_arg {
            continue;
        }

        // Liveness gate: only preserve+restore the setup's value if it is the
        // value the call actually needs in `setup.dst`. If a later instruction
        // writes `setup.dst` with a value that survives unread to the call, that
        // instruction establishes the argument and the setup's value is DEAD.
        // Restoring a dead value here would clobber the real argument (defect
        // #4b: a narrow value materialized by `uxth wN, wM` into a pre-colored
        // arg register was being overwritten by a spurious restore of an
        // unrelated dead value that the allocator had parked in the same reg).
        if !aarch64_call_arg_setup_value_reaches_call(
            ir_func, insts, setup_pos, call_pos, setup.dst,
        ) {
            continue;
        }

        let mut protected =
            aarch64_call_arg_region_protected_regs(ir_func, insts, setup_pos + 1, call_pos);
        push_unique_overlap(&mut protected, setup.dst);

        let Some(scratch) =
            choose_aarch64_call_arg_scratch(setup.dst, &protected, &allocated_scratch)
        else {
            continue;
        };
        allocated_scratch.push(scratch);
        preserves.push(Aarch64CallArgDestPreserve {
            insert_after_pos: setup_pos,
            arg_reg: setup.dst,
            scratch,
        });
    }

    Ok(preserves)
}

/// Decide whether the value written by the call-argument setup at `setup_pos`
/// (into `arg_reg`) is the value the call actually consumes from `arg_reg`.
///
/// The setup value reaches the call only if every intervening definition of
/// `arg_reg` between the setup and the call is *transient* — i.e. its result is
/// read by some instruction strictly before the call (a temporary borrow of the
/// physical register). If any intervening definition writes `arg_reg` with a
/// value that survives unread up to the call, that later definition establishes
/// the argument and the setup's value is dead. In the dead case we must NOT
/// preserve/restore the setup value, because restoring it would overwrite the
/// real argument the call expects (defect #4b).
fn aarch64_call_arg_setup_value_reaches_call(
    ir_func: &IrMachFunction,
    insts: &[InstId],
    setup_pos: usize,
    call_pos: usize,
    arg_reg: PReg,
) -> bool {
    // Walk forward through the region between the setup and the call. Track
    // whether `arg_reg` currently holds the setup's value. Each definition of
    // `arg_reg` either:
    //   - is consumed before the call (the surviving value is still the setup's
    //     value, so processing continues), or
    //   - survives unread to the call (the setup value is dead -> return false).
    for clobber_pos in (setup_pos + 1)..call_pos {
        let clobber_inst = ir_func.inst(insts[clobber_pos]);
        let defines_arg = aarch64_inst_def_pregs(clobber_inst)
            .into_iter()
            .any(|defined| regs_overlap(defined, arg_reg));
        if !defines_arg {
            continue;
        }

        // Is this clobbering definition's value read again before the call by a
        // non-call instruction? If so it is a transient temporary and the setup
        // value is the one the call needs (restore is required). If not, this
        // definition supplies the call's argument and the setup value is dead.
        let consumed_before_call = insts[(clobber_pos + 1)..call_pos].iter().any(|&later_id| {
            aarch64_inst_use_pregs(ir_func.inst(later_id))
                .into_iter()
                .any(|used| regs_overlap(used, arg_reg))
        });
        if !consumed_before_call {
            return false;
        }
    }

    true
}

fn aarch64_call_arg_region_protected_regs(
    ir_func: &IrMachFunction,
    insts: &[InstId],
    start_pos: usize,
    call_pos: usize,
) -> Vec<PReg> {
    let mut protected = Vec::new();

    for (pos, &inst_id) in insts.iter().enumerate().take(call_pos + 1).skip(start_pos) {
        let inst = ir_func.inst(inst_id);
        for preg in aarch64_inst_def_pregs(inst)
            .into_iter()
            .chain(aarch64_inst_use_pregs(inst))
        {
            push_unique_overlap(&mut protected, preg);
        }
        if pos < call_pos {
            for &preg in inst.implicit_defs {
                push_unique_overlap(&mut protected, preg);
            }
        }
        for &preg in inst.implicit_uses {
            push_unique_overlap(&mut protected, preg);
        }
    }

    protected
}

/// Preserve *implicit* argument registers — ABI arg registers the call reads
/// (`implicit_uses`) that are NOT established by any explicit setup copy/uxtw,
/// i.e. the allocator left their value "already in place" (typically a prior
/// call's result) — when that value is clobbered before the call.
///
/// `aarch64_call_arg_dest_preserves` only protects registers written by a
/// recognized *setup*. When an argument is the result of an earlier call it sits
/// in its ABI register with no setup; if the allocator then materializes another
/// argument's constant into that same register (`mov x0, #imm; mov x2, x0`) and
/// parks the original elsewhere without reloading it, the call runs with the
/// constant in place of the live pointer. This pass saves such a register's
/// value immediately before its first clobber and restores it immediately
/// before the call — gated by the liveness preconditions below so a clobber
/// that legitimately establishes the argument (a dead incoming value) is left
/// alone rather than rescued.
fn aarch64_call_arg_implicit_preserves(
    ir_func: &IrMachFunction,
    insts: &[InstId],
    call_pos: usize,
    call_implicit_uses: &[PReg],
    is_entry_block: bool,
) -> Result<Vec<Aarch64CallArgDestPreserve>, PipelineError> {
    // Region in which the argument value is established/clobbered: from the most
    // recent prior call (exclusive) or block start, up to this call. Argument
    // values that are prior-call results live in this window.
    let region_start = {
        let mut s = call_pos;
        while s > 0 && !ir_func.inst(insts[s - 1]).is_call() {
            s -= 1;
        }
        s
    };

    // Registers that hold a LIVE incoming value at the top of the entry block:
    // exactly the formal-parameter ABI registers. Every other argument register
    // holds caller-supplied, unused garbage there. Only meaningful when the
    // region opens at the function entry (region_start == 0 in the entry block).
    let entry_formal_regs: Vec<PReg> = if is_entry_block && region_start == 0 {
        aarch64_formal_abi_source_regs(&ir_func.signature)
    } else {
        Vec::new()
    };

    let setups =
        aarch64_call_arg_setups_in_current_region(ir_func, insts, call_pos, call_implicit_uses)?;
    let mut preserves = Vec::new();
    let mut allocated_scratch = Vec::new();

    for &arg_reg in call_implicit_uses {
        // Skip registers an explicit setup already establishes — those are the
        // `dest_preserves` pass's responsibility.
        if setups.iter().any(|(_, s)| regs_overlap(s.dst, arg_reg)) {
            continue;
        }
        // First clobber of `arg_reg` within the region. With none, the register
        // still holds its incoming value at the call — nothing to do.
        let Some(first_clobber_pos) = (region_start..call_pos).find(|&pos| {
            aarch64_inst_def_pregs(ir_func.inst(insts[pos]))
                .into_iter()
                .any(|defined| regs_overlap(defined, arg_reg))
        }) else {
            continue;
        };
        if first_clobber_pos == 0 {
            continue;
        }
        // Liveness precondition (defect: alloca-address call argument at fn entry).
        // At the top of the entry block, the ONLY argument registers holding a
        // live incoming value are the formal-parameter ABI registers; every other
        // one holds dead, caller-supplied garbage. If `arg_reg` is not a formal-
        // parameter register, its region-entry value is dead and the in-region
        // clobber legitimately ESTABLISHES the argument (typically `sub xN,x29,#imm`
        // materializing a stack alloca address passed as this argument). Restoring
        // its dead entry value would pass null/garbage (the `grow_amortized`
        // SIGSEGV). Skip.
        if is_entry_block
            && region_start == 0
            && !entry_formal_regs
                .iter()
                .any(|&formal| regs_overlap(formal, arg_reg))
        {
            continue;
        }
        // Liveness precondition (defect: variadic ctor num_objs/scalar clobbered).
        // If the region opens right after a call that *clobbered* `arg_reg` as a
        // caller-saved scratch (in the call's `implicit_defs`) and `arg_reg` is NOT
        // that call's result register (hw-encoding 0), the region-entry value is
        // dead garbage — restoring it would overwrite the argument the in-region
        // instructions correctly established (e.g. `Movz w1,#1` for `num_objs`).
        // Skip.
        if region_start >= 1 {
            let opening = ir_func.inst(insts[region_start - 1]);
            let clobbered_by_opening_call = opening.is_call()
                && opening
                    .implicit_defs
                    .iter()
                    .any(|&d| regs_overlap(d, arg_reg));
            if clobbered_by_opening_call && hw_encoding(arg_reg) != 0 {
                continue;
            }
        }
        // Liveness precondition (defect: `&(fresh scalar temp)` argument clobber).
        // If some instruction in `[region_start, first_clobber_pos)` READS
        // `arg_reg`, that read is the entry value's last use (it was relocated/
        // consumed) and the entry value is DEAD by the clobber; the clobber then
        // legitimately ESTABLISHES the argument (`sub x0,x29,#imm` materializing
        // `&disc_temp` whose value a `str` also reads yet IS arg0). Skip.
        let entry_value_read_before_clobber =
            insts[region_start..first_clobber_pos].iter().any(|&id| {
                aarch64_inst_use_pregs(ir_func.inst(id))
                    .into_iter()
                    .any(|used| regs_overlap(used, arg_reg))
            });
        if entry_value_read_before_clobber {
            continue;
        }
        // The pre-clobber value must be the one the call needs (all clobbers
        // transient). `setup_pos = first_clobber_pos - 1` makes the first clobber
        // the first one inspected.
        if !aarch64_call_arg_setup_value_reaches_call(
            ir_func,
            insts,
            first_clobber_pos - 1,
            call_pos,
            arg_reg,
        ) {
            continue;
        }
        // Scratch must survive the clobber..call window and not alias any live reg.
        let mut protected =
            aarch64_call_arg_region_protected_regs(ir_func, insts, first_clobber_pos, call_pos);
        push_unique_overlap(&mut protected, arg_reg);
        let Some(scratch) =
            choose_aarch64_call_arg_scratch(arg_reg, &protected, &allocated_scratch)
        else {
            continue;
        };
        allocated_scratch.push(scratch);
        preserves.push(Aarch64CallArgDestPreserve {
            // Save copy lands at `insert_after_pos + 1` == `first_clobber_pos`,
            // i.e. immediately before the clobber, where `arg_reg` is still live.
            insert_after_pos: first_clobber_pos - 1,
            arg_reg,
            scratch,
        });
    }

    Ok(preserves)
}

fn aarch64_call_arg_setups_in_current_region(
    ir_func: &IrMachFunction,
    insts: &[InstId],
    call_pos: usize,
    call_implicit_uses: &[PReg],
) -> Result<Vec<(usize, Aarch64CallArgSetup)>, PipelineError> {
    let mut setups = Vec::new();
    let mut pos = call_pos;

    while pos > 0 {
        pos -= 1;
        let inst = ir_func.inst(insts[pos]);
        if is_aarch64_call_boundary(inst) || inst.flags.is_branch() || inst.flags.is_return() {
            break;
        }
        let classified = classify_aarch64_call_arg_setup(inst, call_implicit_uses);
        if inst.flags.is_call_arg_setup() && classified.is_none() {
            return Err(PipelineError::Aarch64CallArgRepair(format!(
                "function `{}` call {:?}: malformed semantic call-argument setup {:?} at position {pos}: opcode {:?}, operands {:?}; expected exactly one ABI argument definition and at least one physical source",
                ir_func.name, insts[call_pos], insts[pos], inst.opcode, inst.operands
            )));
        }
        if let Some(setup) = classified
            && call_implicit_uses
                .iter()
                .any(|&arg_reg| regs_overlap(arg_reg, setup.dst))
        {
            setups.push((
                pos,
                Aarch64CallArgSetup {
                    inst_id: insts[pos],
                    ..setup
                },
            ));
        }
    }

    setups.reverse();
    Ok(setups)
}

fn aarch64_inst_def_pregs(inst: &IrMachInst) -> Vec<PReg> {
    let mut defs: Vec<_> = classify_operand_positions(inst)
        .0
        .into_iter()
        .filter_map(|pos| match inst.operands.get(pos) {
            Some(IrOperand::PReg(preg)) => Some(*preg),
            _ => None,
        })
        .collect();
    for &preg in inst.implicit_defs {
        if !defs.contains(&preg) {
            defs.push(preg);
        }
    }
    defs
}

fn aarch64_inst_use_pregs(inst: &IrMachInst) -> Vec<PReg> {
    let mut uses: Vec<_> = classify_operand_positions(inst)
        .1
        .into_iter()
        .filter_map(|pos| match inst.operands.get(pos) {
            Some(IrOperand::PReg(preg)) => Some(*preg),
            _ => None,
        })
        .collect();
    for &preg in inst.implicit_uses {
        if !uses.contains(&preg) {
            uses.push(preg);
        }
    }
    uses
}

fn classify_aarch64_call_arg_setup(
    inst: &IrMachInst,
    call_implicit_uses: &[PReg],
) -> Option<Aarch64CallArgSetup> {
    if !inst.flags.is_call_arg_setup() {
        return None;
    }
    if inst.opcode == IrOpcode::Nop {
        let (Some(IrOperand::PReg(dst)), Some(IrOperand::PReg(src))) =
            (inst.operands.first(), inst.operands.get(1))
        else {
            return None;
        };
        return (regs_overlap(*dst, *src)
            && call_implicit_uses
                .iter()
                .any(|&arg| regs_overlap(arg, *dst)))
        .then_some(Aarch64CallArgSetup {
            inst_id: InstId(0),
            src: *src,
            dst: *dst,
            kind: Aarch64CallArgSetupKind::Copy,
        });
    }
    let matching_defs: Vec<_> = aarch64_inst_def_pregs(inst)
        .into_iter()
        .filter(|defined| {
            call_implicit_uses
                .iter()
                .any(|&arg| regs_overlap(arg, *defined))
        })
        .collect();
    let [dst] = matching_defs.as_slice() else {
        return None;
    };
    let src = aarch64_inst_use_pregs(inst).into_iter().next()?;
    Some(Aarch64CallArgSetup {
        inst_id: InstId(0),
        src,
        dst: *dst,
        kind: if inst.opcode == IrOpcode::Uxtw {
            Aarch64CallArgSetupKind::Uxtw
        } else {
            Aarch64CallArgSetupKind::Copy
        },
    })
}

fn classify_aarch64_final_call_arg_setup(
    inst: &IrMachInst,
    call_implicit_uses: &[PReg],
) -> Option<Aarch64CallArgSetup> {
    if !inst.flags.is_call_arg_setup() {
        return None;
    }
    // An identity copy becomes a non-encoding NOP during Copy lowering, but
    // its exact operands and provenance remain available here.
    if inst.opcode == IrOpcode::Nop {
        let (Some(IrOperand::PReg(dst)), Some(IrOperand::PReg(src))) =
            (inst.operands.first(), inst.operands.get(1))
        else {
            return None;
        };
        return (regs_overlap(*dst, *src)
            && call_implicit_uses
                .iter()
                .any(|&arg| regs_overlap(arg, *dst)))
        .then_some(Aarch64CallArgSetup {
            inst_id: InstId(0),
            src: *src,
            dst: *dst,
            kind: Aarch64CallArgSetupKind::Copy,
        });
    }

    let matching_defs: Vec<_> = aarch64_inst_def_pregs(inst)
        .into_iter()
        .filter(|defined| {
            call_implicit_uses
                .iter()
                .any(|&arg| regs_overlap(arg, *defined))
        })
        .collect();
    let [dst] = matching_defs.as_slice() else {
        return None;
    };
    let src = aarch64_inst_use_pregs(inst).into_iter().next()?;
    Some(Aarch64CallArgSetup {
        inst_id: InstId(0),
        src,
        dst: *dst,
        kind: if inst.opcode == IrOpcode::Uxtw {
            Aarch64CallArgSetupKind::Uxtw
        } else {
            Aarch64CallArgSetupKind::Copy
        },
    })
}

/// Independently re-check final physical call-argument setup immediately before
/// encoding. The repair runs during register allocation, but frame lowering,
/// pseudo expansion, layout, and branch relaxation all happen later. This gate
/// therefore consumes the exact final MOV/Uxtw operands and each call's exact
/// physical argument-register identities (`implicit_uses`) rather than trusting
/// that the earlier repair remained valid.
///
/// The input is one final emission sequence (a MachIR block, or the flattened
/// sequence produced by branch relaxation). No value identity is guessed: an
/// unresolved parallel-move source clobber or an ambiguous argument-register
/// clobber fails closed.
pub(crate) fn verify_aarch64_final_call_argument_sequence<'a>(
    function_name: &str,
    insts: impl IntoIterator<Item = &'a IrMachInst>,
) -> Result<(), PipelineError> {
    let insts: Vec<_> = insts.into_iter().collect();

    for (call_pos, call) in insts.iter().copied().enumerate() {
        if !is_aarch64_call_boundary(call) || call.implicit_uses.is_empty() {
            continue;
        }
        let call_args = call.implicit_uses;

        // `Copy` is a non-encoding pseudo. Crediting it as an argument setup at
        // this boundary would prove a write that the encoder silently omits.
        // The exact final stream must carry a real MOV/Uxtw form instead.
        if insts[..call_pos]
            .iter()
            .rev()
            .take_while(|inst| {
                !is_aarch64_call_boundary(inst)
                    && !inst.flags.is_branch()
                    && !inst.flags.is_return()
            })
            .any(|inst| {
                inst.opcode == IrOpcode::Copy
                    && aarch64_inst_def_pregs(inst)
                        .into_iter()
                        .any(|defined| call_args.iter().any(|&arg| regs_overlap(defined, arg)))
            })
        {
            return Err(PipelineError::Aarch64CallArgRepair(format!(
                "function `{function_name}` final call at instruction {call_pos}: \
                 unresolved Copy pseudo defines an ABI argument register; the \
                 encoder would omit the required setup"
            )));
        }

        // A final contiguous argument-move group has parallel semantics. Every
        // source must still be readable when its move executes. The early
        // repair rewrites clobbered sources to scratch registers; seeing one
        // here proves a later mutation invalidated or bypassed that repair.
        let mut region_start = call_pos;
        while region_start > 0 {
            let previous = insts[region_start - 1];
            if is_aarch64_call_boundary(previous)
                || previous.flags.is_branch()
                || previous.flags.is_return()
            {
                break;
            }
            region_start -= 1;
        }
        if let Some((offset, _)) =
            insts[region_start..call_pos]
                .iter()
                .enumerate()
                .find(|(_, inst)| {
                    inst.flags.is_call_arg_setup()
                        && classify_aarch64_final_call_arg_setup(inst, call_args).is_none()
                })
        {
            return Err(PipelineError::Aarch64CallArgRepair(format!(
                "function `{function_name}` final call at instruction {call_pos}: malformed semantic call-argument setup at instruction {}; expected exactly one ABI argument definition and at least one physical source",
                region_start + offset
            )));
        }
        let group: Vec<_> = insts[region_start..call_pos]
            .iter()
            .copied()
            .filter_map(|inst| classify_aarch64_final_call_arg_setup(inst, call_args))
            .collect();
        for (idx, setup) in group.iter().enumerate() {
            if let Some(previous) = group[..idx]
                .iter()
                .find(|previous| regs_overlap(previous.dst, setup.src))
            {
                return Err(PipelineError::Aarch64CallArgRepair(format!(
                    "function `{function_name}` final call at instruction {call_pos}: \
                     argument setup {:?} <- {:?} reads a source clobbered by earlier \
                     setup {:?} <- {:?}; final stream no longer preserves exact \
                     parallel-move source identity",
                    setup.dst, setup.src, previous.dst, previous.src
                )));
            }
        }

        verify_aarch64_final_call_argument_clobbers(function_name, &insts, call_pos, call_args)?;
    }

    Ok(())
}

fn verify_aarch64_final_call_argument_clobbers(
    function_name: &str,
    insts: &[&IrMachInst],
    call_pos: usize,
    call_args: &[PReg],
) -> Result<(), PipelineError> {
    let mut region_start = call_pos;
    while region_start > 0 {
        let previous = insts[region_start - 1];
        if is_aarch64_call_boundary(previous)
            || previous.flags.is_branch()
            || previous.flags.is_return()
        {
            break;
        }
        region_start -= 1;
    }

    let setups: Vec<_> = (region_start..call_pos)
        .filter_map(|pos| {
            classify_aarch64_final_call_arg_setup(insts[pos], call_args).map(|setup| (pos, setup))
        })
        .collect();

    // Explicitly established arguments: a later non-setup clobber that is also
    // consumed before the call is ambiguous in physical MachIR. It might be a
    // temporary, or it might intentionally replace the argument; encoding must
    // not guess which value the call was meant to consume.
    for (setup_index, (setup_pos, setup)) in setups.iter().copied().enumerate() {
        if setups[setup_index + 1..]
            .iter()
            .any(|(_, later)| regs_overlap(later.dst, setup.dst))
        {
            continue;
        }
        let first_later_clobber = (setup_pos + 1..call_pos).find(|&pos| {
            aarch64_inst_def_pregs(insts[pos])
                .into_iter()
                .any(|defined| regs_overlap(defined, setup.dst))
        });
        if let Some(first_later_clobber) = first_later_clobber
            && aarch64_final_call_arg_all_clobbers_are_read(
                insts,
                first_later_clobber,
                call_pos,
                setup.dst,
            )
        {
            return Err(PipelineError::Aarch64CallArgRepair(format!(
                "function `{function_name}` final call at instruction {call_pos}: \
                 argument {:?} is clobbered after its final setup and that clobber \
                 is read before the call; exact argument value is ambiguous",
                setup.dst
            )));
        }
    }

    // Arguments with no explicit final setup rely on an already-resident value.
    // Apply the same fail-closed rule to both explicit and implicit definitions.
    for &arg_reg in call_args {
        if setups
            .iter()
            .any(|(_, setup)| regs_overlap(setup.dst, arg_reg))
        {
            continue;
        }
        let first_clobber = (region_start..call_pos).find(|&pos| {
            aarch64_inst_def_pregs(insts[pos])
                .into_iter()
                .any(|defined| regs_overlap(defined, arg_reg))
        });
        if let Some(first_clobber) = first_clobber
            && aarch64_final_call_arg_all_clobbers_are_read(insts, first_clobber, call_pos, arg_reg)
        {
            return Err(PipelineError::Aarch64CallArgRepair(format!(
                "function `{function_name}` final call at instruction {call_pos}: \
                 implicit argument {:?} is clobbered and that clobber is read before \
                 the call; exact argument value is ambiguous",
                arg_reg
            )));
        }
    }

    Ok(())
}

fn aarch64_final_call_arg_all_clobbers_are_read(
    insts: &[&IrMachInst],
    scan_start: usize,
    call_pos: usize,
    arg_reg: PReg,
) -> bool {
    for clobber_pos in scan_start..call_pos {
        if !aarch64_inst_def_pregs(insts[clobber_pos])
            .into_iter()
            .any(|defined| regs_overlap(defined, arg_reg))
        {
            continue;
        }
        if !insts[clobber_pos + 1..call_pos].iter().any(|later| {
            aarch64_inst_use_pregs(later)
                .into_iter()
                .any(|used| regs_overlap(used, arg_reg))
        }) {
            return false;
        }
    }
    true
}

fn aarch64_call_arg_sources_requiring_preserve(setups: &[Aarch64CallArgSetup]) -> Vec<PReg> {
    let mut preserve = Vec::new();

    for (idx, setup) in setups.iter().enumerate() {
        let source_clobbered_before_use = setups[..idx]
            .iter()
            .any(|previous| regs_overlap(previous.dst, setup.src));
        if source_clobbered_before_use && !preserve.contains(&setup.src) {
            preserve.push(setup.src);
        }
    }

    preserve
}

fn aarch64_call_arg_protected_regs(
    ir_func: &IrMachFunction,
    call_inst: &IrMachInst,
    setup_region: &[InstId],
) -> Vec<PReg> {
    let mut protected = Vec::new();

    for operand in &call_inst.operands {
        if let IrOperand::PReg(reg) = operand {
            push_unique_overlap(&mut protected, *reg);
        }
    }
    for &reg in call_inst.implicit_uses {
        push_unique_overlap(&mut protected, reg);
    }
    // Preserves are inserted before the first marked setup and remain live
    // until every rewritten setup has consumed them.  Protect every physical
    // read and write in that whole interval, including unmarked spill reloads,
    // frame materialization, and other sequential instructions interleaved
    // between marked setups.  Merely protecting setup operands lets an
    // interleaved `mov x9, ...` overwrite the saved value (or lets the preserve
    // itself clobber a transient x9 value before its read).
    for &inst_id in setup_region {
        for reg in aarch64_inst_def_pregs(ir_func.inst(inst_id))
            .into_iter()
            .chain(aarch64_inst_use_pregs(ir_func.inst(inst_id)))
        {
            push_unique_overlap(&mut protected, reg);
        }
    }

    protected
}

fn choose_aarch64_call_arg_scratch(
    source: PReg,
    protected: &[PReg],
    allocated_scratch: &[PReg],
) -> Option<PReg> {
    let candidates = aarch64_call_arg_scratch_candidates(source)?;
    candidates.into_iter().find(|&candidate| {
        !protected.iter().any(|&reg| regs_overlap(reg, candidate))
            && !allocated_scratch
                .iter()
                .any(|&reg| regs_overlap(reg, candidate))
    })
}

fn aarch64_call_arg_scratch_candidates(source: PReg) -> Option<Vec<PReg>> {
    let class = preg_class(source);
    let candidates = match class {
        RegClass::Gpr64 => (9..=17).map(PReg::new).collect(),
        RegClass::Gpr32 => (9..=17).map(|idx| PReg::new(idx + 32)).collect(),
        RegClass::Fpr128 => (16..=31).map(|idx| PReg::new(idx + 64)).collect(),
        RegClass::Fpr64 => (16..=31).map(|idx| PReg::new(idx + 96)).collect(),
        RegClass::Fpr32 => (16..=31).map(|idx| PReg::new(idx + 128)).collect(),
        RegClass::Fpr16 => (16..=31).map(|idx| PReg::new(idx + 165)).collect(),
        RegClass::Fpr8 => (16..=31).map(|idx| PReg::new(idx + 197)).collect(),
        RegClass::System => return None,
    };
    Some(candidates)
}

fn rewrite_aarch64_call_arg_setup_source(
    inst: &mut IrMachInst,
    kind: Aarch64CallArgSetupKind,
    scratch: PReg,
) {
    match kind {
        Aarch64CallArgSetupKind::Copy | Aarch64CallArgSetupKind::Uxtw => {
            if let Some(operand) = inst.operands.get_mut(1) {
                *operand = IrOperand::PReg(scratch);
            }
        }
    }
}

fn push_unique_overlap(regs: &mut Vec<PReg>, reg: PReg) {
    if !regs.iter().any(|&existing| regs_overlap(existing, reg)) {
        regs.push(reg);
    }
}

fn aarch64_formal_abi_source_regs(signature: &IrSignature) -> Vec<PReg> {
    let lower_param_types: Vec<LowerType> = signature
        .params
        .iter()
        .map(lower_type_from_ir_type)
        .collect();
    let param_locs = AppleAArch64ABI::classify_params(&lower_param_types);

    let mut sources = Vec::new();
    for (loc, ty) in param_locs.iter().zip(lower_param_types.iter()) {
        for preg in aarch64_abi_location_pregs(loc, ty) {
            push_unique_overlap(&mut sources, preg);
        }
    }
    sources
}

fn aarch64_entry_formal_abi_source_regs(ir_func: &IrMachFunction) -> Vec<PReg> {
    let abi_sources = aarch64_formal_abi_source_regs(&ir_func.signature);
    if abi_sources.is_empty() {
        return Vec::new();
    }

    let Some(entry_block) = ir_func.blocks.get(ir_func.entry.0 as usize) else {
        return Vec::new();
    };

    let mut sources = Vec::new();
    for &inst_id in &entry_block.insts {
        let Some(inst) = ir_func.insts.get(inst_id.0 as usize) else {
            continue;
        };

        if inst.opcode == IrOpcode::Copy
            && let Some(IrOperand::PReg(src)) = inst.operands.get(1)
            && let Some(&source) = abi_sources
                .iter()
                .find(|&&source| regs_overlap(source, *src))
        {
            push_unique_overlap(&mut sources, source);
            continue;
        }

        if inst.opcode == IrOpcode::LdrRI
            && matches!(inst.operands.get(2), Some(IrOperand::IncomingArg(_)))
        {
            continue;
        }

        break;
    }

    sources
}

fn aarch64_abi_location_pregs(loc: &ArgLocation, ty: &LowerType) -> Vec<PReg> {
    match loc {
        ArgLocation::Reg(preg) => vec![*preg],
        ArgLocation::RegPair(lo_preg, hi_preg) => vec![*lo_preg, *hi_preg],
        ArgLocation::RegSequence(regs) => regs.clone(),
        ArgLocation::Indirect { ptr_reg } => {
            let mut regs = vec![*ptr_reg];
            if ty.is_aggregate() && ty.bytes() <= 16 {
                regs.push(PReg::new(ptr_reg.encoding() + 1));
            }
            regs
        }
        ArgLocation::Stack { .. } => Vec::new(),
    }
}

fn remove_overlapping_preg(regs: &mut Vec<PReg>, reg: PReg) {
    regs.retain(|&candidate| !regs_overlap(candidate, reg));
}

fn aarch64_inst_reads_unread_formal_sources(inst: &IrMachInst, unread: &[PReg]) -> Vec<PReg> {
    let (_, use_positions) = classify_operand_positions(inst);
    let mut reads = Vec::new();

    for pos in use_positions {
        let Some(IrOperand::PReg(preg)) = inst.operands.get(pos) else {
            continue;
        };
        for &source in unread {
            if regs_overlap(source, *preg) {
                push_unique_overlap(&mut reads, source);
            }
        }
    }

    reads
}

fn verify_aarch64_formal_entry_copy_hazards(ir_func: &IrMachFunction) -> Result<(), PipelineError> {
    let mut unread = aarch64_entry_formal_abi_source_regs(ir_func);
    if unread.is_empty() {
        return Ok(());
    }

    let Some(entry_block) = ir_func.blocks.get(ir_func.entry.0 as usize) else {
        return Ok(());
    };

    for &inst_id in &entry_block.insts {
        if unread.is_empty() {
            break;
        }

        let Some(inst) = ir_func.insts.get(inst_id.0 as usize) else {
            continue;
        };
        let reads = aarch64_inst_reads_unread_formal_sources(inst, &unread);
        let (def_positions, _) = classify_operand_positions(inst);

        for pos in def_positions {
            let Some(IrOperand::PReg(dst)) = inst.operands.get(pos) else {
                continue;
            };
            if let Some(&source) = unread.iter().find(|&&source| {
                regs_overlap(source, *dst) && !reads.iter().any(|&read| regs_overlap(read, source))
            }) {
                return Err(PipelineError::Aarch64FormalArgCopyHazard(format!(
                    "function={} inst={} opcode={:?} dst={} aliases unread ABI source {}",
                    ir_func.name,
                    inst_id.0,
                    inst.opcode,
                    preg_name(*dst),
                    preg_name(source)
                )));
            }
        }

        for read in reads {
            remove_overlapping_preg(&mut unread, read);
        }
    }

    Ok(())
}

/// Drop pure dead defs whose destination stayed virtual after regalloc.
///
/// Linear-scan omits dead values from the allocation map. That is fine for
/// liveness, but the encoder cannot accept a post-regalloc instruction with a
/// still-virtual destination. For pure instructions, an unallocated def means
/// the value is dead, so the instruction can be converted to pseudo-Nop.
pub fn eliminate_dead_unallocated_defs(ir_func: &mut IrMachFunction) {
    let impure_flags = trust_cg_ir::inst::InstFlags::HAS_SIDE_EFFECTS
        .union(trust_cg_ir::inst::InstFlags::READS_MEMORY)
        .union(trust_cg_ir::inst::InstFlags::WRITES_MEMORY)
        .union(trust_cg_ir::inst::InstFlags::IS_CALL)
        .union(trust_cg_ir::inst::InstFlags::IS_BRANCH)
        .union(trust_cg_ir::inst::InstFlags::IS_RETURN)
        .union(trust_cg_ir::inst::InstFlags::IS_TERMINATOR)
        .union(trust_cg_ir::inst::InstFlags::IS_PHI);

    for inst in &mut ir_func.insts {
        if inst.is_pseudo() || !inst.opcode.produces_value() || inst.operands.is_empty() {
            continue;
        }

        let has_unallocated_dst = matches!(inst.operands.first(), Some(IrOperand::VReg(_)));
        if !has_unallocated_dst || !inst.flags.intersection(impure_flags).is_empty() {
            continue;
        }

        inst.opcode = IrOpcode::Nop;
        inst.flags = trust_cg_ir::inst::InstFlags::IS_PSEUDO;
        inst.operands.clear();
    }
}

fn reachable_vreg_use_counts(ir_func: &IrMachFunction) -> HashMap<VReg, usize> {
    let mut use_counts = HashMap::new();

    for &block_id in &ir_func.block_order {
        let block = ir_func.block(block_id);
        for &inst_id in &block.insts {
            let inst = ir_func.inst(inst_id);
            let (_, use_positions) = classify_operand_positions(inst);
            for pos in use_positions {
                if let Some(IrOperand::VReg(vreg)) = inst.operands.get(pos) {
                    *use_counts.entry(*vreg).or_insert(0) += 1;
                }
            }
        }
    }

    use_counts
}

fn dead_def_discard_register(vreg: VReg) -> Option<PReg> {
    match vreg.class {
        RegClass::Gpr64 => Some(XZR),
        RegClass::Gpr32 | RegClass::System => Some(WZR),
        // AArch64 has no architectural FP/SIMD zero register. V16/V17 and
        // every width alias are deliberately excluded from the allocator and
        // reserved for post-RA scratch use (see aarch64_allocatable_regs and
        // scratch_pool_for_class). A dead side-effecting load can therefore
        // target the first reserved alias without clobbering an allocated
        // value. Its result has no uses, so its lifetime ends at the load.
        RegClass::Fpr16 => Some(H16),
        RegClass::Fpr32 => Some(S16),
        RegClass::Fpr64 => Some(D16),
        RegClass::Fpr128 => Some(V16),
        _ => None,
    }
}

/// Preserve side-effecting dead definitions whose destination stayed virtual.
///
/// The allocator may omit a dead value from both the allocation map and spill
/// metadata. Pure dead defs are removed by `eliminate_dead_unallocated_defs`,
/// but memory reads cannot be dropped without changing fault behavior. Binding
/// their unused destination to XZR/WZR (GPR) or a reserved V16 width alias
/// (FP/SIMD) preserves the read while avoiding a clobber of any live allocated
/// register.
pub fn bind_dead_unallocated_defs_to_discard_registers(
    ir_func: &mut IrMachFunction,
) -> Result<(), PipelineError> {
    let use_counts = reachable_vreg_use_counts(ir_func);
    let inst_ids: Vec<InstId> = ir_func
        .blocks
        .iter()
        .flat_map(|block| block.insts.iter().copied())
        .collect();

    for inst_id in inst_ids {
        let inst = ir_func.inst(inst_id);
        let (def_positions, _) = classify_operand_positions(inst);
        if !inst.opcode.produces_value() || def_positions.is_empty() {
            continue;
        }

        for def_pos in def_positions {
            let Some(IrOperand::VReg(vreg)) = ir_func.inst(inst_id).operands.get(def_pos) else {
                continue;
            };
            if use_counts.get(vreg).copied().unwrap_or(0) != 0 {
                continue;
            }

            let Some(discard) = dead_def_discard_register(*vreg) else {
                let inst = ir_func.inst(inst_id);
                return Err(PipelineError::RegAlloc(format!(
                    "cannot bind dead unallocated def for {:?} class {:?} in {:?}",
                    inst.opcode, vreg.class, inst
                )));
            };
            ir_func.inst_mut(inst_id).operands[def_pos] = IrOperand::PReg(discard);
        }
    }

    Ok(())
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum RegAllocDebugDef {
    VReg(VReg),
    PReg(PReg),
}

#[derive(Debug, Clone, Default)]
struct RegAllocDebugSnapshot {
    allocation: BTreeMap<VReg, PReg>,
    spilled_vregs: BTreeSet<VReg>,
    spill_slots: BTreeMap<VReg, StackSlotId>,
    spill_stores: Vec<SpillMaterializedStore>,
    inst_map: Vec<Option<InstId>>,
    defs: BTreeMap<InstId, RegAllocDebugDef>,
}

#[derive(Debug, Clone)]
struct RegAllocOutcome {
    spill_slot_count: usize,
    post_ra_copies_coalesced: u32,
    debug_snapshot: RegAllocDebugSnapshot,
}

fn collect_regalloc_debug_defs(ir_func: &IrMachFunction) -> BTreeMap<InstId, RegAllocDebugDef> {
    ir_func
        .insts
        .iter()
        .enumerate()
        .filter_map(|(idx, inst)| {
            let (def_positions, _) = classify_operand_positions(inst);
            let [def_pos] = def_positions.as_slice() else {
                return None;
            };
            match inst.operands.get(*def_pos) {
                Some(IrOperand::VReg(vreg)) => {
                    Some((InstId(idx as u32), RegAllocDebugDef::VReg(*vreg)))
                }
                Some(IrOperand::PReg(preg)) => {
                    Some((InstId(idx as u32), RegAllocDebugDef::PReg(*preg)))
                }
                _ => None,
            }
        })
        .collect()
}

// ---------------------------------------------------------------------------
// Encoding: IR MachFunction -> machine code bytes
// ---------------------------------------------------------------------------

/// Resolve symbolic block references in branch instructions to byte offsets.
///
/// After register allocation and frame lowering, branch instructions may still
/// contain `Block(BlockId)` operands from the ISel. This pass computes the byte
/// offset of each block in the final layout and replaces Block operands with
/// immediate offsets (PC-relative, in instruction units).
///
/// Must be called after frame lowering (which may add instructions) and before
/// encoding (which needs concrete offsets).
pub fn resolve_branches(func: &mut IrMachFunction) -> Result<(), PipelineError> {
    validate_aarch64_mach_function(func)?;
    resolve_branches_after_validation(func);
    Ok(())
}

/// Resolve branches after the public symbolic CFG authority boundary has
/// already passed and post-RA guard expansion may have inserted validated
/// intra-block immediate skip branches.
///
/// This is the final-emission entry: `block_order` and the instruction
/// stream are FINAL here, so it is also the single point where the loop-head
/// alignment pass inserts its `AlignNop` padding — immediately BEFORE the
/// offsets are computed, so every resolved displacement already includes the
/// padding. (Kill switch `TCG_NO_LOOP_HEAD_ALIGN`; see
/// [`crate::loop_align`].)
fn resolve_branches_after_authority(func: &mut IrMachFunction) -> Result<(), PipelineError> {
    validate_aarch64_mach_function_totality(func)?;
    crate::loop_align::align_innermost_loop_heads(func);
    resolve_branches_after_validation(func);
    Ok(())
}

fn resolve_branches_after_validation(func: &mut IrMachFunction) {
    // Phase 1: Compute the instruction-index offset of each block.
    // Walk blocks in layout order, counting non-pseudo instructions.
    let mut block_offsets: HashMap<BlockId, i64> = HashMap::new();
    let mut current_offset: i64 = 0;

    for &block_id in &func.block_order {
        block_offsets.insert(block_id, current_offset);
        let block = &func.blocks[block_id.0 as usize];
        for &inst_id in &block.insts {
            let inst = &func.insts[inst_id.0 as usize];
            if !inst.is_pseudo() {
                current_offset += 1; // Each instruction is 4 bytes = 1 instruction unit
            }
        }
    }

    // Phase 2: Walk all instructions and replace Block operands with offsets.
    // For each branch instruction, find the Block operand, look up its offset,
    // and replace it with the PC-relative offset (in instruction units).
    let mut inst_offset: i64 = 0;
    for &block_id in &func.block_order.clone() {
        let block = &func.blocks[block_id.0 as usize];
        let inst_ids: Vec<_> = block.insts.clone();
        for &inst_id in &inst_ids {
            let inst = &func.insts[inst_id.0 as usize];
            if inst.is_pseudo() {
                continue;
            }

            let is_branch = matches!(
                inst.opcode,
                IrOpcode::B
                    | IrOpcode::TailCall
                    | IrOpcode::BCond
                    | IrOpcode::Cbz
                    | IrOpcode::Cbnz
                    | IrOpcode::Tbz
                    | IrOpcode::Tbnz
            );

            if is_branch {
                // Find and resolve Block operands to PC-relative immediates.
                let new_operands: Vec<IrOperand> = inst
                    .operands
                    .iter()
                    .map(|op| {
                        if let IrOperand::Block(target_block) = op {
                            if let Some(&target_offset) = block_offsets.get(target_block) {
                                // PC-relative offset in instruction units
                                let rel_offset = target_offset - inst_offset;
                                IrOperand::Imm(rel_offset)
                            } else {
                                op.clone()
                            }
                        } else {
                            op.clone()
                        }
                    })
                    .collect();
                func.insts[inst_id.0 as usize].operands = new_operands;
            }

            inst_offset += 1;
        }
    }
}

/// Encode a single IR instruction into AArch64 machine code.
///
/// Delegates to the unified encoder in [`crate::aarch64::encode`] which
/// dispatches to the correct format-specific encoding function.
fn encode_ir_inst(inst: &IrMachInst) -> Result<u32, PipelineError> {
    crate::aarch64::encode::encode_instruction(inst)
        .map_err(|e| PipelineError::Encoding(e.to_string()))
}

/// Reject public code/fixup-only AArch64 boundaries that cannot return the
/// exact LSDA/personality/FDE sidecar. The EH-aware single/module object paths
/// call the private block-tracking encoder core directly and retain that data.
fn reject_aarch64_eh_sidecar_drop(
    func: &IrMachFunction,
    api: &'static str,
) -> Result<(), PipelineError> {
    // Preserve the stronger malformed-function diagnostic when the machine IR
    // is invalid; the sidecar guard is about valid EH input losing authority.
    validate_aarch64_mach_function_totality(func)?;
    if !func.eh_metadata.has_eh_info() {
        return Ok(());
    }
    Err(PipelineError::EhSidecarUnsupported {
        function: func.name.clone(),
        api,
        reason: "the return type carries only code/fixups and cannot return the exact LSDA, personality, and unwind-frame metadata; use an EH-aware object/module API instead (fail-closed)"
            .to_string(),
    })
}

/// Encode all instructions in a function to machine code bytes.
///
/// Walks blocks in layout order, encoding each non-pseudo instruction.
pub fn encode_function(func: &IrMachFunction) -> Result<Vec<u8>, PipelineError> {
    reject_aarch64_eh_sidecar_drop(func, "encode_function")?;
    let (code, _fixups, _block_offsets) = encode_function_with_fixups_and_blocks_impl(func, None)?;
    Ok(code)
}

/// Encode all instructions in a function to machine code bytes, collecting
/// fixups for cross-function references.
///
/// When a BL/B instruction has a [`Symbol`](IrOperand::Symbol) operand instead
/// of an immediate, the encoder emits a placeholder (`BL 0`) and records a
/// [`Fixup`](crate::macho::fixup::Fixup) with a `Branch26` relocation kind.
/// The caller (typically [`Pipeline::compile_module`]) resolves these fixups
/// into relocations for the linker.
///
/// Returns `(code_bytes, fixup_list)`.
pub fn encode_function_with_fixups(
    func: &IrMachFunction,
) -> Result<(Vec<u8>, crate::macho::fixup::FixupList), PipelineError> {
    reject_aarch64_eh_sidecar_drop(func, "encode_function_with_fixups")?;
    let (code, fixups, _block_offsets) = encode_function_with_fixups_and_blocks_impl(func, None)
        .map_err(|err| match err {
            PipelineError::Encoding(msg) => {
                PipelineError::Encoding(format!("[encode_function_with_fixups] {msg}"))
            }
            other => other,
        })?;
    Ok((code, fixups))
}

fn encode_module_function_with_fixups(
    func: &IrMachFunction,
) -> Result<(Vec<u8>, crate::macho::fixup::FixupList), PipelineError> {
    validate_aarch64_mach_function_totality(func)?;
    if let Some(cleaned) = rbit_return_prefix_copy_cleaned(func) {
        encode_function_with_fixups(&cleaned)
    } else {
        encode_function_with_fixups(func)
    }
}

/// Per-function exception-handling payload collected by the generic module
/// emitters during Phase-1 encoding, consumed by
/// [`Pipeline::emit_module_macho_with_unwind`].
struct ModuleFunctionEhData {
    /// Encoded code length in bytes (the compact-unwind / FDE range).
    code_len: u32,
    /// `(lsda_bytes, personality)` for functions carrying EH structure.
    lsda: Option<(Vec<u8>, String)>,
}

/// Whole-module unwind emission plan (sections + symbols created, relocations
/// pending until the symbol table is final).
struct ModuleUnwindPlan {
    /// Undefined `_<personality>` symbol id. `None` for a module with no EH
    /// function: its unwind entries describe frames only (walk-through), no
    /// pad ever dispatches, and adding an undefined personality would force
    /// every plain-C link to pull in a C++/Rust EH runtime it never calls.
    personality_symbol: Option<crate::macho::SymbolId>,
    /// Per-function `_GCC_except_table_*` symbol id (real or filler LSDA).
    lsda_symbols: Vec<Option<crate::macho::SymbolId>>,
    /// Per-function compact unwind encoding (from its frame layout).
    encodings: Vec<crate::frame::CompactUnwindEncoding>,
    /// DWARF-fallback FDE context, when any function needs it.
    dwarf: Option<ModuleUnwindDwarf>,
}

/// `__eh_frame` emission context for DWARF-fallback functions in a module.
struct ModuleUnwindDwarf {
    /// The CIE+FDE builder (for relocation offset queries).
    cfi: crate::dwarf_cfi::DwarfCfiSection,
    /// 0-based `__eh_frame` section index.
    eh_frame_section: usize,
    /// Local `EH_Frame` symbol id (subtractor base).
    eh_frame_symbol: crate::macho::SymbolId,
    /// For each FDE (in add order), the index of its function.
    fde_functions: Vec<usize>,
}

/// Encode one function for the generic module emitters.
///
/// Non-EH functions take the exact pre-existing
/// [`encode_module_function_with_fixups`] path (byte-identical output). EH
/// functions take the block-tracking encode path so the post-layout LSDA
/// call-site/landing-pad byte offsets can be resolved (mirroring the proven
/// single-function `compile_function` sequence), returning the generated LSDA
/// bytes + personality alongside the code.
fn encode_module_function_with_fixups_and_eh(
    func: &IrMachFunction,
) -> Result<
    (
        Vec<u8>,
        crate::macho::fixup::FixupList,
        Option<(Vec<u8>, String)>,
    ),
    PipelineError,
> {
    if !func.eh_metadata.has_eh_info() {
        let (code, fixups) = encode_module_function_with_fixups(func)?;
        return Ok((code, fixups, None));
    }

    // EH functions need block byte offsets to resolve the LSDA call-site table
    // + landing-pad offsets. `resolve_eh_offsets` mutates the EH metadata, so
    // work on a clone (the module emitters borrow their inputs). The rbit
    // prefix-copy cleanup only applies to single-block functions and EH
    // functions always have >= 2 blocks, so skipping it here cannot change the
    // emitted bytes.
    let mut resolved = func.clone();
    let (code, fixups, block_offsets) =
        encode_function_with_fixups_and_blocks_impl(&resolved, None)?;
    resolve_eh_offsets(&mut resolved, &block_offsets, code.len())?;
    let lsda = generate_lsda_for_function(&resolved)?.ok_or_else(|| {
        PipelineError::Encoding(format!(
            "EH function `{}` produced no LSDA despite carrying EH metadata",
            func.name
        ))
    })?;
    let personality = crate::exception_handling::required_personality_symbol(
        resolved.eh_metadata.personality.as_deref(),
    )
    .map_err(|error| PipelineError::MalformedAarch64Function {
        function: resolved.name.clone(),
        detail: format!("invalid exception-handling personality: {error}"),
    })?
    .to_string();
    Ok((code, fixups, Some((lsda, personality))))
}

fn rbit_return_prefix_copy_cleaned(func: &IrMachFunction) -> Option<IrMachFunction> {
    if func.block_order.len() != 1 {
        return None;
    }

    let block_id = *func.block_order.first()?;
    let block = func.block(block_id);
    let mut idx = 0;
    while idx + 2 < block.insts.len() {
        let copy_id = block.insts[idx];
        let rbit_id = block.insts[idx + 1];
        let ret_id = block.insts[idx + 2];
        if is_redundant_rbit_return_prefix_copy(
            func.inst(copy_id),
            func.inst(rbit_id),
            func.inst(ret_id),
        ) {
            let mut cleaned = func.clone();
            cleaned.blocks[block_id.0 as usize].insts.remove(idx);
            return Some(cleaned);
        }
        idx += 1;
    }

    None
}

fn is_redundant_rbit_return_prefix_copy(
    copy: &IrMachInst,
    rbit: &IrMachInst,
    ret: &IrMachInst,
) -> bool {
    matches!(
        copy.opcode,
        IrOpcode::MovR | IrOpcode::MOVWrr | IrOpcode::MOVXrr
    ) && rbit.opcode == IrOpcode::Rbit
        && ret.is_return()
        && copy.operands.len() >= 2
        && rbit.operands.len() >= 2
        && copy.implicit_defs.is_empty()
        && copy.implicit_uses.is_empty()
        && rbit.operands.first().and_then(IrOperand::as_preg)
            == rbit.operands.get(1).and_then(IrOperand::as_preg)
        && rbit
            .operands
            .first()
            .and_then(IrOperand::as_preg)
            .is_some_and(|rbit_reg| preg_class(rbit_reg) == RegClass::Gpr32)
        && copy
            .operands
            .first()
            .and_then(IrOperand::as_preg)
            .zip(copy.operands.get(1).and_then(IrOperand::as_preg))
            .zip(rbit.operands.first().and_then(IrOperand::as_preg))
            .is_some_and(|((copy_dst, copy_src), rbit_reg)| {
                hw_encoding(copy_dst) == hw_encoding(copy_src)
                    && hw_encoding(copy_src) == hw_encoding(rbit_reg)
            })
}

/// Like [`encode_function_with_fixups_and_blocks`] but also records the final
/// byte offset of each emitted non-pseudo instruction in `provenance`.
pub fn encode_function_with_fixups_and_blocks_with_provenance(
    func: &IrMachFunction,
    provenance: &mut trust_cg_ir::ProvenanceMap,
) -> Result<
    (
        Vec<u8>,
        crate::macho::fixup::FixupList,
        HashMap<BlockId, u32>,
    ),
    PipelineError,
> {
    reject_aarch64_eh_sidecar_drop(
        func,
        "encode_function_with_fixups_and_blocks_with_provenance",
    )?;
    encode_function_with_fixups_and_blocks_impl(func, Some(provenance))
}

/// Like [`encode_function_with_fixups`] but also returns the byte offset at
/// which each basic block begins in the encoded code.
///
/// Used by the JIT's block-level profile hook path (`ProfileHookMode::
/// BlockCounts`, issue #364) to know where to splice per-block trampolines.
/// The returned offsets are the **pre-trampoline** offsets — i.e. where each
/// block's first instruction lives in the plain encoding. The caller is
/// responsible for shifting these offsets when inserting trampolines and for
/// re-patching any branches whose source/target block spacing changes.
pub fn encode_function_with_fixups_and_blocks(
    func: &IrMachFunction,
) -> Result<
    (
        Vec<u8>,
        crate::macho::fixup::FixupList,
        HashMap<BlockId, u32>,
    ),
    PipelineError,
> {
    reject_aarch64_eh_sidecar_drop(func, "encode_function_with_fixups_and_blocks")?;
    encode_function_with_fixups_and_blocks_impl(func, None)
}

#[derive(Debug, Clone, Copy)]
struct SymbolicAArch64FixupKind {
    kind: crate::macho::AArch64RelocKind,
    tls_model: Option<trust_cg_ir::TlsModel>,
}

/// Does `inst` (post-regalloc) write physical register `preg` — via an
/// explicit def-position operand or an implicit clobber (call defs)?
fn inst_writes_preg(inst: &trust_cg_ir::MachInst, preg: PReg) -> bool {
    if inst.implicit_defs.contains(&preg) {
        return true;
    }
    let mut writes = false;
    trust_cg_opt::effects::aarch64_for_each_def_position(inst.opcode, inst.operands.len(), |pos| {
        if inst.operands.get(pos).and_then(|op| op.as_preg()) == Some(preg) {
            writes = true;
        }
    });
    writes
}

/// Find the GOT/TLVP consumer that pairs a symbolic `ADRP dst, @sym`, scanning
/// FORWARD through the block along `dst`'s dataflow.
///
/// The consumer (`LdrGot`/`LdrTlvp` with base == `dst` and the same symbol) is
/// emitted adjacent to its ADRP by ISel, but the SCHEDULER may legally sink
/// unrelated instructions between them. The historical version of this scan
/// inspected only the IMMEDIATELY next non-pseudo instruction, so a scheduled
/// gap made the ADRP fall back to a DIRECT `PAGE21` while the distant LDR
/// still emitted `GOT_LOAD_PAGEOFF12` — a MIXED pair computing
/// `page(sym) + lo12(got_slot_of_sym)`, i.e. a wild load (the wp10-on-Linux
/// `std::panicking::set_hook` HOOK-pointer null-deref class; on Darwin the
/// same mix was masked by ld64's GOT-load relaxation for locally-defined
/// symbols, and on ELF by page-layout coincidence until the layout shifted).
///
/// The scan stops (no pairing) as soon as anything else writes `dst`: past
/// that point the ADRP's page value is dead, so a later `LdrGot` of the same
/// register belongs to a different ADRP.
fn paired_symbolic_adrp_reloc_kind(
    func: &IrMachFunction,
    block_insts: &[InstId],
    inst_index: usize,
    adrp_dst: PReg,
    symbol: &str,
) -> Option<SymbolicAArch64FixupKind> {
    for &next_id in block_insts.iter().skip(inst_index + 1) {
        let next = func.inst(next_id);
        if next.is_pseudo() {
            continue;
        }

        if matches!(
            next.opcode,
            IrOpcode::LdrGot | IrOpcode::LdrTlvp | IrOpcode::LdrGottprel
        ) {
            let base_matches = next.operands.get(1).and_then(|op| op.as_preg()) == Some(adrp_dst);
            let symbol_matches = next.operands.get(2).and_then(|op| op.as_symbol()) == Some(symbol);
            if base_matches && symbol_matches {
                return Some(match next.opcode {
                    IrOpcode::LdrGot => SymbolicAArch64FixupKind {
                        kind: crate::macho::AArch64RelocKind::GotLoadPage21,
                        tls_model: None,
                    },
                    IrOpcode::LdrTlvp => SymbolicAArch64FixupKind {
                        kind: crate::macho::AArch64RelocKind::TlvpLoadPage21,
                        tls_model: Some(trust_cg_ir::TlsModel::Tlv),
                    },
                    IrOpcode::LdrGottprel => SymbolicAArch64FixupKind {
                        kind: crate::macho::AArch64RelocKind::ElfTlsieAdrGottprelPage21,
                        tls_model: Some(trust_cg_ir::TlsModel::InitialExec),
                    },
                    _ => unreachable!(),
                });
            }
        }

        if inst_writes_preg(next, adrp_dst) {
            return None;
        }
    }

    None
}

/// Fail-closed pairing check for the LDR side of a GOT/TLVP sequence: scan
/// BACKWARD from the `LdrGot`/`LdrTlvp` at `inst_index` for the `ADRP` that
/// produces its base register, and require it to name the SAME symbol. If the
/// base register's def is not such an ADRP (or lies outside this block — e.g.
/// hoisted by a pass), the object would carry a GOT/TLVP page-offset
/// relocation whose page half is missing or direct: a silent wild load.
/// Reject the compile instead.
fn ldr_got_has_pairing_adrp(
    func: &IrMachFunction,
    block_insts: &[InstId],
    inst_index: usize,
    base: PReg,
    symbol: &str,
) -> bool {
    for &prev_id in block_insts.iter().take(inst_index).rev() {
        let prev = func.inst(prev_id);
        if prev.is_pseudo() {
            continue;
        }
        if prev.opcode == IrOpcode::Adrp
            && prev.operands.first().and_then(|op| op.as_preg()) == Some(base)
        {
            return prev.operands.get(1).and_then(|op| op.as_symbol()) == Some(symbol);
        }
        if inst_writes_preg(prev, base) {
            return false;
        }
    }
    false
}

/// Re-pair GOT/TLVP page-offset loads whose feeding `ADRP` was separated
/// from them by SPILL/RELOAD (or any other post-ISel transform): insert a
/// fresh `ADRP base, @sym` immediately before the orphaned load.
///
/// WHY THIS IS REQUIRED FOR CORRECTNESS (not an optimization): the GOT-ness
/// of an `ADRP` is not represented in the machine IR — it is reconstructed
/// at encode time by in-block consumer pairing. When regalloc spills the
/// ADRP's result and reloads it in front of the `LdrGot`, the original ADRP
/// (whose remaining in-block consumer view no longer includes the load)
/// emits a DIRECT `PAGE21` while the load still emits `GOT_LOAD_PAGEOFF12`
/// — a mixed pair computing `page(sym) + lo12(got_slot)`: a wild load (the
/// `std::sys::fs::unix::try_statx` -O1/-O2 class). Rematerializing the page
/// value right before the load is unconditionally sound: `ADRP` is pure
/// (PC-relative page of a link-time constant), the destination register is
/// `base` itself, whose stale reloaded value dies here anyway, and the
/// encode-time forward scan then finds the adjacent load and emits the
/// correct GOT/TLVP page kind. The stale reload becomes dead but harmless.
fn repair_orphaned_got_page_pairs(func: &mut IrMachFunction) {
    let block_ids: Vec<BlockId> = func.block_order.clone();
    for block_id in block_ids {
        // (index in block insts, base preg, symbol) for each orphaned load.
        let mut repairs: Vec<(usize, PReg, String)> = Vec::new();
        {
            let insts = &func.blocks[block_id.0 as usize].insts;
            for (idx, &inst_id) in insts.iter().enumerate() {
                let inst = func.inst(inst_id);
                if !matches!(
                    inst.opcode,
                    IrOpcode::LdrGot | IrOpcode::LdrTlvp | IrOpcode::LdrGottprel
                ) {
                    continue;
                }
                let (Some(base), Some(symbol)) = (
                    inst.operands.get(1).and_then(|op| op.as_preg()),
                    inst.operands.get(2).and_then(|op| op.as_symbol()),
                ) else {
                    continue;
                };
                if !ldr_got_has_pairing_adrp(func, insts, idx, base, symbol) {
                    repairs.push((idx, base, symbol.to_string()));
                }
            }
        }
        // Insert in reverse so earlier indices stay valid.
        for (idx, base, symbol) in repairs.into_iter().rev() {
            let adrp = trust_cg_ir::MachInst::new(
                IrOpcode::Adrp,
                vec![
                    trust_cg_ir::MachOperand::PReg(base),
                    trust_cg_ir::MachOperand::Symbol(symbol),
                ],
            );
            let adrp_id = func.push_inst(adrp);
            func.blocks[block_id.0 as usize].insts.insert(idx, adrp_id);
        }
    }
}

fn verify_got_ldr_page_pairing(
    func: &IrMachFunction,
    block_insts: &[InstId],
    inst_index: usize,
    base: PReg,
    symbol: &str,
) -> Result<(), PipelineError> {
    if ldr_got_has_pairing_adrp(func, block_insts, inst_index, base, symbol) {
        return Ok(());
    }
    Err(PipelineError::Encoding(format!(
        "GOT/TLVP page-offset load in function {} uses base register {base:?} for symbol          '{symbol}' without a pairing `ADRP {base:?}, @{symbol}` in the same block; emitting          it would produce a mixed direct/GOT relocation pair (a wild load at run time).          Fail-closed: the page and page-offset halves must be paired.",
        func.name
    )))
}

/// Validate every arena index and block-bearing side table before an AArch64
/// whole-function pass may index or mutate the function. `blocks` is an arena:
/// CFG cleanup may unlink an unreachable block from `block_order` without
/// renumbering the arena. `block_order` is the executable/encoded domain, so it
/// must be closed under every semantic control-flow authority (branch operands,
/// CFG metadata, jump tables, and EH), but need not contain unreachable arena
/// shells. This totality check is also repeated at the lowest shared encoding
/// boundary; final semantic TV4 enforcement remains in
/// [`enforce_aarch64_post_regalloc`].
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum AArch64CfgValidationStage {
    /// Symbolic branch operands are still available and CFG metadata is about
    /// to become regalloc/TV-5 authority. Require an exact semantic match.
    SymbolicAuthority,
    /// A known internal post-resolution funnel replaced Block operands with
    /// relative immediates after the symbolic-authority check already passed.
    ResolvedEncoding,
}

fn validate_aarch64_mach_function_impl(
    func: &IrMachFunction,
    cfg_stage: AArch64CfgValidationStage,
) -> Result<(), PipelineError> {
    let malformed = |detail: String| PipelineError::MalformedAarch64Function {
        function: func.name.clone(),
        detail,
    };
    let block_count = func.blocks.len();
    let valid_block = |block_id: BlockId| (block_id.0 as usize) < block_count;

    if func.eh_metadata.has_eh_info() {
        crate::exception_handling::required_personality_symbol(
            func.eh_metadata.personality.as_deref(),
        )
        .map_err(|error| malformed(format!("invalid exception-handling personality: {error}")))?;
    }

    if !valid_block(func.entry) {
        return Err(malformed(format!(
            "entry block {:?} is outside the {}-block arena",
            func.entry, block_count
        )));
    }
    let mut seen = BTreeSet::new();
    for &block_id in &func.block_order {
        if !valid_block(block_id) {
            return Err(malformed(format!(
                "block_order contains invalid block {:?}",
                block_id
            )));
        }
        if !seen.insert(block_id) {
            return Err(malformed(format!(
                "block_order duplicates block {:?}",
                block_id
            )));
        }
    }
    if func.block_order.first().copied() != Some(func.entry) {
        return Err(malformed(format!(
            "block_order must start with entry block {:?}, got {:?}",
            func.entry,
            func.block_order.first()
        )));
    }

    let mut linked_insts = BTreeSet::new();
    for (block_index, block) in func.blocks.iter().enumerate() {
        let block_id = BlockId(block_index as u32);
        for (&edge, edge_kind) in block
            .preds
            .iter()
            .map(|edge| (edge, "predecessor"))
            .chain(block.succs.iter().map(|edge| (edge, "successor")))
        {
            if !valid_block(edge) {
                return Err(malformed(format!(
                    "block {:?} has invalid {} target {:?}",
                    block_id, edge_kind, edge
                )));
            }
            if seen.contains(&block_id) && !seen.contains(&edge) {
                return Err(malformed(format!(
                    "laid-out block {:?} has {} target {:?} absent from block_order",
                    block_id, edge_kind, edge
                )));
            }
        }

        for &inst_id in &block.insts {
            let inst = func.insts.get(inst_id.0 as usize).ok_or_else(|| {
                malformed(format!(
                    "block {:?} references instruction {:?} outside the {}-instruction arena",
                    block_id,
                    inst_id,
                    func.insts.len()
                ))
            })?;
            if !linked_insts.insert(inst_id) {
                return Err(malformed(format!(
                    "instruction {:?} is linked from more than one block position",
                    inst_id
                )));
            }

            if inst.opcode == IrOpcode::TailCall {
                if inst.flags != IrOpcode::TailCall.default_flags() {
                    return Err(malformed(format!(
                        "tail-call instruction {:?} has non-canonical flags {:?}",
                        inst_id, inst.flags
                    )));
                }
                if !matches!(
                    inst.operands.as_slice(),
                    [IrOperand::Symbol(_) | IrOperand::Block(_) | IrOperand::Imm(_)]
                ) {
                    return Err(malformed(format!(
                        "tail-call instruction {:?} must carry exactly one direct target operand",
                        inst_id
                    )));
                }
            } else if inst.opcode == IrOpcode::B
                && (!inst.implicit_uses.is_empty()
                    || !inst.implicit_defs.is_empty()
                    || inst.flags.is_call())
            {
                return Err(malformed(format!(
                    "ordinary B instruction {:?} carries call-boundary metadata; use structural TailCall",
                    inst_id
                )));
            }

            if seen.contains(&block_id) && inst.is_branch() {
                let has_block_target = inst
                    .operands
                    .iter()
                    .any(|operand| matches!(operand, IrOperand::Block(_)));
                let has_immediate = inst
                    .operands
                    .iter()
                    .any(|operand| matches!(operand, IrOperand::Imm(_)));
                if !has_block_target
                    && has_immediate
                    && cfg_stage == AArch64CfgValidationStage::SymbolicAuthority
                {
                    return Err(malformed(format!(
                        "branch instruction {:?} carries a resolved immediate before the symbolic CFG authority boundary",
                        inst_id
                    )));
                }
            }

            for (operand_index, operand) in inst.operands.iter().enumerate() {
                match operand {
                    IrOperand::Block(target) => {
                        if !valid_block(*target) {
                            return Err(malformed(format!(
                                "instruction {:?} operand {} has invalid block target {:?}",
                                inst_id, operand_index, target
                            )));
                        }
                        if seen.contains(&block_id) && !seen.contains(target) {
                            return Err(malformed(format!(
                                "laid-out block {:?} instruction {:?} operand {} targets {:?}, which is absent from block_order",
                                block_id, inst_id, operand_index, target
                            )));
                        }
                    }
                    IrOperand::StackSlot(slot) if slot.0 as usize >= func.stack_slots.len() => {
                        return Err(malformed(format!(
                            "instruction {:?} operand {} references stack slot {:?} outside the {}-slot arena",
                            inst_id,
                            operand_index,
                            slot,
                            func.stack_slots.len()
                        )));
                    }
                    IrOperand::JumpTableIndex(index)
                        if *index as usize >= func.jump_tables.len() =>
                    {
                        return Err(malformed(format!(
                            "instruction {:?} operand {} references jump table {} outside the {}-table arena",
                            inst_id,
                            operand_index,
                            index,
                            func.jump_tables.len()
                        )));
                    }
                    _ => {}
                }
            }
        }
    }

    if let Some(slot) = func.stack_protector_slot
        && slot.0 as usize >= func.stack_slots.len()
    {
        return Err(malformed(format!(
            "stack protector references slot {:?} outside the {}-slot arena",
            slot,
            func.stack_slots.len()
        )));
    }
    for (table_index, table) in func.jump_tables.iter().enumerate() {
        for &target in &table.targets {
            if !valid_block(target) {
                return Err(malformed(format!(
                    "jump table {} has invalid block target {:?}",
                    table_index, target
                )));
            }
            if !seen.contains(&target) {
                return Err(malformed(format!(
                    "jump table {} targets block {:?}, which is absent from block_order",
                    table_index, target
                )));
            }
        }
    }
    for landing_pad in &func.eh_metadata.landing_pads {
        if !valid_block(landing_pad.block) {
            return Err(malformed(format!(
                "exception landing pad has invalid block target {:?}",
                landing_pad.block
            )));
        }
        if !seen.contains(&landing_pad.block) {
            return Err(malformed(format!(
                "exception landing pad targets block {:?}, which is absent from block_order",
                landing_pad.block
            )));
        }
    }
    for call_site in &func.eh_metadata.call_sites {
        if !valid_block(call_site.call_block) {
            return Err(malformed(format!(
                "exception call site has invalid call block {:?}",
                call_site.call_block
            )));
        }
        if !seen.contains(&call_site.call_block) {
            return Err(malformed(format!(
                "exception call site uses block {:?}, which is absent from block_order",
                call_site.call_block
            )));
        }
        if let Some(target) = call_site.landing_pad_block
            && !valid_block(target)
        {
            return Err(malformed(format!(
                "exception call site has invalid landing-pad block {:?}",
                target
            )));
        }
        if let Some(target) = call_site.landing_pad_block
            && !seen.contains(&target)
        {
            return Err(malformed(format!(
                "exception call site targets landing-pad block {:?}, which is absent from block_order",
                target
            )));
        }
    }

    if cfg_stage == AArch64CfgValidationStage::SymbolicAuthority {
        let expected_edges = derive_ir_cfg_edges_from_branch_operands(func);
        let mut expected_succs = vec![BTreeSet::new(); block_count];
        let mut expected_preds = vec![BTreeSet::new(); block_count];
        for (from, to) in expected_edges {
            if !seen.contains(&from) || !seen.contains(&to) {
                return Err(malformed(format!(
                    "semantic control edge {:?} -> {:?} escapes block_order",
                    from, to
                )));
            }
            expected_succs[from.0 as usize].insert(to);
            expected_preds[to.0 as usize].insert(from);
        }
        for &block_id in &func.block_order {
            let block_index = block_id.0 as usize;
            let block = &func.blocks[block_index];
            let actual_succs: BTreeSet<_> = block.succs.iter().copied().collect();
            if actual_succs.len() != block.succs.len() {
                return Err(malformed(format!(
                    "block {:?} contains duplicate successor metadata: {:?}",
                    block_id, block.succs
                )));
            }
            if actual_succs != expected_succs[block_index] {
                return Err(malformed(format!(
                    "block {:?} successor metadata {:?} does not match semantic control edges {:?}",
                    block_id, actual_succs, expected_succs[block_index]
                )));
            }

            let actual_preds: BTreeSet<_> = block.preds.iter().copied().collect();
            if actual_preds.len() != block.preds.len() {
                return Err(malformed(format!(
                    "block {:?} contains duplicate predecessor metadata: {:?}",
                    block_id, block.preds
                )));
            }
            if actual_preds != expected_preds[block_index] {
                return Err(malformed(format!(
                    "block {:?} predecessor metadata {:?} does not match reciprocal semantic edges {:?}",
                    block_id, actual_preds, expected_preds[block_index]
                )));
            }
        }
    }

    Ok(())
}

pub(crate) fn validate_aarch64_mach_function(func: &IrMachFunction) -> Result<(), PipelineError> {
    validate_aarch64_mach_function_impl(func, AArch64CfgValidationStage::SymbolicAuthority)
}

pub(crate) fn validate_aarch64_mach_function_totality(
    func: &IrMachFunction,
) -> Result<(), PipelineError> {
    validate_aarch64_mach_function_impl(func, AArch64CfgValidationStage::ResolvedEncoding)
}

pub(crate) fn enforce_aarch64_post_regalloc_resolved(
    func: &IrMachFunction,
) -> Result<(), PipelineError> {
    enforce_aarch64_post_regalloc_impl(func, AArch64CfgValidationStage::ResolvedEncoding)
}

fn enforce_aarch64_post_regalloc_impl(
    func: &IrMachFunction,
    cfg_stage: AArch64CfgValidationStage,
) -> Result<(), PipelineError> {
    use trust_cg_verify::post_ra_reaching_def as prd;
    use trust_cg_verify::post_ra_spill_slots as pss;
    use trust_cg_verify::post_regalloc_recheck as prr;

    // The verifier below indexes both arenas. Keep the total boundary check
    // first so malformed public input is always a typed error, never a panic.
    validate_aarch64_mach_function_impl(func, cfg_stage)?;
    if cfg_stage == AArch64CfgValidationStage::ResolvedEncoding
        && !func.blocks.iter().any(|block| {
            block.insts.iter().any(|inst_id| {
                func.insts.get(inst_id.0 as usize).is_some_and(|inst| {
                    inst.is_branch()
                        && !inst
                            .operands
                            .iter()
                            .any(|operand| matches!(operand, IrOperand::Block(_)))
                        && inst
                            .operands
                            .iter()
                            .any(|operand| matches!(operand, IrOperand::Imm(_)))
                })
            })
        })
    {
        // Public low-level encoders may still be handed a wholly symbolic
        // stream. Preserve exact CFG rejection there; totality-only validation
        // is reserved for streams that actually contain resolved/internal
        // immediate branches and are reconstructed below.
        validate_aarch64_mach_function_impl(func, AArch64CfgValidationStage::SymbolicAuthority)?;
    }
    let mut derived_cfg_func = None;
    if cfg_stage == AArch64CfgValidationStage::ResolvedEncoding {
        derived_cfg_func = Some(reconstruct_aarch64_resolved_cfg(func).map_err(|detail| {
            PipelineError::MalformedAarch64Function {
                function: func.name.clone(),
                detail,
            }
        })?);
    }
    let verified_func = derived_cfg_func.as_ref().unwrap_or(func);

    for &block_id in &verified_func.block_order {
        verify_aarch64_final_call_argument_sequence(
            &verified_func.name,
            verified_func
                .block(block_id)
                .insts
                .iter()
                .map(|&inst_id| verified_func.inst(inst_id)),
        )?;
    }

    let mode = prr::post_regalloc_recheck_mode(prr::AARCH64_POST_RA_RECHECK_DEFAULT);
    if let Some(violation) = prr::evaluate(verified_func, "aarch64", mode) {
        return Err(PipelineError::RegAlloc(format!(
            "[TCG-POST-RA-RECHECK] fn `{}` final AArch64 stream violation ({}): {}",
            verified_func.name,
            violation.kind.tag(),
            violation.detail
        )));
    }

    // TV-6 reaching-definition net (WARN default): flag any post-RA physical
    // register read with no reaching definition on every path. Runs ALONGSIDE
    // the structural recheck above; env-gated via TCG_AARCH64_POST_RA_REACHING_DEF.
    let reaching_def_mode = prd::reaching_def_mode();
    if let Some(violation) = prd::evaluate(verified_func, reaching_def_mode) {
        return Err(PipelineError::RegAlloc(format!(
            "[TCG-A64-REACHING-DEF] fn `{}` final AArch64 stream reaching-def violation ({}): {}",
            verified_func.name,
            violation.kind.tag(),
            violation.detail
        )));
    }

    // TV-6 spill-SLOT reaching-store net (WARN default): flag any post-RA reload
    // from an SP-relative spill slot with no reaching store on every path — the
    // memory-dataflow companion to the register reaching-def net above (a dropped
    // or wrong-offset spill store the register check cannot see). Runs ALONGSIDE
    // both checks; env-gated via TCG_AARCH64_POST_RA_SPILL_SLOTS.
    let spill_slot_mode = pss::spill_slot_mode();
    if let Some(violation) = pss::evaluate(verified_func, spill_slot_mode) {
        return Err(PipelineError::RegAlloc(format!(
            "[TCG-A64-SPILL-SLOT] fn `{}` final AArch64 stream spill-slot violation ({}): {}",
            verified_func.name,
            violation.kind.tag(),
            violation.detail
        )));
    }
    Ok(())
}

fn encode_function_with_fixups_and_blocks_impl(
    func: &IrMachFunction,
    mut provenance: Option<&mut trust_cg_ir::ProvenanceMap>,
) -> Result<
    (
        Vec<u8>,
        crate::macho::fixup::FixupList,
        HashMap<BlockId, u32>,
    ),
    PipelineError,
> {
    use crate::macho::fixup::{Fixup, FixupList};
    use trust_cg_ir::inst::AArch64Opcode;

    enforce_aarch64_post_regalloc_resolved(func)?;

    let mut code = Vec::new();
    let mut fixups = FixupList::new();

    // Track byte offsets of each block in the final layout, for jump
    // table patching. This is computed inline as we emit instructions.
    let mut block_byte_offsets: HashMap<BlockId, u32> = HashMap::new();
    // Pending Adr-for-jump-table fixups: (adr_byte_offset, jump_table_idx).
    let mut jt_adr_fixups: Vec<(u32, u32)> = Vec::new();

    // ENC-5: record every emitted word + its intent for the independent
    // decode-check (run over the FINAL bytes just before return). Arms whose
    // word is patched later (linker relocations) record a hole so the
    // patched field's placeholder VALUE is not compared.
    let dc_mode = crate::aarch64::decode_check::a64_decode_check_mode();
    let mut dc_items: Vec<crate::decode_check::DecodeCheckItem<trust_cg_ir::inst::MachInst>> =
        Vec::new();
    let dc_push =
        |items: &mut Vec<crate::decode_check::DecodeCheckItem<trust_cg_ir::inst::MachInst>>,
         start: usize,
         intent: &trust_cg_ir::inst::MachInst,
         hole: Option<crate::decode_check::FixupHole>| {
            if dc_mode != crate::decode_check::DecodeCheckMode::Off {
                items.push(crate::decode_check::DecodeCheckItem {
                    intent: intent.clone(),
                    start,
                    end: start + 4,
                    hole,
                });
            }
        };

    for &block_id in &func.block_order {
        // Record the starting byte offset of this block for later jump-table
        // patching (case target blocks resolve against this map).
        let block_byte_offset = u32::try_from(code.len()).map_err(|_| {
            PipelineError::Encoding(format!(
                "function {} block {:?} offset {} exceeds the u32 AArch64 relocation/LSDA domain",
                func.name,
                block_id,
                code.len()
            ))
        })?;
        block_byte_offsets.insert(block_id, block_byte_offset);

        let block = func.block(block_id);
        for (inst_index, &inst_id) in block.insts.iter().enumerate() {
            let inst = func.inst(inst_id);
            // Skip pseudo-instructions that should have been eliminated.
            if inst.is_pseudo() {
                continue;
            }

            if let Some((operand_idx, vreg)) =
                inst.operands
                    .iter()
                    .enumerate()
                    .find_map(|(operand_idx, operand)| match operand {
                        IrOperand::VReg(vreg) => Some((operand_idx, *vreg)),
                        _ => None,
                    })
            {
                return Err(PipelineError::Encoding(format!(
                    "unresolved vreg {} reached encode in function {} block {:?} inst {:?} operand {} opcode {:?} operands {:?}",
                    vreg.id, func.name, block_id, inst_id, operand_idx, inst.opcode, inst.operands
                )));
            }

            let byte_offset = u32::try_from(code.len()).map_err(|_| {
                PipelineError::Encoding(format!(
                    "function {} instruction {:?} offset {} exceeds the u32 AArch64 relocation/LSDA domain",
                    func.name,
                    inst_id,
                    code.len()
                ))
            })?;

            // Check for BL/B with Symbol operand — needs a relocation fixup.
            let has_symbol_target = matches!(
                inst.opcode,
                AArch64Opcode::Bl | AArch64Opcode::BL | AArch64Opcode::B | AArch64Opcode::TailCall
            ) && inst.operands.first().is_some_and(|op| op.is_symbol());
            let adrp_symbol = if inst.opcode == AArch64Opcode::Adrp {
                inst.operands.get(1).and_then(|op| op.as_symbol())
            } else {
                None
            };
            let pageoff_symbol = if matches!(
                inst.opcode,
                AArch64Opcode::AddPCRel
                    | AArch64Opcode::LdrGot
                    | AArch64Opcode::LdrTlvp
                    | AArch64Opcode::LdrGottprel
                    | AArch64Opcode::AddTprelHi12
                    | AArch64Opcode::AddTprelLo12
            ) {
                inst.operands.get(2).and_then(|op| op.as_symbol())
            } else {
                None
            };

            // Check for ADR with JumpTableIndex operand — emit placeholder,
            // patch the imm21 after we know the table byte offset.
            let adr_jt_idx = if inst.opcode == AArch64Opcode::Adr {
                inst.operands.get(1).and_then(|op| op.as_jump_table_index())
            } else {
                None
            };

            if has_symbol_target {
                // Emit BL/B with imm26=0 (placeholder — linker will patch via relocation).
                let op_bit = match inst.opcode {
                    AArch64Opcode::B | AArch64Opcode::TailCall => 0u32,
                    _ => 1u32, // Bl and BL are both BL
                };
                let placeholder = crate::aarch64::encoding::encode_uncond_branch(op_bit, 0);
                code.extend_from_slice(&placeholder.to_le_bytes());
                dc_push(
                    &mut dc_items,
                    byte_offset as usize,
                    inst,
                    Some(crate::decode_check::FixupHole {
                        offset_in_inst: 0,
                        width: 4,
                        kind: crate::decode_check::FixupHoleKind::Call,
                    }),
                );

                // Record a Branch26 fixup. The symbol name is stored in the fixup
                // target — the module-level emitter resolves it to a symbol index.
                let sym_name = inst.operands[0].as_symbol().ok_or_else(|| {
                    PipelineError::Encoding(format!(
                        "BL/B instruction at offset {} has non-symbol operand",
                        byte_offset
                    ))
                })?;
                fixups.push(Fixup::branch_sym(byte_offset, sym_name.to_string()));
            } else if let Some(sym_name) = adrp_symbol {
                let rd_preg = inst.operands[0].as_preg().ok_or_else(|| {
                    PipelineError::Encoding(format!(
                        "ADRP instruction at offset {} has no PReg destination",
                        byte_offset
                    ))
                })?;
                let rd = trust_cg_ir::aarch64_regs::hw_encoding(rd_preg);
                let placeholder = crate::aarch64::encoding_mem::encode_adrp(0, rd)
                    .map_err(|e| PipelineError::Encoding(e.to_string()))?;
                code.extend_from_slice(&placeholder.to_le_bytes());
                dc_push(
                    &mut dc_items,
                    byte_offset as usize,
                    inst,
                    Some(crate::decode_check::FixupHole {
                        offset_in_inst: 0,
                        width: 4,
                        kind: crate::decode_check::FixupHoleKind::GlobalRef,
                    }),
                );
                let paired_kind = paired_symbolic_adrp_reloc_kind(
                    func,
                    &block.insts,
                    inst_index,
                    rd_preg,
                    sym_name,
                )
                .unwrap_or(SymbolicAArch64FixupKind {
                    kind: crate::macho::AArch64RelocKind::Page21,
                    tls_model: None,
                });
                fixups.push(crate::macho::fixup::Fixup {
                    offset: byte_offset,
                    kind: paired_kind.kind,
                    tls_model: paired_kind.tls_model,
                    target: crate::macho::FixupTarget::NamedSymbol(sym_name.to_string()),
                    addend: 0,
                });
            } else if let Some(sym_name) = pageoff_symbol {
                let sf = if inst
                    .operands
                    .first()
                    .and_then(|op| op.as_preg())
                    .is_some_and(|preg| preg_class(preg) == RegClass::Gpr64)
                {
                    1
                } else {
                    0
                };
                let word = match inst.opcode {
                    AArch64Opcode::AddPCRel => crate::aarch64::encoding::encode_add_sub_imm(
                        sf,
                        0,
                        0,
                        0,
                        0,
                        trust_cg_ir::aarch64_regs::hw_encoding(
                            inst.operands[1].as_preg().ok_or_else(|| {
                                PipelineError::Encoding(format!(
                                    "ADD PC-relative instruction at offset {} has no PReg base",
                                    byte_offset
                                ))
                            })?,
                        ) as u32,
                        trust_cg_ir::aarch64_regs::hw_encoding(
                            inst.operands[0].as_preg().ok_or_else(|| {
                                PipelineError::Encoding(format!(
                                    "ADD PC-relative instruction at offset {} has no PReg destination",
                                    byte_offset
                                ))
                            })?,
                        ) as u32,
                    ),
                    // ELF local-exec TLS TPREL adds: `ADD Xd, Xn, #0 (, LSL
                    // #12)` placeholders; the linker patches imm12 via
                    // `R_AARCH64_TLSLE_ADD_TPREL_HI12` / `_LO12_NC`. The hi12
                    // half sets sh=1 (LSL #12), matching gcc/binutils
                    // local-exec codegen (0x91400000 / 0x91000000 skeletons).
                    AArch64Opcode::AddTprelHi12 | AArch64Opcode::AddTprelLo12 => {
                        crate::aarch64::encoding::encode_add_sub_imm(
                            sf,
                            0,
                            0,
                            (inst.opcode == AArch64Opcode::AddTprelHi12) as u32,
                            0,
                            trust_cg_ir::aarch64_regs::hw_encoding(
                                inst.operands[1].as_preg().ok_or_else(|| {
                                    PipelineError::Encoding(format!(
                                        "ADD TPREL instruction at offset {} has no PReg base",
                                        byte_offset
                                    ))
                                })?,
                            ) as u32,
                            trust_cg_ir::aarch64_regs::hw_encoding(
                                inst.operands[0].as_preg().ok_or_else(|| {
                                    PipelineError::Encoding(format!(
                                        "ADD TPREL instruction at offset {} has no PReg destination",
                                        byte_offset
                                    ))
                                })?,
                            ) as u32,
                        )
                    }
                    AArch64Opcode::LdrGot
                    | AArch64Opcode::LdrTlvp
                    | AArch64Opcode::LdrGottprel => {
                        crate::aarch64::encoding::encode_load_store_ui(
                            0b11,
                            0,
                            0b01,
                            0,
                            trust_cg_ir::aarch64_regs::hw_encoding(
                                inst.operands[1].as_preg().ok_or_else(|| {
                                    PipelineError::Encoding(format!(
                                        "LDR symbolic instruction at offset {} has no PReg base",
                                        byte_offset
                                    ))
                                })?,
                            ) as u32,
                            trust_cg_ir::aarch64_regs::hw_encoding(
                                inst.operands[0].as_preg().ok_or_else(|| {
                                    PipelineError::Encoding(format!(
                                        "LDR symbolic instruction at offset {} has no PReg destination",
                                        byte_offset
                                    ))
                                })?,
                            ) as u32,
                        )
                    }
                    _ => unreachable!(),
                };
                code.extend_from_slice(&word.to_le_bytes());
                dc_push(
                    &mut dc_items,
                    byte_offset as usize,
                    inst,
                    Some(crate::decode_check::FixupHole {
                        offset_in_inst: 0,
                        width: 4,
                        kind: crate::decode_check::FixupHoleKind::GlobalRef,
                    }),
                );
                // Fail-closed pairing symmetry: a GOT/TLVP page-offset LDR
                // whose base is not fed by a same-symbol ADRP in this block
                // would emit a mixed direct/GOT relocation pair (wild load).
                if matches!(
                    inst.opcode,
                    AArch64Opcode::LdrGot | AArch64Opcode::LdrTlvp | AArch64Opcode::LdrGottprel
                ) {
                    let base_preg = inst.operands[1].as_preg().ok_or_else(|| {
                        PipelineError::Encoding(format!(
                            "LDR symbolic instruction at offset {} has no PReg base",
                            byte_offset
                        ))
                    })?;
                    verify_got_ldr_page_pairing(
                        func,
                        &block.insts,
                        inst_index,
                        base_preg,
                        sym_name,
                    )?;
                }
                let kind = match inst.opcode {
                    AArch64Opcode::AddPCRel => crate::macho::AArch64RelocKind::Pageoff12,
                    AArch64Opcode::LdrGot => crate::macho::AArch64RelocKind::GotLoadPageoff12,
                    AArch64Opcode::LdrTlvp => crate::macho::AArch64RelocKind::TlvpLoadPageoff12,
                    AArch64Opcode::LdrGottprel => {
                        crate::macho::AArch64RelocKind::ElfTlsieLd64GottprelLo12Nc
                    }
                    AArch64Opcode::AddTprelHi12 => {
                        crate::macho::AArch64RelocKind::ElfTlsleAddTprelHi12
                    }
                    AArch64Opcode::AddTprelLo12 => {
                        crate::macho::AArch64RelocKind::ElfTlsleAddTprelLo12Nc
                    }
                    _ => unreachable!(),
                };
                let tls_model = match inst.opcode {
                    AArch64Opcode::LdrTlvp => Some(trust_cg_ir::TlsModel::Tlv),
                    AArch64Opcode::LdrGottprel => Some(trust_cg_ir::TlsModel::InitialExec),
                    AArch64Opcode::AddTprelHi12 | AArch64Opcode::AddTprelLo12 => {
                        Some(trust_cg_ir::TlsModel::LocalExec)
                    }
                    _ => None,
                };
                fixups.push(crate::macho::fixup::Fixup {
                    offset: byte_offset,
                    kind,
                    tls_model,
                    target: crate::macho::FixupTarget::NamedSymbol(sym_name.to_string()),
                    addend: 0,
                });
            } else if let Some(jt_idx) = adr_jt_idx {
                // Emit ADR with imm21=0 (placeholder); record fixup so we can
                // patch it after the jump table is appended below.
                let rd_preg = inst.operands[0].as_preg().ok_or_else(|| {
                    PipelineError::Encoding(format!(
                        "Adr instruction at offset {} has no PReg destination",
                        byte_offset
                    ))
                })?;
                let rd = trust_cg_ir::aarch64_regs::hw_encoding(rd_preg);
                let placeholder = crate::aarch64::encoding_mem::encode_adr(0, rd)
                    .map_err(|e| PipelineError::Encoding(e.to_string()))?;
                code.extend_from_slice(&placeholder.to_le_bytes());
                jt_adr_fixups.push((byte_offset, jt_idx));
                // The ADR word is patched in-function below, BEFORE the
                // decode-check runs, so its bytes are final — no hole.
                dc_push(&mut dc_items, byte_offset as usize, inst, None);
            } else {
                let word = encode_ir_inst(inst).map_err(|err| match err {
                    PipelineError::Encoding(msg) => PipelineError::Encoding(format!(
                        "{msg} in function {} block {:?} inst {:?} opcode {:?} operands {:?}",
                        func.name, block_id, inst_id, inst.opcode, inst.operands
                    )),
                    other => other,
                })?;
                code.extend_from_slice(&word.to_le_bytes());
                dc_push(&mut dc_items, byte_offset as usize, inst, None);
            }

            // This encoder is the authority behind EH's exact InstId -> byte
            // re-derivation: every non-pseudo AArch64 instruction must emit one
            // and only one fixed-width word before any trailing jump-table data.
            // Keep that contract executable so a future multiword expansion
            // fails closed instead of making LSDA ranges drift silently.
            let expected_end = usize::try_from(byte_offset)
                .ok()
                .and_then(|offset| offset.checked_add(4))
                .ok_or_else(|| {
                    PipelineError::Encoding(format!(
                        "function {} instruction {:?} encoded-end calculation overflow",
                        func.name, inst_id
                    ))
                })?;
            if code.len() != expected_end {
                return Err(PipelineError::Encoding(format!(
                    "function {} instruction {:?} emitted {} bytes; exact AArch64 layout requires 4",
                    func.name,
                    inst_id,
                    code.len().saturating_sub(byte_offset as usize)
                )));
            }

            if let Some(provenance) = provenance.as_deref_mut() {
                provenance.record_encoding(inst_id, byte_offset);
            }
        }
    }

    // Emit jump tables after the function body and patch the corresponding
    // ADR instructions.
    //
    // Layout: each table lives in the same __text section, placed right
    // after the function body. Entries are 32-bit signed offsets from the
    // table base to the case target block: `target_byte_offset -
    // table_base_byte_offset`. At runtime, the switch computes:
    //   x_base = table_base_addr (via ADR)
    //   x_off  = sign_extend_32(table[index])
    //   br     x_base + x_off
    for (adr_offset, jt_idx) in &jt_adr_fixups {
        let jt = func.jump_tables.get(*jt_idx as usize).ok_or_else(|| {
            PipelineError::Encoding(format!(
                "ADR at {:#x} references unknown jump table index {}",
                adr_offset, jt_idx
            ))
        })?;

        // The table is appended at the current end of the code buffer. Each
        // ADR may reference its own (possibly distinct) table; we allocate
        // one table per fixup in the order they appeared.
        //
        // Note: if two ADRs reference the same `jt_idx`, only the first
        // emission writes the table; subsequent ADRs still patch against
        // the same table_offset (see `placed_tables` map).
        let table_offset = u32::try_from(code.len()).map_err(|_| {
            PipelineError::Encoding(format!(
                "function {} jump-table offset {} exceeds the u32 AArch64 relocation domain",
                func.name,
                code.len()
            ))
        })?;

        // Patch the ADR imm21 with the byte offset from the ADR to the table.
        let pc_relative = table_offset as i64 - *adr_offset as i64;
        if !(-(1 << 20)..(1 << 20)).contains(&pc_relative) {
            return Err(PipelineError::Encoding(format!(
                "ADR->jump table offset {} does not fit in imm21",
                pc_relative
            )));
        }
        // Re-extract the destination register from the placeholder encoding:
        // bits[4:0] hold Rd. Simpler: decode the placeholder we already
        // wrote.
        let placeholder_bytes = &code[*adr_offset as usize..(*adr_offset as usize + 4)];
        let placeholder_word = u32::from_le_bytes([
            placeholder_bytes[0],
            placeholder_bytes[1],
            placeholder_bytes[2],
            placeholder_bytes[3],
        ]);
        let rd = (placeholder_word & 0x1F) as u8;
        let patched = crate::aarch64::encoding_mem::encode_adr(pc_relative as i32, rd)
            .map_err(|e| PipelineError::Encoding(e.to_string()))?;
        code[*adr_offset as usize..(*adr_offset as usize + 4)]
            .copy_from_slice(&patched.to_le_bytes());

        // Append the table entries: 32-bit signed offsets from the table
        // base to each target block.
        for target in &jt.targets {
            let target_offset = block_byte_offsets.get(target).copied().ok_or_else(|| {
                PipelineError::Encoding(format!(
                    "Jump table target block {:?} has no byte offset",
                    target
                ))
            })?;
            let entry: i32 = (target_offset as i64 - table_offset as i64) as i32;
            code.extend_from_slice(&entry.to_le_bytes());
        }
    }

    // ENC-5: run the independent decode-check over the FINAL bytes (after
    // the in-function jump-table ADR patches; linker-patched words carry
    // holes). Enforce failures are fail-closed pipeline errors; the a64
    // default is WARN until the slice-3 corpus-sweep ratchet.
    crate::decode_check::run_decode_check(
        &crate::aarch64::decode_check::A64DecodeCheck,
        &dc_items,
        &code,
        dc_mode,
    )
    .map_err(|err| PipelineError::Encoding(err.message))?;

    Ok((code, fixups, block_byte_offsets))
}

fn macho_symbol_name(name: &str) -> String {
    format!("_{}", name)
}

/// Module-level AOT PGO counter array symbol. One u64 slot per instrumented
/// basic block across the whole module; the GEN-mode object DEFINES this
/// global (zero-initialized, `n_sites * 8` bytes) and every injected counter
/// increment addresses it via `Adrp`/`AddPCRel` PAGE21/PAGEOFF12 relocations.
pub const PGO_COUNTER_ARRAY_SYMBOL: &str = "__tcg_pgo_counters";

/// Module-level AOT PGO site-count symbol: a single u64 (little-endian)
/// holding the number of counter slots, so the dump runtime knows how many
/// u64s to write without a sidecar at run time.
pub const PGO_NSITES_SYMBOL: &str = "__tcg_pgo_nsites";

/// Highest representable counter index: the injected `LdrRI`/`StrRI` use the
/// unsigned scaled 12-bit offset form (8-byte scale), so `idx * 8` must stay
/// within `4095 * 8`. Exceeding it FAILS CLOSED (error, never a wrapped or
/// unscaled fallback) — a canary build with >4096 blocks module-wide should
/// say so loudly rather than silently corrupt profile slots.
const PGO_MAX_COUNTER_INDEX: u64 = 4095;

/// Inject one AOT profile counter increment at the head of every basic block
/// (after any leading `Phi` pseudos, which must stay at the block head for
/// phi elimination):
///
/// ```text
///   adrp  vP, __tcg_pgo_counters@PAGE
///   add   vA, vP, __tcg_pgo_counters@PAGEOFF
///   ldr   vC, [vA, #idx*8]
///   add   vN, vC, #1
///   str   vN, [vA, #idx*8]
/// ```
///
/// All five use FRESH vregs, so the injected code is SSA-clean and register
/// allocation treats it like any other code. `idx` is the module-wide dense
/// counter index: the sink lock is held across base reservation + site
/// recording so concurrent per-function preparation cannot interleave a
/// function's slots (the driver additionally compiles sequentially in GEN
/// mode so slot ASSIGNMENT ORDER is deterministic).
///
/// NOT atomic: the increment is a plain load/add/store, so counts from
/// multi-threaded canaries are approximate (racing increments can drop). The
/// consumer (`branch_taken_rate`) treats counts as estimates and clamps.
fn inject_aot_block_counters(
    func: &mut IrMachFunction,
    sink: &Arc<std::sync::Mutex<trust_cg_opt::pgo::CounterMap>>,
) -> Result<(), PipelineError> {
    let mut guard = match sink.lock() {
        Ok(guard) => guard,
        Err(poisoned) => poisoned.into_inner(),
    };
    let base = guard.sites.len() as u64;
    let blocks: Vec<BlockId> = func.block_order.clone();

    // Fail closed BEFORE mutating anything if any slot would exceed the
    // scaled-offset ceiling.
    if !blocks.is_empty() {
        let last_index = base + blocks.len() as u64 - 1;
        if last_index > PGO_MAX_COUNTER_INDEX {
            return Err(PipelineError::Aarch64ObjectFieldTooLarge {
                function: func.name.clone(),
                field: "pgo counter index (LdrRI/StrRI scaled offset ceiling)",
                value: last_index as u128,
                max: PGO_MAX_COUNTER_INDEX as u128,
            });
        }
    }

    for (i, &block_id) in blocks.iter().enumerate() {
        let index = base + i as u64;
        let byte_off = (index * 8) as i64;

        let page = VReg::new(func.alloc_vreg(), RegClass::Gpr64);
        let addr = VReg::new(func.alloc_vreg(), RegClass::Gpr64);
        let cur = VReg::new(func.alloc_vreg(), RegClass::Gpr64);
        let next = VReg::new(func.alloc_vreg(), RegClass::Gpr64);

        let ids = [
            func.push_inst(IrMachInst::new(
                IrOpcode::Adrp,
                vec![
                    IrOperand::VReg(page),
                    IrOperand::Symbol(PGO_COUNTER_ARRAY_SYMBOL.to_string()),
                ],
            )),
            func.push_inst(IrMachInst::new(
                IrOpcode::AddPCRel,
                vec![
                    IrOperand::VReg(addr),
                    IrOperand::VReg(page),
                    IrOperand::Symbol(PGO_COUNTER_ARRAY_SYMBOL.to_string()),
                ],
            )),
            func.push_inst(IrMachInst::new(
                IrOpcode::LdrRI,
                vec![
                    IrOperand::VReg(cur),
                    IrOperand::VReg(addr),
                    IrOperand::Imm(byte_off),
                ],
            )),
            func.push_inst(IrMachInst::new(
                IrOpcode::AddRI,
                vec![
                    IrOperand::VReg(next),
                    IrOperand::VReg(cur),
                    IrOperand::Imm(1),
                ],
            )),
            func.push_inst(IrMachInst::new(
                IrOpcode::StrRI,
                vec![
                    IrOperand::VReg(next),
                    IrOperand::VReg(addr),
                    IrOperand::Imm(byte_off),
                ],
            )),
        ];

        // Insert after any leading Phi pseudos (phi grouping is a block-head
        // invariant consumed by phi elimination / liveness).
        let blk_index = block_id.0 as usize;
        let insert_at = func.blocks[blk_index]
            .insts
            .iter()
            .position(|&iid| func.insts[iid.0 as usize].opcode != IrOpcode::Phi)
            .unwrap_or(func.blocks[blk_index].insts.len());
        func.blocks[blk_index]
            .insts
            .splice(insert_at..insert_at, ids);

        guard.sites.push(trust_cg_opt::pgo::CounterSite {
            function: func.name.clone(),
            block_id: block_id.0,
            counter_index: index as u32,
            symbol: trust_cg_opt::pgo::counter_symbol(&func.name, block_id.0),
        });
    }

    Ok(())
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ObjectGlobal {
    pub name: String,
    pub data: Vec<u8>,
    pub mutable: bool,
    /// Whether this global's symbol is EXTERNALLY visible (exported from the
    /// object) rather than module-local. Mirrors the trust-ir global's linkage:
    /// `External` / weak / link-once map to `true`; `Internal` / `Private` map to
    /// `false`. A `MonoItem::Static` defined under its own (`#[no_mangle]` or
    /// mangled) symbol needs `true` so a reader in another object / crate / C
    /// driver can resolve it via a data relocation; a private const-alloc copy
    /// (vtable / string literal) is `false`. The Mach-O emitters pass this as the
    /// symbol's `is_global` flag.
    pub is_external: bool,
    /// Relocatable pointer-sized elements embedded in this global's `data`.
    ///
    /// Each entry records that the 8 bytes of `data` starting at `offset` are a
    /// placeholder for the run-time address of `symbol` (a function or data
    /// global, defined-in-module or external) plus `addend`. The object writer
    /// turns each into a data-section absolute-pointer relocation
    /// (`X86_64_RELOC_UNSIGNED` on Mach-O, `R_X86_64_64` on ELF). This is the
    /// vtable / `static FNS: [fn(); N]` keystone: a global whose slots are
    /// symbol addresses the linker fills in. Empty for plain byte globals.
    pub symbol_refs: Vec<GlobalSymbolRef>,
    /// Whether this global is thread-local. When `true` the AArch64 Mach-O
    /// emitter routes this global to the Darwin thread-local sections
    /// (`__thread_data` holds the initial-value template; `__thread_vars` holds
    /// the `tlv_descriptor` symbol a `#[thread_local]` read addresses via the
    /// `ARM64_RELOC_TLVP_LOAD_PAGE21`/`PAGEOFF12` relocations) instead of
    /// `__data`/`__const`. The specific dynamic TLS model is resolved earlier,
    /// during ISel (`TlsModel::Tlv`); object emission only needs the flag.
    /// Thread-local globals are not yet supported by the ELF/x86-64 emitters and
    /// fail closed there.
    pub is_thread_local: bool,
    /// Whether this global is an IMPORT — a reference to a symbol DEFINED in
    /// another object, not a definition emitted here. An import contributes no
    /// section bytes and no defining symbol; its only effect is that a fixup
    /// against its `name` resolves to an undefined-external symbol the linker
    /// satisfies from the defining object.
    ///
    /// This is the cross-object thread-local path: a `#[thread_local]` static is
    /// emitted (its `tlv_descriptor` defined) exactly once, in its own object;
    /// every OTHER object that READS it carries an import of that descriptor
    /// symbol so the `__text` TLVP relocation (`Opcode::TlsRef`) resolves to the
    /// single canonical descriptor rather than defining a duplicate (which would
    /// be a link-time duplicate-symbol error, or divergent per-object storage).
    /// An import is necessarily `is_external` and has empty `data`.
    pub is_import: bool,
    /// Whether this global's DEFINITION is WEAK (coalescable / overridable).
    ///
    /// Mirrors the trust-ir global's linkage: `Weak` / `LinkOnce` (link-once ODR)
    /// map to `true`; `External` / `Internal` / `Private` map to `false`. A weak
    /// defined symbol is emitted with the Mach-O `N_WEAK_DEF` (`n_desc` `0x0080`)
    /// flag / the ELF `STB_WEAK` binding, so that MULTIPLE objects each defining
    /// the same symbol COALESCE to one at link time instead of raising a
    /// duplicate-strong-definition error. This is the keystone of the
    /// cross-static `ptr::eq` fix: a promoted/merged immutable `static` referenced
    /// by another `static` is emitted ONCE as a canonical weak symbol that every
    /// reader imports (so all `&A` sites share one address), and any duplicate
    /// promotion of it coalesces rather than dup-strong-erroring.
    ///
    /// Only meaningful for a DEFINITION (`is_import == false`); an import stays a
    /// strong undefined reference regardless. Weak necessarily implies
    /// `is_external` (a module-local symbol has nothing to coalesce against).
    pub is_weak: bool,
    /// Byte alignment of this global's storage, a power of two (>= 1).
    ///
    /// Taken from the trust-ir `Global.align` (an explicit `#[repr(align(N))]` /
    /// SIMD over-alignment request) when present, else derived from the global's
    /// type layout. The Mach-O / ELF global-section emitters align each global's
    /// section offset UP to this value and widen the owning section's alignment
    /// to the max seen, so an over-aligned static lands on a correctly-aligned
    /// address instead of being packed back-to-back at the section base.
    pub align: u32,
}

/// A relocatable pointer element inside an [`ObjectGlobal`]'s data.
///
/// See [`ObjectGlobal::symbol_refs`]. The `offset` is relative to the start of
/// the owning global's `data` (the writer adds the global's offset within its
/// emitted section to get the section-relative relocation offset).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct GlobalSymbolRef {
    /// Byte offset of the 8-byte pointer slot within the global's `data`.
    pub offset: u64,
    /// Unmangled name of the target symbol (function or data global).
    pub symbol: String,
    /// Constant byte offset added to the resolved symbol address.
    pub addend: i64,
}

/// Validate the public AArch64 object-global surface before any section writer
/// performs offset arithmetic or mutates an object.
///
/// `module_object_globals` produces these invariants, but the `Pipeline` APIs
/// also accept hand-built `ObjectGlobal` values. Invalid pointer slots used to
/// reach an unchecked slice write in the Mach-O data emitter; reject them as a
/// recoverable pipeline error instead of panicking or emitting ambiguous bytes.
fn validate_aarch64_object_globals(globals: &[ObjectGlobal]) -> Result<(), PipelineError> {
    const POINTER_SIZE: u64 = 8;
    let mut names = BTreeSet::new();
    for global in globals {
        if global.name.is_empty() {
            return Err(PipelineError::Encoding(
                "AArch64 object global has an empty symbol name (fail-closed)".to_string(),
            ));
        }
        if !names.insert(global.name.as_str()) {
            return Err(PipelineError::Encoding(format!(
                "AArch64 object contains duplicate global symbol `{}` (fail-closed)",
                global.name
            )));
        }
        if global.align == 0 || !global.align.is_power_of_two() {
            return Err(PipelineError::Encoding(format!(
                "AArch64 object global `{}` has invalid alignment {} (expected a non-zero power of two; fail-closed)",
                global.name, global.align
            )));
        }
        if global.is_import
            && (!global.is_external || !global.data.is_empty() || !global.symbol_refs.is_empty())
        {
            return Err(PipelineError::Encoding(format!(
                "AArch64 object global `{}` is an import but carries local bytes, pointer slots, or non-external linkage (fail-closed)",
                global.name
            )));
        }
        if global.is_weak && (global.is_import || !global.is_external) {
            return Err(PipelineError::Encoding(format!(
                "AArch64 object global `{}` has invalid weak linkage (weak requires an external definition; fail-closed)",
                global.name
            )));
        }

        let mut slot_offsets = BTreeSet::new();
        for symbol_ref in &global.symbol_refs {
            if symbol_ref.symbol.is_empty() {
                return Err(PipelineError::Encoding(format!(
                    "AArch64 object global `{}` has a pointer slot with an empty target symbol (fail-closed)",
                    global.name
                )));
            }
            if !slot_offsets.insert(symbol_ref.offset) {
                return Err(PipelineError::Encoding(format!(
                    "AArch64 object global `{}` has duplicate pointer relocations at byte offset {} (fail-closed)",
                    global.name, symbol_ref.offset
                )));
            }
            let end = symbol_ref.offset.checked_add(POINTER_SIZE).ok_or_else(|| {
                PipelineError::Encoding(format!(
                    "AArch64 object global `{}` pointer slot offset {} overflows (fail-closed)",
                    global.name, symbol_ref.offset
                ))
            })?;
            if end > global.data.len() as u64 {
                return Err(PipelineError::Encoding(format!(
                    "AArch64 object global `{}` pointer slot [{}..{}) exceeds its {} initializer bytes (fail-closed)",
                    global.name,
                    symbol_ref.offset,
                    end,
                    global.data.len()
                )));
            }
        }
    }
    Ok(())
}

/// One defined-global symbol row produced by [`add_elf_global_sections`]:
/// where the global's bytes were placed and how its symbol must be emitted.
struct ElfGlobalSymbolRow {
    name: String,
    /// 1-based section header index the global was placed in.
    section: u16,
    /// Byte offset of the global within that section.
    offset: u64,
    /// Symbol size in bytes (the global's data length).
    size: u64,
    /// `STB_WEAK` coalescable definition (vs `STB_GLOBAL`/local strong).
    is_weak: bool,
    /// Thread-local (`.tdata` resident): the symbol must be `STT_TLS` (its
    /// value is a TLS-template offset, not an address).
    is_tls: bool,
    /// trust-ir `External`/`Weak`/`LinkOnce` linkage: the symbol lives in the
    /// GLOBAL partition (resolvable from other objects). `Internal`/`Private`
    /// globals MUST be `STB_LOCAL`: every module carries its own copy of
    /// content-hashed internals (`str.<hash>`, `vtable.<hash>`), and emitting
    /// them `STB_GLOBAL` makes any two modules sharing a hash collide with
    /// "multiple definition" at static link (the ELF analogue of the Mach-O
    /// emitter honoring `ObjectGlobal::is_external`).
    is_external: bool,
}

/// The names of thread-local IMPORTS (initializer-less cross-object TLS
/// references). They contribute no section bytes; each must be emitted as an
/// UNDEFINED `STT_TLS` symbol so the local-exec TPREL relocations against it
/// resolve to the defining object's TLS block at static link (an undefined
/// `STT_NOTYPE` symbol would be a TLS-vs-non-TLS symbol-kind mismatch).
fn elf_tls_import_names(globals: &[ObjectGlobal]) -> Vec<String> {
    globals
        .iter()
        .filter(|global| global.is_thread_local && global.is_import)
        .map(|global| global.name.clone())
        .collect()
}

fn add_elf_global_sections(
    writer: &mut crate::elf::ElfWriter,
    globals: &[ObjectGlobal],
) -> Vec<ElfGlobalSymbolRow> {
    use crate::elf::constants::{SHF_ALLOC, SHF_TLS, SHF_WRITE, SHT_PROGBITS};

    let mut symbols = Vec::new();
    // IMPORTS (initializer-less cross-object references, TLS or data) define
    // no bytes here: placing one would emit a zero-size DEFINITION that
    // collides with (or shadows) the real definition in another object.
    // They resolve through undefined symbols instead (mirrors the Mach-O
    // emitter's import exclusion).
    let mutable_globals: Vec<&ObjectGlobal> = globals
        .iter()
        .filter(|global| !global.is_thread_local && !global.is_import && global.mutable)
        .collect();
    let immutable_globals: Vec<&ObjectGlobal> = globals
        .iter()
        .filter(|global| !global.is_thread_local && !global.is_import && !global.mutable)
        .collect();
    // Thread-local DEFINITIONS: their initial-value templates live in
    // `.tdata` (SHF_TLS) and their symbols are `STT_TLS`. Initialized and
    // all-zero templates both use `.tdata` (an explicit zero template is
    // semantically identical to a `.tbss` reservation for a definition).
    let tls_globals: Vec<&ObjectGlobal> = globals
        .iter()
        .filter(|global| global.is_thread_local && !global.is_import)
        .collect();

    // Pack a set of globals into one section body, aligning EACH global's
    // offset up to its own declared alignment (an over-aligned static must land
    // on a correctly-aligned offset, not be packed back-to-back), and return
    // the packed bytes, per-global offsets, and the strictest alignment (which
    // the section header must carry so the loader honors the over-alignment).
    fn pack_elf_globals(globals: &[&ObjectGlobal]) -> (Vec<u8>, Vec<u64>, u32) {
        let mut data = Vec::new();
        let mut offsets = Vec::with_capacity(globals.len());
        let mut max_align: u32 = 1;
        for global in globals {
            let align = global.align.max(1) as usize;
            max_align = max_align.max(global.align.max(1));
            let padding = (align - (data.len() % align)) % align;
            data.resize(data.len() + padding, 0);
            offsets.push(data.len() as u64);
            data.extend_from_slice(&global.data);
        }
        (data, offsets, max_align)
    }

    if !mutable_globals.is_empty() {
        let (data, offsets, max_align) = pack_elf_globals(&mutable_globals);
        let section = writer.add_section(
            ".data",
            &data,
            SHT_PROGBITS,
            SHF_ALLOC | SHF_WRITE,
            max_align as u64,
        );
        for (global, offset) in mutable_globals.iter().zip(offsets) {
            symbols.push(ElfGlobalSymbolRow {
                name: global.name.clone(),
                section,
                offset,
                size: global.data.len() as u64,
                is_weak: global.is_weak,
                is_tls: false,
                is_external: global.is_external,
            });
        }
    }

    if !immutable_globals.is_empty() {
        let (data, offsets, max_align) = pack_elf_globals(&immutable_globals);
        let section =
            writer.add_section(".rodata", &data, SHT_PROGBITS, SHF_ALLOC, max_align as u64);
        for (global, offset) in immutable_globals.iter().zip(offsets) {
            symbols.push(ElfGlobalSymbolRow {
                name: global.name.clone(),
                section,
                offset,
                size: global.data.len() as u64,
                is_weak: global.is_weak,
                is_tls: false,
                is_external: global.is_external,
            });
        }
    }

    if !tls_globals.is_empty() {
        // 16-byte-align each template within `.tdata` (matches the strictest
        // alignment a std thread-local template needs on AArch64).
        let mut data: Vec<u8> = Vec::new();
        let mut rows: Vec<(String, u64, u64, bool, bool)> = Vec::new();
        for global in &tls_globals {
            while !data.len().is_multiple_of(16) {
                data.push(0);
            }
            rows.push((
                global.name.clone(),
                data.len() as u64,
                global.data.len() as u64,
                global.is_weak,
                global.is_external,
            ));
            data.extend_from_slice(&global.data);
        }
        let section = writer.add_section(
            ".tdata",
            &data,
            SHT_PROGBITS,
            SHF_ALLOC | SHF_WRITE | SHF_TLS,
            16,
        );
        for (name, offset, size, is_weak, is_external) in rows {
            symbols.push(ElfGlobalSymbolRow {
                name,
                section,
                offset,
                size,
                is_weak,
                is_tls: true,
                is_external,
            });
        }
    }

    symbols
}

fn add_elf_global_object_symbols(
    writer: &mut crate::elf::ElfWriter,
    globals: &[ObjectGlobal],
) -> Vec<String> {
    use crate::elf::constants::{STT_OBJECT, STT_TLS};

    add_elf_global_sections(writer, globals)
        .into_iter()
        .map(|row| {
            let sym_type = if row.is_tls { STT_TLS } else { STT_OBJECT };
            // A weak DEFINITION gets STB_WEAK so duplicate definitions across
            // objects coalesce instead of dup-strong-erroring; an Internal/
            // Private one is STB_LOCAL (content-hashed per-module internals
            // must not collide across objects at static link).
            if row.is_weak {
                writer.add_weak_symbol(&row.name, row.section, row.offset, row.size, sym_type);
            } else {
                writer.add_symbol(
                    &row.name,
                    row.section,
                    row.offset,
                    row.size,
                    row.is_external,
                    sym_type,
                );
            }
            row.name
        })
        .collect()
}

/// Emit immutable module globals into `__TEXT,__const` (`S_REGULAR`, 8-byte
/// aligned), NOT `__cstring`/`S_CSTRING_LITERALS`.
///
/// CORRECTNESS: `S_CSTRING_LITERALS` tells the linker the section holds
/// NUL-terminated C strings, which `ld` deduplicates and merges on NUL
/// boundaries. For arbitrary binary data (e.g. an 8-byte integer with embedded
/// zero bytes) that merging reads only up to the first NUL and coalesces the
/// remainder with adjacent literals — a SILENT MISCOMPILE of every immutable
/// global read (an 8-byte `static N: u64` would link to the bytes of some other
/// string literal). `__TEXT,__const` with `S_REGULAR` keeps the exact bytes and
/// 8-byte alignment, so an ADRP/ADD (`ARM64_RELOC_PAGE21`/`PAGEOFF12`) addressing
/// the symbol reads back the correct value. This mirrors the x86-64 emitter,
/// which places immutable globals in `__TEXT,__const` (`S_REGULAR`) — see
/// `x86_64::pipeline::emit_module_macho`.
fn add_global_const_section(
    writer: &mut crate::macho::MachOWriter,
    globals: &[&ObjectGlobal],
) -> Result<Vec<(String, crate::macho::SymbolId)>, PipelineError> {
    if globals.is_empty() {
        return Ok(Vec::new());
    }

    let mut data = Vec::new();
    let mut offsets = Vec::new();
    offsets.try_reserve_exact(globals.len()).map_err(|error| {
        PipelineError::Encoding(format!(
            "AArch64 immutable-global offset-table allocation failed: {error}"
        ))
    })?;
    // The section's own alignment must cover the strictest per-global alignment
    // (a `#[repr(align(64))]` static needs a 64-aligned section so the loader
    // places its first byte on a 64-aligned address).
    let mut max_align: u32 = 1;
    for global in globals {
        // Align each global up to its OWN declared alignment within the section
        // so an ADRP/ADD pair lands on a correctly-aligned slot.
        let align = global.align.max(1) as usize;
        max_align = max_align.max(global.align.max(1));
        let padding = (align - (data.len() % align)) % align;
        let padded_len = checked_aarch64_size_sum(
            &global.name,
            "immutable-global section alignment",
            data.len(),
            padding,
        )?;
        let final_len = checked_aarch64_size_sum(
            &global.name,
            "immutable-global section byte length",
            padded_len,
            global.data.len(),
        )?;
        data.try_reserve(padding + global.data.len())
            .map_err(|error| {
                PipelineError::Encoding(format!(
                    "AArch64 immutable-global section allocation for `{}` failed: {error}",
                    global.name
                ))
            })?;
        data.resize(padded_len, 0);
        offsets.push(checked_aarch64_object_u64(
            &global.name,
            "immutable-global section offset",
            data.len(),
        )?);
        data.extend_from_slice(&global.data);
        debug_assert_eq!(data.len(), final_len);
    }

    let section_index = writer.add_custom_section(
        b"__const",
        b"__TEXT",
        &data,
        max_align.trailing_zeros(),
        crate::macho::constants::S_REGULAR,
    );
    let section_ordinal = section_index + 1;

    Ok(globals
        .iter()
        .zip(offsets)
        .map(|(global, offset)| {
            let name = macho_symbol_name(&global.name);
            // A weak DEFINITION coalesces across objects (`N_WEAK_DEF`); a strong
            // one is a plain external/local def. Externally-visible globals (e.g.
            // a `#[no_mangle]` / exported `static`) must be GLOBAL symbols so other
            // objects resolve them; private const-alloc copies stay local.
            let symbol_id = if global.is_weak {
                writer.add_weak_symbol(&name, section_ordinal, offset, global.is_external)
            } else {
                writer.add_symbol(&name, section_ordinal, offset, global.is_external)
            }?;
            Ok((global.name.clone(), symbol_id))
        })
        .collect::<Result<Vec<_>, crate::macho::MachOWriteError>>()?)
}

/// A data-section symbol-address relocation (`ARM64_RELOC_UNSIGNED`, 8-byte
/// absolute pointer) deferred until every module symbol exists, so its target's
/// final nlist index is known. This is the AArch64/Mach-O analogue of the
/// x86-64 emitter's `data_reloc_work` (`X86_64_RELOC_UNSIGNED`) — it is what
/// places a function/data address inside a vtable slot or a `static FNS:
/// [fn(); N]` element. Any non-zero addend is baked into the 8-byte section
/// slot before emission (an `ARM64_RELOC_UNSIGNED` adds the resolved symbol
/// address to the in-place value, mirroring clang and the x86-64 path).
struct PendingDataReloc {
    /// 0-based index of the `__DATA,__data` section the slot lives in.
    section_index: usize,
    /// Byte offset of the relocated 8-byte slot within that section.
    offset: u32,
    /// Unmangled target symbol name (a function or data global, in-module or an
    /// undefined external the linker resolves).
    symbol: String,
}

fn add_global_data_section(
    writer: &mut crate::macho::MachOWriter,
    globals: &[&ObjectGlobal],
) -> Result<(Vec<(String, crate::macho::SymbolId)>, Vec<PendingDataReloc>), PipelineError> {
    if globals.is_empty() {
        return Ok((Vec::new(), Vec::new()));
    }

    let mut data = Vec::new();
    let mut offsets = Vec::new();
    offsets.try_reserve_exact(globals.len()).map_err(|error| {
        PipelineError::Encoding(format!(
            "AArch64 mutable-global offset-table allocation failed: {error}"
        ))
    })?;
    // Symbol-address slots to relocate, collected as (section-relative offset,
    // target symbol). The section index is known only after `add_custom_section`.
    let mut reloc_slots: Vec<(u32, String)> = Vec::new();
    // The section's own alignment must cover the strictest per-global alignment.
    let mut max_align: u32 = 1;
    for global in globals {
        // Align each global up to its OWN declared alignment (an atomic /
        // over-aligned static must land on a correctly-aligned address, not be
        // packed back-to-back after the preceding global).
        let align = global.align.max(1) as usize;
        max_align = max_align.max(global.align.max(1));
        let padding = (align - (data.len() % align)) % align;
        let aligned_start = checked_aarch64_size_sum(
            &global.name,
            "mutable-global section alignment",
            data.len(),
            padding,
        )?;
        data.try_reserve(padding).map_err(|error| {
            PipelineError::Encoding(format!(
                "AArch64 mutable-global section alignment padding for `{}` failed: {error}",
                global.name
            ))
        })?;
        data.resize(aligned_start, 0);
        // Section-relative offset of this global (captured AFTER alignment
        // padding but BEFORE the extend, so the reloc-slot math and the
        // offset-table entry agree).
        let global_offset = data.len() as u64;
        let final_len = checked_aarch64_size_sum(
            &global.name,
            "mutable-global section byte length",
            data.len(),
            global.data.len(),
        )?;
        data.try_reserve(global.data.len()).map_err(|error| {
            PipelineError::Encoding(format!(
                "AArch64 mutable-global section allocation for `{}` failed: {error}",
                global.name
            ))
        })?;
        offsets.push(checked_aarch64_object_u64(
            &global.name,
            "mutable-global section offset",
            data.len(),
        )?);
        data.extend_from_slice(&global.data);
        debug_assert_eq!(data.len(), final_len);
        // Bake any non-zero addend into the 8-byte slot now (while we still own
        // the section bytes), then record the slot for an `ARM64_RELOC_UNSIGNED`.
        // Eight zero bytes were reserved for each pointer slot by
        // `trust_ir_global_initializer_data`, so the write stays in bounds.
        for sref in &global.symbol_refs {
            let slot = (global_offset + sref.offset) as usize;
            if sref.addend != 0 {
                let bytes = sref.addend.to_le_bytes();
                data[slot..slot + bytes.len()].copy_from_slice(&bytes);
            }
            reloc_slots.push((slot as u32, sref.symbol.clone()));
        }
    }

    let section_index = writer.add_custom_section(
        b"__data",
        b"__DATA",
        &data,
        max_align.trailing_zeros(),
        crate::macho::constants::S_REGULAR,
    );
    let section_ordinal = section_index + 1;

    let pending = reloc_slots
        .into_iter()
        .map(|(offset, symbol)| PendingDataReloc {
            section_index,
            offset,
            symbol,
        })
        .collect();

    let symbols = globals
        .iter()
        .zip(offsets)
        .map(|(global, offset)| {
            let name = macho_symbol_name(&global.name);
            // A weak DEFINITION coalesces across objects (`N_WEAK_DEF`).
            // Externally-visible globals must be GLOBAL symbols (see the
            // immutable-section emitter above).
            let symbol_id = if global.is_weak {
                writer.add_weak_symbol(&name, section_ordinal, offset, global.is_external)
            } else {
                writer.add_symbol(&name, section_ordinal, offset, global.is_external)
            }?;
            Ok((global.name.clone(), symbol_id))
        })
        .collect::<Result<Vec<_>, crate::macho::MachOWriteError>>()?;
    Ok((symbols, pending))
}

/// A descriptor-slot relocation deferred until all symbols are added, so the
/// `relocation_info.r_symbolnum` can use the FINAL nlist index.
///
/// `pub(crate)` so the x86-64 Mach-O emitter (`x86_64::pipeline::emit_module_macho`)
/// can consume the same deferred relocations and emit them as
/// `X86_64_RELOC_UNSIGNED` (the AArch64 caller emits `ARM64_RELOC_UNSIGNED`);
/// the descriptor section/symbol layout is arch-neutral and shared.
pub(crate) struct PendingTlsReloc {
    /// 0-based index of the `__thread_vars` section the descriptor lives in.
    pub(crate) section_index: usize,
    /// Byte offset of the relocated 8-byte slot within `__thread_vars`.
    pub(crate) offset: u32,
    /// Insertion-time symbol id of the referenced symbol.
    pub(crate) symbol_id: crate::macho::SymbolId,
}

const AARCH64_DARWIN_TLV_POINTER_SIZE: usize = 8;
const AARCH64_DARWIN_TLV_DESCRIPTOR_SIZE: usize = 3 * AARCH64_DARWIN_TLV_POINTER_SIZE;
const AARCH64_DARWIN_TLV_INIT_POINTER_OFFSET: usize = 2 * AARCH64_DARWIN_TLV_POINTER_SIZE;

/// Validate every count-derived Darwin TLV size and the largest descriptor
/// relocation before allocating section storage. Mach-O's non-scattered
/// `r_address` is signed, so bit 31 must stay clear even though our in-memory
/// relocation offset is a `u32`.
fn checked_aarch64_tls_layout(global_count: usize) -> Result<(usize, usize), PipelineError> {
    let descriptor_byte_len = checked_aarch64_capacity(
        "<module>",
        "Darwin TLV descriptor table byte length",
        global_count,
        AARCH64_DARWIN_TLV_DESCRIPTOR_SIZE,
    )?;
    let pending_relocation_capacity = checked_aarch64_capacity(
        "<module>",
        "Darwin TLV pending relocation count",
        global_count,
        2,
    )?;

    if global_count != 0 {
        let last_descriptor_offset = checked_aarch64_capacity(
            "<module>",
            "Darwin TLV last descriptor offset",
            global_count - 1,
            AARCH64_DARWIN_TLV_DESCRIPTOR_SIZE,
        )?;
        let max_relocation_offset = checked_aarch64_size_sum(
            "<module>",
            "Darwin TLV maximum relocation offset",
            last_descriptor_offset,
            AARCH64_DARWIN_TLV_INIT_POINTER_OFFSET,
        )?;
        let max_relocation_offset = checked_aarch64_object_u32(
            "<module>",
            "Darwin TLV maximum relocation offset",
            max_relocation_offset,
        )?;
        checked_aarch64_macho_relocation_offset(
            "<module>",
            "Darwin TLV maximum relocation offset",
            max_relocation_offset,
        )?;
    }

    Ok((descriptor_byte_len, pending_relocation_capacity))
}

/// Emit the Darwin TLV sections for the thread-local globals and register their
/// symbols.
///
/// For each thread-local global `X` with initial value bytes `init`, this lays
/// out (mirroring clang `-O1` / `<mach-o/loader.h>` TLV conventions):
///
/// - `__DATA,__thread_data` (`S_THREAD_LOCAL_REGULAR`): the per-thread initial
///   value template `X$tlv$init`. A local symbol points at it.
/// - `__DATA,__thread_vars` (`S_THREAD_LOCAL_VARIABLES`): the 3-word
///   `tlv_descriptor` `{ thunk = __tlv_bootstrap, key = 0, offset = X$tlv$init }`.
///   The symbol `X` (the one a `#[thread_local]` read addresses through the TLVP
///   relocations) points at the descriptor. Two `ARM64_RELOC_UNSIGNED` (8-byte)
///   relocations fill word 0 (`__tlv_bootstrap`, an undefined dyld import) and
///   word 2 (`X$tlv$init`).
///
/// Returns `(name -> descriptor SymbolId)` for the `X` symbols (so TLVP fixups in
/// `__text` resolve to them) and the list of deferred descriptor relocations,
/// emitted by the caller once every symbol's final nlist index is known.
///
/// `pub(crate)` and arch-neutral: the descriptor byte layout (3 pointer-width
/// words `{ __tlv_bootstrap, 0, X$tlv$init }`), the `__DATA,__thread_data` /
/// `__DATA,__thread_vars` sections and their `S_THREAD_LOCAL_*` flags, and the
/// `_X` / `_X$tlv$init` symbol names are identical on AArch64 and x86-64 Darwin.
/// Only the two internal descriptor pointer relocations differ by arch
/// (`ARM64_RELOC_UNSIGNED` vs `X86_64_RELOC_UNSIGNED`), so this returns them as
/// arch-agnostic `PendingTlsReloc`s for the caller to emit.
pub(crate) fn add_tls_global_sections(
    writer: &mut crate::macho::MachOWriter,
    tls_globals: &[&ObjectGlobal],
) -> Result<(Vec<(String, crate::macho::SymbolId)>, Vec<PendingTlsReloc>), PipelineError> {
    use crate::macho::constants::{S_THREAD_LOCAL_REGULAR, S_THREAD_LOCAL_VARIABLES};

    if tls_globals.is_empty() {
        return Ok((Vec::new(), Vec::new()));
    }

    let (descriptor_byte_len, pending_relocation_capacity) =
        checked_aarch64_tls_layout(tls_globals.len())?;

    // --- __thread_data: the initial-value templates. ---
    let mut data_bytes: Vec<u8> = Vec::new();
    let mut init_offsets: Vec<u64> = Vec::new();
    init_offsets
        .try_reserve_exact(tls_globals.len())
        .map_err(|error| {
            PipelineError::Encoding(format!(
                "AArch64 Darwin TLV initializer offset-table allocation failed: {error}"
            ))
        })?;
    for global in tls_globals {
        // Natural-align each template to the next power of two of its size,
        // capped at the pointer width, so an aligned load of the variable through
        // the resolved address is well-formed. (1 -> 1, 2 -> 2, 3/4 -> 4, 5..8 -> 8.)
        let size = global.data.len().max(1);
        let align = if size >= AARCH64_DARWIN_TLV_POINTER_SIZE {
            AARCH64_DARWIN_TLV_POINTER_SIZE
        } else {
            size.next_power_of_two()
        };
        let padding = (align - (data_bytes.len() % align)) % align;
        let padded_len = checked_aarch64_size_sum(
            &global.name,
            "Darwin TLV initializer alignment",
            data_bytes.len(),
            padding,
        )?;
        let final_len = checked_aarch64_size_sum(
            &global.name,
            "Darwin TLV initializer section byte length",
            padded_len,
            global.data.len(),
        )?;
        data_bytes
            .try_reserve(padding + global.data.len())
            .map_err(|error| {
                PipelineError::Encoding(format!(
                    "AArch64 Darwin TLV initializer allocation for `{}` failed: {error}",
                    global.name
                ))
            })?;
        data_bytes.resize(padded_len, 0);
        init_offsets.push(checked_aarch64_object_u64(
            &global.name,
            "Darwin TLV initializer offset",
            data_bytes.len(),
        )?);
        data_bytes.extend_from_slice(&global.data);
        debug_assert_eq!(data_bytes.len(), final_len);
    }
    let thread_data_index = writer.add_custom_section(
        b"__thread_data",
        b"__DATA",
        &data_bytes,
        3, // 2^3 = 8-byte section alignment (covers any <= ptr-width template)
        S_THREAD_LOCAL_REGULAR,
    );
    let thread_data_ordinal = thread_data_index + 1;

    // Local `X$tlv$init` symbols pointing into __thread_data.
    let init_symbol_ids: Vec<crate::macho::SymbolId> = tls_globals
        .iter()
        .zip(&init_offsets)
        .map(|(global, &offset)| {
            let name = format!("_{}$tlv$init", global.name);
            // The init template is a private local symbol (clang emits it local).
            writer.add_symbol(&name, thread_data_ordinal, offset, false)
        })
        .collect::<Result<Vec<_>, crate::macho::MachOWriteError>>()?;

    // --- __thread_vars: the tlv_descriptor slots, pointer-aligned. ---
    // All descriptor words are placeholder zeros; the linker fills the thunk and
    // init-template pointers via the UNSIGNED relocations recorded below.
    let mut descriptors = Vec::new();
    descriptors
        .try_reserve_exact(descriptor_byte_len)
        .map_err(|error| {
            PipelineError::Encoding(format!(
                "AArch64 Darwin TLV descriptor-table allocation failed: {error}"
            ))
        })?;
    descriptors.resize(descriptor_byte_len, 0);
    let thread_vars_index = writer.add_custom_section(
        b"__thread_vars",
        b"__DATA",
        &descriptors,
        3, // 2^3 = 8-byte (clang uses 2^0, but 8 is safe and natural for ptrs)
        S_THREAD_LOCAL_VARIABLES,
    );
    let thread_vars_ordinal = thread_vars_index + 1;

    // The shared dyld bootstrap thunk — an undefined external import.
    let tlv_bootstrap_id = writer.add_symbol("__tlv_bootstrap", 0, 0, true)?;

    let mut descriptor_symbols: Vec<(String, crate::macho::SymbolId)> = Vec::new();
    descriptor_symbols
        .try_reserve_exact(tls_globals.len())
        .map_err(|error| {
            PipelineError::Encoding(format!(
                "AArch64 Darwin TLV descriptor-symbol allocation failed: {error}"
            ))
        })?;
    let mut pending = Vec::new();
    pending
        .try_reserve_exact(pending_relocation_capacity)
        .map_err(|error| {
            PipelineError::Encoding(format!(
                "AArch64 Darwin TLV relocation-table allocation failed: {error}"
            ))
        })?;
    for (i, global) in tls_globals.iter().enumerate() {
        let desc_offset = checked_aarch64_capacity(
            &global.name,
            "Darwin TLV descriptor offset",
            i,
            AARCH64_DARWIN_TLV_DESCRIPTOR_SIZE,
        )?;
        let desc_symbol_offset = checked_aarch64_object_u64(
            &global.name,
            "Darwin TLV descriptor symbol offset",
            desc_offset,
        )?;
        let thunk_relocation_offset = checked_aarch64_macho_relocation_offset(
            &global.name,
            "Darwin TLV bootstrap relocation offset",
            checked_aarch64_object_u32(
                &global.name,
                "Darwin TLV bootstrap relocation offset",
                desc_offset,
            )?,
        )?;
        let init_relocation_offset = checked_aarch64_size_sum(
            &global.name,
            "Darwin TLV initializer relocation offset",
            desc_offset,
            AARCH64_DARWIN_TLV_INIT_POINTER_OFFSET,
        )?;
        let init_relocation_offset = checked_aarch64_macho_relocation_offset(
            &global.name,
            "Darwin TLV initializer relocation offset",
            checked_aarch64_object_u32(
                &global.name,
                "Darwin TLV initializer relocation offset",
                init_relocation_offset,
            )?,
        )?;
        // The variable symbol `X` names the descriptor slot. A weak thread-local
        // definition coalesces its descriptor across objects (`N_WEAK_DEF`).
        let desc_name = macho_symbol_name(&global.name);
        let desc_symbol_id = if global.is_weak {
            writer.add_weak_symbol(
                &desc_name,
                thread_vars_ordinal,
                desc_symbol_offset,
                global.is_external,
            )
        } else {
            writer.add_symbol(
                &desc_name,
                thread_vars_ordinal,
                desc_symbol_offset,
                global.is_external,
            )
        }?;
        descriptor_symbols.push((global.name.clone(), desc_symbol_id));

        // Word 0 (offset desc_offset): thunk = __tlv_bootstrap.
        pending.push(PendingTlsReloc {
            section_index: thread_vars_index,
            offset: thunk_relocation_offset,
            symbol_id: tlv_bootstrap_id,
        });
        // Word 2 (offset desc_offset + 16): offset = X$tlv$init.
        pending.push(PendingTlsReloc {
            section_index: thread_vars_index,
            offset: init_relocation_offset,
            symbol_id: init_symbol_ids[i],
        });
    }

    Ok((descriptor_symbols, pending))
}

/// Reject a Mach-O TLS definition whose initializer embeds symbol addresses.
///
/// The Darwin TLV emitter copies the initial-value template bytes and emits the
/// two descriptor-pointer relocations, but it has no relocation path for a
/// symbol-address slot inside the per-thread template itself. Accepting such a
/// global would silently leave a null/constant placeholder in every thread.
fn reject_macho_tls_globals_with_symbol_refs(
    globals: &[ObjectGlobal],
) -> Result<(), PipelineError> {
    if let Some(global) = globals
        .iter()
        .find(|global| global.is_thread_local && !global.symbol_refs.is_empty())
    {
        return Err(PipelineError::TargetObjectUnsupported {
            target: "aarch64-apple-darwin".to_string(),
            format: "Mach-O".to_string(),
            reason: format!(
                "thread-local global '{}' carries symbol-address relocation elements; the Darwin TLV initial-value-template relocation path is not implemented (fail-closed)",
                global.name
            ),
        });
    }
    Ok(())
}

/// How a whole-module emission should bind one function's DEFINING symbol.
///
/// This is the function-side analogue of [`ObjectGlobal::is_external`], and it
/// mirrors trust-ir linkage exactly as that field does: `External`/`Weak`/
/// `LinkOnce` → [`Global`](Self::Global), `Internal`/`Private` →
/// [`Local`](Self::Local).
///
/// It matters because a codegen unit's internal helpers are content-hashed:
/// emitting them `STB_GLOBAL` / `N_EXT` makes any two objects that share a hash
/// collide with "duplicate symbol" at static link. A `Local` definition is
/// invisible outside its own object while still resolving intra-object calls.
///
/// A binding is a SYMBOL-TABLE attribute only. It must never change one byte of
/// `__text`, nor any function's offset within it — the emitted code for a
/// function is identical whether it is bound `Global` or `Local`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum FunctionSymbolBinding {
    /// Visible to the linker outside this object (Mach-O `N_EXT`, ELF
    /// `STB_GLOBAL`). The default, and what an empty binding vector means.
    #[default]
    Global,
    /// Defined but not exported (Mach-O: no `N_EXT`, ELF `STB_LOCAL`).
    Local,
}

/// The binding for `index`, defaulting to [`FunctionSymbolBinding::Global`].
///
/// An EMPTY `bindings` slice means "every definition is global", which is what
/// keeps every pre-existing caller byte-identical.
///
/// A NON-empty slice must be 1:1 with the module's functions. A length mismatch
/// is a caller bug that silently mis-binds symbols — every binding past the
/// short point slides onto the wrong definition — so it FAILS CLOSED instead of
/// defaulting. Defaulting is the dangerous choice precisely because it is
/// invisible: the object still emits, and the damage surfaces at static link as
/// a duplicate or missing symbol far from the mis-sized vector that caused it.
fn function_symbol_binding_at(
    bindings: &[FunctionSymbolBinding],
    index: usize,
    function_count: usize,
    function_name: &str,
) -> Result<FunctionSymbolBinding, PipelineError> {
    if bindings.is_empty() {
        return Ok(FunctionSymbolBinding::Global);
    }
    if bindings.len() != function_count {
        return Err(PipelineError::Encoding(format!(
            "function symbol-binding vector has {} entries for a {function_count}-function \
             module (fail-closed: a mis-indexed binding would mark the wrong definition local)",
            bindings.len()
        )));
    }
    bindings.get(index).copied().ok_or_else(|| {
        PipelineError::Encoding(format!(
            "no symbol binding recorded for function `{function_name}` at index {index}"
        ))
    })
}

/// Where one function's machine code landed inside the emitted text section.
///
/// `offset` and `len` are both relative to, and measured in, the combined text
/// section: `offset` is the function's first byte AFTER any inter-function
/// alignment padding, and `len` is its ENCODED body length, excluding trailing
/// padding. That is deliberately not the ELF `st_size` a linker would compute
/// from consecutive symbol offsets (which includes padding) — a consumer
/// cross-checks `len` against the bytes of that function emitted ALONE, and a
/// single-function object's whole text section is exactly its encoded body.
///
/// `name` is the IR-level function name, NOT the object-file symbol: Mach-O
/// prefixes every symbol with `_`, and consumers look extents up by the
/// unprefixed name.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct TextFunctionExtent {
    /// IR-level function name, without any object-format symbol prefix.
    pub name: String,
    /// First byte of the function within the combined text section.
    pub offset: u64,
    /// Encoded body length in bytes, excluding inter-function padding.
    pub len: u64,
}

/// A whole-module object plus the text layout the emitter actually produced.
///
/// The layout is reported rather than re-derived because a consumer that wants
/// to prove the shipped bytes are the bytes it verified must compare against
/// what the emitter DID, not against an independent guess at what it should
/// have done.
#[derive(Debug, Clone)]
pub struct ModuleEmission {
    /// The complete object file.
    pub object: Vec<u8>,
    /// One entry per emitted function, in emission order.
    pub text_extents: Vec<TextFunctionExtent>,
}

fn add_module_symbols_for_fixups(
    writer: &mut crate::macho::MachOWriter,
    func_offsets: &[(String, u64)],
    globals: &[ObjectGlobal],
    fixups: &crate::macho::fixup::FixupList,
    // 1:1 with `func_offsets` when non-empty; empty means "all global".
    bindings: &[FunctionSymbolBinding],
) -> Result<HashMap<String, u32>, PipelineError> {
    use crate::macho::FixupTarget;

    reject_macho_tls_globals_with_symbol_refs(globals)?;

    let mut symbol_ids = Vec::new();
    let mut known_names = BTreeSet::new();

    // Thread-local globals route to the Darwin TLV sections, not __data/__const.
    // An IMPORT (a cross-object reference to a descriptor defined elsewhere) is
    // EXCLUDED here: it defines no descriptor / template, so its `__text` TLVP
    // fixup falls through to the undefined-external path below and the linker
    // resolves it to the single canonical descriptor in the defining object.
    let tls_globals: Vec<&ObjectGlobal> = globals
        .iter()
        .filter(|global| global.is_thread_local && !global.is_import)
        .collect();
    // A non-TLS DATA IMPORT (initializer-less external global — see compiler.rs
    // `is_import`) defines no bytes here; it is a reference to a `static` DEFINED
    // in another object. It must be EXCLUDED from the __data/__const definition
    // lists (exactly like the TLS-import exclusion above) — otherwise it is
    // emitted as a 0-byte symbol DEFINITION and collides with the real
    // definition at link time (`duplicate symbol`). Its GOT reference
    // (`ExternRef` -> @GOTPAGE) falls through to the undefined-external path and
    // the linker resolves it to the defining object.
    // A global carrying symbol-address relocations (a vtable, a `static FNS:
    // [fn(); N]`) MUST live in the writable `__DATA,__data` section: an
    // `ARM64_RELOC_UNSIGNED` cannot be applied to `__TEXT,__const` (the text
    // segment is read-only / code-signed and dyld does not rebase it). This
    // mirrors the x86-64 emitter's `needs_data_section` and clang. Plain
    // relocation-free globals keep their mutable(`__data`)/immutable(`__const`)
    // placement.
    let needs_data_section =
        |global: &&ObjectGlobal| global.mutable || !global.symbol_refs.is_empty();
    let mutable_globals: Vec<&ObjectGlobal> = globals
        .iter()
        .filter(|global| !global.is_thread_local && !global.is_import && needs_data_section(global))
        .collect();
    let immutable_globals: Vec<&ObjectGlobal> = globals
        .iter()
        .filter(|global| {
            !global.is_thread_local && !global.is_import && !needs_data_section(global)
        })
        .collect();
    let (data_symbols, pending_data_relocs) = add_global_data_section(writer, &mutable_globals)?;
    for (name, symbol_id) in data_symbols
        .into_iter()
        .chain(add_global_const_section(writer, &immutable_globals)?)
    {
        let symbol_name = macho_symbol_name(&name);
        symbol_ids.push((name.clone(), symbol_id));
        symbol_ids.push((symbol_name.clone(), symbol_id));
        known_names.insert(name);
        known_names.insert(symbol_name);
    }

    // TLV descriptor sections + their descriptor symbols (so __text TLVP fixups
    // resolve to `_X`). The descriptor relocations are emitted after all symbols
    // exist, so their `r_symbolnum` can use the final nlist order.
    let (tls_descriptor_symbols, pending_tls_relocs) =
        add_tls_global_sections(writer, &tls_globals)?;
    for (name, symbol_id) in tls_descriptor_symbols {
        let symbol_name = macho_symbol_name(&name);
        symbol_ids.push((name.clone(), symbol_id));
        symbol_ids.push((symbol_name.clone(), symbol_id));
        known_names.insert(name);
        known_names.insert(symbol_name);
    }

    for (index, (name, offset)) in func_offsets.iter().enumerate() {
        let symbol_name = macho_symbol_name(name);
        // The ONLY place a function's binding is honoured on the Mach-O path.
        // `is_global == false` clears `N_EXT`, which is what makes an
        // Internal-linkage definition invisible outside this object while its
        // intra-object callers still resolve. The Mach-O writer recomputes the
        // locals-first nlist partition itself, so flipping this needs no index
        // bookkeeping here (unlike ELF).
        let is_global = function_symbol_binding_at(bindings, index, func_offsets.len(), name)?
            == FunctionSymbolBinding::Global;
        let symbol_id = writer.add_symbol(&symbol_name, 1, *offset, is_global)?;
        symbol_ids.push((name.clone(), symbol_id));
        symbol_ids.push((symbol_name.clone(), symbol_id));
        known_names.insert(name.clone());
        known_names.insert(symbol_name);
    }

    let mut undefined_names = BTreeSet::new();
    for fixup in fixups.iter() {
        if let FixupTarget::NamedSymbol(name) = &fixup.target {
            let symbol_name = macho_symbol_name(name);
            if !known_names.contains(name) && !known_names.contains(&symbol_name) {
                undefined_names.insert(name.clone());
            }
        }
    }
    // A data-section symbol-address slot (vtable / `static FNS` element) may
    // target a symbol that no `__text` fixup references — e.g. an external
    // function whose address is only ever taken in data. Register it as an
    // undefined external too, so the relocation below resolves rather than
    // failing closed.
    for reloc in &pending_data_relocs {
        let symbol_name = macho_symbol_name(&reloc.symbol);
        if !known_names.contains(&reloc.symbol) && !known_names.contains(&symbol_name) {
            undefined_names.insert(reloc.symbol.clone());
        }
    }

    for name in undefined_names {
        let symbol_name = macho_symbol_name(&name);
        let symbol_id = writer.add_symbol(&symbol_name, 0, 0, true)?;
        symbol_ids.push((name.clone(), symbol_id));
        known_names.insert(name);
        symbol_ids.push((symbol_name.clone(), symbol_id));
        known_names.insert(symbol_name);
    }

    // Now that every symbol exists, emit the deferred `__thread_vars` descriptor
    // relocations (thunk + init-template pointers) using final nlist indices.
    for reloc in pending_tls_relocs {
        let final_index = writer.final_symbol_index(reloc.symbol_id)?.ok_or_else(|| {
            PipelineError::Encoding(
                "TLV descriptor relocation symbol missing before emission".to_string(),
            )
        })?;
        writer.add_relocation(
            reloc.section_index,
            crate::macho::reloc::Relocation::unsigned_ptr(reloc.offset, final_index),
        )?;
    }

    // Emit the deferred `__DATA,__data` symbol-address relocations
    // (`ARM64_RELOC_UNSIGNED`, 8-byte absolute pointers) using final nlist
    // indices — the same "all symbols first, then relocations" ordering the TLS
    // descriptors above use. The target was registered as an in-module
    // definition (function or data global) or as an undefined external above, so
    // its insertion-time id is present in `symbol_ids`.
    if !pending_data_relocs.is_empty() {
        let name_to_symbol_id: HashMap<&str, crate::macho::SymbolId> = symbol_ids
            .iter()
            .map(|(name, id)| (name.as_str(), *id))
            .collect();
        for reloc in &pending_data_relocs {
            let symbol_id = name_to_symbol_id
                .get(reloc.symbol.as_str())
                .or_else(|| name_to_symbol_id.get(macho_symbol_name(&reloc.symbol).as_str()))
                .copied()
                .expect("data-relocation target symbol should exist after registration");
            let final_index = writer
                .final_symbol_index(symbol_id)
                .expect("data-relocation target symbol nlist lookup should succeed")
                .expect("data-relocation target symbol should have a final nlist index");
            writer.add_relocation(
                reloc.section_index,
                crate::macho::reloc::Relocation::unsigned_ptr(reloc.offset, final_index),
            )?;
        }
    }

    symbol_ids
        .into_iter()
        .map(|(name, symbol_id)| {
            let final_index = writer.final_symbol_index(symbol_id)?.ok_or_else(|| {
                PipelineError::Encoding("symbol missing before Mach-O fixup resolution".to_string())
            })?;
            Ok((name, final_index))
        })
        .collect()
}

/// True when the configured target triple targets a Linux-flavored ELF host.
///
/// trust-cg-codegen historically emitted Mach-O regardless of triple, which made
/// every cross-platform build implicitly host-only. Linux triples now route
/// through the ELF writer so `tcargo trust` artifacts for Linux are real ELF
/// `.o` files (verifiable with `file`/`readelf`).
pub(crate) fn target_triple_uses_elf(triple: &str) -> bool {
    triple.contains("-linux-")
        || triple.ends_with("-linux")
        || triple.contains("-freebsd")
        || triple.contains("-netbsd")
        || triple.contains("-openbsd")
        || triple.contains("-illumos")
        || triple.contains("-solaris")
}

fn target_triple_arch(triple: &str) -> &str {
    triple.split('-').next().unwrap_or("")
}

fn target_triple_is_aarch64(triple: &str) -> bool {
    matches!(target_triple_arch(triple), "aarch64" | "arm64")
}

fn target_triple_uses_macho(triple: &str) -> bool {
    triple.contains("-apple-") || triple.ends_with("-darwin")
}

fn reject_unsupported_aarch64_object_format(target_triple: &str) -> Result<(), PipelineError> {
    // Preserve the historical empty-triple default (AArch64 Mach-O). Every
    // explicit triple is an authority claim: this pipeline emits little-endian
    // AArch64 instructions, so it must never label those bytes as x86, RISC-V,
    // or big-endian AArch64.
    if target_triple.is_empty() {
        return Ok(());
    }

    if !target_triple_is_aarch64(target_triple) {
        return Err(PipelineError::TargetObjectUnsupported {
            target: target_triple.to_string(),
            format: "native object format".to_string(),
            reason: "the AArch64 pipeline emits only little-endian AArch64 machine code; non-AArch64 and aarch64_be triples require their architecture-specific pipeline (fail-closed)".to_string(),
        });
    }

    if target_triple_uses_elf(target_triple) || target_triple_uses_macho(target_triple) {
        return Ok(());
    }

    Err(PipelineError::TargetObjectUnsupported {
        target: target_triple.to_string(),
        format: "native object format".to_string(),
        reason: "AArch64 object emission is supported only for explicit ELF or Apple Mach-O target triples; unknown or unsupported AArch64 triples must fail closed before Mach-O emission".to_string(),
    })
}

/// Emit a minimal ELF `.o` containing a single `.text` section with all functions
/// concatenated, and one `STT_FUNC` symbol per function pointing at its offset.
fn emit_elf_with_function_symbols(
    machine: crate::elf::ElfMachine,
    combined_code: &[u8],
    func_offsets: &[(String, u64)],
    globals: &[ObjectGlobal],
    text_align_log2: u8,
) -> Vec<u8> {
    use crate::elf::ElfWriter;

    let mut writer = ElfWriter::new(machine);
    writer.add_text_section_with_align(
        combined_code,
        elf_text_align_bytes(machine, text_align_log2),
    );
    add_elf_global_object_symbols(&mut writer, globals);

    let total = combined_code.len() as u64;
    for (index, (name, offset)) in func_offsets.iter().enumerate() {
        // Size of this function = next offset (or end of code) minus this offset.
        let next = func_offsets
            .get(index + 1)
            .map(|(_, o)| *o)
            .unwrap_or(total);
        let size = next.saturating_sub(*offset);
        // section=1 (.text), STT_FUNC=2, global=true so the linker can see the symbol.
        writer.add_symbol(name, 1, *offset, size, true, 2);
    }
    writer.write()
}

fn aarch64_elf_branch_reloc_kind(
    target_triple: &str,
    combined_code: &[u8],
    offset: u32,
) -> Result<crate::elf::AArch64RelocType, PipelineError> {
    let offset = offset as usize;
    let Some(bytes) = combined_code.get(offset..offset + 4) else {
        return Err(PipelineError::TargetObjectUnsupported {
            target: target_triple.to_string(),
            format: "ELF".to_string(),
            reason: format!("AArch64 branch fixup offset {offset:#x} is outside .text"),
        });
    };
    let word = u32::from_le_bytes([bytes[0], bytes[1], bytes[2], bytes[3]]);
    match word & 0xfc00_0000 {
        0x9400_0000 => Ok(crate::elf::AArch64RelocType::Call26),
        0x1400_0000 => Ok(crate::elf::AArch64RelocType::Jump26),
        _ => Err(PipelineError::TargetObjectUnsupported {
            target: target_triple.to_string(),
            format: "ELF".to_string(),
            reason: format!(
                "AArch64 Branch26 fixup at {offset:#x} does not point at a B/BL placeholder"
            ),
        }),
    }
}

fn aarch64_elf_reloc_kind(
    target_triple: &str,
    combined_code: &[u8],
    fixup: &crate::macho::fixup::Fixup,
) -> Result<crate::elf::AArch64RelocType, PipelineError> {
    use crate::macho::AArch64RelocKind;

    // The ELF local-exec (TLSLE) and initial-exec (TLSIE) TLS fixups are the
    // ONLY TLS-provenance fixups this emitter accepts, and each is only valid
    // with exactly its own model (the ISel sequence it was emitted from:
    // `MRS; ADD hi12; ADD lo12_nc` for LocalExec, `ADRP :gottprel:;
    // LDR #:gottprel_lo12:; MRS; ADD` for InitialExec). Everything else with
    // a TLS model — in particular the Darwin TLV descriptor fixups — stays
    // fail-closed: Darwin TLV descriptors cannot be mapped to ELF TLS
    // relocations, and TLS-provenance fixups must never be emitted as
    // non-TLS relocations.
    match (fixup.kind, fixup.tls_model) {
        (AArch64RelocKind::ElfTlsleAddTprelHi12, Some(trust_cg_ir::TlsModel::LocalExec)) => {
            return Ok(crate::elf::AArch64RelocType::TlsleAddTprelHi12);
        }
        (AArch64RelocKind::ElfTlsleAddTprelLo12Nc, Some(trust_cg_ir::TlsModel::LocalExec)) => {
            return Ok(crate::elf::AArch64RelocType::TlsleAddTprelLo12Nc);
        }
        (AArch64RelocKind::ElfTlsieAdrGottprelPage21, Some(trust_cg_ir::TlsModel::InitialExec)) => {
            return Ok(crate::elf::AArch64RelocType::TlsieAdrGottprelPage21);
        }
        (
            AArch64RelocKind::ElfTlsieLd64GottprelLo12Nc,
            Some(trust_cg_ir::TlsModel::InitialExec),
        ) => return Ok(crate::elf::AArch64RelocType::TlsieLd64GottprelLo12Nc),
        (
            AArch64RelocKind::ElfTlsleAddTprelHi12 | AArch64RelocKind::ElfTlsleAddTprelLo12Nc,
            model,
        ) => {
            return Err(PipelineError::TargetObjectUnsupported {
                target: target_triple.to_string(),
                format: "ELF".to_string(),
                reason: format!(
                    "AArch64 ELF TLS local-exec fixup {:?} carries model {model:?}; it must carry Some(LocalExec) (fail-closed: TLS relocation model and fixup kind must agree)",
                    fixup.kind
                ),
            });
        }
        (
            AArch64RelocKind::ElfTlsieAdrGottprelPage21
            | AArch64RelocKind::ElfTlsieLd64GottprelLo12Nc,
            model,
        ) => {
            return Err(PipelineError::TargetObjectUnsupported {
                target: target_triple.to_string(),
                format: "ELF".to_string(),
                reason: format!(
                    "AArch64 ELF TLS initial-exec fixup {:?} carries model {model:?}; it must carry Some(InitialExec) (fail-closed: TLS relocation model and fixup kind must agree)",
                    fixup.kind
                ),
            });
        }
        (kind, Some(tls_model)) => {
            return Err(PipelineError::TargetObjectUnsupported {
                target: target_triple.to_string(),
                format: "ELF".to_string(),
                reason: format!(
                    "AArch64 ELF relocation emission does not yet support TLS/TLVP fixup {kind:?} with model Some({tls_model:?}); Darwin TLV descriptors cannot be mapped to ELF TLS relocations, and TLS-provenance fixups require a dedicated ELF TLS relocation model and must not be emitted as non-TLS relocations"
                ),
            });
        }
        (_, None) => {}
    }

    match fixup.kind {
        AArch64RelocKind::Unsigned => Ok(crate::elf::AArch64RelocType::Abs64),
        AArch64RelocKind::Branch26 => {
            aarch64_elf_branch_reloc_kind(target_triple, combined_code, fixup.offset)
        }
        AArch64RelocKind::Page21 => Ok(crate::elf::AArch64RelocType::AdrPrelPgHi21),
        AArch64RelocKind::Pageoff12 => Ok(crate::elf::AArch64RelocType::AddAbsLo12Nc),
        AArch64RelocKind::GotLoadPage21 => Ok(crate::elf::AArch64RelocType::AdrGotPage),
        AArch64RelocKind::GotLoadPageoff12 => Ok(crate::elf::AArch64RelocType::Ld64GotLo12Nc),
        AArch64RelocKind::TlvpLoadPage21 | AArch64RelocKind::TlvpLoadPageoff12 => {
            Err(PipelineError::TargetObjectUnsupported {
                target: target_triple.to_string(),
                format: "ELF".to_string(),
                reason: format!(
                    "AArch64 ELF relocation emission does not yet support TLS/TLVP fixup {:?} with model {:?}; Darwin TLV descriptors cannot be mapped to ELF TLS relocations",
                    fixup.kind, fixup.tls_model
                ),
            })
        }
        other => Err(PipelineError::TargetObjectUnsupported {
            target: target_triple.to_string(),
            format: "ELF".to_string(),
            reason: format!("AArch64 ELF relocation emission does not yet support fixup {other:?}"),
        }),
    }
}

#[cfg(feature = "verify")]
fn aarch64_elf_object_relocation_kind(
    reloc: crate::elf::AArch64RelocType,
) -> trust_cg_verify::ObjectRelocationKind {
    match reloc {
        crate::elf::AArch64RelocType::Abs64 => {
            trust_cg_verify::ObjectRelocationKind::AArch64ElfAbs64
        }
        crate::elf::AArch64RelocType::Call26 => {
            trust_cg_verify::ObjectRelocationKind::AArch64ElfCall26
        }
        crate::elf::AArch64RelocType::Jump26 => {
            trust_cg_verify::ObjectRelocationKind::AArch64ElfJump26
        }
        crate::elf::AArch64RelocType::AdrPrelPgHi21 => {
            trust_cg_verify::ObjectRelocationKind::AArch64ElfAdrPrelPgHi21
        }
        crate::elf::AArch64RelocType::AddAbsLo12Nc => {
            trust_cg_verify::ObjectRelocationKind::AArch64ElfAddAbsLo12Nc
        }
        crate::elf::AArch64RelocType::AdrGotPage => {
            trust_cg_verify::ObjectRelocationKind::AArch64ElfAdrGotPage
        }
        crate::elf::AArch64RelocType::Ld64GotLo12Nc => {
            trust_cg_verify::ObjectRelocationKind::AArch64ElfLd64GotLo12Nc
        }
        crate::elf::AArch64RelocType::TlsieAdrGottprelPage21 => {
            trust_cg_verify::ObjectRelocationKind::AArch64ElfTlsieAdrGottprelPage21
        }
        crate::elf::AArch64RelocType::TlsieLd64GottprelLo12Nc => {
            trust_cg_verify::ObjectRelocationKind::AArch64ElfTlsieLd64GottprelLo12Nc
        }
        crate::elf::AArch64RelocType::TlsleAddTprelHi12 => {
            trust_cg_verify::ObjectRelocationKind::AArch64ElfTlsleAddTprelHi12
        }
        crate::elf::AArch64RelocType::TlsleAddTprelLo12 => {
            trust_cg_verify::ObjectRelocationKind::AArch64ElfTlsleAddTprelLo12
        }
        crate::elf::AArch64RelocType::TlsleAddTprelLo12Nc => {
            trust_cg_verify::ObjectRelocationKind::AArch64ElfTlsleAddTprelLo12Nc
        }
        other => trust_cg_verify::ObjectRelocationKind::AArch64ElfOther(other as u32),
    }
}

#[cfg(feature = "verify")]
fn aarch64_elf_relocation_inventory_report(
    object_name: impl Into<String>,
    target_triple: &str,
    combined_code: &[u8],
    fixups: &crate::macho::fixup::FixupList,
    additional_rows: impl IntoIterator<Item = trust_cg_verify::ObjectRelocationKind>,
) -> Result<trust_cg_verify::ObjectRelocationInventoryReport, PipelineError> {
    let mut emitted = Vec::new();
    for fixup in fixups.iter() {
        let reloc = aarch64_elf_reloc_kind(target_triple, combined_code, fixup)?;
        emitted.push(aarch64_elf_object_relocation_kind(reloc));
    }
    emitted.extend(additional_rows);
    // Every AArch64 ELF row stays fail-closed for production Certified output.
    // TLSLE/TLSIE have strict solver-backed formal obligations and negative
    // controls (`trust_cg_verify::aarch64_elf_tls_reloc_proofs`), but the
    // inventory surface cannot yet distinguish Trusted solver evidence from
    // Certified/kernel authority or bind a solver report to this object.
    // Ordinary rows lack even those target-specific obligations.
    let registry = trust_cg_verify::ObjectRelocationProofRegistry::aarch64_elf_production();
    Ok(
        trust_cg_verify::ObjectRelocationInventoryReport::from_emitted_kinds_with_registry(
            object_name,
            emitted,
            &registry,
        ),
    )
}

/// Map an emitted AArch64 Mach-O relocation kind to its proof-inventory row.
///
/// Each emitted `relocation_info` row is named so the proof-promotion gate can
/// decide coverage. Naming a row is not Certified authority; every current
/// AArch64 Mach-O row maps to an Unverified inventory entry in production.
#[cfg(feature = "verify")]
fn aarch64_macho_object_relocation_kind(
    kind: crate::macho::AArch64RelocKind,
) -> trust_cg_verify::ObjectRelocationKind {
    use crate::macho::AArch64RelocKind as K;
    use trust_cg_verify::ObjectRelocationKind as O;
    match kind {
        K::Page21 => O::AArch64MachOPage21,
        K::Pageoff12 => O::AArch64MachOPageoff12,
        K::GotLoadPage21 => O::AArch64MachOGotLoadPage21,
        K::GotLoadPageoff12 => O::AArch64MachOGotLoadPageoff12,
        K::Branch26 => O::AArch64MachOBranch26,
        K::Unsigned => O::AArch64MachOUnsigned,
        K::Subtractor => O::AArch64MachOSubtractor,
        K::TlvpLoadPage21 => O::AArch64MachOTlvpLoadPage21,
        K::TlvpLoadPageoff12 => O::AArch64MachOTlvpLoadPageoff12,
        other => O::AArch64MachOOther(other as u8),
    }
}

/// Build the object-relocation proof inventory for an AArch64 Mach-O object.
///
/// Walks the emitted symbolic fixups, names each as its `relocation_info` row,
/// and checks coverage against the production registry, whose rows cite the
/// standing solver-backed value-proof lanes
/// (`aarch64_macho_data/call/tlvp_reloc_proofs`, registered with negative
/// controls in the proof database and discharged by the strict proof gate).
/// The BINDING half of the Certified composition is the ENC-9 Mach-O reparse
/// gate, which the writer runs UNCONDITIONALLY at Enforce over the exact bytes
/// of every emitted object (a record mismatch fails the write closed, so a
/// promoted-but-unreparsed object cannot exist). If the gate is downgraded
/// (`TCG_NO_MACHO_REPARSE` / warn / off), the binding is absent and every row
/// reports Unverified — promotion re-fails closed (the `54762bc4` invariant).
/// An `ARM64_RELOC_ADDEND` auxiliary row is never a
/// standalone fixup (it is synthesized only alongside a main page/pageoff/branch
/// reloc with a non-zero addend); the local-immutable-global-read slice uses
/// addend 0, so no addend row is produced.
#[cfg(feature = "verify")]
fn aarch64_macho_relocation_inventory_report(
    object_name: impl Into<String>,
    fixups: &crate::macho::fixup::FixupList,
    additional_rows: impl IntoIterator<Item = trust_cg_verify::ObjectRelocationKind>,
) -> trust_cg_verify::ObjectRelocationInventoryReport {
    let mut emitted: Vec<trust_cg_verify::ObjectRelocationKind> = fixups
        .iter()
        .map(|fixup| aarch64_macho_object_relocation_kind(fixup.kind))
        .collect();
    emitted.extend(additional_rows);
    let registry = trust_cg_verify::ObjectRelocationProofRegistry::aarch64_macho_production();
    let binding = if crate::macho::reparse::macho_reparse_mode()
        == crate::macho::reparse::MachoReparseMode::Enforce
    {
        trust_cg_verify::ObjectProofBinding::MachOReparseEnforced
    } else {
        trust_cg_verify::ObjectProofBinding::Unbound
    };
    trust_cg_verify::ObjectRelocationInventoryReport::from_emitted_kinds_with_registry_and_binding(
        object_name,
        emitted,
        &registry,
        binding,
    )
}

fn emit_aarch64_elf_with_supported_fixups(
    target_triple: &str,
    combined_code: &[u8],
    func_offsets: &[(String, u64)],
    globals: &[ObjectGlobal],
    fixups: &crate::macho::fixup::FixupList,
    text_align_log2: u8,
) -> Result<Vec<u8>, PipelineError> {
    use crate::elf::{Elf64Rela, ElfWriter};
    use crate::macho::FixupTarget;

    let mut writer = ElfWriter::new(crate::elf::ElfMachine::AArch64);
    writer.add_text_section_with_align(
        combined_code,
        elf_text_align_bytes(crate::elf::ElfMachine::AArch64, text_align_log2),
    );

    let total = combined_code.len() as u64;
    let mut symbol_indices: HashMap<String, u32> = HashMap::new();
    let mut next_symbol_index = 1u32; // ELF symbol index 0 is the null symbol.

    // The writer partitions the symbol table locals-first (ELF `sh_info`
    // requirement), preserving insertion order within each class. The
    // incremental index bookkeeping below therefore requires every LOCAL
    // symbol to be recorded BEFORE any global-partition symbol: emit the
    // Internal/Private (STB_LOCAL) global definitions first, then functions
    // and external globals.
    let global_symbol_rows = add_elf_global_sections(&mut writer, globals);
    let elf_global_row_sym_type = |row: &ElfGlobalSymbolRow| {
        if row.is_tls {
            crate::elf::constants::STT_TLS
        } else {
            crate::elf::constants::STT_OBJECT
        }
    };
    for row in global_symbol_rows.iter().filter(|row| !row.is_external) {
        writer.add_symbol(
            &row.name,
            row.section,
            row.offset,
            row.size,
            false,
            elf_global_row_sym_type(row),
        );
        symbol_indices.insert(row.name.clone(), next_symbol_index);
        next_symbol_index += 1;
    }

    for (index, (name, offset)) in func_offsets.iter().enumerate() {
        let next = func_offsets
            .get(index + 1)
            .map(|(_, o)| *o)
            .unwrap_or(total);
        let size = next.saturating_sub(*offset);
        writer.add_symbol(name, 1, *offset, size, true, 2);
        symbol_indices.insert(name.clone(), next_symbol_index);
        next_symbol_index += 1;
    }

    for row in global_symbol_rows.iter().filter(|row| row.is_external) {
        let sym_type = elf_global_row_sym_type(row);
        // A weak DEFINITION gets STB_WEAK so duplicate definitions across objects
        // coalesce instead of dup-strong-erroring; a strong one stays STB_GLOBAL.
        if row.is_weak {
            writer.add_weak_symbol(&row.name, row.section, row.offset, row.size, sym_type);
        } else {
            writer.add_symbol(&row.name, row.section, row.offset, row.size, true, sym_type);
        }
        symbol_indices.insert(row.name.clone(), next_symbol_index);
        next_symbol_index += 1;
    }

    // Thread-local IMPORTS: undefined STT_TLS symbols (a TLS relocation
    // against a non-TLS undefined symbol is a link-time kind mismatch), added
    // BEFORE the generic undefined pass so the TPREL fixups bind to these.
    for name in elf_tls_import_names(globals) {
        if let std::collections::hash_map::Entry::Vacant(entry) = symbol_indices.entry(name) {
            writer.add_symbol(entry.key(), 0, 0, 0, true, crate::elf::constants::STT_TLS);
            entry.insert(next_symbol_index);
            next_symbol_index += 1;
        }
    }

    let mut undefined_names = BTreeSet::new();
    for fixup in fixups.iter() {
        aarch64_elf_reloc_kind(target_triple, combined_code, fixup)?;
        match &fixup.target {
            FixupTarget::NamedSymbol(name) => {
                if !symbol_indices.contains_key(name) {
                    undefined_names.insert(name.clone());
                }
            }
            other => {
                return Err(PipelineError::TargetObjectUnsupported {
                    target: target_triple.to_string(),
                    format: "ELF".to_string(),
                    reason: format!(
                        "AArch64 ELF relocation requires a named symbol target; got {other:?}"
                    ),
                });
            }
        }
    }

    for name in undefined_names {
        writer.add_symbol(&name, 0, 0, 0, true, 0);
        symbol_indices.insert(name, next_symbol_index);
        next_symbol_index += 1;
    }

    for fixup in fixups.iter() {
        let FixupTarget::NamedSymbol(name) = &fixup.target else {
            unreachable!("non-named AArch64 ELF fixup rejected above");
        };
        let symbol_index = symbol_indices
            .get(name)
            .copied()
            .expect("named fixup target should have an ELF symbol");
        let reloc_kind = aarch64_elf_reloc_kind(target_triple, combined_code, fixup)?;
        writer.add_relocation(
            0,
            Elf64Rela::aarch64(fixup.offset as u64, symbol_index, reloc_kind, fixup.addend),
        );
    }

    Ok(writer.write())
}

/// Shared fail-closed gates for globals headed to the AArch64 ELF emitters.
///
/// Thread-local globals are supported: definitions land in `.tdata`
/// (`SHF_TLS`, `STT_TLS` symbols) and imports become undefined `STT_TLS`
/// symbols, addressed by the local-exec `R_AARCH64_TLSLE_ADD_TPREL_*`
/// sequence. A thread-local carrying symbol-address relocation elements
/// stays fail-closed (no `.tdata` data-relocation path — and a relocated
/// pointer in a TLS template would need per-thread rebasing anyway).
///
/// Symbol-address data relocations (vtable / `static FNS: [fn(); N]` slots)
/// are wired for the Mach-O writer (`ARM64_RELOC_UNSIGNED`) but NOT this
/// legacy no-unwind ELF emitter (`add_elf_global_sections` copies the
/// zero-filled pointer slot without an `R_*_64` relocation, so the pointer
/// would link as null). Fail closed here rather than emit a silently-wrong
/// all-zero pointer. (The unwind ELF emitter DOES wire these via
/// `R_AARCH64_ABS64`.)
fn reject_unsupported_elf_globals(
    target_triple: &str,
    globals: &[ObjectGlobal],
) -> Result<(), PipelineError> {
    if let Some(global) = globals.iter().find(|global| !global.symbol_refs.is_empty()) {
        return Err(PipelineError::TargetObjectUnsupported {
            target: target_triple.to_string(),
            format: "ELF".to_string(),
            reason: format!(
                "global '{}' contains symbol-address relocation elements; the ELF object emitter's data-relocation path is not implemented (the Mach-O emitter handles these via ARM64_RELOC_UNSIGNED)",
                global.name
            ),
        });
    }

    Ok(())
}

/// A thread-local template whose bytes embed symbol-address relocation slots
/// has no sound ELF lowering here (each thread's copy would need its own
/// rebased pointer). No producer emits one today; keep it impossible.
fn reject_elf_tls_globals_with_symbol_refs(
    target_triple: &str,
    globals: &[ObjectGlobal],
) -> Result<(), PipelineError> {
    if let Some(global) = globals
        .iter()
        .find(|global| global.is_thread_local && !global.symbol_refs.is_empty())
    {
        return Err(PipelineError::TargetObjectUnsupported {
            target: target_triple.to_string(),
            format: "ELF".to_string(),
            reason: format!(
                "thread-local global '{}' carries symbol-address relocation elements; a relocated pointer inside a TLS initial-value template is not supported (fail-closed)",
                global.name
            ),
        });
    }
    Ok(())
}

fn emit_target_elf_or_reject_fixups(
    target_triple: &str,
    fixups: &crate::macho::fixup::FixupList,
    combined_code: &[u8],
    func_offsets: &[(String, u64)],
    globals: &[ObjectGlobal],
    text_align_log2: u8,
) -> Result<Option<Vec<u8>>, PipelineError> {
    reject_unsupported_aarch64_object_format(target_triple)?;
    if !target_triple_uses_elf(target_triple) {
        return Ok(None);
    }

    reject_unsupported_elf_globals(target_triple, globals)?;

    // The caller has passed the AArch64 target gate above. Do not derive the
    // ELF e_machine from an arbitrary triple: the bytes in `combined_code` are
    // unconditionally little-endian AArch64.
    let machine = crate::elf::ElfMachine::AArch64;

    if !fixups.is_empty() {
        return emit_aarch64_elf_with_supported_fixups(
            target_triple,
            combined_code,
            func_offsets,
            globals,
            fixups,
            text_align_log2,
        )
        .map(Some);
    }

    Ok(Some(emit_elf_with_function_symbols(
        machine,
        combined_code,
        func_offsets,
        globals,
        text_align_log2,
    )))
}

/// Emit an AArch64 ELF object with whole-module `.eh_frame` unwind tables
/// (and `.gcc_except_table` LSDAs for exception-handling functions).
///
/// This is the ELF analogue of [`Pipeline::emit_module_macho_with_unwind`]
/// ([TCG-EH-A64-BATCH] / the FUZZ-7 [TCG-EH-WALK] class): when ANY function in
/// a linked image raises a panic, the unwinder must be able to WALK every
/// trust-cg frame between the throw and the handler. ELF has no compact-unwind
/// section, so EVERY function gets a DWARF FDE:
///
/// * a frame-based function (`layout.uses_frame_pointer`) gets the standard
///   prologue-describing CFI ([`DwarfFde::from_layout`] — the same generator
///   the proven Mach-O DWARF fallback uses);
/// * a zero-frame leaf gets an EMPTY-instruction FDE: the CIE's initial
///   `DW_CFA_def_cfa SP, 0` is exact for its whole body and X30 keeps the
///   return address (`REG_UNSAVED` default rule);
/// * an EH function's REAL LSDA lands in `.gcc_except_table`, referenced from
///   its FDE augmentation; when the module carries EH the shared CIE is zPLR,
///   and every non-EH function gets a synthetic ALL-FILLER LSDA (one
///   `landing_pad == 0` region covering `[0, code_len)`) — the personality's
///   "no handler here, continue unwinding" answer, mirroring the audited
///   Mach-O filler policy (it can only tell the unwinder to KEEP WALKING).
///
/// Pointer scheme (GNU/Linux `.eh_frame` convention): all record pointers are
/// `DW_EH_PE_pcrel|sdata4` fields resolved by `R_AARCH64_PREL32` relocations —
/// FDE pc-begin against the function's own symbol, LSDA against a local
/// `.gcc_except_table` `STT_SECTION` anchor (+ offset addend), and the CIE
/// personality DIRECTLY against the personality symbol (see
/// [`crate::dwarf_cfi::DwarfCie::aarch64_elf_with_eh`] for why the GCC
/// `DW.ref.*` indirect slot is not needed in the static t* link). No
/// mid-object `.eh_frame` terminator is emitted (crtend.o owns it), matching
/// GNU toolchain relocatable objects.
///
/// Behavior gates (all fail closed, never silent):
/// * not an ELF triple → `Ok(None)` (caller falls through to Mach-O);
/// * module has EH but a function is missing its frame layout → error (an
///   undescribed frame would stop phase-1 unwinding dead);
/// * no EH and layouts incomplete → byte-identical legacy no-unwind emission
///   via [`emit_target_elf_or_reject_fixups`] (layout-less API callers).
fn emit_aarch64_elf_module_with_unwind(
    target_triple: &str,
    combined_code: &[u8],
    func_offsets: &[(String, u64)],
    globals: &[ObjectGlobal],
    fixups: &crate::macho::fixup::FixupList,
    func_eh: &[ModuleFunctionEhData],
    frame_layouts: &[Option<crate::frame::FrameLayout>],
    text_align_log2: u8,
) -> Result<Option<Vec<u8>>, PipelineError> {
    use crate::dwarf_cfi::{DwarfCfiSection, DwarfFde};
    use crate::elf::constants::{SHF_ALLOC, SHT_PROGBITS, STT_SECTION};
    use crate::elf::{Elf64Rela, ElfWriter};
    use crate::exception_handling::generate_lsda_from_pads;
    use crate::macho::FixupTarget;

    reject_unsupported_aarch64_object_format(target_triple)?;
    if !target_triple_uses_elf(target_triple) {
        return Ok(None);
    }
    // Thread-locals are supported (`.tdata` definitions + undefined STT_TLS
    // imports + local-exec TPREL text fixups); only a TLS template embedding
    // symbol-address slots stays impossible. Symbol-address data relocations
    // in NON-TLS globals ARE handled below (`R_AARCH64_ABS64` into the
    // global's own section — the ELF analogue of the Mach-O
    // `ARM64_RELOC_UNSIGNED` path).
    reject_elf_tls_globals_with_symbol_refs(target_triple, globals)?;

    let module_has_eh = func_eh.iter().any(|f| f.lsda.is_some());
    let layouts_complete = !func_eh.is_empty()
        && (0..func_eh.len()).all(|i| frame_layouts.get(i).is_some_and(|l| l.is_some()));

    if module_has_eh && !layouts_complete {
        let missing = func_offsets
            .iter()
            .enumerate()
            .find(|(i, _)| frame_layouts.get(*i).is_none_or(|l| l.is_none()))
            .map(|(_, (name, _))| name.clone())
            .unwrap_or_default();
        return Err(PipelineError::Encoding(format!(
            "ELF module carries exception-handling structure, so EVERY function \
             needs an .eh_frame FDE (a frame without one stops unwinding at \
             phase 1 — skipped cleanup Drops at run time), but no frame layout \
             was provided for `{missing}`. Thread per-function frame layouts \
             via compile_module_with_globals_and_layouts (fail-closed)."
        )));
    }
    if !layouts_complete {
        // Layout-less legacy callers: keep the proven no-unwind emission
        // byte-identical.
        return emit_target_elf_or_reject_fixups(
            target_triple,
            fixups,
            combined_code,
            func_offsets,
            globals,
            text_align_log2,
        );
    }
    let layout = |i: usize| -> &crate::frame::FrameLayout {
        frame_layouts[i].as_ref().expect("layouts_complete checked")
    };

    // One personality per module (single shared CIE) — mirror the Mach-O
    // planner's fail-closed policy.
    let mut personalities: Vec<&str> = func_eh
        .iter()
        .filter_map(|f| {
            f.lsda
                .as_ref()
                .map(|(_, p)| crate::exception_handling::canonical_personality_symbol(p.as_str()))
        })
        .collect();
    personalities.sort_unstable();
    personalities.dedup();
    let personality: Option<&str> = match personalities.as_slice() {
        [] => None,
        [single] => Some(*single),
        multiple => {
            return Err(PipelineError::Encoding(format!(
                "ELF module unwind emission supports one personality routine per \
                 module (single shared CIE); found {multiple:?} (fail-closed)"
            )));
        }
    };

    // ----- Build `.gcc_except_table` bytes + per-function offsets -----------
    // Real LSDAs for EH functions; ALL-FILLER LSDAs for the rest when the
    // module carries EH (every FDE under a zPLR CIE carries an LSDA field).
    let mut lsda_data: Vec<u8> = Vec::new();
    let mut lsda_offsets: Vec<Option<i64>> = vec![None; func_eh.len()];
    if module_has_eh {
        for (i, f) in func_eh.iter().enumerate() {
            let bytes: Vec<u8> = match &f.lsda {
                Some((lsda, _)) => lsda.clone(),
                None => {
                    let personality = personality.ok_or_else(|| {
                        PipelineError::Encoding(format!(
                            "synthetic filler LSDA for ELF module function {} needs a \
                             personality routine but the module has none (fail-closed)",
                            func_offsets[i].0
                        ))
                    })?;
                    generate_lsda_from_pads(personality, &[], &[(0, f.code_len, 0)]).map_err(
                        |error| {
                            PipelineError::Encoding(format!(
                                "synthetic filler LSDA for ELF module function {} is \
                                 invalid: {error}",
                                func_offsets[i].0
                            ))
                        },
                    )?
                }
            };
            while !lsda_data.len().is_multiple_of(4) {
                lsda_data.push(0);
            }
            lsda_offsets[i] = Some(checked_aarch64_object_u32(
                &func_offsets[i].0,
                "ELF LSDA section offset",
                lsda_data.len(),
            )? as i64);
            lsda_data.extend_from_slice(&bytes);
        }
    }

    // ----- Build `.eh_frame` (one CIE + an FDE per function) ----------------
    let mut cfi = if module_has_eh {
        DwarfCfiSection::new_aarch64_elf_with_eh()
    } else {
        DwarfCfiSection::new_aarch64_elf()
    };
    for (i, f) in func_eh.iter().enumerate() {
        let layout = layout(i);
        let mut fde = if layout.uses_frame_pointer {
            DwarfFde::from_layout(layout, 0, f.code_len, 0)
        } else {
            // Zero-frame leaf: the CIE's initial CFA=SP+0 rule is exact for
            // the whole body; X30 (unmodified) holds the return address.
            DwarfFde {
                function_offset: 0,
                function_length: f.code_len,
                symbol_index: 0,
                instructions: Vec::new(),
                lsda_pointer: None,
            }
        };
        if module_has_eh {
            fde = fde.with_lsda();
        }
        cfi.add_fde(fde);
    }

    // ----- Assemble the object ----------------------------------------------
    let mut writer = ElfWriter::new(crate::elf::ElfMachine::AArch64);
    writer.add_text_section_with_align(
        combined_code,
        elf_text_align_bytes(crate::elf::ElfMachine::AArch64, text_align_log2),
    ); // user section 0 / shndx 1

    let global_symbol_rows = add_elf_global_sections(&mut writer, globals);

    let except_table_shndx: Option<u16> = if lsda_data.is_empty() {
        None
    } else {
        Some(writer.add_section(".gcc_except_table", &lsda_data, SHT_PROGBITS, SHF_ALLOC, 4))
    };
    let eh_frame_bytes = cfi.to_bytes_no_terminator();
    let eh_frame_shndx =
        writer.add_section(".eh_frame", &eh_frame_bytes, SHT_PROGBITS, SHF_ALLOC, 8);
    let eh_frame_user_idx = (eh_frame_shndx - 1) as usize;

    // The GCC-shaped indirect personality slot: an 8-byte writable cell the
    // CIE's `DW_EH_PE_indirect|pcrel|sdata4` personality field points at,
    // holding the personality's absolute address (`R_AARCH64_ABS64`, a
    // dynamic reloc under PIE). One weak definition per object; duplicate
    // definitions across objects coalesce at link.
    let dw_ref_section_and_name: Option<(u16, String)> = if module_has_eh {
        let personality = personality.expect("module_has_eh implies a personality");
        let shndx = writer.add_section(
            &format!(".data.DW.ref.{personality}"),
            &[0u8; 8],
            SHT_PROGBITS,
            crate::elf::constants::SHF_ALLOC | crate::elf::constants::SHF_WRITE,
            8,
        );
        Some((shndx, format!("DW.ref.{personality}")))
    } else {
        None
    };

    // ----- Symbols -----------------------------------------------------------
    // The writer partitions the symbol table locals-first (ELF requirement),
    // preserving insertion order within each class. Add the single local
    // (the `.gcc_except_table` STT_SECTION anchor) first, then every global,
    // and compute final indices from that partition.
    let mut num_locals = 0u32;
    let except_anchor_index: Option<u32> = except_table_shndx.map(|shndx| {
        writer.add_symbol("", shndx, 0, 0, false, STT_SECTION);
        num_locals += 1;
        num_locals // anchor is the first local → symtab index 1
    });

    let mut symbol_indices: HashMap<String, u32> = HashMap::new();
    let elf_global_row_sym_type = |row: &ElfGlobalSymbolRow| {
        if row.is_tls {
            crate::elf::constants::STT_TLS
        } else {
            crate::elf::constants::STT_OBJECT
        }
    };
    // Internal/Private (STB_LOCAL) global definitions: the writer partitions
    // locals first, so these must be recorded BEFORE any global-partition
    // symbol for the incremental index bookkeeping to stay valid. STB_LOCAL
    // is required for correctness, not taste: every module carries its own
    // copy of content-hashed internals (`str.<hash>` / `vtable.<hash>`), and
    // STB_GLOBAL copies collide across objects at static link.
    for row in global_symbol_rows.iter().filter(|row| !row.is_external) {
        writer.add_symbol(
            &row.name,
            row.section,
            row.offset,
            row.size,
            false,
            elf_global_row_sym_type(row),
        );
        num_locals += 1;
        symbol_indices.insert(row.name.clone(), num_locals);
    }
    let mut next_symbol_index = 1u32 + num_locals;

    let total = combined_code.len() as u64;
    for (index, (name, offset)) in func_offsets.iter().enumerate() {
        let next = func_offsets
            .get(index + 1)
            .map(|(_, o)| *o)
            .unwrap_or(total);
        let size = next.saturating_sub(*offset);
        writer.add_symbol(name, 1, *offset, size, true, 2);
        symbol_indices.insert(name.clone(), next_symbol_index);
        next_symbol_index += 1;
    }

    for row in global_symbol_rows.iter().filter(|row| row.is_external) {
        let sym_type = elf_global_row_sym_type(row);
        if row.is_weak {
            writer.add_weak_symbol(&row.name, row.section, row.offset, row.size, sym_type);
        } else {
            writer.add_symbol(&row.name, row.section, row.offset, row.size, true, sym_type);
        }
        symbol_indices.insert(row.name.clone(), next_symbol_index);
        next_symbol_index += 1;
    }

    // Thread-local IMPORTS: undefined STT_TLS symbols (a TLS relocation
    // against a non-TLS undefined symbol is a link-time kind mismatch), added
    // BEFORE the generic undefined pass so the TPREL fixups bind to these.
    for name in elf_tls_import_names(globals) {
        if let std::collections::hash_map::Entry::Vacant(entry) = symbol_indices.entry(name) {
            writer.add_symbol(entry.key(), 0, 0, 0, true, crate::elf::constants::STT_TLS);
            entry.insert(next_symbol_index);
            next_symbol_index += 1;
        }
    }

    // Undefined externs referenced by text fixups.
    let mut undefined_names = BTreeSet::new();
    for fixup in fixups.iter() {
        aarch64_elf_reloc_kind(target_triple, combined_code, fixup)?;
        match &fixup.target {
            FixupTarget::NamedSymbol(name) => {
                if !symbol_indices.contains_key(name) {
                    undefined_names.insert(name.clone());
                }
            }
            other => {
                return Err(PipelineError::TargetObjectUnsupported {
                    target: target_triple.to_string(),
                    format: "ELF".to_string(),
                    reason: format!(
                        "AArch64 ELF relocation requires a named symbol target; got {other:?}"
                    ),
                });
            }
        }
    }
    // The CIE personality reference (defined here or extern).
    if let Some(personality) = personality
        && !symbol_indices.contains_key(personality)
    {
        undefined_names.insert(personality.to_string());
    }
    // Symbol-address slots inside global data (vtables / fn-pointer tables)
    // may target functions or globals defined elsewhere.
    for global in globals {
        for sref in &global.symbol_refs {
            if !symbol_indices.contains_key(&sref.symbol) {
                undefined_names.insert(sref.symbol.clone());
            }
        }
    }
    for name in undefined_names {
        writer.add_symbol(&name, 0, 0, 0, true, 0);
        symbol_indices.insert(name, next_symbol_index);
        next_symbol_index += 1;
    }

    // The weak `DW.ref.<personality>` slot symbol (global partition).
    let dw_ref_symbol: Option<u32> = dw_ref_section_and_name.as_ref().map(|(shndx, name)| {
        writer.add_weak_symbol(name, *shndx, 0, 8, crate::elf::constants::STT_OBJECT);
        let index = next_symbol_index;
        next_symbol_index += 1;
        index
    });

    // ----- Relocations --------------------------------------------------------
    // `.text`: the branch/page fixups, exactly as the no-unwind emitter.
    for fixup in fixups.iter() {
        let FixupTarget::NamedSymbol(name) = &fixup.target else {
            unreachable!("non-named AArch64 ELF fixup rejected above");
        };
        let symbol_index = symbol_indices
            .get(name)
            .copied()
            .expect("named fixup target should have an ELF symbol");
        let reloc_kind = aarch64_elf_reloc_kind(target_triple, combined_code, fixup)?;
        writer.add_relocation(
            0,
            Elf64Rela::aarch64(fixup.offset as u64, symbol_index, reloc_kind, fixup.addend),
        );
    }

    // Global data sections: `R_AARCH64_ABS64` for every symbol-address slot
    // (vtable / `static FNS: [fn(); N]` elements) — the ELF analogue of the
    // Mach-O `ARM64_RELOC_UNSIGNED` data path. The slot's zero-filled bytes
    // are placeholders; RELA addends carry the constant offset.
    if globals.iter().any(|global| !global.symbol_refs.is_empty()) {
        let global_rows: HashMap<&str, (u16, u64)> = global_symbol_rows
            .iter()
            .map(|row| (row.name.as_str(), (row.section, row.offset)))
            .collect();
        for global in globals {
            if global.symbol_refs.is_empty() {
                continue;
            }
            let (section_shndx, base_offset) = global_rows
                .get(global.name.as_str())
                .copied()
                .ok_or_else(|| {
                    PipelineError::Encoding(format!(
                        "ELF data relocation: global `{}` has symbol-address slots but \
                         was not placed in a data section (fail-closed)",
                        global.name
                    ))
                })?;
            for sref in &global.symbol_refs {
                let symbol_index = symbol_indices
                    .get(&sref.symbol)
                    .copied()
                    .expect("symbol-ref target added to the ELF symbol table above");
                writer.add_relocation(
                    (section_shndx - 1) as usize,
                    Elf64Rela::aarch64(
                        base_offset + sref.offset,
                        symbol_index,
                        crate::elf::AArch64RelocType::Abs64,
                        sref.addend,
                    ),
                );
            }
        }
    }

    // `.eh_frame`: PREL32 pc-begin per FDE (against the function symbol),
    // PREL32 LSDA per FDE (against the `.gcc_except_table` anchor + offset),
    // PREL32 CIE personality (against the weak `DW.ref.<personality>` slot).
    //
    // ORDER MATTERS: GNU ld's `.eh_frame` parser walks the section once with
    // a monotonically advancing relocation cursor, so `.rela.eh_frame` MUST
    // be sorted by ascending `r_offset` ("error in <obj>(.eh_frame); no
    // .eh_frame_hdr table will be created" otherwise — and without the
    // `PT_GNU_EH_FRAME` search table the unwinder finds no FDEs at run
    // time). Section layout is CIE (personality field) then FDEs in add
    // order, and within an FDE pc-begin precedes the LSDA field, so emitting
    // personality → per-FDE (pc-begin, LSDA) yields ascending offsets.
    if module_has_eh {
        if let Some(personality_offset) = cfi.cie_personality_relocation_offset() {
            let dw_ref_symbol = dw_ref_symbol.ok_or_else(|| {
                PipelineError::Encoding(
                    "ELF module unwind emission: zPLR CIE without a DW.ref personality \
                     slot (fail-closed)"
                        .to_string(),
                )
            })?;
            writer.add_relocation(
                eh_frame_user_idx,
                Elf64Rela::aarch64(
                    personality_offset as u64,
                    dw_ref_symbol,
                    crate::elf::AArch64RelocType::Prel32,
                    0,
                ),
            );
        } else {
            return Err(PipelineError::Encoding(
                "ELF module unwind emission: EH module CIE has no personality field \
                 (fail-closed)"
                    .to_string(),
            ));
        }
    }
    let pc_begin_offsets = cfi.fde_pc_begin_relocation_offsets();
    let lsda_field_offsets = cfi.fde_lsda_relocation_offsets();
    if module_has_eh && lsda_field_offsets.len() != pc_begin_offsets.len() {
        return Err(PipelineError::Encoding(format!(
            "ELF module unwind emission: {} FDEs but {} LSDA fields under a zPLR CIE \
             (fail-closed)",
            pc_begin_offsets.len(),
            lsda_field_offsets.len()
        )));
    }
    for (i, pc_begin_offset) in pc_begin_offsets.into_iter().enumerate() {
        let func_symbol = symbol_indices
            .get(&func_offsets[i].0)
            .copied()
            .expect("every module function has an ELF symbol");
        writer.add_relocation(
            eh_frame_user_idx,
            Elf64Rela::aarch64(
                pc_begin_offset as u64,
                func_symbol,
                crate::elf::AArch64RelocType::Prel32,
                0,
            ),
        );
        if module_has_eh {
            let anchor = except_anchor_index.ok_or_else(|| {
                PipelineError::Encoding(
                    "ELF module unwind emission: EH module produced no .gcc_except_table \
                     anchor symbol (fail-closed)"
                        .to_string(),
                )
            })?;
            let lsda_offset = lsda_offsets[i].ok_or_else(|| {
                PipelineError::Encoding(format!(
                    "ELF module unwind emission: FDE for `{}` has an LSDA slot but no \
                     LSDA bytes were laid out (fail-closed)",
                    func_offsets[i].0
                ))
            })?;
            writer.add_relocation(
                eh_frame_user_idx,
                Elf64Rela::aarch64(
                    lsda_field_offsets[i] as u64,
                    anchor,
                    crate::elf::AArch64RelocType::Prel32,
                    lsda_offset,
                ),
            );
        }
    }

    // The DW.ref slot's own content relocation: the 8-byte cell holds the
    // personality's absolute address (dynamic RELATIVE reloc under PIE).
    if let Some((dw_ref_shndx, _)) = &dw_ref_section_and_name {
        let personality_name = personality.expect("dw_ref implies personality");
        let personality_symbol = symbol_indices
            .get(personality_name)
            .copied()
            .expect("personality symbol added above");
        writer.add_relocation(
            (*dw_ref_shndx - 1) as usize,
            Elf64Rela::aarch64(
                0,
                personality_symbol,
                crate::elf::AArch64RelocType::Abs64,
                0,
            ),
        );
    }

    Ok(Some(writer.write()))
}

fn emit_single_function_target_elf_if_needed(
    target_triple: &str,
    func_name: &str,
    code: &[u8],
    fixups: &crate::macho::fixup::FixupList,
    lsda: Option<(&[u8], &str)>,
    frame_layout: Option<&crate::frame::FrameLayout>,
    text_align_log2: u8,
) -> Result<Option<Vec<u8>>, PipelineError> {
    reject_unsupported_aarch64_object_format(target_triple)?;
    if !target_triple_uses_elf(target_triple) {
        return Ok(None);
    }

    let code_len = checked_aarch64_object_u32(func_name, "encoded code length", code.len())?;
    let func_offsets = [(func_name.to_string(), 0)];
    let func_eh = [ModuleFunctionEhData {
        code_len,
        lsda: lsda.map(|(bytes, personality)| (bytes.to_vec(), personality.to_string())),
    }];
    let frame_layouts = [frame_layout.cloned()];
    emit_aarch64_elf_module_with_unwind(
        target_triple,
        code,
        &func_offsets,
        &[],
        fixups,
        &func_eh,
        &frame_layouts,
        text_align_log2,
    )
}

fn add_single_function_symbol_ids_for_fixups(
    writer: &mut crate::macho::MachOWriter,
    func_name: &str,
    function_symbol_id: crate::macho::SymbolId,
    fixups: &crate::macho::fixup::FixupList,
) -> Result<HashMap<String, crate::macho::SymbolId>, PipelineError> {
    use crate::macho::FixupTarget;

    let mut symbol_ids = HashMap::new();
    let mut known_names = BTreeSet::new();
    let symbol_name = macho_symbol_name(func_name);
    symbol_ids.insert(func_name.to_string(), function_symbol_id);
    symbol_ids.insert(symbol_name.clone(), function_symbol_id);
    known_names.insert(func_name.to_string());
    known_names.insert(symbol_name);

    let mut undefined_names = BTreeSet::new();
    for fixup in fixups.iter() {
        if let FixupTarget::NamedSymbol(name) = &fixup.target {
            let symbol_name = macho_symbol_name(name);
            if !known_names.contains(name) && !known_names.contains(&symbol_name) {
                undefined_names.insert(name.clone());
            }
        }
    }

    for name in undefined_names {
        let symbol_name = macho_symbol_name(&name);
        let symbol_id = writer.add_symbol(&symbol_name, 0, 0, true)?;
        symbol_ids.insert(name, symbol_id);
        symbol_ids.insert(symbol_name, symbol_id);
    }

    Ok(symbol_ids)
}

fn final_macho_symbol_index(
    writer: &mut crate::macho::MachOWriter,
    symbol_id: crate::macho::SymbolId,
    context: &str,
) -> Result<u32, PipelineError> {
    writer.final_symbol_index(symbol_id)?.ok_or_else(|| {
        PipelineError::Encoding(format!(
            "Mach-O symbol id {symbol_id} missing before {context}"
        ))
    })
}

// ---------------------------------------------------------------------------
// LSDA generation from EH metadata
// ---------------------------------------------------------------------------

/// Resolve the post-layout byte offsets in a function's exception-handling
/// metadata, using the block byte offsets and total code length from encoding.
///
/// ISel forwards the EH structure (`Invoke` / `LandingPad`) into
/// `MachFunction.eh_metadata` keyed by `BlockId`, but the byte fields
/// (`LandingPadEntry.offset`, `EhCallSiteEntry.start_offset` / `length`) are
/// left at 0 because the layout is not yet known. This pass fills them once
/// block layout + branch resolution + encoding have produced `block_offsets`:
///
/// * a landing pad's `offset` becomes its exact block byte offset;
/// * each block-granular Invoke record must bind to exactly one final
///   `Bl`/`BL`/`Blr`/`BLR` instruction in that block;
/// * the protected range is exactly that fixed-width instruction's four bytes;
/// * every other byte gets a disjoint `landing_pad == None` filler entry.
///
/// Must run AFTER `resolve_branches` + encoding and BEFORE
/// `generate_lsda_for_function`. Missing, stale, ambiguous, overlapping, or
/// sentinel-colliding metadata fails closed instead of silently widening a
/// handler to unrelated instructions.
pub fn resolve_eh_offsets(
    func: &mut IrMachFunction,
    block_offsets: &HashMap<BlockId, u32>,
    code_len: usize,
) -> Result<(), PipelineError> {
    if !func.eh_metadata.has_eh_info() {
        return Ok(());
    }

    use trust_cg_ir::function::EhCallSiteEntry;

    let malformed = |detail: String| PipelineError::MalformedAarch64Function {
        function: func.name.clone(),
        detail: format!("invalid AArch64 EH metadata/layout: {detail}"),
    };
    let code_len = u32::try_from(code_len).map_err(|_| {
        malformed(format!(
            "encoded code length {code_len} exceeds the u32 LSDA offset domain"
        ))
    })?;
    if code_len == 0 {
        return Err(malformed(
            "non-empty EH metadata on an empty encoded function".to_string(),
        ));
    }
    if code_len % 4 != 0 {
        return Err(malformed(format!(
            "encoded code length {code_len} is not AArch64 instruction/data aligned"
        )));
    }

    // Authenticate the encoder's block map and derive exact final instruction
    // identities/offsets from the same fixed-width stream it encoded. InstId is
    // arena-stable across post-RA edits, unlike a positional side table.
    let mut laid_out_blocks = BTreeSet::new();
    let mut encoded_inst_offsets: HashMap<InstId, u32> = HashMap::new();
    let mut body_end = 0u32;
    for &block_id in &func.block_order {
        if !laid_out_blocks.insert(block_id) {
            return Err(malformed(format!(
                "block_order contains duplicate block {block_id:?}"
            )));
        }
        let block = func
            .blocks
            .get(block_id.0 as usize)
            .ok_or_else(|| malformed(format!("block_order names missing block {block_id:?}")))?;
        let encoded_block_start = block_offsets
            .get(&block_id)
            .copied()
            .ok_or_else(|| malformed(format!("block {block_id:?} has no final encoded offset")))?;
        if encoded_block_start != body_end {
            return Err(malformed(format!(
                "block {block_id:?} encoder offset {encoded_block_start} does not match re-derived final offset {body_end}"
            )));
        }
        for &inst_id in &block.insts {
            let inst = func.insts.get(inst_id.0 as usize).ok_or_else(|| {
                malformed(format!(
                    "block {block_id:?} names missing instruction {inst_id:?}"
                ))
            })?;
            if inst.is_pseudo() {
                continue;
            }
            if encoded_inst_offsets.insert(inst_id, body_end).is_some() {
                return Err(malformed(format!(
                    "encoded instruction {inst_id:?} appears in multiple layout positions"
                )));
            }
            body_end = body_end
                .checked_add(4)
                .ok_or_else(|| malformed("encoded instruction offsets overflow u32".to_string()))?;
        }
    }
    if block_offsets.len() != laid_out_blocks.len()
        || block_offsets
            .keys()
            .any(|block| !laid_out_blocks.contains(block))
    {
        return Err(malformed(
            "encoder block-offset map does not exactly match block_order".to_string(),
        ));
    }
    if body_end > code_len {
        return Err(malformed(format!(
            "re-derived instruction body length {body_end} exceeds encoded length {code_len}"
        )));
    }

    // Resolve and authenticate landing-pad offsets. Zero is the LSDA sentinel
    // for "no handler" and therefore cannot identify a semantic landing pad.
    let mut landing_pad_offsets = HashMap::new();
    for lp in &mut func.eh_metadata.landing_pads {
        if landing_pad_offsets.contains_key(&lp.block) {
            return Err(malformed(format!(
                "duplicate landing-pad record for block {:?}",
                lp.block
            )));
        }
        if !laid_out_blocks.contains(&lp.block) {
            return Err(malformed(format!(
                "landing-pad block {:?} is absent from block_order",
                lp.block
            )));
        }
        let offset = block_offsets.get(&lp.block).copied().ok_or_else(|| {
            malformed(format!(
                "landing-pad block {:?} has no final encoded offset",
                lp.block
            ))
        })?;
        let has_real_instruction = func.blocks.get(lp.block.0 as usize).is_some_and(|block| {
            block.insts.iter().any(|inst_id| {
                func.insts
                    .get(inst_id.0 as usize)
                    .is_some_and(|inst| !inst.is_pseudo())
            })
        });
        if offset == 0 {
            return Err(malformed(format!(
                "landing-pad block {:?} resolves to offset 0, reserved by the LSDA as no-handler",
                lp.block
            )));
        }
        if offset >= body_end || !has_real_instruction {
            return Err(malformed(format!(
                "landing-pad block {:?} at offset {offset} has no encoded instruction body",
                lp.block
            )));
        }
        if lp.offset != 0 && lp.offset != offset {
            return Err(malformed(format!(
                "landing-pad block {:?} carries stale offset {}, final layout requires {offset}",
                lp.block, lp.offset
            )));
        }
        lp.offset = offset;
        landing_pad_offsets.insert(lp.block, offset);
    }

    // Ensure the call-site table covers the ENTIRE function `[0, code_len)`.
    //
    // The Itanium personality (`__gxx_personality_v0`, libcxxabi
    // `scan_eh_table`) requires the call-site entries to be sorted, non-
    // overlapping, and — critically — to cover every PC that can be "in flight"
    // during unwinding. If it is consulted at a PC that falls in a GAP between
    // entries (or past the last entry), it does NOT continue unwinding: it calls
    // `std::terminate()` (cxa_personality.cpp lines 908-913 and 918-920).
    //
    // A CATCH-only landing pad never re-enters the unwinder (it claims the
    // exception and returns normally), so a single throwing-call region is
    // enough for it. But a CLEANUP pad runs `_Unwind_Resume(exn)`, which RE-
    // CONSULTS this same function's personality at the resume `Bl`'s PC. That PC
    // lies inside the landing-pad block — NOT inside any throwing-call region —
    // so without full coverage the personality terminates instead of stepping
    // out to the enclosing handler. Clang emits filler `landingPad == 0`
    // call-site entries over the non-throwing regions for exactly this reason.
    //
    // Canonicalize away any prior no-handler entries (including fillers from a
    // previous resolution), then bind every semantic handler record to one
    // exact final call instruction. A no-handler record is semantically
    // equivalent to filler; action chains are derived exclusively from its
    // referenced landing-pad descriptor by the checked LSDA builder.
    let original_call_sites = func.eh_metadata.call_sites.clone();
    let mut protected_blocks = BTreeSet::new();
    let mut explicit = Vec::new();
    for cs in original_call_sites {
        let Some(landing_pad_block) = cs.landing_pad_block else {
            continue;
        };
        if !protected_blocks.insert(cs.call_block) {
            return Err(malformed(format!(
                "EH call block {:?} has multiple handler records; block-granular metadata is ambiguous",
                cs.call_block
            )));
        }
        if !landing_pad_offsets.contains_key(&landing_pad_block) {
            return Err(malformed(format!(
                "EH call block {:?} targets block {landing_pad_block:?}, which has no landing-pad descriptor",
                cs.call_block
            )));
        }
        let block = func
            .blocks
            .get(cs.call_block.0 as usize)
            .filter(|_| laid_out_blocks.contains(&cs.call_block))
            .ok_or_else(|| {
                malformed(format!(
                    "EH call block {:?} is missing or absent from block_order",
                    cs.call_block
                ))
            })?;
        let successor_count = block
            .succs
            .iter()
            .filter(|&&succ| succ == landing_pad_block)
            .count();
        let predecessor_count = func
            .blocks
            .get(landing_pad_block.0 as usize)
            .map_or(0, |pad| {
                pad.preds
                    .iter()
                    .filter(|&&pred| pred == cs.call_block)
                    .count()
            });
        if successor_count != 1 || predecessor_count != 1 {
            return Err(malformed(format!(
                "exceptional edge {:?} -> {landing_pad_block:?} is not exactly reciprocal (successors={successor_count}, predecessors={predecessor_count})",
                cs.call_block
            )));
        }
        let calls: Vec<InstId> = block
            .insts
            .iter()
            .copied()
            .filter(|&inst_id| {
                func.insts.get(inst_id.0 as usize).is_some_and(|inst| {
                    matches!(
                        inst.opcode,
                        IrOpcode::Bl | IrOpcode::BL | IrOpcode::Blr | IrOpcode::BLR
                    )
                })
            })
            .collect();
        let [call_id] = calls.as_slice() else {
            return Err(malformed(format!(
                "EH call block {:?} contains {} eligible BL/BLR calls; exactly one is required by block-granular metadata",
                cs.call_block,
                calls.len()
            )));
        };
        let start = encoded_inst_offsets.get(call_id).copied().ok_or_else(|| {
            malformed(format!(
                "protected call {call_id:?} has no exact final-encoding offset"
            ))
        })?;
        let end = start
            .checked_add(4)
            .ok_or_else(|| malformed(format!("protected call {call_id:?} range overflows u32")))?;
        if end > body_end || end > code_len {
            return Err(malformed(format!(
                "protected call {call_id:?} range [{start},{end}) escapes instruction body [0,{body_end}) or code [0,{code_len})"
            )));
        }
        if (cs.start_offset != 0 || cs.length != 0) && (cs.start_offset != start || cs.length != 4)
        {
            return Err(malformed(format!(
                "protected call {call_id:?} carries stale range [{},{}), final encoding requires [{start},{end})",
                cs.start_offset,
                cs.start_offset.saturating_add(cs.length)
            )));
        }
        explicit.push(EhCallSiteEntry {
            call_block: cs.call_block,
            start_offset: start,
            length: 4,
            landing_pad_block: Some(landing_pad_block),
        });
    }

    explicit.sort_by_key(|cs| cs.start_offset);
    let filler_block = explicit
        .first()
        .map(|cs| cs.call_block)
        .or_else(|| func.block_order.first().copied())
        .ok_or_else(|| malformed("EH function has no laid-out block".to_string()))?;
    let mut resolved_call_sites = Vec::new();
    let mut cursor = 0u32;
    for cs in explicit {
        let start = cs.start_offset;
        let end = start + cs.length;
        if start < cursor {
            return Err(malformed(format!(
                "protected call ranges overlap at byte {start}"
            )));
        }
        if start > cursor {
            resolved_call_sites.push(EhCallSiteEntry {
                call_block: filler_block,
                start_offset: cursor,
                length: start - cursor,
                landing_pad_block: None,
            });
        }
        resolved_call_sites.push(cs);
        cursor = end;
    }
    if cursor < code_len {
        resolved_call_sites.push(EhCallSiteEntry {
            call_block: filler_block,
            start_offset: cursor,
            length: code_len - cursor,
            landing_pad_block: None,
        });
    }
    func.eh_metadata.call_sites = resolved_call_sites;
    Ok(())
}

/// Generate LSDA bytes from a function's exception handling metadata.
///
/// Bridges `trust_cg_ir::ExceptionHandlingMetadata` to the codegen-level
/// `exception_handling::ExceptionTable` and serializes it to the binary
/// LSDA format. Returns `None` if the function has no EH info.
///
/// This must be called after code layout (so block byte offsets are known)
/// and before Mach-O emission (so the LSDA bytes can be placed in the
/// `__gcc_except_tab` section).
pub fn generate_lsda_for_function(func: &IrMachFunction) -> Result<Option<Vec<u8>>, PipelineError> {
    let eh = &func.eh_metadata;
    if !eh.has_eh_info() {
        return Ok(None);
    }

    use crate::exception_handling::{LandingPadDesc, generate_lsda_from_pads};

    let personality = crate::exception_handling::required_personality_symbol(
        eh.personality.as_deref(),
    )
    .map_err(|error| PipelineError::MalformedAarch64Function {
        function: func.name.clone(),
        detail: format!("invalid exception-handling personality: {error}"),
    })?;

    // Convert IR-level landing pad entries to codegen-level descriptors while
    // retaining an exact block->offset authority for call-site references.
    // A duplicate block or stale reference must not silently become the LSDA
    // no-handler sentinel.
    let mut landing_pad_offset_by_block = HashMap::new();
    let mut landing_pad_descs = Vec::with_capacity(eh.landing_pads.len());
    for lp in &eh.landing_pads {
        if landing_pad_offset_by_block
            .insert(lp.block, lp.offset)
            .is_some()
        {
            return Err(PipelineError::MalformedAarch64Function {
                function: func.name.clone(),
                detail: format!(
                    "invalid resolved exception table: duplicate landing-pad block {:?}",
                    lp.block
                ),
            });
        }
        landing_pad_descs.push(LandingPadDesc {
            landing_pad_offset: lp.offset,
            catch_type_indices: lp.catch_type_indices.clone(),
            is_cleanup: lp.is_cleanup,
        });
    }

    // Convert call site entries to (start, length, lp_offset) tuples.
    let mut call_site_ranges = Vec::with_capacity(eh.call_sites.len());
    for (index, cs) in eh.call_sites.iter().enumerate() {
        let lp_offset = match cs.landing_pad_block {
            Some(block) => landing_pad_offset_by_block.get(&block).copied().ok_or_else(|| {
                PipelineError::MalformedAarch64Function {
                    function: func.name.clone(),
                    detail: format!(
                        "invalid resolved exception table: call-site {index} references missing landing-pad block {block:?}"
                    ),
                }
            })?,
            None => 0,
        };
        call_site_ranges.push((cs.start_offset, cs.length, lp_offset));
    }

    let lsda_bytes = generate_lsda_from_pads(personality, &landing_pad_descs, &call_site_ranges)
        .map_err(|error| PipelineError::MalformedAarch64Function {
            function: func.name.clone(),
            detail: format!("invalid resolved exception table: {error}"),
        })?;
    Ok(Some(lsda_bytes))
}

// ---------------------------------------------------------------------------
// Pipeline — main entry point
// ---------------------------------------------------------------------------

/// The Trust Codegen compilation pipeline.
///
/// Orchestrates all phases from trust_ir input through to Mach-O .o emission.
pub struct Pipeline {
    pub config: PipelineConfig,
    profile_use: Option<trust_cg_opt::pgo::ProfData>,
    /// AOT PGO profile-generate sink. When `Some`, `prepare_function_*`
    /// injects per-block counter increments (against the module-level
    /// `__tcg_pgo_counters` array) between verification and register
    /// allocation, and records every `CounterSite` here. `None` (the default)
    /// leaves the pipeline byte-identical to a build without this feature.
    profile_generate_sink: Option<Arc<std::sync::Mutex<trust_cg_opt::pgo::CounterMap>>>,
    certified_pass_execution: bool,
    #[cfg_attr(not(feature = "verify"), allow(dead_code))]
    cegis_cache: Arc<dyn trust_cg_opt::CacheBackend>,
    #[cfg(not(feature = "verify"))]
    cegis_warning_emitted: AtomicBool,
}

fn trust_cg_pass_disabled(name: &str) -> bool {
    crate::env_lock::var("TRUST_CG_DISABLE_PASSES")
        .unwrap_or_default()
        .split(',')
        .any(|disabled| disabled.trim() == name)
}

/// Opt-in counterpart to [`trust_cg_pass_disabled`]: true iff `name` appears in
/// `TRUST_CG_ENABLE_PASSES`. Used for sound-but-default-off transforms.
fn trust_cg_pass_enabled(name: &str) -> bool {
    std::env::var("TRUST_CG_ENABLE_PASSES")
        .unwrap_or_default()
        .split(',')
        .any(|enabled| enabled.trim() == name)
}

fn trust_cg_time_pipeline_enabled() -> bool {
    // Cached once: this is polled ~10x per function (per phase). Reading the env
    // a single time turns the default (timing OFF) hot path into a cheap atomic
    // load instead of two env syscalls per phase per function.
    use std::sync::OnceLock;
    static ENABLED: OnceLock<bool> = OnceLock::new();
    *ENABLED.get_or_init(|| {
        std::env::var_os("TRUST_CG_TIME_PIPELINE").is_some()
            || std::env::var_os("TRUST_CG_TIME_PASSES").is_some()
    })
}

fn ir_function_shape(func: &IrMachFunction) -> (usize, usize) {
    let blocks = func.block_order.len();
    let insts = func
        .block_order
        .iter()
        .map(|&block_id| func.block(block_id).insts.len())
        .sum();
    (blocks, insts)
}

fn dwarf_standard_type_index(ty: DebugBaseType) -> usize {
    match ty {
        DebugBaseType::I8 => 0,
        DebugBaseType::I16 => 1,
        DebugBaseType::I32 => 2,
        DebugBaseType::I64 | DebugBaseType::I128 => 3,
        DebugBaseType::F32 => 4,
        DebugBaseType::F64 => 5,
        DebugBaseType::Bool => 6,
        DebugBaseType::U8 => 7,
        DebugBaseType::U16 => 8,
        DebugBaseType::U32 => 9,
        DebugBaseType::U64 | DebugBaseType::U128 | DebugBaseType::Ptr => 10,
    }
}

fn debug_base_type_for_ir_type(ty: &trust_cg_ir::Type) -> DebugBaseType {
    match ty {
        trust_cg_ir::Type::I8 => DebugBaseType::I8,
        trust_cg_ir::Type::I16 => DebugBaseType::I16,
        trust_cg_ir::Type::I32 => DebugBaseType::I32,
        trust_cg_ir::Type::I64 | trust_cg_ir::Type::I128 => DebugBaseType::I64,
        // DWARF-v1's fixed base-type table has no vector DIE. This is a
        // debug-description-only 128-bit-width fallback; ABI, regalloc, and
        // lowering retain V128 through `lower_type_from_ir_type` below.
        trust_cg_ir::Type::V128 => DebugBaseType::I128,
        trust_cg_ir::Type::F32 => DebugBaseType::F32,
        trust_cg_ir::Type::F64 => DebugBaseType::F64,
        trust_cg_ir::Type::B1 => DebugBaseType::Bool,
        trust_cg_ir::Type::Ptr => DebugBaseType::Ptr,
        trust_cg_ir::Type::F16
        | trust_cg_ir::Type::Struct(_)
        | trust_cg_ir::Type::Array(_, _)
        | trust_cg_ir::Type::Enum { .. } => DebugBaseType::I64,
    }
}

fn dwarf_type_index_for_ir_type(ty: &trust_cg_ir::Type) -> usize {
    dwarf_standard_type_index(debug_base_type_for_ir_type(ty))
}

fn lower_type_from_ir_type(ty: &trust_cg_ir::Type) -> LowerType {
    match ty {
        trust_cg_ir::Type::I8 => LowerType::I8,
        trust_cg_ir::Type::I16 => LowerType::I16,
        trust_cg_ir::Type::I32 => LowerType::I32,
        trust_cg_ir::Type::I64 | trust_cg_ir::Type::Ptr => LowerType::I64,
        trust_cg_ir::Type::I128 => LowerType::I128,
        trust_cg_ir::Type::V128 => LowerType::V128,
        trust_cg_ir::Type::F16 => LowerType::F16,
        trust_cg_ir::Type::F32 => LowerType::F32,
        trust_cg_ir::Type::F64 => LowerType::F64,
        trust_cg_ir::Type::B1 => LowerType::B1,
        trust_cg_ir::Type::Struct(fields) => {
            LowerType::Struct(fields.iter().map(lower_type_from_ir_type).collect())
        }
        trust_cg_ir::Type::Array(elem, count) => {
            LowerType::Array(Box::new(lower_type_from_ir_type(elem)), *count)
        }
        trust_cg_ir::Type::Enum {
            tag_width,
            variants,
        } => LowerType::Enum {
            tag_width: *tag_width,
            variants: variants
                .iter()
                .map(|fields| fields.iter().map(lower_type_from_ir_type).collect())
                .collect(),
        },
    }
}

fn dwarf_register_number(preg: PReg) -> u64 {
    let preg = match preg_class(preg) {
        RegClass::Gpr32 | RegClass::System => gpr32_to_gpr64(preg).unwrap_or(preg),
        _ => preg,
    };
    u64::from(preg.encoding())
}

fn dwarf_param_location(
    loc: &ArgLocation,
    frame_layout: Option<&crate::frame::FrameLayout>,
) -> crate::dwarf_info::VariableLocation {
    match loc {
        ArgLocation::Reg(preg) | ArgLocation::Indirect { ptr_reg: preg } => {
            crate::dwarf_info::VariableLocation::Register(dwarf_register_number(*preg))
        }
        ArgLocation::RegSequence(regs) => regs
            .first()
            .map_or(crate::dwarf_info::VariableLocation::Register(0), |preg| {
                crate::dwarf_info::VariableLocation::Register(dwarf_register_number(*preg))
            }),
        ArgLocation::RegPair(lo_preg, _) => {
            crate::dwarf_info::VariableLocation::Register(dwarf_register_number(*lo_preg))
        }
        ArgLocation::Stack { offset, .. } => {
            let csa_size = frame_layout
                .map(|layout| i64::from(layout.callee_saved_area_size))
                .unwrap_or(0);
            crate::dwarf_info::VariableLocation::FrameOffset(csa_size + *offset)
        }
    }
}

fn operand_aliases_dwarf_register(operand: &IrOperand, dwarf_reg: u64) -> bool {
    let IrOperand::PReg(preg) = operand else {
        return false;
    };

    if matches!(*preg, XZR | WZR) {
        return false;
    }

    dwarf_register_number(*preg) == dwarf_reg
}

fn call_clobbers_dwarf_register(dwarf_reg: u64) -> bool {
    trust_cg_regalloc::aarch64_caller_saved_regs()
        .into_iter()
        .any(|preg| dwarf_register_number(preg) == dwarf_reg)
}

fn inst_clobbers_dwarf_register(inst: &IrMachInst, dwarf_reg: u64) -> bool {
    if inst.flags.contains(trust_cg_ir::inst::InstFlags::IS_CALL)
        && call_clobbers_dwarf_register(dwarf_reg)
    {
        return true;
    }

    let (def_positions, _) = classify_operand_positions(inst);
    def_positions.iter().any(|&pos| {
        inst.operands
            .get(pos)
            .is_some_and(|operand| operand_aliases_dwarf_register(operand, dwarf_reg))
    })
}

fn encoded_instruction_offsets(ir_func: &IrMachFunction) -> Vec<(InstId, u32)> {
    let mut offsets = Vec::new();
    let mut offset = 0u32;
    for block_id in &ir_func.block_order {
        let block = &ir_func.blocks[block_id.0 as usize];
        for &inst_id in &block.insts {
            let inst = &ir_func.insts[inst_id.0 as usize];
            if inst.is_pseudo() {
                continue;
            }
            offsets.push((inst_id, offset));
            offset = offset.saturating_add(4);
        }
    }
    offsets
}

fn entry_register_range_size(
    ir_func: &IrMachFunction,
    dwarf_reg: u64,
    code_size: u32,
) -> Option<u32> {
    if code_size == 0 {
        return None;
    }

    let mut body_size = 0u32;
    for (inst_id, offset) in encoded_instruction_offsets(ir_func) {
        body_size = offset.saturating_add(4);
        let inst = &ir_func.insts[inst_id.0 as usize];
        if inst_clobbers_dwarf_register(inst, dwarf_reg) {
            return (offset > 0).then_some(offset.min(code_size));
        }
    }

    let size = body_size.min(code_size);
    (size > 0).then_some(size)
}

fn bounded_dwarf_param_location(
    ir_func: &IrMachFunction,
    loc: &ArgLocation,
    frame_layout: Option<&crate::frame::FrameLayout>,
    code_size: u32,
) -> crate::dwarf_info::VariableLocation {
    match loc {
        ArgLocation::Reg(preg) => {
            let dwarf_reg = dwarf_register_number(*preg);
            let Some(size) = entry_register_range_size(ir_func, dwarf_reg, code_size) else {
                return crate::dwarf_info::VariableLocation::LocationList(Vec::new());
            };
            crate::dwarf_info::VariableLocation::location_list(
                0,
                size,
                crate::dwarf_info::VariableLocation::Register(dwarf_reg),
            )
        }
        _ => dwarf_param_location(loc, frame_layout),
    }
}

fn alloca_debug_stack_slot_from_provenance_var(
    ir_func: &IrMachFunction,
    var_id: TrustIrVarId,
) -> Option<StackSlotId> {
    if var_id.0 & !DEBUG_PROVENANCE_VAR_INDEX_MASK != ALLOCA_DEBUG_PROVENANCE_VAR_TAG {
        return None;
    }
    let slot = var_id.0 & DEBUG_PROVENANCE_VAR_INDEX_MASK;
    let slot_id = StackSlotId(slot);
    ir_func
        .stack_slots
        .get(slot_id.0 as usize)
        .and_then(|stack_slot| stack_slot.fixed_size())
        .map(|_| slot_id)
}

fn const_value_debug_trust_ir_origin_from_provenance_var(
    var_id: TrustIrVarId,
) -> Option<trust_cg_ir::TrustIrInstId> {
    if var_id.0 & !DEBUG_PROVENANCE_VAR_INDEX_MASK != CONST_VALUE_DEBUG_PROVENANCE_VAR_TAG {
        return None;
    }
    Some(trust_cg_ir::TrustIrInstId(
        var_id.0 & DEBUG_PROVENANCE_VAR_INDEX_MASK,
    ))
}

fn value_debug_trust_ir_origin_from_provenance_var(
    var_id: TrustIrVarId,
) -> Option<trust_cg_ir::TrustIrInstId> {
    if var_id.0 & !DEBUG_PROVENANCE_VAR_INDEX_MASK != VALUE_DEBUG_PROVENANCE_VAR_TAG {
        return None;
    }
    Some(trust_cg_ir::TrustIrInstId(
        var_id.0 & DEBUG_PROVENANCE_VAR_INDEX_MASK,
    ))
}

fn debug_value_binding_vregs(
    input: &trust_cg_lower::Function,
    value_map: Option<
        &HashMap<trust_cg_lower::instructions::Value, trust_cg_lower::isel::ISelOperand>,
    >,
) -> BTreeMap<TrustIrVarId, VReg> {
    let Some(value_map) = value_map else {
        return BTreeMap::new();
    };

    input
        .debug_value_bindings
        .iter()
        .filter_map(|binding| match value_map.get(&binding.value) {
            Some(trust_cg_lower::isel::ISelOperand::VReg(vreg)) => Some((binding.var_id, *vreg)),
            _ => None,
        })
        .collect()
}

fn debug_base_type_bit_width(ty: DebugBaseType) -> u16 {
    match ty {
        DebugBaseType::Bool => 1,
        DebugBaseType::I8 | DebugBaseType::U8 => 8,
        DebugBaseType::I16 | DebugBaseType::U16 => 16,
        DebugBaseType::I32 | DebugBaseType::U32 | DebugBaseType::F32 => 32,
        DebugBaseType::I64 | DebugBaseType::U64 | DebugBaseType::F64 | DebugBaseType::Ptr => 64,
        DebugBaseType::I128 | DebugBaseType::U128 => 128,
    }
}

fn const_debug_value_mask(bit_width: u16) -> Option<u128> {
    match bit_width {
        0 => None,
        width if width <= 64 => Some((1u128 << width) - 1),
        _ => None,
    }
}

fn imm16_operand(inst: &IrMachInst, index: usize) -> Option<u128> {
    let imm = inst.operands.get(index)?.as_imm()?;
    (0..=0xffff).contains(&imm).then_some(imm as u128)
}

fn mov_shift_operand(inst: &IrMachInst) -> Option<u32> {
    let shift = match inst.operands.as_slice() {
        [_, _] => 0,
        [_, _, IrOperand::Imm(shift)] => *shift,
        _ => return None,
    };
    matches!(shift, 0 | 16 | 32 | 48).then_some(shift as u32)
}

fn inst_position(ir_func: &IrMachFunction, inst_id: InstId) -> Option<usize> {
    let mut position = 0usize;
    for block_id in &ir_func.block_order {
        let block = ir_func.blocks.get(block_id.0 as usize)?;
        for &candidate in &block.insts {
            if candidate == inst_id {
                return Some(position);
            }
            position = position.saturating_add(1);
        }
    }
    None
}

fn const_value_from_materialization_chain(
    ir_func: &IrMachFunction,
    origin_insts: &[InstId],
    bit_width: u16,
) -> Option<(InstId, u128)> {
    let mask = const_debug_value_mask(bit_width)?;
    let mut ordered: Vec<(usize, InstId)> = origin_insts
        .iter()
        .copied()
        .filter_map(|inst_id| inst_position(ir_func, inst_id).map(|position| (position, inst_id)))
        .collect();
    ordered.sort_by_key(|(position, _)| *position);

    for (seed_position, seed_id) in ordered.iter().copied() {
        let seed = ir_func.insts.get(seed_id.0 as usize)?;
        let Some(dst) = seed.operands.first() else {
            continue;
        };
        let mut value = match seed.opcode {
            IrOpcode::MovI => {
                if seed.operands.len() != 2 {
                    return None;
                }
                let imm = u64::try_from(seed.operands.get(1)?.as_imm()?).ok()?;
                u128::from(imm) & mask
            }
            IrOpcode::Movz => {
                let imm = imm16_operand(seed, 1)?;
                let shift = mov_shift_operand(seed)?;
                if shift != 0 || shift >= u32::from(bit_width) {
                    return None;
                }
                (imm << shift) & mask
            }
            IrOpcode::Movn => {
                let imm = imm16_operand(seed, 1)?;
                let shift = mov_shift_operand(seed)?;
                if shift != 0 || shift >= u32::from(bit_width) {
                    return None;
                }
                (!(imm << shift)) & mask
            }
            _ => continue,
        };

        for (position, inst_id) in ordered.iter().copied() {
            if position <= seed_position {
                continue;
            }
            let inst = ir_func.insts.get(inst_id.0 as usize)?;
            if inst.opcode != IrOpcode::Movk || inst.operands.first() != Some(dst) {
                continue;
            }
            let imm = imm16_operand(inst, 1)?;
            let shift = mov_shift_operand(inst)?;
            if shift >= u32::from(bit_width) {
                return None;
            }
            let field_mask = (0xffffu128 << shift) & mask;
            value = (value & !field_mask) | ((imm << shift) & mask);
        }

        return Some((seed_id, value & mask));
    }

    None
}

fn emitted_function_inst_range(ir_func: &IrMachFunction) -> Option<(InstId, InstId)> {
    let start = ir_func.block_order.iter().find_map(|block_id| {
        ir_func
            .blocks
            .get(block_id.0 as usize)
            .and_then(|block| block.insts.first().copied())
    })?;
    let end = InstId(u32::try_from(ir_func.insts.len()).unwrap_or(u32::MAX));
    (start < end).then_some((start, end))
}

fn seed_stack_alloca_debug_provenance(
    ir_func: &IrMachFunction,
    provenance: &mut Option<trust_cg_ir::ProvenanceMap>,
) -> Result<(), PipelineError> {
    let Some((start, end)) = emitted_function_inst_range(ir_func) else {
        return Ok(());
    };

    let declarations: Vec<_> = ir_func
        .debug_meta
        .local_variables
        .iter()
        .filter_map(|local| {
            let DebugVariableStorage::ProvenanceVar(var_id) = local.storage else {
                return None;
            };
            let slot = alloca_debug_stack_slot_from_provenance_var(ir_func, var_id)?;
            let already_declared = provenance
                .as_ref()
                .is_some_and(|map| !map.var_live_ranges(var_id).is_empty());
            (!already_declared).then_some((
                var_id,
                VarLocation::new(var_id, start, end, LocationExpr::Stack(slot)),
            ))
        })
        .collect();

    if declarations.is_empty() {
        return Ok(());
    }

    let provenance = provenance.get_or_insert_with(trust_cg_ir::ProvenanceMap::new);
    for (var_id, loc) in declarations {
        if provenance.var_live_ranges(var_id).is_empty() {
            declare_debug_var(provenance, var_id, loc)?;
        }
    }
    Ok(())
}

fn declare_debug_var(
    provenance: &mut trust_cg_ir::ProvenanceMap,
    var_id: TrustIrVarId,
    loc: VarLocation,
) -> Result<(), PipelineError> {
    provenance.declare_var(var_id, loc).map_err(|err| {
        PipelineError::DebugProvenance(format!(
            "failed to declare debug variable {var_id:?}: {err:?}"
        ))
    })
}

fn register_debug_value_preg(snapshot: &RegAllocDebugSnapshot, inst_id: InstId) -> Option<PReg> {
    match snapshot.defs.get(&inst_id).copied()? {
        RegAllocDebugDef::VReg(vreg) => {
            if snapshot.spilled_vregs.contains(&vreg) {
                return None;
            }
            allocated_preg_for_vreg(vreg, &snapshot.allocation)
        }
        RegAllocDebugDef::PReg(preg) => Some(preg),
    }
    .filter(|preg| *preg != XZR && *preg != WZR)
}

fn active_single_origin_inst(
    provenance: &trust_cg_ir::ProvenanceMap,
    snapshot: &RegAllocDebugSnapshot,
    origin: trust_cg_ir::TrustIrInstId,
) -> Option<InstId> {
    let origin_insts = provenance.get_mach_insts(origin)?;
    let [origin_inst] = origin_insts else {
        return None;
    };
    if !provenance
        .get_entry(*origin_inst)
        .is_some_and(|entry| entry.is_active())
    {
        return None;
    }
    snapshot
        .inst_map
        .get(origin_inst.0 as usize)
        .copied()
        .flatten()
}

fn active_origin_insts(
    provenance: &trust_cg_ir::ProvenanceMap,
    snapshot: &RegAllocDebugSnapshot,
    origin: trust_cg_ir::TrustIrInstId,
) -> Vec<InstId> {
    let Some(origin_insts) = provenance.get_mach_insts(origin) else {
        return Vec::new();
    };

    origin_insts
        .iter()
        .copied()
        .filter(|inst| {
            provenance
                .get_entry(*inst)
                .is_some_and(|entry| entry.is_active())
        })
        .filter_map(|inst| snapshot.inst_map.get(inst.0 as usize).copied().flatten())
        .collect()
}

fn function_end_inst(ir_func: &IrMachFunction) -> InstId {
    InstId(u32::try_from(ir_func.insts.len()).unwrap_or(u32::MAX))
}

fn next_layout_inst_or_end(ir_func: &IrMachFunction, inst_id: InstId) -> Option<InstId> {
    let mut seen_inst = false;
    for block_id in &ir_func.block_order {
        let block = ir_func.blocks.get(block_id.0 as usize)?;
        for &candidate in &block.insts {
            if seen_inst {
                return Some(candidate);
            }
            seen_inst = candidate == inst_id;
        }
    }
    seen_inst.then_some(function_end_inst(ir_func))
}

fn previous_non_pseudo_layout_inst(ir_func: &IrMachFunction, inst_id: InstId) -> Option<InstId> {
    let mut previous = None;
    for block_id in &ir_func.block_order {
        let block = ir_func.blocks.get(block_id.0 as usize)?;
        for &candidate in &block.insts {
            if candidate == inst_id {
                return previous;
            }
            if !ir_func.inst(candidate).is_pseudo() {
                previous = Some(candidate);
            }
        }
    }
    None
}

fn unique_spilled_vreg_for_slot(
    snapshot: &RegAllocDebugSnapshot,
    slot: StackSlotId,
) -> Option<VReg> {
    let mut owner = None;
    for (&vreg, &candidate_slot) in &snapshot.spill_slots {
        if candidate_slot != slot {
            continue;
        }
        if owner.replace(vreg).is_some() {
            return None;
        }
    }
    owner
}

fn spilled_debug_value_slot(
    snapshot: &RegAllocDebugSnapshot,
    inst_id: InstId,
) -> Option<(VReg, StackSlotId)> {
    let RegAllocDebugDef::VReg(vreg) = snapshot.defs.get(&inst_id).copied()? else {
        return None;
    };
    spilled_debug_value_slot_for_vreg(snapshot, vreg)
}

fn spilled_debug_value_slot_for_vreg(
    snapshot: &RegAllocDebugSnapshot,
    vreg: VReg,
) -> Option<(VReg, StackSlotId)> {
    if !matches!(vreg.class, RegClass::Gpr32 | RegClass::Gpr64) {
        return None;
    }
    if !snapshot.spilled_vregs.contains(&vreg)
        || allocated_preg_for_vreg(vreg, &snapshot.allocation).is_some()
    {
        return None;
    }
    let slot = snapshot.spill_slots.get(&vreg).copied()?;
    (unique_spilled_vreg_for_slot(snapshot, slot)? == vreg).then_some((vreg, slot))
}

fn materialized_spill_store_after_origin(
    ir_func: &IrMachFunction,
    snapshot: &RegAllocDebugSnapshot,
    vreg: VReg,
    slot: StackSlotId,
    origin_inst: InstId,
) -> Option<InstId> {
    let origin_position = inst_position(ir_func, origin_inst)?;
    snapshot
        .spill_stores
        .iter()
        .filter(|store| store.vreg == vreg && store.slot == slot)
        .filter_map(|store| {
            let position = inst_position(ir_func, store.inst)?;
            (position > origin_position).then_some((position, store.inst))
        })
        .min_by_key(|(position, _)| *position)
        .map(|(_, inst)| inst)
}

fn first_spill_store_to_slot_after(
    ir_func: &IrMachFunction,
    snapshot: &RegAllocDebugSnapshot,
    slot: StackSlotId,
    after_inst: InstId,
) -> Option<InstId> {
    let after_position = inst_position(ir_func, after_inst)?;
    snapshot
        .spill_stores
        .iter()
        .filter(|store| store.slot == slot && store.inst != after_inst)
        .filter_map(|store| {
            let position = inst_position(ir_func, store.inst)?;
            (position > after_position).then_some((position, store.inst))
        })
        .min_by_key(|(position, _)| *position)
        .map(|(_, inst)| inst)
}

fn first_materialized_spill_store(
    ir_func: &IrMachFunction,
    snapshot: &RegAllocDebugSnapshot,
    vreg: VReg,
    slot: StackSlotId,
) -> Option<InstId> {
    snapshot
        .spill_stores
        .iter()
        .filter(|store| store.vreg == vreg && store.slot == slot)
        .filter_map(|store| {
            inst_position(ir_func, store.inst).map(|position| (position, store.inst))
        })
        .min_by_key(|(position, _)| *position)
        .map(|(_, inst)| inst)
}

fn spill_debug_value_stack_range(
    ir_func: &IrMachFunction,
    snapshot: &RegAllocDebugSnapshot,
    origin_inst: InstId,
) -> Option<(InstId, InstId, InstId, StackSlotId)> {
    let (vreg, slot) = spilled_debug_value_slot(snapshot, origin_inst)?;
    spill_debug_value_stack_range_for_vreg(ir_func, snapshot, origin_inst, vreg, slot)
}

fn spill_debug_value_stack_range_for_vreg(
    ir_func: &IrMachFunction,
    snapshot: &RegAllocDebugSnapshot,
    origin_inst: InstId,
    vreg: VReg,
    slot: StackSlotId,
) -> Option<(InstId, InstId, InstId, StackSlotId)> {
    if ir_func.block_order.len() != 1 {
        return None;
    }
    let store = materialized_spill_store_after_origin(ir_func, snapshot, vreg, slot, origin_inst)?;
    let start = next_layout_inst_or_end(ir_func, store)?;
    let materializing_store = previous_non_pseudo_layout_inst(ir_func, start)?;
    let end = first_spill_store_to_slot_after(ir_func, snapshot, slot, store)
        .unwrap_or_else(|| function_end_inst(ir_func));
    register_debug_value_position_range(ir_func, start, end)?;
    Some((materializing_store, start, end, slot))
}

fn bound_spill_debug_value_stack_range(
    ir_func: &IrMachFunction,
    snapshot: &RegAllocDebugSnapshot,
    vreg: VReg,
    slot: StackSlotId,
) -> Option<(InstId, InstId, InstId, StackSlotId)> {
    if ir_func.block_order.len() != 1 {
        return None;
    }
    let store = first_materialized_spill_store(ir_func, snapshot, vreg, slot)?;
    let start = next_layout_inst_or_end(ir_func, store)?;
    let materializing_store = previous_non_pseudo_layout_inst(ir_func, start)?;
    let end = first_spill_store_to_slot_after(ir_func, snapshot, slot, store)
        .unwrap_or_else(|| function_end_inst(ir_func));
    register_debug_value_position_range(ir_func, start, end)?;
    Some((materializing_store, start, end, slot))
}

fn inst_defines_overlapping_preg(inst: &IrMachInst, preg: PReg) -> bool {
    let (def_positions, _) = classify_operand_positions(inst);
    def_positions.iter().any(|&pos| {
        matches!(
            inst.operands.get(pos),
            Some(IrOperand::PReg(def)) if regs_overlap(*def, preg)
        )
    }) || inst
        .implicit_defs
        .iter()
        .any(|&def| regs_overlap(def, preg))
}

fn register_debug_value_end(ir_func: &IrMachFunction, start: InstId, preg: PReg) -> Option<InstId> {
    if ir_func.block_order.len() != 1 {
        return None;
    }

    let mut seen_start = false;
    for &block_id in &ir_func.block_order {
        let block = ir_func.blocks.get(block_id.0 as usize)?;
        for &inst_id in &block.insts {
            if !seen_start {
                seen_start = inst_id == start;
                continue;
            }
            let inst = ir_func.insts.get(inst_id.0 as usize)?;
            if !inst.is_pseudo() && inst_defines_overlapping_preg(inst, preg) {
                return Some(inst_id);
            }
        }
    }

    seen_start.then_some(InstId(
        u32::try_from(ir_func.insts.len()).unwrap_or(u32::MAX),
    ))
}

fn register_debug_value_position_range(
    ir_func: &IrMachFunction,
    start: InstId,
    end: InstId,
) -> Option<(usize, usize)> {
    // `ProvenanceMap::declare_var` validates half-open ranges on the RAW
    // instruction IDs (`start < end` in arena-id order), while `start`/`end`
    // here are discovered in LAYOUT order. Post-RA layout can place an
    // early-arena-id instruction after a later one (e.g. a frame-address
    // materialization created during stack rewriting but appended late in
    // the block), so a range that is well-formed in layout positions can
    // still be inverted in raw IDs. Such a range is unrepresentable under
    // the provenance contract: drop it — the variable simply gets no DWARF
    // location, which is strictly better than `declare_var` fail-closing
    // the whole compilation with `InvalidRange`.
    if start >= end {
        return None;
    }
    let start_position = inst_position(ir_func, start)?;
    let end_position = if end.0 as usize >= ir_func.insts.len() {
        ir_func
            .block_order
            .iter()
            .filter_map(|block_id| ir_func.blocks.get(block_id.0 as usize))
            .map(|block| block.insts.len())
            .sum()
    } else {
        inst_position(ir_func, end)?
    };
    (start_position < end_position).then_some((start_position, end_position))
}

fn seed_spilled_value_debug_provenance(
    ir_func: &IrMachFunction,
    provenance: &mut Option<trust_cg_ir::ProvenanceMap>,
    snapshot: &RegAllocDebugSnapshot,
    debug_value_bindings: &BTreeMap<TrustIrVarId, VReg>,
) -> Result<(), PipelineError> {
    let Some(existing_provenance) = provenance.as_ref() else {
        return Ok(());
    };
    let declarations: Vec<_> = ir_func
        .debug_meta
        .local_variables
        .iter()
        .filter_map(|local| {
            if debug_base_type_bit_width(local.ty) > 64 {
                return None;
            }
            let DebugVariableStorage::ProvenanceVar(var_id) = local.storage else {
                return None;
            };
            let origin = value_debug_trust_ir_origin_from_provenance_var(var_id)?;
            if !existing_provenance.var_live_ranges(var_id).is_empty() {
                return None;
            }
            let mut ranges = Vec::new();
            let mut seen = BTreeSet::new();
            let active_origin_insts = active_origin_insts(existing_provenance, snapshot, origin);
            if let Some(bound_vreg) = debug_value_bindings.get(&var_id).copied()
                && matches!(bound_vreg.class, RegClass::Gpr32 | RegClass::Gpr64)
                && snapshot.spilled_vregs.contains(&bound_vreg)
                && allocated_preg_for_vreg(bound_vreg, &snapshot.allocation).is_none()
                && let Some(bound_slot) = snapshot.spill_slots.get(&bound_vreg).copied()
            {
                for origin_inst in &active_origin_insts {
                    let Some((store, start, end, slot)) = spill_debug_value_stack_range_for_vreg(
                        ir_func,
                        snapshot,
                        *origin_inst,
                        bound_vreg,
                        bound_slot,
                    ) else {
                        continue;
                    };
                    if seen.insert((start, end, slot)) {
                        ranges.push((
                            Some((*origin_inst, store)),
                            VarLocation::new(var_id, start, end, LocationExpr::Stack(slot)),
                        ));
                    }
                }
                if ranges.is_empty()
                    && let Some((store, start, end, slot)) = bound_spill_debug_value_stack_range(
                        ir_func, snapshot, bound_vreg, bound_slot,
                    )
                    && seen.insert((start, end, slot))
                {
                    let clone_edge = active_origin_insts
                        .first()
                        .copied()
                        .map(|origin_inst| (origin_inst, store));
                    ranges.push((
                        clone_edge,
                        VarLocation::new(var_id, start, end, LocationExpr::Stack(slot)),
                    ));
                }
            }
            if ranges.is_empty() {
                for origin_inst in active_origin_insts {
                    let Some((store, start, end, slot)) =
                        spill_debug_value_stack_range(ir_func, snapshot, origin_inst)
                    else {
                        continue;
                    };
                    if seen.insert((start, end, slot)) {
                        ranges.push((
                            Some((origin_inst, store)),
                            VarLocation::new(var_id, start, end, LocationExpr::Stack(slot)),
                        ));
                    }
                }
            }
            (!ranges.is_empty()).then_some((var_id, ranges))
        })
        .collect();

    if declarations.is_empty() {
        return Ok(());
    }

    let provenance = provenance.get_or_insert_with(trust_cg_ir::ProvenanceMap::new);
    for (var_id, ranges) in declarations {
        if provenance.var_live_ranges(var_id).is_empty() {
            for (clone_edge, loc) in ranges {
                if let Some((origin_inst, store)) = clone_edge {
                    provenance.record_clone(
                        origin_inst,
                        store,
                        trust_cg_ir::PassId::new("codegen-debug-spill-materialization"),
                    );
                }
                declare_debug_var(provenance, var_id, loc)?;
            }
        }
    }
    Ok(())
}

fn seed_register_value_debug_provenance(
    ir_func: &IrMachFunction,
    provenance: &mut Option<trust_cg_ir::ProvenanceMap>,
    snapshot: &RegAllocDebugSnapshot,
) -> Result<(), PipelineError> {
    let Some(existing_provenance) = provenance.as_ref() else {
        return Ok(());
    };
    let declarations: Vec<_> = ir_func
        .debug_meta
        .local_variables
        .iter()
        .filter_map(|local| {
            if debug_base_type_bit_width(local.ty) > 64 {
                return None;
            }
            let DebugVariableStorage::ProvenanceVar(var_id) = local.storage else {
                return None;
            };
            let origin = value_debug_trust_ir_origin_from_provenance_var(var_id)?;
            if !existing_provenance.var_live_ranges(var_id).is_empty() {
                return None;
            }
            let start = active_single_origin_inst(existing_provenance, snapshot, origin)?;
            let inst = ir_func.insts.get(start.0 as usize)?;
            if inst.is_pseudo() {
                return None;
            }
            let preg = register_debug_value_preg(snapshot, start)?;
            let end = register_debug_value_end(ir_func, start, preg)?;
            register_debug_value_position_range(ir_func, start, end)?;
            Some((
                var_id,
                VarLocation::new(var_id, start, end, LocationExpr::Reg(preg)),
            ))
        })
        .collect();

    if declarations.is_empty() {
        return Ok(());
    }

    let provenance = provenance.get_or_insert_with(trust_cg_ir::ProvenanceMap::new);
    for (var_id, loc) in declarations {
        if provenance.var_live_ranges(var_id).is_empty() {
            declare_debug_var(provenance, var_id, loc)?;
        }
    }
    Ok(())
}

fn seed_constant_value_debug_provenance(
    ir_func: &IrMachFunction,
    provenance: &mut Option<trust_cg_ir::ProvenanceMap>,
) -> Result<(), PipelineError> {
    let Some(existing_provenance) = provenance.as_ref() else {
        return Ok(());
    };
    let function_end = InstId(u32::try_from(ir_func.insts.len()).unwrap_or(u32::MAX));
    let declarations: Vec<_> = ir_func
        .debug_meta
        .local_variables
        .iter()
        .filter_map(|local| {
            let DebugVariableStorage::ProvenanceVar(var_id) = local.storage else {
                return None;
            };
            let origin = const_value_debug_trust_ir_origin_from_provenance_var(var_id)?;
            if !existing_provenance.var_live_ranges(var_id).is_empty() {
                return None;
            }
            let bit_width = debug_base_type_bit_width(local.ty);
            let (start, value) = const_value_from_materialization_chain(
                ir_func,
                existing_provenance.get_mach_insts(origin)?,
                bit_width,
            )?;
            (start < function_end).then_some((
                var_id,
                VarLocation::new(
                    var_id,
                    start,
                    function_end,
                    LocationExpr::Const { value, bit_width },
                ),
            ))
        })
        .collect();

    if declarations.is_empty() {
        return Ok(());
    }

    let provenance = provenance.get_or_insert_with(trust_cg_ir::ProvenanceMap::new);
    for (var_id, loc) in declarations {
        if provenance.var_live_ranges(var_id).is_empty() {
            declare_debug_var(provenance, var_id, loc)?;
        }
    }
    Ok(())
}

fn provenance_debug_variable_location(
    adapter: Option<&crate::debug_provenance::DebugProvenanceAdapter<'_>>,
    var_id: trust_cg_ir::provenance::TrustIrVarId,
) -> crate::dwarf_info::VariableLocation {
    let entries = adapter
        .map(|adapter| adapter.location_list_entries(var_id))
        .unwrap_or_default();

    crate::dwarf_info::VariableLocation::LocationList(entries)
}

fn build_debug_variables(
    ir_func: &IrMachFunction,
    debug_meta: &trust_cg_ir::function::FunctionDebugMeta,
    frame_layout: Option<&crate::frame::FrameLayout>,
    code_size: u32,
    provenance: Option<&trust_cg_ir::ProvenanceMap>,
) -> Vec<crate::dwarf_info::VariableDebugInfo> {
    let stack_slot_offsets = frame_layout
        .map(|layout| crate::frame::stack_slot_frame_offsets(ir_func, layout))
        .unwrap_or_default();
    let debug_provenance_locals = debug_meta.local_variables.iter().filter_map(|local| {
        let DebugVariableStorage::ProvenanceVar(var_id) = local.storage else {
            return None;
        };
        Some(crate::debug_provenance::DebugProvenanceLocal::new(
            var_id,
            debug_base_type_bit_width(local.ty),
            alloca_debug_stack_slot_from_provenance_var(ir_func, var_id),
        ))
    });
    let debug_provenance_adapter = provenance.map(|provenance| {
        crate::debug_provenance::DebugProvenanceAdapter::new(
            ir_func,
            provenance,
            &stack_slot_offsets,
            code_size,
            debug_provenance_locals,
        )
    });
    let mut claimed_source_slots = BTreeSet::new();
    for local in &debug_meta.local_variables {
        if let DebugVariableStorage::ProvenanceVar(var_id) = local.storage
            && let Some(slot) = alloca_debug_stack_slot_from_provenance_var(ir_func, var_id)
        {
            claimed_source_slots.insert(slot.0 as usize);
        }
    }
    let mut variables: Vec<crate::dwarf_info::VariableDebugInfo> = debug_meta
        .local_variables
        .iter()
        .filter_map(|local| match local.storage {
            DebugVariableStorage::StackSlot(slot) => {
                let slot_idx = slot as usize;
                let ir_slot = ir_func.stack_slots.get(slot_idx)?;
                ir_slot.fixed_size()?;
                let frame_offset = stack_slot_offsets.get(slot_idx).copied().flatten()?;
                claimed_source_slots.insert(slot_idx);
                let frame_location =
                    crate::dwarf_info::VariableLocation::FrameOffset(i64::from(frame_offset));
                Some(crate::dwarf_info::VariableDebugInfo {
                    name: local.name.clone(),
                    type_index: dwarf_standard_type_index(local.ty),
                    location: crate::dwarf_info::VariableLocation::location_list(
                        0,
                        code_size,
                        frame_location,
                    ),
                })
            }
            DebugVariableStorage::ConstantInt(value) => {
                Some(crate::dwarf_info::VariableDebugInfo {
                    name: local.name.clone(),
                    type_index: dwarf_standard_type_index(local.ty),
                    location: crate::dwarf_info::VariableLocation::ConstantInt(value),
                })
            }
            DebugVariableStorage::ProvenanceVar(var_id) => {
                Some(crate::dwarf_info::VariableDebugInfo {
                    name: local.name.clone(),
                    type_index: dwarf_standard_type_index(local.ty),
                    location: provenance_debug_variable_location(
                        debug_provenance_adapter.as_ref(),
                        var_id,
                    ),
                })
            }
        })
        .collect();

    variables.extend(
        ir_func
            .stack_slots
            .iter()
            .enumerate()
            .filter_map(|(i, slot)| {
                if claimed_source_slots.contains(&i) {
                    return None;
                }
                let size = slot.fixed_size()?;
                let frame_offset = stack_slot_offsets.get(i).copied().flatten()?;
                if size == 0 {
                    return None;
                }
                // Map slot size to a base type index.
                let type_index = match size {
                    1 => 0, // i8
                    2 => 1, // i16
                    4 => 2, // i32
                    8 => 3, // i64
                    _ => 3, // default i64
                };
                Some(crate::dwarf_info::VariableDebugInfo {
                    name: format!("local_{}", i),
                    type_index,
                    location: crate::dwarf_info::VariableLocation::FrameOffset(i64::from(
                        frame_offset,
                    )),
                })
            }),
    );

    variables
}

fn log_pipeline_phase_start(func: &IrMachFunction, phase: &str) -> Option<Instant> {
    if !trust_cg_time_pipeline_enabled() {
        return None;
    }
    let (blocks, insts) = ir_function_shape(func);
    eprintln!(
        "[trust-cg-time-pipeline] start func={} phase={} blocks={} insts={}",
        func.name, phase, blocks, insts
    );
    Some(Instant::now())
}

fn log_pipeline_phase_end(func: &IrMachFunction, phase: &str, start: Option<Instant>) {
    let Some(start) = start else {
        return;
    };
    let (blocks, insts) = ir_function_shape(func);
    eprintln!(
        "[trust-cg-time-pipeline] end func={} phase={} elapsed_us={} blocks={} insts={}",
        func.name,
        phase,
        start.elapsed().as_micros(),
        blocks,
        insts
    );
}

impl Pipeline {
    /// Create a new pipeline with the given configuration.
    pub fn new(config: PipelineConfig) -> Self {
        Self {
            config,
            profile_use: None,
            profile_generate_sink: None,
            certified_pass_execution: false,
            #[cfg(feature = "verify")]
            cegis_cache: trust_cg_verify::SharedCegisCache::default_arc(),
            #[cfg(not(feature = "verify"))]
            cegis_cache: Arc::new(trust_cg_opt::InMemoryCache::new()),
            #[cfg(not(feature = "verify"))]
            cegis_warning_emitted: AtomicBool::new(false),
        }
    }

    /// Report what proof evidence this pipeline configuration actually
    /// produces, and what it relies on rather than checks.
    ///
    /// This is the honest answer for the fast JIT route, which does not build
    /// a compile-service artifact and therefore has nowhere else to carry an
    /// evidence field. A pipeline configured with `verify: false` and
    /// [`DispatchVerifyMode::Off`] — the flagship consumer's configuration —
    /// reports
    /// [`ProofEvidenceVerdict::MissingEvidence`](crate::jit_contract::ProofEvidenceVerdict::MissingEvidence)
    /// at [`EvidenceStrength::NotRun`](crate::jit_contract::EvidenceStrength::NotRun),
    /// so "nothing ran" is a fact the consumer can read rather than an absence
    /// it has to infer.
    ///
    /// Reporting only: calling this runs no verifier and changes no behaviour.
    pub fn proof_evidence(&self) -> crate::jit_contract::ProofEvidenceSummary {
        crate::proof_evidence::route_evidence(
            crate::proof_evidence::ROUTE_EVIDENCE_VERIFIER,
            self.route_facts(),
            &crate::proof_evidence::evidence_environment(),
        )
    }

    /// What this pipeline's configuration actually runs.
    pub fn route_facts(&self) -> crate::proof_evidence::RouteFacts {
        crate::proof_evidence::RouteFacts {
            instruction_verification_ran: self.config.verify,
            dispatch_verification_ran: self.config.verify_dispatch != DispatchVerifyMode::Off,
            // The pipeline emits certificates only when the function verifier
            // runs; there is no separate certificate knob on this route.
            proof_certificates_emitted: self.config.verify,
            evidence_report_present: false,
            manifest_pin_accepted: false,
        }
    }

    /// Attach a decoded `.profdata` artifact for profile-use mode.
    pub fn with_profile_use(mut self, profile: trust_cg_opt::pgo::ProfData) -> Self {
        self.profile_use = Some(profile);
        self
    }

    /// Attach an AOT PGO counter-site sink, enabling profile-generate mode:
    /// every prepared function gets one counter increment per basic block
    /// (indexing the module-level `__tcg_pgo_counters` u64 array), and the
    /// `(function, block_id, counter_index)` triples land in `sink` so the
    /// caller can emit the sites sidecar and size the counter array global.
    pub fn with_profile_generate_sink(
        mut self,
        sink: Arc<std::sync::Mutex<trust_cg_opt::pgo::CounterMap>>,
    ) -> Self {
        self.profile_generate_sink = Some(sink);
        self
    }

    /// Enable the non-default certified const-fold/DCE opt pass execution
    /// slice for this pipeline.
    pub fn with_certified_pass_execution(mut self) -> Self {
        self.certified_pass_execution = true;
        self
    }

    /// Create a pipeline with default O2 configuration.
    pub fn default_o2() -> Self {
        Self::new(PipelineConfig::default())
    }

    fn pass_disabled(&self, name: &str) -> bool {
        self.config
            .disabled_passes_override
            .as_deref()
            .map(|disabled| disabled.split(',').any(|disabled| disabled.trim() == name))
            .unwrap_or_else(|| trust_cg_pass_disabled(name))
    }

    /// Run the bounded fsym trust-ir preflight for one function.
    ///
    /// FAIL-CLOSED: if the scan reports a deref-coverage gap (a dropped
    /// dereference obligation — the #49 fail-open class), this returns
    /// `Err(PipelineError::FsymCoverageGap)` so the gap fails the compile,
    /// mirroring the CLI gate on `report.has_coverage_error()`. A coverage gap
    /// must not be swallowed as advisory metrics. (The verify-off branch returns
    /// a Skip summary and has no report, so it cannot have a coverage gap.)
    fn run_fsym_trust_ir_preflight(
        &self,
        module: &trust_ir::Module,
        trust_ir_func: &trust_ir::Function,
    ) -> Result<Option<FsymTrustIrPipelineSummary>, PipelineError> {
        if !self.config.enable_fsym_trust_ir_preflight {
            return Ok(None);
        }

        #[cfg(feature = "verify")]
        {
            let single_function_module = fsym_single_function_module(module, trust_ir_func);
            let report = trust_cg_verify::fsym_trust_ir::scan_module(&single_function_module);
            let has_coverage_error = report.has_coverage_error();
            let summary =
                fsym_trust_ir_summary_from_report(&module.name, &trust_ir_func.name, report);
            // Fail closed on a deref-coverage gap for THIS function. A
            // module-level coverage error that is not for this function would
            // not appear in `summary.coverage_errors`; in practice the scan is
            // single-function here, so the two coincide, but gate on the
            // function-scoped detail so the error message is precise.
            if has_coverage_error && summary.coverage_error_count > 0 {
                return Err(PipelineError::FsymCoverageGap(
                    summary.coverage_errors.join("; "),
                ));
            }
            // Defensive: if the report flagged a coverage error but none mapped
            // to this function name, still fail closed rather than swallow it.
            if has_coverage_error {
                return Err(PipelineError::FsymCoverageGap(format!(
                    "deref-coverage gap reported by fsym scan of function `{}`",
                    trust_ir_func.name
                )));
            }
            Ok(Some(summary))
        }

        #[cfg(not(feature = "verify"))]
        {
            Ok(Some(FsymTrustIrPipelineSummary {
                module_name: module.name.clone(),
                function_name: trust_ir_func.name.clone(),
                scanned: false,
                warning_count: 1,
                skipped: Some(FsymTrustIrPipelineSkip {
                    reason: "verify-feature-disabled".to_string(),
                    detail:
                        "bounded trust_ir fsym preflight requires trust-cg-codegen `verify` feature"
                            .to_string(),
                }),
                ..Default::default()
            }))
        }
    }

    #[cfg(not(feature = "verify"))]
    fn warn_cegis_superopt_ignored(&self) {
        if !self.cegis_warning_emitted.swap(true, Ordering::Relaxed) {
            eprintln!(
                "trust-cg: warning: --cegis-superopt=N ignored: binary built without `verify` feature"
            );
        }
    }

    #[cfg_attr(not(feature = "verify"), allow(dead_code))]
    fn cegis_opt_level(&self) -> u8 {
        match self.config.opt_level {
            OptLevel::O0 => 0,
            OptLevel::O1 => 1,
            OptLevel::O2 => 2,
            OptLevel::O3 => 3,
        }
    }

    /// Run the CEGIS superopt pass on a function when configured.
    ///
    /// Returns the per-run pass statistics when the pass actually executed.
    /// Returns `None` when the pass is disabled or unavailable.
    pub fn run_cegis_superopt(&self, func: &mut IrMachFunction) -> Option<CegisPassStats> {
        #[cfg(feature = "verify")]
        {
            use trust_cg_opt::pass_manager::MachinePass;

            let budget_sec = self.config.cegis_superopt_budget_sec?;
            if budget_sec == 0 {
                return None;
            }

            let mut pass =
                trust_cg_verify::CegisSuperoptPass::new(trust_cg_verify::CegisSuperoptConfig {
                    budget_sec,
                    per_query_ms: 5_000,
                    target_triple: self.config.target_triple.clone(),
                    cpu: String::new(),
                    features: Vec::new(),
                    opt_level: self.cegis_opt_level(),
                    cache: Some(self.cegis_cache.clone()),
                    trace: None,
                });
            let _ = pass.run(func);
            Some(pass.stats().clone())
        }

        #[cfg(not(feature = "verify"))]
        {
            let _ = func;
            if self.config.cegis_superopt_budget_sec.is_some() {
                self.warn_cegis_superopt_ignored();
            }
            None
        }
    }

    /// AArch64 fall-through branch-layout optimization (EXEC-SPEED).
    ///
    /// Runs at `-O2`/`-O3` immediately before [`resolve_branches`], the only
    /// point where `block_order` is final and consumed verbatim by the branch
    /// resolver and encoder. Reorders blocks so a loop body falls through from
    /// its header and elides unconditional branches to the layout-next block.
    /// Fail-closed on EH/jump-table/indirect-branch functions (see
    /// [`crate::layout::aarch64_layout_fallthrough_and_elide`]). Kill switch:
    /// `TRUST_CG_DISABLE_PASSES=branch_layout`.
    fn apply_aarch64_branch_layout(&self, func: &mut IrMachFunction) {
        if matches!(self.config.opt_level, OptLevel::O2 | OptLevel::O3)
            && !self.pass_disabled("branch_layout")
        {
            // Bottom-test loop rotation is DEFAULT-OFF. It is sound (see
            // `layout::rotate_top_tested_loops`) but measured *slower* than the
            // top-tested reorder+elide on the target reduction kernels: the
            // rotation puts the loop compare on the induction-variable critical
            // path, whereas the top-test uses the already-available value and
            // pays only a predicted-not-taken exit branch. Kept opt-in (like the
            // x86 branch-layout `fallthrough_rule`) via
            // `TRUST_CG_ENABLE_PASSES=branch_layout_rotate` for A/B experiments.
            let rotate = trust_cg_pass_enabled("branch_layout_rotate");
            crate::layout::aarch64_layout_fallthrough_and_elide(func, rotate);
            // Layout-independent branch-to-next elision. The reorder pass above
            // fails closed as a WHOLE on already-rotated loops (a conditional
            // back-edge) and on EH/jump-table functions, yet a rotated loop
            // still carries a redundant `b <next>` at its body→latch seam — a
            // taken branch to the very next instruction, present in EVERY
            // rotated scalar loop. This pure elision removes it WITHOUT any
            // reorder (sound on all those shapes; see
            // `layout::aarch64_elide_branch_to_next`). It is a no-op when the
            // reorder pass already ran and elided.
            crate::layout::aarch64_elide_branch_to_next(func);
        }
    }

    /// Re-derive final AArch64 stream structure after every post-RA rewrite.
    /// This is a correctness gate, so its production mode is unconditionally
    /// Enforce and any violation aborts before encoding.
    fn recheck_aarch64_post_regalloc(&self, func: &IrMachFunction) -> Result<(), PipelineError> {
        enforce_aarch64_post_regalloc_resolved(func)
    }

    /// Compile a trust_ir function through the full pipeline, producing target
    /// object bytes.
    ///
    /// This is the main entry point. It takes a `trust_cg_lower::Function` (trust_ir)
    /// and returns the bytes of a valid .o file for the configured target triple.
    pub fn compile_function(
        &self,
        input: &trust_cg_lower::Function,
    ) -> Result<Vec<u8>, PipelineError> {
        reject_unsupported_aarch64_object_format(&self.config.target_triple)?;
        // Phase 1: Instruction Selection (no proof context in single-function path)
        let (isel_func, value_map) = self.run_isel(input, None)?;
        let debug_value_bindings = debug_value_binding_vregs(input, value_map.as_ref());
        let mut provenance = provenance_from_isel_trust_ir_origins(&isel_func);
        let trust_ir_source_locs = trust_ir_source_locs_from_input(input);

        // Phase 2: Convert ISel output to shared IR (issue #73 consolidation:
        // conversion logic now lives in ISelFunction::to_ir_func()).
        let mut ir_func = isel_func.to_ir_func();
        ir_func.debug_meta = input.debug_meta.clone();
        ir_func.stack_protector = input.stack_protector;

        // Edge-connectivity check (non-fatal).
        //
        // This was originally `debug_assert!(total_succs > 0, ..)` but that
        // fired on legal trust_ir whose non-entry blocks all terminate with
        // `Return` (no `Br`/`CondBr` edges). After DCE such blocks are
        // harmless — register allocation, frame lowering, and encoding all
        // operate per-block and do not require inter-block connectivity.
        // Tripping the assert prevented the pipeline from being a total
        // function over valid trust_ir (#447: panic-fuzz totality). We keep the
        // shape of the check as a no-op sentinel for future debugging.
        #[cfg(debug_assertions)]
        {
            let has_branches = ir_func.blocks.len() > 1;
            if has_branches {
                let _total_succs: usize = ir_func.blocks.iter().map(|b| b.succs.len()).sum();
                let _total_preds: usize = ir_func.blocks.iter().map(|b| b.preds.len()).sum();
                // Tolerated: _total_succs == 0 or _total_preds == 0 is a legal
                // (if unusual) multi-block shape — see issue #447.
            }
        }

        // This standalone route has no exact Trust-IR obligation/replay binding.  ISel facts remain
        // available on `isel_func` for diagnostics, but none may authorize a behavior-changing pass.
        let proof_optimization_metadata = None;

        // Sentinel S1: snapshot guard carriers at birth (before optimization) into a per-function
        // ledger keyed by the arch-neutral Certified-Elimination Kernel. Shadow only.
        let guard_observation = crate::guard_ledger::observe_carrier_births(&ir_func);

        // Phase 3: Optimization
        self.run_optimization_with_proof_metadata_checked(
            &mut ir_func,
            proof_optimization_metadata,
            provenance.as_mut(),
        )?;

        // Sentinel S1: reconcile the snapshot against the optimized function (mark eliminated vs
        // trapped), run the shadow kernel, and check guard-count conservation. Zero behavior
        // change: never fails the compile, output gated by TRUST_CG_GUARD_SHADOW.
        crate::guard_ledger::finalize_and_observe(guard_observation, &ir_func);

        // Phase 3.5: Verification (optional — gated by config.verify)
        self.run_verification(&ir_func)?;

        // Phase 4-6: Register Allocation
        let regalloc = self.run_regalloc(&mut ir_func)?;

        // Phase 6.5: Lower pseudo Copy instructions to real moves.
        lower_copies(&mut ir_func)?;
        eliminate_dead_unallocated_defs(&mut ir_func);
        bind_dead_unallocated_defs_to_discard_registers(&mut ir_func)?;
        ensure_no_unresolved_vregs(&ir_func, "regalloc/copy lowering")?;

        // Phase 7: Frame Lowering
        let frame_layout = self.run_frame_lowering(&mut ir_func)?;

        // Phase 7.25: Expand proof-only guards before branch resolution.
        crate::lower::expand_trap_bounds_check_exact(&mut ir_func);
        crate::lower::expand_trap_null_if_zero(&mut ir_func);
        crate::lower::expand_trap_div_zero_if_zero(&mut ir_func);
        crate::lower::expand_trap_shift_range_if_oob(&mut ir_func);
        crate::lower::expand_trap_overflow_exact(&mut ir_func);

        // Phase 7.4: Fall-through branch layout (O2/O3) — reorder blocks for
        // fall-through and elide redundant jumps. Must run right before
        // resolve_branches so `block_order` is final and consumed verbatim.
        self.apply_aarch64_branch_layout(&mut ir_func);

        // Phase 7.5: Branch Resolution — resolve symbolic Block operands to
        // PC-relative byte offsets before encoding.
        resolve_branches_after_authority(&mut ir_func)?;
        self.recheck_aarch64_post_regalloc(&ir_func)?;
        seed_spilled_value_debug_provenance(
            &ir_func,
            &mut provenance,
            &regalloc.debug_snapshot,
            &debug_value_bindings,
        )?;
        seed_register_value_debug_provenance(&ir_func, &mut provenance, &regalloc.debug_snapshot)?;
        seed_constant_value_debug_provenance(&ir_func, &mut provenance)?;
        seed_stack_alloca_debug_provenance(&ir_func, &mut provenance)?;

        // Phase 8: Encoding
        let (code, fixups, eh_block_offsets) = if let Some(provenance) = provenance.as_mut() {
            let (code, fixups, block_offsets) = if ir_func.eh_metadata.has_eh_info() {
                // EH-aware owner: keep exact block offsets for LSDA resolution
                // while threading provenance through the private encoder core.
                encode_function_with_fixups_and_blocks_impl(&ir_func, Some(provenance))?
            } else {
                encode_function_with_fixups_and_blocks_with_provenance(&ir_func, provenance)?
            };
            provenance.build_transitive();
            (code, fixups, Some(block_offsets))
        } else if ir_func.eh_metadata.has_eh_info() {
            // EH functions need block byte offsets to resolve the LSDA call-site
            // table + landing-pad offsets, so take the block-tracking encode path
            // even without provenance.
            let (code, fixups, block_offsets) =
                encode_function_with_fixups_and_blocks_impl(&ir_func, None)?;
            (code, fixups, Some(block_offsets))
        } else {
            let (code, fixups) = encode_function_with_fixups(&ir_func)?;
            (code, fixups, None)
        };

        reject_unsupported_aarch64_object_format(&self.config.target_triple)?;

        // Phase 8.5: LSDA Generation — resolve the post-layout EH byte offsets
        // from the block offsets just computed, then generate the
        // Language-Specific Data Area (call sites, landing pads, type table).
        if let Some(block_offsets) = &eh_block_offsets {
            resolve_eh_offsets(&mut ir_func, block_offsets, code.len())?;
        }
        let lsda = generate_lsda_for_function(&ir_func)?;

        // ELF target: emit with `.eh_frame` (and `.gcc_except_table` when the
        // function carries EH structure) — the LSDA above is required input,
        // so this fork sits after Phase 8.5 (Mach-O flow unchanged).
        if target_triple_uses_elf(&self.config.target_triple) {
            let personality = if lsda.is_some() {
                Some(
                    crate::exception_handling::required_personality_symbol(
                        ir_func.eh_metadata.personality.as_deref(),
                    )
                    .map_err(|error| {
                        PipelineError::MalformedAarch64Function {
                            function: ir_func.name.clone(),
                            detail: format!("invalid exception-handling personality: {error}"),
                        }
                    })?,
                )
            } else {
                None
            };
            if let Some(obj_bytes) = emit_single_function_target_elf_if_needed(
                &self.config.target_triple,
                &ir_func.name,
                &code,
                &fixups,
                lsda.as_deref().zip(personality),
                Some(&frame_layout),
                ir_func.text_align_log2,
            )? {
                return Ok(obj_bytes);
            }
        }

        // Phase 9: Mach-O Emission (with compact unwind + LSDA)
        let debug_provenance = provenance
            .as_ref()
            .map(|provenance| (provenance, &trust_ir_source_locs));
        let obj_bytes = self.emit_macho(
            &ir_func,
            &code,
            Some(&frame_layout),
            lsda.as_deref(),
            debug_provenance,
            Some(&fixups),
        )?;

        Ok(obj_bytes)
    }

    /// Compile a pre-built IR function (skipping ISel).
    ///
    /// Useful when you already have an `IrMachFunction` and want to run
    /// the remaining phases (opt, regalloc, frame, encode, emit).
    pub fn compile_ir_function(
        &self,
        ir_func: &mut IrMachFunction,
    ) -> Result<Vec<u8>, PipelineError> {
        self.compile_ir_function_with_stats(ir_func)
            .map(|(obj_bytes, _stats)| obj_bytes)
    }

    /// Compile a pre-built IR function and return optimization pass stats.
    ///
    /// This is used by the high-level compiler to attach certified pass-chain
    /// evidence from the real optimization path without changing the legacy
    /// `compile_ir_function` return type.
    pub fn compile_ir_function_with_stats(
        &self,
        ir_func: &mut IrMachFunction,
    ) -> Result<(Vec<u8>, trust_cg_opt::PassStats), PipelineError> {
        reject_unsupported_aarch64_object_format(&self.config.target_triple)?;
        validate_aarch64_mach_function(ir_func)?;

        // Phase 3: Optimization
        let optimization_stats = self.run_optimization_checked(ir_func)?;

        // Phase 3.5: Verification (optional — gated by config.verify)
        self.run_verification(ir_func)?;

        // Phase 4-6: Register Allocation
        let _regalloc = self.run_regalloc(ir_func)?;

        // Phase 6.5: Lower pseudo Copy instructions to real moves.
        lower_copies(ir_func)?;
        eliminate_dead_unallocated_defs(ir_func);
        bind_dead_unallocated_defs_to_discard_registers(ir_func)?;
        ensure_no_unresolved_vregs(ir_func, "regalloc/copy lowering")?;

        // Phase 7: Frame Lowering
        let frame_layout = self.run_frame_lowering(ir_func)?;

        // Phase 7.25: Expand proof-only guards before branch resolution.
        crate::lower::expand_trap_bounds_check_exact(ir_func);
        crate::lower::expand_trap_null_if_zero(ir_func);
        crate::lower::expand_trap_div_zero_if_zero(ir_func);
        crate::lower::expand_trap_shift_range_if_oob(ir_func);
        crate::lower::expand_trap_overflow_exact(ir_func);

        // Phase 7.4: Fall-through branch layout (O2/O3).
        self.apply_aarch64_branch_layout(ir_func);

        // Phase 7.5: Branch Resolution
        resolve_branches_after_authority(ir_func)?;
        self.recheck_aarch64_post_regalloc(ir_func)?;

        // Phase 8: Encoding. EH functions need block byte offsets to resolve
        // the LSDA, so take the block-tracking encode path when EH is present.
        let (code, fixups, eh_block_offsets) = if ir_func.eh_metadata.has_eh_info() {
            let (code, fixups, block_offsets) =
                encode_function_with_fixups_and_blocks_impl(ir_func, None)?;
            (code, fixups, Some(block_offsets))
        } else {
            let (code, fixups) = encode_function_with_fixups(ir_func)?;
            (code, fixups, None)
        };

        reject_unsupported_aarch64_object_format(&self.config.target_triple)?;

        // Phase 8.5: LSDA Generation — resolve EH byte offsets, then build LSDA.
        if let Some(block_offsets) = &eh_block_offsets {
            resolve_eh_offsets(ir_func, block_offsets, code.len())?;
        }
        let lsda = generate_lsda_for_function(ir_func)?;

        // ELF target: emit with `.eh_frame` (and `.gcc_except_table` when the
        // function carries EH structure) — the LSDA above is required input,
        // so this fork sits after Phase 8.5 (Mach-O flow unchanged).
        if target_triple_uses_elf(&self.config.target_triple) {
            let personality = if lsda.is_some() {
                Some(
                    crate::exception_handling::required_personality_symbol(
                        ir_func.eh_metadata.personality.as_deref(),
                    )
                    .map_err(|error| {
                        PipelineError::MalformedAarch64Function {
                            function: ir_func.name.clone(),
                            detail: format!("invalid exception-handling personality: {error}"),
                        }
                    })?,
                )
            } else {
                None
            };
            if let Some(obj_bytes) = emit_single_function_target_elf_if_needed(
                &self.config.target_triple,
                &ir_func.name,
                &code,
                &fixups,
                lsda.as_deref().zip(personality),
                Some(&frame_layout),
                ir_func.text_align_log2,
            )? {
                return Ok((obj_bytes, optimization_stats));
            }
        }

        // Phase 9: Mach-O Emission (with compact unwind + LSDA)
        let obj_bytes = self.emit_macho(
            ir_func,
            &code,
            Some(&frame_layout),
            lsda.as_deref(),
            None,
            Some(&fixups),
        )?;

        Ok((obj_bytes, optimization_stats))
    }

    /// Prepare a trust_ir function through phases 1-7.5 (ISel through branch
    /// resolution) without encoding or Mach-O emission.
    ///
    /// The returned `IrMachFunction` is ready to be passed to
    /// [`compile_module`](Self::compile_module) alongside other prepared
    /// functions. This enables multi-function compilation where cross-function
    /// BL instructions are resolved via BRANCH26 relocations.
    pub fn prepare_function(
        &self,
        input: &trust_cg_lower::Function,
    ) -> Result<IrMachFunction, PipelineError> {
        self.prepare_function_with_proofs(input, None)
    }

    /// Like [`prepare_function`](Self::prepare_function) but also propagates
    /// trust_ir proof annotations from the adapter's [`ProofContext`](trust_cg_lower::ProofContext)
    /// onto the machine instructions and function metadata.
    ///
    /// Proof annotations enable proof-consuming optimizations (proof_opts pass)
    /// that eliminate runtime safety checks verified by ay.
    pub fn prepare_function_with_proofs(
        &self,
        input: &trust_cg_lower::Function,
        proof_ctx: Option<&trust_cg_lower::ProofContext>,
    ) -> Result<IrMachFunction, PipelineError> {
        let (ir_func, _metrics) = self.prepare_function_with_metrics(input, proof_ctx)?;
        Ok(ir_func)
    }

    /// Batch variant of [`prepare_function_with_proofs`](Self::prepare_function_with_proofs)
    /// that prepares many functions across a bounded Rayon worker pool,
    /// returning one result per input in **input order** (`results[i]`
    /// corresponds to `inputs[i]`).
    ///
    /// This mirrors [`compile_module_parallel`](Self::compile_module_parallel):
    /// it fans the *existing* per-function `prepare` across cores. The serial
    /// ISel+regalloc phase has no batch API of its own, so multi-function
    /// modules (e.g. a model-checker's successor kernel + invariant checks +
    /// liveness) otherwise pay that cost serially.
    ///
    /// ## Determinism / soundness
    ///
    /// Each function's preparation is a pure function of its own input. Every
    /// pipeline phase reachable from here (`run_isel`,
    /// `run_optimization_with_proof_metadata`, `run_regalloc`,
    /// `run_frame_lowering`, `run_verification`, branch resolution) takes
    /// `&self` and builds entirely fresh, stack-local state per call, so no
    /// mutable state is shared across functions. The only interior-mutable
    /// `self` field reachable on this path is the CEGIS cache, and it is inert
    /// unless `config.cegis_superopt_budget_sec` is `Some(> 0)` (see
    /// `run_cegis_superopt`). Symbols derive from the per-function
    /// `input.name` and block ids, never a process-global counter. Therefore
    /// the parallel output is **byte-identical** to the serial loop, including
    /// symbol order, and `rayon`'s indexed `par_iter().map().collect()`
    /// preserves input order.
    ///
    /// Falls back to a serial loop (the same per-function call) when there are
    /// fewer than two work items or the host parallelism cap is one, so the
    /// success path is identical regardless of how many workers actually run.
    pub fn prepare_functions_parallel(
        &self,
        inputs: &[(trust_cg_lower::Function, trust_cg_lower::ProofContext)],
    ) -> Vec<Result<IrMachFunction, PipelineError>> {
        let prepare_serially = || {
            inputs
                .iter()
                .map(|(func, proof_ctx)| self.prepare_function_with_proofs(func, Some(proof_ctx)))
                .collect()
        };

        let Some(worker_count) = crate::resource_limits::worker_count_for_items(inputs.len())
        else {
            // Not enough work to justify parallel overhead — run serially in
            // input order (byte-identical to the parallel success path).
            return prepare_serially();
        };

        let pool = match crate::resource_limits::build_rayon_pool(worker_count) {
            Ok(pool) => pool,
            // Pool construction failed: degrade to a deterministic serial pass
            // rather than failing the whole batch. Same observable output.
            Err(_) => return prepare_serially(),
        };

        // `par_iter().map().collect::<Vec<_>>()` preserves input order, so
        // `results[i]` corresponds to `inputs[i]`. Each closure invocation
        // shares only `&self` (immutable on this path) and operates on its own
        // input with thread-local fresh state — no cross-function mutation.
        use rayon::prelude::*;
        pool.install(|| {
            inputs
                .par_iter()
                .map(|(func, proof_ctx)| self.prepare_function_with_proofs(func, Some(proof_ctx)))
                .collect()
        })
    }

    /// Like [`prepare_function_with_proofs`](Self::prepare_function_with_proofs)
    /// but also records per-phase timings and register-allocation spill-slot
    /// counts for downstream observability.
    pub fn prepare_function_with_metrics(
        &self,
        input: &trust_cg_lower::Function,
        proof_ctx: Option<&trust_cg_lower::ProofContext>,
    ) -> Result<(IrMachFunction, PreparationMetrics), PipelineError> {
        let (ir_func, metrics, _provenance) =
            self.prepare_function_with_metrics_and_provenance(input, proof_ctx, None)?;
        Ok((ir_func, metrics))
    }

    /// Like [`prepare_function_with_metrics`](Self::prepare_function_with_metrics),
    /// but also returns the post-optimization trust_ir-to-MachIR provenance map
    /// when the input carried trust_ir origins.
    ///
    /// The returned map has not been encoded yet, so binary-offset queries are
    /// populated only after the caller encodes with
    /// [`encode_function_with_fixups_and_blocks_with_provenance`] and calls
    /// [`trust_cg_ir::ProvenanceMap::build_transitive`].
    pub fn prepare_function_with_metrics_and_provenance_map(
        &self,
        input: &trust_cg_lower::Function,
        proof_ctx: Option<&trust_cg_lower::ProofContext>,
    ) -> Result<
        (
            IrMachFunction,
            PreparationMetrics,
            Option<trust_cg_ir::ProvenanceMap>,
        ),
        PipelineError,
    > {
        self.prepare_function_with_metrics_and_provenance(input, proof_ctx, None)
    }

    /// Like [`prepare_function_with_metrics`](Self::prepare_function_with_metrics),
    /// retaining the older trust_ir-aware call shape for callers that have the
    /// source function handy. Proof-citation provenance now comes from the
    /// lowered function's explicit trust_ir-origin sidecar.
    pub fn prepare_function_with_metrics_and_trust_ir_provenance(
        &self,
        input: &trust_cg_lower::Function,
        proof_ctx: Option<&trust_cg_lower::ProofContext>,
        _trust_ir_func: &trust_ir::Function,
    ) -> Result<(IrMachFunction, PreparationMetrics), PipelineError> {
        let (ir_func, metrics, _provenance) =
            self.prepare_function_with_metrics_and_provenance(input, proof_ctx, None)?;
        Ok((ir_func, metrics))
    }

    /// Like [`prepare_function_with_metrics_and_trust_ir_provenance`](Self::prepare_function_with_metrics_and_trust_ir_provenance),
    /// but retains the trust_ir module context needed by bounded fsym diagnostics.
    pub fn prepare_function_with_metrics_and_trust_ir_module(
        &self,
        input: &trust_cg_lower::Function,
        proof_ctx: Option<&trust_cg_lower::ProofContext>,
        trust_ir_module: &trust_ir::Module,
        trust_ir_func: &trust_ir::Function,
    ) -> Result<(IrMachFunction, PreparationMetrics), PipelineError> {
        let (ir_func, metrics, _provenance) = self.prepare_function_with_metrics_and_provenance(
            input,
            proof_ctx,
            Some((trust_ir_module, trust_ir_func)),
        )?;
        Ok((ir_func, metrics))
    }

    fn prepare_function_with_metrics_and_provenance(
        &self,
        input: &trust_cg_lower::Function,
        proof_ctx: Option<&trust_cg_lower::ProofContext>,
        trust_ir_source: Option<(&trust_ir::Module, &trust_ir::Function)>,
    ) -> Result<
        (
            IrMachFunction,
            PreparationMetrics,
            Option<trust_cg_ir::ProvenanceMap>,
        ),
        PipelineError,
    > {
        let mut metrics = PreparationMetrics::default();

        if let Some((trust_ir_module, trust_ir_func)) = trust_ir_source {
            // Fail-closed: a deref-coverage gap (#49 class) propagates as
            // PipelineError::FsymCoverageGap rather than being swallowed into
            // advisory metrics.
            metrics.fsym_trust_ir_summary =
                self.run_fsym_trust_ir_preflight(trust_ir_module, trust_ir_func)?;
        }

        // Phase 1: Instruction Selection
        let isel_timer = if trust_cg_time_pipeline_enabled() {
            eprintln!(
                "[trust-cg-time-pipeline] start func={} phase=isel",
                input.name
            );
            Some(Instant::now())
        } else {
            None
        };
        let isel_start = Instant::now();
        let (isel_func, value_map) = self.run_isel(input, proof_ctx)?;
        let debug_value_bindings = debug_value_binding_vregs(input, value_map.as_ref());
        metrics.timings.isel = Some(isel_start.elapsed());
        if let Some(start) = isel_timer {
            eprintln!(
                "[trust-cg-time-pipeline] end func={} phase=isel elapsed_us={}",
                input.name,
                start.elapsed().as_micros()
            );
        }

        // Phase 2: Convert ISel output to shared IR
        let mut provenance = provenance_from_isel_trust_ir_origins(&isel_func);
        let mut ir_func = isel_func.to_ir_func();
        ir_func.debug_meta = input.debug_meta.clone();
        ir_func.stack_protector = input.stack_protector;

        // Phase 2.5: Propagate proof annotations from ProofContext onto MachInsts.
        //
        // The adapter's ProofContext maps LIR Values to proof annotations.
        // The ISel's value_map maps LIR Values to VRegs/operands.
        // We build a VReg->InstId reverse map from the IR function, then
        // annotate defining instructions with proof annotations.
        if trust_cg_lower::guard_evidence::validator_guard_replay_authority_available()
            && let (Some(ctx), Some(vmap)) = (proof_ctx, &value_map)
        {
            apply_proof_annotations(&mut ir_func, ctx, vmap);
        }

        // Edge-connectivity check (non-fatal).
        //
        // This was originally `debug_assert!(total_succs > 0, ..)` but that
        // fired on legal trust_ir whose non-entry blocks all terminate with
        // `Return` (no `Br`/`CondBr` edges). After DCE such blocks are
        // harmless — register allocation, frame lowering, and encoding all
        // operate per-block and do not require inter-block connectivity.
        // Tripping the assert prevented the pipeline from being a total
        // function over valid trust_ir (#447: panic-fuzz totality). We keep the
        // shape of the check as a no-op sentinel for future debugging.
        #[cfg(debug_assertions)]
        {
            let has_branches = ir_func.blocks.len() > 1;
            if has_branches {
                let _total_succs: usize = ir_func.blocks.iter().map(|b| b.succs.len()).sum();
                let _total_preds: usize = ir_func.blocks.iter().map(|b| b.preds.len()).sum();
                // Tolerated: _total_succs == 0 or _total_preds == 0 is a legal
                // (if unusual) multi-block shape — see issue #447.
            }
        }

        // ProofFact sidecars (NoAlias, Aligned, NoUndef, ranges, and related facts) are as
        // producer-constructible as the single proof annotation field.  Keep them in ISel and the
        // ProofContext for reporting, but do not feed them to behavior-changing optimization passes
        // until exact replay authority is available.
        let proof_optimization_metadata =
            if trust_cg_lower::guard_evidence::validator_guard_replay_authority_available() {
                let mut metadata = proof_optimization_metadata_from_isel_facts(&isel_func);
                if let (Some(ctx), Some(vmap)) = (proof_ctx, &value_map) {
                    merge_proof_optimization_metadata(
                        &mut metadata,
                        proof_optimization_metadata_from_context(&ir_func, ctx, vmap),
                    );
                }
                (!metadata.proof_facts().is_empty()).then_some(metadata)
            } else {
                None
            };

        // Phase 2.75: always install the empty-authority production guard gate.  Status/lineage and
        // annotations remain report metadata; none can authorize deletion without exact replay.
        debug_assert!(guard_kernel_gate_enabled());
        let kernel_gate = build_guard_kernel_gate(
            &mut ir_func,
            &isel_func,
            proof_ctx,
            trust_ir_source.map(|(module, _)| module),
        );

        // Phase 3: Optimization (including proof-consuming optimizations)
        let phase_timer = log_pipeline_phase_start(&ir_func, "optimization");
        let optimization_start = Instant::now();
        let optimization_stats = self.run_optimization_with_proof_metadata_and_gate_checked(
            &mut ir_func,
            proof_optimization_metadata,
            provenance.as_mut(),
            kernel_gate,
        )?;
        // Sentinel S4 (AArch64 production parity with x86): fail closed if the
        // independent re-check of any kernel-authorized guard elimination
        // rejects. The boxed proof pass surfaces its re-check verdict through
        // `PassStats::kernel_recheck`; a rejection aborts the compile before
        // regalloc/encoding can emit code that deleted a guard it could not
        // independently re-justify.
        if let Err(reason) = optimization_stats.kernel_recheck() {
            return Err(PipelineError::GuardKernelRecheckRejected(format!(
                "in `{}`: {reason}",
                ir_func.name
            )));
        }
        metrics.proof_optimization_certificates = proof_optimization_certificate_citations(
            &ir_func.name,
            &optimization_stats.proof_optimization_certificates,
        );
        metrics.certified_pass_runs = optimization_stats.certified_pass_runs.clone();
        metrics.timings.optimization = Some(optimization_start.elapsed());
        log_pipeline_phase_end(&ir_func, "optimization", phase_timer);

        // Phase 3.5: Verification (optional)
        let phase_timer = log_pipeline_phase_start(&ir_func, "verification");
        let verification_start = Instant::now();
        self.run_verification(&ir_func)?;
        if self.function_verification_selected(&ir_func.name) {
            metrics.timings.verification = Some(verification_start.elapsed());
        }
        log_pipeline_phase_end(&ir_func, "verification", phase_timer);

        // Phase 3.75: AOT PGO counter injection (profile-generate mode only).
        //
        // Deliberately AFTER optimization + verification (the canary must
        // count the SAME optimized CFG a later profile-use compile will query,
        // and the counters must not perturb or be moved by the optimizer) and
        // BEFORE register allocation (the increments use fresh vregs that the
        // allocator assigns like any other code). `None` sink = byte-identical
        // default path.
        if let Some(sink) = &self.profile_generate_sink {
            inject_aot_block_counters(&mut ir_func, sink)?;
        }

        // Phase 4-6: Register Allocation
        let phase_timer = log_pipeline_phase_start(&ir_func, "regalloc");
        let regalloc_start = Instant::now();
        let regalloc = self.run_regalloc(&mut ir_func)?;
        metrics.spill_slot_count = regalloc.spill_slot_count;
        metrics.post_ra_copies_coalesced = regalloc.post_ra_copies_coalesced;
        metrics.timings.regalloc = Some(regalloc_start.elapsed());
        log_pipeline_phase_end(&ir_func, "regalloc", phase_timer);

        // Phase 6.5: Lower pseudo Copy instructions to real moves.
        let phase_timer = log_pipeline_phase_start(&ir_func, "copy-lowering");
        lower_copies(&mut ir_func)?;
        eliminate_dead_unallocated_defs(&mut ir_func);
        bind_dead_unallocated_defs_to_discard_registers(&mut ir_func)?;
        ensure_no_unresolved_vregs(&ir_func, "regalloc/copy lowering")?;
        log_pipeline_phase_end(&ir_func, "copy-lowering", phase_timer);

        // Phase 7: Frame Lowering
        let phase_timer = log_pipeline_phase_start(&ir_func, "frame-lowering");
        let frame_lowering_start = Instant::now();
        let frame_layout = self.run_frame_lowering(&mut ir_func)?;
        // Retain the layout so module callers can thread it into whole-module
        // unwind-table emission (`compile_module_with_globals_and_layouts`).
        metrics.frame_layout = Some(frame_layout);
        metrics.timings.frame_lowering = Some(frame_lowering_start.elapsed());
        log_pipeline_phase_end(&ir_func, "frame-lowering", phase_timer);

        // Phase 7.25: Expand proof-only guards before branch resolution.
        crate::lower::expand_trap_bounds_check_exact(&mut ir_func);
        crate::lower::expand_trap_null_if_zero(&mut ir_func);
        crate::lower::expand_trap_div_zero_if_zero(&mut ir_func);
        crate::lower::expand_trap_shift_range_if_oob(&mut ir_func);
        crate::lower::expand_trap_overflow_exact(&mut ir_func);

        // Phase 7.4: Fall-through branch layout (O2/O3).
        self.apply_aarch64_branch_layout(&mut ir_func);

        // Phase 7.5: Branch Resolution
        let phase_timer = log_pipeline_phase_start(&ir_func, "branch-resolution");
        let branch_resolution_start = Instant::now();
        resolve_branches_after_authority(&mut ir_func)?;
        self.recheck_aarch64_post_regalloc(&ir_func)?;
        metrics.timings.branch_resolution = Some(branch_resolution_start.elapsed());
        log_pipeline_phase_end(&ir_func, "branch-resolution", phase_timer);

        seed_spilled_value_debug_provenance(
            &ir_func,
            &mut provenance,
            &regalloc.debug_snapshot,
            &debug_value_bindings,
        )?;
        seed_register_value_debug_provenance(&ir_func, &mut provenance, &regalloc.debug_snapshot)?;
        seed_constant_value_debug_provenance(&ir_func, &mut provenance)?;
        seed_stack_alloca_debug_provenance(&ir_func, &mut provenance)?;

        Ok((ir_func, metrics, provenance))
    }

    /// Prepare a pre-built IR function through phases 3-7.5 (optimization
    /// through branch resolution) without encoding or Mach-O emission.
    ///
    /// Like [`prepare_function`](Self::prepare_function) but skips ISel,
    /// accepting an `IrMachFunction` directly. The returned function is ready
    /// for [`compile_module`](Self::compile_module).
    pub fn prepare_ir_function(&self, ir_func: &mut IrMachFunction) -> Result<(), PipelineError> {
        validate_aarch64_mach_function(ir_func)?;

        // Phase 3: Optimization
        self.run_optimization_checked(ir_func)?;

        // Phase 3.5: Verification (optional)
        self.run_verification(ir_func)?;

        // Phase 4-6: Register Allocation
        let _regalloc = self.run_regalloc(ir_func)?;

        // Phase 6.5: Lower pseudo Copy instructions to real moves.
        lower_copies(ir_func)?;
        eliminate_dead_unallocated_defs(ir_func);
        bind_dead_unallocated_defs_to_discard_registers(ir_func)?;
        ensure_no_unresolved_vregs(ir_func, "regalloc/copy lowering")?;

        // Phase 7: Frame Lowering
        let _frame_layout = self.run_frame_lowering(ir_func)?;

        // Phase 7.25: Expand proof-only guards before branch resolution.
        crate::lower::expand_trap_bounds_check_exact(ir_func);
        crate::lower::expand_trap_null_if_zero(ir_func);
        crate::lower::expand_trap_div_zero_if_zero(ir_func);
        crate::lower::expand_trap_shift_range_if_oob(ir_func);
        crate::lower::expand_trap_overflow_exact(ir_func);

        // Phase 7.4: Fall-through branch layout (O2/O3).
        self.apply_aarch64_branch_layout(ir_func);

        // Phase 7.5: Branch Resolution
        resolve_branches_after_authority(ir_func)?;
        self.recheck_aarch64_post_regalloc(ir_func)?;

        Ok(())
    }

    /// Encode an already-allocated IR function to Mach-O.
    ///
    /// Skips ISel, optimization, and regalloc. Useful for testing the
    /// encoding and emission phases in isolation.
    pub fn encode_and_emit(&self, ir_func: &mut IrMachFunction) -> Result<Vec<u8>, PipelineError> {
        reject_unsupported_aarch64_object_format(&self.config.target_triple)?;
        validate_aarch64_mach_function(ir_func)?;

        // Phase 7: Frame Lowering
        let frame_layout = self.run_frame_lowering(ir_func)?;

        // Phase 7.25: Expand proof-only guards before encoding.
        crate::lower::expand_trap_bounds_check_exact(ir_func);
        crate::lower::expand_trap_null_if_zero(ir_func);
        crate::lower::expand_trap_div_zero_if_zero(ir_func);
        crate::lower::expand_trap_shift_range_if_oob(ir_func);
        crate::lower::expand_trap_overflow_exact(ir_func);
        self.recheck_aarch64_post_regalloc(ir_func)?;

        // Phase 8: Encoding. Capture block offsets when EH is present so any
        // unresolved EH metadata can be bound to the exact final BL/BLR and
        // landing-pad offsets before LSDA generation. Pre-authored offsets are
        // accepted only when they exactly match the final encoding.
        let (code, fixups, eh_block_offsets) = if ir_func.eh_metadata.has_eh_info() {
            let (code, fixups, block_offsets) =
                encode_function_with_fixups_and_blocks_impl(ir_func, None)?;
            (code, fixups, Some(block_offsets))
        } else {
            let (code, fixups) = encode_function_with_fixups(ir_func)?;
            (code, fixups, None)
        };

        // Phase 8.5: LSDA Generation
        if let Some(block_offsets) = &eh_block_offsets {
            resolve_eh_offsets(ir_func, block_offsets, code.len())?;
        }
        let lsda = generate_lsda_for_function(ir_func)?;

        // ELF target: emit with `.eh_frame` (and `.gcc_except_table` when the
        // function carries EH structure) — same fork as `compile_function`.
        if target_triple_uses_elf(&self.config.target_triple) {
            let personality = if lsda.is_some() {
                Some(
                    crate::exception_handling::required_personality_symbol(
                        ir_func.eh_metadata.personality.as_deref(),
                    )
                    .map_err(|error| {
                        PipelineError::MalformedAarch64Function {
                            function: ir_func.name.clone(),
                            detail: format!("invalid exception-handling personality: {error}"),
                        }
                    })?,
                )
            } else {
                None
            };
            if let Some(obj_bytes) = emit_single_function_target_elf_if_needed(
                &self.config.target_triple,
                &ir_func.name,
                &code,
                &fixups,
                lsda.as_deref().zip(personality),
                Some(&frame_layout),
                ir_func.text_align_log2,
            )? {
                return Ok(obj_bytes);
            }
        }

        // Phase 9: Mach-O Emission (with compact unwind + LSDA)
        let obj_bytes = self.emit_macho(
            ir_func,
            &code,
            Some(&frame_layout),
            lsda.as_deref(),
            None,
            Some(&fixups),
        )?;

        Ok(obj_bytes)
    }

    /// Compile multiple pre-built IR functions into a single Mach-O .o file.
    ///
    /// All functions are concatenated into one `__text` section. Cross-function
    /// BL/B instructions with [`Symbol`](IrOperand::Symbol) operands are resolved
    /// into `ARM64_RELOC_BRANCH26` relocations, allowing the linker (or a
    /// subsequent static link step) to patch the call targets.
    ///
    /// This is the correct path for producing .o files with multiple functions —
    /// unlike [`compile_function`](Self::compile_function) which produces one .o
    /// per function and cannot represent cross-function calls.
    ///
    /// Each function must already be in post-regalloc, post-frame-lowering state
    /// (physical registers, branches resolved). The caller can prepare functions
    /// using the pipeline's individual phases or by building IR directly.
    pub fn compile_module(&self, functions: &[IrMachFunction]) -> Result<Vec<u8>, PipelineError> {
        self.compile_module_with_globals(functions, &[])
    }

    #[cfg(feature = "verify")]
    pub fn module_relocation_inventory_report(
        &self,
        functions: &[IrMachFunction],
        object_name: impl Into<String>,
    ) -> Result<Option<trust_cg_verify::ObjectRelocationInventoryReport>, PipelineError> {
        self.module_relocation_inventory_report_with_object_state(functions, &[], &[], object_name)
    }

    /// Build the relocation inventory from the production module's complete
    /// relocation-bearing input surface.
    ///
    /// Unlike the legacy code/fixup-only wrapper above, this includes relocation
    /// rows introduced after text encoding: global-data pointer slots, Darwin
    /// TLV descriptors, whole-module compact-unwind / DWARF fallback records,
    /// and ELF FDEs. Certified-object promotion must use this method so an
    /// known object-side row can sit outside the proof authority boundary. This
    /// pre-emission report is not an exact-object digest binding; all non-empty
    /// production registries remain fail-closed until such a binding exists.
    #[cfg(feature = "verify")]
    pub fn module_relocation_inventory_report_with_object_state(
        &self,
        functions: &[IrMachFunction],
        globals: &[ObjectGlobal],
        frame_layouts: &[Option<crate::frame::FrameLayout>],
        object_name: impl Into<String>,
    ) -> Result<Option<trust_cg_verify::ObjectRelocationInventoryReport>, PipelineError> {
        use crate::macho::fixup::FixupList;
        use trust_cg_verify::ObjectRelocationKind;

        reject_unsupported_aarch64_object_format(&self.config.target_triple)?;
        validate_aarch64_object_globals(globals)?;
        let object_name = object_name.into();

        if let Some(func) = functions.iter().find(|func| func.eh_metadata.has_eh_info()) {
            return Err(PipelineError::EhSidecarUnsupported {
                function: func.name.clone(),
                api: "module_relocation_inventory_report",
                reason: "EH object emission adds compact-unwind/eh-frame/personality/LSDA relocations that this inventory does not yet enumerate; refusing to return an incomplete or promotable report (fail-closed)"
                    .to_string(),
            });
        }

        let layouts_complete = !functions.is_empty()
            && (0..functions.len())
                .all(|i| frame_layouts.get(i).is_some_and(|layout| layout.is_some()));

        let estimated_code_size = checked_aarch64_capacity(
            "<module>",
            "estimated combined code capacity",
            functions.len(),
            100,
        )?;
        let mut combined_code = Vec::with_capacity(estimated_code_size);
        let mut combined_fixups = FixupList::new();
        for func in functions {
            // Mirror the production emitters' inter-function alignment padding
            // exactly, or the inventory's fixup offsets would drift from the
            // real object's.
            pad_aarch64_text_for_function_alignment(
                &mut combined_code,
                &func.name,
                func.text_align_log2,
            )?;
            let func_start = checked_aarch64_object_u64(
                &func.name,
                "combined text function offset",
                combined_code.len(),
            )?;
            let (code, fixups) = encode_module_function_with_fixups(func)?;
            for fixup in fixups.iter() {
                let mut adjusted = fixup.clone();
                adjusted.offset =
                    checked_aarch64_fixup_offset(&func.name, func_start, fixup.offset)?;
                combined_fixups.push(adjusted);
            }
            extend_aarch64_object_code(&mut combined_code, &func.name, &code)?;
        }

        if !target_triple_uses_elf(&self.config.target_triple) {
            reject_unsupported_aarch64_object_format(&self.config.target_triple)?;
            reject_macho_tls_globals_with_symbol_refs(globals)?;

            // The module DWARF writer emits address relocations derived from
            // source/provenance tables after text encoding. Until those rows
            // are enumerated from the same debug plan, refuse to issue an
            // incomplete inventory rather than silently certify around them.
            if self.config.emit_debug && !functions.is_empty() {
                return Err(PipelineError::ObjectRelocationInventoryIncomplete {
                    object: object_name,
                    reason: "Mach-O DWARF sections emit ARM64_RELOC_UNSIGNED address rows that are not yet enumerated by the certified-object inventory (fail-closed)"
                        .to_string(),
                });
            }

            let mut object_rows = Vec::new();

            // One absolute-pointer relocation for every symbol-address slot in
            // an emitted non-TLS data definition. Imports define no section and
            // TLS templates are rejected above until their own slot-relocation
            // path exists.
            for global in globals
                .iter()
                .filter(|global| !global.is_thread_local && !global.is_import)
            {
                object_rows.extend(std::iter::repeat_n(
                    ObjectRelocationKind::AArch64MachOUnsigned,
                    global.symbol_refs.len(),
                ));
            }

            // Every Darwin TLV definition emits two absolute descriptor rows:
            // `__tlv_bootstrap` and the initial-value-template pointer.
            let tls_definitions = globals
                .iter()
                .filter(|global| global.is_thread_local && !global.is_import)
                .count();
            object_rows.extend(std::iter::repeat_n(
                ObjectRelocationKind::AArch64MachOUnsigned,
                tls_definitions.saturating_mul(2),
            ));

            // The production Compiler always supplies complete frame layouts.
            // Mach-O then emits one compact-unwind function-pointer row per
            // function; a DWARF-fallback FDE adds a SUBTRACTOR+UNSIGNED pair.
            if layouts_complete {
                for layout in frame_layouts.iter().take(functions.len()).flatten() {
                    object_rows.push(ObjectRelocationKind::AArch64MachOUnsigned);
                    if crate::frame::encode_compact_unwind(layout).needs_dwarf_fallback() {
                        object_rows.push(ObjectRelocationKind::AArch64MachOSubtractor);
                        object_rows.push(ObjectRelocationKind::AArch64MachOUnsigned);
                    }
                }
            }

            // AArch64 Mach-O symbolic data relocations: name every emitted row.
            // The PAGE/PAGEOFF/GOT/TLVP/BRANCH formula modules are AY-backed
            // formal evidence, not production Certified authority bound to this
            // exact object. The production registry is therefore empty and every
            // non-empty inventory stays fail-closed. We still hand the consumer a
            // precise inventory instead of a blanket "not implemented" rejection.
            return Ok(Some(aarch64_macho_relocation_inventory_report(
                object_name,
                &combined_fixups,
                object_rows,
            )));
        }

        let mut object_rows = Vec::new();
        if layouts_complete {
            reject_elf_tls_globals_with_symbol_refs(&self.config.target_triple, globals)?;
            for global in globals.iter().filter(|global| !global.is_thread_local) {
                object_rows.extend(std::iter::repeat_n(
                    ObjectRelocationKind::AArch64ElfAbs64,
                    global.symbol_refs.len(),
                ));
            }
            // The whole-module ELF emitter emits one PC-relative FDE pc-begin
            // row for every function even when the module itself has no EH.
            object_rows.extend(std::iter::repeat_n(
                ObjectRelocationKind::AArch64ElfPrel32,
                functions.len(),
            ));
        } else {
            // Mirror the legacy layout-less emitter: it has no global-data
            // relocation path and rejects any such object before emission.
            reject_unsupported_elf_globals(&self.config.target_triple, globals)?;
        }
        Ok(Some(aarch64_elf_relocation_inventory_report(
            object_name,
            &self.config.target_triple,
            &combined_code,
            &combined_fixups,
            object_rows,
        )?))
    }

    pub fn compile_module_with_globals(
        &self,
        functions: &[IrMachFunction],
        globals: &[ObjectGlobal],
    ) -> Result<Vec<u8>, PipelineError> {
        self.compile_module_with_globals_and_layouts(functions, globals, &[])
    }

    /// Like [`compile_module_with_globals`](Self::compile_module_with_globals),
    /// but additionally threads each function's post-frame-lowering
    /// [`FrameLayout`](crate::frame::FrameLayout) (1:1 with `functions`; produced
    /// by [`prepare_function_with_metrics`](Self::prepare_function_with_metrics)
    /// as [`PreparationMetrics::frame_layout`]).
    ///
    /// When a complete layout vector is supplied, whole-module unwind tables
    /// (the x86 EH-Lane-5 analogue, FUZZ-7 [TCG-EH-WALK]) give EVERY function a
    /// `__LD,__compact_unwind` entry — and a DWARF FDE when its frame needs the
    /// fallback — even if the module itself has no handler. That lets an
    /// exception raised below a plain trust-cg frame unwind THROUGH it. A
    /// layout-less non-EH caller keeps the legacy byte-identical no-unwind path.
    ///
    /// Calling this with an EH-carrying module and missing layouts FAILS CLOSED
    /// (never a silent table drop).
    pub fn compile_module_with_globals_and_layouts(
        &self,
        functions: &[IrMachFunction],
        globals: &[ObjectGlobal],
        frame_layouts: &[Option<crate::frame::FrameLayout>],
    ) -> Result<Vec<u8>, PipelineError> {
        // Byte-identity with every pre-existing caller is structural, not
        // asserted: this IS the emission path, called with no bindings (so every
        // definition is global), with only the reported layout discarded.
        self.compile_module_emission(functions, globals, frame_layouts, &[])
            .map(|emission| emission.object)
    }

    /// Emit a whole-module object AND report where each function's code landed.
    ///
    /// This is [`compile_module_with_globals_and_layouts`](Self::compile_module_with_globals_and_layouts)
    /// plus two things it cannot express:
    ///
    /// * **`bindings`** — per-function symbol binding, 1:1 with `functions` when
    ///   non-empty. An EMPTY slice means every definition is
    ///   [`FunctionSymbolBinding::Global`], which is exactly the legacy
    ///   behaviour, so an empty-bindings call is byte-for-byte what the older
    ///   entry point produced. A binding is a symbol-table attribute ONLY: it
    ///   never perturbs a code byte, a text offset, or a relocation.
    /// * **`text_extents`** — the offset and encoded length of every function
    ///   inside the combined text section. A caller that must prove the shipped
    ///   object contains the bytes it verified needs the emitter's own account
    ///   of the layout, not an independent re-derivation of it.
    ///
    /// FAIL-CLOSED SCOPE. Non-`Global` bindings are honoured on the Mach-O path
    /// only. The ELF emitters compute symbol indices with running counters that
    /// depend on every local symbol preceding the global partition, so silently
    /// binding a function local there would shift the `symbol_index` of every
    /// relocation — a miscompile, not a cosmetic difference. Until those three
    /// emitters are made binding-aware, an ELF target with any `Local` binding
    /// is REFUSED rather than mis-emitted. An all-`Global` ELF module (which is
    /// every legacy caller) is unaffected.
    pub fn compile_module_emission(
        &self,
        functions: &[IrMachFunction],
        globals: &[ObjectGlobal],
        frame_layouts: &[Option<crate::frame::FrameLayout>],
        bindings: &[FunctionSymbolBinding],
    ) -> Result<ModuleEmission, PipelineError> {
        use crate::macho::fixup::FixupList;

        if !bindings.is_empty() && bindings.len() != functions.len() {
            return Err(PipelineError::Encoding(format!(
                "module emission received {} symbol binding(s) for {} function(s); \
                 a binding vector must be empty or 1:1 with the functions",
                bindings.len(),
                functions.len()
            )));
        }

        reject_unsupported_aarch64_object_format(&self.config.target_triple)?;
        validate_aarch64_object_globals(globals)?;

        // Symbol-address data relocations (vtable / `static FNS: [fn(); N]`
        // slots) are emitted for the Mach-O writer below via
        // `add_global_data_section` → `ARM64_RELOC_UNSIGNED` (the AArch64
        // analogue of the x86-64 emitter's `X86_64_RELOC_UNSIGNED` path). The ELF
        // emitter is still handled by `emit_target_elf_or_reject_fixups` below,
        // which fails closed on any global it cannot yet relocate.

        // Phase 1: Encode each function, collecting code bytes and fixups.
        // Track each function's byte offset within the combined __text section.
        // EH functions additionally resolve their post-layout LSDA here.
        // Pre-allocate based on estimated 4 bytes per instruction * ~25 insts/func.
        let estimated_code_size = checked_aarch64_capacity(
            "<module>",
            "estimated combined code capacity",
            functions.len(),
            100,
        )?;
        let mut combined_code = Vec::with_capacity(estimated_code_size);
        let mut combined_fixups = FixupList::new();
        let mut func_offsets: Vec<(String, u64)> = Vec::with_capacity(functions.len());
        let mut func_eh: Vec<ModuleFunctionEhData> = Vec::with_capacity(functions.len());
        let mut text_extents: Vec<TextFunctionExtent> = Vec::with_capacity(functions.len());

        for func in functions {
            pad_aarch64_text_for_function_alignment(
                &mut combined_code,
                &func.name,
                func.text_align_log2,
            )?;
            let func_start = checked_aarch64_object_u64(
                &func.name,
                "combined text function offset",
                combined_code.len(),
            )?;
            func_offsets.push((func.name.clone(), func_start));

            let (code, fixups, lsda) = encode_module_function_with_fixups_and_eh(func)?;
            let code_len =
                checked_aarch64_object_u32(&func.name, "encoded code length", code.len())?;

            // The layout report is READ OFF the emission, not recomputed: this
            // is the same `func_start` the symbol table gets and the same
            // encoded length the unwind tables get. `func_start` is already
            // past the alignment padding, and `code_len` excludes the padding
            // that follows — so `len` is the function's own bytes, which is
            // what a consumer can compare against that function emitted alone.
            text_extents.push(TextFunctionExtent {
                name: func.name.clone(),
                offset: func_start,
                len: u64::from(code_len),
            });

            // Adjust fixup offsets to be relative to the combined section.
            for fixup in fixups.iter() {
                let mut adjusted = fixup.clone();
                adjusted.offset =
                    checked_aarch64_fixup_offset(&func.name, func_start, fixup.offset)?;
                combined_fixups.push(adjusted);
            }

            func_eh.push(ModuleFunctionEhData { code_len, lsda });
            extend_aarch64_object_code(&mut combined_code, &func.name, &code)?;
        }

        // Select object format based on the configured target triple.
        // Linux-flavored triples produce ELF with whole-module `.eh_frame`
        // unwind tables (walk-through FDEs when layouts are threaded, LSDAs
        // for EH functions); layout-less legacy callers keep the plain
        // emission and an EH module missing layouts fails closed inside.
        // ELF. The three ELF emitters compute relocation `symbol_index` values
        // with running counters that assume every function lands in the GLOBAL
        // partition; `ElfWriter::write` then re-sorts locals first. Binding a
        // function local without restructuring that bookkeeping would shift
        // every relocation's target — a miscompile that links and runs. So a
        // non-`Global` binding is REFUSED here rather than silently dropped or
        // mis-emitted. All-`Global` (every legacy caller) is untouched.
        if target_triple_uses_elf(&self.config.target_triple)
            && bindings
                .iter()
                .any(|binding| *binding != FunctionSymbolBinding::Global)
        {
            return Err(PipelineError::Encoding(format!(
                "target `{}` emits ELF, whose symbol-index bookkeeping is not yet \
                 binding-aware; refusing to emit a non-global function binding \
                 rather than shift every relocation's symbol index",
                self.config.target_triple
            )));
        }
        if let Some(obj) = emit_aarch64_elf_module_with_unwind(
            &self.config.target_triple,
            &combined_code,
            &func_offsets,
            globals,
            &combined_fixups,
            &func_eh,
            frame_layouts,
            aarch64_module_text_align_log2(functions),
        )? {
            return Ok(ModuleEmission {
                object: obj,
                text_extents,
            });
        }
        reject_unsupported_aarch64_object_format(&self.config.target_triple)?;

        let object = self.emit_module_macho_with_unwind(
            &combined_code,
            combined_fixups,
            &func_offsets,
            &func_eh,
            frame_layouts,
            globals,
            functions,
            bindings,
        )?;
        Ok(ModuleEmission {
            object,
            text_extents,
        })
    }

    /// Compile multiple pre-built IR functions into a single Mach-O .o file,
    /// using rayon to encode functions in parallel.
    ///
    /// Each function is encoded independently into its own buffer on a worker
    /// thread. Results are then merged sequentially (fast memcpy) into the
    /// combined __text section. This eliminates the sequential encoding
    /// bottleneck for modules with many functions.
    ///
    /// Falls back to [`compile_module`](Self::compile_module) for single-function
    /// modules where parallel overhead would dominate.
    pub fn compile_module_parallel(
        &self,
        functions: &[IrMachFunction],
    ) -> Result<Vec<u8>, PipelineError> {
        self.compile_module_parallel_with_globals(functions, &[])
    }

    pub fn compile_module_parallel_with_globals(
        &self,
        functions: &[IrMachFunction],
        globals: &[ObjectGlobal],
    ) -> Result<Vec<u8>, PipelineError> {
        self.compile_module_parallel_with_globals_and_layouts(functions, globals, &[])
    }

    /// Parallel variant of
    /// [`compile_module_with_globals_and_layouts`](Self::compile_module_with_globals_and_layouts)
    /// — see there for the whole-module unwind-table semantics of
    /// `frame_layouts`.
    pub fn compile_module_parallel_with_globals_and_layouts(
        &self,
        functions: &[IrMachFunction],
        globals: &[ObjectGlobal],
        frame_layouts: &[Option<crate::frame::FrameLayout>],
    ) -> Result<Vec<u8>, PipelineError> {
        use crate::macho::fixup::FixupList;
        use rayon::prelude::*;

        reject_unsupported_aarch64_object_format(&self.config.target_triple)?;
        validate_aarch64_object_globals(globals)?;

        // Symbol-address data relocations are emitted by the Mach-O writer via
        // `add_global_data_section` (`ARM64_RELOC_UNSIGNED`); the ELF path still
        // fails closed in `emit_target_elf_or_reject_fixups`. See the sequential
        // `compile_module_with_globals_and_layouts` for the rationale.

        let Some(worker_count) = crate::resource_limits::worker_count_for_items(functions.len())
        else {
            // Not enough to justify parallel overhead; fall back to sequential.
            return self.compile_module_with_globals_and_layouts(functions, globals, frame_layouts);
        };

        let pool = crate::resource_limits::build_rayon_pool(worker_count)
            .map_err(|err| PipelineError::ISel(format!("parallel worker pool error: {err}")))?;

        // Phase 1: Encode each function in parallel, producing per-function buffers.
        // Each encoding is fully independent — no shared mutable state. EH
        // functions additionally resolve their post-layout LSDA here.
        type EncodedModuleFn = (String, Vec<u8>, FixupList, Option<(Vec<u8>, String)>);
        let encoded: Vec<Result<EncodedModuleFn, PipelineError>> = pool.install(|| {
            functions
                .par_iter()
                .map(|func| {
                    let (code, fixups, lsda) = encode_module_function_with_fixups_and_eh(func)?;
                    Ok((func.name.clone(), code, fixups, lsda))
                })
                .collect()
        });

        // Phase 2: Merge per-function buffers sequentially (fast memcpy).
        // Pre-calculate total size for a single allocation.
        let mut total_size: usize = 0;
        let mut results: Vec<EncodedModuleFn> = Vec::with_capacity(encoded.len());
        for result in encoded {
            let entry = result?;
            total_size = checked_aarch64_size_sum(
                &entry.0,
                "combined code byte length",
                total_size,
                entry.1.len(),
            )?;
            results.push(entry);
        }

        let mut combined_code = Vec::with_capacity(total_size);
        let mut combined_fixups = FixupList::new();
        let mut func_offsets: Vec<(String, u64)> = Vec::with_capacity(results.len());
        let mut func_eh: Vec<ModuleFunctionEhData> = Vec::with_capacity(results.len());

        for (func, (name, code, fixups, lsda)) in functions.iter().zip(results) {
            // `par_iter().collect()` preserves input order, so results[i]
            // is functions[i]'s encoding; the alignment request must come
            // from the SAME function whose code is being placed.
            debug_assert_eq!(func.name, name);
            pad_aarch64_text_for_function_alignment(
                &mut combined_code,
                &name,
                func.text_align_log2,
            )?;
            let func_start = checked_aarch64_object_u64(
                &name,
                "combined text function offset",
                combined_code.len(),
            )?;
            let code_len = checked_aarch64_object_u32(&name, "encoded code length", code.len())?;
            func_offsets.push((name.clone(), func_start));

            // Adjust fixup offsets to be relative to the combined section.
            for fixup in fixups.iter() {
                let mut adjusted = fixup.clone();
                adjusted.offset = checked_aarch64_fixup_offset(&name, func_start, fixup.offset)?;
                combined_fixups.push(adjusted);
            }

            func_eh.push(ModuleFunctionEhData { code_len, lsda });
            extend_aarch64_object_code(&mut combined_code, &name, &code)?;
        }

        // ELF: whole-module `.eh_frame` emission (see the sequential path).
        if let Some(obj) = emit_aarch64_elf_module_with_unwind(
            &self.config.target_triple,
            &combined_code,
            &func_offsets,
            globals,
            &combined_fixups,
            &func_eh,
            frame_layouts,
            aarch64_module_text_align_log2(functions),
        )? {
            return Ok(obj);
        }
        reject_unsupported_aarch64_object_format(&self.config.target_triple)?;

        self.emit_module_macho_with_unwind(
            &combined_code,
            combined_fixups,
            &func_offsets,
            &func_eh,
            frame_layouts,
            globals,
            functions,
            // The parallel worker carries no binding channel:
            // `compile_module_emission` always takes the sequential path, so a
            // non-global binding can never reach here and be silently dropped.
            &[],
        )
    }

    /// Phase 2+3 of the generic multi-function module emitters: build the
    /// Mach-O object (combined `__text`, symbols, branch relocations) and —
    /// when the module carries exception-handling structure — the WHOLE-MODULE
    /// unwind tables.
    ///
    /// ## Whole-module unwind tables (EH A64 Lane 5, the x86 FUZZ-7 analogue)
    ///
    /// When ANY function in the module has an LSDA, EVERY function in it must
    /// be WALKABLE by the unwinder: a panic raised in (or below) one function
    /// of this module unwinds through its sibling frames (`main`, shims, plain
    /// no-drop helpers) on its way to the handler. A frame with no unwind entry
    /// stops phase-1 unwinding dead (`_URC_END_OF_STACK` — libstd aborts with
    /// "failed to initiate panic, error 5"), skipping every cleanup Drop — the
    /// FUZZ-7 [TCG-EH-WALK] miscompile class, previously closed on x86-64
    /// (502c09f) and now ported here for aarch64 Mach-O.
    ///
    /// The emission mirrors the PROVEN single-function aarch64 EH path
    /// (`emit_macho`), N-ary:
    ///
    /// * every function gets a 32-byte `__LD,__compact_unwind` entry whose
    ///   `function` field is relocated `ARM64_RELOC_UNSIGNED` against the
    ///   function's OWN symbol (exact atom association for ld64 — the aarch64
    ///   equivalent of x86's section-based reloc scheme);
    /// * a function whose frame the compact encoding cannot describe
    ///   (`UNWIND_ARM64_MODE_DWARF`) gets a DWARF FDE in `__TEXT,__eh_frame`
    ///   under the module's single shared CIE, with the same
    ///   subtractor+unsigned self-relative pc-begin/LSDA relocation scheme the
    ///   single-function path uses;
    /// * an EH function's REAL LSDA lands in `__TEXT,__gcc_except_tab`
    ///   (referenced from its compact entry via `with_lsda_symbol`, or from its
    ///   FDE augmentation when in DWARF mode);
    /// * when the shared CIE must be zPLR (an EH function needs the DWARF
    ///   fallback), every OTHER DWARF-fallback function gets a synthetic
    ///   ALL-FILLER LSDA (one `landing_pad == 0` call-site region covering
    ///   `[0, code_len)` — the personality's "no handler here, continue
    ///   unwinding" answer), because a zPLR CIE declares "L" and every FDE
    ///   under it must carry an LSDA field. The filler can only tell the
    ///   unwinder to KEEP WALKING — it can never dispatch to a wrong pad.
    ///
    /// A module with NO EH function still emits walk-through unwind metadata
    /// when complete layouts are supplied (the production `Compiler` path).
    /// Layout-less legacy callers remain byte-identical to the pre-port emitter.
    fn emit_module_macho_with_unwind(
        &self,
        combined_code: &[u8],
        mut combined_fixups: crate::macho::fixup::FixupList,
        func_offsets: &[(String, u64)],
        func_eh: &[ModuleFunctionEhData],
        frame_layouts: &[Option<crate::frame::FrameLayout>],
        globals: &[ObjectGlobal],
        // Post-codegen IR functions (1:1 and same order as `func_offsets` /
        // `func_eh`), threaded solely to emit DWARF debug sections when
        // `self.config.emit_debug` is set. Their per-instruction `source_loc`s
        // and `debug_meta` feed the `__DWARF` line program / subprograms.
        functions: &[IrMachFunction],
        // Per-function symbol binding, 1:1 with `func_offsets` when non-empty.
        // Empty means every definition is global, which is what every legacy
        // caller passes and what keeps their output byte-identical.
        bindings: &[FunctionSymbolBinding],
    ) -> Result<Vec<u8>, PipelineError> {
        use crate::macho::MachOWriter;
        use crate::macho::reloc::Relocation;
        use crate::unwind::{
            CompactUnwindEntry, CompactUnwindSection, add_compact_unwind_to_writer,
        };

        let mut writer = MachOWriter::new();
        writer.add_text_section_with_align(
            combined_code,
            u32::from(aarch64_module_text_align_log2(functions)),
        );

        let module_has_eh = func_eh.iter().any(|f| f.lsda.is_some());
        // Unwind tables are not only for EH modules: an exception (or Rust
        // panic) raised BELOW a plain trust-cg frame must be able to unwind
        // THROUGH it to an outer handler. A frame with no unwind entry stops
        // phase-1 unwinding dead (the unwinder cannot restore FP/LR/SP past
        // it) and the process terminates — the cross-module face of the
        // FUZZ-7 [TCG-EH-WALK] class. So: whenever the caller threads a
        // complete set of frame layouts (the real `Compiler` path always
        // does), emit walk-through unwind entries for every function even
        // when nothing in the module catches. EH modules keep the stricter
        // rule: missing layouts FAIL CLOSED inside the planner. Layout-less
        // legacy callers (direct `compile_module*` API users) keep the old
        // no-unwind-section output.
        let layouts_complete = !func_eh.is_empty()
            && (0..func_eh.len()).all(|i| frame_layouts.get(i).is_some_and(|l| l.is_some()));

        // Whole-module unwind planning + section/symbol CREATION happens BEFORE
        // `add_module_symbols_for_fixups` computes final nlist indices: the
        // LSDA / EH_Frame locals and the personality undefined shift the final
        // dysymtab order, so every symbol must exist before any index is read
        // (the same critical ordering the single-function `emit_macho`
        // documents).
        let eh_emission = if module_has_eh || layouts_complete {
            Some(self.plan_module_unwind_sections(
                &mut writer,
                func_offsets,
                func_eh,
                frame_layouts,
            )?)
        } else {
            None
        };

        // Add defined function symbols and undefined external symbols needed by
        // branch fixups. Track final nlist indices for fixup resolution.
        let symbol_map = add_module_symbols_for_fixups(
            &mut writer,
            func_offsets,
            globals,
            &combined_fixups,
            bindings,
        )?;

        // Resolve named symbol fixups to numeric indices, then convert fixups
        // to relocations.
        combined_fixups.resolve_named_symbols(|name| {
            // Try bare name first (e.g., "func_b"), then mangled ("_func_b").
            symbol_map.get(name).copied().or_else(|| {
                let mangled = macho_symbol_name(name);
                symbol_map.get(&mangled).copied()
            })
        })?;

        let relocations = combined_fixups.resolve_to_relocations()?;
        for reloc in relocations {
            writer.add_relocation(0, reloc)?; // section 0 = __text
        }

        // Emit the unwind entries + relocations now that the symbol table is
        // final (all indices below are final nlist indices).
        if let Some(plan) = eh_emission {
            // `None` for a walk-through-only module: nothing below may then
            // reference a personality (fail-closed at each use site).
            let personality_index: Option<u32> = match plan.personality_symbol {
                Some(symbol) => Some(final_macho_symbol_index(
                    &mut writer,
                    symbol,
                    "module personality unwind emission",
                )?),
                None => None,
            };
            let require_personality = |index: Option<u32>| -> Result<u32, PipelineError> {
                index.ok_or_else(|| {
                    PipelineError::Encoding(
                        "module unwind emission: an EH entry needs a personality \
                         routine but the module planned none (fail-closed)"
                            .to_string(),
                    )
                })
            };
            let function_index = |i: usize| -> Result<u32, PipelineError> {
                let name = &func_offsets[i].0;
                symbol_map
                    .get(name)
                    .copied()
                    .or_else(|| symbol_map.get(&macho_symbol_name(name)).copied())
                    .ok_or_else(|| {
                        PipelineError::Encoding(format!(
                            "module unwind emission: no symbol for function `{name}`"
                        ))
                    })
            };

            // One compact unwind entry per function (ld64's primary unwind
            // input). DWARF-mode entries carry no personality/LSDA fields —
            // ld64 reads both from the FDE.
            let mut cu_section = CompactUnwindSection::new();
            for (i, f) in func_eh.iter().enumerate() {
                let mut entry = CompactUnwindEntry::new(
                    0, // function_offset baked 0; relocated against the fn's own symbol
                    f.code_len,
                    plan.encodings[i].encoding,
                    function_index(i)?,
                );
                if !plan.encodings[i].needs_dwarf_fallback() && f.lsda.is_some() {
                    entry = entry.with_personality_symbol(require_personality(personality_index)?);
                    let lsda_symbol = plan.lsda_symbols[i].ok_or_else(|| {
                        PipelineError::Encoding(format!(
                            "module unwind emission: EH function `{}` has no LSDA symbol",
                            func_offsets[i].0
                        ))
                    })?;
                    entry = entry.with_lsda_symbol(final_macho_symbol_index(
                        &mut writer,
                        lsda_symbol,
                        "module LSDA unwind emission",
                    )?);
                }
                cu_section.add_entry(entry);
            }
            add_compact_unwind_to_writer(&mut writer, &cu_section)?;

            if let Some(dwarf) = plan.dwarf {
                let eh_frame_index = final_macho_symbol_index(
                    &mut writer,
                    dwarf.eh_frame_symbol,
                    "module EH frame relocation emission",
                )?;
                if let Some(offset) = dwarf.cfi.cie_personality_relocation_offset() {
                    let offset = checked_aarch64_macho_relocation_offset(
                        "<module>",
                        "CIE personality relocation offset",
                        offset,
                    )?;
                    writer.add_relocation(
                        dwarf.eh_frame_section,
                        Relocation::pointer_to_got_pcrel(
                            offset,
                            require_personality(personality_index)?,
                        ),
                    )?;
                }
                for (k, pc_begin_offset) in dwarf
                    .cfi
                    .fde_pc_begin_relocation_offsets()
                    .into_iter()
                    .enumerate()
                {
                    let i = dwarf.fde_functions[k];
                    let pc_begin_offset = checked_aarch64_macho_relocation_offset(
                        &func_offsets[i].0,
                        "FDE PC-begin relocation offset",
                        pc_begin_offset,
                    )?;
                    writer.add_relocation(
                        dwarf.eh_frame_section,
                        Relocation::subtractor(pc_begin_offset, eh_frame_index, 3),
                    )?;
                    writer.add_relocation(
                        dwarf.eh_frame_section,
                        Relocation::unsigned_ptr(pc_begin_offset, function_index(i)?),
                    )?;
                }
                // LSDA slots exist for every FDE exactly when the CIE is zPLR,
                // so the k-th offset belongs to the k-th FDE's function.
                for (k, lsda_offset) in dwarf
                    .cfi
                    .fde_lsda_relocation_offsets()
                    .into_iter()
                    .enumerate()
                {
                    let i = dwarf.fde_functions[k];
                    let lsda_offset = checked_aarch64_macho_relocation_offset(
                        &func_offsets[i].0,
                        "FDE LSDA relocation offset",
                        lsda_offset,
                    )?;
                    let lsda_symbol = plan.lsda_symbols[i].ok_or_else(|| {
                        PipelineError::Encoding(format!(
                            "module unwind emission: FDE for `{}` has an LSDA slot but \
                             no LSDA symbol",
                            func_offsets[i].0
                        ))
                    })?;
                    let lsda_index = final_macho_symbol_index(
                        &mut writer,
                        lsda_symbol,
                        "module FDE LSDA relocation emission",
                    )?;
                    writer.add_relocation(
                        dwarf.eh_frame_section,
                        Relocation::subtractor(lsda_offset, eh_frame_index, 3),
                    )?;
                    writer.add_relocation(
                        dwarf.eh_frame_section,
                        Relocation::unsigned_ptr(lsda_offset, lsda_index),
                    )?;
                }
            }
        }

        // Emit DWARF debug sections when debug info is requested. Unlike the
        // single-function `emit_macho`, the unwind path fuses every function
        // into one `__text` section, so the compilation unit carries one
        // `DW_TAG_subprogram` per function whose `low_pc` is the function's byte
        // offset within `__text` and whose `.debug_line` rows are shifted by the
        // same offset (o-local addresses). The DWARF address fields carry
        // `ARM64_RELOC_UNSIGNED` relocations against `__text`; ld combines
        // those with the STABS debug map (N_OSO/N_FUN) synthesized from the
        // object's function symbols so the o-local PCs become final linked
        // addresses. This is what lets a forced backtrace resolve
        // `file:line:col` for panic=unwind (EH) modules, which always route
        // here.
        if self.config.emit_debug && !functions.is_empty() {
            use crate::dwarf_info::{
                DwarfDebugInfo, FunctionDebugInfo, SourceLanguage, add_debug_info_to_writer,
            };

            // Compilation-unit source file: the first function carrying a real
            // stamped path (module `files` table via adapter debug_meta); the
            // adapter always leaves a synthetic `<module>.rs` fallback.
            let cu_source_file = functions
                .iter()
                .find_map(|f| f.debug_meta.source_file.clone())
                .unwrap_or_else(|| "unknown.rs".to_string());

            let mut debug_info = DwarfDebugInfo::new(&cu_source_file, ".", SourceLanguage::Rust);
            debug_info.add_standard_types();

            for (i, func) in functions.iter().enumerate() {
                // `func_offsets` / `func_eh` are 1:1 and same-order as `functions`.
                let low_pc = func_offsets.get(i).map(|(_, off)| *off).unwrap_or(0);
                let size = func_eh.get(i).map(|e| e.code_len).unwrap_or(0);

                // Per-instruction line rows (intra-function, 4-byte-stride
                // heuristic — same source as `emit_macho`'s no-provenance path),
                // shifted to o-local `__text` addresses by the function offset.
                let mut line_entries = build_source_line_entries(func, None);
                for e in &mut line_entries {
                    e.address = e.address.saturating_add(low_pc);
                }

                let symbol_name = format!("_{}", func.name);
                let decl_line = if func.debug_meta.decl_line > 0 {
                    func.debug_meta.decl_line as u16
                } else {
                    1
                };

                debug_info.add_function(FunctionDebugInfo {
                    name: func.name.clone(),
                    linkage_name: Some(symbol_name),
                    low_pc,
                    size,
                    params: vec![],
                    variables: vec![],
                    scopes: vec![],
                    line_entries,
                    decl_file: 1,
                    decl_line,
                });
            }

            add_debug_info_to_writer(&mut writer, &debug_info)
                .map_err(|err| PipelineError::Encoding(format!("DWARF emission failed: {err}")))?;
        }

        Ok(writer.write()?)
    }

    /// Build the `__gcc_except_tab` / `__eh_frame` sections and their symbols
    /// for an EH-carrying module, and compute each function's compact unwind
    /// encoding. Fails closed when a function is missing its frame layout
    /// (every frame needs an unwind entry — see
    /// [`emit_module_macho_with_unwind`](Self::emit_module_macho_with_unwind)).
    fn plan_module_unwind_sections(
        &self,
        writer: &mut crate::macho::MachOWriter,
        func_offsets: &[(String, u64)],
        func_eh: &[ModuleFunctionEhData],
        frame_layouts: &[Option<crate::frame::FrameLayout>],
    ) -> Result<ModuleUnwindPlan, PipelineError> {
        use crate::dwarf_cfi::{DwarfCfiSection, DwarfFde};
        use crate::exception_handling::generate_lsda_from_pads;
        use crate::macho::constants::S_REGULAR;

        // Every frame must be describable: a function without a layout would
        // get NO unwind entry, i.e. an unwalkable frame (the exact hole this
        // emission closes). Fail closed, never a silent drop.
        for (i, (name, _)) in func_offsets.iter().enumerate() {
            if frame_layouts.get(i).is_none_or(|layout| layout.is_none()) {
                return Err(PipelineError::Encoding(format!(
                    "module carries exception-handling structure, so EVERY function \
                     needs an unwind-table entry (a frame without one stops unwinding \
                     at phase 1 — skipped cleanup Drops at run time), but no frame \
                     layout was provided for `{name}`. Thread per-function frame \
                     layouts via compile_module_with_globals_and_layouts (fail-closed)."
                )));
            }
        }
        let layout = |i: usize| -> &crate::frame::FrameLayout {
            frame_layouts[i].as_ref().expect("checked above")
        };

        // One personality per module: the shared CIE and the synthetic filler
        // LSDAs have a single personality slot. Distinct personalities in one
        // module would need per-personality CIEs — fail closed until needed.
        let mut personalities: Vec<&str> = func_eh
            .iter()
            .filter_map(|f| {
                f.lsda.as_ref().map(|(_, p)| {
                    crate::exception_handling::canonical_personality_symbol(p.as_str())
                })
            })
            .collect();
        personalities.sort_unstable();
        personalities.dedup();
        let personality: Option<String> = match personalities.as_slice() {
            // No EH function: walk-through-only unwind entries (frame
            // descriptions without pads) reference no personality at all.
            [] => None,
            [single] => Some((*single).to_string()),
            multiple => {
                return Err(PipelineError::Encoding(format!(
                    "module unwind emission supports one personality routine per \
                     module (single shared CIE); found {multiple:?} (fail-closed)"
                )));
            }
        };

        let encodings: Vec<crate::frame::CompactUnwindEncoding> = (0..func_eh.len())
            .map(|i| crate::frame::encode_compact_unwind(layout(i)))
            .collect();
        // zPLR CIE required iff an EH function itself needs the DWARF fallback
        // (its LSDA then rides on its FDE, and the CIE must declare P+L).
        let dwarf_has_eh = func_eh
            .iter()
            .zip(&encodings)
            .any(|(f, enc)| f.lsda.is_some() && enc.needs_dwarf_fallback());

        // `__TEXT,__gcc_except_tab`: real LSDAs for EH functions; synthetic
        // ALL-FILLER LSDAs for non-EH functions that get an FDE under a zPLR
        // CIE (every FDE under "L" must carry an LSDA; the filler's single
        // `landing_pad == 0` region over `[0, code_len)` reads as "continue
        // unwinding" — it can never dispatch to a wrong pad).
        let mut lsda_data: Vec<u8> = Vec::new();
        let mut lsda_offsets: Vec<Option<u32>> = vec![None; func_eh.len()];
        for (i, f) in func_eh.iter().enumerate() {
            let bytes: Option<Vec<u8>> = match &f.lsda {
                Some((lsda, _)) => Some(lsda.clone()),
                None if dwarf_has_eh && encodings[i].needs_dwarf_fallback() => {
                    // `dwarf_has_eh` implies some function has an LSDA, and
                    // every LSDA carries a personality, so `personality` is
                    // `Some` here — keep the guard fail-closed anyway.
                    let personality = personality.as_deref().ok_or_else(|| {
                        PipelineError::Encoding(format!(
                            "synthetic filler LSDA for module function {} needs a \
                             personality routine but the module has none (fail-closed)",
                            func_offsets[i].0
                        ))
                    })?;
                    let bytes = generate_lsda_from_pads(personality, &[], &[(0, f.code_len, 0)])
                        .map_err(|error| {
                            PipelineError::Encoding(format!(
                                "synthetic filler LSDA for module function {} is invalid: {error}",
                                func_offsets[i].0
                            ))
                        })?;
                    Some(bytes)
                }
                None => None,
            };
            if let Some(bytes) = bytes {
                // 4-byte align each LSDA within the section (matching the
                // section's 2^2 alignment; LSDA offsets are symbol-addressed).
                let max_growth = checked_aarch64_size_sum(
                    &func_offsets[i].0,
                    "LSDA section growth",
                    bytes.len(),
                    3,
                )?;
                checked_aarch64_size_sum(
                    &func_offsets[i].0,
                    "LSDA section byte length",
                    lsda_data.len(),
                    max_growth,
                )?;
                lsda_data.try_reserve(max_growth).map_err(|error| {
                    PipelineError::Encoding(format!(
                        "LSDA section allocation for `{}` failed: {error}",
                        func_offsets[i].0
                    ))
                })?;
                while !lsda_data.len().is_multiple_of(4) {
                    lsda_data.push(0);
                }
                lsda_offsets[i] = Some(checked_aarch64_object_u32(
                    &func_offsets[i].0,
                    "LSDA section offset",
                    lsda_data.len(),
                )?);
                lsda_data.extend_from_slice(&bytes);
            }
        }
        let mut lsda_symbols: Vec<Option<usize>> = vec![None; func_eh.len()];
        if !lsda_data.is_empty() {
            let lsda_section = writer.add_custom_section(
                b"__gcc_except_tab",
                b"__TEXT",
                &lsda_data,
                2, // 2^2 = 4-byte alignment (matching LLVM)
                S_REGULAR,
            );
            for (i, offset) in lsda_offsets.iter().enumerate() {
                if let Some(offset) = offset {
                    let name = format!("_GCC_except_table_{}", func_offsets[i].0);
                    lsda_symbols[i] = Some(writer.add_symbol(
                        &name,
                        lsda_section + 1,
                        u64::from(*offset),
                        false,
                    )?);
                }
            }
        }

        // `__TEXT,__eh_frame`: one FDE per DWARF-fallback function under the
        // module's single shared CIE, with the self-relative addends baked
        // exactly as the single-function path does.
        let mut dwarf = None;
        if encodings.iter().any(|enc| enc.needs_dwarf_fallback()) {
            let mut cfi = if dwarf_has_eh {
                DwarfCfiSection::new_aarch64_with_eh()
            } else {
                DwarfCfiSection::new()
            };
            let mut fde_functions: Vec<usize> = Vec::new();
            for (i, f) in func_eh.iter().enumerate() {
                if !encodings[i].needs_dwarf_fallback() {
                    continue;
                }
                let mut fde = DwarfFde::from_layout(layout(i), 0, f.code_len, 0);
                if dwarf_has_eh {
                    fde = fde.with_lsda();
                }
                cfi.add_fde(fde);
                fde_functions.push(i);
            }
            let mut eh_frame = cfi.to_bytes();
            // ld64's arm64 `__eh_frame` reader parses entries up to the SECTION
            // BOUNDS and rejects the ELF-style zero-length terminator entry with
            // "empty CIE" (Apple's own toolchain emits no terminator on Mach-O).
            // Strip the 4 trailing zero bytes before emission; the roundtrip
            // checker and internal serialization keep the terminator, and every
            // relocation-patch offset below lies before it.
            if eh_frame.len() >= 4 && eh_frame[eh_frame.len() - 4..] == [0, 0, 0, 0] {
                eh_frame.truncate(eh_frame.len() - 4);
            }
            if !eh_frame.is_empty() {
                const EH_FRAME_FLAGS: u32 = 0x6800_000B;
                for pc_begin_offset in cfi.fde_pc_begin_relocation_offsets() {
                    let addend = -(i64::from(pc_begin_offset));
                    let offset = pc_begin_offset as usize;
                    eh_frame[offset..offset + 8].copy_from_slice(&addend.to_le_bytes());
                }
                for lsda_offset in cfi.fde_lsda_relocation_offsets() {
                    let addend = -(i64::from(lsda_offset));
                    let offset = lsda_offset as usize;
                    eh_frame[offset..offset + 8].copy_from_slice(&addend.to_le_bytes());
                }
                let eh_frame_section = writer.add_custom_section(
                    b"__eh_frame",
                    b"__TEXT",
                    &eh_frame,
                    3, // 2^3 = 8-byte alignment
                    EH_FRAME_FLAGS,
                );
                let eh_frame_symbol =
                    writer.add_symbol("EH_Frame", eh_frame_section + 1, 0, false)?;
                dwarf = Some(ModuleUnwindDwarf {
                    cfi,
                    eh_frame_section,
                    eh_frame_symbol,
                    fde_functions,
                });
            }
        }

        let personality_symbol = match &personality {
            Some(personality) => Some(writer.add_symbol(&format!("_{personality}"), 0, 0, true)?),
            None => None,
        };

        Ok(ModuleUnwindPlan {
            personality_symbol,
            lsda_symbols,
            encodings,
            dwarf,
        })
    }

    // --- Phase implementations ---

    /// Phase 1: Run instruction selection on the input function.
    ///
    /// When `proof_ctx` is provided, returns the ISel value map alongside
    /// the function so the caller can propagate proof annotations to the IR.
    fn run_isel(
        &self,
        input: &trust_cg_lower::Function,
        proof_ctx: Option<&trust_cg_lower::ProofContext>,
    ) -> Result<
        (
            trust_cg_lower::isel::ISelFunction,
            Option<
                std::collections::HashMap<
                    trust_cg_lower::instructions::Value,
                    trust_cg_lower::isel::ISelOperand,
                >,
            >,
        ),
        PipelineError,
    > {
        use trust_cg_lower::isel::InstructionSelector;

        input.validate_eh_structure().map_err(|reason| {
            PipelineError::ISel(format!(
                "invalid exception-handling structure in `{}`: {reason}",
                input.name
            ))
        })?;

        let sig = trust_cg_lower::function::Signature {
            params: input.signature.params.clone(),
            returns: input.signature.returns.clone(),
        };

        let mut isel = InstructionSelector::new(input.name.clone(), sig.clone());

        // Propagate stack slot metadata from the LIR function to the ISel.
        isel.set_stack_slots(input.stack_slots.clone());

        // Seed Value->Type hints from the adapter (Call/CallIndirect result
        // types, see #381). Must happen BEFORE select_block_* so that
        // `value_type()` lookups during selection return the true callee
        // return type instead of the I64 default.
        isel.seed_value_types(&input.value_types);

        // Seed pure-callee names so `select_call` can stamp the emitted Bl
        // with `ProofAnnotation::Pure` for SROA partial-escape (#456).
        // A public `Pure` label cannot authorize SROA's partial-escape transform.  Preserve the
        // names in LIR/report metadata, but do not stamp behavior-changing call proof annotations.
        if trust_cg_lower::guard_evidence::validator_guard_replay_authority_available() {
            isel.seed_pure_callees(&input.pure_callees);
        }

        // Seed importer-licensed libm-pure callee names (intrinsic-origin math
        // libcalls). NOT gated on the validator-guard replay authority above:
        // the license authority here is the importer's own verified proof (the
        // llvm.* intrinsic's `speculatable willreturn nounwind memory(none)`
        // attribute set plus module-wide plain-use exclusion), and the stamped
        // `InstFlags::LIBM_PURE_CALL` is metadata consumed only by the gated
        // `loop-dead-pure-sink` pass — it never authorizes SROA/DCE/reordering.
        isel.seed_libm_pure_callees(&input.libm_pure_callees);

        // Whole-function pre-scan for Iconst origins. Enables cross-block
        // rematerialization in `use_value` so an SSA constant defined in one
        // block can be reused in any non-dominated successor.
        isel.seed_iconst_origins(input.blocks.values().map(|bb| bb.instructions.as_slice()));

        // Whole-function value use counts: the idiom-fusion analyses
        // (overflow/smulh/bitreverse/mul-add) skip pattern-intermediate defs
        // and MUST see cross-block uses (branch-arg edge copies) to keep that
        // sound — the miniz_oxide `inflate::core::transfer` madd-fusion class
        // ("value ... not defined before use"). See
        // `InstructionSelector::value_use_counts`.
        isel.seed_function_value_use_counts(input);

        // Lower formal arguments at entry: copies ABI physical registers into
        // VRegs and populates the value_map for function parameters.
        isel.lower_formal_arguments(&sig, input.entry_block)
            .map_err(|e| PipelineError::ISel(e.to_string()))?;

        let block_order = input.layout_order();

        // Process blocks in layout order. For non-entry blocks, define block
        // parameter Values before processing instructions.

        let _t_loop_start = std::time::Instant::now();
        for block_ref in &block_order {
            let _t_block = std::time::Instant::now();
            let basic_block = &input.blocks[block_ref];
            if *block_ref != input.entry_block && !basic_block.params.is_empty() {
                isel.define_block_params(&basic_block.params);
            }
            let trust_ir_origins = input
                .trust_ir_origins
                .get(block_ref)
                .map(Vec::as_slice)
                .unwrap_or(&[]);
            isel.select_block_with_provenance(
                *block_ref,
                &basic_block.instructions,
                &basic_block.source_locs,
                trust_ir_origins,
            )
            .map_err(|e| PipelineError::ISel(e.to_string()))?;
            let _d = _t_block.elapsed().as_millis();
            if _d > 5 && std::env::var_os("TY_TRUST_CG_JIT_PROFILE").is_some() {
                eprintln!("[JIT Profile] block {} took {}ms", block_ref.0, _d);
            }
        }
        if std::env::var_os("TY_TRUST_CG_JIT_PROFILE").is_some() {
            eprintln!(
                "[JIT Profile] run_isel loop total: {:?}",
                _t_loop_start.elapsed()
            );
        }

        if proof_ctx.is_some() || !input.debug_value_bindings.is_empty() {
            let (func, value_map) = isel
                .finalize_with_value_map_and_eh_info(&input.eh_info)
                .map_err(|e| PipelineError::ISel(e.to_string()))?;
            Ok((func, Some(value_map)))
        } else {
            let func = isel
                .finalize_with_eh_info(&input.eh_info)
                .map_err(|e| PipelineError::ISel(e.to_string()))?;
            Ok((func, None))
        }
    }

    /// Phase 3: Run optimization passes and instruction scheduling.
    ///
    /// After the main optimization pipeline, runs pre-register-allocation
    /// instruction scheduling. The scheduler variant depends on the
    /// optimization level:
    ///
    /// - **O0**: No scheduling (fastest compile).
    /// - **O1**: [`trust_cg_opt::scheduler::InstructionScheduler`] (fast, ILP-focused).
    /// - **O2/O3**: [`trust_cg_opt::scheduler::PressureAwareScheduler`]
    ///   (balances ILP with register pressure to reduce spills).
    fn run_optimization_checked(
        &self,
        func: &mut IrMachFunction,
    ) -> Result<trust_cg_opt::PassStats, PipelineError> {
        let function = func.name.clone();
        catch_optimization_invariant(function, || self.run_optimization(func))
    }

    fn run_optimization_with_proof_metadata_checked(
        &self,
        func: &mut IrMachFunction,
        proof_metadata: Option<trust_cg_opt::proof_opts::ProofOptimizationMetadata>,
        provenance: Option<&mut trust_cg_ir::ProvenanceMap>,
    ) -> Result<trust_cg_opt::PassStats, PipelineError> {
        let function = func.name.clone();
        catch_optimization_invariant(function, || {
            self.run_optimization_with_proof_metadata(func, proof_metadata, provenance)
        })
    }

    fn run_optimization_with_proof_metadata_and_gate_checked(
        &self,
        func: &mut IrMachFunction,
        proof_metadata: Option<trust_cg_opt::proof_opts::ProofOptimizationMetadata>,
        provenance: Option<&mut trust_cg_ir::ProvenanceMap>,
        kernel_gate: Option<(
            trust_cg_ir::DischargedEvidenceTable,
            std::collections::HashMap<InstId, (u128, Option<u128>)>,
        )>,
    ) -> Result<trust_cg_opt::PassStats, PipelineError> {
        let function = func.name.clone();
        catch_optimization_invariant(function, || {
            self.run_optimization_with_proof_metadata_and_gate(
                func,
                proof_metadata,
                provenance,
                kernel_gate,
            )
        })
    }

    fn run_optimization(&self, func: &mut IrMachFunction) -> trust_cg_opt::PassStats {
        self.run_optimization_with_proof_metadata(func, None, None)
    }

    fn run_optimization_with_proof_metadata(
        &self,
        func: &mut IrMachFunction,
        proof_metadata: Option<trust_cg_opt::proof_opts::ProofOptimizationMetadata>,
        provenance: Option<&mut trust_cg_ir::ProvenanceMap>,
    ) -> trust_cg_opt::PassStats {
        if cfg!(test) {
            // Retain the structural proof-pass model for in-crate unit tests.  Downstream and
            // integration builds compile the production branch below.
            return self.run_optimization_with_proof_metadata_and_gate(
                func,
                proof_metadata,
                provenance,
                None,
            );
        }

        // Default/private callers do not carry an exact validator replay capability.  Do not let a
        // caller-supplied sidecar reach proof optimization, and install the empty gate explicitly:
        // `None` would select the legacy label-only guard path.
        self.run_optimization_with_proof_metadata_and_gate(
            func,
            None,
            provenance,
            Some((
                trust_cg_lower::guard_evidence::production_guard_replay_evidence(),
                std::collections::HashMap::new(),
            )),
        )
    }

    fn run_optimization_with_proof_metadata_and_gate(
        &self,
        func: &mut IrMachFunction,
        proof_metadata: Option<trust_cg_opt::proof_opts::ProofOptimizationMetadata>,
        provenance: Option<&mut trust_cg_ir::ProvenanceMap>,
        kernel_gate: Option<(
            trust_cg_ir::DischargedEvidenceTable,
            std::collections::HashMap<InstId, (u128, Option<u128>)>,
        )>,
    ) -> trust_cg_opt::PassStats {
        use trust_cg_opt::pass_manager::MachinePass;
        use trust_cg_opt::pipeline::{OptLevel as OptOptLevel, OptimizationPipeline};
        use trust_cg_opt::scheduler::{InstructionScheduler, PressureAwareScheduler};

        let opt_level = match self.config.opt_level {
            OptLevel::O0 => OptOptLevel::O0,
            OptLevel::O1 => OptOptLevel::O1,
            OptLevel::O2 => OptOptLevel::O2,
            OptLevel::O3 => OptOptLevel::O3,
        };

        // Run the optimization pipeline for the selected level.
        //
        // sincos-merge (Darwin arm64 only) needs to know whether the object
        // target is Mach-O: `___sincos_stret` and its {d0=sin, d1=cos} return
        // ABI are Apple-specific. The historical empty-triple default is AArch64
        // Mach-O (Darwin); every explicit Apple/darwin triple qualifies too.
        let target_is_darwin = self.config.target_triple.is_empty()
            || target_triple_uses_macho(&self.config.target_triple);
        let mut pipeline =
            OptimizationPipeline::new(opt_level).with_target_is_darwin(target_is_darwin);
        if let Some(disabled) = &self.config.disabled_passes_override {
            pipeline = pipeline.with_disabled_passes(disabled.clone());
        }
        if let Some(enabled) = self.config.contains4_scanner_batch_rewrite_override {
            pipeline = pipeline.with_contains4_scanner_batch_rewrite(enabled);
        }
        if self.config.skip_cse_gvn {
            // CSE/GVN extend live ranges on the bet that the allocator will
            // rematerialize under pressure; the JIT-latency profile disables
            // remat, so for these kernels the bet loses and the passes only add
            // spill traffic. The passes are value-preserving, so skipping them
            // is a pure code-quality choice with no effect on results.
            pipeline = pipeline.without_redundancy_elimination();
        }
        if self.certified_pass_execution {
            pipeline = pipeline.with_certified_pass_execution();
        }
        if let Some((evidence, obligations)) = kernel_gate {
            // Route every candidate through the fail-closed kernel policy.
            pipeline = pipeline.with_kernel_gate(evidence, obligations);
        }
        if let Some(metadata) = proof_metadata {
            pipeline = pipeline.with_proof_optimization_metadata(metadata);
        }
        if let Some(profile) = self.profile_use.clone() {
            pipeline = pipeline.with_profile_use(profile);
        }
        let phase_timer = log_pipeline_phase_start(func, "opt-pass-manager");
        let stats = if let Some(provenance) = provenance {
            pipeline.run_with_provenance(func, provenance)
        } else {
            pipeline.run(func)
        };
        log_pipeline_phase_end(func, "opt-pass-manager", phase_timer);

        let phase_timer = log_pipeline_phase_start(func, "cegis-superopt");
        let _ = self.run_cegis_superopt(func);
        log_pipeline_phase_end(func, "cegis-superopt", phase_timer);

        if self.pass_disabled("sched") {
            return stats;
        }

        // Pre-register-allocation instruction scheduling.
        // Skip at O0 for fastest compile. At O1, use the fast ILP scheduler.
        // At O2+, use pressure-aware scheduling by default.
        match self.config.opt_level {
            OptLevel::O0 => {
                // No scheduling at O0.
            }
            OptLevel::O1 => {
                let phase_timer = log_pipeline_phase_start(func, "codegen-scheduler");
                let mut sched = InstructionScheduler;
                sched.run(func);
                log_pipeline_phase_end(func, "codegen-scheduler", phase_timer);
            }
            OptLevel::O2 | OptLevel::O3 => {
                let phase_timer = log_pipeline_phase_start(func, "codegen-scheduler");
                let mut sched = PressureAwareScheduler;
                sched.run(func);
                log_pipeline_phase_end(func, "codegen-scheduler", phase_timer);
            }
        }
        stats
    }

    /// Phase 3.5: Run function-level verification (optional).
    ///
    /// When `self.config.verify` is true and the `verify` feature is enabled,
    /// calls [`trust_cg_verify::verify_function`] on the optimized IR. Returns an
    /// error only if any instruction *fails* verification (i.e., a proof was
    /// found but produced Invalid/Unknown). Unverified instructions (no proof
    /// available) are tolerated — they are expected for opcodes not yet covered
    /// by the proof database.
    ///
    /// When the `verify` feature is disabled, this is a no-op.
    #[cfg(feature = "verify")]
    fn run_verification(&self, func: &IrMachFunction) -> Result<(), PipelineError> {
        // Skip the expensive ProofDatabase construction + evaluation when
        // verification is disabled. Previously we always ran verify_function()
        // and only checked the result when config.verify was true, but
        // ProofDatabase::new() alone consumes significant stack space in debug
        // builds (hundreds of proof obligations with SmtExpr trees), which
        // contributed to stack overflows on the default 8 MB test-thread stack.
        // See issue #205.
        if !self.function_verification_selected(&func.name) {
            return Ok(());
        }

        let report = crate::jit_cert::run_on_proof_verifier_stack(
            "trust-cg-pipeline-proof-verifier",
            || trust_cg_verify::verify_function(func),
        );
        Self::enforce_verification_report(report)
    }

    /// Fail-closed translation of a per-instruction verification report into
    /// the pipeline verdict: any FAILED instruction (a bound proof that
    /// refuted) rejects the compile; unverified/skipped instructions are
    /// tolerated (expected for opcodes without proof coverage).
    ///
    /// Split out of [`Self::run_verification`] so tests can drive the exact
    /// enforcement path with a refuted report — `verify_function` cannot be
    /// made to refute on well-formed input from here (the refutation content
    /// lives in trust-cg-verify's reconstruction/TV-2 layers), so the
    /// corrupted-lowering harness injects the report it produces.
    #[cfg(feature = "verify")]
    fn enforce_verification_report(
        report: trust_cg_verify::FunctionVerificationReport,
    ) -> Result<(), PipelineError> {
        if report.failed_count() > 0 {
            return Err(PipelineError::VerificationFailed {
                function: report.function_name.clone(),
                failures: report.failed_count(),
                coverage: report.coverage_percent(),
                report,
            });
        }

        Ok(())
    }

    /// Stub when `verify` feature is disabled — verification is a no-op,
    /// EXCEPT under [`DispatchVerifyMode::Sampled`]: a caller that opted into
    /// sampled verification must not get a silent no-op (fail closed). The
    /// legacy `verify = true` + no-feature combination keeps its historical
    /// silent-skip behaviour.
    #[cfg(not(feature = "verify"))]
    fn run_verification(&self, func: &IrMachFunction) -> Result<(), PipelineError> {
        if self.config.verify_dispatch.samples_function(&func.name) {
            return Err(PipelineError::SampledVerifyUnavailable {
                function: func.name.clone(),
            });
        }
        Ok(())
    }

    /// Whether phase 3.5 function-level verification runs for `name`:
    /// either full verification (`config.verify`) or the deterministic
    /// [`DispatchVerifyMode::Sampled`] sample selects it.
    fn function_verification_selected(&self, name: &str) -> bool {
        self.config.verify || self.config.verify_dispatch.samples_function(name)
    }

    /// Phase 4-6: Run register allocation and apply results.
    ///
    /// Returns the spill-slot count and a small post-rebuild snapshot used by
    /// debug provenance seeding to distinguish allocated values from spills.
    fn run_regalloc(&self, ir_func: &mut IrMachFunction) -> Result<RegAllocOutcome, PipelineError> {
        rebuild_ir_cfg_edges_from_branch_operands(ir_func);
        // Regalloc phase-internal attribution (Task 3): the pipeline-side seams
        // that bracket the core allocator. Gated on the SAME env var as pass
        // timing (via `trust_cg_time_pipeline_enabled`, which is true under
        // TRUST_CG_TIME_PASSES); cached, so OFF is a single atomic load.
        let ra_time = trust_cg_time_pipeline_enabled();

        // Phase 4: Convert IR to regalloc format
        let t = ra_time.then(Instant::now);
        let mut ra_func = ir_to_regalloc(ir_func)?;
        if let Some(t) = t {
            eprintln!(
                "[trust-cg-time-regalloc] func={} pass=pipeline stage=ir-to-regalloc elapsed_us={}",
                ra_func.name,
                t.elapsed().as_micros()
            );
        }

        // LEVER A (TCG_AARCH64_RA_LOOP_DEPTH, default OFF): the aarch64 path
        // never populates RegAllocBlock::loop_depth (the ir_to_regalloc adapter
        // copies the IR block's 0-stub field), so compute_spill_weight
        // degenerates to static use-density and evicts hot-loop heap bases in
        // favor of remat-eligible constants with many static uses. When the flag
        // is set, fill loop_depth with the CFG's natural-loop nesting depth
        // (dominator/back-edge analysis, deterministic) before liveness/regalloc
        // runs, restoring the 10^depth hot-loop weighting. Mirrors x86's opt-in
        // TCG_X86_RA_LOOP_DEPTH; default OFF => byte-identical to HEAD.
        // LIVE-RANGE SPLITTING (TCG_AARCH64_RA_SPLIT) also needs non-degenerate
        // loop-depth weights, but it populates them TRANSIENTLY inside the
        // regalloc split driver (only the re-allocation pass + KEEP-BETTER metric
        // see them; the depth-0 state is restored whenever the split is declined,
        // so a program the split does not help stays byte-identical to HEAD).
        // Coupling Lever A here at the pipeline level instead would apply it to
        // the FIRST allocation too and regress values it does not help (measured:
        // fannkuch grows reloads under pipeline-level depth). So the split flag is
        // deliberately NOT wired here; only Lever A (TCG_AARCH64_RA_LOOP_DEPTH)
        // is. Both default OFF => byte-identical to HEAD.
        //
        // GREEDY ALLOCATOR (DEFAULT ON since the 2026-07-18 flip; escape hatch
        // TCG_AARCH64_RA_LINEARSCAN=1 restores the legacy LinearScan): selects
        // the LLVM-style Greedy strategy for the aarch64 AOT path (the strategy
        // x86-64 production AOT drives through the same translation validator;
        // splitting is held OFF here — see the config-site comment below for
        // the measured split P0). The greedy eviction heuristics price spill
        // weight at 10^depth, so this ALSO populates loop depths
        // unconditionally (the coherent pair: depth-aware weights are what make
        // greedy's eviction pick the right victims).
        // FLIP EVIDENCE (measured on main at 09674fa, 46-program reliable set,
        // interleaved best-of-5, all bit-exact): geomean 1.0758 -> 1.0275
        // (ON/OFF 0.955); lists 2.12->1.00, ReedSolomon 2.41->1.47, salsa20
        // 1.84->1.20, huffbench 1.97->1.49, dry 1.30->1.19, almabench
        // 1.56->1.48; the ONE >5% regression is matmul_f64_4x4 1.26->1.55
        // (pressure-shuffle class — documented, diagnosis queued); the older
        // sieve +7.7% regression did NOT recur post-branch-forwarding.
        // Compile +1.5% suite / +1-1.7% at scale. Canonical torture with
        // greedy 1064 PASS / 0 MISCOMPILE; zero validator incidents.
        let mut ra_greedy = std::env::var_os("TCG_AARCH64_RA_LINEARSCAN").is_none()
            || std::env::var_os("TCG_AARCH64_RA_GREEDY").is_some();
        if ra_greedy || std::env::var_os("TCG_AARCH64_RA_LOOP_DEPTH").is_some() {
            let t = ra_time.then(Instant::now);
            trust_cg_regalloc::populate_loop_depths(&mut ra_func);
            if let Some(t) = t {
                eprintln!(
                    "[trust-cg-time-regalloc] func={} pass=pipeline stage=loop-depth elapsed_us={}",
                    ra_func.name,
                    t.elapsed().as_micros()
                );
            }
        }

        // LOOP-FREE ALLOCATOR ROUTING (default ON alongside the greedy flip;
        // escape hatch TCG_AARCH64_RA_GREEDY_ALWAYS=1 forces greedy even here):
        // route functions with NO natural loops back to LinearScan.
        //
        // WHY. Greedy's ONE >5% regression under the 2026-07-18 flip is
        // matmul_f64_4x4 (1.26 -> 1.57 end-to-end). Disasm-grounded root cause,
        // a three-line chain that ONLY fires in loop-free straight-line code:
        //   (1) spill weight degenerates to static use-density here — the
        //       10^depth hot-loop term is inert at depth 0 (liveness.rs:596),
        //       so populate_loop_depths above leaves every block at depth 0;
        //   (2) greedy processes intervals in density order, so the long
        //       multi-use whole-block FMA-chain intervals are handled LAST, and
        //       can_evict (greedy.rs:884) is unwinnable for a whole-block span —
        //       every preg already hosts a denser short temp somewhere on the
        //       span, so nothing can be evicted;
        //   (3) splitting is held OFF here (the fail-silent split P0 documented
        //       at the config site below), so the loser is whole-vreg spilled
        //       with a reload materialized INTO each FMA use (21 spill ops vs
        //       LinearScan's 8). LinearScan's positional (program-order)
        //       processing handles straight-line register pressure correctly.
        //
        // ZERO-RISK TO THE FLIP EVIDENCE. Every measured >5% flip WIN
        // (lists / ReedSolomon / salsa20 / huffbench / dry / almabench) is
        // loop-DRIVEN, i.e. max loop depth > 0, so those functions keep greedy
        // unchanged. Only loop-free functions — where the flip's own evidence
        // shows greedy has no upside and the one regression — move back.
        //
        // Read mechanism: populate_loop_depths (above, run under the same gate)
        // fills RegAllocBlock::loop_depth with the natural-loop nesting count;
        // a simple max over blocks == 0 means the function has no natural loop.
        // TCG_AARCH64_RA_LINEARSCAN=1 already forces ra_greedy=false everywhere
        // (this block is then a no-op); TCG_AARCH64_RA_GREEDY_ALWAYS=1 opts a
        // loop-free function back INTO greedy for future measurement.
        if ra_greedy && std::env::var_os("TCG_AARCH64_RA_GREEDY_ALWAYS").is_none() {
            let max_loop_depth = ra_func
                .blocks
                .iter()
                .map(|b| b.loop_depth)
                .max()
                .unwrap_or(0);
            if max_loop_depth == 0 {
                ra_greedy = false;
            }
        }

        // Debug: dump block structure before regalloc
        #[cfg(debug_assertions)]
        if std::env::var("TRUST_CG_DEBUG_REGALLOC").is_ok() {
            eprintln!("=== REGALLOC DEBUG: {} ===", ra_func.name);
            for (bi, block) in ra_func.blocks.iter().enumerate() {
                eprintln!(
                    "  block {}: insts={:?} succs={:?} preds={:?}",
                    bi,
                    block.insts.len(),
                    block.succs,
                    block.preds
                );
            }
            for (ii, inst) in ra_func.insts.iter().enumerate() {
                eprintln!(
                    "  inst {}: opc={} defs={:?} uses={:?}",
                    ii,
                    inst.opcode,
                    inst.defs
                        .iter()
                        .filter_map(|o| o.as_vreg())
                        .collect::<Vec<_>>(),
                    inst.uses
                        .iter()
                        .filter_map(|o| o.as_vreg())
                        .collect::<Vec<_>>()
                );
            }
        }

        // Phase 5: Run the allocator
        let mut ra_config = if self.config.enable_jit_fast_regalloc {
            // Latency-tuned profile for in-process JIT shapes: coalescing,
            // splitting, remat, and slot reuse off. Runs on the LinearScan
            // core, which carries the defensive `active_allocation_overlaps`
            // interference guard, so the JIT and AOT allocators share one
            // correct code path. The disabled passes are what cost time, not
            // the strategy. See AllocConfig::jit_latency_aarch64.
            trust_cg_regalloc::AllocConfig::jit_latency_aarch64()
        } else if ra_greedy {
            // GREEDY ALLOCATOR SWITCH (TCG_AARCH64_RA_GREEDY): LLVM-style greedy
            // eviction-based allocation, the strategy x86-64 production AOT
            // uses. Loop depths were populated above under the same gate so the
            // greedy spill-weight eviction sees the 10^depth hot-loop signal.
            //
            // LIVE-RANGE SPLITTING (TCG_AARCH64_RA_SPLITTING=1, default OFF): x86
            // runs greedy WITH splitting in production; aarch64 now can too, but
            // behind an opt-in gate while the exec evidence is gathered. (Distinct
            // from TCG_AARCH64_RA_SPLIT, which gates the separate LinearScan-side
            // gap-split experiment in trust_cg_regalloc::try_allocate; this flag
            // gates the GREEDY allocate_with_splitting path.)
            //
            // HISTORY. Measured 2026-07-18, greedy `allocate_with_splitting` on
            // this pipeline SILENTLY MISCOMPILED — a split piece's spill-slot
            // store landed on one CFG path while a reload sat on a path the store
            // did not dominate, so the reload read an uninitialized slot (repros:
            // gcc-c-torture 990628-1.c SIGSEGV; ReedSolomon rsdec_204 NULL heap
            // base). TWO things have since landed that unblock this:
            //   (1) the regalloc translation validator's slot-initialization
            //       dominance gate (`check_slot_init_dominance`, 029393b) — a
            //       reload not dominated by a store on EVERY path is now a NAMED
            //       compile error, so the class is fail-CLOSED, never silent;
            //   (2) this materialization now anchors a split connector's store at
            //       the PSEUDO_COPY split boundary (the def site of the spilled
            //       split child), which the splitter's own CFG-safety rules make
            //       dominate every reload of that piece — see
            //       `retained_spill_materialization_sites` /
            //       `materialize_spilled_operands_at_sites`.
            // The validator gate is the oracle and stays always-on regardless of
            // this flag: if a placement is ever wrong, the compile fails closed.
            //
            // SPLITTING FLIP CAMPAIGN (measured 2026-07-22, aarch64 native, this
            // release dylib, certs-off, best-of-11..15). A/B over the 18-prog
            // beat-llvm suite + the 7-prog gt set, three ways: forced LinearScan
            // (TCG_AARCH64_RA_LINEARSCAN=1), default adaptive greedy, and
            // greedy+splitting (this flag). Result: NO-GO — splitting stays
            // default-OFF.
            //   * CORRECTNESS: 25 progs x 3 strategies, zero exit mismatches,
            //     zero compile-fails, zero regalloc-validator false positives.
            //     Splitting's historically fail-SILENT class (the 2026-07-18
            //     990628-1 / rsdec_204 miscompiles noted above) came back
            //     fail-CLEAN here — the dominance gate + anchored materialization
            //     hold across the whole corpus.
            //   * PERF: on the noise-clean compute-dominated subset (LLVM>=30ms,
            //     11 progs) geomean vs LLVM was split 0.9545 < greedy 0.9642 <
            //     linear-scan 0.9700 — so greedy correctly beats LinearScan
            //     (re-confirms the d9ecd29d flip on this corpus too), and
            //     splitting adds only ~1% on top, almost entirely v1_saxpy
            //     (~8% real, held across reruns) while p1_xorshift slightly
            //     regresses and the sub-10ms micro-progs (h1/v2/v3) swing >20%
            //     run-to-run (startup-noise-dominated, not codegen signal).
            //   * p4_matmul, the benchmark that motivated the regalloc frontier,
            //     is RA-INVARIANT: linear-scan == greedy == greedy+split == 83ms
            //     (~2.8x LLVM). Its gap is the audited auto-vectorization loss,
            //     not register allocation — splitting does nothing for its
            //     24-accumulator inner loop.
            // A ~1%, single-benchmark-carried, noise-adjacent win does not clear
            // the bar to flip a previously-miscompiling default on by default, so
            // splitting remains opt-in behind this flag pending a higher-pressure
            // corpus (lists / ReedSolomon / salsa20 class) where it can show a
            // broad-based win.
            let mut cfg = trust_cg_regalloc::AllocConfig::greedy_aarch64();
            cfg.enable_splitting = std::env::var_os("TCG_AARCH64_RA_SPLITTING").is_some();
            cfg
        } else {
            trust_cg_regalloc::AllocConfig::default_aarch64()
        };
        // AArch64 post-RA rematerialization inside the allocator is left OFF: on
        // this pipeline the allocator does NOT assign physical registers to
        // spilled values (they stay VRegs; the pipeline's spill-materialization
        // pass assigns scratch pregs per use-site later). The allocator-side
        // `apply_rematerialization` replaces a spill-reload with a clone of the
        // constant's defining instruction that still carries the spilled VReg as
        // its def, then drops the vreg from `result.spills`; that clone is never
        // materialized to a physical register, so the consuming instruction reads
        // an unresolved VReg the encoder rejects ("unresolved virtual register(s)
        // after regalloc/copy lowering"). Rematerialization of Free (pure integer
        // immediate) spilled constants is instead performed soundly in the
        // pipeline's spill-materialization path, where the reload's scratch preg
        // is already known — see `remat_free_spilled_constants` and its use in
        // `materialize_spilled_operands_at_sites`.
        ra_config.enable_remat = false;
        let t = ra_time.then(Instant::now);
        let result = trust_cg_regalloc::allocate(&mut ra_func, &ra_config)
            .map_err(|e| PipelineError::RegAlloc(e.to_string()))?;
        if let Some(t) = t {
            eprintln!(
                "[trust-cg-time-regalloc] func={} pass=pipeline stage=allocate-core elapsed_us={}",
                ra_func.name,
                t.elapsed().as_micros()
            );
        }
        let spill_slot_count = result.spills.len();

        // SPLIT DIAGNOSTIC (TCG_AARCH64_RA_SPLIT_STATS, default OFF): count
        // spilled vregs that are the DEF of a PSEUDO_COPY split connector — i.e.
        // split PIECES that were spilled, exercising the split-boundary store
        // path this materialization must place dominance-correctly. A whole-vreg
        // spill's def is a real instruction, so it is not counted. Diagnostic
        // only; no effect on codegen.
        if std::env::var_os("TCG_AARCH64_RA_SPLIT_STATS").is_some() && !result.spills.is_empty() {
            use trust_cg_regalloc::machine_types::RegAllocOperand as RaOp;
            let spilled_ids: std::collections::BTreeSet<u32> =
                result.spills.iter().map(|s| s.vreg.id).collect();
            let mut piece_spills = 0usize;
            for inst in &ra_func.insts {
                if inst.opcode == trust_cg_regalloc::phi_elim::PSEUDO_COPY {
                    for d in &inst.defs {
                        if let RaOp::VReg(v) = d
                            && spilled_ids.contains(&v.id)
                        {
                            piece_spills += 1;
                        }
                    }
                }
            }
            eprintln!(
                "[trust-cg-split-stats] func={} spills={} split_piece_spills={}",
                ra_func.name,
                result.spills.len(),
                piece_spills
            );
        }

        // Debug: dump allocation
        #[cfg(debug_assertions)]
        if std::env::var("TRUST_CG_DEBUG_REGALLOC").is_ok() {
            eprintln!("  allocation:");
            let mut allocs: Vec<_> = result.allocation.iter().collect();
            allocs.sort_by_key(|(v, _)| v.id);
            for (vreg, preg) in allocs {
                eprintln!("    v{} -> {:?}", vreg.id, preg);
            }
            let mut spills: Vec<_> = result.spills.iter().map(|spill| spill.vreg.id).collect();
            spills.sort_unstable();
            eprintln!("  spills: {:?}", spills);
            eprintln!("=== END REGALLOC DEBUG ===");
        }

        // Phase 5.5: Post-RA spill optimization — eliminate dead stores,
        // redundant reloads, and dead definitions in spill code. Runs on the
        // regalloc-format function which still has spill pseudo-instructions.
        // Enabled at O1+ optimization levels. The `post_ra` bisect key lets a
        // caller disable it via TRUST_CG_DISABLE_PASSES for debugging.
        let post_ra_enabled =
            self.config.opt_level != OptLevel::O0 && !self.pass_disabled("post_ra");
        if post_ra_enabled {
            let t = ra_time.then(Instant::now);
            let _post_ra_stats = trust_cg_regalloc::post_ra_optimize(&mut ra_func);
            if let Some(t) = t {
                eprintln!(
                    "[trust-cg-time-regalloc] func={} pass=pipeline stage=post-ra-optimize elapsed_us={}",
                    ra_func.name,
                    t.elapsed().as_micros()
                );
            }
        }

        // Phase 5.6: Materialize the allocation on the regalloc-side function and
        // remove redundant physical-register copies before rebuilding IR and
        // lowering Copy pseudos to real MOVs.
        //
        // This now runs for spillful functions too. It used to be gated to
        // spill-free functions, which left high-register-pressure (spillful)
        // functions — exactly the ones that emit the most redundant reg-reg
        // moves — with no post-RA coalescing at all.
        //
        // Coalescing is inherently spill-safe: spilled values stay as VRegs
        // (they are never present in `result.allocation`, so
        // `apply_regalloc_to_regalloc` leaves them untouched), and
        // `post_ra_coalesce` only ever renames or deletes redundant *physical*
        // register copies. VRegs and the PSEUDO_SPILL_LOAD/STORE pseudos (which
        // carry VReg + StackSlot operands and no pregs) are invisible to its
        // liveness and rename logic, so spilled values are never disturbed. The
        // scratch registers used by later spill materialization are reserved and
        // never allocated, so coalescing can neither produce nor depend on them.
        //
        // `retained_spill_materialization_sites` is computed *after* coalescing
        // so each spill site anchors to an instruction that still lives in its
        // block. Computing it first would let a coalesced-away copy become a
        // dangling anchor that the rebuild remap silently drops (losing a spill
        // reload/store). Coalescing removes NOP'd copies from the block
        // instruction lists, so the post-coalesce anchors are always live.
        let mut post_ra_copies_coalesced = 0u32;
        if post_ra_enabled {
            let t = ra_time.then(Instant::now);
            apply_regalloc_to_regalloc(&mut ra_func, &result.allocation);
            let post_ra_coalesce_stats = trust_cg_regalloc::post_ra_coalesce(&mut ra_func);
            post_ra_copies_coalesced = post_ra_coalesce_stats.copies_removed;
            if let Some(t) = t {
                eprintln!(
                    "[trust-cg-time-regalloc] func={} pass=pipeline stage=post-ra-coalesce elapsed_us={}",
                    ra_func.name,
                    t.elapsed().as_micros()
                );
            }
        }
        let spill_sites = retained_spill_materialization_sites(&ra_func, &result.spills);

        // Phase 6: Rebuild the IR from the regalloc-side function so interval
        // splitting, phi elimination, and spill-side rewrites are visible to
        // the encoder path.
        let t = ra_time.then(Instant::now);
        let inst_map = rebuild_ir_from_regalloc_with_map(ir_func, &ra_func)?;
        if let Some(t) = t {
            eprintln!(
                "[trust-cg-time-regalloc] func={} pass=pipeline stage=rebuild-ir elapsed_us={}",
                ra_func.name,
                t.elapsed().as_micros()
            );
        }
        let debug_defs = collect_regalloc_debug_defs(ir_func);
        let mut spill_sites = remap_spill_materialization_sites(spill_sites, &inst_map);
        let effective_spills =
            effective_spills_from_materialization_sites(&spill_sites, &result.spills);

        // Phase 6.5: Apply the allocation back to the rebuilt IR, then
        // materialize any remaining spilled values into that same IR.
        apply_regalloc(ir_func, &result.allocation);
        verify_aarch64_formal_entry_copy_hazards(ir_func)?;
        ensure_spill_stack_slots(ir_func, &effective_spills);
        add_missing_spill_materialization_sites(ir_func, &mut spill_sites, &effective_spills);
        // Free-constant rematerialization: recover the pure-integer-immediate
        // move templates of spilled constants from their (still-VReg) defs
        // BEFORE materialization creates the reloads. This is the sound,
        // scratch-register-aware replacement for allocator-side remat — see the
        // note on `ra_config.enable_remat` above.
        let remat_consts = find_free_remat_spilled_constants(ir_func, &effective_spills);
        let spill_debug_info = materialize_spilled_operands_at_sites(ir_func, &spill_sites)?;
        // Turn each per-iteration reload of a Free constant into a per-iteration
        // recompute (`ldur scratch,[frame]` -> `movz scratch,#imm`), killing the
        // spilled-loop-constant reload traffic.
        let remat_reloads = remat_free_spilled_constant_reloads(ir_func, &remat_consts);
        if remat_reloads > 0 && trust_cg_time_pipeline_enabled() {
            eprintln!(
                "[trust-cg-time-regalloc] func={} pass=pipeline stage=remat-free-const reloads={}",
                ir_func.name, remat_reloads
            );
        }
        // Drop redundant two-copy round-trips before the call-arg fixup so it
        // does not misread a relocation round-trip as a parallel-move swap.
        eliminate_redundant_copy_roundtrips(ir_func);
        fixup_aarch64_call_arg_source_clobbers(ir_func)?;

        // Phase 6.6: Redundant spill-slot reload elision — delete a reload of
        // a regalloc spill slot whose bytes provably still sit in the target
        // scratch register (block-local; see the pass doc for the alias and
        // scratch-liveness proofs). Runs after every reload/store has been
        // materialized and after the copy fixups so the block contents are
        // final. Kill switch TCG_SPILL_RELOAD_CSE_OFF; bisect key
        // `spill_reload_cse`.
        if post_ra_enabled && !self.pass_disabled("spill_reload_cse") {
            let regalloc_spill_slots: BTreeSet<StackSlotId> =
                effective_spills.iter().map(|spill| spill.slot).collect();
            let reloads_elided = elide_redundant_spill_slot_reloads(ir_func, &regalloc_spill_slots);
            if reloads_elided > 0 && trust_cg_time_pipeline_enabled() {
                eprintln!(
                    "[trust-cg-time-regalloc] func={} pass=pipeline stage=spill-reload-cse elided={}",
                    ir_func.name, reloads_elided
                );
            }
        }

        // Phase 6.7: Post-RA branch forwarding. `split_critical_edges` (inside
        // the allocator, after the last CfgSimplify) leaves empty jump-only
        // trampoline blocks on critical edges; `post_ra_coalesce` above then
        // strips their phi copies, so a hot-loop back-edge pays two taken
        // branches per iteration. Retarget every direct branch through such
        // trampolines to their ultimate destination and drop the now-dead
        // trampolines from the layout. Pure branch-target rewrite (no register
        // or instruction changes) and gated with `post_ra` so it only runs when
        // coalescing has actually emptied the trampolines. Kill switch:
        // TRUST_CG_DISABLE_PASSES=branch_forward.
        if post_ra_enabled && !self.pass_disabled("branch_forward") {
            let t = ra_time.then(Instant::now);
            let bf_stats = crate::branch_forward::forward_post_ra_branches(ir_func);
            if let Some(t) = t {
                eprintln!(
                    "[trust-cg-time-regalloc] func={} pass=pipeline stage=branch-forward forwarded={} removed={} elapsed_us={}",
                    ir_func.name,
                    bf_stats.branches_forwarded,
                    bf_stats.trampolines_removed,
                    t.elapsed().as_micros()
                );
            }
        }

        let spill_slots: BTreeMap<_, _> = effective_spills
            .iter()
            .map(|spill| (spill.vreg, spill.slot))
            .collect();
        let spilled_vregs = spill_slots.keys().copied().collect();

        Ok(RegAllocOutcome {
            spill_slot_count,
            post_ra_copies_coalesced,
            debug_snapshot: RegAllocDebugSnapshot {
                allocation: result.allocation,
                spilled_vregs,
                spill_slots,
                spill_stores: spill_debug_info.stores,
                inst_map,
                defs: debug_defs,
            },
        })
    }

    /// Phase 7: Frame lowering — prologue/epilogue + frame index elimination.
    ///
    /// Returns the computed [`FrameLayout`] so downstream phases (compact unwind
    /// emission) can use it without recomputing.
    fn run_frame_lowering(
        &self,
        func: &mut IrMachFunction,
    ) -> Result<crate::frame::FrameLayout, PipelineError> {
        use crate::frame;

        if func.stack_protector.is_enabled() && !self.supports_stack_protector_target() {
            let target = if self.config.target_triple.is_empty() {
                "unknown".to_string()
            } else {
                self.config.target_triple.clone()
            };
            return Err(PipelineError::TargetObjectUnsupported {
                target,
                format: "Mach-O".to_string(),
                reason: "stack canary lowering currently supports only AArch64 Apple Mach-O"
                    .to_string(),
            });
        }

        frame::ensure_stack_protector_slot(func);

        // Compute outgoing arg area size from actual call sites. ISel emits
        // stack-passed arguments as stores with base=SP; scanning those stores
        // yields the high-water mark the caller must reserve at the bottom of
        // its own frame so the stores do not overlap the saved FP/LR pair
        // (bug fix: test_differential_call_with_stack_args, issue #301).
        let outgoing_arg_size = frame::compute_max_outgoing_arg_size(func);
        let layout = if frame::function_has_runtime_stack_slots(func) {
            frame::compute_frame_layout_dynamic(func, outgoing_arg_size, true)
        } else {
            frame::compute_frame_layout(func, outgoing_arg_size, true)
        };
        frame::eliminate_frame_indices(func, &layout);
        // FINDING #10a: frame lowering can now fail closed (e.g. a constant-count
        // alloca whose byte size overflows u64) instead of aborting; surface it
        // as a recoverable pipeline error.
        //
        // Shrink-wrapping (ON by default; kill switch TCG_AARCH64_SHRINKWRAP_OFF)
        // is only sound for Darwin Mach-O FRAME-mode unwind: ELF/DWARF-fallback
        // FDEs hardcode the entry prologue, so an ELF triple declines. The empty
        // triple is the historical AArch64 Mach-O default (Darwin).
        let shrink_wrap_eligibility = if target_triple_uses_elf(&self.config.target_triple) {
            frame::ShrinkWrapEligibility::Disabled
        } else {
            frame::ShrinkWrapEligibility::DarwinFrame
        };
        frame::insert_prologue_epilogue_shrinkwrap(func, &layout, shrink_wrap_eligibility)
            .map_err(|e| PipelineError::Encoding(e.to_string()))?;

        // Regalloc spill/reload can orphan a GOT/TLVP page-offset load from
        // its feeding ADRP; re-pair by rematerializing the ADRP at the load
        // (see `repair_orphaned_got_page_pairs` — required for relocation
        // correctness, enforced fail-closed at encode).
        repair_orphaned_got_page_pairs(func);

        // Final safety net: legalize any scalar load/store whose fully-resolved
        // base+offset is outside BOTH encodable AArch64 immediate ranges (e.g. a
        // spill store `str x16, [x29, #-384]` whose slot offset landed out of
        // range). Runs last in frame lowering — after every pass that can
        // finalize an offset, and before branch resolution — so the instructions
        // it inserts are counted in PC-relative branch offsets.
        frame::legalize_large_mem_offsets(func)
            .map_err(|e| PipelineError::Encoding(e.to_string()))?;
        Ok(layout)
    }

    fn supports_stack_protector_target(&self) -> bool {
        let triple = self.config.target_triple.trim();
        triple.is_empty() || triple.contains("aarch64-apple") || triple.contains("arm64-apple")
    }

    /// Phase 9: Emit a Mach-O .o file from encoded machine code.
    ///
    /// When `frame_layout` is provided, a `__LD,__compact_unwind` section is
    /// emitted containing a single compact unwind entry for the function.
    /// This is required by macOS for backtraces, profilers, and exception handling.
    ///
    /// When `lsda_bytes` is provided, a `__TEXT,__gcc_except_tab` section is
    /// emitted containing the LSDA (Language-Specific Data Area) for exception
    /// handling. The personality routine reads this data to dispatch exceptions
    /// to the correct landing pad.
    ///
    /// When `self.config.emit_debug` is true, DWARF debug sections are also
    /// emitted (`__DWARF,__debug_info`, `__debug_abbrev`, `__debug_str`,
    /// `__debug_line`).
    fn emit_macho(
        &self,
        ir_func: &IrMachFunction,
        code: &[u8],
        frame_layout: Option<&crate::frame::FrameLayout>,
        lsda_bytes: Option<&[u8]>,
        debug_provenance: Option<(
            &trust_cg_ir::ProvenanceMap,
            &BTreeMap<trust_cg_ir::TrustIrInstId, trust_cg_ir::SourceLoc>,
        )>,
        fixups: Option<&crate::macho::fixup::FixupList>,
    ) -> Result<Vec<u8>, PipelineError> {
        use crate::dwarf_cfi::{DwarfCfiSection, DwarfFde};
        use crate::macho::MachOWriter;
        use crate::macho::constants::S_REGULAR;
        use crate::macho::reloc::Relocation;
        use crate::unwind::{
            CompactUnwindEntry, CompactUnwindSection, add_compact_unwind_to_writer,
        };

        let func_name = &ir_func.name;
        let code_len = checked_aarch64_object_u32(func_name, "encoded code length", code.len())?;
        let mut writer = MachOWriter::new();
        // Honor the function's emission-time alignment request (loop-head
        // alignment): a single-function object places the function at section
        // offset 0, so section alignment alone makes its function-relative
        // 32-byte boundaries absolute.
        writer.add_text_section_with_align(code, u32::from(ir_func.text_align_log2.max(2)));

        // Add the function symbol with Mach-O name mangling (_prefix).
        let symbol_name = format!("_{}", func_name);
        // Section index 1 = __text (first section, 1-based).
        let symbol_id = writer.add_symbol(&symbol_name, 1, 0, true)?;

        let mut lsda_symbol_id = None;
        let mut personality_symbol_id = None;

        // Emit LSDA (__gcc_except_tab) section + its symbols for exception
        // handling. Non-DWARF compact-unwind entries reference this section
        // directly; DWARF fallback entries reference it from the FDE
        // augmentation data. It must appear in __TEXT to be PC-relative
        // addressable on AArch64 macOS.
        //
        // CRITICAL ORDERING: these symbols MUST be created BEFORE the text
        // fixups are resolved to relocations below. The LSDA symbol is a *local*
        // (defined) symbol; `MachOWriter::write` emits symbols in Mach-O
        // dysymtab order (locals, then external-defined, then undefined), so
        // inserting a local symbol shifts the final index of every undefined
        // symbol. If we resolved the BL relocations first (computing each
        // callee's `final_symbol_index`) and then added the LSDA local symbol,
        // every text relocation would point one slot too early — the linker
        // would wire `bl cxx_throw` to the wrong callee. Adding the EH symbols
        // up front makes the symbol table final before any index is read.
        if let Some(lsda) = lsda_bytes {
            let lsda_section = writer.add_custom_section(
                b"__gcc_except_tab",
                b"__TEXT",
                lsda,
                2, // 2^2 = 4-byte alignment (matching LLVM)
                S_REGULAR,
            );
            let name = format!("_GCC_except_table_{}", func_name);
            lsda_symbol_id = Some(writer.add_symbol(&name, lsda_section + 1, 0, false)?);

            let personality = crate::exception_handling::required_personality_symbol(
                ir_func.eh_metadata.personality.as_deref(),
            )
            .map_err(|error| PipelineError::MalformedAarch64Function {
                function: ir_func.name.clone(),
                detail: format!("invalid exception-handling personality: {error}"),
            })?;
            let name = format!("_{}", personality);
            personality_symbol_id = Some(writer.add_symbol(&name, 0, 0, true)?);
        }

        // Register every fixup target before unwind emission can expose a
        // final nlist index. A later DWARF `EH_Frame` local changes final symbol
        // order, so target registration and numeric-index resolution must be
        // separate phases.
        let fixup_symbol_ids = if let Some(fixups) = fixups
            && !fixups.is_empty()
        {
            Some(add_single_function_symbol_ids_for_fixups(
                &mut writer,
                func_name,
                symbol_id,
                fixups,
            )?)
        } else {
            None
        };

        // Emit compact unwind section if we have frame layout information.
        if let Some(layout) = frame_layout {
            let probe_entry = CompactUnwindEntry::from_layout(
                layout, 0, // function_offset (relocated via ARM64_RELOC_UNSIGNED)
                code_len, 0,
            );
            let needs_dwarf_fallback = probe_entry.needs_dwarf_fallback();
            let mut eh_frame_info = None;

            if needs_dwarf_fallback {
                let has_eh = lsda_bytes.is_some();
                let mut cfi = if has_eh {
                    DwarfCfiSection::new_aarch64_with_eh()
                } else {
                    DwarfCfiSection::new()
                };
                let mut fde = DwarfFde::from_layout(layout, 0, code_len, 0);
                if has_eh {
                    fde = fde.with_lsda();
                }
                cfi.add_fde(fde);
                let mut eh_frame = cfi.to_bytes();
                // Strip the ELF-style zero terminator: ld64-arm64 parses to the
                // section bounds and rejects a zero-length entry as "empty CIE"
                // (see the module-batch site above).
                if eh_frame.len() >= 4 && eh_frame[eh_frame.len() - 4..] == [0, 0, 0, 0] {
                    eh_frame.truncate(eh_frame.len() - 4);
                }
                if !eh_frame.is_empty() {
                    const EH_FRAME_FLAGS: u32 = 0x6800_000B;
                    for pc_begin_offset in cfi.fde_pc_begin_relocation_offsets() {
                        let addend = -(pc_begin_offset as i64);
                        let offset = pc_begin_offset as usize;
                        eh_frame[offset..offset + 8].copy_from_slice(&addend.to_le_bytes());
                    }
                    for lsda_offset in cfi.fde_lsda_relocation_offsets() {
                        let addend = -(lsda_offset as i64);
                        let offset = lsda_offset as usize;
                        eh_frame[offset..offset + 8].copy_from_slice(&addend.to_le_bytes());
                    }
                    let eh_frame_section = writer.add_custom_section(
                        b"__eh_frame",
                        b"__TEXT",
                        &eh_frame,
                        3, // 2^3 = 8-byte alignment
                        EH_FRAME_FLAGS,
                    );
                    let eh_frame_symbol =
                        writer.add_symbol("EH_Frame", eh_frame_section + 1, 0, false)?;
                    eh_frame_info = Some((eh_frame_section, eh_frame_symbol, cfi));
                }
            }

            let function_symbol_index =
                final_macho_symbol_index(&mut writer, symbol_id, "function unwind emission")?;
            let personality_symbol_index = personality_symbol_id
                .map(|id| final_macho_symbol_index(&mut writer, id, "personality unwind emission"))
                .transpose()?;
            let lsda_symbol_index = lsda_symbol_id
                .map(|id| final_macho_symbol_index(&mut writer, id, "LSDA unwind emission"))
                .transpose()?;
            let eh_frame_symbol_index = eh_frame_info
                .as_ref()
                .map(|(_, symbol_id, _)| {
                    final_macho_symbol_index(
                        &mut writer,
                        *symbol_id,
                        "EH frame relocation emission",
                    )
                })
                .transpose()?;

            let mut cu_section = CompactUnwindSection::new();
            let mut entry = CompactUnwindEntry::from_layout(
                layout,
                0, // function_offset (relocated via ARM64_RELOC_UNSIGNED)
                code_len,
                function_symbol_index,
            );
            if !needs_dwarf_fallback {
                if let Some(symbol_index) = personality_symbol_index {
                    entry = entry.with_personality_symbol(symbol_index);
                }
                if let Some(symbol_index) = lsda_symbol_index {
                    entry = entry.with_lsda_symbol(symbol_index);
                }
            }
            cu_section.add_entry(entry);
            add_compact_unwind_to_writer(&mut writer, &cu_section)?;

            if let Some((eh_frame_section, _, cfi)) = eh_frame_info
                && let Some(eh_frame_symbol_index) = eh_frame_symbol_index
            {
                if let (Some(offset), Some(symbol_index)) = (
                    cfi.cie_personality_relocation_offset(),
                    personality_symbol_index,
                ) {
                    let offset = checked_aarch64_macho_relocation_offset(
                        func_name,
                        "CIE personality relocation offset",
                        offset,
                    )?;
                    writer.add_relocation(
                        eh_frame_section,
                        Relocation::pointer_to_got_pcrel(offset, symbol_index),
                    )?;
                }
                for pc_begin_offset in cfi.fde_pc_begin_relocation_offsets() {
                    let pc_begin_offset = checked_aarch64_macho_relocation_offset(
                        func_name,
                        "FDE PC-begin relocation offset",
                        pc_begin_offset,
                    )?;
                    writer.add_relocation(
                        eh_frame_section,
                        Relocation::subtractor(pc_begin_offset, eh_frame_symbol_index, 3),
                    )?;
                    writer.add_relocation(
                        eh_frame_section,
                        Relocation::unsigned_ptr(pc_begin_offset, function_symbol_index),
                    )?;
                }
                if let Some(symbol_index) = lsda_symbol_index {
                    for lsda_offset in cfi.fde_lsda_relocation_offsets() {
                        let lsda_offset = checked_aarch64_macho_relocation_offset(
                            func_name,
                            "FDE LSDA relocation offset",
                            lsda_offset,
                        )?;
                        writer.add_relocation(
                            eh_frame_section,
                            Relocation::subtractor(lsda_offset, eh_frame_symbol_index, 3),
                        )?;
                        writer.add_relocation(
                            eh_frame_section,
                            Relocation::unsigned_ptr(lsda_offset, symbol_index),
                        )?;
                    }
                }
            }
        }

        // Resolve text fixups only after every unwind/LSDA symbol has been
        // registered. A relocation stores a final nlist index and therefore
        // freezes the writer's symbol table; adding an EH_Frame local after
        // this point would otherwise silently invalidate earlier indices.
        if let Some(fixups) = fixups
            && let Some(fixup_symbol_ids) = fixup_symbol_ids
        {
            let symbol_map = fixup_symbol_ids
                .into_iter()
                .map(|(name, symbol_id)| {
                    let final_index = writer.final_symbol_index(symbol_id)?.ok_or_else(|| {
                        PipelineError::Encoding(
                            "symbol missing before Mach-O fixup resolution".to_string(),
                        )
                    })?;
                    Ok((name, final_index))
                })
                .collect::<Result<HashMap<_, _>, PipelineError>>()?;
            let mut resolved_fixups = fixups.clone();
            resolved_fixups.resolve_named_symbols(|name| {
                symbol_map.get(name).copied().or_else(|| {
                    let mangled = macho_symbol_name(name);
                    symbol_map.get(&mangled).copied()
                })
            })?;
            let relocations = resolved_fixups.resolve_to_relocations()?;
            for reloc in relocations {
                writer.add_relocation(0, reloc)?;
            }
        }

        // Emit DWARF debug sections when debug info is requested.
        if self.config.emit_debug {
            use crate::dwarf_info::{
                DwarfDebugInfo, EnumType, Enumerator, FunctionDebugInfo, FunctionParam,
                SourceLanguage, StructMember, StructType, VariableLocation,
                add_debug_info_to_writer,
            };

            let debug_meta = &ir_func.debug_meta;

            // Determine source file name from debug_meta or fall back to function name.
            let default_file = format!("{}.rs", func_name);
            let source_file = debug_meta.source_file.as_deref().unwrap_or(&default_file);

            let mut debug_info = DwarfDebugInfo::new(source_file, ".", SourceLanguage::Rust);
            debug_info.add_standard_types();

            for sty in &debug_meta.struct_types {
                debug_info.add_struct_type(StructType {
                    name: sty.name.clone(),
                    byte_size: sty.byte_size,
                    members: sty
                        .members
                        .iter()
                        .map(|member| StructMember {
                            name: member.name.clone(),
                            offset: member.offset,
                            type_index: dwarf_standard_type_index(member.ty),
                        })
                        .collect(),
                });
            }

            for ety in &debug_meta.enum_types {
                debug_info.add_enum_type(EnumType {
                    name: ety.name.clone(),
                    byte_size: ety.byte_size,
                    underlying_type_index: dwarf_standard_type_index(ety.underlying_type),
                    enumerators: ety
                        .enumerators
                        .iter()
                        .map(|enumerator| Enumerator {
                            name: enumerator.name.clone(),
                            value: enumerator.value,
                        })
                        .collect(),
                });
            }

            // Build parameter debug info from source names and ABI locations.
            let lower_param_types: Vec<LowerType> = ir_func
                .signature
                .params
                .iter()
                .map(lower_type_from_ir_type)
                .collect();
            let abi_param_locations = AppleAArch64ABI::classify_params(&lower_param_types);
            let param_count = debug_meta
                .param_names
                .len()
                .max(ir_func.signature.params.len());
            let params: Vec<FunctionParam> = (0..param_count)
                .map(|i| {
                    let name = debug_meta
                        .param_names
                        .get(i)
                        .cloned()
                        .unwrap_or_else(|| format!("arg{}", i));
                    let type_index = ir_func
                        .signature
                        .params
                        .get(i)
                        .map(dwarf_type_index_for_ir_type)
                        .unwrap_or(3);
                    let location = abi_param_locations
                        .get(i)
                        .map_or(VariableLocation::Register(0), |loc| {
                            bounded_dwarf_param_location(ir_func, loc, frame_layout, code_len)
                        });
                    FunctionParam {
                        name,
                        type_index,
                        location,
                    }
                })
                .collect();

            let variables = build_debug_variables(
                ir_func,
                debug_meta,
                frame_layout,
                code_len,
                debug_provenance.map(|(provenance, _)| provenance),
            );

            let line_entries = build_source_line_entries(ir_func, debug_provenance);

            let decl_line = if debug_meta.decl_line > 0 {
                debug_meta.decl_line as u16
            } else {
                1
            };

            debug_info.add_function(FunctionDebugInfo {
                name: func_name.to_string(),
                linkage_name: Some(symbol_name.clone()),
                low_pc: 0,
                size: code_len,
                params,
                variables,
                scopes: vec![],
                line_entries,
                decl_file: 1,
                decl_line,
            });
            add_debug_info_to_writer(&mut writer, &debug_info)
                .map_err(|err| PipelineError::Encoding(format!("DWARF emission failed: {err}")))?;
        }

        Ok(writer.write()?)
    }

    // --- Dispatch verification ---

    /// Verify a dispatch plan against a compute graph, applying the configured
    /// [`DispatchVerifyMode`] policy.
    ///
    /// Returns:
    /// - `Ok(plan)` if verification passes or is disabled
    /// - `Ok(cpu_only_plan)` if verification fails under
    ///   [`DispatchVerifyMode::FallbackOnFailure`]
    /// - `Err(DispatchVerificationFailed)` if verification fails under
    ///   [`DispatchVerifyMode::ErrorOnFailure`]
    pub fn verify_dispatch_plan(
        &self,
        graph: &ComputeGraph,
        plan: DispatchPlan,
        recommendations: &[TargetRecommendation],
    ) -> Result<DispatchPlan, PipelineError> {
        match self.config.verify_dispatch {
            DispatchVerifyMode::Off => Ok(plan),
            DispatchVerifyMode::FallbackOnFailure => {
                let report = verify_dispatch_plan_properties(graph, &plan);
                if report.all_ok() {
                    Ok(plan)
                } else {
                    // Fall back to a CPU-only plan.
                    Ok(generate_cpu_only_plan(graph, recommendations))
                }
            }
            // Sampled applies its sampling to per-FUNCTION verification only;
            // dispatch plans are one-per-graph, so they get the fail-closed
            // ErrorOnFailure treatment.
            DispatchVerifyMode::ErrorOnFailure | DispatchVerifyMode::Sampled { .. } => {
                let report = verify_dispatch_plan_properties(graph, &plan);
                if report.all_ok() {
                    Ok(plan)
                } else {
                    let violations = report.total_violations();
                    let summary = format!("{}", report);
                    Err(PipelineError::DispatchVerificationFailed {
                        violations,
                        summary,
                        report,
                    })
                }
            }
        }
    }

    /// Generate a dispatch plan, verify it, and return the verified (or
    /// fallback) plan. This is the primary integration point for dispatch
    /// verification in the compilation pipeline.
    ///
    /// Combines plan generation with verification in a single call.
    pub fn generate_and_verify_dispatch(
        &self,
        graph: &ComputeGraph,
        recommendations: &[TargetRecommendation],
    ) -> Result<DispatchPlan, PipelineError> {
        let plan = generate_dispatch_plan(graph, recommendations);
        self.verify_dispatch_plan(graph, plan, recommendations)
    }

    /// Generate Metal kernel code for GPU-targeted dispatch operations.
    ///
    /// This is the primary integration point for Metal kernel generation in
    /// the compilation pipeline. It takes a verified dispatch plan and compute
    /// graph, and produces all MSL kernel sources plus host-side dispatch code.
    ///
    /// Typical usage:
    /// ```text
    /// let plan = pipeline.generate_and_verify_dispatch(&graph, &recs)?;
    /// let metal = pipeline.emit_metal_kernels(&plan, &graph)?;
    /// // metal.kernels contains MSL sources to compile with `xcrun metal`
    /// // metal.dispatch_code contains Objective-C host dispatch code
    /// ```
    pub fn emit_metal_kernels(
        &self,
        plan: &DispatchPlan,
        graph: &ComputeGraph,
    ) -> Result<crate::metal_emitter::MetalOutput, PipelineError> {
        crate::metal_emitter::emit_metal_kernels(plan, graph).map_err(PipelineError::from)
    }
}

// ---------------------------------------------------------------------------
// CoreML MIL generation from dispatch plan
// ---------------------------------------------------------------------------

/// Output of CoreML MIL program generation from a dispatch plan.
///
/// Contains the generated MIL program, any ANE compatibility warnings, and
/// an estimated latency based on the dispatch plan's cycle estimates for
/// ANE-targeted nodes.
#[derive(Debug, Clone)]
pub struct CoreMLOutput {
    /// The generated MIL program representing ANE-targeted operations.
    pub program: MilProgram,
    /// ANE compatibility warnings (empty if fully compatible).
    pub warnings: Vec<String>,
    /// Estimated latency in microseconds for the ANE subgraph, derived from
    /// the dispatch plan's per-node cycle estimates at an assumed 1 GHz
    /// Neural Engine clock.
    pub estimated_latency_us: u64,
}

/// Collect ANE-targeted nodes from a dispatch plan and request a CoreML MIL
/// program from the corresponding compute graph nodes.
///
/// This is the fail-closed integration boundary between the dispatch pipeline
/// and the CoreML emitter. It:
/// 1. Collects all node IDs assigned to `NeuralEngine` in the plan
/// 2. Resolves those IDs to `ComputeNode` references from the graph
/// 3. Delegates exact-recipe validation to
///    [`CoreMLEmitter::emit_program_from_nodes`]
/// 4. Validates ANE compatibility via [`validate_ane_compatibility`]
/// 5. Estimates latency from the plan's per-node cycle costs
///
/// TrustIR does not yet carry an exact tensor primitive/shape recipe, so the
/// emitter currently rejects every non-empty request with
/// `NoExactCoreMlRecipe`; steps 4 and 5 remain the future success path once
/// that canonical recipe exists. This function must not infer semantics from
/// operation names, byte counts, or public target labels.
pub fn emit_coreml_program(
    plan: &DispatchPlan,
    graph: &ComputeGraph,
) -> Result<CoreMLOutput, PipelineError> {
    // Step 1: Collect ANE-targeted node IDs from the dispatch plan assignment.
    let mut ane_node_ids: Vec<ComputeNodeId> = plan
        .assignment
        .iter()
        .filter(|(_, target)| **target == ComputeTarget::NeuralEngine)
        .map(|(id, _)| *id)
        .collect();

    if ane_node_ids.is_empty() {
        return Err(PipelineError::CoreMLEmit(CoreMLEmitError::EmptyNodeList));
    }

    // Sort by node ID for deterministic ordering.
    ane_node_ids.sort_by_key(|id| id.0);

    // Step 2: Resolve node IDs to ComputeNode references from the graph.
    let mut ane_nodes: Vec<ComputeNode> = Vec::with_capacity(ane_node_ids.len());
    for node_id in &ane_node_ids {
        let node = graph.node(*node_id).ok_or(PipelineError::CoreMLEmit(
            CoreMLEmitError::MissingPlanNode { node_id: *node_id },
        ))?;
        ane_nodes.push(node.clone());
    }

    // Step 3: Generate MIL program from ANE nodes.
    let mut emitter = CoreMLEmitter::new();
    let program = emitter.emit_program_from_nodes(&ane_nodes)?;

    // Step 4: Validate ANE compatibility.
    let warnings = validate_ane_compatibility(&program);

    // Step 5: Estimate latency from dispatch plan cycle costs.
    // Sum the estimated_cycles from KernelLaunch ops targeting NeuralEngine
    // nodes. Convert cycles to microseconds assuming ~1 GHz ANE clock.
    let total_ane_cycles: u64 = plan
        .ops
        .iter()
        .filter_map(|op| match op {
            DispatchOp::KernelLaunch {
                target: ComputeTarget::NeuralEngine,
                estimated_cycles,
                ..
            } => Some(*estimated_cycles),
            _ => None,
        })
        .sum();

    // 1 GHz = 1 cycle per ns. Convert cycles to microseconds: cycles / 1000.
    let estimated_latency_us = total_ane_cycles.saturating_div(1000).max(1);

    Ok(CoreMLOutput {
        program,
        warnings,
        estimated_latency_us,
    })
}

// ---------------------------------------------------------------------------
// CPU-only dispatch plan fallback
// ---------------------------------------------------------------------------

/// Generate a CPU-only dispatch plan as a safe fallback.
///
/// When dispatch verification fails, this function generates a conservative
/// plan that runs every node on `CpuScalar`. No data transfers or
/// synchronizations are needed because all execution stays on the CPU.
pub fn generate_cpu_only_plan(
    graph: &ComputeGraph,
    _recommendations: &[TargetRecommendation],
) -> DispatchPlan {
    use trust_cg_lower::dispatch::DispatchOp;
    use trust_cg_lower::target_analysis::ComputeTarget;

    let mut assignment = HashMap::new();
    let mut ops = Vec::new();
    let mut total_cycles: u64 = 0;

    // Walk nodes in ID order. Since all nodes are on the same target
    // (CpuScalar), no transfers or syncs are needed.
    let mut node_ids: Vec<_> = graph.nodes.iter().map(|n| n.id).collect();
    node_ids.sort_by_key(|id| id.0);

    for node_id in &node_ids {
        assignment.insert(*node_id, ComputeTarget::CpuScalar);

        let node = graph.node(*node_id);
        let estimated_cycles = node
            .and_then(|n| n.costs.get(&ComputeTarget::CpuScalar))
            .map(|c| c.latency_cycles)
            .unwrap_or(1);

        ops.push(DispatchOp::CpuFallback {
            node_id: *node_id,
            reason: "dispatch verification fallback".to_string(),
        });
        total_cycles = total_cycles.saturating_add(estimated_cycles);
    }

    DispatchPlan {
        ops,
        assignment,
        estimated_total_cycles: total_cycles,
    }
}

// ---------------------------------------------------------------------------
// Convenience: compile_to_object — one-shot compilation
// ---------------------------------------------------------------------------

/// Compile a trust_ir function to a Mach-O .o file in one call.
///
/// This is the highest-level API for Trust Codegen compilation.
pub fn compile_to_object(
    input: &trust_cg_lower::Function,
    opt_level: OptLevel,
) -> Result<Vec<u8>, PipelineError> {
    let config = PipelineConfig {
        opt_level,
        emit_debug: false,
        verify_dispatch: DispatchVerifyMode::FallbackOnFailure,
        verify: false,
        cegis_superopt_budget_sec: None,
        target_triple: String::new(),
        enable_fsym_trust_ir_preflight: false,
        // AOT object compilation keeps the full quality regalloc.
        enable_jit_fast_regalloc: false,
        // ...and therefore keeps CSE/GVN (rematerialization is available).
        skip_cse_gvn: false,
        disabled_passes_override: None,
        contains4_scanner_batch_rewrite_override: None,
    };
    let pipeline = Pipeline::new(config);
    pipeline.compile_function(input)
}

/// Run the dialect-framework progressive-lowering pipeline (verif -> trust_ir ->
/// machir -> MachFunction) on a [`trust_cg_dialect::DialectModule`] and return
/// one [`IrMachFunction`] per contained function.
///
/// Integration point for Trust Codegen#433 / trust_ir#428. The `DialectModule` must have
/// the `verif`, `trust_ir`, and `machir` dialects registered (see
/// [`trust_cg_dialect::dialects::conversions::register_all`]). Any op that no
/// registered pattern handles trips the legality gate inside
/// [`trust_cg_dialect::lower_module`] — producing a hard error in one known
/// location rather than leaking an unknown op into the MachFunction.
///
/// This is an early hook: for modules that arrive as `DialectModule` the
/// frontend calls this and then feeds the resulting MachFunctions through
/// the rest of the pipeline (regalloc, frame lowering, encoding, Mach-O).
/// `trust_ir::Module` frontends continue to use the legacy
/// [`Pipeline::compile_function`] path. Both paths converge at MachFunction.
pub fn dialect_lower_module(
    module: &mut trust_cg_dialect::DialectModule,
) -> Result<Vec<IrMachFunction>, trust_cg_dialect::LowerModuleError> {
    trust_cg_dialect::lower_module(module)
}

/// Build an `add(a: i32, b: i32) -> i32` function directly in IR.
///
/// This is a convenience for testing the pipeline without needing the full
/// trust_ir input infrastructure. It builds the function directly in trust-cg-ir
/// types with physical registers (simulating post-ISel + post-regalloc state).
pub fn build_add_test_function() -> IrMachFunction {
    use trust_cg_ir::function::Type;
    use trust_cg_ir::regs::{X0, X1};

    let sig = IrSignature::new(vec![Type::I32, Type::I32], vec![Type::I32]);
    let mut func = IrMachFunction::new("add".to_string(), sig);
    let entry = func.entry;

    // ADD X0, X0, X1 (result in X0 per ABI)
    let add = IrMachInst::new(
        IrOpcode::AddRR,
        vec![
            IrOperand::PReg(X0),
            IrOperand::PReg(X0),
            IrOperand::PReg(X1),
        ],
    );
    let add_id = func.push_inst(add);
    func.append_inst(entry, add_id);

    // RET
    let ret = IrMachInst::new(IrOpcode::Ret, vec![]);
    let ret_id = func.push_inst(ret);
    func.append_inst(entry, ret_id);

    func
}

