    /// `total()` must count `unattributed`.
    ///
    /// The JIT path reports its whole regalloc..encode region there because it
    /// has no per-phase timers. If a future edit drops the field from the sum,
    /// every JIT breakdown silently loses most of its measured time and the
    /// remaining phases look artificially dominant -- the same class of bug as
    /// the equal-quarters split this field replaced.
    #[test]
    fn phase_timings_total_counts_unattributed() {
        let mut t = PhaseTimings::default();
        assert_eq!(t.total(), Duration::ZERO);

        t.unattributed = Some(Duration::from_micros(400));
        assert_eq!(
            t.total(),
            Duration::from_micros(400),
            "unattributed time must be included in total()"
        );

        t.isel = Some(Duration::from_micros(100));
        assert_eq!(t.total(), Duration::from_micros(500));
    }

    /// The x86-64 JIT path must not resurrect the fabricated split: it used to
    /// divide one measured region by four and store the identical quotient in
    /// regalloc/frame_lowering/branch_resolution/encoding, making those rows
    /// equal by construction in every breakdown. Time it cannot attribute
    /// belongs in `unattributed`, not spread across phases it never measured.
    #[test]
    fn jit_region_is_reported_unattributed_not_split_across_phases() {
        // Shape the JIT path now produces for one function.
        let mut t = PhaseTimings::default();
        t.isel = Some(Duration::from_micros(100));
        t.unattributed = Some(Duration::from_micros(400));

        let fabricated = [
            t.regalloc,
            t.frame_lowering,
            t.branch_resolution,
            t.encoding,
        ];
        assert!(
            fabricated.iter().all(|d| d.is_none()),
            "JIT path has no per-phase timers for these; reporting a number here \
             claims a measurement that was never taken: {fabricated:?}"
        );
        assert_eq!(
            t.total(),
            Duration::from_micros(500),
            "total must be preserved"
        );
    }
    use trust_cg_ir::inst::{AArch64Opcode as IrOpcode, InstFlags, MachInst as IrMachInst};
    use trust_cg_ir::operand::MachOperand as IrOperand;
    use trust_cg_ir::regs::{
        D0, D16, D17, PReg, RegClass, S0, S16, S17, SP, VReg, W0, W1, W3, W4, W5, W9, W16, W17, X0,
        X1, X2, X3, X4, X5, X6, X8, X9, X16, X17, X19, X20, X21, X28, X29, X30,
    };
    use trust_cg_ir::types::{BlockId, InstId, StackSlotId};

