    #[test]
    fn aarch64_object_field_boundaries_fail_closed_without_large_allocations() {
        assert_eq!(
            checked_aarch64_object_u32("boundary", "encoded code length", u32::MAX as usize,)
                .unwrap(),
            u32::MAX,
        );
        #[cfg(target_pointer_width = "64")]
        assert!(matches!(
            checked_aarch64_object_u32("boundary", "encoded code length", u32::MAX as usize + 1,),
            Err(PipelineError::Aarch64ObjectFieldTooLarge {
                field: "encoded code length",
                ..
            })
        ));

        assert_eq!(
            checked_aarch64_fixup_offset("boundary", u64::from(u32::MAX - 4), 4).unwrap(),
            u32::MAX,
        );
        assert!(matches!(
            checked_aarch64_fixup_offset("boundary", u64::from(u32::MAX), 1),
            Err(PipelineError::Aarch64ObjectFieldTooLarge {
                field: "combined text fixup offset",
                ..
            })
        ));

        assert_eq!(
            checked_aarch64_macho_relocation_offset(
                "boundary",
                "Mach-O relocation offset",
                i32::MAX as u32,
            )
            .unwrap(),
            i32::MAX as u32,
        );
        assert!(matches!(
            checked_aarch64_macho_relocation_offset(
                "boundary",
                "Mach-O relocation offset",
                i32::MAX as u32 + 1,
            ),
            Err(PipelineError::Aarch64ObjectFieldTooLarge {
                field: "Mach-O relocation offset",
                ..
            })
        ));

        assert!(checked_aarch64_capacity("boundary", "capacity", usize::MAX, 2).is_err());
        assert!(checked_aarch64_size_sum("boundary", "size", usize::MAX, 1).is_err());

        let last_fitting_tls_count = ((i32::MAX as usize - AARCH64_DARWIN_TLV_INIT_POINTER_OFFSET)
            / AARCH64_DARWIN_TLV_DESCRIPTOR_SIZE)
            + 1;
        let (descriptor_byte_len, pending_relocation_capacity) =
            checked_aarch64_tls_layout(last_fitting_tls_count).unwrap();
        assert_eq!(
            descriptor_byte_len,
            last_fitting_tls_count * AARCH64_DARWIN_TLV_DESCRIPTOR_SIZE,
        );
        assert_eq!(pending_relocation_capacity, last_fitting_tls_count * 2);
        assert!(matches!(
            checked_aarch64_tls_layout(last_fitting_tls_count + 1),
            Err(PipelineError::Aarch64ObjectFieldTooLarge {
                field: "Darwin TLV maximum relocation offset",
                ..
            })
        ));
    }

    #[allow(dead_code)]
    fn read_elf_u16(bytes: &[u8], offset: usize) -> u16 {
        u16::from_le_bytes([bytes[offset], bytes[offset + 1]])
    }

    #[allow(dead_code)]
    fn read_elf_u32(bytes: &[u8], offset: usize) -> u32 {
        u32::from_le_bytes([
            bytes[offset],
            bytes[offset + 1],
            bytes[offset + 2],
            bytes[offset + 3],
        ])
    }

    #[allow(dead_code)]
    fn read_elf_u64(bytes: &[u8], offset: usize) -> u64 {
        u64::from_le_bytes([
            bytes[offset],
            bytes[offset + 1],
            bytes[offset + 2],
            bytes[offset + 3],
            bytes[offset + 4],
            bytes[offset + 5],
            bytes[offset + 6],
            bytes[offset + 7],
        ])
    }

    #[allow(dead_code)]
    fn elf_cstr(bytes: &[u8], offset: usize) -> &str {
        let end = bytes[offset..]
            .iter()
            .position(|b| *b == 0)
            .map(|len| offset + len)
            .expect("ELF string should be nul-terminated");
        std::str::from_utf8(&bytes[offset..end]).expect("ELF string should be utf8")
    }

    #[derive(Debug, Clone, Copy)]
    #[allow(dead_code)]
    struct ElfSectionView {
        offset: u64,
        size: u64,
        sh_type: u32,
        sh_flags: u64,
        entsize: u64,
    }

    #[allow(dead_code)]
    fn find_elf_section_view(bytes: &[u8], target_name: &str) -> Option<ElfSectionView> {
        let shoff = read_elf_u64(bytes, 40) as usize;
        let shentsize = read_elf_u16(bytes, 58) as usize;
        let shnum = read_elf_u16(bytes, 60) as usize;
        let shstrndx = read_elf_u16(bytes, 62) as usize;
        let shstr = shoff + shstrndx * shentsize;
        let shstr_offset = read_elf_u64(bytes, shstr + 24) as usize;

        for idx in 0..shnum {
            let shdr = shoff + idx * shentsize;
            let name_offset = shstr_offset + read_elf_u32(bytes, shdr) as usize;
            if elf_cstr(bytes, name_offset) == target_name {
                return Some(ElfSectionView {
                    sh_type: read_elf_u32(bytes, shdr + 4),
                    sh_flags: read_elf_u64(bytes, shdr + 8),
                    offset: read_elf_u64(bytes, shdr + 24),
                    size: read_elf_u64(bytes, shdr + 32),
                    entsize: read_elf_u64(bytes, shdr + 56),
                });
            }
        }
        None
    }

    #[allow(dead_code)]
    fn elf_relocations(bytes: &[u8]) -> Vec<crate::elf::Elf64Rela> {
        let section = find_elf_section_view(bytes, ".rela.text").expect(".rela.text section");
        assert_eq!(section.sh_type, crate::elf::constants::SHT_RELA);
        assert_eq!(
            section.entsize,
            crate::elf::constants::ELF64_RELA_SIZE as u64
        );
        let count = (section.size / section.entsize) as usize;
        let mut relocs = Vec::with_capacity(count);
        for idx in 0..count {
            let offset = section.offset as usize + idx * crate::elf::constants::ELF64_RELA_SIZE;
            let entry: &[u8; crate::elf::constants::ELF64_RELA_SIZE] = bytes
                [offset..offset + crate::elf::constants::ELF64_RELA_SIZE]
                .try_into()
                .expect("relocation entry size");
            relocs.push(crate::elf::Elf64Rela::decode(entry));
        }
        relocs
    }

    #[allow(dead_code)]
    fn elf_symbol_names(bytes: &[u8]) -> Vec<String> {
        let symtab = find_elf_section_view(bytes, ".symtab").expect(".symtab section");
        let strtab = find_elf_section_view(bytes, ".strtab").expect(".strtab section");
        let count = (symtab.size / crate::elf::constants::ELF64_SYM_SIZE as u64) as usize;
        let mut names = Vec::with_capacity(count);
        for idx in 0..count {
            let offset = symtab.offset as usize + idx * crate::elf::constants::ELF64_SYM_SIZE;
            let name_offset = read_elf_u32(bytes, offset) as usize;
            names.push(elf_cstr(bytes, strtab.offset as usize + name_offset).to_string());
        }
        names
    }

    #[derive(Debug)]
    #[allow(dead_code)]
    struct ElfSymbolView {
        name: String,
        info: u8,
        section: u16,
        size: u64,
    }

    #[allow(dead_code)]
    fn elf_symbols(bytes: &[u8]) -> Vec<ElfSymbolView> {
        let symtab = find_elf_section_view(bytes, ".symtab").expect(".symtab section");
        let strtab = find_elf_section_view(bytes, ".strtab").expect(".strtab section");
        let count = (symtab.size / crate::elf::constants::ELF64_SYM_SIZE as u64) as usize;
        let mut symbols = Vec::with_capacity(count);
        for idx in 0..count {
            let offset = symtab.offset as usize + idx * crate::elf::constants::ELF64_SYM_SIZE;
            let name_offset = read_elf_u32(bytes, offset) as usize;
            symbols.push(ElfSymbolView {
                name: elf_cstr(bytes, strtab.offset as usize + name_offset).to_string(),
                info: bytes[offset + 4],
                section: read_elf_u16(bytes, offset + 6),
                size: read_elf_u64(bytes, offset + 16),
            });
        }
        symbols
    }

    #[allow(dead_code)]
    fn elf_section_data<'a>(bytes: &'a [u8], name: &str) -> &'a [u8] {
        let section = find_elf_section_view(bytes, name).expect("ELF section should exist");
        &bytes[section.offset as usize..section.offset as usize + section.size as usize]
    }

