    #[test]
    fn location_list_fixed_stack_debug_variables_still_emit_bounded_range() {
        let sig = IrSignature::new(vec![], vec![Type::I64]);
        let mut func = IrMachFunction::new("debug_stack_local".to_string(), sig);
        let slot = func.alloc_stack_slot(StackSlot::new(8, 8));
        func.debug_meta
            .local_variables
            .push(trust_cg_ir::function::DebugLocalVariable {
                name: "slot_local".to_string(),
                ty: DebugBaseType::U64,
                storage: DebugVariableStorage::StackSlot(slot.0),
                decl_line: 6,
            });

        let layout = crate::frame::compute_frame_layout(&func, 0, false);
        let frame_offsets = crate::frame::stack_slot_frame_offsets(&func, &layout);
        let frame_offset = frame_offsets[slot.0 as usize].expect("fixed slot should have offset");
        let variables = build_debug_variables(&func, &func.debug_meta, Some(&layout), 16, None);

        assert_eq!(variables.len(), 1);
        assert_eq!(variables[0].name, "slot_local");
        let crate::dwarf_info::VariableLocation::LocationList(entries) = &variables[0].location
        else {
            panic!("fixed stack local should stay on the bounded loclist path");
        };
        assert_eq!(entries.len(), 1);
        assert_eq!(entries[0].low_pc, 0);
        assert_eq!(entries[0].size, 16);
        let expected_location =
            crate::dwarf_info::VariableLocation::FrameOffset(i64::from(frame_offset));
        assert_eq!(
            entries[0].expression,
            crate::dwarf_info::encode_location_expr(&expected_location)
        );
    }

    #[test]
    fn provenance_debug_variables_emit_register_location_list_range() {
        let sig = IrSignature::new(vec![], vec![Type::I64]);
        let mut func = IrMachFunction::new("debug_register_provenance_local".to_string(), sig);
        let entry = func.entry;
        let origin = trust_cg_ir::TrustIrInstId(5);
        let var_id =
            trust_cg_ir::provenance::TrustIrVarId(VALUE_DEBUG_PROVENANCE_VAR_TAG | origin.0);

        let first = func.push_inst(IrMachInst::new(
            IrOpcode::Movz,
            vec![IrOperand::PReg(X0), IrOperand::Imm(1)],
        ));
        let second = func.push_inst(IrMachInst::new(
            IrOpcode::AddRR,
            vec![
                IrOperand::PReg(X1),
                IrOperand::PReg(X0),
                IrOperand::PReg(X2),
            ],
        ));
        let ret = func.push_inst(IrMachInst::new(IrOpcode::Ret, vec![]));
        func.append_inst(entry, first);
        func.append_inst(entry, second);
        func.append_inst(entry, ret);
        func.debug_meta
            .local_variables
            .push(trust_cg_ir::function::DebugLocalVariable {
                name: "tracked".to_string(),
                ty: DebugBaseType::U64,
                storage: DebugVariableStorage::ProvenanceVar(var_id),
                decl_line: 12,
            });

        let mut provenance = trust_cg_ir::ProvenanceMap::new();
        provenance.record_lowering(origin, &[first], trust_cg_ir::PassId::new("test-isel"));
        provenance
            .declare_var(
                var_id,
                trust_cg_ir::provenance::VarLocation::new(
                    var_id,
                    first,
                    ret,
                    trust_cg_ir::provenance::LocationExpr::Reg(X0),
                ),
            )
            .expect("test provenance register range should be valid");

        let variables = build_debug_variables(&func, &func.debug_meta, None, 12, Some(&provenance));

        assert_eq!(variables.len(), 1);
        assert_eq!(variables[0].name, "tracked");
        let crate::dwarf_info::VariableLocation::LocationList(entries) = &variables[0].location
        else {
            panic!("provenance variable should emit a bounded DWARF location list");
        };
        assert_eq!(entries.len(), 1);
        assert_eq!(entries[0].low_pc, 0);
        assert_eq!(entries[0].size, 8);
        assert_eq!(
            entries[0].expression,
            crate::dwarf_info::encode_location_expr(
                &crate::dwarf_info::VariableLocation::Register(0)
            )
        );
    }

