    #[test]
    fn synthetic_debug_provenance_var_tags_require_exact_namespace() {
        let sig = IrSignature::new(vec![], vec![Type::I64]);
        let mut func = IrMachFunction::new("debug_provenance_var_tags".to_string(), sig);
        let slot = func.alloc_stack_slot(StackSlot::new(8, 8));

        let alloca_var = trust_cg_ir::provenance::TrustIrVarId(ALLOCA_DEBUG_PROVENANCE_VAR_TAG);
        let const_var = trust_cg_ir::provenance::TrustIrVarId(CONST_VALUE_DEBUG_PROVENANCE_VAR_TAG);
        let value_var = trust_cg_ir::provenance::TrustIrVarId(VALUE_DEBUG_PROVENANCE_VAR_TAG);
        let combined_var = trust_cg_ir::provenance::TrustIrVarId(
            ALLOCA_DEBUG_PROVENANCE_VAR_TAG | CONST_VALUE_DEBUG_PROVENANCE_VAR_TAG,
        );

        assert_eq!(
            alloca_debug_stack_slot_from_provenance_var(&func, alloca_var),
            Some(slot)
        );
        assert_eq!(
            const_value_debug_trust_ir_origin_from_provenance_var(const_var),
            Some(trust_cg_ir::TrustIrInstId(0))
        );
        assert_eq!(
            value_debug_trust_ir_origin_from_provenance_var(value_var),
            Some(trust_cg_ir::TrustIrInstId(0))
        );
        assert_eq!(
            alloca_debug_stack_slot_from_provenance_var(&func, const_var),
            None
        );
        assert_eq!(
            const_value_debug_trust_ir_origin_from_provenance_var(alloca_var),
            None
        );
        assert_eq!(
            alloca_debug_stack_slot_from_provenance_var(&func, value_var),
            None
        );
        assert_eq!(
            const_value_debug_trust_ir_origin_from_provenance_var(value_var),
            None
        );
        assert_eq!(
            value_debug_trust_ir_origin_from_provenance_var(alloca_var),
            None
        );
        assert_eq!(
            value_debug_trust_ir_origin_from_provenance_var(const_var),
            None
        );
        assert_eq!(
            alloca_debug_stack_slot_from_provenance_var(&func, combined_var),
            None
        );
        assert_eq!(
            const_value_debug_trust_ir_origin_from_provenance_var(combined_var),
            None
        );
        assert_eq!(
            value_debug_trust_ir_origin_from_provenance_var(combined_var),
            None
        );
    }

    #[test]
    fn provenance_debug_variables_seed_stack_alloca_range_after_o3_prepare() {
        let mut module = trust_ir::Module::new("debug_alloca_provenance");
        let ft = module.add_func_type(trust_ir::FuncTy {
            params: vec![trust_ir::Ty::I64],
            returns: vec![trust_ir::Ty::I64],
            is_vararg: false,
        });
        let mut trust_ir_func = trust_ir::Function::new(
            trust_ir::FuncId::new(0),
            "debug_alloca_provenance",
            ft,
            trust_ir::BlockId::new(0),
        );
        let slot = trust_ir::ValueId::new(1);
        let loaded = trust_ir::ValueId::new(2);
        trust_ir_func.blocks = vec![trust_ir::Block {
            id: trust_ir::BlockId::new(0),
            params: vec![(trust_ir::ValueId::new(0), trust_ir::Ty::I64)],
            body: vec![
                trust_ir::InstrNode::new(trust_ir::Inst::Alloca {
                    ty: trust_ir::Ty::I64,
                    count: None,
                    align: None,
                })
                .with_result(slot),
                trust_ir::InstrNode::new(trust_ir::Inst::Store {
                    ty: trust_ir::Ty::I64,
                    ptr: slot,
                    value: trust_ir::ValueId::new(0),
                    align: None,
                    volatile: false,
                }),
                trust_ir::InstrNode::new(trust_ir::Inst::Load {
                    ty: trust_ir::Ty::I64,
                    ptr: slot,
                    align: None,
                    volatile: false,
                })
                .with_result(loaded),
                trust_ir::InstrNode::new(trust_ir::Inst::Return {
                    values: vec![loaded],
                }),
            ],
        }];
        module.add_function(trust_ir_func.clone());

        let (lir_func, _proof_ctx) = trust_cg_lower::translate_function(&trust_ir_func, &module)
            .expect("translate test trust_ir");
        let local = lir_func
            .debug_meta
            .local_variables
            .first()
            .expect("fixed scalar alloca should create debug local");
        let DebugVariableStorage::ProvenanceVar(var_id) = local.storage else {
            panic!("fixed scalar alloca should use provenance-backed storage");
        };
        assert_eq!(var_id.0, ALLOCA_DEBUG_PROVENANCE_VAR_TAG);

        let pipeline = Pipeline::new(PipelineConfig {
            opt_level: OptLevel::O3,
            emit_debug: true,
            verify: false,
            ..PipelineConfig::default()
        });
        let (prepared, _metrics, provenance) = pipeline
            .prepare_function_with_metrics_and_provenance_map(&lir_func, None)
            .expect("O3 prepare should seed alloca debug provenance");
        let provenance =
            provenance.expect("trust_ir origins or debug locals should create provenance");

        let ranges = provenance.var_live_ranges(var_id);
        assert_eq!(ranges.len(), 1);
        assert_eq!(ranges[0].end, InstId(prepared.insts.len() as u32));
        assert_eq!(
            ranges[0].value,
            trust_cg_ir::provenance::LocationExpr::Stack(StackSlotId(0))
        );

        let layout = crate::frame::compute_frame_layout(&prepared, 0, true);
        let frame_offsets = crate::frame::stack_slot_frame_offsets(&prepared, &layout);
        let frame_offset = frame_offsets[0].expect("alloca stack slot should have frame offset");
        let code = encode_function(&prepared).expect("prepared function should encode");
        let variables = build_debug_variables(
            &prepared,
            &prepared.debug_meta,
            Some(&layout),
            code.len() as u32,
            Some(&provenance),
        );
        let local_0: Vec<_> = variables
            .iter()
            .filter(|variable| variable.name == "local_0")
            .collect();
        assert_eq!(
            local_0.len(),
            1,
            "provenance local must claim stack fallback"
        );
        let crate::dwarf_info::VariableLocation::LocationList(entries) = &local_0[0].location
        else {
            panic!("seeded alloca provenance should reach the loclist consumer");
        };
        assert_eq!(entries.len(), 1);
        assert_eq!(entries[0].low_pc, 0);
        assert_eq!(entries[0].size, code.len() as u32);
        assert_eq!(
            entries[0].expression,
            crate::dwarf_info::encode_location_expr(
                &crate::dwarf_info::VariableLocation::FrameOffset(i64::from(frame_offset))
            )
        );
    }

    #[test]
    fn provenance_debug_variables_seed_register_value_range_after_o3_prepare() {
        let mut module = trust_ir::Module::new("debug_value_provenance");
        let ft = module.add_func_type(trust_ir::FuncTy {
            params: vec![trust_ir::Ty::I64, trust_ir::Ty::I64],
            returns: vec![trust_ir::Ty::I64],
            is_vararg: false,
        });
        let mut trust_ir_func = trust_ir::Function::new(
            trust_ir::FuncId::new(0),
            "debug_value_provenance",
            ft,
            trust_ir::BlockId::new(0),
        );
        let lhs = trust_ir::ValueId::new(0);
        let rhs = trust_ir::ValueId::new(1);
        let sum = trust_ir::ValueId::new(2);
        trust_ir_func.blocks = vec![trust_ir::Block {
            id: trust_ir::BlockId::new(0),
            params: vec![(lhs, trust_ir::Ty::I64), (rhs, trust_ir::Ty::I64)],
            body: vec![
                trust_ir::InstrNode::new(trust_ir::Inst::BinOp {
                    op: trust_ir::BinOp::Add,
                    ty: trust_ir::Ty::I64,
                    lhs,
                    rhs,
                })
                .with_result(sum)
                .with_span(trust_ir::SourceSpan {
                    file: 0,
                    line: 31,
                    col: 7,
                }),
                trust_ir::InstrNode::new(trust_ir::Inst::Return { values: vec![sum] }),
            ],
        }];
        module.add_function(trust_ir_func.clone());

        let (lir_func, _proof_ctx) = trust_cg_lower::translate_function(&trust_ir_func, &module)
            .expect("translate test trust_ir");
        let local = lir_func
            .debug_meta
            .local_variables
            .first()
            .expect("source-spanned binop should create debug local");
        let DebugVariableStorage::ProvenanceVar(var_id) = local.storage else {
            panic!("binop value local should use provenance-backed storage");
        };
        assert_eq!(local.name, "value_0");
        assert_eq!(local.ty, DebugBaseType::I64);
        assert_eq!(local.decl_line, 31);
        assert_eq!(var_id.0, VALUE_DEBUG_PROVENANCE_VAR_TAG);
        assert!(
            lir_func.stack_slots.is_empty(),
            "register-backed value local must not allocate a stack slot"
        );

        let pipeline = Pipeline::new(PipelineConfig {
            opt_level: OptLevel::O3,
            emit_debug: true,
            verify: false,
            ..PipelineConfig::default()
        });
        let (prepared, _metrics, provenance) = pipeline
            .prepare_function_with_metrics_and_provenance_map(&lir_func, None)
            .expect("O3 prepare should seed register debug provenance");
        let provenance =
            provenance.expect("trust_ir origins or debug locals should create provenance");

        let ranges = provenance.var_live_ranges(var_id);
        assert_eq!(ranges.len(), 1);
        let trust_cg_ir::provenance::LocationExpr::Reg(preg) = ranges[0].value else {
            panic!("binop value local should seed a register location");
        };
        assert_ne!(preg, XZR);
        assert_ne!(preg, WZR);
        assert!(
            register_debug_value_position_range(&prepared, ranges[0].start, ranges[0].end)
                .is_some(),
            "seeded register range should be bounded in final layout order"
        );

        let code = encode_function(&prepared).expect("prepared function should encode");
        let variables = build_debug_variables(
            &prepared,
            &prepared.debug_meta,
            None,
            code.len() as u32,
            Some(&provenance),
        );
        let value_0: Vec<_> = variables
            .iter()
            .filter(|variable| variable.name == "value_0")
            .collect();
        assert_eq!(value_0.len(), 1);
        let crate::dwarf_info::VariableLocation::LocationList(entries) = &value_0[0].location
        else {
            panic!("seeded register provenance should reach the loclist consumer");
        };
        assert_eq!(entries.len(), 1);
        assert_eq!(
            entries[0].expression,
            crate::dwarf_info::encode_location_expr(
                &crate::dwarf_info::VariableLocation::Register(dwarf_register_number(preg))
            )
        );
        assert!(entries[0].size > 0);
    }

    #[test]
    fn provenance_debug_variables_seed_spilled_value_stack_range_after_o3_prepare() {
        let sig = IrSignature::new(vec![Type::I64, Type::I64], vec![Type::I64]);
        let mut ir_func = IrMachFunction::new("debug_spilled_value_provenance".to_string(), sig);
        let entry = ir_func.entry;
        let origin = trust_cg_ir::TrustIrInstId(0);
        let var_id = TrustIrVarId(VALUE_DEBUG_PROVENANCE_VAR_TAG | origin.0);
        let local_name = "value_0".to_string();
        ir_func
            .debug_meta
            .local_variables
            .push(trust_cg_ir::function::DebugLocalVariable {
                name: local_name.clone(),
                ty: DebugBaseType::I64,
                storage: DebugVariableStorage::ProvenanceVar(var_id),
                decl_line: 73,
            });

        let tracked = VReg::new(0, RegClass::Gpr64);
        let tracked_inst = ir_func.push_inst(
            IrMachInst::with_flags(
                IrOpcode::AddRR,
                vec![
                    IrOperand::VReg(tracked),
                    IrOperand::PReg(X0),
                    IrOperand::PReg(X1),
                ],
                IrOpcode::AddRR.default_flags() | InstFlags::HAS_SIDE_EFFECTS,
            )
            .with_source_loc(trust_cg_ir::SourceLoc {
                file: 0,
                line: 73,
                col: 11,
            }),
        );
        ir_func.append_inst(entry, tracked_inst);

        let mut live = vec![tracked];
        for i in 1..34u32 {
            let vreg = VReg::new(i, RegClass::Gpr64);
            let inst = ir_func.push_inst(IrMachInst::with_flags(
                IrOpcode::MovI,
                vec![IrOperand::VReg(vreg), IrOperand::Imm((i + 100) as i64)],
                IrOpcode::MovI.default_flags() | InstFlags::HAS_SIDE_EFFECTS,
            ));
            ir_func.append_inst(entry, inst);
            live.push(vreg);
        }

        let mut acc = live[0];
        for (next_vreg, value) in (64u32..).zip(live.iter().copied().skip(1)) {
            let next = VReg::new(next_vreg, RegClass::Gpr64);
            let inst = ir_func.push_inst(IrMachInst::with_flags(
                IrOpcode::AddRR,
                vec![
                    IrOperand::VReg(next),
                    IrOperand::VReg(acc),
                    IrOperand::VReg(value),
                ],
                IrOpcode::AddRR.default_flags() | InstFlags::HAS_SIDE_EFFECTS,
            ));
            ir_func.append_inst(entry, inst);
            acc = next;
        }
        let copy = ir_func.push_inst(IrMachInst::new(
            IrOpcode::Copy,
            vec![IrOperand::PReg(X0), IrOperand::VReg(acc)],
        ));
        ir_func.append_inst(entry, copy);
        let ret = ir_func.push_inst(IrMachInst::new(IrOpcode::Ret, vec![]));
        ir_func.append_inst(entry, ret);

        let mut provenance = trust_cg_ir::ProvenanceMap::new();
        provenance.record_lowering(
            origin,
            &[tracked_inst],
            trust_cg_ir::PassId::new("test-isel"),
        );
        let pipeline = Pipeline::new(PipelineConfig {
            opt_level: OptLevel::O3,
            emit_debug: true,
            verify: false,
            ..PipelineConfig::default()
        });
        let mut provenance = Some(provenance);
        pipeline.run_optimization_with_proof_metadata(&mut ir_func, None, provenance.as_mut());
        pipeline
            .run_verification(&ir_func)
            .expect("test function should verify before regalloc");
        let regalloc = pipeline
            .run_regalloc(&mut ir_func)
            .expect("O3 prepare should run regalloc");
        assert!(
            regalloc.spill_slot_count > 0,
            "test fixture must force register-allocation spills"
        );
        lower_copies(&mut ir_func).unwrap();
        eliminate_dead_unallocated_defs(&mut ir_func);
        bind_dead_unallocated_defs_to_discard_registers(&mut ir_func)
            .expect("dead defs should bind to discard registers");
        ensure_no_unresolved_vregs(&ir_func, "regalloc/copy lowering")
            .expect("prepared test function should not have unresolved vregs");
        let frame_layout = pipeline
            .run_frame_lowering(&mut ir_func)
            .expect("test function should frame-lower");
        crate::lower::expand_trap_bounds_check_exact(&mut ir_func);
        crate::lower::expand_trap_null_if_zero(&mut ir_func);
        crate::lower::expand_trap_div_zero_if_zero(&mut ir_func);
        crate::lower::expand_trap_shift_range_if_oob(&mut ir_func);
        crate::lower::expand_trap_overflow_exact(&mut ir_func);
        resolve_branches_after_authority(&mut ir_func)
            .expect("prepared debug function must resolve branches");
        seed_spilled_value_debug_provenance(
            &ir_func,
            &mut provenance,
            &regalloc.debug_snapshot,
            &BTreeMap::new(),
        )
        .expect("test spilled value provenance should be valid");
        seed_register_value_debug_provenance(&ir_func, &mut provenance, &regalloc.debug_snapshot)
            .expect("test register value provenance should be valid");
        seed_constant_value_debug_provenance(&ir_func, &mut provenance)
            .expect("test constant value provenance should be valid");
        seed_stack_alloca_debug_provenance(&ir_func, &mut provenance)
            .expect("test stack alloca provenance should be valid");
        let prepared = ir_func;
        let provenance = provenance.expect("test provenance should remain available");

        let ranges = provenance.var_live_ranges(var_id);
        assert_eq!(ranges.len(), 1);
        let trust_cg_ir::provenance::LocationExpr::Stack(slot) = ranges[0].value else {
            panic!("spilled value local should seed a stack location");
        };
        assert_eq!(ranges[0].end, InstId(prepared.insts.len() as u32));

        let ordered_insts: Vec<_> = prepared
            .block_order
            .iter()
            .flat_map(|block_id| prepared.blocks[block_id.0 as usize].insts.iter().copied())
            .collect();
        let start_index = ordered_insts
            .iter()
            .position(|inst| *inst == ranges[0].start)
            .expect("stack range start should be a materialized instruction boundary");
        assert!(
            start_index > 0,
            "stack range should start after the spill store, not at function entry"
        );
        let materializing_store = ordered_insts[start_index - 1];
        let previous_inst = prepared.inst(materializing_store);
        assert_eq!(
            previous_inst.opcode,
            IrOpcode::StrRI,
            "stack range should start immediately after the materialized spill store"
        );
        let store_entry = provenance
            .get_entry(materializing_store)
            .expect("materialized spill store should carry debug provenance");
        assert_eq!(store_entry.trust_ir_origins, vec![origin]);
        assert!(
            provenance
                .get_mach_insts(origin)
                .is_some_and(|insts| insts.contains(&materializing_store)),
            "materialized spill store should remain linked to the value origin"
        );

        let frame_offsets = crate::frame::stack_slot_frame_offsets(&prepared, &frame_layout);
        let frame_offset =
            frame_offsets[slot.0 as usize].expect("spill stack slot should have frame offset");
        let code = encode_function(&prepared).expect("prepared function should encode");
        let variables = build_debug_variables(
            &prepared,
            &prepared.debug_meta,
            Some(&frame_layout),
            code.len() as u32,
            Some(&provenance),
        );
        let value_0: Vec<_> = variables
            .iter()
            .filter(|variable| variable.name == local_name)
            .collect();
        assert_eq!(value_0.len(), 1);
        let crate::dwarf_info::VariableLocation::LocationList(entries) = &value_0[0].location
        else {
            panic!("seeded stack provenance should reach the loclist consumer");
        };
        assert_eq!(entries.len(), 1);
        assert!(entries[0].low_pc > 0);
        assert!(entries[0].size > 0);
        assert_eq!(
            entries[0].expression,
            crate::dwarf_info::encode_location_expr(
                &crate::dwarf_info::VariableLocation::FrameOffset(i64::from(frame_offset))
            )
        );
    }

    /// Post-RA layout order can diverge from arena-id order: a frame-address
    /// materialization created early in the arena (small raw `InstId`) may be
    /// placed late in the block. If that instruction is the first clobber of
    /// a register-value debug local's `preg`, the discovered range is valid
    /// in layout positions but inverted in raw IDs — and
    /// `ProvenanceMap::declare_var` validates raw IDs (`start < end`), which
    /// used to fail-close whole modules (`InvalidRange { start: 39, end: 1 }`
    /// on the `precondition_check` shims once the logical-immediate fold
    /// changed register assignment). Such a range is unrepresentable: the
    /// seeder must drop the location, not error.
    #[test]
    fn register_value_debug_provenance_drops_layout_raw_id_inverted_range() {
        let sig = IrSignature::new(vec![Type::I64, Type::I64], vec![Type::I64]);
        let mut ir_func = IrMachFunction::new("debug_raw_id_inverted_range".to_string(), sig);
        let entry = ir_func.entry;
        let origin = trust_cg_ir::TrustIrInstId(38);
        let var_id = TrustIrVarId(VALUE_DEBUG_PROVENANCE_VAR_TAG | origin.0);
        ir_func
            .debug_meta
            .local_variables
            .push(trust_cg_ir::function::DebugLocalVariable {
                name: "shifted".to_string(),
                ty: DebugBaseType::I64,
                storage: DebugVariableStorage::ProvenanceVar(var_id),
                decl_line: 17,
            });

        // Arena id 0: created FIRST but placed late in layout — clobbers X2.
        let frame_addr = ir_func.push_inst(IrMachInst::new(
            IrOpcode::SubRI,
            vec![
                IrOperand::PReg(X2),
                IrOperand::PReg(X29),
                IrOperand::Imm(32),
            ],
        ));
        // Arena id 1: the tracked value's def (start of the register range).
        let lsl = ir_func.push_inst(IrMachInst::new(
            IrOpcode::LslRR,
            vec![
                IrOperand::PReg(X2),
                IrOperand::PReg(X0),
                IrOperand::PReg(X3),
            ],
        ));
        // Arena id 2: folded logical-immediate consumer; does not redefine X2.
        let orr = ir_func.push_inst(IrMachInst::new(
            IrOpcode::OrrRI,
            vec![IrOperand::PReg(X0), IrOperand::PReg(X2), IrOperand::Imm(1)],
        ));
        let ret = ir_func.push_inst(IrMachInst::new(IrOpcode::Ret, vec![]));
        ir_func.append_inst(entry, lsl);
        ir_func.append_inst(entry, orr);
        ir_func.append_inst(entry, frame_addr);
        ir_func.append_inst(entry, ret);

        let mut provenance = trust_cg_ir::ProvenanceMap::new();
        provenance.record_lowering(origin, &[lsl], trust_cg_ir::PassId::new("test-isel"));
        let snapshot = RegAllocDebugSnapshot {
            allocation: BTreeMap::new(),
            spilled_vregs: BTreeSet::new(),
            spill_slots: BTreeMap::new(),
            spill_stores: vec![],
            inst_map: vec![Some(frame_addr), Some(lsl), Some(orr), Some(ret)],
            defs: BTreeMap::from([(lsl, RegAllocDebugDef::PReg(X2))]),
        };

        let mut provenance = Some(provenance);
        seed_register_value_debug_provenance(&ir_func, &mut provenance, &snapshot).expect(
            "a layout-valid but raw-id-inverted register range must be dropped, not fail-close",
        );

        let provenance = provenance.expect("provenance should remain available");
        assert!(
            provenance.var_live_ranges(var_id).is_empty(),
            "unrepresentable range must produce no location at all"
        );
    }

    #[test]
    fn spilled_value_debug_provenance_accepts_spilled_range_from_cloned_origin() {
        let sig = IrSignature::new(vec![Type::I64, Type::I64], vec![Type::I64]);
        let mut ir_func = IrMachFunction::new("debug_spilled_value_cloned_origin".to_string(), sig);
        let entry = ir_func.entry;
        let slot = ir_func.alloc_stack_slot(StackSlot::new(8, 8));
        let origin = trust_cg_ir::TrustIrInstId(7);
        let var_id = TrustIrVarId(VALUE_DEBUG_PROVENANCE_VAR_TAG | origin.0);
        ir_func
            .debug_meta
            .local_variables
            .push(trust_cg_ir::function::DebugLocalVariable {
                name: "spill_probe".to_string(),
                ty: DebugBaseType::I64,
                storage: DebugVariableStorage::ProvenanceVar(var_id),
                decl_line: 91,
            });

        let clone_inst = ir_func.push_inst(IrMachInst::new(
            IrOpcode::Movz,
            vec![IrOperand::PReg(X2), IrOperand::Imm(1)],
        ));
        let origin_inst = ir_func.push_inst(IrMachInst::new(
            IrOpcode::AddRR,
            vec![
                IrOperand::PReg(X16),
                IrOperand::PReg(X0),
                IrOperand::PReg(X1),
            ],
        ));
        let store = ir_func.push_inst(IrMachInst::new(
            IrOpcode::StrRI,
            vec![IrOperand::PReg(X16), IrOperand::StackSlot(slot)],
        ));
        let range_start = ir_func.push_inst(IrMachInst::new(
            IrOpcode::Movz,
            vec![IrOperand::PReg(X0), IrOperand::Imm(0)],
        ));
        ir_func.append_inst(entry, clone_inst);
        ir_func.append_inst(entry, origin_inst);
        ir_func.append_inst(entry, store);
        ir_func.append_inst(entry, range_start);

        let mut provenance = trust_cg_ir::ProvenanceMap::new();
        provenance.record_lowering(
            origin,
            &[origin_inst],
            trust_cg_ir::PassId::new("test-isel"),
        );
        provenance.record_clone(
            origin_inst,
            clone_inst,
            trust_cg_ir::PassId::new("test-clone"),
        );

        let tracked = VReg::new(42, RegClass::Gpr64);
        let snapshot = RegAllocDebugSnapshot {
            allocation: BTreeMap::new(),
            spilled_vregs: BTreeSet::from([tracked]),
            spill_slots: BTreeMap::from([(tracked, slot)]),
            spill_stores: vec![SpillMaterializedStore {
                vreg: tracked,
                slot,
                inst: store,
            }],
            inst_map: vec![
                Some(clone_inst),
                Some(origin_inst),
                Some(store),
                Some(range_start),
            ],
            defs: BTreeMap::from([(origin_inst, RegAllocDebugDef::VReg(tracked))]),
        };

        let mut provenance = Some(provenance);
        seed_spilled_value_debug_provenance(&ir_func, &mut provenance, &snapshot, &BTreeMap::new())
            .expect("cloned-origin spill debug provenance should seed");
        let provenance = provenance.expect("provenance should still exist");
        let ranges = provenance.var_live_ranges(var_id);
        assert_eq!(ranges.len(), 1);
        assert_eq!(ranges[0].start, range_start);
        assert_eq!(ranges[0].end, InstId(ir_func.insts.len() as u32));
        assert_eq!(ranges[0].value, LocationExpr::Stack(slot));

        let layout = crate::frame::FrameLayout {
            callee_saved_pairs: vec![],
            callee_saved_area_size: 0,
            spill_area_size: 8,
            local_area_size: 0,
            outgoing_arg_area_size: 0,
            total_frame_size: 16,
            uses_frame_pointer: true,
            is_leaf: true,
            uses_red_zone: false,
            fp_to_spill_offset: 0,
            has_dynamic_alloc: false,
        };
        let variables = build_debug_variables(
            &ir_func,
            &ir_func.debug_meta,
            Some(&layout),
            16,
            Some(&provenance),
        );
        let spill_probe = variables
            .iter()
            .find(|variable| variable.name == "spill_probe")
            .expect("spill_probe debug variable should be emitted");
        let crate::dwarf_info::VariableLocation::LocationList(entries) = &spill_probe.location
        else {
            panic!("spill_probe should use a bounded location list");
        };
        assert_eq!(entries.len(), 1);
        assert_eq!(entries[0].low_pc, 12);
        assert_eq!(entries[0].size, 4);
        assert_eq!(
            entries[0].expression,
            crate::dwarf_info::encode_location_expr(
                &crate::dwarf_info::VariableLocation::FrameOffset(-8)
            )
        );
    }

    #[test]
