    #[test]
    fn constant_debug_provenance_rejects_nonzero_move_wide_seed_shifts() {
        let mut func = IrMachFunction::new(
            "debug_shifted_move_wide".to_string(),
            IrSignature::new(vec![], vec![]),
        );
        let explicit_zero = func.push_inst(IrMachInst::new(
            IrOpcode::Movz,
            vec![IrOperand::PReg(X0), IrOperand::Imm(7), IrOperand::Imm(0)],
        ));
        let shifted_movz = func.push_inst(IrMachInst::new(
            IrOpcode::Movz,
            vec![IrOperand::PReg(X1), IrOperand::Imm(7), IrOperand::Imm(16)],
        ));
        let shifted_movn = func.push_inst(IrMachInst::new(
            IrOpcode::Movn,
            vec![IrOperand::PReg(X2), IrOperand::Imm(0), IrOperand::Imm(16)],
        ));
        let malformed_extra = func.push_inst(IrMachInst::new(
            IrOpcode::Movz,
            vec![
                IrOperand::PReg(X3),
                IrOperand::Imm(7),
                IrOperand::Imm(0),
                IrOperand::Imm(0),
            ],
        ));
        for inst_id in [explicit_zero, shifted_movz, shifted_movn, malformed_extra] {
            func.append_inst(func.entry, inst_id);
        }

        assert_eq!(
            const_value_from_materialization_chain(&func, &[explicit_zero], 64),
            Some((explicit_zero, 7))
        );
        assert_eq!(
            const_value_from_materialization_chain(&func, &[shifted_movz], 64),
            None
        );
        assert_eq!(
            const_value_from_materialization_chain(&func, &[shifted_movn], 64),
            None
        );
        assert_eq!(
            const_value_from_materialization_chain(&func, &[malformed_extra], 64),
            None
        );
    }

