    #[test]
    fn fsym_trust_ir_preflight_metrics_are_emitted_from_prepare_pipeline() {
        let mut module = trust_ir::Module::new("fsym_codegen");
        let ft = module.add_func_type(trust_ir::FuncTy {
            params: vec![],
            returns: vec![trust_ir::Ty::I64],
            is_vararg: false,
        });
        let mut func = trust_ir::Function::new(
            trust_ir::FuncId::new(0),
            "divzero",
            ft,
            trust_ir::BlockId::new(0),
        );
        func.blocks = vec![trust_ir::Block {
            id: trust_ir::BlockId::new(0),
            params: vec![],
            body: vec![
                trust_ir::InstrNode::new(trust_ir::Inst::Const {
                    ty: trust_ir::Ty::I64,
                    value: trust_ir::Constant::Int(42),
                })
                .with_result(trust_ir::ValueId::new(0)),
                trust_ir::InstrNode::new(trust_ir::Inst::Const {
                    ty: trust_ir::Ty::I64,
                    value: trust_ir::Constant::Int(0),
                })
                .with_result(trust_ir::ValueId::new(1)),
                trust_ir::InstrNode::new(trust_ir::Inst::BinOp {
                    op: trust_ir::BinOp::SDiv,
                    ty: trust_ir::Ty::I64,
                    lhs: trust_ir::ValueId::new(0),
                    rhs: trust_ir::ValueId::new(1),
                })
                .with_result(trust_ir::ValueId::new(2))
                .with_span(trust_ir::SourceSpan {
                    file: 7,
                    line: 11,
                    col: 13,
                }),
                trust_ir::InstrNode::new(trust_ir::Inst::Return {
                    values: vec![trust_ir::ValueId::new(2)],
                }),
            ],
        }];
        module.add_function(func);

        let (lir_func, proof_ctx) =
            trust_cg_lower::translate_function(&module.functions[0], &module).expect("translate");
        let pipeline = Pipeline::new(PipelineConfig {
            opt_level: OptLevel::O0,
            enable_fsym_trust_ir_preflight: true,
            ..PipelineConfig::default()
        });

        let (prepared, metrics) = pipeline
            .prepare_function_with_metrics_and_trust_ir_module(
                &lir_func,
                Some(&proof_ctx),
                &module,
                &module.functions[0],
            )
            .expect("prepare should compile after fsym preflight");

        let summary = metrics
            .fsym_trust_ir_summary
            .expect("fsym summary should be emitted");
        assert_eq!(summary.module_name, "fsym_codegen");
        assert_eq!(summary.function_name, "divzero");
        assert!(summary.scanned);
        assert_eq!(summary.diagnostic_count, 1);
        assert_eq!(summary.warning_count, 1);
        assert_eq!(summary.diagnostics[0].kind, "Arithmetic");
        assert_eq!(
            summary.diagnostics[0].span,
            Some(FsymTrustIrPipelineSourceSpan {
                file: 7,
                line: 11,
                col: 13
            })
        );
        assert!(
            summary.diagnostics[0]
                .warning
                .contains("warning[fsym]: arithmetic")
        );
        let summary_json =
            serde_json::to_value(&summary).expect("fsym preflight summary serializes");
        assert_eq!(summary_json["diagnostics"][0]["span"]["file"], 7);
        assert_eq!(summary_json["diagnostics"][0]["span"]["line"], 11);
        assert_eq!(summary_json["diagnostics"][0]["span"]["col"], 13);

        let object = pipeline
            .compile_module(&[prepared])
            .expect("prepared function should still reach module emission");
        assert!(object.len() >= 4);
    }

    /// FAIL-CLOSED wiring: a deref-coverage gap on the report must be carried
    /// into the pipeline summary (`coverage_error_count`/`coverage_errors`),
    /// which is the signal `run_fsym_trust_ir_preflight` turns into
    /// `PipelineError::FsymCoverageGap`. Mirrors the CLI gate on
    /// `report.has_coverage_error()` at the pipeline level.
    #[cfg(feature = "verify")]
    #[test]
    fn fsym_coverage_error_is_carried_into_pipeline_summary() {
        use trust_cg_verify::fsym_trust_ir::{FsymCoverageError, FsymTrustIrReport};

        let mut report = FsymTrustIrReport::default();
        report.scanned_function_names.push("gappy".to_string());
        report.coverage_errors.push(FsymCoverageError {
            module: "m".to_string(),
            function: "gappy".to_string(),
            block: 0,
            inst_index: 3,
            opcode: "Load",
            detail: "dropped deref obligation".to_string(),
        });
        // A coverage error for a DIFFERENT function must not be attributed here.
        report.coverage_errors.push(FsymCoverageError {
            module: "m".to_string(),
            function: "other".to_string(),
            block: 1,
            inst_index: 0,
            opcode: "Store",
            detail: "elsewhere".to_string(),
        });

        let summary = super::fsym_trust_ir_summary_from_report("m", "gappy", report);
        assert_eq!(
            summary.coverage_error_count, 1,
            "exactly the in-function coverage gap must be carried"
        );
        assert_eq!(summary.coverage_errors.len(), 1);
        assert!(
            summary.coverage_errors[0].contains("deref-coverage invariant violated"),
            "coverage gap detail must be rendered: {:?}",
            summary.coverage_errors
        );
        assert!(summary.coverage_errors[0].contains("Load"));
    }

    #[test]
    fn fsym_trust_ir_preflight_preserves_bounded_skip_limitations() {
        let mut module = trust_ir::Module::new("fsym_codegen_skip");
        let ft = module.add_func_type(trust_ir::FuncTy {
            params: vec![],
            returns: vec![trust_ir::Ty::I64],
            is_vararg: false,
        });
        let mut body = Vec::new();
        for idx in 0..=trust_cg_verify::fsym_trust_ir::FSYM_TRUST_IR_MAX_STRAIGHT_LINE_INSTRUCTIONS
        {
            body.push(
                trust_ir::InstrNode::new(trust_ir::Inst::Const {
                    ty: trust_ir::Ty::I64,
                    value: trust_ir::Constant::Int(i128::from(idx as u64)),
                })
                .with_result(trust_ir::ValueId::new(idx as u32)),
            );
        }
        body.push(trust_ir::InstrNode::new(trust_ir::Inst::Return {
            values: vec![trust_ir::ValueId::new(
                trust_cg_verify::fsym_trust_ir::FSYM_TRUST_IR_MAX_STRAIGHT_LINE_INSTRUCTIONS as u32,
            )],
        }));
        let mut func = trust_ir::Function::new(
            trust_ir::FuncId::new(0),
            "too_large",
            ft,
            trust_ir::BlockId::new(0),
        );
        func.blocks = vec![trust_ir::Block {
            id: trust_ir::BlockId::new(0),
            params: vec![],
            body,
        }];
        module.add_function(func);

        let (lir_func, proof_ctx) =
            trust_cg_lower::translate_function(&module.functions[0], &module).expect("translate");
        let pipeline = Pipeline::new(PipelineConfig {
            opt_level: OptLevel::O0,
            enable_fsym_trust_ir_preflight: true,
            ..PipelineConfig::default()
        });

        let (_prepared, metrics) = pipeline
            .prepare_function_with_metrics_and_trust_ir_module(
                &lir_func,
                Some(&proof_ctx),
                &module,
                &module.functions[0],
            )
            .expect("prepare should continue after bounded fsym skip");

        let summary = metrics
            .fsym_trust_ir_summary
            .expect("fsym summary should be emitted");
        assert!(!summary.scanned);
        assert_eq!(summary.warning_count, 1);
        let skipped = summary
            .skipped
            .expect("too-large function should be skipped");
        assert_eq!(skipped.reason, "TooLarge");
        assert!(skipped.detail.contains("over fsym bound"));
    }

