    #[test]
    fn proof_to_annotation_does_not_turn_range_into_bounds() {
        assert_eq!(
            proof_to_annotation(&trust_cg_lower::Proof::NoOverflow { signed: true }),
            Some(trust_cg_ir::ProofAnnotation::NoSignedOverflow)
        );
        assert_eq!(
            proof_to_annotation(&trust_cg_lower::Proof::NoOverflow { signed: false }),
            Some(trust_cg_ir::ProofAnnotation::NoUnsignedOverflow)
        );
        assert_eq!(
            proof_to_annotation(&trust_cg_lower::Proof::InRange { lo: 0, hi: 7 }),
            None
        );
        assert_eq!(
            proof_to_annotation(&trust_cg_lower::Proof::InBounds {
                base: trust_ir::ValueId::new(0),
                index: trust_ir::ValueId::new(1),
            }),
            None
        );
        assert_eq!(
            proof_to_annotation(&trust_cg_lower::Proof::ExactInBounds {
                base: trust_cg_lower::instructions::Value(0),
                index: trust_cg_lower::instructions::Value(1),
                bound: 8,
            }),
            Some(trust_cg_ir::ProofAnnotation::InBounds)
        );
    }

    fn proof_optimization_citation_module() -> trust_ir::Module {
        proof_optimization_citation_module_with_span(42, 7)
    }

    fn proof_optimization_citation_module_without_span() -> trust_ir::Module {
        let mut module = proof_optimization_citation_module();
        module.functions[0].blocks[0].body[0].span = None;
        module
    }

    fn proof_optimization_citation_module_with_span(line: u32, col: u32) -> trust_ir::Module {
        use trust_ir::{
            BinOp, Block as TrustIrBlock, BlockId, FuncId, FuncTy, Function as TrustIrFunction,
            Inst, InstrNode, Module as TrustIrModule, ProofAnnotation, SourceSpan, Ty, ValueId,
        };

        let mut module = TrustIrModule::new("proof_opt_codegen");
        let ft = module.add_func_type(FuncTy {
            params: vec![Ty::I64, Ty::I64],
            returns: vec![Ty::I64],
            is_vararg: false,
        });
        let mut func = TrustIrFunction::new(FuncId::new(0), "proof_opt_entry", ft, BlockId::new(0));
        func.blocks = vec![TrustIrBlock {
            id: BlockId::new(0),
            params: vec![(ValueId::new(0), Ty::I64), (ValueId::new(1), Ty::I64)],
            body: vec![
                InstrNode::new(Inst::BinOp {
                    op: BinOp::Add,
                    ty: Ty::I64,
                    lhs: ValueId::new(0),
                    rhs: ValueId::new(1),
                })
                .with_result(ValueId::new(2))
                .with_proof(ProofAnnotation::NoOverflow)
                .with_proof(ProofAnnotation::NoUndef)
                .with_proof(ProofAnnotation::BoundedLoop(8))
                .with_span(SourceSpan { file: 1, line, col }),
                InstrNode::new(Inst::Return {
                    values: vec![ValueId::new(2)],
                }),
            ],
        }];
        module.add_function(func);
        module
    }

    fn proof_optimization_collision_module() -> trust_ir::Module {
        use trust_ir::{
            BinOp, Block as TrustIrBlock, BlockId, FuncId, FuncTy, Function as TrustIrFunction,
            Inst, InstrNode, Module as TrustIrModule, ProofAnnotation, SourceSpan, Ty, ValueId,
        };

        let mut module = TrustIrModule::new("proof_opt_codegen_collision");
        let ft = module.add_func_type(FuncTy {
            params: vec![Ty::I64, Ty::I64],
            returns: vec![Ty::I64],
            is_vararg: false,
        });
        let mut func = TrustIrFunction::new(
            FuncId::new(0),
            "proof_opt_collision_entry",
            ft,
            BlockId::new(0),
        );
        let colliding_span = SourceSpan {
            file: 1,
            line: 42,
            col: 7,
        };
        func.blocks = vec![TrustIrBlock {
            id: BlockId::new(0),
            params: vec![(ValueId::new(0), Ty::I64), (ValueId::new(1), Ty::I64)],
            body: vec![
                InstrNode::new(Inst::BinOp {
                    op: BinOp::Add,
                    ty: Ty::I64,
                    lhs: ValueId::new(0),
                    rhs: ValueId::new(1),
                })
                .with_result(ValueId::new(2))
                .with_proof(ProofAnnotation::NoOverflow)
                .with_span(colliding_span),
                InstrNode::new(Inst::BinOp {
                    op: BinOp::Add,
                    ty: Ty::I64,
                    lhs: ValueId::new(2),
                    rhs: ValueId::new(1),
                })
                .with_result(ValueId::new(3))
                .with_proof(ProofAnnotation::NoOverflow)
                .with_span(colliding_span),
                InstrNode::new(Inst::Return {
                    values: vec![ValueId::new(3)],
                }),
            ],
        }];
        module.add_function(func);
        module
    }

    #[test]
    fn production_pipeline_keeps_forged_proof_sidecars_report_only() {
        let module = proof_optimization_citation_module();
        let lowered = trust_cg_lower::translate_module(&module).expect("trust_ir lowers");
        let (lir_func, proof_ctx) = lowered.first().expect("module has one function");
        let pipeline = Pipeline::new(PipelineConfig {
            opt_level: OptLevel::O2,
            ..PipelineConfig::default()
        });

        let (_prepared, metrics) = pipeline
            .prepare_function_with_metrics_and_trust_ir_provenance(
                lir_func,
                Some(proof_ctx),
                &module.functions[0],
            )
            .expect("real codegen preparation succeeds");

        assert!(metrics.proof_optimization_certificates.is_empty());
        assert!(!trust_cg_lower::guard_evidence::validator_guard_replay_authority_available());
        // The source module still carries all labels for reporting/audit; only the optimization
        // authority channel is empty.
        assert_eq!(module.functions[0].blocks[0].body[0].proofs.len(), 3);
    }

    #[test]
    fn proof_optimization_citation_json_value_preserves_wire_fields() {
        // Wire-format coverage is intentionally structural. Production must not mint this
        // citation from public trust_ir labels until exact validator replay authority is wired.
        let cert = ProofOptimizationCertificateCitation {
            function_name: "proof_opt_entry".to_owned(),
            certificate_id: "00000000000000000000000000000001".to_owned(),
            proof_hash: "00000000000000000000000000000002".to_owned(),
            validation_hash: "00000000000000000000000000000003".to_owned(),
            source_region_hash: "00000000000000000000000000000004".to_owned(),
            target_region_hash: "00000000000000000000000000000005".to_owned(),
            transform_name: "proof-opts.structural-test".to_owned(),
            transform_version: 1,
            admission: "structural-test".to_owned(),
            kind: "GuardEliminated".to_owned(),
            status: "applied".to_owned(),
            rejection_code: None,
            rejection_fact: None,
            rejection_detail: None,
            consumed_facts: vec![ProofOptimizationConsumedFactCitation {
                name: "NotNull".to_owned(),
                payload: None,
            }],
        };
        let json = cert.to_json_value();

        assert_eq!(json["function_name"], "proof_opt_entry");
        assert_eq!(json["certificate_id"], cert.certificate_id);
        assert_eq!(json["proof_hash"], cert.proof_hash);
        assert_eq!(json["validation_hash"], cert.validation_hash);
        assert_eq!(json["source_region_hash"], cert.source_region_hash);
        assert_eq!(json["target_region_hash"], cert.target_region_hash);
        assert_eq!(json["transform_name"], cert.transform_name);
        assert_eq!(json["transform_version"], cert.transform_version);
        assert_eq!(json["admission"], cert.admission);
        assert_eq!(json["kind"], cert.kind);
        assert_eq!(json["status"], cert.status);
        assert_eq!(
            json["rejection_code"],
            cert.rejection_code
                .as_ref()
                .map_or(serde_json::Value::Null, |code| {
                    serde_json::Value::String(code.clone())
                })
        );
        assert_eq!(
            json["rejection_fact"],
            cert.rejection_fact
                .as_ref()
                .map_or(serde_json::Value::Null, |fact| {
                    serde_json::Value::String(fact.clone())
                })
        );
        assert_eq!(
            json["rejection_detail"],
            cert.rejection_detail
                .as_ref()
                .map_or(serde_json::Value::Null, |detail| {
                    serde_json::Value::String(detail.clone())
                })
        );
        assert_eq!(
            json["consumed_facts"],
            serde_json::Value::Array(
                cert.consumed_facts
                    .iter()
                    .map(|fact| {
                        let mut object = serde_json::Map::with_capacity(2);
                        object.insert(
                            "name".to_owned(),
                            serde_json::Value::String(fact.name.clone()),
                        );
                        object.insert(
                            "payload".to_owned(),
                            fact.payload
                                .as_ref()
                                .map_or(serde_json::Value::Null, |payload| {
                                    serde_json::Value::String(payload.clone())
                                }),
                        );
                        serde_json::Value::Object(object)
                    })
                    .collect()
            )
        );
    }

    fn production_proof_optimization_certificates(
        module: &trust_ir::Module,
    ) -> Vec<ProofOptimizationCertificateCitation> {
        let lowered = trust_cg_lower::translate_module(module).expect("trust_ir lowers");
        let (lir_func, proof_ctx) = lowered.first().expect("module has one function");
        let pipeline = Pipeline::new(PipelineConfig {
            opt_level: OptLevel::O2,
            ..PipelineConfig::default()
        });

        let (_prepared, metrics) = pipeline
            .prepare_function_with_metrics_and_trust_ir_provenance(
                lir_func,
                Some(proof_ctx),
                &module.functions[0],
            )
            .expect("real codegen preparation succeeds");

        metrics.proof_optimization_certificates
    }

    #[test]
    fn production_does_not_mint_proof_citations_from_labels_at_any_source_loc() {
        let first = production_proof_optimization_certificates(
            &proof_optimization_citation_module_with_span(42, 7),
        );
        let moved_source_loc = production_proof_optimization_certificates(
            &proof_optimization_citation_module_with_span(99, 13),
        );

        assert!(first.is_empty());
        assert!(moved_source_loc.is_empty());
    }

    #[test]
    fn production_does_not_mint_proof_citations_from_labels_without_source_loc() {
        let certs = production_proof_optimization_certificates(
            &proof_optimization_citation_module_without_span(),
        );

        assert!(certs.is_empty());
    }

    #[test]
    fn duplicate_source_locs_cannot_mint_multiple_label_only_citations() {
        let module = proof_optimization_collision_module();
        let certs = production_proof_optimization_certificates(&module);

        assert!(certs.is_empty());
        assert_eq!(module.functions[0].blocks[0].body[0].proofs.len(), 1);
        assert_eq!(module.functions[0].blocks[0].body[1].proofs.len(), 1);
    }

    #[test]
    fn apply_proof_annotations_skips_unrepresentable_range_proofs() {
        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("proof_binding".to_string(), sig);
        let dst = VReg::new(0, RegClass::Gpr64);
        let lhs = VReg::new(1, RegClass::Gpr64);
        let rhs = VReg::new(2, RegClass::Gpr64);
        let inst_id = func.push_inst(IrMachInst::new(
            IrOpcode::AddRR,
            vec![
                IrOperand::VReg(dst),
                IrOperand::VReg(lhs),
                IrOperand::VReg(rhs),
            ],
        ));
        func.append_inst(func.entry, inst_id);

        let value = trust_cg_lower::instructions::Value(42);
        let mut proof_ctx = trust_cg_lower::ProofContext::default();
        proof_ctx.value_proofs.insert(
            value,
            vec![
                trust_cg_lower::Proof::InRange { lo: 0, hi: 7 },
                trust_cg_lower::Proof::NoOverflow { signed: true },
            ],
        );

        let mut value_map = std::collections::HashMap::new();
        value_map.insert(value, trust_cg_lower::ISelOperand::VReg(dst));

        apply_proof_annotations(&mut func, &proof_ctx, &value_map);

        assert_eq!(
            func.inst(inst_id).proof,
            Some(trust_cg_ir::ProofAnnotation::NoSignedOverflow),
            "range facts must not masquerade as bounds facts or hide later consumable proofs"
        );
    }

