    #[test]
    fn apply_proof_annotations_keys_defs_by_full_vreg_class() {
        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("vreg_class_binding".to_string(), sig);
        let gpr = VReg::new(0, RegClass::Gpr64);
        let fpr = VReg::new(0, RegClass::Fpr64);
        let gpr_id = func.push_inst(IrMachInst::new(
            IrOpcode::AddRR,
            vec![
                IrOperand::VReg(gpr),
                IrOperand::VReg(gpr),
                IrOperand::VReg(gpr),
            ],
        ));
        let fpr_id = func.push_inst(IrMachInst::new(
            IrOpcode::FaddRR,
            vec![
                IrOperand::VReg(fpr),
                IrOperand::VReg(fpr),
                IrOperand::VReg(fpr),
            ],
        ));
        func.append_inst(func.entry, gpr_id);
        func.append_inst(func.entry, fpr_id);

        let value = trust_cg_lower::instructions::Value(12);
        let mut proof_ctx = trust_cg_lower::ProofContext::default();
        proof_ctx.value_proofs.insert(
            value,
            vec![trust_cg_lower::Proof::NoOverflow { signed: true }],
        );

        let mut value_map = std::collections::HashMap::new();
        value_map.insert(value, trust_cg_lower::ISelOperand::VReg(fpr));

        apply_proof_annotations(&mut func, &proof_ctx, &value_map);

        assert_eq!(func.inst(gpr_id).proof, None);
        assert_eq!(
            func.inst(fpr_id).proof,
            Some(trust_cg_ir::ProofAnnotation::NoSignedOverflow),
            "same numeric VReg id in a different class must bind to the matching class"
        );
    }

