    #[test]
    fn prepare_o2_keeps_notnull_guard_without_validator_replay() {
        let mut func = trust_cg_lower::Function::new(
            "nonnull_o2".to_string(),
            trust_cg_lower::function::Signature {
                params: vec![trust_cg_lower::Type::I64],
                returns: vec![],
            },
        );
        func.block_order
            .push(trust_cg_lower::instructions::Block(0));
        func.blocks.insert(
            trust_cg_lower::instructions::Block(0),
            trust_cg_lower::function::BasicBlock {
                params: vec![],
                instructions: vec![
                    trust_cg_lower::instructions::Instruction {
                        opcode: trust_cg_lower::instructions::Opcode::GuardNull {
                            obligation: None,
                        },
                        args: vec![trust_cg_lower::instructions::Value(0)],
                        results: vec![],
                    },
                    trust_cg_lower::instructions::Instruction {
                        opcode: trust_cg_lower::instructions::Opcode::Return,
                        args: vec![],
                        results: vec![],
                    },
                ],
                source_locs: vec![],
            },
        );
        func.value_types.insert(
            trust_cg_lower::instructions::Value(0),
            trust_cg_lower::Type::I64,
        );

        let mut proof_ctx = trust_cg_lower::ProofContext::default();
        proof_ctx.value_proofs.insert(
            trust_cg_lower::instructions::Value(0),
            vec![trust_cg_lower::Proof::NotNull {
                ptr: trust_ir::ValueId::new(0),
            }],
        );

        let pipeline = Pipeline::new(PipelineConfig {
            opt_level: OptLevel::O2,
            ..PipelineConfig::default()
        });
        let (prepared, metrics) = pipeline
            .prepare_function_with_metrics(&func, Some(&proof_ctx))
            .expect("O2 preparation succeeds");

        assert!(prepared.blocks.iter().any(|block| {
            block
                .insts
                .iter()
                .any(|inst_id| prepared.inst(*inst_id).opcode == IrOpcode::Cbnz)
        }));
        assert!(prepared.blocks.iter().any(|block| {
            block
                .insts
                .iter()
                .any(|inst_id| prepared.inst(*inst_id).opcode == IrOpcode::Brk)
        }));
        assert!(
            metrics
                .proof_optimization_certificates
                .iter()
                .all(|cert| { cert.kind != "GuardEliminated" || cert.status != "applied" })
        );
        assert!(!trust_cg_lower::guard_evidence::validator_guard_replay_authority_available());
    }

    #[test]
    fn apply_proof_annotations_binds_inbounds_only_to_exact_bounds_guard() {
        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("bounds_guard".to_string(), sig);
        let base = VReg::new(3, RegClass::Gpr64);
        let index = VReg::new(4, RegClass::Gpr64);
        let guard_id = func.push_inst(IrMachInst::new(
            IrOpcode::TrapBoundsCheckExact,
            vec![
                IrOperand::VReg(base),
                IrOperand::VReg(index),
                IrOperand::Imm(8),
            ],
        ));
        func.append_inst(func.entry, guard_id);

        let base_value = trust_cg_lower::instructions::Value(23);
        let index_value = trust_cg_lower::instructions::Value(24);
        let mut proof_ctx = trust_cg_lower::ProofContext::default();
        proof_ctx.value_proofs.insert(
            index_value,
            vec![trust_cg_lower::Proof::ExactInBounds {
                base: base_value,
                index: index_value,
                bound: 8,
            }],
        );
        let mut value_map = std::collections::HashMap::new();
        value_map.insert(base_value, trust_cg_lower::ISelOperand::VReg(base));
        value_map.insert(index_value, trust_cg_lower::ISelOperand::VReg(index));

        apply_proof_annotations(&mut func, &proof_ctx, &value_map);

        assert_eq!(
            func.inst(guard_id).proof,
            Some(trust_cg_ir::ProofAnnotation::InBounds)
        );
    }

