    #[test]
    fn proof_optimization_metadata_at_offset_zero_is_report_only_without_replay_authority() {
        use trust_cg_opt::pass_manager::MachinePass;

        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("aligned_pair_metadata".to_string(), sig);
        let ptr = VReg::new(0, RegClass::Gpr64);

        let str0 = func.push_inst(IrMachInst::new(
            IrOpcode::StrRI,
            vec![IrOperand::PReg(X0), IrOperand::VReg(ptr), IrOperand::Imm(0)],
        ));
        let str1 = func.push_inst(IrMachInst::new(
            IrOpcode::StrRI,
            vec![IrOperand::PReg(X1), IrOperand::VReg(ptr), IrOperand::Imm(8)],
        ));
        func.append_inst(func.entry, str0);
        func.append_inst(func.entry, str1);

        let mut proof_ctx = trust_cg_lower::ProofContext::default();
        let pointer_value = trust_cg_lower::instructions::Value(0);
        proof_ctx
            .value_facts
            .insert(pointer_value, vec![trust_cg_lower::ProofFact::Aligned(16)]);

        let mut value_map = std::collections::HashMap::new();
        value_map.insert(pointer_value, trust_cg_lower::ISelOperand::VReg(ptr));

        let metadata = proof_optimization_metadata_from_context(&func, &proof_ctx, &value_map);
        let mut pass = trust_cg_opt::proof_opts::ProofOptimization::new();
        pass.set_metadata(&metadata);

        assert_eq!(
            metadata.inst_proof_facts(str0),
            &[trust_cg_ir::ProofFact::Aligned(16)]
        );
        assert!(!pass.run(&mut func));
        assert_eq!(pass.stats().pair_mem_ops_combined, 0);
        assert_eq!(func.block(func.entry).insts, vec![str0, str1]);
        assert!(pass.certificates().is_empty());
    }

