    #[test]
    fn aligned_base_through_early_addri_temps_remains_report_only() {
        use trust_cg_opt::addr_mode::AddrModeEarlyFormation;
        use trust_cg_opt::pass_manager::MachinePass;
        use trust_cg_opt::proof_opts::ProofOptimization;

        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("aligned_pair_addri_metadata".to_string(), sig);
        let val0 = VReg::new(0, RegClass::Gpr64);
        let val1 = VReg::new(1, RegClass::Gpr64);
        let ptr = VReg::new(2, RegClass::Gpr64);
        let tmp0 = VReg::new(3, RegClass::Gpr64);
        let tmp1 = VReg::new(4, RegClass::Gpr64);

        let add0 = func.push_inst(IrMachInst::new(
            IrOpcode::AddRI,
            vec![
                IrOperand::VReg(tmp0),
                IrOperand::VReg(ptr),
                IrOperand::Imm(0),
            ],
        ));
        let str0 = func.push_inst(IrMachInst::new(
            IrOpcode::StrRI,
            vec![
                IrOperand::VReg(val0),
                IrOperand::VReg(tmp0),
                IrOperand::Imm(0),
            ],
        ));
        let add1 = func.push_inst(IrMachInst::new(
            IrOpcode::AddRI,
            vec![
                IrOperand::VReg(tmp1),
                IrOperand::VReg(ptr),
                IrOperand::Imm(8),
            ],
        ));
        let str1 = func.push_inst(IrMachInst::new(
            IrOpcode::StrRI,
            vec![
                IrOperand::VReg(val1),
                IrOperand::VReg(tmp1),
                IrOperand::Imm(0),
            ],
        ));
        let ret = func.push_inst(IrMachInst::new(IrOpcode::Ret, vec![]));
        for inst_id in [add0, str0, add1, str1, ret] {
            func.append_inst(func.entry, inst_id);
        }

        let mut proof_ctx = trust_cg_lower::ProofContext::default();
        let pointer_value = trust_cg_lower::instructions::Value(0);
        proof_ctx
            .value_facts
            .insert(pointer_value, vec![trust_cg_lower::ProofFact::Aligned(16)]);

        let mut value_map = std::collections::HashMap::new();
        value_map.insert(pointer_value, trust_cg_lower::ISelOperand::VReg(ptr));

        let metadata = proof_optimization_metadata_from_context(&func, &proof_ctx, &value_map);

        let mut addrmode = AddrModeEarlyFormation;
        assert!(addrmode.run(&mut func));
        assert_eq!(func.block(func.entry).insts, vec![str0, str1, ret]);

        let mut proof = ProofOptimization::new();
        proof.set_metadata(&metadata);
        assert_eq!(
            metadata.inst_proof_facts(str0),
            &[trust_cg_ir::ProofFact::Aligned(16)]
        );
        assert!(!proof.run(&mut func));
        assert_eq!(proof.stats().pair_mem_ops_combined, 0);
        assert_eq!(func.block(func.entry).insts, vec![str0, str1, ret]);
        assert!(proof.certificates().is_empty());
    }

