    #[test]
    fn alignment_fact_movz_decoder_rejects_shifted_or_malformed_constants() {
        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("aligned_pair_movz_shape".to_string(), sig);
        let explicit_zero = VReg::new(0, RegClass::Gpr64);
        let shifted = VReg::new(1, RegClass::Gpr64);
        let extra = VReg::new(2, RegClass::Gpr64);

        let explicit_zero_id = func.push_inst(IrMachInst::new(
            IrOpcode::Movz,
            vec![
                IrOperand::VReg(explicit_zero),
                IrOperand::Imm(8),
                IrOperand::Imm(0),
            ],
        ));
        let shifted_id = func.push_inst(IrMachInst::new(
            IrOpcode::Movz,
            vec![
                IrOperand::VReg(shifted),
                IrOperand::Imm(8),
                IrOperand::Imm(16),
            ],
        ));
        let extra_id = func.push_inst(IrMachInst::new(
            IrOpcode::Movz,
            vec![
                IrOperand::VReg(extra),
                IrOperand::Imm(8),
                IrOperand::Imm(0),
                IrOperand::Imm(0),
            ],
        ));
        let defs = std::collections::HashMap::from([
            (explicit_zero, Some(explicit_zero_id)),
            (shifted, Some(shifted_id)),
            (extra, Some(extra_id)),
        ]);

        assert_eq!(unique_gpr64_movz_imm(&func, &defs, explicit_zero), Some(8));
        assert_eq!(unique_gpr64_movz_imm(&func, &defs, shifted), None);
        assert_eq!(unique_gpr64_movz_imm(&func, &defs, extra), None);
    }

