    #[test]
    fn compile_module_registers_unresolved_call_as_undefined_symbol() {
        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("main".to_string(), sig);
        let entry = func.entry;
        let call = IrMachInst::new(IrOpcode::Bl, vec![IrOperand::Symbol("printf".to_string())]);
        let ret = IrMachInst::new(IrOpcode::Ret, vec![]);
        let call_id = func.push_inst(call);
        let ret_id = func.push_inst(ret);
        func.append_inst(entry, call_id);
        func.append_inst(entry, ret_id);

        let pipeline = Pipeline::new(PipelineConfig::default());
        let obj = pipeline
            .compile_module(&[func])
            .expect("external call should emit an undefined symbol");
        let parsed = crate::macho::linker::MachOParser::parse(&obj).expect("parse Mach-O object");

        let printf_idx = parsed
            .symbols
            .iter()
            .position(|sym| sym.name == "_printf")
            .expect("object should contain _printf");
        let printf = &parsed.symbols[printf_idx];
        assert!(printf.is_external());
        assert!(printf.is_undefined());

        let text = parsed
            .sections
            .iter()
            .find(|section| section.name == "__text")
            .expect("__text section");
        assert_eq!(text.relocations.len(), 1);
        assert!(text.relocations[0].is_extern);
        assert_eq!(text.relocations[0].symbol_index as usize, printf_idx);
    }

    #[test]
    fn implicit_preserve_skips_addr_of_fresh_scalar_temp_arg() {
        // Regression (AArch64 `&(fresh scalar temp)` call-argument clobber).
        //
        // The derived `Hash for Level` stores `sext(tag)` into a fresh stack slot
        // and calls `hash(&disc_temp, state)`. arg0 is the alloca address, which
        // the allocator materializes DIRECTLY into x0 (`sub x0, x29, #imm`) and
        // then reuses as the `str` store address. Before this fix the implicit-
        // preserve pass mistook the `sub` for a transient clobber (its result is
        // read by the `str`), saved x0's region-entry value (self) into a scratch
        // before the `sub`, and restored it before the call — overwriting the real
        // `&disc_temp` argument with `self`. The pass must be a no-op here: x0's
        // entry value (self) was already relocated to a callee-saved reg
        // (`Copy x19, x0`) before the clobber, so it is DEAD and there is nothing
        // to rescue.
        let sig = IrSignature::new(vec![Type::Ptr, Type::Ptr], vec![]);
        let mut func = IrMachFunction::new("level_hash".to_string(), sig);
        let entry = func.entry;

        // Copy x19, x0 : park `self` in a callee-saved reg (LAST use of x0's
        //                region-entry value, before the arg register is reused).
        let save_self = func.push_inst(make_inst(
            IrOpcode::Copy,
            vec![IrOperand::PReg(X19), IrOperand::PReg(X0)],
        ));
        // Copy x20, x1 : park `state`.
        let save_state = func.push_inst(make_inst(
            IrOpcode::Copy,
            vec![IrOperand::PReg(X20), IrOperand::PReg(X1)],
        ));
        // SubRI x0, x29, #48 : x0 = &disc_temp (alloca address). FIRST clobber of
        //                      x0; not a Copy/Uxtw so not a recognized setup.
        let addr = func.push_inst(make_inst(
            IrOpcode::SubRI,
            vec![
                IrOperand::PReg(X0),
                IrOperand::PReg(X29),
                IrOperand::Imm(48),
            ],
        ));
        // StrRI x2, [x0] : disc_temp = sext(tag). Consumes x0 as the address —
        //                  the read that fooled the "transient clobber" test.
        let store = func.push_inst(make_inst(
            IrOpcode::StrRI,
            vec![IrOperand::PReg(X2), IrOperand::PReg(X0), IrOperand::Imm(0)],
        ));
        // Copy x1, x20 : setup arg1 = state.
        let setup_arg1 = func.push_inst(make_inst(
            IrOpcode::Copy,
            vec![IrOperand::PReg(X1), IrOperand::PReg(X20)],
        ));
        // Bl leaf, implicit_uses = [x0, x1].
        let call = func.push_inst(
            IrMachInst::new(
                IrOpcode::Bl,
                vec![IrOperand::Symbol("hash_leaf".to_string())],
            )
            .with_implicit_uses(&[X0, X1]),
        );
        for id in [save_self, save_state, addr, store, setup_arg1, call] {
            func.append_inst(entry, id);
        }

        let before = func.block(entry).insts.clone();
        fixup_aarch64_call_arg_source_clobbers(&mut func).unwrap();
        let after = func.block(entry).insts.clone();

        // No spurious x0 preserve/restore: the pass is a no-op on this shape.
        assert_eq!(
            before, after,
            "must not insert a spurious x0 preserve/restore around &(fresh scalar temp) arg"
        );
        // The only definition of x0 reaching the call is the `sub` that computes
        // `&disc_temp`; no Copy re-defines x0 (a restore would).
        for &id in &after {
            let inst = func.inst(id);
            if inst.opcode == IrOpcode::Copy
                && aarch64_inst_def_pregs(inst)
                    .iter()
                    .any(|&d| regs_overlap(d, X0))
            {
                panic!("no Copy may redefine x0 before the call (would clobber &disc_temp)");
            }
        }
    }

    #[test]
    fn implicit_preserve_still_rescues_clobbered_live_arg() {
        // Guard against over-correction of the fix above: the true-positive the
        // implicit-preserve pass exists for must STILL be fixed. arg0 is a value
        // "already in place" in x0 whose only consumer is the call; the allocator
        // reuses x0 for another argument's constant (`mov x0,#imm; mov x2,x0`) and
        // never reloads arg0. x0's entry value is NOT read before the clobber, so
        // the new liveness gate does not fire and the preserve/restore still runs.
        let sig = IrSignature::new(vec![Type::Ptr, Type::Ptr], vec![]);
        let mut func = IrMachFunction::new("ctor_set".to_string(), sig);
        let entry = func.entry;

        // Copy x20, x1 : park `state` (does not touch x0; keeps the clobber off
        //                position 0 so the pass considers it).
        let save_state = func.push_inst(make_inst(
            IrOpcode::Copy,
            vec![IrOperand::PReg(X20), IrOperand::PReg(X1)],
        ));
        // MovI x0, #7 : clobber x0 with arg2's constant (not a setup).
        let clobber = func.push_inst(make_inst(
            IrOpcode::MovI,
            vec![IrOperand::PReg(X0), IrOperand::Imm(7)],
        ));
        // Copy x2, x0 : setup arg2 from the constant (consumes the clobber value).
        let setup_arg2 = func.push_inst(make_inst(
            IrOpcode::Copy,
            vec![IrOperand::PReg(X2), IrOperand::PReg(X0)],
        ));
        // Copy x1, x20 : setup arg1 = state.
        let setup_arg1 = func.push_inst(make_inst(
            IrOpcode::Copy,
            vec![IrOperand::PReg(X1), IrOperand::PReg(X20)],
        ));
        // Bl ctor, implicit_uses = [x0, x1, x2].
        let call = func.push_inst(
            IrMachInst::new(IrOpcode::Bl, vec![IrOperand::Symbol("ctor".to_string())])
                .with_implicit_uses(&[X0, X1, X2]),
        );
        for id in [save_state, clobber, setup_arg2, setup_arg1, call] {
            func.append_inst(entry, id);
        }

        let before_len = func.block(entry).insts.len();
        fixup_aarch64_call_arg_source_clobbers(&mut func).unwrap();
        let after = func.block(entry).insts.clone();

        // The clobbered live arg0 must still be rescued: one preserve (before the
        // clobber) plus one restore (before the call).
        assert_eq!(
            after.len(),
            before_len + 2,
            "must preserve+restore the clobbered live arg0"
        );
        let call_idx = after
            .iter()
            .position(|&id| func.inst(id).is_call())
            .expect("call present");
        let restore = func.inst(after[call_idx - 1]);
        assert_eq!(restore.opcode, IrOpcode::Copy);
        assert!(
            aarch64_inst_def_pregs(restore)
                .iter()
                .any(|&d| regs_overlap(d, X0)),
            "the instruction immediately before the call must restore x0"
        );
    }

