    #[test]
    fn aarch64_object_routes_reject_mislabeled_architectures_and_big_endian() {
        let sig = IrSignature::new(vec![], vec![]);
        let mut template = IrMachFunction::new("main".to_string(), sig);
        let ret_id = template.push_inst(IrMachInst::new(IrOpcode::Ret, vec![]));
        template.append_inst(template.entry, ret_id);

        for target in [
            "x86_64-apple-darwin",
            "x86_64-unknown-linux-gnu",
            "riscv64-apple-darwin",
            "riscv64-unknown-linux-gnu",
            "aarch64_be-unknown-linux-gnu",
        ] {
            let pipeline = Pipeline::new(PipelineConfig {
                target_triple: target.to_string(),
                ..Default::default()
            });

            let module_error = pipeline
                .compile_module(&[template.clone()])
                .expect_err("AArch64 module bytes must not be emitted under another ISA label");
            assert!(
                matches!(module_error, PipelineError::TargetObjectUnsupported { .. }),
                "{target}: {module_error}"
            );

            let mut single = template.clone();
            let single_error = pipeline
                .encode_and_emit(&mut single)
                .expect_err("AArch64 single-function bytes must not be mislabeled");
            assert!(
                matches!(single_error, PipelineError::TargetObjectUnsupported { .. }),
                "{target}: {single_error}"
            );
        }
    }

    // -----------------------------------------------------------------------
    // Whole-module unwind planning (EH A64 Lane 5): per-function compact
    // unwind encodings, DWARF FDE fallbacks under one shared CIE, and the
    // synthetic filler LSDA rule.
    // -----------------------------------------------------------------------

    fn test_frame_layout_fp_frame() -> crate::frame::FrameLayout {
        use trust_cg_ir::regs::{X29, X30};
        crate::frame::FrameLayout {
            callee_saved_pairs: vec![crate::frame::CalleeSavedPair {
                reg1: X29,
                reg2: X30,
                fp_offset: -16,
                is_fpr: false,
            }],
            callee_saved_area_size: 16,
            spill_area_size: 0,
            local_area_size: 0,
            outgoing_arg_area_size: 0,
            total_frame_size: 16,
            uses_frame_pointer: true,
            is_leaf: false,
            uses_red_zone: false,
            fp_to_spill_offset: 0,
            has_dynamic_alloc: false,
        }
    }

    fn test_frame_layout_dynamic() -> crate::frame::FrameLayout {
        crate::frame::FrameLayout {
            has_dynamic_alloc: true,
            ..test_frame_layout_fp_frame()
        }
    }

    fn test_frame_layout_frameless() -> crate::frame::FrameLayout {
        crate::frame::FrameLayout {
            callee_saved_pairs: vec![],
            callee_saved_area_size: 0,
            total_frame_size: 0,
            uses_frame_pointer: false,
            is_leaf: true,
            ..test_frame_layout_fp_frame()
        }
    }

    /// A fake (but structurally valid) LSDA payload for planning tests.
    fn test_lsda() -> Option<(Vec<u8>, String)> {
        Some((vec![0xFF, 0x01, 0x00], "rust_eh_personality".to_string()))
    }

    /// Compact-describable frames in an EH module: every function gets a
    /// compact encoding, only the EH function gets an LSDA symbol, and no
    /// `__eh_frame` is needed.
    #[test]
    fn module_unwind_plan_compact_frames_no_eh_frame() {
        let mut writer = crate::macho::MachOWriter::new();
        writer.add_text_section(&[0u8; 64]);
        let pipeline = Pipeline::new(PipelineConfig::default());
        let func_offsets = vec![("eh_fn".to_string(), 0u64), ("plain".to_string(), 32u64)];
        let func_eh = vec![
            ModuleFunctionEhData {
                code_len: 32,
                lsda: test_lsda(),
            },
            ModuleFunctionEhData {
                code_len: 32,
                lsda: None,
            },
        ];
        let layouts = vec![
            Some(test_frame_layout_fp_frame()),
            Some(test_frame_layout_frameless()),
        ];

        let plan = pipeline
            .plan_module_unwind_sections(&mut writer, &func_offsets, &func_eh, &layouts)
            .expect("plan");

        assert_eq!(
            plan.encodings[0].encoding & 0x0F00_0000,
            crate::frame::UNWIND_ARM64_MODE_FRAME,
            "EH function's FP frame is compact-describable"
        );
        assert_eq!(
            plan.encodings[1].encoding,
            crate::frame::UNWIND_ARM64_MODE_FRAMELESS,
            "plain trivial leaf is FRAMELESS"
        );
        assert!(plan.lsda_symbols[0].is_some(), "EH fn has its real LSDA");
        assert!(
            plan.lsda_symbols[1].is_none(),
            "compact plain frame needs no LSDA (no zPLR FDE constraint)"
        );
        assert!(
            plan.dwarf.is_none(),
            "no DWARF fallback frame -> no __eh_frame"
        );
    }

    /// An EH function that needs the DWARF fallback forces the zPLR CIE, so
    /// EVERY DWARF-fallback function's FDE must carry an LSDA — the non-EH one
    /// gets the synthetic ALL-FILLER LSDA ("continue unwinding").
    #[test]
    fn module_unwind_plan_dwarf_eh_gets_zplr_fde_and_filler_lsda() {
        let mut writer = crate::macho::MachOWriter::new();
        writer.add_text_section(&[0u8; 64]);
        let pipeline = Pipeline::new(PipelineConfig::default());
        let func_offsets = vec![
            ("eh_dyn".to_string(), 0u64),
            ("plain_dyn".to_string(), 32u64),
        ];
        let func_eh = vec![
            ModuleFunctionEhData {
                code_len: 32,
                lsda: test_lsda(),
            },
            ModuleFunctionEhData {
                code_len: 32,
                lsda: None,
            },
        ];
        let layouts = vec![
            Some(test_frame_layout_dynamic()),
            Some(test_frame_layout_dynamic()),
        ];

        let plan = pipeline
            .plan_module_unwind_sections(&mut writer, &func_offsets, &func_eh, &layouts)
            .expect("plan");

        assert!(plan.encodings.iter().all(|e| e.needs_dwarf_fallback()));
        let dwarf = plan.dwarf.as_ref().expect("DWARF frames need __eh_frame");
        assert_eq!(dwarf.fde_functions, vec![0, 1], "one FDE per DWARF frame");
        assert_eq!(
            dwarf.cfi.fde_lsda_relocation_offsets().len(),
            2,
            "zPLR CIE: every FDE carries an LSDA slot"
        );
        assert!(
            dwarf.cfi.cie_personality_relocation_offset().is_some(),
            "zPLR CIE carries the personality"
        );
        assert!(plan.lsda_symbols[0].is_some(), "EH fn has its real LSDA");
        assert!(
            plan.lsda_symbols[1].is_some(),
            "non-EH DWARF-fallback fn gets the synthetic filler LSDA"
        );
    }

    /// A plain function needing DWARF fallback in a module whose EH functions
    /// are all compact-describable: zR CIE (no personality/LSDA slots), the
    /// EH function's LSDA rides on its compact entry.
    #[test]
    fn module_unwind_plan_plain_dwarf_under_compact_eh_uses_zr_cie() {
        let mut writer = crate::macho::MachOWriter::new();
        writer.add_text_section(&[0u8; 64]);
        let pipeline = Pipeline::new(PipelineConfig::default());
        let func_offsets = vec![
            ("eh_fn".to_string(), 0u64),
            ("plain_dyn".to_string(), 32u64),
        ];
        let func_eh = vec![
            ModuleFunctionEhData {
                code_len: 32,
                lsda: test_lsda(),
            },
            ModuleFunctionEhData {
                code_len: 32,
                lsda: None,
            },
        ];
        let layouts = vec![
            Some(test_frame_layout_fp_frame()),
            Some(test_frame_layout_dynamic()),
        ];

        let plan = pipeline
            .plan_module_unwind_sections(&mut writer, &func_offsets, &func_eh, &layouts)
            .expect("plan");

        let dwarf = plan.dwarf.as_ref().expect("the dynamic frame needs an FDE");
        assert_eq!(dwarf.fde_functions, vec![1]);
        assert!(
            dwarf.cfi.fde_lsda_relocation_offsets().is_empty(),
            "zR CIE: no LSDA slots"
        );
        assert!(
            dwarf.cfi.cie_personality_relocation_offset().is_none(),
            "zR CIE: no personality"
        );
        assert!(plan.lsda_symbols[0].is_some(), "EH fn keeps its real LSDA");
        assert!(
            plan.lsda_symbols[1].is_none(),
            "no zPLR constraint -> no filler LSDA"
        );
    }

    /// Missing frame layouts for ANY function in an EH module fail closed —
    /// an unwind-table-less frame would be unwalkable (FUZZ-7 [TCG-EH-WALK]).
    #[test]
    fn module_unwind_plan_missing_layout_fails_closed() {
        let mut writer = crate::macho::MachOWriter::new();
        writer.add_text_section(&[0u8; 64]);
        let pipeline = Pipeline::new(PipelineConfig::default());
        let func_offsets = vec![("eh_fn".to_string(), 0u64), ("plain".to_string(), 32u64)];
        let func_eh = vec![
            ModuleFunctionEhData {
                code_len: 32,
                lsda: test_lsda(),
            },
            ModuleFunctionEhData {
                code_len: 32,
                lsda: None,
            },
        ];
        let layouts = vec![Some(test_frame_layout_fp_frame()), None];

        let err = pipeline
            .plan_module_unwind_sections(&mut writer, &func_offsets, &func_eh, &layouts)
            .err()
            .expect("missing layout must fail closed");
        assert!(format!("{err}").contains("no frame layout"));
    }

