    #[cfg(feature = "verify")]
    #[test]
    fn aarch64_macho_branch26_and_unsigned_relocation_inventory_promotes() {
        use trust_cg_verify::{
            ObjectProofBinding, ObjectRelocationInventoryReport, ObjectRelocationKind,
            ObjectRelocationProofRegistry, RelocationInventoryStatus,
        };

        // (A) A direct call (`Bl symbol`) emits an `ARM64_RELOC_BRANCH26` row.
        // The row cites the aarch64_macho_call_reloc_proofs lane and the
        // report is built under the default-Enforce ENC-9 reparse binding —
        // the Certified composition (lane + container-bound reparse) —
        // so the inventory PROMOTES.
        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("main".to_string(), sig);
        let call = IrMachInst::new(IrOpcode::Bl, vec![IrOperand::Symbol("printf".to_string())]);
        let ret = IrMachInst::new(IrOpcode::Ret, vec![]);
        let call_id = func.push_inst(call);
        let ret_id = func.push_inst(ret);
        func.append_inst(func.entry, call_id);
        func.append_inst(func.entry, ret_id);

        let pipeline = Pipeline::new(PipelineConfig {
            target_triple: "aarch64-apple-darwin".to_string(),
            ..Default::default()
        });
        let report = pipeline
            .module_relocation_inventory_report(&[func], "macho.o")
            .expect("inventory report is produced for Mach-O symbolic fixups")
            .expect("AArch64 Mach-O target yields a report");

        assert!(
            report.is_promotable(),
            "BRANCH26 is lane-covered and ENC-9 bound; it must promote: {report:?}"
        );
        assert!(
            report
                .entries
                .iter()
                .any(|e| e.kind == ObjectRelocationKind::AArch64MachOBranch26),
            "BRANCH26 row must be present: {report:?}"
        );
        assert!(
            report
                .entries
                .iter()
                .all(|entry| { entry.status == RelocationInventoryStatus::Verified })
        );
        assert!(report.promotion_rejection_reason().is_none());

        // (B) An `ARM64_RELOC_UNSIGNED` row (absolute pointer slot) is now in
        // the production registry (aarch64_macho_data_reloc_proofs lane), but
        // a registry row alone is Trusted, not Certified: UNBOUND it stays
        // fail-closed (the 54762bc4 doctrine), and it promotes only under the
        // ENC-9 reparse-enforced binding.
        let registry = ObjectRelocationProofRegistry::aarch64_macho_production();
        let unbound = ObjectRelocationInventoryReport::from_emitted_kinds_with_registry(
            "macho.o",
            [ObjectRelocationKind::AArch64MachOUnsigned],
            &registry,
        );
        assert!(
            !unbound.is_promotable(),
            "a lane-covered but UNBOUND UNSIGNED row must stay fail-closed: {unbound:?}"
        );
        assert!(
            unbound
                .promotion_rejection_reason()
                .is_some_and(|r| r.contains("lacks an independent reparse binding"))
        );
        let bound = ObjectRelocationInventoryReport::from_emitted_kinds_with_registry_and_binding(
            "macho.o",
            [ObjectRelocationKind::AArch64MachOUnsigned],
            &registry,
            ObjectProofBinding::MachOReparseEnforced,
        );
        assert!(
            bound.is_promotable(),
            "a lane-covered, ENC-9-bound UNSIGNED row must promote: {bound:?}"
        );
        assert!(bound.entries.iter().all(|e| {
            e.kind == ObjectRelocationKind::AArch64MachOUnsigned
                && e.status == RelocationInventoryStatus::Verified
        }));
    }

    #[cfg(feature = "verify")]
    #[test]
    fn aarch64_macho_adrp_add_global_inventory_promotes() {
        // An ADRP + ADD pair addressing a local global emits the PAGE21 +
        // PAGEOFF12 rows. Both cite the aarch64_macho_data_reloc_proofs lane
        // and the report is built under the default-Enforce ENC-9 reparse
        // binding, so the inventory PROMOTES (the Certified composition).
        use trust_cg_ir::regs::X0;

        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("read_global".to_string(), sig);

        // ADRP x0, _G@PAGE
        let adrp = IrMachInst::new(
            IrOpcode::Adrp,
            vec![IrOperand::PReg(X0), IrOperand::Symbol("_G".to_string())],
        );
        // ADD x0, x0, _G@PAGEOFF
        let add = IrMachInst::new(
            IrOpcode::AddPCRel,
            vec![
                IrOperand::PReg(X0),
                IrOperand::PReg(X0),
                IrOperand::Symbol("_G".to_string()),
            ],
        );
        let ret = IrMachInst::new(IrOpcode::Ret, vec![]);
        let adrp_id = func.push_inst(adrp);
        let add_id = func.push_inst(add);
        let ret_id = func.push_inst(ret);
        func.append_inst(func.entry, adrp_id);
        func.append_inst(func.entry, add_id);
        func.append_inst(func.entry, ret_id);

        let pipeline = Pipeline::new(PipelineConfig {
            target_triple: "aarch64-apple-darwin".to_string(),
            ..Default::default()
        });
        let report = pipeline
            .module_relocation_inventory_report(&[func], "macho.o")
            .expect("inventory report is produced")
            .expect("AArch64 Mach-O target yields a report");

        assert!(
            report.is_promotable(),
            "the lane-covered, ENC-9-bound PAGE21/PAGEOFF12 pair must promote: {report:?}"
        );
        assert!(report.promotion_rejection_reason().is_none());
        let kinds: Vec<_> = report.entries.iter().map(|e| e.kind).collect();
        assert!(
            kinds.contains(&trust_cg_verify::ObjectRelocationKind::AArch64MachOPage21),
            "expected a PAGE21 row: {report:?}"
        );
        assert!(
            kinds.contains(&trust_cg_verify::ObjectRelocationKind::AArch64MachOPageoff12),
            "expected a PAGEOFF12 row: {report:?}"
        );
        for entry in &report.entries {
            assert_eq!(
                entry.status,
                trust_cg_verify::RelocationInventoryStatus::Verified,
                "every emitted page-pair row must be Verified under the composition: {entry:?}"
            );
        }
    }

    #[cfg(feature = "verify")]
    #[test]
    fn aarch64_macho_production_inventory_matches_all_serialized_relocation_rows() {
        use trust_cg_verify::ObjectRelocationKind;

        let make_ret = |name: &str| {
            let mut func = IrMachFunction::new(name.to_string(), IrSignature::new(vec![], vec![]));
            let ret = func.push_inst(IrMachInst::new(IrOpcode::Ret, vec![]));
            func.append_inst(func.entry, ret);
            func
        };
        let functions = vec![make_ret("main"), make_ret("dynamic_frame")];
        let globals = vec![
            ObjectGlobal {
                name: "FN_SLOT".to_string(),
                data: vec![0; 8],
                mutable: true,
                is_external: true,
                symbol_refs: vec![GlobalSymbolRef {
                    offset: 0,
                    symbol: "main".to_string(),
                    addend: 0,
                }],
                is_thread_local: false,
                is_import: false,
                is_weak: false,
                align: 8,
            },
            ObjectGlobal {
                name: "TLS_BYTES".to_string(),
                data: vec![1, 2, 3, 4],
                mutable: true,
                is_external: true,
                symbol_refs: vec![],
                is_thread_local: true,
                is_import: false,
                is_weak: false,
                align: 4,
            },
        ];
        let layouts = vec![
            Some(test_frame_layout_fp_frame()),
            Some(test_frame_layout_dynamic()),
        ];
        let pipeline = Pipeline::new(PipelineConfig {
            target_triple: "aarch64-apple-darwin".to_string(),
            ..Default::default()
        });

        let object = pipeline
            .compile_module_with_globals_and_layouts(&functions, &globals, &layouts)
            .expect("production Mach-O object should emit");
        let parsed = crate::macho::linker::MachOParser::parse(&object)
            .expect("production Mach-O object should parse");
        let mut actual: Vec<ObjectRelocationKind> = parsed
            .sections
            .iter()
            .flat_map(|section| section.relocations.iter())
            .map(|relocation| aarch64_macho_object_relocation_kind(relocation.kind))
            .collect();

        let report = pipeline
            .module_relocation_inventory_report_with_object_state(
                &functions,
                &globals,
                &layouts,
                "production.o",
            )
            .expect("production inventory should be generated")
            .expect("AArch64 Mach-O has a relocation inventory");
        let mut inventoried: Vec<ObjectRelocationKind> =
            report.entries.iter().map(|entry| entry.kind).collect();

        actual.sort_unstable();
        inventoried.sort_unstable();
        assert_eq!(
            inventoried, actual,
            "the production object report must inventory every serialized relocation row exactly"
        );
        assert_eq!(
            actual
                .iter()
                .filter(|kind| **kind == ObjectRelocationKind::AArch64MachOUnsigned)
                .count(),
            6,
            "data + TLS descriptors + compact unwind + fallback FDE unsigned rows"
        );
        assert_eq!(
            actual
                .iter()
                .filter(|kind| **kind == ObjectRelocationKind::AArch64MachOSubtractor)
                .count(),
            1,
            "the dynamic frame's fallback FDE emits one subtractor row"
        );
        // Every serialized kind (UNSIGNED, SUBTRACTOR) is lane-covered and
        // the report is built under the default-Enforce ENC-9 reparse
        // binding, so the production inventory now PROMOTES with every row
        // Verified. (The inventory==serialized sensor above remains the
        // unsound-under-report guard.)
        assert!(
            report.is_promotable(),
            "lane-covered, ENC-9-bound production inventory must promote: {report:?}"
        );
        assert!(
            report
                .entries
                .iter()
                .all(|entry| entry.status == trust_cg_verify::RelocationInventoryStatus::Verified)
        );
    }

