    #[test]
    fn compile_module_aarch64_linux_thread_local_global_emits_tdata_definition() {
        // A thread-local DEFINITION on the ELF path lands in `.tdata`
        // (SHF_TLS) with an STT_TLS symbol carrying the template offset —
        // NEVER a plain `.data` symbol (one shared copy would be a silent
        // miscompile). Structural check on the emitted bytes.
        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("main".to_string(), sig);
        let ret = IrMachInst::new(IrOpcode::Ret, vec![]);
        let ret_id = func.push_inst(ret);
        func.append_inst(func.entry, ret_id);

        let globals = vec![ObjectGlobal {
            name: "TLS_BYTES".to_string(),
            data: vec![1, 2, 3, 4],
            mutable: true,
            is_external: true,
            symbol_refs: vec![],
            is_thread_local: true,
            is_import: false,
            is_weak: false,
            align: 1,
        }];
        let pipeline = Pipeline::new(PipelineConfig {
            target_triple: "aarch64-unknown-linux-gnu".to_string(),
            ..Default::default()
        });
        let obj = pipeline
            .compile_module_with_globals(&[func], &globals)
            .expect("ELF thread-local definition must compile to a .tdata template");
        assert_eq!(&obj[0..4], b"\x7fELF");
        let tdata = find_elf_section_view(&obj, ".tdata")
            .expect("thread-local definition must produce a .tdata section");
        // SHF_ALLOC|SHF_WRITE|SHF_TLS and the exact template bytes.
        assert_eq!(
            tdata.sh_flags & crate::elf::constants::SHF_TLS,
            crate::elf::constants::SHF_TLS,
            ".tdata must carry SHF_TLS"
        );
        let template = &obj[tdata.offset as usize..(tdata.offset + tdata.size) as usize];
        assert_eq!(&template[..4], &[1, 2, 3, 4]);
        assert!(
            elf_symbol_names(&obj).iter().any(|n| n == "TLS_BYTES"),
            "the TLS template symbol must be emitted"
        );
        assert!(
            find_elf_section_view(&obj, ".data").is_none(),
            "a thread-local must NOT be emitted as a plain .data definition"
        );
    }

    #[test]
    fn compile_module_aarch64_darwin_emits_thread_local_tlv_sections_and_symbols() {
        // A thread-local object global on the Darwin Mach-O path must materialize
        // the TLV sections (`__thread_data` initial-value template +
        // `__thread_vars` `tlv_descriptor`) and the descriptor / init / bootstrap
        // symbols. Structural check on the emitted bytes (no host needed).
        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("main".to_string(), sig);
        let ret = IrMachInst::new(IrOpcode::Ret, vec![]);
        let ret_id = func.push_inst(ret);
        func.append_inst(func.entry, ret_id);

        let globals = vec![ObjectGlobal {
            name: "X".to_string(),
            data: vec![0xCD, 0xAB, 0x00, 0x00],
            mutable: true,
            is_external: true,
            symbol_refs: vec![],
            is_thread_local: true,
            is_import: false,
            is_weak: false,
            align: 1,
        }];
        let pipeline = Pipeline::new(PipelineConfig {
            target_triple: "aarch64-apple-darwin".to_string(),
            ..Default::default()
        });
        let obj = pipeline
            .compile_module_with_globals(&[func], &globals)
            .expect("thread-local global should emit Darwin TLV sections");

        // Valid Mach-O.
        assert_eq!(&obj[0..4], &0xFEED_FACFu32.to_le_bytes());
        // The TLV section names and the descriptor/init/bootstrap symbol names
        // are present (as raw section-name / string-table bytes).
        let contains = |needle: &[u8]| obj.windows(needle.len()).any(|w| w == needle);
        assert!(contains(b"__thread_data"), "missing __thread_data section");
        assert!(contains(b"__thread_vars"), "missing __thread_vars section");
        assert!(contains(b"_X\0"), "missing descriptor symbol _X");
        assert!(
            contains(b"_X$tlv$init\0"),
            "missing init symbol _X$tlv$init"
        );
        assert!(
            contains(b"__tlv_bootstrap\0"),
            "missing dyld thunk import __tlv_bootstrap"
        );
        // The 4-byte initial-value template `CD AB 00 00` is in the object.
        assert!(
            contains(&[0xCD, 0xAB, 0x00, 0x00]),
            "missing thread-local initial value template"
        );
    }

    #[test]
    fn compile_module_aarch64_linux_emits_byte_globals_as_object_symbols() {
        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("main".to_string(), sig);
        let ret = IrMachInst::new(IrOpcode::Ret, vec![]);
        let ret_id = func.push_inst(ret);
        func.append_inst(func.entry, ret_id);

        let globals = vec![
            ObjectGlobal {
                name: "MUT_BYTES".to_string(),
                data: vec![1, 2, 3],
                mutable: true,
                is_external: true,
                symbol_refs: vec![],
                is_thread_local: false,
                is_import: false,
                is_weak: false,
                align: 1,
            },
            ObjectGlobal {
                name: "IMM_BYTES".to_string(),
                data: vec![4, 5],
                mutable: false,
                is_external: true,
                symbol_refs: vec![],
                is_thread_local: false,
                is_import: false,
                is_weak: false,
                align: 8,
            },
        ];
        let pipeline = Pipeline::new(PipelineConfig {
            target_triple: "aarch64-unknown-linux-gnu".to_string(),
            ..Default::default()
        });
        let obj = pipeline
            .compile_module_with_globals(&[func], &globals)
            .expect("Linux AArch64 byte globals should be emitted into ELF");

        assert_eq!(&obj[0..4], b"\x7fELF");
        assert_eq!(elf_section_data(&obj, ".data"), &[1, 2, 3]);
        assert_eq!(elf_section_data(&obj, ".rodata"), &[4, 5]);

        let symbols = elf_symbols(&obj);
        for (name, size) in [("MUT_BYTES", 3), ("IMM_BYTES", 2)] {
            let symbol = symbols
                .iter()
                .find(|symbol| symbol.name == name)
                .expect("global object symbol should be present");
            assert_ne!(symbol.section, 0, "global object must be defined");
            assert_eq!(symbol.size, size);
            assert_eq!(
                symbol.info & 0x0f,
                crate::elf::constants::STT_OBJECT,
                "global object must use STT_OBJECT"
            );
        }
    }

