    #[test]
    fn compile_module_aarch64_linux_tls_fixup_still_fails_closed() {
        assert_aarch64_linux_unsupported_symbol_fixup_fails_closed(
            [
                IrMachInst::new(
                    IrOpcode::Adrp,
                    vec![
                        IrOperand::PReg(X17),
                        IrOperand::Symbol("tls_global".to_string()),
                    ],
                ),
                IrMachInst::new(
                    IrOpcode::LdrTlvp,
                    vec![
                        IrOperand::PReg(X16),
                        IrOperand::PReg(X17),
                        IrOperand::Symbol("tls_global".to_string()),
                    ],
                ),
            ],
            "TLS/TLVP fixup TlvpLoadPage21 with model Some(Tlv)",
        );
        // A LONE `LdrTlvp` (no pairing ADRP at all) is now refused even
        // earlier, by the encode-time page-pairing backstop: emitting its
        // page-offset fixup without a same-block page half would be a mixed
        // relocation pair regardless of target. Still fail-closed, different
        // (stronger) boundary.
        {
            let sig = IrSignature::new(vec![], vec![]);
            let mut func = IrMachFunction::new("main".to_string(), sig);
            let lone = func.push_inst(IrMachInst::new(
                IrOpcode::LdrTlvp,
                vec![
                    IrOperand::PReg(X16),
                    IrOperand::PReg(X17),
                    IrOperand::Symbol("tls_global".to_string()),
                ],
            ));
            let ret = func.push_inst(IrMachInst::new(IrOpcode::Ret, vec![]));
            func.append_inst(func.entry, lone);
            func.append_inst(func.entry, ret);
            let pipeline = Pipeline::new(PipelineConfig {
                target_triple: "aarch64-unknown-linux-gnu".to_string(),
                ..Default::default()
            });
            let err = pipeline
                .compile_module(&[func])
                .expect_err("unpaired TLVP page-offset load must fail closed");
            let msg = err.to_string();
            // Two fail-closed gates can legitimately catch this shape: the
            // GOT/TLVP page-pairing backstop, or (since the reaching-def
            // checker landed) the earlier read-without-reaching-def gate on
            // the unpaired load's register. Either way the compile FAILS
            // CLOSED — pin that, not which gate fires first.
            assert!(
                msg.contains("without a pairing `ADRP") || msg.contains("REACHING-DEF"),
                "expected a fail-closed rejection (page-pairing backstop or \
                 reaching-def gate), got: {msg}"
            );
        }
    }

