    #[test]
    fn run_isel_aarch64_linux_dynamic_tls_models_fail_before_elf_mapping() {
        use trust_cg_ir::TlsModel;
        use trust_cg_lower::function::{BasicBlock, Function as LowerFunction, Signature};
        use trust_cg_lower::instructions::{Block, Instruction, Opcode, Value};
        use trust_cg_lower::types::Type as LowerType;

        // InitialExec now lowers (GOT-indirect TPREL, `select_tls_ref`); only
        // the dlopen-era GD/LD models remain fail-closed (unreachable-by-lane
        // VERDICT: trust-cg emits main-executable objects only).
        for model in [TlsModel::GeneralDynamic, TlsModel::LocalDynamic] {
            let mut func = LowerFunction::new(
                format!("tls_{model:?}"),
                Signature {
                    params: vec![],
                    returns: vec![LowerType::I64],
                },
            );
            func.entry_block = Block(0);
            func.block_order = vec![Block(0)];
            func.blocks.insert(
                Block(0),
                BasicBlock {
                    params: vec![],
                    instructions: vec![
                        Instruction {
                            opcode: Opcode::TlsRef {
                                name: "tls_global".to_string(),
                                model,
                                local_exec_offset: None,
                            },
                            args: vec![],
                            results: vec![Value(0)],
                        },
                        Instruction {
                            opcode: Opcode::Return,
                            args: vec![Value(0)],
                            results: vec![],
                        },
                    ],
                    source_locs: vec![],
                },
            );

            let pipeline = Pipeline::new(PipelineConfig {
                target_triple: "aarch64-unknown-linux-gnu".to_string(),
                opt_level: OptLevel::O0,
                ..PipelineConfig::default()
            });
            let err = pipeline
                .run_isel(&func, None)
                .expect_err("Linux dynamic TLS models must fail before ELF emission");

            let PipelineError::ISel(message) = err else {
                panic!("expected ISel fail-closed dynamic TLS error, got {err:?}");
            };
            assert!(
                message.contains(&format!("unsupported AArch64 TlsRef model {model:?}")),
                "diagnostic must name rejected TLS model {model:?}, got {message:?}"
            );
            assert!(
                message.contains("unreachable-by-lane"),
                "diagnostic must state the GD/LD unreachable-by-lane verdict, got {message:?}"
            );
            assert!(
                message.contains("main-executable objects only"),
                "diagnostic must name the main-executable-only link model, got {message:?}"
            );
        }
    }

    /// InitialExec is no longer in the fail-closed set: through the real
    /// `run_isel` pipeline entry it selects the GOT-indirect TPREL sequence
    /// (ADRP + LdrGottprel + MRS + ADD), whose fixups the ELF emitter maps to
    /// the TLSIE relocation pair.
    #[test]
    fn run_isel_aarch64_linux_initial_exec_tls_selects_got_indirect_sequence() {
        use trust_cg_ir::TlsModel;
        use trust_cg_ir::inst::AArch64Opcode;
        use trust_cg_lower::function::{BasicBlock, Function as LowerFunction, Signature};
        use trust_cg_lower::instructions::{Block, Instruction, Opcode, Value};
        use trust_cg_lower::types::Type as LowerType;

        let mut func = LowerFunction::new(
            "tls_initial_exec".to_string(),
            Signature {
                params: vec![],
                returns: vec![LowerType::I64],
            },
        );
        func.entry_block = Block(0);
        func.block_order = vec![Block(0)];
        func.blocks.insert(
            Block(0),
            BasicBlock {
                params: vec![],
                instructions: vec![
                    Instruction {
                        opcode: Opcode::TlsRef {
                            name: "tls_global".to_string(),
                            model: TlsModel::InitialExec,
                            local_exec_offset: None,
                        },
                        args: vec![],
                        results: vec![Value(0)],
                    },
                    Instruction {
                        opcode: Opcode::Return,
                        args: vec![Value(0)],
                        results: vec![],
                    },
                ],
                source_locs: vec![],
            },
        );

        let pipeline = Pipeline::new(PipelineConfig {
            target_triple: "aarch64-unknown-linux-gnu".to_string(),
            opt_level: OptLevel::O0,
            ..PipelineConfig::default()
        });
        let (isel_func, _) = pipeline
            .run_isel(&func, None)
            .expect("InitialExec TlsRef must select the GOT-indirect TPREL sequence");

        let block = &isel_func.blocks[&trust_cg_lower::instructions::Block(0)];
        let opcodes: Vec<_> = block.insts.iter().map(|i| i.opcode).collect();
        assert_eq!(
            &opcodes[..4],
            &[
                AArch64Opcode::Adrp,
                AArch64Opcode::LdrGottprel,
                AArch64Opcode::Mrs,
                AArch64Opcode::AddRR,
            ],
            "InitialExec must lower to ADRP;LDR(gottprel);MRS;ADD, got {opcodes:?}"
        );
        // Same-register, same-symbol ADRP/LDR pairing (the encode-time TLSIE
        // page-kind reconstruction depends on it).
        assert_eq!(block.insts[1].operands[1], block.insts[0].operands[0]);
        assert_eq!(
            block.insts[0].operands[1],
            trust_cg_lower::isel::ISelOperand::Symbol("tls_global".to_string())
        );
        assert_eq!(
            block.insts[1].operands[2],
            trust_cg_lower::isel::ISelOperand::Symbol("tls_global".to_string())
        );
    }

