    #[test]
    fn classify_def_use_post_index_writeback_roles_are_not_flattened() {
        let vec = VReg::new(0, RegClass::Fpr128);
        let base = VReg::new(1, RegClass::Gpr64);
        let st1 = make_inst(
            IrOpcode::NeonSt1Post,
            vec![
                IrOperand::VReg(vec),
                IrOperand::VReg(base),
                IrOperand::Imm(5),
            ],
        );
        let (defs, uses, _) = classify_def_use(&st1).unwrap();
        assert_eq!(
            defs.iter()
                .filter_map(|op| op.as_vreg())
                .collect::<Vec<_>>(),
            vec![base]
        );
        assert_eq!(
            uses.iter()
                .filter_map(|op| op.as_vreg())
                .collect::<Vec<_>>(),
            vec![vec, base]
        );

        let loaded = VReg::new(2, RegClass::Fpr128);
        let ld1 = make_inst(
            IrOpcode::NeonLd1Post,
            vec![
                IrOperand::VReg(loaded),
                IrOperand::VReg(base),
                IrOperand::Imm(5),
            ],
        );
        let (defs, uses, _) = classify_def_use(&ld1).unwrap();
        assert_eq!(
            defs.iter()
                .filter_map(|op| op.as_vreg())
                .collect::<Vec<_>>(),
            vec![loaded, base]
        );
        assert_eq!(
            uses.iter()
                .filter_map(|op| op.as_vreg())
                .collect::<Vec<_>>(),
            vec![base]
        );

        let x0 = VReg::new(3, RegClass::Gpr64);
        let x1 = VReg::new(4, RegClass::Gpr64);
        let ldp_post = make_inst(
            IrOpcode::LdpPostIndex,
            vec![
                IrOperand::VReg(x0),
                IrOperand::VReg(x1),
                IrOperand::VReg(base),
                IrOperand::Imm(16),
            ],
        );
        let (defs, uses, _) = classify_def_use(&ldp_post).unwrap();
        assert_eq!(
            defs.iter()
                .filter_map(|op| op.as_vreg())
                .collect::<Vec<_>>(),
            vec![x0, x1, base]
        );
        assert_eq!(
            uses.iter()
                .filter_map(|op| op.as_vreg())
                .collect::<Vec<_>>(),
            vec![base]
        );

        // LDP Q-pair post-index mirrors LdpPostIndex: BOTH Q registers are
        // defs and the base is a def-use — flattening operand 1 to a use
        // would hide the second loaded register from regalloc.
        let q0 = VReg::new(10, RegClass::Fpr128);
        let q1 = VReg::new(11, RegClass::Fpr128);
        let neon_ldp = make_inst(
            IrOpcode::NeonLdpQPost,
            vec![
                IrOperand::VReg(q0),
                IrOperand::VReg(q1),
                IrOperand::VReg(base),
                IrOperand::Imm(32),
            ],
        );
        let (defs, uses, _) = classify_def_use(&neon_ldp).unwrap();
        assert_eq!(
            defs.iter()
                .filter_map(|op| op.as_vreg())
                .collect::<Vec<_>>(),
            vec![q0, q1, base]
        );
        assert_eq!(
            uses.iter()
                .filter_map(|op| op.as_vreg())
                .collect::<Vec<_>>(),
            vec![base]
        );

        // STP Q-pair post-index is the STORE mirror: BOTH Q registers are USES
        // (stored), only the base is a def (writeback). Flattening operand 1 to
        // a def would fabricate a phantom write of the second stored register.
        let neon_stp = make_inst(
            IrOpcode::NeonStpQPost,
            vec![
                IrOperand::VReg(q0),
                IrOperand::VReg(q1),
                IrOperand::VReg(base),
                IrOperand::Imm(32),
            ],
        );
        let (defs, uses, _) = classify_def_use(&neon_stp).unwrap();
        assert_eq!(
            defs.iter()
                .filter_map(|op| op.as_vreg())
                .collect::<Vec<_>>(),
            vec![base]
        );
        assert_eq!(
            uses.iter()
                .filter_map(|op| op.as_vreg())
                .collect::<Vec<_>>(),
            vec![q0, q1, base]
        );

        let stp_pre = make_inst(
            IrOpcode::StpPreIndex,
            vec![
                IrOperand::VReg(x0),
                IrOperand::VReg(x1),
                IrOperand::VReg(base),
                IrOperand::Imm(-16),
            ],
        );
        let (defs, uses, _) = classify_def_use(&stp_pre).unwrap();
        assert_eq!(
            defs.iter()
                .filter_map(|op| op.as_vreg())
                .collect::<Vec<_>>(),
            vec![base]
        );
        assert_eq!(
            uses.iter()
                .filter_map(|op| op.as_vreg())
                .collect::<Vec<_>>(),
            vec![x0, x1, base]
        );

        let ldr_pre = make_inst(
            IrOpcode::LdrPreIndex,
            vec![
                IrOperand::VReg(x0),
                IrOperand::VReg(base),
                IrOperand::Imm(8),
            ],
        );
        let (defs, uses, _) = classify_def_use(&ldr_pre).unwrap();
        assert_eq!(
            defs.iter()
                .filter_map(|op| op.as_vreg())
                .collect::<Vec<_>>(),
            vec![x0, base]
        );
        assert_eq!(
            uses.iter()
                .filter_map(|op| op.as_vreg())
                .collect::<Vec<_>>(),
            vec![base]
        );

        let str_post = make_inst(
            IrOpcode::StrPostIndex,
            vec![
                IrOperand::VReg(x0),
                IrOperand::VReg(base),
                IrOperand::Imm(-8),
            ],
        );
        let (defs, uses, _) = classify_def_use(&str_post).unwrap();
        assert_eq!(
            defs.iter()
                .filter_map(|op| op.as_vreg())
                .collect::<Vec<_>>(),
            vec![base]
        );
        assert_eq!(
            uses.iter()
                .filter_map(|op| op.as_vreg())
                .collect::<Vec<_>>(),
            vec![x0, base]
        );
    }

    #[test]
    fn rebuild_post_index_writeback_operands_from_regalloc_roles() {
        use trust_cg_regalloc::machine_types::RegAllocOperand as RaOp;

        let vec = VReg::new(0, RegClass::Fpr128);
        let base = VReg::new(1, RegClass::Gpr64);

        assert_eq!(
            regalloc_explicit_operand_count(IrOpcode::NeonSt1Post, 1, 3).unwrap(),
            3
        );
        assert_eq!(
            rebuild_operands_from_regalloc(
                IrOpcode::NeonSt1Post,
                &[RaOp::VReg(base)],
                &[RaOp::VReg(vec), RaOp::VReg(base), RaOp::Imm(5)],
            )
            .unwrap(),
            vec![
                IrOperand::VReg(vec),
                IrOperand::VReg(base),
                IrOperand::Imm(5),
            ]
        );

        let loaded = VReg::new(2, RegClass::Fpr128);
        assert_eq!(
            regalloc_explicit_operand_count(IrOpcode::NeonLd1Post, 2, 2).unwrap(),
            3
        );
        assert_eq!(
            rebuild_operands_from_regalloc(
                IrOpcode::NeonLd1Post,
                &[RaOp::VReg(loaded), RaOp::VReg(base)],
                &[RaOp::VReg(base), RaOp::Imm(5)],
            )
            .unwrap(),
            vec![
                IrOperand::VReg(loaded),
                IrOperand::VReg(base),
                IrOperand::Imm(5),
            ]
        );

        let x0 = VReg::new(3, RegClass::Gpr64);
        let x1 = VReg::new(4, RegClass::Gpr64);
        assert_eq!(
            regalloc_explicit_operand_count(IrOpcode::LdpPostIndex, 3, 2).unwrap(),
            4
        );
        assert_eq!(
            regalloc_explicit_operand_count(IrOpcode::NeonLdpQPost, 3, 2).unwrap(),
            4
        );
        let q0 = VReg::new(10, RegClass::Fpr128);
        let q1 = VReg::new(11, RegClass::Fpr128);
        assert_eq!(
            rebuild_operands_from_regalloc(
                IrOpcode::NeonLdpQPost,
                &[RaOp::VReg(q0), RaOp::VReg(q1), RaOp::VReg(base)],
                &[RaOp::VReg(base), RaOp::Imm(32)],
            )
            .unwrap(),
            vec![
                IrOperand::VReg(q0),
                IrOperand::VReg(q1),
                IrOperand::VReg(base),
                IrOperand::Imm(32),
            ]
        );
        assert_eq!(
            regalloc_explicit_operand_count(IrOpcode::StpPreIndex, 1, 4).unwrap(),
            4
        );
        // STP Q-pair post-index: 1 def (base writeback) + 4 uses (both Q data
        // regs, old base, immediate) — the STORE mirror of NeonLdpQPost.
        assert_eq!(
            regalloc_explicit_operand_count(IrOpcode::NeonStpQPost, 1, 4).unwrap(),
            4
        );
        assert_eq!(
            rebuild_operands_from_regalloc(
                IrOpcode::NeonStpQPost,
                &[RaOp::VReg(base)],
                &[
                    RaOp::VReg(q0),
                    RaOp::VReg(q1),
                    RaOp::VReg(base),
                    RaOp::Imm(32)
                ],
            )
            .unwrap(),
            vec![
                IrOperand::VReg(q0),
                IrOperand::VReg(q1),
                IrOperand::VReg(base),
                IrOperand::Imm(32),
            ]
        );
        assert_eq!(
            regalloc_explicit_operand_count(IrOpcode::LdrPreIndex, 2, 2).unwrap(),
            3
        );
        assert_eq!(
            regalloc_explicit_operand_count(IrOpcode::LdrPostIndex, 2, 2).unwrap(),
            3
        );
        assert_eq!(
            regalloc_explicit_operand_count(IrOpcode::StrPreIndex, 1, 3).unwrap(),
            3
        );
        assert_eq!(
            regalloc_explicit_operand_count(IrOpcode::StrPostIndex, 1, 3).unwrap(),
            3
        );
        assert_eq!(
            rebuild_operands_from_regalloc(
                IrOpcode::LdrPostIndex,
                &[RaOp::VReg(x0), RaOp::VReg(base)],
                &[RaOp::VReg(base), RaOp::Imm(8)],
            )
            .unwrap(),
            vec![
                IrOperand::VReg(x0),
                IrOperand::VReg(base),
                IrOperand::Imm(8),
            ]
        );
        assert_eq!(
            rebuild_operands_from_regalloc(
                IrOpcode::StrPreIndex,
                &[RaOp::VReg(base)],
                &[RaOp::VReg(x0), RaOp::VReg(base), RaOp::Imm(-8)],
            )
            .unwrap(),
            vec![
                IrOperand::VReg(x0),
                IrOperand::VReg(base),
                IrOperand::Imm(-8),
            ]
        );
        assert_eq!(
            rebuild_operands_from_regalloc(
                IrOpcode::StpPreIndex,
                &[RaOp::VReg(base)],
                &[
                    RaOp::VReg(x0),
                    RaOp::VReg(x1),
                    RaOp::VReg(base),
                    RaOp::Imm(-16),
                ],
            )
            .unwrap(),
            vec![
                IrOperand::VReg(x0),
                IrOperand::VReg(x1),
                IrOperand::VReg(base),
                IrOperand::Imm(-16),
            ]
        );
    }

    #[test]
    fn classify_operand_positions_ldpri_matches_def_use() {
        let v0 = VReg::new(0, RegClass::Gpr64);
        let v1 = VReg::new(1, RegClass::Gpr64);
        let base = VReg::new(2, RegClass::Gpr64);
        let inst = make_inst(
            IrOpcode::LdpRI,
            vec![
                IrOperand::VReg(v0),
                IrOperand::VReg(v1),
                IrOperand::VReg(base),
                IrOperand::Imm(0),
            ],
        );

        let (def_positions, use_positions) = classify_operand_positions(&inst);
        assert_eq!(def_positions, vec![0, 1]);
        assert_eq!(use_positions, vec![2, 3]);

        let (defs, uses, _) = classify_def_use(&inst).unwrap();
        assert_eq!(defs.len(), def_positions.len());
        assert_eq!(uses.len(), use_positions.len());
    }

