    #[test]
    fn atomic_lse_def_use_regalloc_rebuild_and_spill_roles() {
        use trust_cg_regalloc::machine_types::{
            RegAllocBlock, RegAllocFunction, RegAllocInst, RegAllocOperand as RaOp,
        };

        let update = VReg::new(0, RegClass::Gpr64);
        let old = VReg::new(1, RegClass::Gpr64);
        let addr = VReg::new(2, RegClass::Gpr64);

        for opcode in [
            IrOpcode::Ldadd,
            IrOpcode::Ldadda,
            IrOpcode::Ldaddal,
            IrOpcode::Ldclr,
            IrOpcode::Ldclra,
            IrOpcode::Ldclral,
            IrOpcode::Ldeor,
            IrOpcode::Ldeora,
            IrOpcode::Ldeoral,
            IrOpcode::Ldset,
            IrOpcode::Ldseta,
            IrOpcode::Ldsetal,
            IrOpcode::Ldsmax,
            IrOpcode::Ldsmaxa,
            IrOpcode::Ldsmaxal,
            IrOpcode::Ldsmin,
            IrOpcode::Ldsmina,
            IrOpcode::Ldsminal,
            IrOpcode::Ldumax,
            IrOpcode::Ldumaxa,
            IrOpcode::Ldumaxal,
            IrOpcode::Ldumin,
            IrOpcode::Ldumina,
            IrOpcode::Lduminal,
            IrOpcode::Swp,
            IrOpcode::Swpa,
            IrOpcode::Swpal,
        ] {
            let inst = make_inst(
                opcode,
                vec![
                    IrOperand::VReg(update),
                    IrOperand::VReg(old),
                    IrOperand::VReg(addr),
                ],
            );
            let (def_positions, use_positions) = classify_operand_positions(&inst);
            assert_eq!(def_positions, vec![1], "{opcode:?}");
            assert_eq!(use_positions, vec![0, 2], "{opcode:?}");

            let (defs, uses, _) = classify_def_use(&inst).unwrap();
            assert_eq!(defs.len(), 1, "{opcode:?}");
            assert_eq!(uses.len(), 2, "{opcode:?}");
            assert_eq!(defs[0].as_vreg(), Some(old), "{opcode:?}");
            assert_eq!(uses[0].as_vreg(), Some(update), "{opcode:?}");
            assert_eq!(uses[1].as_vreg(), Some(addr), "{opcode:?}");
        }

        let expected = VReg::new(10, RegClass::Gpr64);
        let desired = VReg::new(11, RegClass::Gpr64);
        let cas_addr = VReg::new(12, RegClass::Gpr64);
        for opcode in [
            IrOpcode::Cas,
            IrOpcode::Casa,
            IrOpcode::Casal,
            IrOpcode::Casl,
        ] {
            let inst = make_inst(
                opcode,
                vec![
                    IrOperand::VReg(expected),
                    IrOperand::VReg(desired),
                    IrOperand::VReg(cas_addr),
                ],
            );
            let (def_positions, use_positions) = classify_operand_positions(&inst);
            assert_eq!(def_positions, vec![0], "{opcode:?}");
            assert_eq!(use_positions, vec![0, 1, 2], "{opcode:?}");

            let (defs, uses, _) = classify_def_use(&inst).unwrap();
            assert_eq!(defs.len(), 1, "{opcode:?}");
            assert_eq!(uses.len(), 3, "{opcode:?}");
            assert_eq!(defs[0].as_vreg(), Some(expected), "{opcode:?}");
            assert_eq!(uses[0].as_vreg(), Some(expected), "{opcode:?}");
            assert_eq!(uses[1].as_vreg(), Some(desired), "{opcode:?}");
            assert_eq!(uses[2].as_vreg(), Some(cas_addr), "{opcode:?}");
        }

        let sig = IrSignature::new(vec![], vec![]);
        let mut rebuilt = IrMachFunction::new("atomic_rebuild".to_string(), sig);
        let entry = rebuilt.entry;
        for inst in [
            IrMachInst::new(
                IrOpcode::Ldadd,
                vec![
                    IrOperand::VReg(update),
                    IrOperand::VReg(old),
                    IrOperand::VReg(addr),
                ],
            ),
            IrMachInst::new(
                IrOpcode::Cas,
                vec![
                    IrOperand::VReg(expected),
                    IrOperand::VReg(desired),
                    IrOperand::VReg(cas_addr),
                ],
            ),
        ] {
            let id = rebuilt.push_inst(inst);
            rebuilt.append_inst(entry, id);
        }

        let ra_func = RegAllocFunction {
            name: "atomic_rebuild".to_string(),
            insts: vec![
                RegAllocInst {
                    opcode: IrOpcode::Ldadd as u16,
                    defs: vec![RaOp::VReg(old)],
                    uses: vec![RaOp::VReg(update), RaOp::VReg(addr)],
                    implicit_defs: Vec::new(),
                    implicit_uses: Vec::new(),
                    tied_operands: Vec::new(),
                    flags: IrOpcode::Ldadd.default_flags(),
                },
                RegAllocInst {
                    opcode: IrOpcode::Cas as u16,
                    defs: vec![RaOp::VReg(expected)],
                    uses: vec![
                        RaOp::VReg(expected),
                        RaOp::VReg(desired),
                        RaOp::VReg(cas_addr),
                    ],
                    implicit_defs: Vec::new(),
                    implicit_uses: Vec::new(),
                    tied_operands: Vec::new(),
                    flags: IrOpcode::Cas.default_flags(),
                },
            ],
            blocks: vec![RegAllocBlock {
                insts: vec![InstId(0), InstId(1)],
                preds: Vec::new(),
                succs: Vec::new(),
                loop_depth: 0,
            }],
            block_order: vec![BlockId(0)],
            entry_block: BlockId(0),
            next_vreg: 13,
            next_stack_slot: 0,
            stack_slots: BTreeMap::new(),
        };

        rebuild_ir_from_regalloc(&mut rebuilt, &ra_func).unwrap();
        assert_eq!(
            rebuilt.insts[0].operands,
            vec![
                IrOperand::VReg(update),
                IrOperand::VReg(old),
                IrOperand::VReg(addr),
            ]
        );
        assert_eq!(
            rebuilt.insts[1].operands,
            vec![
                IrOperand::VReg(expected),
                IrOperand::VReg(desired),
                IrOperand::VReg(cas_addr),
            ]
        );

        let mut rmw_spill = IrMachFunction::new(
            "atomic_rmw_spill".to_string(),
            IrSignature::new(vec![], vec![]),
        );
        let rmw_id = rmw_spill.push_inst(IrMachInst::new(
            IrOpcode::Ldadd,
            vec![
                IrOperand::VReg(update),
                IrOperand::VReg(old),
                IrOperand::PReg(X2),
            ],
        ));
        rmw_spill.append_inst(rmw_spill.entry, rmw_id);
        materialize_spilled_operands(
            &mut rmw_spill,
            &[
                trust_cg_regalloc::SpillInfo {
                    vreg: update,
                    slot: StackSlotId(0),
                },
                trust_cg_regalloc::SpillInfo {
                    vreg: old,
                    slot: StackSlotId(1),
                },
            ],
        )
        .unwrap();
        let block = rmw_spill.block(rmw_spill.entry);
        assert_eq!(block.insts.len(), 3);
        assert_eq!(rmw_spill.inst(block.insts[0]).opcode, IrOpcode::LdrRI);
        assert_eq!(rmw_spill.inst(block.insts[1]).opcode, IrOpcode::Ldadd);
        assert_eq!(
            rmw_spill.inst(block.insts[1]).operands,
            vec![
                IrOperand::PReg(X16),
                IrOperand::PReg(X17),
                IrOperand::PReg(X2),
            ]
        );
        assert_eq!(rmw_spill.inst(block.insts[2]).opcode, IrOpcode::StrRI);
        assert_eq!(
            rmw_spill.inst(block.insts[2]).operands[0],
            IrOperand::PReg(X17)
        );

        let mut cas_spill = IrMachFunction::new(
            "atomic_cas_spill".to_string(),
            IrSignature::new(vec![], vec![]),
        );
        let cas_id = cas_spill.push_inst(IrMachInst::new(
            IrOpcode::Cas,
            vec![
                IrOperand::VReg(expected),
                IrOperand::PReg(X1),
                IrOperand::PReg(X2),
            ],
        ));
        cas_spill.append_inst(cas_spill.entry, cas_id);
        materialize_spilled_operands(
            &mut cas_spill,
            &[trust_cg_regalloc::SpillInfo {
                vreg: expected,
                slot: StackSlotId(0),
            }],
        )
        .unwrap();
        let block = cas_spill.block(cas_spill.entry);
        assert_eq!(block.insts.len(), 3);
        assert_eq!(cas_spill.inst(block.insts[0]).opcode, IrOpcode::LdrRI);
        assert_eq!(cas_spill.inst(block.insts[1]).opcode, IrOpcode::Cas);
        assert_eq!(
            cas_spill.inst(block.insts[1]).operands,
            vec![
                IrOperand::PReg(X16),
                IrOperand::PReg(X1),
                IrOperand::PReg(X2),
            ]
        );
        assert_eq!(cas_spill.inst(block.insts[2]).opcode, IrOpcode::StrRI);
        assert_eq!(
            cas_spill.inst(block.insts[2]).operands[0],
            IrOperand::PReg(X16)
        );
    }

    #[test]
    fn classify_def_use_physical_register_operands() {
        // Post-regalloc instruction with PRegs
        let inst = make_inst(
            IrOpcode::AddRR,
            vec![
                IrOperand::PReg(X0),
                IrOperand::PReg(X1),
                IrOperand::PReg(X2),
            ],
        );

        let (defs, uses, _) = classify_def_use(&inst).unwrap();
        assert_eq!(defs.len(), 1);
        assert_eq!(uses.len(), 2);
        assert_eq!(defs[0].as_preg(), Some(X0));
        assert_eq!(uses[0].as_preg(), Some(X1));
    }

    #[test]
    fn classify_def_use_rejects_frame_index_operand() {
        // FrameIndex should be lowered before regalloc; classify_def_use should error
        let inst = make_inst(
            IrOpcode::AddRR,
            vec![
                IrOperand::FrameIndex(trust_cg_ir::types::FrameIdx(-8)),
                IrOperand::PReg(X0),
            ],
        );

        let result = classify_def_use(&inst);
        assert!(result.is_err());
        match result.unwrap_err() {
            PipelineError::InvalidOperand(msg) => {
                assert!(msg.contains("FrameIndex"));
            }
            other => panic!("expected InvalidOperand, got {:?}", other),
        }
    }

