    #[test]
    fn spilled_pair_candidate_stays_scalar_without_replay_authority() {
        use trust_cg_opt::pass_manager::MachinePass;
        use trust_cg_opt::proof_opts::ProofOptimization;

        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("stp_scalarize_citation".to_string(), sig);

        let value0 = VReg::new(0, RegClass::Gpr64);
        let value1 = VReg::new(1, RegClass::Gpr64);
        let base = VReg::new(2, RegClass::Gpr64);
        let str0 = func.push_inst(IrMachInst::new(
            IrOpcode::StrRI,
            vec![
                IrOperand::VReg(value0),
                IrOperand::VReg(base),
                IrOperand::Imm(0),
            ],
        ));
        let str1 = func.push_inst(IrMachInst::new(
            IrOpcode::StrRI,
            vec![
                IrOperand::VReg(value1),
                IrOperand::VReg(base),
                IrOperand::Imm(8),
            ],
        ));
        func.append_inst(func.entry, str0);
        func.append_inst(func.entry, str1);

        let mut proof = ProofOptimization::new();
        proof.set_inst_proof_facts(str0, vec![trust_cg_ir::ProofFact::Aligned(16)]);
        proof.set_inst_proof_facts(str1, vec![trust_cg_ir::ProofFact::Aligned(16)]);

        assert!(!proof.run(&mut func));
        assert_eq!(proof.stats().pair_mem_ops_combined, 0);
        assert_eq!(func.block(func.entry).insts, vec![str0, str1]);
        let citations = proof_optimization_certificate_citations(&func.name, proof.certificates());
        assert!(citations.is_empty());

        let spills = vec![
            trust_cg_regalloc::SpillInfo {
                vreg: value0,
                slot: StackSlotId(0),
            },
            trust_cg_regalloc::SpillInfo {
                vreg: value1,
                slot: StackSlotId(1),
            },
            trust_cg_regalloc::SpillInfo {
                vreg: base,
                slot: StackSlotId(2),
            },
        ];
        materialize_spilled_operands(&mut func, &spills).unwrap();

        let block = func.block(func.entry);
        let scalar_store_count = block
            .insts
            .iter()
            .filter(|inst_id| func.inst(**inst_id).opcode == IrOpcode::StrRI)
            .count();
        assert_eq!(scalar_store_count, 2);
        assert!(
            block
                .insts
                .iter()
                .all(|inst_id| func.inst(*inst_id).opcode != IrOpcode::StpRI),
            "scalarized spill path must not leave the pair op behind"
        );
        ensure_no_unresolved_vregs(&func, "scalar spill materialization").unwrap();
    }

