    #[test]
    fn materialize_spilled_operands_handles_ldpri_two_spilled_defs_with_physical_base() {
        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("test".to_string(), sig);

        let dst0 = VReg::new(0, RegClass::Gpr64);
        let dst1 = VReg::new(1, RegClass::Gpr64);
        let inst_id = func.push_inst(IrMachInst::new(
            IrOpcode::LdpRI,
            vec![
                IrOperand::VReg(dst0),
                IrOperand::VReg(dst1),
                IrOperand::PReg(X2),
                IrOperand::Imm(0),
            ],
        ));
        func.append_inst(func.entry, inst_id);

        let spills = vec![
            trust_cg_regalloc::SpillInfo {
                vreg: dst0,
                slot: StackSlotId(0),
            },
            trust_cg_regalloc::SpillInfo {
                vreg: dst1,
                slot: StackSlotId(1),
            },
        ];

        materialize_spilled_operands(&mut func, &spills).unwrap();

        // A GPR pair with a physical base is SPLIT into two independent
        // single-value load+spill-store sequences that hold each value in X16
        // ONLY, leaving X17 free for the frame-index eliminator's far-offset
        // address materialization. Keeping the original `ldp X16, X17` (the old
        // behavior) put a live value in X17 that the first store's far-offset
        // materialization would overwrite — the pr28982b loop-carried-pointer
        // miscompile.
        let block = &func.blocks[func.entry.0 as usize];
        assert_eq!(block.insts.len(), 4);

        let load_dst0 = func.inst(block.insts[0]);
        assert_eq!(load_dst0.opcode, IrOpcode::LdrRI);
        assert_eq!(
            load_dst0.operands,
            vec![IrOperand::PReg(X16), IrOperand::PReg(X2), IrOperand::Imm(0),]
        );

        let store_dst0 = func.inst(block.insts[1]);
        assert_eq!(store_dst0.opcode, IrOpcode::StrRI);
        assert_eq!(
            store_dst0.operands,
            vec![IrOperand::PReg(X16), IrOperand::StackSlot(StackSlotId(0))]
        );

        let load_dst1 = func.inst(block.insts[2]);
        assert_eq!(load_dst1.opcode, IrOpcode::LdrRI);
        assert_eq!(
            load_dst1.operands,
            vec![IrOperand::PReg(X16), IrOperand::PReg(X2), IrOperand::Imm(8),]
        );

        let store_dst1 = func.inst(block.insts[3]);
        assert_eq!(store_dst1.opcode, IrOpcode::StrRI);
        assert_eq!(
            store_dst1.operands,
            vec![IrOperand::PReg(X16), IrOperand::StackSlot(StackSlotId(1))]
        );
        ensure_no_unresolved_vregs(&func, "ldpri two-def spill materialization").unwrap();
    }

