    #[test]
    fn materialize_spilled_operands_scalarizes_ldpri_two_spilled_defs_and_base() {
        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("test".to_string(), sig);

        let dst0 = VReg::new(0, RegClass::Gpr64);
        let dst1 = VReg::new(1, RegClass::Gpr64);
        let base = VReg::new(2, RegClass::Gpr64);
        let inst_id = func.push_inst(IrMachInst::new(
            IrOpcode::LdpRI,
            vec![
                IrOperand::VReg(dst0),
                IrOperand::VReg(dst1),
                IrOperand::VReg(base),
                IrOperand::Imm(16),
            ],
        ));
        func.append_inst(func.entry, inst_id);

        let spills = vec![
            trust_cg_regalloc::SpillInfo {
                vreg: dst0,
                slot: StackSlotId(0),
            },
            trust_cg_regalloc::SpillInfo {
                vreg: dst1,
                slot: StackSlotId(1),
            },
            trust_cg_regalloc::SpillInfo {
                vreg: base,
                slot: StackSlotId(2),
            },
        ];

        materialize_spilled_operands(&mut func, &spills).unwrap();

        let block = &func.blocks[func.entry.0 as usize];
        assert_eq!(block.insts.len(), 8);

        let load_base = func.inst(block.insts[0]);
        assert_eq!(load_base.opcode, IrOpcode::LdrRI);
        assert_eq!(
            load_base.operands,
            vec![IrOperand::PReg(X16), IrOperand::StackSlot(StackSlotId(2))]
        );

        let adjust_base = func.inst(block.insts[1]);
        assert_eq!(adjust_base.opcode, IrOpcode::AddRI);
        assert_eq!(
            adjust_base.operands,
            vec![
                IrOperand::PReg(X16),
                IrOperand::PReg(X16),
                IrOperand::Imm(16),
            ]
        );

        let load_dst0 = func.inst(block.insts[2]);
        assert_eq!(load_dst0.opcode, IrOpcode::LdrRI);
        assert_eq!(
            load_dst0.operands,
            vec![
                IrOperand::PReg(X17),
                IrOperand::PReg(X16),
                IrOperand::Imm(0),
            ]
        );

        let store_dst0 = func.inst(block.insts[3]);
        assert_eq!(store_dst0.opcode, IrOpcode::StrRI);
        assert_eq!(
            store_dst0.operands,
            vec![IrOperand::PReg(X17), IrOperand::StackSlot(StackSlotId(0))]
        );

        let reload_base = func.inst(block.insts[4]);
        assert_eq!(reload_base.opcode, IrOpcode::LdrRI);
        assert_eq!(
            reload_base.operands,
            vec![IrOperand::PReg(X16), IrOperand::StackSlot(StackSlotId(2))]
        );

        let readjust_base = func.inst(block.insts[5]);
        assert_eq!(readjust_base.opcode, IrOpcode::AddRI);
        assert_eq!(
            readjust_base.operands,
            vec![
                IrOperand::PReg(X16),
                IrOperand::PReg(X16),
                IrOperand::Imm(16),
            ]
        );

        let load_dst1 = func.inst(block.insts[6]);
        assert_eq!(load_dst1.opcode, IrOpcode::LdrRI);
        assert_eq!(
            load_dst1.operands,
            vec![
                IrOperand::PReg(X17),
                IrOperand::PReg(X16),
                IrOperand::Imm(8),
            ]
        );

        let store_dst1 = func.inst(block.insts[7]);
        assert_eq!(store_dst1.opcode, IrOpcode::StrRI);
        assert_eq!(
            store_dst1.operands,
            vec![IrOperand::PReg(X17), IrOperand::StackSlot(StackSlotId(1))]
        );
        assert!(
            block
                .insts
                .iter()
                .all(|inst_id| func.inst(*inst_id).opcode != IrOpcode::LdpRI),
            "scalarized spill materialization must remove the unresolved LDP"
        );
        ensure_no_unresolved_vregs(&func, "ldpri full spill scalarization").unwrap();
    }

