    // Register-offset spill materialization for the non-default addressing
    // modes (scaled index and 32-bit extended index). The emitted scratch
    // sequence must reproduce the effective address the non-spill LdrRO/StrRO
    // encoder + hardware compute: addr = base + (extend(index) << scale). These
    // pin the exact opcodes, cross-checked against the faithful ARM-ARM model in
    // tests/common/a64_interp.rs (UXTW=zext32, SXTW=sext32, shift = log2(size)).

    #[test]
    fn materialize_spilled_operands_handles_ldro_lsl_scaled_index() {
        // LDR Xdst, [Xbase, Xindex, LSL #3] (option=0b011, S=1, 8-byte access).
        // This is the exact mode the ty MCL native tests exercise (Imm(7)).
        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("test".to_string(), sig);

        let dst = VReg::new(0, RegClass::Gpr64);
        let base = VReg::new(1, RegClass::Gpr64);
        let index = VReg::new(2, RegClass::Gpr64);
        let inst_id = func.push_inst(IrMachInst::new(
            IrOpcode::LdrRO,
            vec![
                IrOperand::VReg(dst),
                IrOperand::VReg(base),
                IrOperand::VReg(index),
                IrOperand::Imm((0b011 << 1) | 1), // == 7
            ],
        ));
        func.append_inst(func.entry, inst_id);

        let spills = vec![
            trust_cg_regalloc::SpillInfo {
                vreg: dst,
                slot: StackSlotId(0),
            },
            trust_cg_regalloc::SpillInfo {
                vreg: base,
                slot: StackSlotId(1),
            },
            trust_cg_regalloc::SpillInfo {
                vreg: index,
                slot: StackSlotId(2),
            },
        ];

        materialize_spilled_operands(&mut func, &spills).unwrap();

        let block = &func.blocks[func.entry.0 as usize];
        assert_eq!(block.insts.len(), 6);

        // [0] reload base into X16, [1] reload index into X17.
        assert_eq!(func.inst(block.insts[0]).opcode, IrOpcode::LdrRI);
        assert_eq!(func.inst(block.insts[0]).operands[0], IrOperand::PReg(X16));
        assert_eq!(func.inst(block.insts[1]).opcode, IrOpcode::LdrRI);
        assert_eq!(func.inst(block.insts[1]).operands[0], IrOperand::PReg(X17));

        // [2] scale the index by log2(8) = 3 (no extend for the LSL form).
        let shift = func.inst(block.insts[2]);
        assert_eq!(shift.opcode, IrOpcode::LslRI);
        assert_eq!(
            shift.operands,
            vec![
                IrOperand::PReg(X17),
                IrOperand::PReg(X17),
                IrOperand::Imm(3),
            ]
        );

        // [3] addr = base + scaled index.
        let add_addr = func.inst(block.insts[3]);
        assert_eq!(add_addr.opcode, IrOpcode::AddRR);
        assert_eq!(
            add_addr.operands,
            vec![
                IrOperand::PReg(X16),
                IrOperand::PReg(X16),
                IrOperand::PReg(X17),
            ]
        );

        // [4] the load, now a plain [addr, #0].
        let load = func.inst(block.insts[4]);
        assert_eq!(load.opcode, IrOpcode::LdrRI);
        assert_eq!(
            load.operands,
            vec![
                IrOperand::PReg(X17),
                IrOperand::PReg(X16),
                IrOperand::Imm(0),
            ]
        );

        // [5] spill the loaded value back to dst's slot.
        let store = func.inst(block.insts[5]);
        assert_eq!(store.opcode, IrOpcode::StrRI);
        assert_eq!(store.operands[0], IrOperand::PReg(X17));
        assert_eq!(store.operands[1], IrOperand::StackSlot(StackSlotId(0)));
    }

    #[test]
    fn materialize_spilled_operands_handles_strro_sxtw_scaled_index() {
        // STR Xval, [Xbase, Windex, SXTW #3] (option=0b110, S=1, 8-byte access).
        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("test".to_string(), sig);

        let value = VReg::new(0, RegClass::Gpr64);
        let base = VReg::new(1, RegClass::Gpr64);
        let index = VReg::new(2, RegClass::Gpr32);
        let inst_id = func.push_inst(IrMachInst::new(
            IrOpcode::StrRO,
            vec![
                IrOperand::VReg(value),
                IrOperand::VReg(base),
                IrOperand::VReg(index),
                IrOperand::Imm((0b110 << 1) | 1), // == 13
            ],
        ));
        func.append_inst(func.entry, inst_id);

        let spills = vec![
            trust_cg_regalloc::SpillInfo {
                vreg: value,
                slot: StackSlotId(0),
            },
            trust_cg_regalloc::SpillInfo {
                vreg: base,
                slot: StackSlotId(1),
            },
            trust_cg_regalloc::SpillInfo {
                vreg: index,
                slot: StackSlotId(2),
            },
        ];

        materialize_spilled_operands(&mut func, &spills).unwrap();

        let block = &func.blocks[func.entry.0 as usize];
        assert_eq!(block.insts.len(), 7);

        // [1] reload the 32-bit index into W17 (zero-extended into X17).
        let load_index = func.inst(block.insts[1]);
        assert_eq!(load_index.opcode, IrOpcode::LdrRI);
        assert_eq!(load_index.operands[0], IrOperand::PReg(W17));
        assert_eq!(load_index.operands[1], IrOperand::StackSlot(StackSlotId(2)));

        // [2] sign-extend the low 32 bits of the index.
        let ext = func.inst(block.insts[2]);
        assert_eq!(ext.opcode, IrOpcode::Sxtw);
        assert_eq!(
            ext.operands,
            vec![IrOperand::PReg(X17), IrOperand::PReg(X17)]
        );

        // [3] scale by log2(8) = 3.
        let shift = func.inst(block.insts[3]);
        assert_eq!(shift.opcode, IrOpcode::LslRI);
        assert_eq!(
            shift.operands,
            vec![
                IrOperand::PReg(X17),
                IrOperand::PReg(X17),
                IrOperand::Imm(3),
            ]
        );

        // [4] addr = base + extended, scaled index (into X17).
        let add_addr = func.inst(block.insts[4]);
        assert_eq!(add_addr.opcode, IrOpcode::AddRR);
        assert_eq!(
            add_addr.operands,
            vec![
                IrOperand::PReg(X17),
                IrOperand::PReg(X16),
                IrOperand::PReg(X17),
            ]
        );

        // [5] reload the value, [6] store it at the computed address.
        let load_value = func.inst(block.insts[5]);
        assert_eq!(load_value.opcode, IrOpcode::LdrRI);
        assert_eq!(load_value.operands[0], IrOperand::PReg(X16));
        assert_eq!(load_value.operands[1], IrOperand::StackSlot(StackSlotId(0)));

        let store = func.inst(block.insts[6]);
        assert_eq!(store.opcode, IrOpcode::StrRI);
        assert_eq!(
            store.operands,
            vec![
                IrOperand::PReg(X16),
                IrOperand::PReg(X17),
                IrOperand::Imm(0),
            ]
        );
    }

    #[test]
    fn materialize_spilled_operands_handles_ldro_uxtw_scaled_index() {
        // LDR Wdst, [Xbase, Windex, UXTW #2] (option=0b010, S=1, 4-byte access).
        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("test".to_string(), sig);

        let dst = VReg::new(0, RegClass::Gpr32);
        let base = VReg::new(1, RegClass::Gpr64);
        let index = VReg::new(2, RegClass::Gpr32);
        let inst_id = func.push_inst(IrMachInst::new(
            IrOpcode::LdrRO,
            vec![
                IrOperand::VReg(dst),
                IrOperand::VReg(base),
                IrOperand::VReg(index),
                IrOperand::Imm((0b010 << 1) | 1), // == 5
            ],
        ));
        func.append_inst(func.entry, inst_id);

        let spills = vec![
            trust_cg_regalloc::SpillInfo {
                vreg: dst,
                slot: StackSlotId(0),
            },
            trust_cg_regalloc::SpillInfo {
                vreg: base,
                slot: StackSlotId(1),
            },
            trust_cg_regalloc::SpillInfo {
                vreg: index,
                slot: StackSlotId(2),
            },
        ];

        materialize_spilled_operands(&mut func, &spills).unwrap();

        let block = &func.blocks[func.entry.0 as usize];
        assert_eq!(block.insts.len(), 7);

        // [2] zero-extend the low 32 bits of the index.
        let ext = func.inst(block.insts[2]);
        assert_eq!(ext.opcode, IrOpcode::Uxtw);
        assert_eq!(
            ext.operands,
            vec![IrOperand::PReg(X17), IrOperand::PReg(X17)]
        );

        // [3] scale by log2(4) = 2.
        let shift = func.inst(block.insts[3]);
        assert_eq!(shift.opcode, IrOpcode::LslRI);
        assert_eq!(
            shift.operands,
            vec![
                IrOperand::PReg(X17),
                IrOperand::PReg(X17),
                IrOperand::Imm(2),
            ]
        );

        // [4] addr = base + extended, scaled index.
        let add_addr = func.inst(block.insts[4]);
        assert_eq!(add_addr.opcode, IrOpcode::AddRR);
        assert_eq!(
            add_addr.operands,
            vec![
                IrOperand::PReg(X16),
                IrOperand::PReg(X16),
                IrOperand::PReg(X17),
            ]
        );

        // [5] the 32-bit load into W17.
        let load = func.inst(block.insts[5]);
        assert_eq!(load.opcode, IrOpcode::LdrRI);
        assert_eq!(
            load.operands,
            vec![
                IrOperand::PReg(W17),
                IrOperand::PReg(X16),
                IrOperand::Imm(0),
            ]
        );
    }

    #[test]
    fn materialize_spilled_operands_fails_closed_on_unsupported_ro_option() {
        // option=0b000 (UXTB) is not a valid register-offset extend; the
        // materializer must fail closed rather than silently miscompile.
        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("test".to_string(), sig);

        let dst = VReg::new(0, RegClass::Gpr64);
        let base = VReg::new(1, RegClass::Gpr64);
        let index = VReg::new(2, RegClass::Gpr64);
        let inst_id = func.push_inst(IrMachInst::new(
            IrOpcode::LdrRO,
            vec![
                IrOperand::VReg(dst),
                IrOperand::VReg(base),
                IrOperand::VReg(index),
                IrOperand::Imm(0), // option=0b000, S=0
            ],
        ));
        func.append_inst(func.entry, inst_id);

        let spills = vec![
            trust_cg_regalloc::SpillInfo {
                vreg: dst,
                slot: StackSlotId(0),
            },
            trust_cg_regalloc::SpillInfo {
                vreg: base,
                slot: StackSlotId(1),
            },
            trust_cg_regalloc::SpillInfo {
                vreg: index,
                slot: StackSlotId(2),
            },
        ];

        assert!(materialize_spilled_operands(&mut func, &spills).is_err());
    }

