    #[test]
    fn rebuild_ir_from_regalloc_does_not_leak_incoming_arg_to_later_zero_offset_load() {
        use trust_cg_regalloc::machine_types::{
            RegAllocBlock, RegAllocFunction, RegAllocInst, RegAllocOperand,
        };

        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("incoming_arg_restore".to_string(), sig);
        let entry = func.entry;
        let arg_value = VReg::new(0, RegClass::Gpr32);
        let state_addr = VReg::new(1, RegClass::Gpr64);
        let loaded_value = VReg::new(2, RegClass::Gpr64);

        let incoming_load = func.push_inst(IrMachInst::new(
            IrOpcode::LdrRI,
            vec![
                IrOperand::VReg(arg_value),
                IrOperand::PReg(trust_cg_ir::regs::X29),
                IrOperand::IncomingArg(0),
            ],
        ));
        let state_load = func.push_inst(IrMachInst::new(
            IrOpcode::LdrRI,
            vec![
                IrOperand::VReg(loaded_value),
                IrOperand::VReg(state_addr),
                IrOperand::Imm(0),
            ],
        ));
        func.append_inst(entry, incoming_load);
        func.append_inst(entry, state_load);

        let ra_func = RegAllocFunction {
            name: "incoming_arg_restore".to_string(),
            insts: vec![
                RegAllocInst {
                    opcode: IrOpcode::LdrRI as u16,
                    defs: vec![RegAllocOperand::VReg(arg_value)],
                    uses: vec![
                        RegAllocOperand::PReg(trust_cg_ir::regs::X29),
                        RegAllocOperand::Imm(0),
                    ],
                    implicit_defs: Vec::new(),
                    implicit_uses: Vec::new(),
                    tied_operands: Vec::new(),
                    flags: IrOpcode::LdrRI.default_flags(),
                },
                RegAllocInst {
                    opcode: IrOpcode::LdrRI as u16,
                    defs: vec![RegAllocOperand::VReg(loaded_value)],
                    uses: vec![RegAllocOperand::VReg(state_addr), RegAllocOperand::Imm(0)],
                    implicit_defs: Vec::new(),
                    implicit_uses: Vec::new(),
                    tied_operands: Vec::new(),
                    flags: IrOpcode::LdrRI.default_flags(),
                },
            ],
            blocks: vec![RegAllocBlock {
                insts: vec![InstId(0), InstId(1)],
                preds: Vec::new(),
                succs: Vec::new(),
                loop_depth: 0,
            }],
            block_order: vec![BlockId(0)],
            entry_block: BlockId(0),
            next_vreg: 3,
            next_stack_slot: 0,
            stack_slots: BTreeMap::new(),
        };

        rebuild_ir_from_regalloc(&mut func, &ra_func).unwrap();

        assert_eq!(
            func.insts[0].operands,
            vec![
                IrOperand::VReg(arg_value),
                IrOperand::PReg(trust_cg_ir::regs::X29),
                IrOperand::IncomingArg(0),
            ]
        );
        assert_eq!(
            func.insts[1].operands,
            vec![
                IrOperand::VReg(loaded_value),
                IrOperand::VReg(state_addr),
                IrOperand::Imm(0),
            ]
        );
    }

