    #[test]
    fn aarch64_call_arg_fixup_prunes_superseded_identity_setup() {
        static CALL_ARGS: [PReg; 2] = [X0, X1];

        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("superseded_identity_arg".to_string(), sig);
        let entry = func.entry;

        // This exact post-RA shape arose in Level::hash. The trailing identity
        // reads the x19 value established by the first setup; it must not be
        // interpreted as a request to restore stale pre-group x1.
        let setup_x1 = func.push_inst(call_arg_setup(IrMachInst::new(
            IrOpcode::Copy,
            vec![IrOperand::PReg(X1), IrOperand::PReg(X19)],
        )));
        let setup_x0 = func.push_inst(call_arg_setup(IrMachInst::new(
            IrOpcode::Copy,
            vec![IrOperand::PReg(X0), IrOperand::PReg(X21)],
        )));
        let identity_x1 = func.push_inst(call_arg_setup(IrMachInst::new(
            IrOpcode::Copy,
            vec![IrOperand::PReg(X1), IrOperand::PReg(X1)],
        )));
        let call = func.push_inst(
            IrMachInst::new(IrOpcode::Bl, vec![IrOperand::Symbol("_callee".into())])
                .with_implicit_uses(&CALL_ARGS),
        );
        func.append_inst(entry, setup_x1);
        func.append_inst(entry, setup_x0);
        func.append_inst(entry, identity_x1);
        func.append_inst(entry, call);

        fixup_aarch64_call_arg_source_clobbers(&mut func).unwrap();
        assert_eq!(
            func.block(entry).insts,
            vec![setup_x1, setup_x0, identity_x1, call],
            "repair must not insert a stale x1 preserve/restore"
        );

        lower_copies(&mut func).unwrap();
        assert_eq!(func.inst(identity_x1).opcode, IrOpcode::Nop);
        assert_eq!(
            func.block(entry).insts,
            vec![setup_x1, setup_x0, identity_x1, call],
            "identity provenance must survive as a non-encoding final marker"
        );
    }

