    #[test]
    fn aarch64_call_arg_provenance_distinguishes_sequential_reload_from_parallel_setup() {
        static CALL_ARGS: [PReg; 2] = [X1, X2];
        let mut func = IrMachFunction::new(
            "sequential_reload_before_args".to_string(),
            IrSignature::new(vec![], vec![]),
        );
        let entry = func.entry;

        // A spill reload is sequential: X2 must receive X16 before the marked
        // X1 setup reads it.  The following marked identity records that the
        // same reloaded value is also the X2 argument.  Adjacency-based
        // reconstruction used to misread the first two instructions as a
        // parallel source clobber and reject this exact production shape.
        let reload = func.push_inst(IrMachInst::new(
            IrOpcode::Copy,
            vec![IrOperand::PReg(X2), IrOperand::PReg(X16)],
        ));
        let setup_x1 = func.push_inst(call_arg_setup(IrMachInst::new(
            IrOpcode::Copy,
            vec![IrOperand::PReg(X1), IrOperand::PReg(X2)],
        )));
        let setup_x2 = func.push_inst(call_arg_setup(IrMachInst::new(
            IrOpcode::Copy,
            vec![IrOperand::PReg(X2), IrOperand::PReg(X2)],
        )));
        let call = func.push_inst(
            IrMachInst::new(IrOpcode::Bl, vec![IrOperand::Symbol("_callee".into())])
                .with_implicit_uses(&CALL_ARGS),
        );
        for id in [reload, setup_x1, setup_x2, call] {
            func.append_inst(entry, id);
        }

        fixup_aarch64_call_arg_source_clobbers(&mut func).unwrap();
        assert_eq!(
            func.block(entry).insts,
            vec![reload, setup_x1, setup_x2, call]
        );
        lower_copies(&mut func).unwrap();
        assert_eq!(func.inst(reload).opcode, IrOpcode::MOVXrr);
        assert_eq!(func.inst(setup_x1).opcode, IrOpcode::MOVXrr);
        assert_eq!(func.inst(setup_x2).opcode, IrOpcode::Nop);
        verify_aarch64_final_call_argument_sequence(
            &func.name,
            func.block(entry).insts.iter().map(|&id| func.inst(id)),
        )
        .expect("the exact sequential reload plus marked setup must verify");
    }

