    // Regression for defect #4b: the allocator may park an unrelated, soon-dead
    // value in a pre-colored argument register (here X4). A later `uxth w4, w5`
    // re-establishes X4 as the *actual* argument the call consumes. The
    // dead-value's earlier copy into X4 must NOT trigger a save/restore, because
    // restoring it would clobber the real argument. The fixup is liveness-aware:
    // because the `uxth` value reaches the call unread, the earlier X4 copy is
    // recognized as dead and left alone.
    #[test]
    fn aarch64_call_arg_fixup_skips_preserve_for_dead_value_in_arg_reg() {
        static CALL_ARGS: [PReg; 1] = [X4];

        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("dead_arg_reg_value".to_string(), sig);
        let entry = func.entry;

        // X4 <- X6: park a value in the 5th arg register. It is used twice below
        // (so it is not immediately dead) but never again after that.
        let park_x4 = func.push_inst(IrMachInst::new(
            IrOpcode::Copy,
            vec![IrOperand::PReg(X4), IrOperand::PReg(X6)],
        ));
        // Two consumers of the parked value (mul + xor analogue). After these,
        // the parked X4 value is dead.
        let use1 = func.push_inst(IrMachInst::new(
            IrOpcode::AddRR,
            vec![
                IrOperand::PReg(X1),
                IrOperand::PReg(X4),
                IrOperand::PReg(X3),
            ],
        ));
        let use2 = func.push_inst(IrMachInst::new(
            IrOpcode::AddRR,
            vec![
                IrOperand::PReg(X5),
                IrOperand::PReg(X1),
                IrOperand::PReg(X4),
            ],
        ));
        // The REAL 5th argument: zero-extend the narrow value into X4. Its value
        // is read only by the call below, so it reaches the call unread.
        let real_arg = func.push_inst(IrMachInst::new(
            IrOpcode::Uxth,
            vec![IrOperand::PReg(W4), IrOperand::PReg(W5)],
        ));
        let call = func.push_inst(
            IrMachInst::new(IrOpcode::Blr, vec![IrOperand::PReg(X21)])
                .with_implicit_uses(&CALL_ARGS),
        );
        func.append_inst(entry, park_x4);
        func.append_inst(entry, use1);
        func.append_inst(entry, use2);
        func.append_inst(entry, real_arg);
        func.append_inst(entry, call);

        fixup_aarch64_call_arg_source_clobbers(&mut func).unwrap();

        // No save/restore must be inserted: the sequence is unchanged.
        let insts = func.block(entry).insts.clone();
        assert_eq!(
            insts,
            vec![park_x4, use1, use2, real_arg, call],
            "no preserve/restore should be inserted around a dead value parked in an arg register"
        );
    }

    /// Regression: a variadic-constructor `num_objs` argument clobbered by a
    /// spurious implicit-preserve restore.
    ///
    /// `clean_alloc_ctor(tag, num_objs, scalar, field…)` is variadic. The
    /// allocator can materialize a constant shared by two arguments (e.g.
    /// `tag == num_objs == 1`) into one argument register (X1) and copy it to
    /// the other (X0) — `Movz W1,#1 ; Copy W0,W1`. X1's region-entry value was
    /// clobbered *dead* by the opening call (X1 is caller-saved and is NOT that
    /// call's result register). The old implicit-preserve saw `Copy W0,W1`
    /// "consume" X1 and wrongly restored X1's dead region-entry value, wiping
    /// `num_objs` — the runtime then allocated an Int cell with too few fields
    /// and `clean_ctor_get` read out of bounds. No preserve is correct: X1's
    /// argument is the freshly materialized constant, not a live incoming value.
    #[test]
    fn aarch64_call_arg_fixup_skips_preserve_for_constant_arg_after_call_clobber() {
        static OPENING_CLOBBERS: [PReg; 3] = [X0, X1, X2];
        static CTOR_ARGS: [PReg; 3] = [X0, X1, X2];

        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("variadic_ctor_num_objs".to_string(), sig);
        let entry = func.entry;

        // Opening call: result (the field) lands in X0 (live); X1/X2 are
        // caller-saved and left dead.
        let opening = func.push_inst(
            IrMachInst::new(IrOpcode::Blr, vec![IrOperand::PReg(X21)])
                .with_implicit_defs(&OPENING_CLOBBERS),
        );
        // Capture the field (opening call's X0 result) for the stack slot.
        let capture = func.push_inst(IrMachInst::new(
            IrOpcode::Copy,
            vec![IrOperand::PReg(X3), IrOperand::PReg(X0)],
        ));
        // num_objs = 1 materialized into the X1 argument register.
        let movz_x1 = func.push_inst(IrMachInst::new(
            IrOpcode::Movz,
            vec![IrOperand::PReg(W1), IrOperand::Imm(1)],
        ));
        // tag = 1 (the same constant) copied from X1 into the X0 argument reg —
        // this read is what fooled the old "consumed before call" gate.
        let copy_x0 = func.push_inst(IrMachInst::new(
            IrOpcode::Copy,
            vec![IrOperand::PReg(W0), IrOperand::PReg(W1)],
        ));
        // Variadic field spilled to the stack (Apple ABI passes varargs on stack).
        let str_field = func.push_inst(IrMachInst::new(
            IrOpcode::StrRI,
            vec![IrOperand::PReg(X3), IrOperand::PReg(SP), IrOperand::Imm(0)],
        ));
        let call = func.push_inst(
            IrMachInst::new(
                IrOpcode::Bl,
                vec![IrOperand::Symbol("clean_alloc_ctor".into())],
            )
            .with_implicit_uses(&CTOR_ARGS),
        );
        for inst in [opening, capture, movz_x1, copy_x0, str_field, call] {
            func.append_inst(entry, inst);
        }

        fixup_aarch64_call_arg_source_clobbers(&mut func).unwrap();

        // No preserve/restore must be inserted: X1's argument is the freshly
        // materialized constant, not a live region-entry value to rescue.
        let insts = func.block(entry).insts.clone();
        assert_eq!(
            insts,
            vec![opening, capture, movz_x1, copy_x0, str_field, call],
            "no preserve/restore should wrap a constant argument established after a caller-saved clobber"
        );
    }

    /// Regression: an alloca address materialized into a NON-parameter argument
    /// register at the function entry and passed as a call argument. This is the
    /// `RawVecInner::grow_one` shape: `%9 = alloca Layout` whose address is arg5
    /// (`sub x4, x29, #imm`) and is written to via `str` before the call, yet is
    /// exactly the `&Layout` the call consumes.
    ///
    /// The materializing `sub` DEFs x4 at a position past 0 (so the
    /// `first_clobber_pos == 0` gate does not fire) and its value is READ by the
    /// store before the call (so the "consumed before call" transient test is
    /// fooled into thinking a live entry value must be rescued). But x4 is NOT a
    /// formal-parameter register — the function takes one pointer param in x0 —
    /// so x4's region-entry value is dead caller garbage. The old implicit-
    /// preserve saved that dead x4 into a scratch before the `sub` and restored
    /// it (`mov x9,x4` / `mov x4,x9`) before the `bl`, passing NULL/garbage as
    /// the `&Layout`; `grow_amortized` then read `layout.align` through it and
    /// SIGSEGV'd. No preserve is correct: the `sub` establishes the argument.
    #[test]
    fn aarch64_call_arg_fixup_skips_preserve_for_alloca_addr_arg_at_entry() {
        static CALL_ARGS: [PReg; 1] = [X4];

        // One pointer parameter => the only live incoming ABI register is X0.
        let sig = IrSignature::new(vec![Type::Ptr], vec![]);
        let mut func = IrMachFunction::new("alloca_addr_arg_at_entry".to_string(), sig);
        let entry = func.entry;

        // A non-X4 def first, so the first clobber of X4 is not at position 0.
        let relocate_self = func.push_inst(IrMachInst::new(
            IrOpcode::Copy,
            vec![IrOperand::PReg(X1), IrOperand::PReg(X0)],
        ));
        // Materialize the alloca address into X4 (arg5): `sub x4, x29, #0x60`.
        let sub_x4 = func.push_inst(IrMachInst::new(
            IrOpcode::SubRI,
            vec![
                IrOperand::PReg(X4),
                IrOperand::PReg(X29),
                IrOperand::Imm(0x60),
            ],
        ));
        // Store through X4 (reads X4 as the store address) — "consumed" before
        // the call yet X4's value still reaches the call as the argument.
        let store_via_x4 = func.push_inst(IrMachInst::new(
            IrOpcode::StrRI,
            vec![IrOperand::PReg(X19), IrOperand::PReg(X4), IrOperand::Imm(0)],
        ));
        let call = func.push_inst(
            IrMachInst::new(
                IrOpcode::Bl,
                vec![IrOperand::Symbol("grow_amortized".into())],
            )
            .with_implicit_uses(&CALL_ARGS),
        );
        for inst in [relocate_self, sub_x4, store_via_x4, call] {
            func.append_inst(entry, inst);
        }

        fixup_aarch64_call_arg_source_clobbers(&mut func).unwrap();

        // No save/restore around X4: the `sub` establishes the argument, and X4's
        // dead region-entry value (X4 is not a formal parameter) is nothing to
        // preserve. The sequence must be unchanged.
        let insts = func.block(entry).insts.clone();
        assert_eq!(
            insts,
            vec![relocate_self, sub_x4, store_via_x4, call],
            "no preserve/restore should wrap an alloca-address argument materialized at entry into a non-parameter arg register"
        );
    }

    #[test]
    fn aarch64_call_arg_fixup_leaves_non_clobbering_args_unchanged() {
        static CALL_ARGS: [PReg; 2] = [X0, X1];

        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("ordered_call_args".to_string(), sig);
        let entry = func.entry;

        let copy_x0 = func.push_inst(call_arg_setup(IrMachInst::new(
            IrOpcode::Copy,
            vec![IrOperand::PReg(X0), IrOperand::PReg(X5)],
        )));
        let copy_x1 = func.push_inst(call_arg_setup(IrMachInst::new(
            IrOpcode::Copy,
            vec![IrOperand::PReg(X1), IrOperand::PReg(X6)],
        )));
        let call = func.push_inst(
            IrMachInst::new(IrOpcode::Blr, vec![IrOperand::PReg(X21)])
                .with_implicit_uses(&CALL_ARGS),
        );
        func.append_inst(entry, copy_x0);
        func.append_inst(entry, copy_x1);
        func.append_inst(entry, call);

        fixup_aarch64_call_arg_source_clobbers(&mut func).unwrap();

        assert_eq!(func.block(entry).insts, vec![copy_x0, copy_x1, call]);
    }

    #[test]
    fn aarch64_call_arg_fixup_fails_closed_when_gpr_scratch_is_exhausted() {
        let call_args: &'static [PReg] = Box::leak(
            std::iter::once(X0)
                .chain(std::iter::once(X1))
                .chain((9..=17).map(PReg::new))
                .collect::<Vec<_>>()
                .into_boxed_slice(),
        );
        let mut func = IrMachFunction::new(
            "gpr_scratch_exhaustion".to_string(),
            IrSignature::new(vec![], vec![]),
        );
        let entry = func.entry;
        for inst in [
            call_arg_setup(IrMachInst::new(
                IrOpcode::Copy,
                vec![IrOperand::PReg(X0), IrOperand::PReg(X1)],
            )),
            call_arg_setup(IrMachInst::new(
                IrOpcode::Copy,
                vec![IrOperand::PReg(X1), IrOperand::PReg(X0)],
            )),
            IrMachInst::new(IrOpcode::Blr, vec![IrOperand::PReg(X21)])
                .with_implicit_uses(call_args),
        ] {
            let id = func.push_inst(inst);
            func.append_inst(entry, id);
        }
        let original = func.block(entry).insts.clone();

        let err = fixup_aarch64_call_arg_source_clobbers(&mut func).unwrap_err();
        assert!(matches!(err, PipelineError::Aarch64CallArgRepair(_)));
        assert!(err.to_string().contains("no Gpr64 scratch register"));
        assert_eq!(func.block(entry).insts, original);
    }

