    #[test]
    fn aarch64_call_arg_access_model_includes_implicit_defs_and_uses() {
        static IMPLICIT_DEFS: [PReg; 1] = [X3];
        static IMPLICIT_USES: [PReg; 1] = [X4];
        let inst = IrMachInst::new(
            IrOpcode::AddRR,
            vec![
                IrOperand::PReg(X0),
                IrOperand::PReg(X1),
                IrOperand::PReg(X2),
            ],
        )
        .with_implicit_defs(&IMPLICIT_DEFS)
        .with_implicit_uses(&IMPLICIT_USES);

        let defs = aarch64_inst_def_pregs(&inst);
        let uses = aarch64_inst_use_pregs(&inst);
        assert!(defs.contains(&X0), "explicit destination must be modeled");
        assert!(defs.contains(&X3), "implicit definition must be modeled");
        assert!(uses.contains(&X1) && uses.contains(&X2));
        assert!(uses.contains(&X4), "implicit use must be modeled");
    }

