    #[test]
    fn aarch64_tco_tail_call_keeps_exact_args_and_regalloc_call_boundary() {
        use trust_cg_opt::pass_manager::MachinePass;
        use trust_cg_opt::tail_call::TailCallOptimization;

        static CALL_ARGS: [PReg; 3] = [X0, X1, D0];
        static CALL_DEFS: [PReg; 1] = [X8];
        let mut func =
            IrMachFunction::new("tail_caller".to_string(), IrSignature::new(vec![], vec![]));
        let entry = func.entry;
        let call = func.push_inst(
            IrMachInst::new(
                IrOpcode::Bl,
                vec![IrOperand::Symbol("tail_callee".to_string())],
            )
            .with_implicit_uses(&CALL_ARGS)
            .with_implicit_defs(&CALL_DEFS),
        );
        let ret = func.push_inst(IrMachInst::new(IrOpcode::Ret, vec![]));
        func.append_inst(entry, call);
        func.append_inst(entry, ret);

        let mut tco = TailCallOptimization;
        assert!(tco.run(&mut func));
        let tail = func.inst(func.block(entry).insts[0]);
        assert_eq!(tail.opcode, IrOpcode::TailCall);
        assert_eq!(tail.implicit_uses, &CALL_ARGS);
        assert_eq!(tail.implicit_defs, &CALL_DEFS);

        let ra = ir_to_regalloc(&func).unwrap();
        let ra_tail = &ra.insts[0];
        assert_eq!(ra_tail.opcode, IrOpcode::TailCall as u16);
        assert_eq!(ra_tail.implicit_uses, CALL_ARGS);
        assert!(ra_tail.flags.is_call());
        assert!(ra_tail.flags.is_branch());
        assert!(ra_tail.flags.is_terminator());
        assert!(ra_tail.implicit_defs.contains(&X8));
        assert!(
            ra_tail.implicit_defs.contains(&X0),
            "tail-call must receive ordinary caller-saved clobbers"
        );
    }

    #[test]
    fn aarch64_tail_call_repair_and_final_encode_fail_closed_on_mutation() {
        static CALL_ARGS: [PReg; 2] = [X0, X1];
        let mut func = IrMachFunction::new(
            "tail_repair_mutation".to_string(),
            IrSignature::new(vec![], vec![]),
        );
        let entry = func.entry;
        let setup_x0 = func.push_inst(call_arg_setup(IrMachInst::new(
            IrOpcode::Copy,
            vec![IrOperand::PReg(X0), IrOperand::PReg(X1)],
        )));
        let setup_x1 = func.push_inst(call_arg_setup(IrMachInst::new(
            IrOpcode::Copy,
            vec![IrOperand::PReg(X1), IrOperand::PReg(X0)],
        )));
        let tail = func.push_inst(
            IrMachInst::new(
                IrOpcode::TailCall,
                vec![IrOperand::Symbol("tail_callee".to_string())],
            )
            .with_implicit_uses(&CALL_ARGS),
        );
        for inst_id in [setup_x0, setup_x1, tail] {
            func.append_inst(entry, inst_id);
        }

        fixup_aarch64_call_arg_source_clobbers(&mut func).unwrap();
        lower_copies(&mut func).unwrap();
        encode_function(&func).expect("repaired tail-call sequence must encode");

        let mut clobbered_source = func.clone();
        clobbered_source.inst_mut(setup_x1).operands[1] = IrOperand::PReg(X0);
        let err = encode_function(&clobbered_source)
            .expect_err("tail-call arg mutation after repair must fail closed");
        assert!(matches!(err, PipelineError::Aarch64CallArgRepair(_)));
        assert!(err.to_string().contains("final stream no longer preserves"));

        let mut downgraded_to_branch = func.clone();
        downgraded_to_branch.inst_mut(tail).opcode = IrOpcode::B;
        let err = encode_function(&downgraded_to_branch)
            .expect_err("tail-call carrier downgraded to ordinary B must fail closed");
        assert!(matches!(
            err,
            PipelineError::MalformedAarch64Function { .. }
        ));
    }

    #[test]
    fn aarch64_final_encode_rejects_call_arg_hazard_mutated_after_repair() {
        static CALL_ARGS: [PReg; 2] = [X0, X1];
        let mut func = IrMachFunction::new(
            "post_repair_call_arg_mutation".to_string(),
            IrSignature::new(vec![], vec![]),
        );
        let entry = func.entry;
        let setup_x0 = func.push_inst(call_arg_setup(IrMachInst::new(
            IrOpcode::Copy,
            vec![IrOperand::PReg(X0), IrOperand::PReg(X1)],
        )));
        let setup_x1 = func.push_inst(call_arg_setup(IrMachInst::new(
            IrOpcode::Copy,
            vec![IrOperand::PReg(X1), IrOperand::PReg(X0)],
        )));
        let call = func.push_inst(
            IrMachInst::new(IrOpcode::Blr, vec![IrOperand::PReg(X21)])
                .with_implicit_uses(&CALL_ARGS),
        );
        let ret = func.push_inst(IrMachInst::new(IrOpcode::Ret, vec![IrOperand::PReg(X30)]));
        for inst_id in [setup_x0, setup_x1, call, ret] {
            func.append_inst(entry, inst_id);
        }

        fixup_aarch64_call_arg_source_clobbers(&mut func).unwrap();
        lower_copies(&mut func).unwrap();
        verify_aarch64_final_call_argument_sequence(
            &func.name,
            func.block(entry)
                .insts
                .iter()
                .map(|&inst_id| func.inst(inst_id)),
        )
        .expect("the repaired final physical stream must verify");

        // Simulate any post-repair rewrite corrupting the repaired X1 <- X9
        // source back to the already-clobbered X0. This mutation occurs after
        // pseudos have become final MOVs; the encoding boundary must catch it.
        func.inst_mut(setup_x1).operands[1] = IrOperand::PReg(X0);

        let err = encode_function(&func)
            .expect_err("final encoding must reject a post-repair argument hazard");
        assert!(matches!(err, PipelineError::Aarch64CallArgRepair(_)));
        assert!(err.to_string().contains("final stream no longer preserves"));
    }

