    #[test]
    fn aarch64_cfg_derivation_includes_eh_landing_pad_edges() {
        let mut func = IrMachFunction::new(
            "invoke_cfg_edges".to_string(),
            IrSignature::new(vec![], vec![]),
        );
        let normal = func.create_block();
        let unwind = func.create_block();
        let call = func.push_inst(IrMachInst::new(
            IrOpcode::Bl,
            vec![IrOperand::Symbol("may_unwind".into())],
        ));
        func.append_inst(func.entry, call);
        for block in [normal, unwind] {
            let ret = func.push_inst(IrMachInst::new(IrOpcode::Ret, vec![]));
            func.append_inst(block, ret);
        }
        func.add_edge(func.entry, normal);
        func.add_edge(func.entry, unwind);
        func.eh_metadata.personality = Some("rust_eh_personality".to_string());
        func.eh_metadata
            .add_call_site(trust_cg_ir::function::EhCallSiteEntry {
                call_block: func.entry,
                start_offset: 0,
                length: 0,
                landing_pad_block: Some(unwind),
            });

        validate_aarch64_mach_function(&func)
            .expect("Invoke unwind transfer must participate in exact CFG authority");
    }

    #[test]
    fn aarch64_resolved_cfg_reconstruction_recovers_blocks_and_ignores_guard_skips() {
        let mut func = IrMachFunction::new(
            "resolved_cfg_reconstruction".to_string(),
            IrSignature::new(vec![], vec![]),
        );
        let target = func.create_block();
        let branch = func.push_inst(IrMachInst::new(IrOpcode::B, vec![IrOperand::Imm(1)]));
        func.append_inst(func.entry, branch);
        let ret = func.push_inst(IrMachInst::new(IrOpcode::Ret, vec![]));
        func.append_inst(target, ret);

        assert!(
            func.block(func.entry).succs.is_empty(),
            "fixture must begin with missing/stale resolved CFG metadata"
        );
        let reconstructed = reconstruct_aarch64_resolved_cfg(&func)
            .expect("resolved block-start target must reconstruct exactly");
        assert_eq!(reconstructed.block(func.entry).succs, vec![target]);
        enforce_aarch64_post_regalloc_resolved(&func)
            .expect("final post-RA gate must use reconstructed, not stale, CFG authority");

        let mut guard = IrMachFunction::new(
            "resolved_intra_block_guard".to_string(),
            IrSignature::new(vec![], vec![]),
        );
        for inst in [
            IrMachInst::new(
                IrOpcode::CmpRI,
                vec![IrOperand::PReg(X0), IrOperand::Imm(0)],
            ),
            IrMachInst::new(IrOpcode::BCond, vec![IrOperand::Imm(0), IrOperand::Imm(2)]),
            IrMachInst::new(IrOpcode::Brk, vec![]),
            IrMachInst::new(IrOpcode::Ret, vec![]),
        ] {
            let id = guard.push_inst(inst);
            guard.append_inst(guard.entry, id);
        }
        let guard_view = reconstruct_aarch64_resolved_cfg(&guard)
            .expect("validated +2/BRK guard skip is intra-block control flow");
        assert!(guard_view.block(guard.entry).succs.is_empty());
        enforce_aarch64_post_regalloc_resolved(&guard)
            .expect("validated intra-block guard must pass the final authority gate");
    }

