    #[test]
    fn bind_dead_unallocated_defs_preserves_fp_and_simd_reads_in_reserved_scratch() {
        for (class, expected) in [
            (RegClass::Fpr16, H16),
            (RegClass::Fpr32, S16),
            (RegClass::Fpr64, D16),
            (RegClass::Fpr128, V16),
        ] {
            let sig = IrSignature::new(vec![], vec![]);
            let mut func = IrMachFunction::new(format!("dead_{class:?}_load"), sig);
            let dead = VReg::new(0, class);
            let inst_id = func.push_inst(IrMachInst::new(
                IrOpcode::VolatileLdrRI,
                vec![
                    IrOperand::VReg(dead),
                    IrOperand::PReg(X0),
                    IrOperand::Imm(0),
                ],
            ));
            func.append_inst(func.entry, inst_id);

            eliminate_dead_unallocated_defs(&mut func);
            bind_dead_unallocated_defs_to_discard_registers(&mut func).unwrap();

            let load = func.inst(inst_id);
            assert_eq!(load.opcode, IrOpcode::VolatileLdrRI);
            assert_eq!(load.operands[0], IrOperand::PReg(expected));
            assert!(load.flags.contains(InstFlags::READS_MEMORY));
            assert!(load.flags.contains(InstFlags::HAS_SIDE_EFFECTS));
            ensure_no_unresolved_vregs(&func, "test phase").unwrap();
        }
    }

    #[test]
    fn unused_volatile_fp_and_v128_loads_survive_aarch64_prepare_pipeline() {
        use trust_cg_lower::Type;
        use trust_cg_lower::function::{BasicBlock, Function as LowerFunction, Signature};
        use trust_cg_lower::instructions::{Block, Instruction, Opcode, Value};

        let entry = Block(0);
        let mut func = LowerFunction::new(
            "dead_volatile_fp_loads",
            Signature {
                params: vec![Type::I64],
                returns: vec![],
            },
        );
        func.entry_block = entry;
        func.block_order = vec![entry];
        func.blocks.insert(
            entry,
            BasicBlock {
                params: vec![],
                instructions: vec![
                    Instruction {
                        opcode: Opcode::VolatileLoad {
                            ty: Type::F32,
                            align: Some(4),
                        },
                        args: vec![Value(0)],
                        results: vec![Value(1)],
                    },
                    Instruction {
                        opcode: Opcode::VolatileLoad {
                            ty: Type::F64,
                            align: Some(8),
                        },
                        args: vec![Value(0)],
                        results: vec![Value(2)],
                    },
                    Instruction {
                        opcode: Opcode::VolatileLoad {
                            ty: Type::V128,
                            align: Some(16),
                        },
                        args: vec![Value(0)],
                        results: vec![Value(3)],
                    },
                    Instruction {
                        opcode: Opcode::Return,
                        args: vec![],
                        results: vec![],
                    },
                ],
                source_locs: vec![],
            },
        );

        let pipeline = Pipeline::new(PipelineConfig {
            opt_level: OptLevel::O0,
            verify: false,
            ..PipelineConfig::default()
        });
        let (prepared, _) = pipeline
            .prepare_function_with_metrics(&func, None)
            .expect("dead volatile FP/SIMD results must remain encodable");
        let destination_classes: Vec<_> = prepared
            .insts
            .iter()
            .filter(|inst| inst.opcode == IrOpcode::VolatileLdrRI)
            .map(|inst| match inst.operands.first() {
                Some(IrOperand::PReg(reg)) => preg_class(*reg),
                other => panic!("volatile load destination must be allocated: {other:?}"),
            })
            .collect();
        assert_eq!(
            destination_classes,
            vec![RegClass::Fpr32, RegClass::Fpr64, RegClass::Fpr128]
        );
    }

    #[test]
    fn atomic_lse_def_use_bind_dead_unallocated_ldpri_defs_to_discard_registers() {
        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("test".to_string(), sig);

        let v0 = VReg::new(0, RegClass::Gpr64);
        let v1 = VReg::new(1, RegClass::Gpr64);
        let inst_id = func.push_inst(IrMachInst::new(
            IrOpcode::LdpRI,
            vec![
                IrOperand::VReg(v0),
                IrOperand::VReg(v1),
                IrOperand::PReg(X2),
                IrOperand::Imm(0),
            ],
        ));
        func.append_inst(func.entry, inst_id);

        eliminate_dead_unallocated_defs(&mut func);
        bind_dead_unallocated_defs_to_discard_registers(&mut func).unwrap();

        let inst = func.inst(inst_id);
        assert_eq!(inst.opcode, IrOpcode::LdpRI);
        assert!(inst.flags.contains(InstFlags::READS_MEMORY));
        assert_eq!(
            inst.operands,
            vec![
                IrOperand::PReg(XZR),
                IrOperand::PReg(XZR),
                IrOperand::PReg(X2),
                IrOperand::Imm(0),
            ]
        );
        ensure_no_unresolved_vregs(&func, "test phase").unwrap();
    }

    #[test]
    fn bind_dead_unallocated_defs_keeps_live_unallocated_memory_read_def() {
        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("test".to_string(), sig);

        let v0 = VReg::new(0, RegClass::Gpr64);
        let load_id = func.push_inst(IrMachInst::new(
            IrOpcode::LdrRI,
            vec![IrOperand::VReg(v0), IrOperand::PReg(X0), IrOperand::Imm(0)],
        ));
        func.append_inst(func.entry, load_id);
        let add_id = func.push_inst(IrMachInst::new(
            IrOpcode::AddRR,
            vec![
                IrOperand::PReg(X1),
                IrOperand::VReg(v0),
                IrOperand::PReg(X2),
            ],
        ));
        func.append_inst(func.entry, add_id);

        bind_dead_unallocated_defs_to_discard_registers(&mut func).unwrap();

        assert_eq!(func.insts[0].operands[0], IrOperand::VReg(v0));
    }

    #[test]
    fn bind_dead_unallocated_defs_counts_same_id_other_class_separately() {
        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("test".to_string(), sig);

        let gpr_v0 = VReg::new(0, RegClass::Gpr64);
        let fpr_v0 = VReg::new(0, RegClass::Fpr64);
        let load_id = func.push_inst(IrMachInst::new(
            IrOpcode::LdrRI,
            vec![
                IrOperand::VReg(gpr_v0),
                IrOperand::PReg(X0),
                IrOperand::Imm(0),
            ],
        ));
        func.append_inst(func.entry, load_id);
        let fpr_use_id = func.push_inst(IrMachInst::new(
            IrOpcode::MovR,
            vec![IrOperand::PReg(D16), IrOperand::VReg(fpr_v0)],
        ));
        func.append_inst(func.entry, fpr_use_id);

        bind_dead_unallocated_defs_to_discard_registers(&mut func).unwrap();

        assert_eq!(func.insts[0].operands[0], IrOperand::PReg(XZR));
        assert_eq!(func.inst(fpr_use_id).operands[1], IrOperand::VReg(fpr_v0));
    }

