    #[test]
    fn rebuild_ir_cfg_edges_uses_actual_branch_operands_before_regalloc() {
        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("stale_cfg_edges".to_string(), sig);
        let entry = func.entry;
        let fallthrough = func.create_block();
        let cold = func.create_block();

        let branch = func.push_inst(IrMachInst::new(
            IrOpcode::BCond,
            vec![IrOperand::Imm(1), IrOperand::Block(cold)],
        ));
        func.append_inst(entry, branch);
        let fallthrough_ret = func.push_inst(IrMachInst::new(IrOpcode::Ret, vec![]));
        func.append_inst(fallthrough, fallthrough_ret);
        let cold_ret = func.push_inst(IrMachInst::new(IrOpcode::Ret, vec![]));
        func.append_inst(cold, cold_ret);

        func.block_mut(entry).succs.push(cold);
        func.block_mut(cold).preds.push(entry);

        rebuild_ir_cfg_edges_from_branch_operands(&mut func);

        assert_eq!(func.block(entry).succs, vec![cold, fallthrough]);
        assert_eq!(func.block(fallthrough).preds, vec![entry]);
        assert_eq!(func.block(cold).preds, vec![entry]);

        let ra_func = ir_to_regalloc(&func).unwrap();
        assert_eq!(
            ra_func.blocks[entry.0 as usize].succs,
            vec![cold, fallthrough]
        );
    }

    #[test]
    fn verifier_rejects_formal_copy_dest_aliasing_later_unread_abi_source() {
        let sig = IrSignature::new(vec![Type::I64, Type::I64], vec![]);
        let mut func = IrMachFunction::new("formal_copy_hazard".to_string(), sig);
        let entry = func.entry;

        let first = func.push_inst(IrMachInst::new(
            IrOpcode::Copy,
            vec![IrOperand::PReg(X1), IrOperand::PReg(X0)],
        ));
        let second = func.push_inst(IrMachInst::new(
            IrOpcode::Copy,
            vec![IrOperand::PReg(X0), IrOperand::PReg(X1)],
        ));
        func.append_inst(entry, first);
        func.append_inst(entry, second);

        let err = verify_aarch64_formal_entry_copy_hazards(&func).unwrap_err();
        assert!(
            matches!(err, PipelineError::Aarch64FormalArgCopyHazard(_)),
            "unexpected verifier error: {err}"
        );
        assert!(
            err.to_string()
                .contains("dst=x1 aliases unread ABI source x1"),
            "diagnostic should identify the clobbered unread formal source: {err}"
        );
    }

    #[test]
    fn verifier_allows_formal_copy_that_reads_its_own_abi_source_alias() {
        let sig = IrSignature::new(
            vec![Type::I64, Type::I64, Type::I64, Type::I32, Type::I64],
            vec![],
        );
        let mut func = IrMachFunction::new("formal_copy_same_source_alias".to_string(), sig);
        let entry = func.entry;

        for (dst, src) in [(X0, X0), (X1, X1), (X2, X2)] {
            let inst = func.push_inst(IrMachInst::new(
                IrOpcode::Copy,
                vec![IrOperand::PReg(dst), IrOperand::PReg(src)],
            ));
            func.append_inst(entry, inst);
        }
        let i32_formal = func.push_inst(IrMachInst::new(
            IrOpcode::Copy,
            vec![IrOperand::PReg(W3), IrOperand::PReg(X3)],
        ));
        let later = func.push_inst(IrMachInst::new(
            IrOpcode::Copy,
            vec![IrOperand::PReg(W4), IrOperand::PReg(X4)],
        ));
        func.append_inst(entry, i32_formal);
        func.append_inst(entry, later);

        verify_aarch64_formal_entry_copy_hazards(&func).unwrap();
    }

    #[test]
    fn ir_to_regalloc_adds_aarch64_call_clobbers() {
        static EXISTING_DEFS: [PReg; 2] = [PReg::new(0), PReg::new(19)];

        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("test".to_string(), sig);
        let entry = func.entry;
        let call = IrMachInst::new(
            IrOpcode::Bl,
            vec![IrOperand::Symbol("_external_action".to_string())],
        )
        .with_implicit_defs(&EXISTING_DEFS);
        let call_id = func.push_inst(call);
        func.append_inst(entry, call_id);

        let ra_func = ir_to_regalloc(&func).unwrap();
        let implicit_defs = &ra_func.insts[0].implicit_defs;

        assert!(implicit_defs.contains(&PReg::new(0))); // X0
        assert!(implicit_defs.contains(&PReg::new(15))); // X15
        assert!(implicit_defs.contains(&PReg::new(32))); // W0
        assert!(implicit_defs.contains(&PReg::new(64))); // V0
        assert!(implicit_defs.contains(&PReg::new(80))); // V16
        assert!(implicit_defs.contains(&PReg::new(112))); // D16
        assert!(implicit_defs.contains(&PReg::new(144))); // S16
        assert!(implicit_defs.contains(&PReg::new(19))); // Existing non-clobber preserved.
        assert_eq!(
            implicit_defs
                .iter()
                .filter(|&&preg| preg == PReg::new(0))
                .count(),
            1,
            "existing implicit defs should not be duplicated"
        );
    }

    #[test]
    fn ir_to_regalloc_blr_adds_call_clobbers_and_preserves_arg_live_ins() {
        static ARG_LIVE_INS: [PReg; 8] = [
            PReg::new(0),
            PReg::new(1),
            PReg::new(2),
            PReg::new(3),
            PReg::new(4),
            PReg::new(5),
            PReg::new(6),
            PReg::new(7),
        ];

        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("indirect_call".to_string(), sig);
        let entry = func.entry;
        let call = IrMachInst::new(IrOpcode::Blr, vec![IrOperand::PReg(X16)])
            .with_implicit_uses(&ARG_LIVE_INS);
        let call_id = func.push_inst(call);
        func.append_inst(entry, call_id);

        let ra_func = ir_to_regalloc(&func).unwrap();
        let ra_call = &ra_func.insts[0];

        assert!(ra_call.flags.is_call(), "BLR must remain a call");
        assert!(
            ra_call.defs.is_empty(),
            "BLR must not treat its target as a def"
        );
        assert_eq!(ra_call.uses.len(), 1);
        assert_eq!(ra_call.uses[0].as_preg(), Some(X16));

        for preg in ARG_LIVE_INS {
            assert!(
                ra_call.implicit_uses.contains(&preg),
                "argument register {preg:?} must be live into BLR"
            );
        }

        assert!(ra_call.implicit_defs.contains(&PReg::new(0))); // X0
        assert!(ra_call.implicit_defs.contains(&PReg::new(7))); // X7
        assert!(ra_call.implicit_defs.contains(&PReg::new(15))); // X15
        assert!(ra_call.implicit_defs.contains(&PReg::new(16))); // X16/IP0
        assert!(ra_call.implicit_defs.contains(&PReg::new(17))); // X17/IP1
        assert!(ra_call.implicit_defs.contains(&PReg::new(18))); // X18 platform register
        assert!(ra_call.implicit_defs.contains(&PReg::new(30))); // X30/LR
        assert!(ra_call.implicit_defs.contains(&PReg::new(48))); // W16
        assert!(ra_call.implicit_defs.contains(&PReg::new(49))); // W17
        assert!(ra_call.implicit_defs.contains(&PReg::new(50))); // W18
        assert!(ra_call.implicit_defs.contains(&PReg::new(62))); // W30
        assert!(ra_call.implicit_defs.contains(&PReg::new(64))); // V0
        assert!(ra_call.implicit_defs.contains(&PReg::new(80))); // V16
    }

    #[test]
    fn rebuild_ir_preserves_frontend_copy_before_lowering_return_copy() {
        use trust_cg_regalloc::machine_types::{
            RegAllocBlock, RegAllocFunction, RegAllocInst, RegAllocOperand as RaOp,
        };

        let sig = IrSignature::new(vec![], vec![]);
        let mut ir_func = IrMachFunction::new("return_copy".to_string(), sig);
        let entry = ir_func.entry;
        let v0 = VReg::new(0, RegClass::Gpr64);

        for inst in [
            IrMachInst::new(
                IrOpcode::Movz,
                vec![IrOperand::VReg(v0), IrOperand::Imm(42)],
            ),
            IrMachInst::new(
                IrOpcode::Copy,
                vec![IrOperand::PReg(X0), IrOperand::VReg(v0)],
            ),
            IrMachInst::new(IrOpcode::Ret, vec![IrOperand::PReg(X30)]),
        ] {
            let id = ir_func.push_inst(inst);
            ir_func.append_inst(entry, id);
        }

        let ra_func = RegAllocFunction {
            name: "return_copy".to_string(),
            insts: vec![
                RegAllocInst {
                    opcode: IrOpcode::Movz as u16,
                    defs: vec![RaOp::VReg(v0)],
                    uses: vec![RaOp::Imm(42)],
                    implicit_defs: Vec::new(),
                    implicit_uses: Vec::new(),
                    tied_operands: Vec::new(),
                    flags: IrOpcode::Movz.default_flags(),
                },
                RegAllocInst {
                    opcode: IrOpcode::Copy as u16,
                    defs: vec![RaOp::PReg(X0)],
                    uses: vec![RaOp::VReg(v0)],
                    implicit_defs: Vec::new(),
                    implicit_uses: Vec::new(),
                    tied_operands: Vec::new(),
                    flags: IrOpcode::Copy.default_flags(),
                },
                RegAllocInst {
                    opcode: IrOpcode::Ret as u16,
                    defs: Vec::new(),
                    uses: vec![RaOp::PReg(X30)],
                    implicit_defs: Vec::new(),
                    implicit_uses: vec![X0],
                    tied_operands: Vec::new(),
                    flags: IrOpcode::Ret.default_flags(),
                },
            ],
            blocks: vec![RegAllocBlock {
                insts: vec![InstId(0), InstId(1), InstId(2)],
                preds: Vec::new(),
                succs: Vec::new(),
                loop_depth: 0,
            }],
            block_order: vec![BlockId(0)],
            entry_block: BlockId(0),
            next_vreg: 1,
            next_stack_slot: 0,
            stack_slots: BTreeMap::new(),
        };

        rebuild_ir_from_regalloc(&mut ir_func, &ra_func).unwrap();
        let copy_id = ir_func.block(ir_func.entry).insts[1];
        assert_eq!(ir_func.inst(copy_id).opcode, IrOpcode::Copy);

        let mut allocation = BTreeMap::new();
        allocation.insert(v0, X28);
        apply_regalloc(&mut ir_func, &allocation);
        lower_copies(&mut ir_func).unwrap();

        let lowered_copy = ir_func.inst(copy_id);
        assert_eq!(lowered_copy.opcode, IrOpcode::MOVXrr);
        assert_eq!(
            lowered_copy.operands,
            vec![IrOperand::PReg(X0), IrOperand::PReg(X28)]
        );
        assert!(!lowered_copy.flags.contains(InstFlags::IS_PSEUDO));
    }

