    // =========================================================================
    // DispatchVerifyMode::Sampled — deterministic sampled verification
    // =========================================================================

    fn sampled(modulus: u32) -> DispatchVerifyMode {
        DispatchVerifyMode::Sampled {
            modulus: std::num::NonZeroU32::new(modulus).expect("nonzero modulus"),
        }
    }

    #[test]
    fn sampled_mode_selects_deterministic_subset() {
        let names = [
            "add",
            "sub",
            "mul",
            "Next_0",
            "Next_1",
            "Next_2",
            "Next_3",
            "Next_4",
            "Invariant_0",
            "Liveness_0",
        ];

        // modulus = 1 selects everything.
        for name in names {
            assert!(sampled(1).samples_function(name), "{name} at modulus 1");
        }

        // modulus = 3: selection is exactly hash % 3 == 0, stable across calls.
        let selected: Vec<&str> = names
            .iter()
            .copied()
            .filter(|name| sampled(3).samples_function(name))
            .collect();
        for name in names {
            assert_eq!(
                sampled(3).samples_function(name),
                sampled_verify_hash(name).is_multiple_of(3),
                "{name} selection must equal the documented hash rule"
            );
            assert_eq!(
                sampled(3).samples_function(name),
                sampled(3).samples_function(name),
                "{name} selection must be deterministic"
            );
        }
        // The sample is neither empty nor total for this corpus — the test
        // would be vacuous otherwise.
        assert!(!selected.is_empty(), "modulus 3 must select something");
        assert!(
            selected.len() < names.len(),
            "modulus 3 must not select everything"
        );

        // Non-sampled modes never select functions.
        for mode in [
            DispatchVerifyMode::Off,
            DispatchVerifyMode::FallbackOnFailure,
            DispatchVerifyMode::ErrorOnFailure,
        ] {
            for name in names {
                assert!(!mode.samples_function(name), "{mode:?} must not sample");
            }
        }
    }

    #[test]
    fn sampled_hash_is_pinned_fnv1a() {
        // Pin the exact FNV-1a/64 constants: a silent hash change would
        // silently reshuffle which production functions get verified.
        assert_eq!(sampled_verify_hash(""), 0xcbf2_9ce4_8422_2325);
        // FNV-1a of "a": (basis ^ 0x61) * prime.
        assert_eq!(
            sampled_verify_hash("a"),
            (0xcbf2_9ce4_8422_2325u64 ^ 0x61).wrapping_mul(0x0000_0100_0000_01b3)
        );
    }

    #[cfg(feature = "verify")]
    #[test]
    fn sampled_mode_gates_function_verification() {
        // The pipeline's phase-3.5 gate: Off skips, Sampled{1} selects every
        // function, and an unselected name under a larger modulus skips.
        let func = build_add_test_function();

        let off = Pipeline::new(PipelineConfig::default());
        assert!(!off.function_verification_selected(&func.name));

        let always = Pipeline::new(PipelineConfig {
            verify_dispatch: sampled(1),
            ..Default::default()
        });
        assert!(always.function_verification_selected(&func.name));
        // And the selected function actually verifies clean end-to-end.
        always
            .run_verification(&func)
            .expect("sampled add function verifies");

        // Find a modulus that deselects "add" (exists: hash is fixed).
        let deselecting = (2..64)
            .find(|m| !sampled_verify_hash(&func.name).is_multiple_of(*m))
            .expect("some modulus below 64 deselects the add function");
        let sometimes = Pipeline::new(PipelineConfig {
            verify_dispatch: sampled(deselecting as u32),
            ..Default::default()
        });
        assert!(!sometimes.function_verification_selected(&func.name));
        sometimes
            .run_verification(&func)
            .expect("deselected function skips verification");
    }

    /// A deliberately corrupted lowering inside the sample IS caught.
    ///
    /// Layered harness (no existing verify-mode test builds a refuting
    /// function, because `verify_function` on well-formed input cannot
    /// refute — the refutation content lives in trust-cg-verify):
    ///  1. the corrupted lowering (isel emitted SUB where the source op was
    ///     Iadd) refutes at the obligation layer, with the same public
    ///     encoders `reconstruct_alu_obligation` uses internally;
    ///  2. the refuted report drives the EXACT enforcement path
    ///     `run_verification` applies to a sampled function, and the compile
    ///     is rejected with `PipelineError::VerificationFailed`.
    #[cfg(feature = "verify")]
    #[test]
    fn sampled_corrupted_lowering_is_caught() {
        use trust_cg_verify::lowering_proof::MachineSideProvenance;
        use trust_cg_verify::smt::SmtExpr;
        use trust_cg_verify::verify::VerificationResult;
        use trust_cg_verify::{ProofObligation, verify_by_evaluation};

        // (1) The corrupted lowering refutes: source Iadd vs emitted SubRR.
        let a = SmtExpr::var("recon_src1", 32);
        let b = SmtExpr::var("recon_src2", 32);
        let corrupted = ProofObligation {
            name: "RECONSTRUCTED Iadd -> SubRR (INJECTED corrupted lowering)".to_string(),
            trust_ir_expr: trust_cg_verify::trust_ir_semantics::encode_trust_ir_binop(
                &trust_cg_lower::instructions::Opcode::Iadd,
                LowerType::I32,
                a.clone(),
                b.clone(),
            ),
            aarch64_expr: trust_cg_verify::aarch64_semantics::encode_sub_rr(
                trust_cg_ir::cc::OperandSize::S32,
                a,
                b,
            ),
            inputs: vec![
                ("recon_src1".to_string(), 32),
                ("recon_src2".to_string(), 32),
            ],
            preconditions: vec![],
            fp_inputs: vec![],
            category: None,
            machine_side_provenance: MachineSideProvenance::Reconstructed {
                from_opcode: "SubRR".to_string(),
                arity: 2,
            },
        };
        let VerificationResult::Invalid { counterexample } = verify_by_evaluation(&corrupted)
        else {
            panic!("SUB-for-Iadd must refute");
        };

        // (2) The refuted report fails the sampled compile, fail closed.
        let corrupted_fn_name = "add"; // in the modulus-1 sample by definition
        assert!(sampled(1).samples_function(corrupted_fn_name));
        let report = trust_cg_verify::FunctionVerificationReport {
            function_name: corrupted_fn_name.to_string(),
            instructions: vec![trust_cg_verify::InstructionReport {
                inst_index: 0,
                opcode: trust_cg_verify::InstructionOpcode::AArch64(IrOpcode::SubRR),
                result: trust_cg_verify::InstructionVerificationResult::Failed {
                    proof_name: corrupted.name.clone(),
                    detail: counterexample,
                },
            }],
        };
        match Pipeline::enforce_verification_report(report) {
            Err(PipelineError::VerificationFailed {
                function, failures, ..
            }) => {
                assert_eq!(function, corrupted_fn_name);
                assert_eq!(failures, 1);
            }
            other => panic!("corrupted lowering must fail the compile, got {other:?}"),
        }
    }

    /// Compile-time overhead probe for [`DispatchVerifyMode::Sampled`].
    ///
    /// It is explicitly qualified because it is a measurement, not an
    /// assertion. Run `TRUST_CG_RUN_MEASUREMENT_TESTS=1 cargo test --release
    /// -p trust-cg-codegen --lib sampled_verify_overhead_probe -- --nocapture`
    /// to reproduce the budget numbers documented on the `Sampled` variant.
    #[cfg(feature = "verify")]
    #[test]
    fn sampled_verify_overhead_probe() {
        if !matches!(
            std::env::var("TRUST_CG_RUN_MEASUREMENT_TESTS").as_deref(),
            Ok("1")
        ) {
            eprintln!(
                "measurement campaign not requested; \
                 set TRUST_CG_RUN_MEASUREMENT_TESTS=1 to run"
            );
            return;
        }

        fn build_batch() -> Vec<IrMachFunction> {
            use trust_cg_ir::function::Type;
            use trust_cg_ir::regs::{X0, X1, X2};
            (0..64)
                .map(|i| {
                    let sig = IrSignature::new(vec![Type::I64, Type::I64], vec![Type::I64]);
                    let mut func = IrMachFunction::new(format!("probe_fn_{i}"), sig);
                    let entry = func.entry;
                    for _ in 0..8 {
                        for opcode in [IrOpcode::AddRR, IrOpcode::SubRR, IrOpcode::MulRR] {
                            let inst = IrMachInst::new(
                                opcode,
                                vec![
                                    IrOperand::PReg(X2),
                                    IrOperand::PReg(X0),
                                    IrOperand::PReg(X1),
                                ],
                            );
                            let id = func.push_inst(inst);
                            func.append_inst(entry, id);
                        }
                    }
                    let ret = func.push_inst(IrMachInst::new(IrOpcode::Ret, vec![]));
                    func.append_inst(entry, ret);
                    func
                })
                .collect()
        }

        let run = |mode: DispatchVerifyMode| -> Duration {
            let pipeline = Pipeline::new(PipelineConfig {
                opt_level: OptLevel::O2,
                verify_dispatch: mode,
                ..Default::default()
            });
            let mut batch = build_batch();
            let start = Instant::now();
            for func in &mut batch {
                pipeline
                    .compile_ir_function(func)
                    .expect("probe function compiles");
            }
            start.elapsed()
        };

        // Warm the proof database / verdict caches once so the probe measures
        // steady-state per-compile cost, then measure both modes.
        let _ = run(sampled(16));
        let off = run(DispatchVerifyMode::Off);
        let sampled_16 = run(sampled(16));
        let selected = (0..64)
            .filter(|i| sampled(16).samples_function(&format!("probe_fn_{i}")))
            .count();
        println!(
            "sampled-verify overhead probe: batch=64 fns x 25 insts, selected={selected}, \
             off={off:?}, sampled_n16={sampled_16:?}, overhead={:.1}%",
            (sampled_16.as_secs_f64() / off.as_secs_f64() - 1.0) * 100.0
        );
    }

