    fn build_stack_protected_ret_function(name: &str) -> IrMachFunction {
        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new(name.to_string(), sig);
        func.stack_protector = StackProtectorMode::StackGuard;
        let ret = func.push_inst(IrMachInst::new(IrOpcode::Ret, vec![]));
        func.append_inst(func.entry, ret);
        func
    }

    #[test]
    fn stack_protector_prepare_emits_guard_check_and_object_symbols() {
        let pipeline = Pipeline::new(PipelineConfig {
            opt_level: OptLevel::O0,
            target_triple: "aarch64-apple-darwin".to_string(),
            ..Default::default()
        });
        let mut func = build_stack_protected_ret_function("stack_canary_probe");

        pipeline
            .prepare_ir_function(&mut func)
            .expect("stack-protected function should prepare on Darwin arm64");

        assert_eq!(func.stack_protector_slot, Some(StackSlotId(0)));

        let opcodes: Vec<IrOpcode> = func
            .block_order
            .iter()
            .flat_map(|block| func.block(*block).insts.iter().copied())
            .map(|inst_id| func.inst(inst_id).opcode)
            .collect();

        assert!(
            opcodes.windows(4).any(|window| {
                window
                    == [
                        IrOpcode::Adrp,
                        IrOpcode::LdrGot,
                        IrOpcode::LdrRI,
                        IrOpcode::StrRI,
                    ]
            }),
            "prologue should load and save __stack_chk_guard: {opcodes:?}"
        );
        assert!(
            opcodes.windows(6).any(|window| {
                window
                    == [
                        IrOpcode::Adrp,
                        IrOpcode::LdrGot,
                        IrOpcode::LdrRI,
                        IrOpcode::LdrRI,
                        IrOpcode::CmpRR,
                        IrOpcode::BCond,
                    ]
            }),
            "epilogue should reload, compare, and branch on canary mismatch: {opcodes:?}"
        );
        assert!(
            opcodes.contains(&IrOpcode::Bl),
            "fail block should call __stack_chk_fail"
        );

        let obj = pipeline
            .compile_module(&[func])
            .expect("prepared stack-protected function should emit object");
        let parsed = crate::macho::linker::MachOParser::parse(&obj)
            .expect("stack-protected object should parse as Mach-O");
        let undefined: BTreeSet<_> = parsed
            .symbols
            .iter()
            .filter(|symbol| symbol.is_undefined())
            .map(|symbol| symbol.name.as_str())
            .collect();
        assert!(undefined.contains("___stack_chk_guard"));
        assert!(undefined.contains("___stack_chk_fail"));
        let text = parsed
            .sections
            .iter()
            .find(|section| section.name == "__text")
            .expect("object should contain __text");
        assert!(
            text.relocations.len() >= 5,
            "guard page/load and fail call should produce relocations, got {:?}",
            text.relocations
        );
        let relocation_kinds: Vec<_> = text
            .relocations
            .iter()
            .map(|relocation| relocation.kind)
            .collect();
        assert_eq!(
            relocation_kinds
                .iter()
                .filter(|kind| **kind == crate::macho::reloc::AArch64RelocKind::GotLoadPage21)
                .count(),
            2,
            "stack guard ADRP sites should use GOT page relocations: {relocation_kinds:?}"
        );
        assert_eq!(
            relocation_kinds
                .iter()
                .filter(|kind| {
                    **kind == crate::macho::reloc::AArch64RelocKind::GotLoadPageoff12
                })
                .count(),
            2,
            "stack guard LDR sites should use GOT pageoff relocations: {relocation_kinds:?}"
        );
        assert!(
            !relocation_kinds.contains(&crate::macho::reloc::AArch64RelocKind::Page21)
                && !relocation_kinds.contains(&crate::macho::reloc::AArch64RelocKind::Pageoff12),
            "stack guard should not use direct page relocations: {relocation_kinds:?}"
        );
    }

    #[test]
    fn stack_protector_rejects_explicit_unsupported_target() {
        let pipeline = Pipeline::new(PipelineConfig {
            opt_level: OptLevel::O0,
            target_triple: "x86_64-unknown-linux-gnu".to_string(),
            ..Default::default()
        });
        let mut func = build_stack_protected_ret_function("stack_canary_unsupported");

        let err = pipeline
            .prepare_ir_function(&mut func)
            .expect_err("unsupported target should fail closed");
        match err {
            PipelineError::TargetObjectUnsupported {
                target,
                format,
                reason,
            } => {
                assert_eq!(target, "x86_64-unknown-linux-gnu");
                assert_eq!(format, "Mach-O");
                assert!(reason.contains("stack canary lowering"));
            }
            other => panic!("expected TargetObjectUnsupported, got {other:?}"),
        }
    }

    fn build_high_pressure_copy_function() -> IrMachFunction {
        let sig = IrSignature::new(vec![], vec![Type::I64]);
        let mut func = IrMachFunction::new("high_pressure_copy".to_string(), sig);
        let entry = func.entry;

        let mut live = Vec::new();
        for i in 0..30u32 {
            let v = VReg::new(i, RegClass::Gpr64);
            let mov = IrMachInst::new(
                IrOpcode::MovI,
                vec![IrOperand::VReg(v), IrOperand::Imm((i + 1) as i64)],
            );
            let id = func.push_inst(mov);
            func.append_inst(entry, id);
            live.push(v);
        }

        let copied = VReg::new(30, RegClass::Gpr64);
        let copy = IrMachInst::new(
            IrOpcode::Copy,
            vec![IrOperand::VReg(copied), IrOperand::VReg(live[29])],
        );
        let copy_id = func.push_inst(copy);
        func.append_inst(entry, copy_id);

        let mut acc = VReg::new(31, RegClass::Gpr64);
        let seed = IrMachInst::new(
            IrOpcode::AddRR,
            vec![
                IrOperand::VReg(acc),
                IrOperand::VReg(live[0]),
                IrOperand::VReg(live[1]),
            ],
        );
        let seed_id = func.push_inst(seed);
        func.append_inst(entry, seed_id);

        for (idx, value) in live.iter().enumerate().skip(2).take(27) {
            let next = VReg::new(31 + idx as u32, RegClass::Gpr64);
            let add = IrMachInst::new(
                IrOpcode::AddRR,
                vec![
                    IrOperand::VReg(next),
                    IrOperand::VReg(acc),
                    IrOperand::VReg(*value),
                ],
            );
            let add_id = func.push_inst(add);
            func.append_inst(entry, add_id);
            acc = next;
        }

        let result = IrMachInst::new(
            IrOpcode::AddRR,
            vec![
                IrOperand::PReg(X0),
                IrOperand::VReg(acc),
                IrOperand::VReg(copied),
            ],
        );
        let result_id = func.push_inst(result);
        func.append_inst(entry, result_id);

        let ret = IrMachInst::new(IrOpcode::Ret, vec![]);
        let ret_id = func.push_inst(ret);
        func.append_inst(entry, ret_id);

        func
    }

    #[test]
    fn compile_ir_function_handles_copy_under_spill_pressure() {
        let mut func = build_high_pressure_copy_function();
        let pipeline = Pipeline::new(PipelineConfig {
            opt_level: OptLevel::O0,
            ..Default::default()
        });

        let result = pipeline.compile_ir_function(&mut func);
        assert!(
            result.is_ok(),
            "high-pressure copy function should compile through full pipeline: {:?}",
            result
        );
    }

